%-----------------------------------------------------------------------------%
% Harness
%-----------------------------------------------------------------------------%

:- type tally
    --->    tally(
                t_pass :: int,
                t_fail :: int
            ).

:- pred check(string::in, bool::in, tally::in, tally::out, io::di, io::uo)
    is det.

check(Name, Ok, !Tally, !IO) :-
    (
        Ok = yes,
        !Tally ^ t_pass := !.Tally ^ t_pass + 1
    ;
        Ok = no,
        !Tally ^ t_fail := !.Tally ^ t_fail + 1,
        io.format("  FAIL  %s\n", [s(Name)], !IO)
    ).

main(!IO) :-
    io.command_line_arguments(Args, !IO),
    % The probes live in the test binary, so they run against the library the
    % suite runs against.
    ( if Args = ["trace", Artefact, Scenario] then
        emit_trace(Artefact, Scenario, !IO)
    else if Args = ["record", Artefact, Scenario, Out] then
        emit_recording(Artefact, Scenario, Out, !IO)
    else if Args = ["read", Recording] then
        read_recording(Recording, !IO)
    else if Args = ["selfhash", Artefact] then
        probe_self_hash(Artefact, !IO)
    else if Args = ["contract", Artefact] then
        probe_contract(Artefact, !IO)
    else if Args = ["replay", Artefact, Recording] then
        replay_recording(Artefact, Recording, !IO)
    else if Args = ["atoms", Artefact] then
        list_atoms(Artefact, !IO)
    else if Args = ["wire", Container] then
        dump_wire(Container, !IO)
    else if Args = ["schemas", Artefact] then
        list_schemas(Artefact, !IO)
    else if Args = ["series", Artefact] then
        list_series(Artefact, !IO)
    else if Args = ["order", Artefact, Scenario] then
        order_scenario(Artefact, Scenario, !IO)
    else if Args = ["tms", Artefact, Scenario] then
        audit_scenario(Artefact, Scenario, !IO)
    else if Args = ["atom-table"] then
        print_atom_table(!IO)
    else if Args = ["capability-table"] then
        print_capability_table(!IO)
    else if Args = ["platform"] then
        print_platform(!IO)
    else if Args = ["schema-sources", Artefact] then
        print_schema_sources(Artefact, !IO)
    else if Args = [] then
        run_suite(!IO)
    else
        io.write_string(
            "usage: test_ds [trace <artefact.dsc> <scenario.scn>]\n" ++
            "               [record <artefact.dsc> <scenario.scn> <out.rfcs>]\n" ++
            "               [atoms <artefact.dsc>]\n" ++
            "               [wire <artefact.dsc | recording.rfcs>]\n" ++
            "               [schemas <artefact.dsc>]\n" ++
            "               [series <artefact.dsc>]\n" ++
            "               [tms <artefact.dsc> <scenario.scn>]\n" ++
            "               [atom-table]\n" ++
            "               [capability-table]\n" ++
            "               [platform]\n", !IO),
        io.set_exit_status(2, !IO)
    ).

%-----------------------------------------------------------------------------%
% `wire` -- every atom's top-level fields, through the real readers
%-----------------------------------------------------------------------------%
%
% The Mercury half of the runtime differential's wire check: libds dumps the same
% container through `pyds.atoms`, and the two texts must be identical. Framed
% with `ds.atom.next_frame` and walked with `ds.wire.next_field`, the
% predicates the loader and the stream reader use:
%
%     atom <offset> <field number>
%      <field> <wire type> <value>
%
% A varint as read, a fixed64 / fixed32 as its little-endian unsigned value, a
% length-delimited value as lowercase hex (`-` when empty). A container that
% ends cleanly prints `end`; one the framing refuses prints `error <offset>`,
% and a body the field walk refuses prints ` error` and goes on to the next
% atom.

:- pred dump_wire(string::in, io::di, io::uo) is det.

dump_wire(Path, !IO) :-
    io.open_binary_input(Path, OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, ReadRes, !IO),
        io.close_binary_input(Stream, !IO),
        (
            ReadRes = ok(BM),
            wire_frames(init_reader(BM), !IO)
        ;
            ReadRes = error(Err),
            io.format("READ FAILED %s\n", [s(io.error_message(Err))], !IO),
            io.set_exit_status(1, !IO)
        )
    ;
        OpenRes = error(Err2),
        io.format("OPEN FAILED %s\n", [s(io.error_message(Err2))], !IO),
        io.set_exit_status(1, !IO)
    ).

:- pred wire_frames(reader::in, io::di, io::uo) is det.

wire_frames(R0, !IO) :-
    next_frame(FR, R0, R1),
    (
        FR = fr_eof,
        io.write_string("end\n", !IO)
    ;
        FR = fr_error(_, Offset),
        io.format("error %d\n", [i(Offset)], !IO)
    ;
        FR = fr_ok(F),
        Atom = F ^ fr_atom,
        (
            Atom = known(A),
            Field = atom_field(A)
        ;
            Atom = unknown(Field)
        ),
        io.format("atom %d %d\n",
            [i(F ^ fr_offset), i(uint32.cast_to_int(Field))], !IO),
        wire_body_fields(F ^ fr_body, !IO),
        wire_frames(R1, !IO)
    ).

:- pred wire_body_fields(reader::in, io::di, io::uo) is det.

wire_body_fields(R0, !IO) :-
    next_field(FR, R0, R1),
    (
        FR = fields_end
    ;
        FR = field_error(_),
        io.write_string(" error\n", !IO)
    ;
        FR = field(Num, V),
        N = uint32.cast_to_int(Num),
        (
            V = fv_varint(U),
            io.format(" %d 0 %s\n", [i(N), s(uint64_to_string(U))], !IO)
        ;
            V = fv_fixed64(U),
            io.format(" %d 1 %s\n", [i(N), s(uint64_to_string(U))], !IO)
        ;
            V = fv_bytes(B),
            io.format(" %d 2 %s\n", [i(N), s(hex_or_dash(reader_bytes(B)))],
                !IO)
        ;
            V = fv_fixed32(U32),
            io.format(" %d 5 %d\n", [i(N), i(uint32.cast_to_int(U32))], !IO)
        ),
        wire_body_fields(R1, !IO)
    ).

:- func hex_or_dash(list(uint8)) = string.

hex_or_dash(Bytes) =
    ( if Bytes = [] then
        "-"
    else
        string.append_list(list.map(
            (func(B) = string.format("%02x", [i(uint8.cast_to_int(B))])), Bytes))
    ).

%-----------------------------------------------------------------------------%
% `atoms` -- what an artefact contains, through the real frame walk
%-----------------------------------------------------------------------------%
%
% Walked with `ds.atom.next_frame`, the predicate `ds.dsc` loads with, so no
% second implementation of [RFCS.19]'s framing reasons about atoms.

    % The atom registry, as `ds.atom` holds it: `<field>\t<message>`, from
    % what the compiled `wire/2` answers. Enumerated by probing every field
    % number in `1 .. 2047`, the range a two-byte inner tag holds, since
    % `wire/2`'s `multi` mode is private to `ds.atom`.
    %
:- pred print_atom_table(io::di, io::uo) is det.

print_atom_table(!IO) :-
    int.fold_up(print_atom_row, 1, 2047, !IO).

:- pred print_atom_row(int::in, io::di, io::uo) is det.

print_atom_row(N, !IO) :-
    ( if atom_of_field(uint32.det_from_int(N), A) then
        io.format("%d\t%s\n", [i(N), s(atom_message(A))], !IO)
    else
        true
    ).

    % `test_ds capability-table`: the Mercury half of the capabilities check.
    % `ds.capability` is written by hand from
    % `proto/capabilities.proto#Capability`, and the check holds what this
    % prints to the proto. Four views, because the table can be wrong in four places
    % and each is visible only from its own:
    %
    %   ctor    every constructor of the type, through `construct`, with its
    %           `capability_number` and `capability_name`. A constructor left
    %           out of `all_capabilities` shows here and nowhere else.
    %   member  every number in 0 .. 1023 that `capability_of_number`
    %           answers: what [RBND.1.3] and the loader consult.
    %   named   every constructor whose name `capability_named` answers with
    %           that constructor ([LCAP.1]'s stable name, both ways).
    %   all     `all_capabilities` in list order, which `ascending` and
    %           [RBND.4.2]'s serialization rely on being by number.
    %
:- pred print_capability_table(io::di, io::uo) is det.

print_capability_table(!IO) :-
    % As `test_registry.m`'s `constants`: an enumeration's constructors take
    % no arguments, so `construct` with none builds each one.
    TD = type_of(cap_realtime),
    NF = construct.det_num_functors(TD),
    Ctors = list.filter_map(
        ( func(I) = C is semidet :-
            U = construct.construct(TD, I, []),
            univ_to_type(U, C)
        ), 0 .. (NF - 1)),
    list.foldl(
        ( pred(C::in, !.IO::di, !:IO::uo) is det :-
            io.format("ctor\t%d\t%s\n",
                [i(capability_number(C)), s(capability_name(C))], !IO)
        ), Ctors, !IO),
    int.fold_up(
        ( pred(N::in, !.IO::di, !:IO::uo) is det :-
            ( if capability_of_number(N, C) then
                io.format("member\t%d\t%s\n", [i(N), s(capability_name(C))],
                    !IO)
            else
                true
            )
        ), 0, 1023, !IO),
    list.foldl(
        ( pred(C::in, !.IO::di, !:IO::uo) is det :-
            ( if capability_named(capability_name(C), C) then
                io.format("named\t%d\t%s\n",
                    [i(capability_number(C)), s(capability_name(C))], !IO)
            else
                true
            )
        ), Ctors, !IO),
    list.foldl(
        ( pred(C::in, !.IO::di, !:IO::uo) is det :-
            io.format("all\t%d\t%s\n",
                [i(capability_number(C)), s(capability_name(C))], !IO)
        ), all_capabilities, !IO).

    % `test_ds platform`: the Mercury half of the platform check.
    % The platform signature ([LDET.2.3], [NDET.2]), one `<field> <value>` line
    % per field and `backend <identity>` per series backend in slot order, as
    % the check prints libds's, so the two outputs are compared whole.
    %
:- pred print_platform(io::di, io::uo) is det.

print_platform(!IO) :-
    Sig = platform_signature,
    io.format("os_family %s\ncpu_arch %s\nlibc %s\ncompiler %s\n" ++
        "ds_version %s\n",
        [s(Sig ^ ps_os_family), s(Sig ^ ps_cpu_arch), s(Sig ^ ps_libc),
         s(Sig ^ ps_compiler), s(Sig ^ ps_ds_version)], !IO),
    list.foldl(
        ( pred(B::in, !.IO::di, !:IO::uo) is det :-
            io.format("backend %s\n", [s(B)], !IO)
        ), Sig ^ ps_backends, !IO).

    % `test_ds schema-sources <artefact>`: the Mercury half of the
    % schema-sources check. One `<schema> <file> <line> <col>` line per
    % schema whose SchemaSource names a module with a DsSource, sorted, as
    % the check prints libds's. The
    % case without a file is `test_srcs_decode`'s.
    %
:- pred print_schema_sources(string::in, io::di, io::uo) is det.

print_schema_sources(Path, !IO) :-
    read_bitmap(Path, Res, !IO),
    (
        Res = yes(BM),
        load_dsc(BM, LoadRes),
        (
            LoadRes = loaded(P),
            Lines0 = list.filter_map(schema_source_line(P), schema_sources(P)),
            list.sort(Lines0, Lines),
            list.foldl(io.write_string, Lines, !IO)
        ;
            LoadRes = load_failed(_),
            io.write_string("load refused\n", !IO)
        )
    ;
        Res = no,
        io.format("cannot read %s\n", [s(Path)], !IO),
        io.set_exit_status(2, !IO)
    ).

:- func schema_source_line(program, pair(string, source_pos)) = string
    is semidet.

schema_source_line(P, Name - Pos) = Line :-
    source_file(P, Pos ^ sp_clip, File),
    Line = string.append_list([Name, " ", File, " ",
        string.uint32_to_string(Pos ^ sp_line), " ",
        string.uint32_to_string(Pos ^ sp_col), "\n"]).

    % The platform signature's shape: this runtime names every one of its
    % series backings, each once. Its values are compared with libds's by
    % the platform check.
    %
% @spec [NDET.2.2]
:- pred test_platform(tally::in, tally::out, io::di, io::uo) is det.

test_platform(!T, !IO) :-
    Sig = platform_signature,
    Order = backend_slot_order,
    % The predicate forms of `sort` and `sort_and_remove_dups`: applied to one
    % argument, the function and predicate forms are ambiguous.
    list.sort(Order, Sorted),
    list.sort_and_remove_dups(Order, Distinct),
    list.sort_and_remove_dups(Sig ^ ps_backends, DistinctIds),
    list.length(Order, Slots),
    check("[NDET.2.2] the slot order names every series backing once",
        ( if
            num_functors(type_of(bk_welford)) = Slots,
            Distinct = Sorted
          then yes else no ), !T, !IO),
    check("[NDET.2.2] the signature lists one identity per backing, in order",
        ( if
            Sig ^ ps_backends = list.map(backend_identity, Order),
            list.same_length(DistinctIds, Order)
          then yes else no ), !T, !IO),
    check("[NDET.2.2] each identity is <atom>:<name>:<version>",
        ( if list.all_true(backend_identity_shape, Sig ^ ps_backends)
          then yes else no ), !T, !IO),
    % The clause's own example, whole: a backing named by anything but its
    % body message fails.
    check("NDET.2.2: the ring buffer is SeriesBackendRingBuffer:ds-ring-buffer:1.0.0",
        ( if backend_identity(bk_ring_buffer) =
                "SeriesBackendRingBuffer:ds-ring-buffer:1.0.0"
          then yes else no ), !T, !IO),
    check("[LDET.2.3] every build fact is answered; the version is this one",
        ( if
            Sig ^ ps_os_family \= "",
            Sig ^ ps_cpu_arch \= "",
            Sig ^ ps_libc \= "",
            Sig ^ ps_compiler \= "",
            Sig ^ ps_ds_version = ds.version.ds_version
          then yes else no ), !T, !IO).

:- pred backend_identity_shape(string::in) is semidet.

    % `<atom>` is a series backing's body message ([RDSC.7.1]): every one is
    % `SeriesBackend` and the backing's name.
    %
backend_identity_shape(Identity) :-
    string.split_at_char(':', Identity) = [Atom, Name, Version],
    string.remove_prefix("SeriesBackend", Atom, Backing),
    Backing \= "",
    Name \= "",
    Version \= "".

    % [NDET.2.5]'s table, whole and in slot order. `test_platform` checks the
    % list's shape; this pins what the identities are. Written out from the
    % clause, not derived from `ds.platform`, which is what it checks.
    %
% @spec [NDET.2.5]
:- pred test_ndet_2_5_backends(tally::in, tally::out, io::di, io::uo) is det.

test_ndet_2_5_backends(!T, !IO) :-
    Want = [
        "SeriesBackendWelfordEwma:ds-welford-ewma:0.1.0",
        "SeriesBackendMonotonicDeque:ds-monotonic-deque:0.1.0",
        "SeriesBackendFifoDeque:ds-fifo-deque:0.1.0",
        "SeriesBackendReservoir:ds-reservoir:0.1.0",
        "SeriesBackendIntervalPulse:ds-interval-pulse:0.1.0",
        "SeriesBackendNumericIntegral:ds-numeric-integral:0.1.0",
        "SeriesBackendRingBuffer:ds-ring-buffer:1.0.0"
    ],
    Sig = platform_signature,
    Got = Sig ^ ps_backends,
    check("[NDET.2.5] the backends are exactly the clause's seven, in order",
        ( if Got = Want then yes else no ), !T, !IO),
    ( if Got = Want then
        true
    else
        io.format("  want %s\n  got  %s\n",
            [s(string.join_list(", ", Want)), s(string.join_list(", ", Got))],
            !IO)
    ).

    % One atom kind's tally. A named record rather than a `pair`, whose `-`
    % is also subtraction.
    %
:- type atom_tally
    --->    atom_tally(
                tally_name  :: string,
                tally_count :: int
            ).

:- pred list_atoms(string::in, io::di, io::uo) is det.

list_atoms(Path, !IO) :-
    io.open_binary_input(Path, OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, ReadRes, !IO),
        io.close_binary_input(Stream, !IO),
        (
            ReadRes = ok(BM),
            walk_atoms(init_reader(BM), map.init, Counts, 0, Total, !IO),
            io.format("%d atoms\n", [i(Total)], !IO),
            map.foldl(print_atom_count, Counts, !IO),
            map.foldl(count_unknown, Counts, 0, Unknown),
            ( if Unknown > 0 then
                io.format("%d atom kind(s) unknown to ds.atom\n",
                    [i(Unknown)], !IO)
            else
                true
            )
        ;
            ReadRes = error(Err),
            io.format("cannot read %s: %s\n",
                [s(Path), s(io.error_message(Err))], !IO),
            io.set_exit_status(2, !IO)
        )
    ;
        OpenRes = error(Err),
        io.format("cannot open %s: %s\n",
            [s(Path), s(io.error_message(Err))], !IO),
        io.set_exit_status(2, !IO)
    ).

    % Keyed on the field number, so an unknown atom cannot be dropped from
    % the tally.
    %
:- pred walk_atoms(reader::in,
                   map(uint32, atom_tally)::in,
                   map(uint32, atom_tally)::out,
                   int::in, int::out, io::di, io::uo) is det.

walk_atoms(R0, !Counts, !Total, !IO) :-
    next_frame(Result, R0, R),
    (
        Result = fr_eof
    ;
        Result = fr_error(Err, Offset),
        io.format("  ERROR at byte %d: %s\n",
            [i(Offset), s(string(Err))], !IO),
        io.set_exit_status(1, !IO)
    ;
        Result = fr_ok(Frame),
        !:Total = !.Total + 1,
        (
            Frame ^ fr_atom = known(A),
            Field = atom_field(A),
            Name = atom_message(A)
        ;
            Frame ^ fr_atom = unknown(N),
            Field = N,
            % No registry entry: a loader refuses it [RFCS.19.3].
            Name = "UNKNOWN"
        ),
        ( if map.search(!.Counts, Field, Seen) then
            Prev = Seen ^ tally_count,
            map.det_update(Field, atom_tally(Name, Prev + 1), !Counts)
        else
            map.det_insert(Field, atom_tally(Name, 1), !Counts)
        ),
        walk_atoms(R, !Counts, !Total, !IO)
    ).

:- pred print_atom_count(uint32::in, atom_tally::in,
                         io::di, io::uo) is det.

print_atom_count(Field, atom_tally(Name, Count), !IO) :-
    io.format("  %5d  %-8s x%d\n",
        [i(uint32.cast_to_int(Field)), s(Name), i(Count)], !IO).

:- pred count_unknown(uint32::in, atom_tally::in, int::in, int::out)
    is det.

count_unknown(_, atom_tally(Name, _), !N) :-
    ( if string.prefix(Name, "UNKNOWN") then !:N = !.N + 1 else true ).

    % A cache entry is gone once the instant reaches its deadline, on the
    % read and at the sweep, and an entry with no deadline never goes. The
    % boundary is libds's `now >= deadline`.
    %
:- pred test_cache_expiry(tally::in, tally::out, io::di, io::uo) is det.

test_cache_expiry(!T, !IO) :-
    C0 = init_cache,
    cache_put("k", int(7i64), 1, yes(from_ns(10u64)), C0, C1),
    cache_put("forever", int(1i64), 1, no, C1, C2),
    check("cache: an entry reads before its deadline",
        ( if cache_get_live(C2, from_ns(9u64), "k", int(7i64))
          then yes else no ), !T, !IO),
    check("cache: an entry is a miss AT its deadline",
        ( if cache_get_live(C2, from_ns(10u64), "k", _) then no else yes ),
        !T, !IO),
    check("cache: an entry with no deadline never expires",
        ( if cache_get_live(C2, from_ns(1000000u64), "forever", int(1i64))
          then yes else no ), !T, !IO),
    check("cache: the raw read ignores deadlines",
        ( if cache_get(C2, "k", int(7i64)) then yes else no ), !T, !IO),
    cache_sweep(from_ns(9u64), Early, C2, C3),
    check("cache: a sweep before the deadline removes nothing",
        ( if Early = [], cache_size(C3) = 2 then yes else no ), !T, !IO),
    cache_sweep(from_ns(10u64), AtDeadline, C2, C4),
    check("cache: a sweep AT the deadline removes that entry and names it",
        ( if AtDeadline = ["k"], cache_size(C4) = 1,
             cache_get(C4, "forever", _), not cache_get(C4, "k", _)
          then yes else no ), !T, !IO),

    % [LDET.5.11]: several expired keys are named in the order they were last
    % set. The writes make that order differ from key order: m, z, a, then m
    % again, so set order is z a m and key order a m z.
    S0 = init_cache,
    cache_put("m", int(1i64), 1, yes(from_ns(10u64)), S0, S1),
    cache_put("z", int(1i64), 1, yes(from_ns(10u64)), S1, S2),
    cache_put("a", int(1i64), 1, yes(from_ns(10u64)), S2, S3),
    cache_put("m", int(2i64), 1, yes(from_ns(10u64)), S3, S4),
    cache_sweep(from_ns(10u64), Swept, S4, S5),
    % @spec [LDET.5.11]
    check("LDET.5.11 the sweep names expired keys in last-set order",
        ( if Swept = ["z", "a", "m"], cache_size(S5) = 0 then yes else no ),
        !T, !IO).

:- pred run_suite(io::di, io::uo) is det.

run_suite(!IO) :-
    T0 = tally(0, 0),
    test_ids(T0, T1, !IO),
    test_json(T1, T2, !IO),
    test_json_text(T2, T2a, !IO),
