%-----------------------------------------------------------------------------%
% ds.id -- reserved zeros are unrepresentable
%-----------------------------------------------------------------------------%

:- pred test_ids(tally::in, tally::out, io::di, io::uo) is det.

test_ids(!T, !IO) :-
    check("node_id rejects 0",
        ( if node_id(0u32, _) then no else yes ), !T, !IO),
    check("node_id accepts 1",
        ( if node_id(1u32, N) then
            ( if node_id_value(N) = 1u32 then yes else no )
          else no ), !T, !IO),
    check("expr_id rejects 0",
        ( if expr_id(0u32, _) then no else yes ), !T, !IO),
    check("module_id rejects 0 (the unset sentinel)",
        ( if module_id(0u32, _) then no else yes ), !T, !IO),

    % Slot 0 is a real slot. A slot_index is a position in a schema of at
    % most 65 535 slots; the wire's byte range and its 255 marker are
    % `ds.expr`'s readers' ([RDSC.4a.9.1]).
    check("slot_index ACCEPTS 0",
        ( if slot_index(0u32, _) then yes else no ), !T, !IO),
    check("slot_index ACCEPTS 255, a position the wire's fields cannot name",
        ( if slot_index(255u32, _) then yes else no ), !T, !IO),
    check("slot_index rejects 0xFFFF, past a schema's 65 535 slots",
        ( if slot_index(0xFFFFu32, _) then no else yes ), !T, !IO),

    check("seq round-trips 0 (stream_seq.tla starts AT zero)",
        ( if seq_value(make_seq(0u64)) = 0u64 then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%
% ds.json -- canonical order IS the representation
%-----------------------------------------------------------------------------%

:- pred test_json(tally::in, tally::out, io::di, io::uo) is det.

test_json(!T, !IO) :-
    % The claim ds.json rests on: two objects with equal contents built in
    % different orders unify, so Json equality is `=` ([RLOW.3.7.5]).
    A = j_object(object(["b" - j_int(2i64), "a" - j_int(1i64)])),
    B = j_object(object(["a" - j_int(1i64), "b" - j_int(2i64)])),
    check("object equality is insertion-order independent",
        ( if A = B then yes else no ), !T, !IO),

    check("members come back key-ascending",
        ( if members(object(["z" - j_null, "a" - j_null])) = [K1 - _, _],
             K1 = "a"
          then yes else no ), !T, !IO),

    % A repeated key given to the builder: the last wins, as libds's
    % `ds_json_object_set` replaces. Text that repeats a key is refused where
    % it is parsed ([LGRA.5.8.7]).
    check("duplicate key -- last wins",
        ( if members(object(["k" - j_int(1i64), "k" - j_int(2i64)]))
                = ["k" - j_int(2i64)]
          then yes else no ), !T, !IO),

    % The distinction that makes `has(path)` the only discriminator an author
    % has [LNUL.8.4]: resolving to a present null succeeds, an absent path
    % fails. One layer up ds.value collapses both.
    Doc = j_object(object(["a" - j_object(object(["b" - j_null]))])),
    check("resolve to a present null SUCCEEDS",
        ( if resolve([key("a"), key("b")], Doc, j_null) then yes else no ),
        !T, !IO),
    check("resolve to an absent path FAILS",
        ( if resolve([key("a"), key("z")], Doc, _) then no else yes ),
        !T, !IO),
    check("has_path agrees with resolve on a present null",
        ( if has_path([key("a"), key("b")], Doc) then yes else no ), !T, !IO),

    % A key against an array, or an index against an object, has no clause,
    % so it does not resolve.
    check("key step against an array does not resolve",
        ( if resolve([key("a")], j_array([j_int(1i64)]), _) then no else yes ),
        !T, !IO),
    check("index step in range resolves",
        ( if resolve([index(1)], j_array([j_int(7i64), j_int(8i64)]), j_int(8i64))
          then yes else no ), !T, !IO),
    check("index step out of range does not resolve",
        ( if resolve([index(5)], j_array([j_int(7i64)]), _) then no else yes ),
        !T, !IO),
    check("negative index does not resolve",
        ( if resolve([index(-1)], j_array([j_int(7i64)]), _) then no else yes ),
        !T, !IO).

%-----------------------------------------------------------------------------%
% ds.json_text -- libds's json.c grammar, case by case
%-----------------------------------------------------------------------------%

:- func jt(string) = parse_result.

jt(Text) = Result :-
    ds.json_text.parse(Text, Result).

:- func jt_with(json_limits, string) = parse_result.

jt_with(Limits, Text) = Result :-
    ds.json_text.parse_with(Limits, Text, Result).

:- pred jt_is(string::in, string::in, parse_result::in,
              tally::in, tally::out, io::di, io::uo) is det.

jt_is(Name, Text, Want, !T, !IO) :-
    check("json_text: " ++ Name, ( if jt(Text) = Want then yes else no ),
        !T, !IO).

:- pred test_json_text(tally::in, tally::out, io::di, io::uo) is det.

test_json_text(!T, !IO) :-
    % Scalars. A number with `.` or an exponent is a Float, any other an Int,
    % as libds's `parse_number` decides it.
    jt_is("null", "null", parsed(j_null), !T, !IO),
    jt_is("true", "true", parsed(j_bool(yes)), !T, !IO),
    jt_is("false", "false", parsed(j_bool(no)), !T, !IO),
    jt_is("an integer is an Int", "123", parsed(j_int(123i64)), !T, !IO),
    jt_is("a negative integer", "-7", parsed(j_int(-7i64)), !T, !IO),
    jt_is("-0 is the Int 0, as strtoll reads it", "-0",
        parsed(j_int(0i64)), !T, !IO),
    jt_is("a fraction is a Float", "1.5", parsed(j_float(1.5)), !T, !IO),
    jt_is("an exponent alone is a Float", "1e3",
        parsed(j_float(1000.0)), !T, !IO),
    jt_is("a signed capital exponent", "-2.5E+2",
        parsed(j_float(-250.0)), !T, !IO),
    jt_is("0.1 is correctly rounded", "0.1", parsed(j_float(0.1)), !T, !IO),

    % A Json Float is finite ([LGRA.5.8.10]): a literal that rounds to an
    % infinity is refused, never saturated, and the rounded value decides.
    % 1.7976931348623159e308 is below 1e309 and above 2^1024 - 2^970, so it
    % rounds to inf; 1.7976931348623158e308 is above the largest double's own
    % decimal and below that threshold, so it rounds to the largest double.
    jt_is("past the largest double is refused", "1e999",
        refused(jr_float_outside_double), !T, !IO),
    jt_is("below the most negative double is refused", "-1e400",
        refused(jr_float_outside_double), !T, !IO),
    jt_is("past the rounding threshold is refused", "1.7976931348623159e308",
        refused(jr_float_outside_double), !T, !IO),
    jt_is("inside an object too", "{\"x\":1e400}",
        refused(jr_float_outside_double), !T, !IO),
    jt_is("below the threshold reads as the largest double",
        "1.7976931348623158e308", parsed(j_float(float.max)), !T, !IO),
    check("json_text: a literal that rounds to zero is +0.0, of either sign",
        ( if
            jt("1e-400") = parsed(j_float(Pos)),
            jt("-1e-400") = parsed(j_float(Neg)),
            Pos = 0.0, Neg = 0.0,
            float.unchecked_quotient(1.0, Pos) > 0.0,
            float.unchecked_quotient(1.0, Neg) > 0.0
          then yes else no ), !T, !IO),

    % Int64 at its edges: refused outside, never saturated.
    jt_is("int64 max", "9223372036854775807",
        parsed(j_int(int64.max_int64)), !T, !IO),
    jt_is("int64 min", "-9223372036854775808",
        parsed(j_int(int64.min_int64)), !T, !IO),
    jt_is("one past int64 max is refused", "9223372036854775808",
        refused(jr_int_outside_int64), !T, !IO),
    jt_is("one below int64 min is refused", "-9223372036854775809",
        refused(jr_int_outside_int64), !T, !IO),
    jt_is("a 64-digit integer is outside int64, as libds says",
        string.duplicate_char('9', 64),
        refused(jr_int_outside_int64), !T, !IO),

    % Numbers libds's scan refuses.
    jt_is("a leading zero ends the number: 01", "01",
        refused(jr_syntax), !T, !IO),
    jt_is("a bare point", "1.", refused(jr_syntax), !T, !IO),
    jt_is("no integer part", ".5", refused(jr_syntax), !T, !IO),
    jt_is("a bare minus", "-", refused(jr_syntax), !T, !IO),
    jt_is("a plus sign", "+1", refused(jr_syntax), !T, !IO),
    jt_is("an empty exponent", "1e", refused(jr_syntax), !T, !IO),
    jt_is("a signed empty exponent", "1e+", refused(jr_syntax), !T, !IO),

    % Literals are byte prefixes; what follows is the next token's.
    jt_is("a truncated literal", "tru", refused(jr_syntax), !T, !IO),
    jt_is("a literal with a tail", "truex", refused(jr_syntax), !T, !IO),
    jt_is("nul", "nul", refused(jr_syntax), !T, !IO),

    % Whitespace is space, tab, LF and CR, around every token.
    jt_is("whitespace around tokens", " \t\n\r[ 1 ,\t2 ]\r\n",
        parsed(j_array([j_int(1i64), j_int(2i64)])), !T, !IO),
    jt_is("trailing whitespace is fine", "1 ", parsed(j_int(1i64)), !T, !IO),
    jt_is("trailing junk is not", "1 x", refused(jr_syntax), !T, !IO),
    jt_is("the empty text", "", refused(jr_syntax), !T, !IO),
    jt_is("whitespace alone", " \n", refused(jr_syntax), !T, !IO),

    % Containers.
    jt_is("empty containers", "[[],{}]",
        parsed(j_array([j_array([]), j_object(empty_object)])), !T, !IO),
    jt_is("an object", "{\"b\":1,\"a\":[true,null]}",
        parsed(j_object(object(["a" - j_array([j_bool(yes), j_null]),
                                "b" - j_int(1i64)]))), !T, !IO),
    jt_is("a trailing comma in an array", "[1,]", refused(jr_syntax), !T, !IO),
    jt_is("a trailing comma in an object", "{\"a\":1,}",
        refused(jr_syntax), !T, !IO),
    jt_is("an unquoted key", "{a:1}", refused(jr_syntax), !T, !IO),
    jt_is("a missing comma", "[1 2]", refused(jr_syntax), !T, !IO),
    jt_is("an unclosed array", "[1", refused(jr_syntax), !T, !IO),
    % [LGRA.5.8.7]: an object that repeats a key is refused, and the key is
    % compared as decoded, so an escaped spelling of it is the same key.
    jt_is("a repeated key is refused (LGRA.5.8.7)", "{\"k\":1,\"k\":2}",
        refused(jr_repeated_key), !T, !IO),
    jt_is("a key repeated through an escape is refused",
        "{\"k\":1,\"\\u006b\":2}", refused(jr_repeated_key), !T, !IO),
    jt_is("a key repeated in a nested object is refused",
        "{\"a\":{\"k\":1,\"k\":2}}", refused(jr_repeated_key), !T, !IO),
    jt_is("one key in two objects is not a repeat",
        "[{\"k\":1},{\"k\":2}]",
        parsed(j_array([j_object(object(["k" - j_int(1i64)])),
                        j_object(object(["k" - j_int(2i64)]))])), !T, !IO),

    % Strings.
    jt_is("the simple escapes", "\"\\\"\\\\\\/\\b\\f\\n\\r\\t\"",
        parsed(j_string("\"\\/\b\f\n\r\t")), !T, !IO),
    jt_is("a two-byte \\u", "\"\\u00e9\"", parsed(j_string("é")), !T, !IO),
    jt_is("a three-byte \\u, upper-case hex", "\"\\u20AC\"",
        parsed(j_string("€")), !T, !IO),
    jt_is("raw UTF-8 is copied", "\"é€\"", parsed(j_string("é€")), !T, !IO),
    % [LSTR.7.2.3]: a `\u` names one UTF-16 code unit (RFC 8259 §7). A high
    % then a low surrogate escape is the one codepoint the pair encodes, in a
    % value and in a key: U+10348 (D800 DF48, the lowest high surrogate) and
    % U+10FFFF (DBFF DFFF, the highest pair). A surrogate that is half of no
    % such pair is malformed. The bytes are libds's
    % `test_lstr_7_2_3__surrogate_pairs`. Path: `ds.json_text.escape` and
    % `hex4`, under `parse`.
    SurHwair = string.char_to_string(char.det_from_int(0x10348)),
    SurLast = string.char_to_string(char.det_from_int(0x10FFFF)),
    % @spec [LSTR.7.2.3]
    jt_is("[LSTR.7.2.3] a surrogate pair is one codepoint, U+10348",
        "\"\\ud800\\udf48\"", parsed(j_string(SurHwair)), !T, !IO),
    % @spec [LSTR.7.2.3]
    jt_is("[LSTR.7.2.3] a surrogate pair is one codepoint, U+10FFFF",
        "\"\\udbff\\udfff\"", parsed(j_string(SurLast)), !T, !IO),
    % @spec [LSTR.7.2.3]
    jt_is("[LSTR.7.2.3] a pair in upper-case hex, in a key and a value",
        "{\"a\\uD800\\uDF48b\": \"x\\ud800\\udf48\"}",
        parsed(j_object(object([("a" ++ SurHwair ++ "b")
            - j_string("x" ++ SurHwair)]))),
        !T, !IO),
    list.foldl2(
        ( pred(Case::in, T0::in, T1::out, IO0::di, IO1::uo) is det :-
            Case = {SurLabel, SurText},
            % @spec [LSTR.7.2.3]
            jt_is("[LSTR.7.2.3] " ++ SurLabel ++ " is refused", SurText,
                refused(jr_unpaired_surrogate), T0, T1, IO0, IO1)
        ),
        [{"a lone high surrogate", "\"\\ud800\""},
         {"a lone low surrogate", "\"\\udf48\""},
         {"a low surrogate before a high", "\"\\udf48\\ud800\""},
         {"a high surrogate, then a non-escape", "\"\\ud800x\""},
         {"a high surrogate, then a BMP escape", "\"\\ud800\\u0041\""},
         {"a high surrogate, then a cut escape", "\"\\ud800\\udf4\""},
         {"a lone high surrogate in a key", "{\"\\ud800\": 1}"}],
        !T, !IO),
    jt_is("\\u0000 is refused", "\"a\\u0000b\"",
        refused(jr_nul_escape), !T, !IO),
    jt_is("an unknown escape", "\"\\x\"", refused(jr_syntax), !T, !IO),
    jt_is("a short \\u", "\"\\u12\"", refused(jr_syntax), !T, !IO),
    jt_is("a raw control character", "\"a\tb\"", refused(jr_syntax), !T, !IO),
    jt_is("an unterminated string", "\"abc", refused(jr_syntax), !T, !IO),

    % The depth cap ([LGRA.5.8.6]): the root is level 1; level `max_depth`
    % parses, one more does not.
    jt_is("nesting at the cap parses", nested_text(max_depth),
        parsed(nested_term(max_depth)), !T, !IO),
    jt_is("nesting one past the cap is refused", nested_text(max_depth + 1),
        refused(jr_limit(jl_depth)), !T, !IO),

    % The table is [LGRA.5.8.6]'s four. The other three are tested
    % through `parse_with` at small bounds, each at its bound and one past it.
    check("json_text: the table is LGRA.5.8.6's four limits",
        ( if limits = json_limits(yes(max_depth), yes(max_nodes),
                yes(max_string_bytes), yes(max_text_bytes))
          then yes else no ), !T, !IO),
    Nodes = json_limits(no, yes(3), no, no),
    check("json_text: 3 nodes at a 3-node limit",
        ( if jt_with(Nodes, "[1,2]") = parsed(_) then yes else no ), !T, !IO),
    check("json_text: 4 nodes at a 3-node limit",
        ( if jt_with(Nodes, "[1,2,3]") = refused(jr_limit(jl_nodes))
          then yes else no ), !T, !IO),
    Strs = json_limits(no, no, yes(3), no),
    check("json_text: 3 string bytes at a 3-byte limit",
        ( if jt_with(Strs, "[\"ab\",\"c\"]") = parsed(_) then yes else no ),
        !T, !IO),
    check("json_text: a key counts as string bytes",
        ( if jt_with(Strs, "{\"ab\":\"cd\"}") =
                refused(jr_limit(jl_string_bytes))
          then yes else no ), !T, !IO),
    Text = json_limits(no, no, no, yes(5)),
    check("json_text: 5 bytes of text at a 5-byte limit",
        ( if jt_with(Text, "[1,2]") = parsed(_) then yes else no ), !T, !IO),
    % Six bytes, and malformed: refused for its length, so the limit is
    % checked before the text is read.
    check("json_text: 6 bytes of text at a 5-byte limit, before any parse",
        ( if jt_with(Text, "[1, xy") = refused(jr_limit(jl_text_bytes))
          then yes else no ), !T, !IO).

:- func nested_text(int) = string.

nested_text(N) =
    string.duplicate_char('[', N) ++ string.duplicate_char(']', N).

    % `N` levels of array, the innermost empty.
    %
:- func nested_term(int) = json.

nested_term(N) = ( if N =< 1 then j_array([]) else j_array([nested_term(N - 1)]) ).

%-----------------------------------------------------------------------------%
% ds.builtins -- the transcription, exercised
%-----------------------------------------------------------------------------%

:- pred test_builtins(tally::in, tally::out, io::di, io::uo) is det.

test_builtins(!T, !IO) :-
    check("FN_LOG = 47 is the log ACTION",
        ( if builtin_fn(47u32, fn_log) then yes else no ), !T, !IO),
    check("FN_LN = 9 is natural log, live through CORE-MATH",
        ( if builtin_fn(9u32, fn_ln) then yes else no ), !T, !IO),

    check("0 is the protobuf sentinel, refused",
        ( if builtin_fn(0u32, _) then no else yes ), !T, !IO),
    check("0 rejects as rf_unspecified",
        ( if why_rejected(0u32) = rf_unspecified then yes else no ), !T, !IO),
    check("15 is FN_TAN, live through CORE-MATH",
        ( if builtin_fn(15u32, fn_tan) then yes else no ), !T, !IO),
    check("19 is FN_ATAN2 and round-trips",
        ( if builtin_fn_wire(fn_atan2) = 19u32, builtin_fn(19u32, fn_atan2)
          then yes else no ), !T, !IO),
    check("42 is the belief candset tombstone",
        ( if why_rejected(42u32) = rf_belief then yes else no ), !T, !IO),
    check("109, FN_IS_NULL, is reserved and never a call",
        ( if why_rejected(109u32) = rf_not_callable then yes else no ),
        !T, !IO),
    check("112 FN_LATEST is never emitted as a call",
        ( if builtin_fn(112u32, _) then no else yes ), !T, !IO),
    check("128 is past the end",
        ( if why_rejected(128u32) = rf_unallocated then yes else no ),
        !T, !IO),
    check("80 FN_MONOTONIC is retired, not unallocated",
        ( if builtin_fn(80u32, _) then no
          else if why_rejected(80u32) = rf_retired_monotonic then yes
          else no ), !T, !IO),

    check("12 is FN_POW",
        ( if builtin_fn(12u32, fn_pow) then yes else no ), !T, !IO),
    check("127 FN_MONOTONIC_NS is the last allocated op",
        ( if builtin_fn(127u32, fn_monotonic_ns) then yes else no ), !T, !IO),

    % Both directions of the one table.
    check("wire round-trips fn_series_percentile",
        ( if builtin_fn_wire(fn_series_percentile) = 114u32 then yes else no ),
        !T, !IO),
    check("wire round-trips fn_currency_convert",
        ( if builtin_fn(builtin_fn_wire(fn_currency_convert),
                        fn_currency_convert)
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%
% ds.expr -- sentinels lifted at the wire boundary
%-----------------------------------------------------------------------------%

:- pred test_expr(tally::in, tally::out, io::di, io::uo) is det.

    % [RDSC.4a.9.1]: an index is a byte, 0..254, and 255
    % is the marker where the field has one. Each reader fails on what its
    % field cannot hold, which the decoder refuses.
    %
test_expr(!T, !IO) :-
    check("[RDSC.4a.9.1] pattern_index 255 is the candidate fact",
        ( if wire_fact_index(255u32, candidate) then yes else no ),
        !T, !IO),
    check("[RDSC.4a.9.1] pattern_index 254 is token position 254",
        ( if wire_fact_index(254u32, token_fact(254)) then yes else no ),
        !T, !IO),
    check("pattern_index 0 is token position 0",
        ( if wire_fact_index(0u32, token_fact(0)) then yes else no ),
        !T, !IO),
    check("[RDSC.4a.9.1] pattern_index 256 is no index",
        ( if wire_fact_index(256u32, _) then no else yes ), !T, !IO),
    check("[RDSC.4a.9.1] pattern_index 0xFFFF, the old marker, is no index",
        ( if wire_fact_index(0xFFFFu32, _) then no else yes ), !T, !IO),

    % The fact itself, VarExpr's alone.
    check("[RDSC.4a.9.1] VarExpr slot_index 255 is the whole fact",
        ( if wire_slot_read(255u32, whole_fact) then yes else no ),
        !T, !IO),
    check("VarExpr slot_index 3 is a slot read",
        ( if wire_slot_read(3u32, slot(_)) then yes else no ), !T, !IO),
    check("[RDSC.4a.9.1] VarExpr slot_index 256 is no index",
        ( if wire_slot_read(256u32, _) then no else yes ), !T, !IO),

    % AlphaTest and SlotAssign have no marker: 254 is the last index, and 255
    % is past the field ([RDSC.4a.9.1], [RDSC.4a.6.1]).
    check("[RDSC.4a.9.1] strict slot read accepts 254",
        ( if wire_slot_strict(254u32, S), slot_index_value(S) = 254u32
          then yes else no ), !T, !IO),
    check("[RDSC.4a.9.1] strict slot read REFUSES 255",
        ( if wire_slot_strict(255u32, _) then no else yes ), !T, !IO),
    check("strict slot read accepts 3",
        ( if wire_slot_strict(3u32, _) then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%
% ds.chrono
%-----------------------------------------------------------------------------%

:- pred test_chrono(tally::in, tally::out, io::di, io::uo) is det.

test_chrono(!T, !IO) :-
    I0 = from_ns(1000u64),
    D = duration_from_ns(500u64),
    check("add(instant, duration)",
        ( if instant_ns(add(I0, D)) = 1500u64 then yes else no ), !T, !IO),
    check("diff saturates at zero rather than wrapping",
        ( if duration_ns(diff(I0, from_ns(9999u64))) = 0u64
          then yes else no ), !T, !IO),
    check("before is strict",
        ( if before(I0, I0) then no else yes ), !T, !IO),

    % [LTIM.1.1.3]: a slot round-trip is not the identity on a Time.
    Z = ds_time(1234i64, 3600i64),
    check("to_utc drops the zone offset",
        ( if tz_offset_ns(to_utc(Z)) = 0i64 then yes else no ), !T, !IO),
    check("to_utc preserves utc_ns",
        ( if utc_ns(to_utc(Z)) = utc_ns(Z) then yes else no ), !T, !IO),
    check("local_ns is a same-unit add",
        ( if local_ns(Z) = utc_ns(Z) + 3600i64 then yes else no ), !T, !IO),

    % Mock-only: a live clock fails rather than ignoring the advance.
    Live = init_clock(I0),
    check("clock_advance FAILS on a live clock",
        ( if clock_advance(D, Live, _) then no else yes ), !T, !IO),
    ( if clock_to_mock(Live, Mock) then
        test_mock_clock(D, Mock, !T, !IO),
        test_ntst_3_1_advance_range(Mock, !T, !IO)
    else
        check("[NLFC.5.4] a fresh live clock switches to mock", no, !T, !IO)
    ),
    test_live_clock(I0, !T, !IO),
    test_ltim_2_8_2_a_live_reading_past_the_top_is_held(!T, !IO),
    test_ltim_local(!T, !IO).

    % @spec [NTST.3.1]
    % An advance past a clock's range is refused, the cases and the values of
    % libds's `test_ntst_3_1__an_advance_past_a_clocks_range_is_refused`.
    % `clock_advance` fails, and the clock it was given is a value, so nothing
    % moved. Path: `clock_advance` -> `ntst_3_1_advance_past_range`. A
    % session's status is `test_mercury_ds`'s.
    %
:- pred test_ntst_3_1_advance_range(clock::in, tally::in, tally::out,
    io::di, io::uo) is det.

test_ntst_3_1_advance_range(Mock, !T, !IO) :-
    One = duration_from_ns(1u64),
    TopNs = uint64.cast_from_int64(int64.max_int64),
    AtTop = duration_from_ns(TopNs),
    PastTop = duration_from_ns(TopNs + 1u64),
    check("[NTST.3.1] wall at 2^63 - 1, advance 1: refused",
        ( if
            clock_wall_set(int64.max_int64, Mock, W1),
            not clock_advance(One, W1, _)
          then yes else no ), !T, !IO),
    check("[NTST.3.1] wall at 2^63 - 2, advance 1: lands on the top",
        ( if
            clock_wall_set(int64.max_int64 - 1i64, Mock, W2),
            clock_advance(One, W2, A2),
            clock_source_wall(A2) = yes(int64.max_int64),
            clock_source_now(A2) = from_ns(1u64)
          then yes else no ), !T, !IO),
    check("[NTST.3.1] wall negative, duration 2^63: refused, the sum in range",
        ( if
            clock_wall_set(-5i64, Mock, W3),
            not clock_advance(PastTop, W3, _)
          then yes else no ), !T, !IO),
    check("[NTST.3.1] no wall, duration 2^63 - 1: taken, the wall still none",
        ( if
            clock_advance(AtTop, Mock, A4),
            clock_source_wall(A4) = no,
            clock_source_now(A4) = from_ns(TopNs)
          then yes else no ), !T, !IO),
    check("[NTST.3.1] no wall, duration 2^63: refused",
        ( if clock_advance(PastTop, Mock, _) then no else yes ), !T, !IO),
    check("[NTST.3.1] monotonic at 2^63 - 1: advance 1 refused, advance 0 taken",
        ( if
            clock_set(from_ns(TopNs), Mock, M6),
            not clock_advance(One, M6, _),
            clock_advance(duration_from_ns(0u64), M6, A6),
            clock_source_now(A6) = from_ns(TopNs)
          then yes else no ), !T, !IO),
    check("[NTST.3.1] a set to 2^63: refused, and a set to 2^63 - 1 taken",
        ( if
            not clock_set(from_ns(TopNs + 1u64), Mock, _),
            not clock_set(from_ns(uint64.max_uint64), Mock, _),
            ntst_3_1_set_past_range(from_ns(TopNs + 1u64)),
            not ntst_3_1_set_past_range(from_ns(TopNs))
          then yes else no ), !T, !IO).

    % @spec [LTIM.2.8.2]
    % A live reading past the top of the monotonic clock's range is held at the
    % top. libds reaches it by switching a mock clock at the top to live; a
    % Mercury clock has no such switch, so this live clock starts at the top.
    % Path: `clock_observe` -> `ltim_2_8_2_held`.
    %
:- pred test_ltim_2_8_2_a_live_reading_past_the_top_is_held(tally::in,
    tally::out, io::di, io::uo) is det.

test_ltim_2_8_2_a_live_reading_past_the_top_is_held(!T, !IO) :-
    Top = from_ns(uint64.cast_from_int64(int64.max_int64)),
    read_wall_clock(R0, !IO),
    next_reading(R0, 100000000, R1, !IO),
    check("[LTIM.2.8.2] a live reading past the top reads the top, and does "
        ++ "not decrease",
        ( if
            clock_observe(R0, init_clock(Top), Anchored),
            clock_source_now(Anchored) = Top,
            clock_observe(R1, Anchored, Later),
            clock_source_now(Later) = Top
          then yes else no ), !T, !IO).

    % Two clocks, a source and a held sample, one sample per step.
    %
:- pred test_mock_clock(duration::in, clock::in, tally::in, tally::out,
    io::di, io::uo) is det.

test_mock_clock(D, Mock, !T, !IO) :-
    % The source moves to the origins; the held sample is the last sample's
    % and changes only at the next one ([LTIM.2.8.4]).
    check("[NLFC.5.4] live -> mock puts the monotonic clock at 0 "
        ++ "and the wall clock unset",
        ( if clock_source_now(Mock) = from_ns(0u64), clock_wall(Mock) = no
          then yes else no ), !T, !IO),
    ( if clock_advance(D, Mock, C1) then
        check("[NTST.3.3] an advance moves the source, not the held sample",
            ( if clock_now(C1) = clock_now(Mock),
                 clock_source_now(C1) = from_ns(500u64)
              then yes else no ), !T, !IO),
        check("an advance leaves an unset wall clock unset",
            ( if clock_wall(C1) = no then yes else no ), !T, !IO),
        clock_sample(step_pump, Rec1, C1, S1),
        check("[LTIM.2.8.4] a sample takes the source into the held sample",
            ( if clock_now(S1) = from_ns(500u64) then yes else no ), !T, !IO),
        check("[LTIM.2.8.5] the first sample is recorded",
            ( if Rec1 = yes then yes else no ), !T, !IO),
        clock_mark_recorded(S1, M1),
        clock_sample(step_pump, Rec2, M1, _),
        check("[LTIM.2.8.5] an unchanged sample is not recorded again",
            ( if Rec2 = no then yes else no ), !T, !IO),
        ( if clock_wall_set(7000i64, M1, W1), clock_advance(D, W1, W2) then
            clock_sample(step_pump, Rec3, W2, S3),
            check("[NTST.3.1] an advance moves a set wall clock by the "
                ++ "same duration",
                ( if clock_wall(S3) = yes(7500i64) then yes else no ),
                !T, !IO),
            check("[LTIM.2.8.5] a moved wall clock is recorded",
                ( if Rec3 = yes then yes else no ), !T, !IO)
        else
            check("clock_wall_set works on a mock clock", no, !T, !IO)
        ),
        check("[NTST.3.1] before the first sample a backward set is allowed",
            ( if clock_set(from_ns(100u64), C1, _) then yes else no ),
            !T, !IO),
        % The first sample, not the first input: M1 has taken a pump's sample
        % and no input, and a backward set there would put a decreasing
        % ClockAdvance on the trace ([LTIM.2.8.2]).
        check("[NTST.3.1] after a pump's sample, with no input, a backward "
            ++ "set is refused",
            ( if clock_set(from_ns(100u64), M1, _) then no else yes ),
            !T, !IO),
        clock_sample(step_input, _, M1, Consumed),
        check("[NTST.3.1] after an input a backward set is refused",
            ( if clock_set(from_ns(100u64), Consumed, _) then no else yes ),
            !T, !IO),
        check("[NTST.3.1] and a forward set is not",
            ( if clock_set(from_ns(900u64), Consumed, _) then yes else no ),
            !T, !IO),
        check("[NLFC.5.4] a mock clock stays mock",
            ( if clock_to_mock(Consumed, Same), Same = Consumed
              then yes else no ), !T, !IO)
    else
        check("clock_advance works on a mock clock", no, !T, !IO)
    ).

    % `utc()` and `local()`, and the zone's `TimeZoneOffset` rows behind the
    % second ([LTIM.10.7]). Each fault takes libds's class
    % (`adapter_ds_local`).
    %
:- pred test_ltim_local(tally::in, tally::out, io::di, io::uo) is det.

test_ltim_local(!T, !IO) :-
    Hour = 3600000000000i64,
    T0 = e_lit(time(ds_time(1000i64, Hour))),
    LA = e_lit(text("America/Los_Angeles")),
    % The offset depends on the instant, as DST makes it: -8 h before 500 ns,
    % -7 h from then on. Two rows, the period half-open.
    WithTz = tz_ectx([
        {"America/Los_Angeles", int64.min_int64, 500i64, -28800i64},
        {"America/Los_Angeles", 500i64, int64.max_int64, -25200i64}]),

    check("[LTIM.3.1] utc() keeps the instant and zeroes the offset",
        ( if eval(e_call(fn_utc, [T0]), ectx, ev_ok(time(U))),
             utc_ns(U) = 1000i64, tz_offset_ns(U) = 0i64
          then yes else no ), !T, !IO),
    check("[LTIM.3.2] local() keeps the instant and takes the row's offset, "
        ++ "seconds made nanoseconds",
        ( if eval(e_call(fn_local, [T0, LA]), WithTz, ev_ok(time(L))),
             utc_ns(L) = 1000i64, tz_offset_ns(L) = -7i64 * Hour
          then yes else no ), !T, !IO),
    check("[LTIM.10.7] the row is chosen AT the instant",
        ( if eval(e_call(fn_local, [e_lit(time(ds_time(100i64, 0i64))), LA]),
                WithTz, ev_ok(time(L2))),
             tz_offset_ns(L2) = -8i64 * Hour
          then yes else no ), !T, !IO),
    check("[LTIM.10.7] valid_until is exclusive: 499 ns is the first row's, "
            ++ "500 the second's",
        ( if
            eval(e_call(fn_local, [e_lit(time(ds_time(499i64, 0i64))), LA]),
                WithTz, ev_ok(time(L3))),
            tz_offset_ns(L3) = -8i64 * Hour,
            eval(e_call(fn_local, [e_lit(time(ds_time(500i64, 0i64))), LA]),
                WithTz, ev_ok(time(L4))),
            tz_offset_ns(L4) = -7i64 * Hour
          then yes else no ), !T, !IO),
    check("[LTIM.10.5.4] no rows is a DOMAIN fault, never UTC",
        ( if eval(e_call(fn_local, [T0, LA]), ectx, ev_fault(rf_domain))
          then yes else no ), !T, !IO),
    % A zone no row answers is DOMAIN, whatever supplied it.
    Mars = e_lit(text("Mars/Olympus")),
    check("[LTIM.10.5.3] a refused zone from a literal is DOMAIN",
        ( if eval(e_call(fn_local, [T0, Mars]), WithTz, ev_fault(rf_domain))
          then yes else no ), !T, !IO),
    check("[LTIM.10.5.3] and from Json data DOMAIN too, not a TypeError",
        ( if eval(e_tainted(e_call(fn_local, [T0, Mars])), WithTz,
                ev_fault(rf_domain))
          then yes else no ), !T, !IO),
    % A `null` operand is a TypeError at a clean node, where a mismatch of a
    % present value is the artefact's ([IRET.9.6]).
    check("[IRET.9.6] local() of a null is a TypeError, untainted",
        ( if eval(e_call(fn_local, [e_lit(null), LA]), WithTz,
                ev_fault(rf_type_error))
          then yes else no ), !T, !IO),
    check("[IRET.9.6] and so is a null zone",
        ( if eval(e_call(fn_local, [T0, e_lit(null)]), WithTz,
                ev_fault(rf_type_error))
          then yes else no ), !T, !IO),
    check("local() of a non-Time is a mismatch",
        ( if eval(e_call(fn_local, [e_lit(text("noon")), LA]), WithTz,
                ev_fault(rf_artefact_lied))
          then yes else no ), !T, !IO),
    test_ltim_date(!T, !IO),
    test_ltim_1_2_2_date_range(!T, !IO),
    test_ltim_14_calendar(!T, !IO),
    test_iso8601_at_an_offset(!T, !IO),
    test_ltim_8_2_4_range_ends(!T, !IO),
    test_ltim_components(!T, !IO),
    test_ltim_10_7_index(!T, !IO).

    % @spec [LTIM.10.7] -- working memory's zone index, the counterpart of
    % libds's `test_ltim_10_7__resolution`, case for case: the floor row
    % answers while its period runs, overlapping rows in either order, a
    % retract and an upsert, byte-for-byte zones, and 1024 rows asserted in a
    % scrambled order then half retracted. Driven through
    % `ds.wm.ltim_10_7_offset` and `assert_fact` / `retract_fact`, the doors
    % every path into working memory passes.
    %
:- pred test_ltim_10_7_index(tally::in, tally::out, io::di, io::uo) is det.

test_ltim_10_7_index(!T, !IO) :-
    Z = "Europe/Berlin",
    Wide = {Z, 0i64, 1000i64, 60i64},
    Narrow = {Z, 500i64, 600i64, 120i64},
    Resolve = (func(Ctx, Zone, At) = Answer :-
        ( if
            interned(Ctx ^ ec_interns, Zone, Ref),
            ltim_10_7_offset(Ctx ^ ec_wm, Ref, At, Off)
        then
            Answer = yes(Off)
        else
            Answer = no
        )),
    list.foldl2(
        ( pred({Label, Rows}::in, T0::in, T1::out, IO0::di, IO1::uo) is det :-
            C = tz_ectx(Rows),
            check("[LTIM.10.7] " ++ Label ++ ": before every valid_from, none",
                ( if Resolve(C, Z, -1i64) = no then yes else no ), T0, Ta,
                IO0, IOa),
            check("[LTIM.10.7] " ++ Label ++ ": valid_from is inclusive",
                ( if Resolve(C, Z, 0i64) = yes(60i32) then yes else no ),
                Ta, Tb, IOa, IOb),
            check("[LTIM.10.7] " ++ Label ++ ": 550, the greatest valid_from "
                    ++ "not after it answers",
                ( if Resolve(C, Z, 550i64) = yes(120i32) then yes else no ),
                Tb, Tc, IOb, IOc),
            check("[LTIM.10.7] " ++ Label ++ ": 700, the floor's period has "
                    ++ "ended, so none, though the wide row covers it",
                ( if Resolve(C, Z, 700i64) = no then yes else no ),
                Tc, Td, IOc, IOd),
            check("[LTIM.10.7] " ++ Label ++ ": valid_until is exclusive",
                ( if Resolve(C, Z, 1000i64) = no then yes else no ),
                Td, Te, IOd, IOe),
            check("[LTIM.10.6] " ++ Label ++ ": the zone compares byte for "
                    ++ "byte",
                ( if Resolve(C, "europe/berlin", 550i64) = no then yes else no ),
                Te, T1, IOe, IO1)),
        [{"wide first", [Wide, Narrow]}, {"narrow first", [Narrow, Wide]}],
        !T, !IO),

    % Retract, upsert and the zone leaving the index, on one working memory.
    C0 = tz_ectx([Wide, Narrow]),
    WM0 = C0 ^ ec_wm,
    IT = C0 ^ ec_interns,
    ( if
        interned(IT, Z, ZRef),
        fact_for_identity(WM0, tz_identity(ZRef, 500i64), NarrowFact),
        retract_fact(NarrowFact ^ f_id, rc_explicit, WM0, WM1)
    then
        check("[LTIM.10.7] a retracted row leaves the index: 550 and 700 read "
                ++ "the wide row again",
            ( if
                ltim_10_7_offset(WM1, ZRef, 550i64, 60i32),
                ltim_10_7_offset(WM1, ZRef, 700i64, 60i32)
              then yes else no ), !T, !IO),
        assert_fact(tzo_schema, [str(ZRef), int(0i64), int(2000i64),
            int(90i64)], at(0), no, tms_none, live, Up, WM1, WM2),
        check("[LTIM.10.7] an upsert of (zone, valid_from) answers with its "
                ++ "own values",
            ( if
                Up = replaced(_, UpId),
                ltim_10_7_offset(WM2, ZRef, 1500i64, 90i32),
                ltim_10_7_offset(WM2, ZRef, 100i64, 90i32),
                tz_zone_count(WM2) = 1,
                retract_fact(UpId, rc_explicit, WM2, WM3),
                not ltim_10_7_offset(WM3, ZRef, 100i64, _),
                tz_zone_count(WM3) = 0
              then yes else no ), !T, !IO)
    else
        check("[LTIM.10.7] the narrow row is found and retracted", no, !T, !IO)
    ),

    % 1024 rows: row k covers [10k, 10k + 10) with offset k, asserted in the
    % order i -> 7919 i mod 1024 (7919 is prime), then every even row
    % retracted.
    N = 1024,
    Order = list.map((func(I) = (I * 7919) mod N), 0 .. N - 1),
    Many = tz_ectx(list.map(
        (func(K) = {Z, int64.from_int(10 * K), int64.from_int(10 * K + 10),
            int64.from_int(K)}), Order)),
    ( if interned(Many ^ ec_interns, Z, MRef) then
        % The rows whose midpoint does not read the row's own offset.
        Wrong = list.filter(
            ( pred(J::in) is semidet :-
                not ltim_10_7_offset(Many ^ ec_wm, MRef,
                    int64.from_int(10 * J + 5), int32.det_from_int(J)) ),
            0 .. N - 1),
        check("[LTIM.10.7] each of 1024 rows answers its own period",
            ( if Wrong = [] then yes else no ), !T, !IO),
        list.foldl(
            ( pred(R::in, W0::in, W::out) is det :-
                ( if
                    fact_for_identity(W0,
                        tz_identity(MRef, int64.from_int(10 * R)), F),
                    retract_fact(F ^ f_id, rc_explicit, W0, W1)
                then
                    W = W1
                else
                    unexpected($pred, "retract a row of 1024")
                )),
            list.filter((pred(E::in) is semidet :- E mod 2 = 0), 0 .. N - 1),
            Many ^ ec_wm, Half),
        % An even row is gone and its midpoint reads none; an odd one stays.
        Wrong2 = list.filter(
            ( pred(J2::in) is semidet :-
                At = int64.from_int(10 * J2 + 5),
                ( if J2 mod 2 = 0 then
                    ltim_10_7_offset(Half, MRef, At, _)
                else
                    not ltim_10_7_offset(Half, MRef, At, int32.det_from_int(J2))
                ) ),
            0 .. N - 1),
        check("[LTIM.10.7] with every even row retracted, each instant reads "
                ++ "its own row or none",
            ( if Wrong2 = [] then yes else no ), !T, !IO)
    else
        check("[LTIM.10.7] the zone is interned", no, !T, !IO)
    ).

    % The identity of the `TimeZoneOffset` row (zone, valid_from)
    % ([LTIM.10.6]), as `project_identity` computes it for `tzo_schema`.
    %
:- func tz_identity(intern_ref, int64) = fact_identity.

tz_identity(Zone, From) = Key :-
    ( if
        project_identity(tzo_schema,
            array.from_list([str(Zone), int(From), null, null])) = yes(K)
    then
        Key = K
    else
        unexpected($pred, "TimeZoneOffset has an identity")
    ).

    % [LTIM.6.5]: a component of `(instant, zone)`. The cases are libds's
    % `test_components_in_a_zone`, instant for instant: the zone moves the day
    % and with it every calendar component, "UTC" needs no row, and the last
    % instant a row covers does not overflow in Tokyo.
    %
:- pred test_ltim_components(tally::in, tally::out, io::di, io::uo) is det.

test_ltim_components(!T, !IO) :-
    WithTz = two_zones,
    Jan2 = e_lit(int(1767322800000000000i64)),     % 2026-01-02T03:00:00Z
    Dec31 = e_lit(int(1767211200000000000i64)),    % 2025-12-31T20:00:00Z
    Dec31Plus61 = e_lit(int(1767211261000000000i64)),
    % The last instant a row covers: valid_until is exclusive ([LTIM.10.7]).
    Last = e_lit(int(int64.max_int64 - 1i64)),     % 2262-04-11T23:47:16Z
    UTC = e_lit(text("UTC")),
    LA = e_lit(text("America/Los_Angeles")),
    Tokyo = e_lit(text("Asia/Tokyo")),
    Cases = [
        {"day(UTC) = 2", fn_day, Jan2, UTC, 2i64},
        {"hour(UTC) = 3", fn_hour, Jan2, UTC, 3i64},
        {"day_of_week(UTC) = 4, a Friday", fn_day_of_week, Jan2, UTC, 4i64},
        {"day(Los Angeles) = 1", fn_day, Jan2, LA, 1i64},
        {"hour(Los Angeles) = 19", fn_hour, Jan2, LA, 19i64},
        {"day_of_week(Los Angeles) = 3, a Thursday", fn_day_of_week, Jan2,
            LA, 3i64},
        {"year(UTC) = 2025", fn_year, Dec31, UTC, 2025i64},
        {"year(Tokyo) = 2026", fn_year, Dec31, Tokyo, 2026i64},
        {"month(Tokyo) = 1", fn_month, Dec31, Tokyo, 1i64},
        {"minute(Tokyo, +61 s) = 1", fn_minute, Dec31Plus61, Tokyo, 1i64},
        {"second(Tokyo, +61 s) = 1", fn_second, Dec31Plus61, Tokyo, 1i64},
        {"day(INT64_MAX - 1, Tokyo) = 12, no overflow", fn_day, Last, Tokyo,
            12i64},
        {"hour(INT64_MAX - 1, Tokyo) = 8", fn_hour, Last, Tokyo, 8i64},
        {"hour(INT64_MAX, UTC) = 23: UTC takes no row", fn_hour,
            e_lit(int(int64.max_int64)), UTC, 23i64}
    ],
    list.foldl2(
        (pred({Label, Fn, At, Zone, Want}::in, T0::in, T1::out,
                IO0::di, IO1::uo) is det :-
            check("[LTIM.6.5] " ++ Label,
                ( if eval(e_call(Fn, [At, Zone]), WithTz, ev_ok(int(Want)))
                  then yes else no ), T0, T1, IO0, IO1)),
        Cases, !T, !IO),
    check("[LTIM.10.5.3] a component in a refused zone is DOMAIN",
        ( if eval(e_call(fn_hour, [Jan2, e_lit(text("Nowhere/Land"))]), WithTz,
                ev_fault(rf_domain))
          then yes else no ), !T, !IO),
    check("[LTIM.10.5.3] and from Json data DOMAIN too, not a TypeError",
        ( if eval(e_tainted(e_call(fn_hour,
                    [Jan2, e_lit(text("Nowhere/Land"))])), WithTz,
                ev_fault(rf_domain))
          then yes else no ), !T, !IO),
    check("[LTIM.10.8] hour(UTC) needs no row, as utc(t) needs none",
        ( if eval(e_call(fn_hour, [Jan2, UTC]), ectx, ev_ok(int(3i64)))
          then yes else no ), !T, !IO),
    % A component in a zone is a `local()` evaluation, so with no row it is
    % DOMAIN, as `local()` is.
    check("[LTIM.10.5.3] hour(Tokyo) with no rows is DOMAIN",
        ( if eval(e_call(fn_hour, [Jan2, Tokyo]), ectx, ev_fault(rf_domain))
          then yes else no ), !T, !IO),
    check("[LTIM.10.7] hour(INT64_MAX, Tokyo) has no row: valid_until is "
            ++ "exclusive",
        ( if eval(e_call(fn_hour, [e_lit(int(int64.max_int64)), Tokyo]),
                WithTz, ev_fault(rf_domain))
          then yes else no ), !T, !IO),
    % [LTIM.10.8]: only exactly "UTC" answers with no row.
    check("[LTIM.10.8] \"utc\" is a zone like any other, with no row DOMAIN",
        ( if eval(e_call(fn_local, [Jan2, e_lit(text("utc"))]), ectx,
                ev_fault(rf_domain))
          then yes else no ), !T, !IO),
    check("[LTIM.10.8] local(t, \"UTC\") is offset 0 with no row",
        ( if eval(e_call(fn_local, [Jan2, UTC]), ectx, ev_ok(time(UT))),
             tz_offset_ns(UT) = 0i64
          then yes else no ), !T, !IO).

    % `t.date(tz)`, days since 1970-01-01 in the named zone, through
    % the zone's rows and with `local`'s failure classes. The cases are
    % libds's `test_date_resolves` / `test_date_unresolved_errs`, instant for
    % instant, and each is one where the UTC date is a different answer.
    %
:- pred test_ltim_date(tally::in, tally::out, io::di, io::uo) is det.

test_ltim_date(!T, !IO) :-
    WithTz = two_zones,
    Date =(func(Instant, Zone) = Outcome :-
        eval(e_call(fn_time_date, [e_lit(time(ds_time(Instant, 0i64))),
            e_lit(text(Zone))]), WithTz, Outcome)),
    % 2026-01-02T03:00:00Z: day 20455 in UTC, 2026-01-01T19:00 in LA.
    Jan2 = 1767322800000000000i64,
    check("[LTIM.3.3.1] date(UTC) is the UTC day",
        ( if Date(Jan2, "UTC") = ev_ok(int(20455i64)) then yes else no ),
        !T, !IO),
    check("[LTIM.3.3.1] date(America/Los_Angeles) is the local day, not UTC's",
        ( if Date(Jan2, "America/Los_Angeles") = ev_ok(int(20454i64))
          then yes else no ), !T, !IO),
    check("date() floors across the epoch: -1 ns is day -1 in UTC",
        ( if Date(-1i64, "UTC") = ev_ok(int(-1i64)) then yes else no ),
        !T, !IO),
    check("date() floors across the epoch: -1 ns is day 0 in Tokyo",
        ( if Date(-1i64, "Asia/Tokyo") = ev_ok(int(0i64)) then yes else no ),
        !T, !IO),
    % [LTIM.1.2.2]: the date must be a `Date`, days -106751 through 106751.
    % libds's `test_date_resolves`, case for case. The last instant a row
    % covers, INT64_MAX - 1 ([LTIM.10.7]), is 08:47 on day 106752 in Tokyo,
    % found without overflow and refused; 1677-09-21T15:12:43Z is on day
    % -106752 in UTC and on the first Date in Tokyo.
    check("[LTIM.1.2.2] date() of the last covered instant in Tokyo is day "
            ++ "106752, not a Date: NOT_REPRESENTABLE",
        ( if Date(int64.max_int64 - 1i64, "Asia/Tokyo")
                = ev_fault(rf_not_representable)
          then yes else no ), !T, !IO),
    check("[LTIM.10.7] date(INT64_MAX, Tokyo) has no row",
        ( if Date(int64.max_int64, "Asia/Tokyo") = ev_fault(rf_domain)
          then yes else no ), !T, !IO),
    check("[LTIM.1.2.2] date() of the last instant in UTC is the last Date",
        ( if Date(int64.max_int64, "UTC") = ev_ok(int(106751i64))
          then yes else no ), !T, !IO),
    Early = int64.min_int64 + 54000000000000i64,    % fifteen hours on
    check("[LTIM.1.2.2] 1677-09-21T15:12:43Z is day -106752 in UTC, not a Date",
        ( if Date(Early, "UTC") = ev_fault(rf_not_representable)
          then yes else no ), !T, !IO),
    check("[LTIM.1.2.2] and day -106751 in Tokyo, the first Date",
        ( if Date(Early, "Asia/Tokyo") = ev_ok(int(-106751i64))
          then yes else no ), !T, !IO),
    check("[LTIM.10.5.3] date() of a refused zone is DOMAIN, never UTC",
        ( if Date(Jan2, "Nowhere/Land") = ev_fault(rf_domain)
          then yes else no ), !T, !IO),
    check("[LTIM.10.5.3] and from Json data DOMAIN too, not a TypeError",
        ( if eval(e_tainted(e_call(fn_time_date, [e_lit(int(Jan2)),
                    e_lit(text("Nowhere/Land"))])), WithTz, ev_fault(rf_domain))
          then yes else no ), !T, !IO),
    % [LTIM.10.8]: "UTC" needs no row; any other zone with no rows is a
    % DOMAIN fault, never UTC.
    check("[LTIM.10.8] date(UTC) with no rows is the UTC day",
        ( if eval(e_call(fn_time_date, [e_lit(int(Jan2)), e_lit(text("UTC"))]),
                ectx, ev_ok(int(20455i64)))
          then yes else no ), !T, !IO),
    check("[LTIM.10.5.4] date(Asia/Tokyo) with no rows is a DOMAIN fault, "
            ++ "never UTC",
        ( if eval(e_call(fn_time_date, [e_lit(int(Jan2)),
                    e_lit(text("Asia/Tokyo"))]), ectx, ev_fault(rf_domain))
          then yes else no ), !T, !IO).

    % [LTIM.14.1] / [LTIM.14.2]: `calendar.time` and `calendar.date`, libds's
    % `test_ltim_14_1__calendar_builds`, `test_ltim_14_2__calendar_domain` and
    % `test_ltim_14_2__calendar_not_representable`, case for case. A field out
    % of its range is DOMAIN, checked before the value's range; a value out of
    % its type's range is NOT_REPRESENTABLE; a null field is null.
    %
:- pred test_ltim_14_calendar(tally::in, tally::out, io::di, io::uo) is det.

test_ltim_14_calendar(!T, !IO) :-
    Lits = (func(Is) = list.map((func(I) = e_lit(int(I))), Is)),
    Time = (func(Is) = Outcome :-
        eval(e_call(fn_calendar_time, Lits(Is)), ectx, Outcome)),
    Date = (func(Is) = Outcome :-
        eval(e_call(fn_calendar_date, Lits(Is)), ectx, Outcome)),
    check("[LTIM.14.1] calendar.time(2024, 1, 15, 16, 0, 0, 123456789)",
        ( if Time([2024i64, 1i64, 15i64, 16i64, 0i64, 0i64, 123456789i64])
                = ev_ok(time(ds_time(1705334400123456789i64, 0i64)))
          then yes else no ), !T, !IO),
    check("[LTIM.14.1] calendar.time(1969, 12, 31, 23, 59, 59) is -1 s",
        ( if Time([1969i64, 12i64, 31i64, 23i64, 59i64, 59i64, 0i64])
                = ev_ok(time(ds_time(-1000000000i64, 0i64)))
          then yes else no ), !T, !IO),
    check("[LTIM.14.1] calendar.date(2024, 2, 29) is day 19782",
        ( if Date([2024i64, 2i64, 29i64]) = ev_ok(int(19782i64))
          then yes else no ), !T, !IO),
    check("[LTIM.8.2.4] calendar.time's nanoseconds are written whole",
        ( if
            eval(e_call(fn_to_string, [e_call(fn_calendar_time,
                Lits([2024i64, 1i64, 15i64, 16i64, 0i64, 0i64, 123456789i64]))]),
                ectx, ev_ok(text("2024-01-15T16:00:00.123456789Z")))
          then yes else no ), !T, !IO),
    Domain = [
        "month 13" - [2024i64, 13i64, 1i64],
        "month 0" - [2024i64, 0i64, 1i64],
        "2023-02-29" - [2023i64, 2i64, 29i64],
        "day 0" - [2024i64, 1i64, 0i64],
        "2024-04-31" - [2024i64, 4i64, 31i64],
        "month 13, year 2^63-1" - [int64.max_int64, 13i64, 1i64]
    ],
    TimeDomain = [
        "hour 24" - [2024i64, 1i64, 1i64, 24i64, 0i64, 0i64, 0i64],
        "minute 60" - [2024i64, 1i64, 1i64, 0i64, 60i64, 0i64, 0i64],
        "second 60" - [2024i64, 1i64, 1i64, 0i64, 0i64, 60i64, 0i64],
        "nanosecond 10^9" - [2024i64, 1i64, 1i64, 0i64, 0i64, 0i64,
            1000000000i64],
        "nanosecond -1" - [2024i64, 1i64, 1i64, 0i64, 0i64, 0i64, -1i64],
        "hour -1" - [2024i64, 1i64, 1i64, -1i64, 0i64, 0i64, 0i64]
    ],
    list.filter((pred((_ - Is)::in) is semidet :-
            not (
                Date(Is) = ev_fault(rf_domain),
                Time(Is ++ [0i64, 0i64, 0i64, 0i64]) = ev_fault(rf_domain)
            )),
        Domain, WrongDate),
    list.filter((pred((_ - Is)::in) is semidet :-
            Time(Is) \= ev_fault(rf_domain)),
        TimeDomain, WrongTime),
    report_offenders(assoc_list.keys(WrongDate ++ WrongTime), !IO),
    check("[LTIM.14.2] a field outside its range is DOMAIN",
        ( if WrongDate = [], WrongTime = [] then yes else no ), !T, !IO),
    check("[LTIM.14.2] 2024-02-29T23:59:59.999999999Z is an instant",
        ( if Time([2024i64, 2i64, 29i64, 23i64, 59i64, 59i64, 999999999i64])
                = ev_ok(time(_))
          then yes else no ), !T, !IO),
    check("[LTIM.14.2] a null field is null",
        ( if
            eval(e_call(fn_calendar_date, [e_lit(int(2024i64)), e_lit(null),
                e_lit(int(1i64))]), ectx, ev_ok(null))
          then yes else no ), !T, !IO),
    NotRep = (pred(O::in) is semidet :- O = ev_fault(rf_not_representable)),
    Times = [
        "1677-09-21" - [1677i64, 9i64, 21i64, 0i64, 0i64, 0i64, 0i64]
            - no,
        "1677-09-21T00:12:43.145224191Z" - [1677i64, 9i64, 21i64, 0i64, 12i64,
            43i64, 145224191i64] - no,
        "1677-09-21T00:12:43.145224192Z" - [1677i64, 9i64, 21i64, 0i64, 12i64,
            43i64, 145224192i64] - yes(int64.min_int64),
        "1677-09-21T00:12:44Z" - [1677i64, 9i64, 21i64, 0i64, 12i64, 44i64,
            0i64] - yes(-9223372036000000000i64),
        "2262-04-11T23:47:16.854775807Z" - [2262i64, 4i64, 11i64, 23i64, 47i64,
            16i64, 854775807i64] - yes(int64.max_int64),
        "2262-04-11T23:47:16.854775808Z" - [2262i64, 4i64, 11i64, 23i64, 47i64,
            16i64, 854775808i64] - no,
        "2262-04-12" - [2262i64, 4i64, 12i64, 0i64, 0i64, 0i64, 0i64] - no,
        "year 2^63-1" - [int64.max_int64, 1i64, 1i64, 0i64, 0i64, 0i64, 0i64]
            - no,
        "year -2^63" - [int64.min_int64, 12i64, 31i64, 23i64, 59i64, 59i64,
            0i64] - no
    ],
    list.filter((pred((_ - Is - Want)::in) is semidet :-
            Got = Time(Is),
            not (
                Want = yes(Utc), Got = ev_ok(time(ds_time(Utc, 0i64)))
            ;
                Want = no, NotRep(Got)
            )),
        Times, WrongTimes),
    report_offenders(list.map((func(N - _ - _) = N), WrongTimes), !IO),
    check("[LTIM.14.2] calendar.time at the ends of the Time range",
        ( if WrongTimes = [] then yes else no ), !T, !IO),
    check("[LTIM.14.2] calendar.date(2262^63-1, 1, 1) is NOT_REPRESENTABLE",
        ( if NotRep(Date([int64.max_int64, 1i64, 1i64])) then yes else no ),
        !T, !IO).

    % [LTIM.8.2.4]: `::String` writes the wall clock at the value's offset
    % from the local split, never from `UtcNs + OffsetNs`, which passes int64
    % within |offset| of either end. libds's
    % `test_ltim_8_2_4__render_at_the_range_ends`, case for case, through
    % `ds.format.render_iso8601` as `time_to_string` calls it.
    %
:- pred test_ltim_8_2_4_range_ends(tally::in, tally::out, io::di, io::uo)
    is det.

test_ltim_8_2_4_range_ends(!T, !IO) :-
    Cases = [
        {-9223362000000000000i64, -28800000000000i64,
            "1677-09-20T19:00:00-08:00"},
        {9223358400000000000i64, 32400000000000i64,
            "2262-04-12T05:00:00+09:00"},
        {int64.min_int64, -28800000000000i64,
            "1677-09-20T16:12:43.145224192-08:00"}
    ],
    list.foldl2(check_render_iso8601, Cases, !T, !IO).

:- pred check_render_iso8601({int64, int64, string}::in, tally::in,
    tally::out, io::di, io::uo) is det.

check_render_iso8601({Utc, Off, Want}, !T, !IO) :-
    Got = render_iso8601(Utc, Off),
    check_quiet("[LTIM.8.2.4] range end " ++ Want,
        ( if Got = Want then yes else no ), Got, Want, !T, !IO).

    % [LTIM.1.2.2]: the Date range, days
    % -106751 (1677-09-22) through 106751 (2262-04-11), held at each place
    % `ds.eval` makes or reads a `Date` -- libds's `test_ltim_1_2_2__date_range`,
    % case for case:
    %   - `calendar.date` (`ltim_14_2_calendar_date`): a calendar day outside
    %     is NOT_REPRESENTABLE ([LTIM.14.2]);
    %   - `::String` (`time_to_string`): a day outside is NOT_REPRESENTABLE;
    %   - `add_months` on a `Date` (`ltim_4_3_shift`): a result outside is
    %     NOT_REPRESENTABLE;
    %   - `add_months` on a `Time` is NOT held to it: a `Time` on 1677-09-21,
    %     whose UTC day is -106752, still shifts.
    %
:- pred test_ltim_1_2_2_date_range(tally::in, tally::out, io::di, io::uo)
    is det.

test_ltim_1_2_2_date_range(!T, !IO) :-
    ToDate = (func(Y, M, D) = Outcome :-
        eval(e_call(fn_calendar_date, [e_lit(int(Y)), e_lit(int(M)),
            e_lit(int(D))]), ectx, Outcome)),
    check("[LTIM.1.2.2] calendar.date(2262, 4, 12) is NOT_REPRESENTABLE",
        ( if ToDate(2262i64, 4i64, 12i64) = ev_fault(rf_not_representable)
          then yes else no ), !T, !IO),
    check("[LTIM.1.2.2] calendar.date(1677, 9, 21) is NOT_REPRESENTABLE",
        ( if ToDate(1677i64, 9i64, 21i64) = ev_fault(rf_not_representable)
          then yes else no ), !T, !IO),
    check("[LTIM.1.2.2] calendar.date(2262, 4, 11) is the last Date",
        ( if ToDate(2262i64, 4i64, 11i64) = ev_ok(int(106751i64))
          then yes else no ), !T, !IO),
    check("[LTIM.1.2.2] calendar.date(1677, 9, 22) is the first Date",
        ( if ToDate(1677i64, 9i64, 22i64) = ev_ok(int(-106751i64))
          then yes else no ), !T, !IO),
    Render = (func(D) = Outcome :-
        eval(e_call(fn_to_string, [e_lit(int(D))]), ectx, Outcome)),
    check("[LTIM.1.2.2] the last Date renders 2262-04-11",
        ( if Render(106751i64) = ev_ok(text("2262-04-11")) then yes else no ),
        !T, !IO),
    check("[LTIM.1.2.2] the first Date renders 1677-09-22",
        ( if Render(-106751i64) = ev_ok(text("1677-09-22")) then yes else no ),
        !T, !IO),
    check("[LTIM.1.2.2] day 106752 does not render: NOT_REPRESENTABLE",
        ( if Render(106752i64) = ev_fault(rf_not_representable)
          then yes else no ), !T, !IO),
    Shift = (func(D, N) = Outcome :-
        eval(e_call(fn_add_months, [e_lit(int(D)), e_lit(int(N))]), ectx,
            Outcome)),
    check("[LTIM.1.2.2] add_months(2262-04-11, 1) is NOT_REPRESENTABLE",
        ( if Shift(106751i64, 1i64) = ev_fault(rf_not_representable)
          then yes else no ), !T, !IO),
    check("[LTIM.1.2.2] add_months(1677-09-22, -1) is NOT_REPRESENTABLE",
        ( if Shift(-106751i64, -1i64) = ev_fault(rf_not_representable)
          then yes else no ), !T, !IO),
    check("[LTIM.1.2.2] add_months(2262-04-11, -1) is 2262-03-11",
        ( if Shift(106751i64, -1i64) = ev_ok(int(106720i64)) then yes else no ),
        !T, !IO),
    check("[LTIM.1.2.2] add_months(1677-09-22, 1) is 1677-10-22",
        ( if Shift(-106751i64, 1i64) = ev_ok(int(-106721i64)) then yes else no ),
        !T, !IO),
    Day = 86400000000000i64,
    Early = int64.min_int64 + 54000000000000i64,    % 1677-09-21T15:12:43Z
    check("[LTIM.1.2.2] add_months on a Time of 1677-09-21 is not held to the "
            ++ "Date range",
        ( if
            eval(e_call(fn_add_months, [e_lit(time(ds_time(Early, 0i64))),
                e_lit(int(1i64))]), ectx, ev_ok(time(Shifted))),
            utc_ns(Shifted) = Early + 30i64 * Day
          then yes else no ), !T, !IO).

    % A `Time` at a non-zero offset needs `local()` and a zone's rows.
    % `::String` writes the wall clock at the value's offset, then `+hh:mm`
    % or `-hh:mm`, and a fraction only when it is not zero ([LTIM.8.2.4]).
    % libds's `test_iso8601_render_at_an_offset`, case for case.
    %
:- pred test_iso8601_at_an_offset(tally::in, tally::out, io::di, io::uo)
    is det.

test_iso8601_at_an_offset(!T, !IO) :-
    WithTz = two_zones,
    Iso = (func(Instant, Zone) = Outcome :-
        eval(e_call(fn_to_string, [
            e_call(fn_local, [e_lit(time(ds_time(Instant, 0i64))),
                e_lit(text(Zone))]),
            e_lit(text("iso8601"))]), WithTz, Outcome)),
    list.foldl2(
        ( pred({Instant, Zone, Want}::in, T0::in, T1::out,
                IO0::di, IO1::uo) is det :-
            check("[LTIM.8.2.4] ::String writes " ++ Want,
                ( if Iso(Instant, Zone) = ev_ok(text(Want)) then yes else no ),
                T0, T1, IO0, IO1)),
        [{1700000000000000000i64, "America/Los_Angeles",
            "2023-11-14T14:13:20-08:00"},
         {1700000000000000000i64, "Asia/Tokyo", "2023-11-15T07:13:20+09:00"},
         {1700000000500000000i64, "Asia/Tokyo",
            "2023-11-15T07:13:20.5+09:00"},
         {1700000000000000000i64, "UTC", "2023-11-14T22:13:20Z"}],
        !T, !IO).

    % A live clock moves by the wall time it is shown, and only
    % forward. Real readings, since nothing outside ds.chrono can make one.
    %
:- pred test_live_clock(instant::in, tally::in, tally::out, io::di, io::uo)
    is det.

test_live_clock(I0, !T, !IO) :-
    read_wall_clock(R0, !IO),
    Live = init_clock(I0),
    check("clock_observe FAILS on a mock clock",
        ( if clock_to_mock(Live, Mock), clock_observe(R0, Mock, _)
          then no else yes ),
        !T, !IO),
    check("[NLFC.5.4] live -> mock is refused once an input is consumed",
        ( if clock_sample(step_input, _, Live, Consumed),
             clock_to_mock(Consumed, _)
          then no else yes ),
        !T, !IO),
    % A pump's sample closes the switch too, with no input: the mock clock
    % would start at 0, below it.
    check("[NLFC.5.4] live -> mock is refused after a pump's sample, with no "
        ++ "input",
        ( if clock_sample(step_pump, _, Live, Pumped),
             clock_to_mock(Pumped, _)
          then no else yes ),
        !T, !IO),
    check("[NLFC.5.4] and allowed before any sample",
        ( if clock_to_mock(Live, _) then yes else no ), !T, !IO),
    ( if clock_observe(R0, Live, Anchored) then
        check("the first reading anchors a live clock where it stands",
            ( if clock_source_now(Anchored) = I0 then yes else no ), !T, !IO),
        check("[NTST.3.3] an observation is not a sample",
            ( if clock_wall(Anchored) = no then yes else no ), !T, !IO),
        clock_sample(step_pump, _, Anchored, Sampled),
        check("[LTIM.2.8.3] a sample of a live clock holds a wall value",
            ( if clock_wall(Sampled) = yes(_) then yes else no ), !T, !IO),
        % Two nanosecond reads can still agree on a coarse platform clock, so
        % wait for it to turn, bounded so a clock that never moves fails the
        % next check rather than hanging the suite.
        next_reading(R0, 100000000, R1, !IO),
        ( if clock_observe(R1, Anchored, Moved) then
            check("a later reading moves a live clock forward",
                ( if before(I0, clock_source_now(Moved)) then yes else no ),
                !T, !IO),
            check("an earlier reading never moves it back",
                ( if clock_observe(R0, Moved, Back),
                     clock_source_now(Back) = clock_source_now(Moved)
                  then yes else no ), !T, !IO)
        else
            check("a live clock observes a second reading", no, !T, !IO)
        )
    else
        check("clock_observe works on a live clock", no, !T, !IO)
    ).

:- pred next_reading(wall_reading::in, int::in, wall_reading::out,
    io::di, io::uo) is det.

next_reading(R0, Tries, R, !IO) :-
    read_wall_clock(R1, !IO),
    ( if R1 = R0, Tries > 0 then
        next_reading(R0, Tries - 1, R, !IO)
    else
        R = R1
    ).

%-----------------------------------------------------------------------------%
% ds.rules -- the central claim: compare/3 IS the firing order
%-----------------------------------------------------------------------------%

    % A terminal ordinal. `source_index/2` is `semidet` on N >= 0.
:- func sidx_of(int) = source_index.

sidx_of(N) = S :-
    ( if source_index(N, S0) then
        S = S0
    else
        unexpected($pred, "terminal ordinal")
    ).

:- pred test_order_key(tally::in, tally::out, io::di, io::uo) is det.

test_order_key(!T, !IO) :-
    First = order_key(sidx_of(0), make_timetag(9000u64)),
    Second = order_key(sidx_of(1), make_timetag(1u64)),
    Third = order_key(sidx_of(2), make_timetag(1u64)),

    % The ordinal dominates the timetag: an earlier rule in source order fires
    % before a later one activated at any earlier moment.
    check("an earlier ordinal fires first even with a much later timetag",
        ( if compare((<), First, Second) then yes else no ), !T, !IO),
    check("and ordinals order transitively",
        ( if compare((<), Second, Third) then yes else no ), !T, !IO),

    % Within one rule, earlier timetag first [LDET.5.5]. The timetag orders
    % activations of a single rule and nothing across rules.
    Early = order_key(sidx_of(1), make_timetag(5u64)),
    Late  = order_key(sidx_of(1), make_timetag(6u64)),
    check("within one rule, earlier timetag fires first",
        ( if compare((<), Early, Late) then yes else no ), !T, !IO),

    % A duplicate key is a duplicate timetag within one rule, since the
    % ordinal is fixed per rule.
    check("equal ordinal and timetag compare equal (so a map rejects the dup)",
        ( if compare((=), Early, order_key(sidx_of(1), make_timetag(5u64)))
          then yes else no ), !T, !IO),

    check("no_rate_limit is not rate limited",
        ( if rate_limited(no_rate_limit) then no else yes ), !T, !IO),
    check("a cooldown makes it rate limited",
        ( if rate_limited(rate_config(yes(duration_from_ns(1u64))))
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%
% ds.rate -- the key's identity is the thing under test
%-----------------------------------------------------------------------------%

:- pred test_rate(tally::in, tally::out, io::di, io::uo) is det.

test_rate(!T, !IO) :-
    intern("1", One, init_interns, IT1),
    intern("a", A, IT1, IT2),
    intern("rule", Rule, IT2, IT),

    % [RLOW.4.6.2.1]'s identity: pairs that must be two keys, since a wrongly
    % suppressed firing produces no output, beside the controls that must
    % stay one.
    check("integer 1, string \"1\" and true are three keys",
        ( if
            K1 = activation_key(IT, [int(1i64)]),
            KS = activation_key(IT, [str(One)]),
            KB = activation_key(IT, [bool(yes)]),
            K1 \= KS, K1 \= KB, KS \= KB
          then yes else no ), !T, !IO),
    check("floats differing in the seventh decimal are two keys",
        ( if activation_key(IT, [float(1.0000001)]) \=
             activation_key(IT, [float(1.0000002)])
          then yes else no ), !T, !IO),
    check("floats above 1e15 are two keys",
        ( if activation_key(IT, [float(1.0e16)]) \=
             activation_key(IT, [float(2.0e16)])
          then yes else no ), !T, !IO),
    check("a string holding 0x01 is not two fields",
        ( if activation_key(IT, [text("a\x01\b")]) \=
             activation_key(IT, [text("a"), text("b")])
          then yes else no ), !T, !IO),
    Long = string.duplicate_char('x', 600),
    check("keys differing only after byte 511 are two keys",
        ( if activation_key(IT, [text(Long ++ "a")]) \=
             activation_key(IT, [text(Long ++ "b")])
          then yes else no ), !T, !IO),
    check("null is not the empty string",
        ( if activation_key(IT, [int(1i64), null, int(2i64)]) \=
             activation_key(IT, [int(1i64), text(""), int(2i64)])
          then yes else no ), !T, !IO),

    % The controls: equal values of one representation are one key.
    check("0.0 and -0.0 are one key",
        ( if activation_key(IT, [float(0.0)]) =
             activation_key(IT, [float(-0.0)])
          then yes else no ), !T, !IO),
    check("an interned and a computed \"1\" are one key",
        ( if activation_key(IT, [str(One)]) = activation_key(IT, [text("1")])
          then yes else no ), !T, !IO),
    check("an empty argument list is the rule-global key",
        ( if activation_key(IT, []) = [] then yes else no ), !T, !IO),

    % -- the gate ------------------------------------------------------------
    %
    % `rate_allow(rule, key..., cooldown_ns)`, as the compiler emits it.
    Cool30 = [str(Rule), str(A), int(30i64)],

    gate_run(IT, Cool30, [0u64, 10u64, 30u64], CoolVerdicts),
    check("cooldown fires, suppresses inside the window, fires at the edge",
        ( if CoolVerdicts = [rv_fire, rv_cool_suppress, rv_fire]
          then yes else no ), !T, !IO),

    % A suppressed attempt does not move the window: the fire at 0 still
    % governs at 29, and 30 is its edge.
    gate_run(IT, Cool30, [0u64, 29u64, 30u64], HeldVerdicts),
    check("a suppressed attempt leaves the window where the last fire put it",
        ( if HeldVerdicts = [rv_fire, rv_cool_suppress, rv_fire]
          then yes else no ), !T, !IO),

    % No keys at all is the rule-global gate ([LCDB.3.3.3]'s empty key), not
    % a malformed call.
    gate_run(IT, [str(Rule), int(30i64)], [0u64, 1u64], RuleGlobal),
    check("a name and a window alone is the rule-global gate",
        ( if RuleGlobal = [rv_fire, rv_cool_suppress] then yes else no ),
        !T, !IO),

    % Every abnormal shape fires. A gate that cannot decide must not suppress:
    % a wrongly suppressed firing emits nothing at all, so it cannot be seen.
    gate_run(IT, [str(Rule), str(A), int(0i64)], [0u64, 0u64], NoWindow),
    check("a zero window always fires",
        ( if NoWindow = [rv_fire, rv_fire] then yes else no ), !T, !IO),
    gate_run(IT, [int(7i64), str(A), int(30i64)], [0u64, 1u64], NoName),
    check("a non-string rule name fails OPEN",
        ( if NoName = [rv_fire, rv_fire] then yes else no ), !T, !IO),
    gate_run(IT, [str(Rule)], [0u64, 1u64], TooFew),
    check("too few arguments fails OPEN",
        ( if TooFew = [rv_fire, rv_fire] then yes else no ), !T, !IO),

    % The key separates buckets: two activations differing in a key value do
    % not share a cooldown.
    gate_two_keys(IT, Verdict2),
    check("a different key value gets its own window",
        ( if Verdict2 = rv_fire then yes else no ), !T, !IO),

    list.foldl2(rgate_vector, rgate_corpus, !T, !IO).

%-----------------------------------------------------------------------------%
% `formal/k/rgate.k`'s vectors, run through the transcription
%-----------------------------------------------------------------------------%
%
% The model's cooldown vectors, read from its `.expected` files rather than
% re-derived: `test_rate` above asserts what this runtime does, and these
% what the cooldown clauses require as a K definition states them, so the
% model's files and this table change together or one of them fails.
%
:- type rgate_vector
    --->    rgate_vector(
                rgv_name  :: string,
                rgv_cool  :: int,
                rgv_steps :: list({int, uint64}),
                            % `act "R" <key>` at an instant, in schedule order.
                            % The model's `tick N` is folded in: these are
                            % absolute instants, which is what the gate reads.
                rgv_model :: list(rate_verdict),
                            % Verbatim from the `.expected` file beside the
                            % `.prog`, decoded from `<tag>:R:K@t|` form.
                rgv_agrees :: bool
                            % Whether this runtime is expected to agree with
                            % the model. A `no` row is a filed divergence, and
                            % fails if it starts agreeing.
            ).

:- func rgate_corpus = list(rgate_vector).

rgate_corpus = [
    rgate_vector("cool_first", 10, [{1, 0u64}],
        [rv_fire], yes),
    rgate_vector("cool_perkey", 10, [{1, 0u64}, {2, 0u64}],
        [rv_fire, rv_fire], yes),
    rgate_vector("cool_refire", 10, [{1, 0u64}, {1, 10u64}],
        [rv_fire, rv_fire], yes),
    rgate_vector("cool_suppress", 10, [{1, 0u64}, {1, 5u64}],
        [rv_fire, rv_cool_suppress], yes)
].

:- pred rgate_vector(rgate_vector::in, tally::in, tally::out,
                     io::di, io::uo) is det.

rgate_vector(V, !T, !IO) :-
    intern("R", Rule, init_interns, IT),
    list.map_foldl(rgate_step(IT, Rule, V ^ rgv_cool),
        V ^ rgv_steps, Actual, init_rate_table, _),
    Agreed = ( if Actual = V ^ rgv_model then yes else no ),
    (
        V ^ rgv_agrees = yes,
        Name = "rgate." ++ V ^ rgv_name ++ ": this runtime agrees with the model"
    ;
        V ^ rgv_agrees = no,
        Name = "rgate." ++ V ^ rgv_name ++ ": this runtime DIVERGES, as filed"
    ),
    ( if Agreed = V ^ rgv_agrees then
        Result = yes
    else
        Result = no,
        io.format("  note: rgate.%s model=%s actual=%s\n",
            [s(V ^ rgv_name), s(string(V ^ rgv_model)), s(string(Actual))], !IO)
    ),
    check(Name, Result, !T, !IO).

    % One `act "R" <key>` at an instant. The activation key is an integer in the
    % model and a key VALUE in the guard's argument list; `int(K)` is the same
    % thing under this encoder, which renders an integer as its decimal.
    %
:- pred rgate_step(intern_table::in, intern_ref::in, int::in,
                   {int, uint64}::in, rate_verdict::out,
                   rate_table::in, rate_table::out) is det.

rgate_step(IT, Rule, Cool, {Key, Ns}, Verdict, !Table) :-
    rate_gate([str(Rule), int(int64.from_int(Key)), int(int64.from_int(Cool))],
        IT, from_ns(Ns), Verdict, !Table).

    % Drive one gate through a series of instants, collecting the verdicts.
    %
:- pred gate_run(intern_table::in, list(ds_value)::in, list(uint64)::in,
                 list(rate_verdict)::out) is det.

gate_run(IT, Args, Times, Verdicts) :-
    list.map_foldl(gate_at(IT, Args), Times, Verdicts, init_rate_table, _).

:- pred gate_at(intern_table::in, list(ds_value)::in, uint64::in,
                rate_verdict::out, rate_table::in, rate_table::out) is det.

gate_at(IT, Args, Ns, Verdict, !Table) :-
    rate_gate(Args, IT, from_ns(Ns), Verdict, !Table).

:- pred gate_two_keys(intern_table::in, rate_verdict::out) is det.

gate_two_keys(IT, Verdict) :-
    intern("k1", K1, IT, IT1),
    intern("k2", K2, IT1, IT2),
    intern("r", R, IT2, IT3),
    rate_gate([str(R), str(K1), int(30i64)], IT3, from_ns(0u64), _,
        init_rate_table, T1),
    rate_gate([str(R), str(K2), int(30i64)], IT3, from_ns(1u64), Verdict,
        T1, _).

%-----------------------------------------------------------------------------%
% ds.schema -- key width falls out of which slots are the key
%-----------------------------------------------------------------------------%

:- pred test_schema(tally::in, tally::out, io::di, io::uo) is det.

test_schema(!T, !IO) :-
    check("a ttl schema has NO key width",
        ( if key_width(lc_ttl([], duration_from_ns(1u64))) = no
          then yes else no ), !T, !IO),

    Mut = lslot(role_mutable),
    Key = lslot(role_key),

    check("no key slots -> singleton",
        ( if key_width(lc_logical([Mut, Mut], no)) = yes(kw_singleton)
          then yes else no ), !T, !IO),
    check("one key slot -> entity",
        ( if key_width(lc_logical([Key, Mut], no)) = yes(kw_entity)
          then yes else no ), !T, !IO),
    check("two of three -> composite",
        ( if key_width(lc_logical([Key, Key, Mut], no)) = yes(kw_composite)
          then yes else no ), !T, !IO),
    check("all key slots -> relation",
        ( if key_width(lc_logical([Key, Key], no)) = yes(kw_relation)
          then yes else no ), !T, !IO),

    % One slot, and it is the key: both "key = one slot" (entity) and "key =
    % all slots" (relation) under [LFAC.1.7.2]. The two describe the same
    % behaviour; only the diagnostic label differs ([RDSC.6.8.4]), and this
    % runtime answers `kw_entity`, the clause's listing order.
    check("a single key slot alone -> entity (the overlapping case)",
        ( if key_width(lc_logical([Key], no)) = yes(kw_entity)
          then yes else no ), !T, !IO).

    % A logical slot with the given role, everything else fixed. Enough for
    % key_width, which reads only the role.
:- func lslot(identity_role) = logical_slot.

lslot(Role) =
    logical_slot(
        slot_common(make_intern_ref(1u32), k_int, S, non_null, no, no, no, unbounded, no),
        Role, exact) :-
    ( if slot_index(0u32, S0) then S = S0 else unexpected($pred, "slot 0") ).

%-----------------------------------------------------------------------------%
% ds.fact -- the contested tolerance boundary
%-----------------------------------------------------------------------------%

:- pred test_fact(tally::in, tally::out, io::di, io::uo) is det.

test_fact(!T, !IO) :-
    check("exact: equal values are unchanged",
        ( if slot_unchanged(exact, int(5i64), int(5i64)) then yes else no ),
        !T, !IO),
    check("exact: different values are a change",
        ( if slot_unchanged(exact, int(5i64), int(6i64)) then no else yes ),
        !T, !IO),

    % [LFAC.2.5.1]: a delta of exactly the tolerance is a no-op.
    check("tolerance boundary: delta == T is a NO-OP",
        ( if slot_unchanged(within(0.5), float(20.0), float(20.5))
          then yes else no ), !T, !IO),
    check("delta just over T is a change",
        ( if slot_unchanged(within(0.5), float(20.0), float(20.6))
          then no else yes ), !T, !IO),

    % Under strict `<`, `tolerance 0` makes an identical re-assert a meaningful
    % change, defeating the purpose of [LFAC.2.5.1].
    check("tolerance 0 still suppresses an IDENTICAL re-assert",
        ( if slot_unchanged(within(0.0), float(1.5), float(1.5))
          then yes else no ), !T, !IO),

    % [LFAC.2.5.1]: equal iff exactly equal or `|delta| <= T`, so two equal
    % infinities are unchanged under any tolerance, though their delta is
    % NaN. Infinities of opposite sign differ by an infinity, which a finite
    % tolerance does not cover.
    % @spec [LFAC.2.5.1]
    check("[LFAC.2.5.1] +inf re-asserted over +inf under tolerance 0.5 is "
            ++ "unchanged",
        ( if slot_unchanged(within(0.5), float(float.infinity),
                float(float.infinity))
          then yes else no ), !T, !IO),
    check("[LFAC.2.5.1] -inf re-asserted over -inf under tolerance 0.5 is "
            ++ "unchanged",
        ( if slot_unchanged(within(0.5), float(-float.infinity),
                float(-float.infinity))
          then yes else no ), !T, !IO),
    check("[LFAC.2.5.1] -inf re-asserted over +inf under tolerance 0.5 is a "
            ++ "change",
        ( if slot_unchanged(within(0.5), float(float.infinity),
                float(-float.infinity))
          then no else yes ), !T, !IO),

    % Tolerance is legal only on Int/Float; other kinds compare exactly.
    check("a declared tolerance does not loosen string comparison",
        ( if slot_unchanged(within(9.0), str(make_intern_ref(1u32)),
                            str(make_intern_ref(2u32)))
          then no else yes ), !T, !IO),

    check("null is unchanged from null",
        ( if slot_unchanged(within(1.0), null, null) then yes else no ),
        !T, !IO).

%-----------------------------------------------------------------------------%
% ds.fault
%-----------------------------------------------------------------------------%

:- pred test_fault(tally::in, tally::out, io::di, io::uo) is det.

test_fault(!T, !IO) :-
    check("a clause id parses",
        ( if clause_id("RDSC.8.7", _) then yes else no ), !T, !IO),
    % The corpus uses 4a / 4b for sections inserted after the fact; a
    % numeric-only check would reject real citations.
    check("an alphanumeric component parses (RDSC.4a.3)",
        ( if clause_id("RDSC.4a.3", _) then yes else no ), !T, !IO),
    check("a bare document is not a citation",
        ( if clause_id("RDSC", _) then no else yes ), !T, !IO),
    check("a lowercase prefix is rejected",
        ( if clause_id("rdsc.8.7", _) then no else yes ), !T, !IO),
    check("an empty component is rejected",
        ( if clause_id("RDSC..7", _) then no else yes ), !T, !IO),
    check("clause_id_string round-trips",
        ( if clause_id("LFAC.1.7.5", C),
             clause_id_string(C) = "LFAC.1.7.5"
          then yes else no ), !T, !IO),

    % A bounds refusal changes nothing and halts nothing; the class decides
    % which errors halt.
    check("a contract breach is rejected, not fatal (RTCT.7.2)",
        ( if disposition(ee_contract_breach(cap_wm_max)) = rejected
          then yes else no ), !T, !IO),
    % The class decides the disposition. A clean type mismatch is the
    % artefact lying.
    check("an EngineError-class expression fault is latched",
        ( if disposition(ee_expr_fault(rf_artefact_lied)) = latched
          then yes else no ), !T, !IO),
    check("a ComputationError-class one is reported, not latched",
        ( if disposition(ee_expr_fault(rf_div_zero)) = reported
          then yes else no ), !T, !IO),
    check("and a TypeError-class one is reported -- data, not the engine",
        ( if disposition(ee_expr_fault(rf_type_error)) = reported
          then yes else no ), !T, !IO),
    check("a duplicate order key is latched -- determinism is lost",
        ( if disposition(ee_duplicate_order_key) = latched then yes else no ),
        !T, !IO).

%-----------------------------------------------------------------------------%
% ds.action
%-----------------------------------------------------------------------------%

:- pred test_action(tally::in, tally::out, io::di, io::uo) is det.

test_action(!T, !IO) :-
    % Kwargs keep wire order, which is the compiler's: it sorts a call's
    % kwargs by name ([RLOW.7.3.1]) and neither runtime sorts again. Sorting
    % here would hide an artefact the compiler failed to sort.
    K = make_kwargs(["zulu" - e_now, "alpha" - e_now]),
    check("kwargs keep the order they were built in",
        ( if kwarg_list(K) = [N1 - _, _], N1 = "zulu" then yes else no ),
        !T, !IO),
    check("so two source orders are NOT equal -- the difference survives",
        ( if K = make_kwargs(["alpha" - e_now, "zulu" - e_now])
          then no else yes ), !T, !IO),

    % One verb degrades, two abort, the rest substitute: a malformed log line
    % is worth emitting and a malformed outbound call is not.
    check("log degrades on an argument that cannot be evaluated",
        ( if arg_error_policy(a_log(log_info, e_now)) = degrade
          then yes else no ), !T, !IO),
    % The service is a bare name with no module qualification: `ActionCall`
    % carries `service` as a string and no `module_id`. Only `ServiceDef` has one.
    check("call ABORTS",
        ( if arg_error_policy(a_call(make_intern_ref(1u32),
                                     correlated(make_intern_ref(2u32)),
                                     make_kwargs([]), no))
                = abort
          then yes else no ), !T, !IO),
    check("emit substitutes",
        ( if arg_error_policy(a_emit(make_schema_id(1u32), [], plain, no))
                = substitute
          then yes else no ), !T, !IO),

    % DEBUG = 0 .. CRITICAL = 4, with no sentinel: zero is a level.
    check("log level 0 is DEBUG, not a sentinel",
        ( if log_level(0i64, log_debug) then yes else no ), !T, !IO),
    check("log level 4 is CRITICAL",
        ( if log_level(4i64, log_critical) then yes else no ), !T, !IO),
    check("log level 5 is refused -- the range ends at CRITICAL",
        ( if log_level(5i64, _) then no else yes ), !T, !IO),
    check("a negative level is refused",
        ( if log_level(-1i64, _) then no else yes ), !T, !IO).

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% Byte-buffer helpers
%-----------------------------------------------------------------------------%

:- func from_bytes(list(int)) = bitmap.

from_bytes(Bs) = BM :-
    BM0 = bitmap.init(list.length(Bs) * 8),
    fill_bytes(0, Bs, BM0, BM).

:- pred fill_bytes(int::in, list(int)::in,
                   bitmap::bitmap_di, bitmap::bitmap_uo) is det.

fill_bytes(_, [], !BM).
fill_bytes(I, [B | Bs], !BM) :-
    bitmap.set_uint8(I, uint8.cast_from_int(B), !BM),
    fill_bytes(I + 1, Bs, !BM).

:- func reader_over(list(int)) = reader.

reader_over(Bs) = init_reader(from_bytes(Bs)).

    % An artefact the suite built or edited, sealed and loaded as a bitmap.
    %
:- func sealed(list(int)) = bitmap.

sealed(Bs) = from_bytes(seal(Bs)).

    % [RDSC.3.6] -- seal an artefact the way the compiler does: zero the
    % header's `dsc_sha256` in place, hash the whole artefact, and write the
    % digest into those 32 bytes. `load_dsc` refuses an artefact whose hash
    % does not match, so every artefact a test builds or edits is re-sealed.
    %
    % Located by walking the header's fields, not as
    % `ds.dsc.verify_self_hash` finds it, so the two locate the field
    % independently. Bytes with no DscHeader to walk come back unchanged.
    %
:- func seal(list(int)) = list(int).

seal(Bs) = Sealed :-
    ( if seal_field_offset(array.from_list(Bs), Off) then
        Zeroed = put_range(Off, list.duplicate(32, 0), Bs),
        Digest = sha256(list.map(uint8.cast_from_int, Zeroed)),
        Sealed = put_range(Off, list.map(uint8.cast_to_int, Digest), Zeroed)
    else
        Sealed = Bs
    ).

    % The offset of the 32 `dsc_sha256` bytes: the first atom is DscHeader (field
    % 263), and field 7 of its body, length-delimited and 32 long.
    %
:- pred seal_field_offset(array(int)::in, int::out) is semidet.

seal_field_offset(A, Off) :-
    array.size(A) > 0,
    A ^ elem(0) = 0x0A,
    varint_at(A, 1, _OuterLen, P1),
    varint_at(A, P1, Tag, P2),
    Tag = (263 << 3) \/ 2,
    varint_at(A, P2, BodyLen, Start),
    End = Start + BodyLen,
    End =< array.size(A),
    hash_field_in(A, Start, End, Off).

:- pred hash_field_in(array(int)::in, int::in, int::in, int::out) is semidet.

hash_field_in(A, Pos, End, Off) :-
    Pos < End,
    varint_at(A, Pos, Key, P1),
    Wire = Key /\ 7,
    ( if Key >> 3 = 7, Wire = 2 then
        varint_at(A, P1, Len, Off),
        Len = 32,
        Off + 32 =< End
    else
        seal_skip_value(A, Wire, P1, Next),
        hash_field_in(A, Next, End, Off)
    ).

:- pred seal_skip_value(array(int)::in, int::in, int::in, int::out) is semidet.

seal_skip_value(A, Wire, P, Next) :-
    ( if Wire = 0 then
        varint_at(A, P, _, Next)
    else if Wire = 1 then
        Next = P + 8
    else if Wire = 2 then
        varint_at(A, P, Len, Q),
        Next = Q + Len
    else
        Wire = 5,
        Next = P + 4
    ).

:- pred varint_at(array(int)::in, int::in, int::out, int::out) is semidet.

varint_at(A, P, V, Next) :-
    varint_loop(A, P, 0, 0, V, Next).

:- pred varint_loop(array(int)::in, int::in, int::in, int::in,
                    int::out, int::out) is semidet.

varint_loop(A, P, Shift, Acc, V, Next) :-
    P >= 0,
    P < array.size(A),
    Shift < 63,
    B = A ^ elem(P),
    Acc1 = Acc \/ ((B /\ 0x7F) << Shift),
    ( if B /\ 0x80 = 0 then
        V = Acc1,
        Next = P + 1
    else
        varint_loop(A, P + 1, Shift + 7, Acc1, V, Next)
    ).

    % `Bs` with the bytes from `Off` on replaced by `New`, length unchanged.
    %
:- func put_range(int, list(int), list(int)) = list(int).

put_range(Off, New, Bs) = Before ++ New ++ After :-
    list.det_split_list(Off, Bs, Before, Rest),
    list.det_split_list(list.length(New), Rest, _, After).

%-----------------------------------------------------------------------------%
% ds.atom -- the registry
%-----------------------------------------------------------------------------%

:- pred test_registry(tally::in, tally::out, io::di, io::uo) is det.

test_registry(!T, !IO) :-
    check("263 is DscHeader",
        ( if atom_of_field(263u32, at_dsc_header) then yes else no ), !T, !IO),
    check("258 is StreamHeader",
        ( if atom_of_field(258u32, at_stream_header) then yes else no ), !T, !IO),
    check("1 is FactAssert",
        ( if atom_of_field(1u32, at_fact_assert) then yes else no ), !T, !IO),
    check("field number round-trips",
        ( if atom_field(at_terminal_node) = 270u32 then yes else no ), !T, !IO),

    % An atom is named by its body message, as libds's
    % `ds_rfcs_message_name` and pyds's `AtomKind.message` name it.
    check("atom_message names the body message",
        ( if atom_message(at_fact_assert) = "FactAssert",
             atom_message(at_stream_header) = "StreamHeader",
             atom_message(at_series_backend_ring_buffer) =
                "SeriesBackendRingBuffer"
          then yes else no ), !T, !IO),

    % The constructors and the message rows are two generated blocks of one
    % module. The oneof field is its message in snake case, so each
    % constructor must be `at_` and that spelling.
    Allocated = list.filter_map(
        (func(N) = A is semidet :- atom_of_field(uint32.det_from_int(N), A)),
        1 .. 2047),
    check("every constructor is at_ and its message in snake case",
        ( if Allocated = [_ | _],
             list.all_true(
                (pred(A::in) is semidet :-
                    string(A) = "at_" ++ snake_case(atom_message(A))),
                Allocated)
          then yes else no ), !T, !IO),
    Messages = list.map(atom_message, Allocated),
    check("no two atoms share a message",
        ( if list.same_length(list.sort_and_remove_dups(Messages), Messages)
          then yes else no ), !T, !IO),

    % `atom.proto` reserves 260 and holds 323 out of `Atom.oneof body`
    % (TextNote is deferred, [RFCS.25]), so neither has a registry entry.
    check("260 and 323 are unallocated -- the Seal and TextNote",
        ( if list.all_true(retired_magic, [260u32, 323u32])
          then yes else no ), !T, !IO),

    % `atom.proto` reserves 271-286 and 322.
    check("271-286 and 322 are unallocated, never reissued",
        ( if list.all_true(retired_magic, [271u32, 279u32, 286u32, 322u32])
          then yes else no ), !T, !IO),

    check("an unallocated number is not in the registry",
        ( if atom_of_field(999u32, _) then no else yes ), !T, !IO),

    % OracleEmit and OraclePublish carry one layout in two messages, and are
    % told apart by number, never by a discriminator inside the body.
    check("OracleEmit and OraclePublish are distinct atoms",
        ( if atom_field(at_oracle_emit) = 288u32, atom_field(at_oracle_publish) = 289u32
          then yes else no ), !T, !IO),

    check("only DscHeader opens a Dsc",
        ( if container_of(at_dsc_header, container_dsc) then yes else no ), !T, !IO),
    check("only StreamHeader opens a Stream",
        ( if container_of(at_stream_header, container_stream) then yes else no ),
        !T, !IO),
    check("SchemaDef opens neither, though it is legal in both containers",
        ( if container_of(at_schema_def, _) then no else yes ), !T, !IO).

    % `FactAssert` -> `fact_assert`: an underscore before each capital but the
    % first, then lower case. `extract_atoms.py`'s `snake`, which the generator
    % holds every oneof field to.
    %
:- func snake_case(string) = string.

snake_case(S) = string.from_char_list(list.reverse(
    list.foldl(
        (func(C, Acc) =
            ( if char.is_upper(C), Acc = [_ | _]
              then [char.to_lower(C), '_' | Acc]
              else [char.to_lower(C) | Acc] )),
        string.to_char_list(S), []))).

%-----------------------------------------------------------------------------%
% ds.wire -- varints
%-----------------------------------------------------------------------------%

:- pred test_varint(tally::in, tally::out, io::di, io::uo) is det.

test_varint(!T, !IO) :-
    check("single-byte varint",
        ( if read_varint(ok(0u64), reader_over([0x00]), _) then yes else no ),
        !T, !IO),
    check("varint 1",
        ( if read_varint(ok(1u64), reader_over([0x01]), _) then yes else no ),
        !T, !IO),
    check("two-byte varint 300",
        ( if read_varint(ok(300u64), reader_over([0xAC, 0x02]), _)
          then yes else no ), !T, !IO),

    % The real inner tag from a compiled artefact: 0xBA 0x10 -> 2106 -> field
    % 263, wire type 2 -> DscHeader.
    check("BA 10 decodes to 2106",
        ( if read_varint(ok(2106u64), reader_over([0xBA, 0x10]), _)
          then yes else no ), !T, !IO),
    check("BA 10 is field 263, wire type 2",
        ( if read_tag(ok({263u32, wt_len}), reader_over([0xBA, 0x10]), _)
          then yes else no ), !T, !IO),

    check("a varint running off the end is truncated, not garbage",
        ( if read_varint(error(we_truncated), reader_over([0x80]), _)
          then yes else no ), !T, !IO),
    check("an empty buffer is truncated",
        ( if read_varint(error(we_truncated), reader_over([]), _)
          then yes else no ), !T, !IO),

    % Eleven continuation bytes, refused rather than truncated.
    check("an 11-byte varint is overlong",
        ( if read_varint(error(we_varint_overlong),
                reader_over([0x80, 0x80, 0x80, 0x80, 0x80, 0x80,
                             0x80, 0x80, 0x80, 0x80, 0x01]), _)
          then yes else no ), !T, !IO),

    % Wire types 3 and 4 are the deprecated groups, which the format lacks.
    check("wire type 3 (deprecated group) is refused",
        ( if read_tag(error(we_bad_wire_type(3)), reader_over([0x0B]), _)
          then yes else no ), !T, !IO),

    check("a sub-reader is bounded to its own body",
        ( if read_delimited(ok(Sub), reader_over([0x02, 0xAA, 0xBB, 0xCC]), _),
             remaining(Sub) = 2
          then yes else no ), !T, !IO),
    check("a body longer than the buffer is truncated",
        ( if read_delimited(error(we_truncated),
                reader_over([0x09, 0xAA]), _)
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%
% ds.atom -- the frame walk
%-----------------------------------------------------------------------------%

:- pred test_frames(tally::in, tally::out, io::di, io::uo) is det.

test_frames(!T, !IO) :-
    % A minimal well-formed frame: outer 0A, len 4; inner tag BA 10 (DscHeader),
    % len 1, body 00.
    check("a well-formed frame yields its atom and a bounded body",
        ( if next_frame(fr_ok(F), reader_over([0x0A, 0x04, 0xBA, 0x10,
                                               0x01, 0x00]), _),
             F ^ fr_atom = known(at_dsc_header),
             remaining(F ^ fr_body) = 1
          then yes else no ), !T, !IO),

    check("the walk reaches EOF cleanly on an empty container",
        ( if next_frame(fr_eof, reader_over([]), _) then yes else no ),
        !T, !IO),

    % [RFCS.19.3]: the case a generated protobuf parser accepts silently.
    check("an Atom with no oneof member is REFUSED",
        ( if next_frame(fr_error(ae_empty_atom, _), reader_over([0x0A, 0x00]), _)
          then yes else no ), !T, !IO),

    % The outer frame is container field 1 for every atom.
    check("an outer tag that is not field 1 is refused",
        ( if next_frame(fr_error(ae_bad_outer_tag(2u32), _),
                reader_over([0x12, 0x04, 0xBA, 0x10, 0x01, 0x00]), _)
          then yes else no ), !T, !IO),

    % [RDSC.11.1]: the outer tag is the byte 0x0A, judged before any varint,
    % so a lone 0xFF is no tag still arriving.
    check("a 0xFF where a frame begins is a bad outer tag, not a short varint",
        ( if next_frame(FF, reader_over([0xFF]), _),
             FF = fr_error(FFE, _),
             FFE = ae_bad_outer_tag(_)
          then yes else no ), !T, !IO),
    % The two truncations apart: the frame running past the buffer is the
    % outer's (`ae_wire`), which more bytes complete; the atom's field running
    % past a complete frame is the body's (`ae_body`), which they do not.
    check("a frame cut short at the buffer's end is the outer's truncation",
        ( if next_frame(fr_error(ae_wire(we_truncated), _),
                reader_over([0x0A, 0x05, 0xBA, 0x10]), _)
          then yes else no ), !T, !IO),
    check("a body cut short inside a complete frame is the body's truncation",
        ( if next_frame(fr_error(ae_body(we_truncated), _),
                reader_over([0x0A, 0x03, 0xBA, 0x10, 0x05]), _)
          then yes else no ), !T, !IO),
    check("a field number past 2^32 is refused, not narrowed",
        ( if read_tag(error(we_field_overflow),
                reader_over([0x82, 0x80, 0x80, 0x80, 0x80, 0x01]), _)
          then yes else no ), !T, !IO),

    % The walk frames and judges no number: an unknown one is `unknown`, for
    % the caller to refuse [RFCS.19.3]. Field 999 -> tag 7994 -> BA 3E, and
    % field 100 -> tag 802 -> A2 06.
    check("an unknown number frames as unknown (999)",
        ( if next_frame(fr_ok(F2), reader_over([0x0A, 0x04, 0xBA, 0x3E,
                                                0x01, 0x00]), _),
             F2 ^ fr_atom = unknown(999u32)
          then yes else no ), !T, !IO),
    check("an unknown number frames as unknown (100)",
        ( if next_frame(fr_ok(F3), reader_over([0x0A, 0x04, 0xA2, 0x06,
                                                0x01, 0x00]), _),
             F3 ^ fr_atom = unknown(100u32)
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%
% The real artefact
%-----------------------------------------------------------------------------%
%
% Everything above reads bytes this suite chose. This is a `.dsc` compiled
% from `07_action_verbs.ds`, which exercises every RHS verb.

:- pred test_real_artefact(tally::in, tally::out, io::di, io::uo) is det.

test_real_artefact(!T, !IO) :-
    io.open_binary_input("fixtures/07_action_verbs.dsc", OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, Res, !IO),
        io.close_binary_input(Stream, !IO)
    ;
        OpenRes = error(OpenErr),
        Res = error(OpenErr)
    ),
    (
        Res = ok(BM),
        R0 = init_reader(BM),
        walk(R0, 0, Count, [], RevAtoms, Outcome),
        list.reverse(RevAtoms, Atoms),

        check("the real artefact walks to a clean EOF",
            ( if Outcome = fr_eof then yes else no ), !T, !IO),
        check("it contains frames",
            ( if Count > 0 then yes else no ), !T, !IO),
        check("the first atom is DscHeader, so this is a Dsc",
            ( if Atoms = [known(First) | _], container_of(First, container_dsc)
              then yes else no ), !T, !IO),
        % The registry knows every atom in a real artefact.
        check("the artefact carries no atom this registry does not know",
            ( if list.member(unknown(_), Atoms) then no else yes ), !T, !IO),
        check("a Rete network (a TerminalNode) is known and decoded",
            ( if list.member(known(at_terminal_node), Atoms) then yes else no ),
            !T, !IO),
        io.format("  note: real artefact = %d atoms\n", [i(Count)], !IO),

        % The self-hash, verified against a real artefact ([RDSC.3.6]).
        ( if load_dsc(BM, loaded(P0)) then
            check("the real artefact's dsc_sha256 verifies",
                ( if verify_self_hash(BM, header(P0)) then yes else no ),
                !T, !IO),
            % [RBND.3.1]: a recording carries the header's hash, copied, not a
            % hash of the file as written. On a real artefact the two differ,
            % so a recorder that hashed the file fails the second conjunct.
            check("[RBND.3.1] a recording's dsc_hash is the header's dsc_sha256",
                ( if recording_dsc_hash(P0) = header(P0) ^ dh_sha256,
                     bitmap_bytes(BM, FileBytes),
                     sha256(FileBytes) \= recording_dsc_hash(P0)
                  then yes else no ), !T, !IO),
            % And fails on a tampered one. Flipping one byte of the source
            % echo leaves the header intact and the file a different file.
            ( if flip_a_byte(BM, Tampered) then
                check("...and does NOT verify once a byte is flipped",
                    ( if verify_self_hash(Tampered, header(P0))
                      then no else yes ), !T, !IO),
                % [RDSC.3.6]: and `load_dsc` refuses it.
                check("...and the tampered artefact is refused at load",
                    ( if load_dsc(Tampered, load_failed(ET)),
                         ET ^ le_kind = lek_semantic,
                         clause_id_string(ET ^ le_clause) = "RDSC.3.6"
                      then yes else no ), !T, !IO)
            else
                check("the fixture is long enough to tamper with", no, !T, !IO)
            )
        else
            check("the real artefact loads", no, !T, !IO)
        ),

        true
    ;
        Res = error(E),
        check("fixture is readable: " ++ io.error_message(E), no, !T, !IO)
    ).

:- pred walk(reader::in, int::in, int::out,
             list(atom_ref)::in, list(atom_ref)::out, frame_result::out) is det.

walk(R0, N0, N, Acc0, Acc, Outcome) :-
    next_frame(Result, R0, R1),
    (
        Result = fr_ok(F),
        walk(R1, N0 + 1, N, [F ^ fr_atom | Acc0], Acc, Outcome)
    ;
        Result = fr_eof,
        N = N0, Acc = Acc0, Outcome = fr_eof
    ;
        Result = fr_error(E, Off),
        N = N0, Acc = Acc0, Outcome = fr_error(E, Off)
    ).

    % The encoder's acceptance test: re-framing compiled artefacts must give
    % their bytes back. Three unalike artefacts: 07 is eight verbs in one
    % rule, 50 is 64 atoms including DocString, ServiceDef, SchemaTtl and the
    % synthesised continuation terminals, 51 has no inline actions.
    %
    % The atom bodies are copied verbatim. This covers the two framing
    % levels, the length varints and the inner `oneof` tag.
    %
:- pred test_encoder_roundtrip(tally::in, tally::out, io::di, io::uo) is det.

test_encoder_roundtrip(!T, !IO) :-
    list.foldl2(reframe_fixture,
        ["fixtures/07_action_verbs.dsc",
         "fixtures/50_call_cont.dsc",
         "fixtures/51_after.dsc"], !T, !IO).

:- pred reframe_fixture(string::in, tally::in, tally::out,
                        io::di, io::uo) is det.

reframe_fixture(Path, !T, !IO) :-
    io.open_binary_input(Path, OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, Res, !IO),
        io.close_binary_input(Stream, !IO)
    ;
        OpenRes = error(OpenErr),
        Res = error(OpenErr)
    ),
    (
        Res = ok(BM),
        reframe(init_reader(BM), init_builder, Rebuilt, Outcome),
        Bytes = builder_bytes(Rebuilt),
        check("re-framed BYTE FOR BYTE: " ++ Path,
            ( if Outcome = fr_eof,
                 bitmap_bytes(BM, Original),
                 Bytes = Original
              then yes else no ), !T, !IO),
        ( if bitmap_bytes(BM, Orig), Bytes \= Orig then
            % Only on a mismatch, and it is the first thing wanted: a length
            % varint that is one byte short shows up as a small index, a wrong
            % tag as index 1.
            io.format("  note: %s -- %d bytes vs %d, first diff at %d\n",
                [s(Path), i(list.length(Bytes)), i(list.length(Orig)),
                 i(first_diff(Bytes, Orig, 0))], !IO)
        else
            true
        )
    ;
        Res = error(E),
        check("readable: " ++ Path ++ ": " ++ io.error_message(E), no, !T, !IO)
    ).

    % The recorded-stream writer, read back by this runtime's own decoder:
    % internal consistency, not conformance. It establishes that the atom
    % identities are the ones intended, the framing survives a round trip,
    % the subsetting drops what it should, and a fact body decodes to the
    % values that went in.
    %
:- pred test_rfcs_writer(tally::in, tally::out, io::di, io::uo) is det.

test_rfcs_writer(!T, !IO) :-
    intern("Reading", NameRef, init_interns, IT1),
    intern("kitchen", ZoneRef, IT1, IT2),
    % Interned, not fabricated: `expand` is semidet, so a ref not in the
    % table would make the atom vanish.
    intern("my_rule", RuleRef, IT2, IT),
    Fire = fire_id(make_timetag(9u64), RuleRef),
    Slots = [rslot(0, k_int), rslot(1, k_string)],
    Schema = schema(make_schema_id(7u32), make_schema_name(NameRef),
        lc_logical(Slots, no), no, no),
    Ctx = rfcs_ctx([Schema], IT),
    Meta = stream_meta(ds.version.ds_version, [], [], [], "", ""),

    Values = [int(42i64), str(ZoneRef)],
    check("a fact body encodes",
        ( if encode_fact_body(Ctx, Schema, Values, _) then yes else no ),
        !T, !IO),

    % A slot count mismatch fails rather than encode a short body, which
    % would decode to a fact with a default in the missing slot.
    check("a fact body with too few values FAILS",
        ( if encode_fact_body(Ctx, Schema, [int(42i64)], _) then no else yes ),
        !T, !IO),

    % A kind mismatch is the same hazard: `int` into a String slot would encode
    % as a varint where a reader expects bytes.
    check("a fact body with a mistyped value FAILS",
        ( if encode_fact_body(Ctx, Schema, [str(ZoneRef), int(1i64)], _)
          then no else yes ), !T, !IO),

    Records = [
        {make_seq(1u64), se_fact_assert(make_fact_id(11u64),
            make_schema_id(7u32), Values, no)},
        {make_seq(2u64), se_fact_retract(make_fact_id(11u64))},
        {make_seq(3u64), se_clock_tick(from_ns(5000u64), yes(9000i64))},
        {make_seq(4u64), se_fire_begin(Fire)},
        {make_seq(5u64), se_fire_end(Fire)},
        % Reaches no atom: a cooldown's arming is callback-only, and
        % `ds.rfcs.recordable/1` has no case for it.
        {make_seq(6u64), se_timer_armed(Fire, duration_from_ns(1000u64),
            from_ns(6000u64))}
    ],
    encode_stream(Meta, Ctx, from_ns(1234u64), Records, Bytes, Unencodable),
    check("nothing recordable failed to encode",
        ( if Unencodable = [] then yes else no ), !T, !IO),
    BM = from_bytes(list.map(uint8.cast_to_int, Bytes)),
    walk(init_reader(BM), 0, Count, [], RevAtoms, Outcome),
    list.reverse(RevAtoms, Atoms),

    check("the written stream walks to a clean EOF",
        ( if Outcome = fr_eof then yes else no ), !T, !IO),
    % The schema prelude comes first: [RFCS.5.1] requires a reader to hold a
    % schema's SchemaDef and Slot atoms before the first FactAssert that uses
    % it, so their place in the sequence is the obligation.
    check("the atoms are StreamHeader, the schema prelude, then the events in order",
        ( if Atoms = [known(at_stream_header),
                      known(at_schema_def), known(at_slot), known(at_slot),
                      known(at_fact_assert), known(at_fact_retract), known(at_clock_advance),
                      known(at_rule_fire_annotation), known(at_rule_fire_annotation)]
          then yes else no ), !T, !IO),
    io.format("  note: recorded stream = %d atoms from %d events + 1 schema\n",
        [i(Count), i(list.length(Records))], !IO),

    % Who produced a fact picks its atom [RFCS.6a, 7a]. An assert inside a
    % firing writes no FactAssert; its verb marker writes the FactEmit, carrying the body
    % and the rule. An engine removal is a FactWithdraw with its cause; a host one
    % stays FactRetract.
    Emitted = [
        {make_seq(1u64), se_fire_begin(Fire)},
        {make_seq(2u64), se_fact_assert(make_fact_id(12u64),
            make_schema_id(7u32), Values, no)},
        {make_seq(3u64), se_emit(make_fact_id(12u64), make_schema_id(7u32))},
        {make_seq(4u64), se_fire_end(Fire)},
        {make_seq(5u64), se_fact_withdraw(make_fact_id(12u64), rc_ttl)}
    ],
    encode_stream(Meta, Ctx, from_ns(1234u64), Emitted, EBytes, EUnenc),
    check("an emitted fact and its withdrawal encode",
        ( if EUnenc = [] then yes else no ), !T, !IO),
    walk(init_reader(from_bytes(list.map(uint8.cast_to_int, EBytes))), 0, _,
        [], RevEAtoms, _),
    check("a rule's fact is FactEmit, not FactAssert, and the engine's removal is FactWithdraw",
        ( if list.reverse(RevEAtoms) = [known(at_stream_header),
                      known(at_schema_def), known(at_slot), known(at_slot),
                      known(at_rule_fire_annotation), known(at_fact_emit), known(at_rule_fire_annotation),
                      known(at_fact_withdraw)]
          then yes else no ), !T, !IO),

    % [RFCS.6a.1]: the reader keeps who produced a fact. A `FactAssert` and a
    % `FactEmit` both decode to `se_fact_assert`; `dsm_emitted` holds the seqs
    % of the `FactEmit`s, and `ds.replay` delivers every other decoded assert
    % as an input. So the host's fact (11) must be outside the set and the
    % rule's (12) inside it.
    Mixed = [{make_seq(0u64), se_fact_assert(make_fact_id(11u64),
        make_schema_id(7u32), Values, no)} | Emitted],
    encode_stream(Meta, Ctx, from_ns(1234u64), Mixed, MBytes, _),
    decode_stream(from_bytes(list.map(uint8.cast_to_int, MBytes)),
        init_interns, MResult),
    ( if
        MResult = decoded(MDS),
        list.find_first_match(
            (pred(RecH::in) is semidet :-
                RecH = {_, EvH},
                EvH = se_fact_assert(FidH, _, _, _),
                FidH = make_fact_id(11u64)),
            MDS ^ dsm_events, {HostSeq, _}),
        list.find_first_match(
            (pred(RecR::in) is semidet :-
                RecR = {_, EvR},
                EvR = se_fact_assert(FidR, _, _, _),
                FidR = make_fact_id(12u64)),
            MDS ^ dsm_events, {RuleSeq, _})
    then
        check("[RFCS.6a.1] the host's FactAssert is not noted as emitted",
            ( if set.member(seq_value(HostSeq), MDS ^ dsm_emitted)
              then no else yes ), !T, !IO),
        check("[RFCS.6a.1] the rule's FactEmit is noted as emitted",
            ( if set.member(seq_value(RuleSeq), MDS ^ dsm_emitted)
              then yes else no ), !T, !IO)
    else
        check("[RFCS.6a.1] a host assert and a rule's emit decode", no,
            !T, !IO)
    ),
    % A host cause has no FactWithdraw: an `rc_explicit` withdrawal cannot
    % encode.
    encode_stream(Meta, Ctx, from_ns(0u64),
        [{make_seq(1u64), se_fact_withdraw(make_fact_id(12u64), rc_explicit)}],
        _, HostUnenc),
    check("a withdrawal without an engine cause does NOT encode",
        ( if HostUnenc = [_] then yes else no ), !T, !IO),

    % [RFCS.7a.2]: a reader carries a cause the enum does not hold: it
    % accepts the atom and keeps the number, the reserved 4 included. The atom
    % is compare class, so an unknown cause is a difference a comparison
    % finds, not a decode error.
    % `Emitted`'s FactWithdraw (fact 12, `rc_ttl`: fields `08 0c 10 02`) is
    % re-pointed at 4 and at 9, and each must decode to `se_fact_withdraw_unnamed` of
    % fact 12 with its own number. The unpatched stream is the control that
    % the patch site is the cause: it decodes to the named `rc_ttl`.
    ( if fwth_cause_site(EBytes, FwPre, FwPost) then
        FwPatched = (func(FwCause) =
            FwPre ++ [0x08u8, 0x0cu8, 0x10u8, FwCause | FwPost]),
        FwWithdrawals = (func(FwBytes) = FwEvents :-
            decode_stream(from_bytes(list.map(uint8.cast_to_int, FwBytes)),
                init_interns, FwResult),
            ( if FwResult = decoded(FwDS) then
                FwEvents = list.filter_map(
                    ( func(FwRec) = FwEv is semidet :-
                        FwRec = {_, FwEv},
                        ( FwEv = se_fact_withdraw(_, _)
                        ; FwEv = se_fact_withdraw_unnamed(_, _) )
                    ), FwDS ^ dsm_events)
            else
                FwEvents = []
            )),
        check("[RFCS.7a.2] the unpatched FactWithdraw decodes to its named "
                ++ "cause",
            ( if FwWithdrawals(EBytes) =
                    [se_fact_withdraw(make_fact_id(12u64), rc_ttl)]
              then yes else no ), !T, !IO),
        check("[RFCS.7a.2] a FactWithdraw whose cause the enum does not hold "
                ++ "(9) "
                ++ "decodes and carries 9",
            ( if FwWithdrawals(FwPatched(0x09u8)) =
                    [se_fact_withdraw_unnamed(make_fact_id(12u64), 9u32)]
              then yes else no ), !T, !IO),
        check("[RFCS.7a.2] the reserved cause 4 decodes and carries 4, as 9 "
                ++ "does",
            ( if FwWithdrawals(FwPatched(0x04u8)) =
                    [se_fact_withdraw_unnamed(make_fact_id(12u64), 4u32)]
              then yes else no ), !T, !IO)
    else
        check("the FactWithdraw's fact_id and cause fields are where this "
                ++ "looks", no,
            !T, !IO)
    ),

    % Each atom carries the clock at its own event: the recording's origin
    % before the first tick, the tick's instant after it.
    Asserted = se_fact_assert(make_fact_id(11u64), make_schema_id(7u32),
        Values, no),
    Ticked = se_clock_tick(from_ns(5000u64), no),
    Timed = [
        {make_seq(1u64), Asserted},
        {make_seq(2u64), Ticked},
        {make_seq(3u64), se_fire_begin(Fire)}
    ],
    encode_stream(Meta, Ctx, from_ns(1234u64), Timed, TBytes, _),
    ( if
        encode_event(Meta, Ctx, from_ns(1234u64), make_seq(1u64), Asserted,
            Early),
        encode_event(Meta, Ctx, from_ns(5000u64), make_seq(1u64), Asserted,
            Late),
        encode_event(Meta, Ctx, from_ns(5000u64), make_seq(2u64), Ticked, Tick),
        encode_event(Meta, Ctx, from_ns(5000u64), make_seq(3u64),
            se_fire_begin(Fire), Begun),
        encode_event(Meta, Ctx, from_ns(1234u64), make_seq(3u64),
            se_fire_begin(Fire), BegunEarly)
    then
        check("an atom carries the origin before a tick, the tick after",
            ( if list.remove_suffix(TBytes, Early ++ Tick ++ Begun, _)
              then yes else no ), !T, !IO),
        % Without this the check above could pass on encodings that ignore the
        % clock altogether.
        check("the two stampings encode differently",
            ( if Early \= Late, Begun \= BegunEarly then yes else no ), !T, !IO)
    else
        check("the timed events encode", no, !T, !IO)
    ),

    % [LFST.5.6]: every FactAssert carries an event_id, derived from the
    % stream's run id, tier id and the record's seq, and nothing else. The
    % lockstep recordings checker compares the bytes with libds's; here, what
    % it depends on.
    EidA = lfst_5_6_event_id("r1", "t1", 1u64),
    EidChars = string.to_char_list(EidA),
    check("an event_id is UUID-shaped, version 8, RFC 4122 variant",
        ( if
            list.length(EidChars) = 36,
            % `('-')`, parenthesised: a bare `'-'` is the minus operator.
            list.index0(EidChars, 8, EidC8), EidC8 = ('-'),
            list.index0(EidChars, 13, EidC13), EidC13 = ('-'),
            list.index0(EidChars, 18, EidC18), EidC18 = ('-'),
            list.index0(EidChars, 23, EidC23), EidC23 = ('-'),
            list.index0(EidChars, 14, EidVer), EidVer = '8',
            list.index0(EidChars, 19, EidVar),
            list.member(EidVar, ['8', '9', 'a', 'b'])
          then yes else no ), !T, !IO),
    check("the same ids and seq derive the same event_id",
        ( if lfst_5_6_event_id("r1", "t1", 1u64) = EidA then yes else no ),
        !T, !IO),
    check("the seq, the run id and the tier id each move it",
        ( if
            lfst_5_6_event_id("r1", "t1", 2u64) \= EidA,
            lfst_5_6_event_id("r2", "t1", 1u64) \= EidA,
            lfst_5_6_event_id("r1", "t2", 1u64) \= EidA,
            % The separator is in the hash: "r1"+"t1" is not "r"+"1t1".
            lfst_5_6_event_id("r", "1t1", 1u64) \= EidA
          then yes else no ), !T, !IO),
    EidMeta = stream_meta(ds.version.ds_version, [], [], [], "r1", "t1"),
    ( if
        encode_event(EidMeta, Ctx, from_ns(1234u64), make_seq(1u64), Asserted,
            EidWith),
        encode_event(Meta, Ctx, from_ns(1234u64), make_seq(1u64), Asserted,
            EidWithout)
    then
        string.to_utf8_code_unit_list(EidA, EidCodes),
        string.to_utf8_code_unit_list(lfst_5_6_event_id("", "", 1u64),
            EidNoCodes),
        check("a FactAssert ends with field 8, the event_id its ids and seq derive",
            ( if list.remove_suffix(EidWith,
                    [0x42u8, 36u8] ++ list.map(uint8.cast_from_int, EidCodes),
                    _)
              then yes else no ), !T, !IO),
        check("and with no ids it still carries one, from the seq alone",
            ( if list.remove_suffix(EidWithout,
                    [0x42u8, 36u8] ++ list.map(uint8.cast_from_int, EidNoCodes),
                    _)
              then yes else no ), !T, !IO)
    else
        check("the FactAssert with ids encodes", no, !T, !IO)
    ).

    % A recording carrying a reserved 260 or a deferred TextNote (323) is
    % refused: neither number is in `ds.atom`, so neither names a member of
    % `Atom`'s oneof [RFCS.19.3]. Each is appended with an empty body and with
    % one that holds a field.
    %
    % @spec [RFCS.19.3]
:- pred test_rfcs_retired_atoms_refused(tally::in, tally::out, io::di, io::uo)
    is det.

test_rfcs_retired_atoms_refused(!T, !IO) :-
    Bytes = (func(Ints) = list.map(uint8.cast_from_int, Ints)),
    Meta = stream_meta(ds.version.ds_version, [], [], [], "", ""),
    Header = encode_header(Meta),
    Decode = (func(Bs) = R :-
        decode_stream(from_bytes(list.map(uint8.cast_to_int, Bs)),
            init_interns, R)),
    Plain = Decode(Header),
    % The outer frame is `Atom` field 1, then the inner key: 260 is A2 10 and
    % 323 is 9A 14, each two varint bytes. The full body is `08 01`, field 1
    % as a varint.
    Appended = [
        {"an empty Seal (260)",   Bytes([0x0A, 0x03, 0xA2, 0x10, 0x00])},
        {"a Seal (260) with a body",
            Bytes([0x0A, 0x05, 0xA2, 0x10, 0x02, 0x08, 0x01])},
        {"an empty TextNote (323)", Bytes([0x0A, 0x03, 0x9A, 0x14, 0x00])},
        {"a TextNote (323) with a body",
            Bytes([0x0A, 0x05, 0x9A, 0x14, 0x02, 0x08, 0x01])}
    ],
    check("the bare header decodes",
        ( if Plain = decoded(_) then yes else no ), !T, !IO),
    list.foldl2(
        ( pred(Case::in, T0::in, T1::out, IO0::di, IO1::uo) is det :-
            Case = {What, Atom},
            check("RFCS.19.3: a recording with " ++ What
                    ++ " appended is refused",
                ( if Decode(Header ++ Atom) = decode_failed("RFCS.19.3", _)
                  then yes else no ),
                T0, T1, IO0, IO1)
        ), Appended, !T, !IO).

    % The binding comparators, and the traps [RBND.8] names: a comparator that
    % sorts the capabilities before comparing, and one that binds on a subset
    % of the tuple.
    %
:- pred test_binding(tally::in, tally::out, io::di, io::uo) is det.

test_binding(!T, !IO) :-
    % `call` (8) and `regex` (6), ascending.
    A = dialect_binding([1u8, 2u8], [6, 8], [9u8]),
    check("identical dialect bindings bind",
        ( if compare_dialect(A, A) = bound then yes else no ), !T, !IO),

    check("a differing dsc_sha256 is -700",
        ( if compare_dialect(A, A ^ db_dsc_sha := [3u8]) = mismatch(-700, _)
          then yes else no ), !T, !IO),
    check("differing capabilities are -701 (RBND.5.2)",
        ( if compare_dialect(A, A ^ db_capabilities := [6]) = mismatch(-701, _)
          then yes else no ), !T, !IO),
    check("a differing dialect_def_sha256 is -701 (RBND.5.2)",
        ( if compare_dialect(A, A ^ db_def_sha := [8u8]) = mismatch(-701, _)
          then yes else no ), !T, !IO),

    % The order is part of the tuple: [RBND.1.3] writes the capabilities
    % ascending, so the same set in a different order does not bind.
    check("the same capabilities in a different order do NOT bind",
        ( if compare_dialect(A, A ^ db_capabilities := [8, 6])
             = mismatch(-701, _)
          then yes else no ), !T, !IO),

    Rt = rt_binding([7u8]),
    check("identical RT bindings bind",
        ( if compare_rt(Rt, Rt) = bound then yes else no ), !T, !IO),
    check("a differing rt_config_sha256 is -704",
        ( if compare_rt(Rt, Rt ^ rb_sha := [8u8]) = mismatch(-704, _)
          then yes else no ), !T, !IO),

    % `RBND.5.2` -- for `capabilities` the detail names the capabilities in
    % one tuple and not the other.
    ( if compare_dialect(A, A ^ db_capabilities := [6]) = mismatch(_, Detail)
    then
        check("the detail names the capability in one tuple only",
            ( if string.sub_string_search(Detail, "capabilities", _),
                 string.sub_string_search(Detail, "call", _)
              then yes else no ), !T, !IO)
    else
        check("a capabilities mismatch produces a detail", no, !T, !IO)
    ),
    check("a hash in a detail is truncated to 16 hex chars",
        ( if string.length(short_hex(sha256([]))) = 16 then yes else no ),
        !T, !IO),

    % On two real artefacts, both built against the `default` dialect: the
    % decoder's path and the comparator's meet on real bytes ([RBND.8]).
    binding_of("fixtures/07_action_verbs.dsc", DefaultB, !IO),
    binding_of("fixtures/54_series.dsc", SeriesB, !IO),
    (
        DefaultB = yes(D), SeriesB = yes(S),
        check("a real artefact binds to itself",
            ( if compare_dialect(D, D) = bound then yes else no ), !T, !IO),
        check("two different artefacts do NOT bind",
            ( if compare_dialect(D, S) = mismatch(_, _) then yes else no ),
            !T, !IO),
        check("the first mismatch reported is the dsc_sha256 (-700)",
            ( if compare_dialect(D, S) = mismatch(-700, _) then yes else no ),
            !T, !IO),
        % [RBND.1.3]: "The dialect's name is not part of the tuple: two
        % programs whose settings resolve alike are bound alike, whatever
        % dialect each named." Both artefacts resolve `default`'s settings, so
        % with the bundle hash equalised nothing is left. Both name `default`,
        % so this says nothing about different names; the name is absent from
        % the tuple by construction (`dialect_binding` has no field for it).
        check("two artefacts with one set of settings bind (RBND.1.3)",
            ( if compare_dialect(D, S ^ db_dsc_sha := D ^ db_dsc_sha) = bound
              then yes else no ), !T, !IO)
    ;
        DefaultB = no,
        check("07_action_verbs.dsc loads for the binding test", no, !T, !IO)
    ;
        DefaultB = yes(_), SeriesB = no,
        check("54_series.dsc loads for the binding test", no, !T, !IO)
    ).

    % A fixture's dialect binding tuple, or `no` if it will not load.
    %
:- pred binding_of(string::in, maybe(dialect_binding)::out,
                   io::di, io::uo) is det.

binding_of(Path, Result, !IO) :-
    io.open_binary_input(Path, OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, ReadRes, !IO),
        io.close_binary_input(Stream, !IO),
        ( if ReadRes = ok(BM), load_dsc(BM, loaded(P)) then
            H = header(P),
            Result = yes(dialect_binding(H ^ dh_sha256, H ^ dh_capabilities,
                H ^ dh_dialect_sha))
        else
            Result = no
        )
    ;
        OpenRes = error(_),
        Result = no
    ).

    % SHA-256 against FIPS 180-4's own examples: a one-block message, a
    % two-block message and the empty string, which still pads a block.
    %
:- pred test_sha256(tally::in, tally::out, io::di, io::uo) is det.

test_sha256(!T, !IO) :-
    check("sha256(\"\") -- the padding-only block",
        ( if hex(sha256([])) =
             "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
          then yes else no ), !T, !IO),
    check("sha256(\"abc\") -- FIPS 180-4 B.1",
        ( if hex(sha256(ascii("abc"))) =
             "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
          then yes else no ), !T, !IO),
    Two = "abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq",
    check("sha256 of a 56-byte message -- FIPS 180-4 B.2, two blocks",
        ( if hex(sha256(ascii(Two))) =
             "248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1"
          then yes else no ), !T, !IO),
    % The block boundary: 55 bytes is the largest message whose padding still
    % fits its own block, 56 the smallest that needs a second.
    check("sha256 of 55 bytes -- the last message that fits one block",
        ( if hex(sha256(ascii(string.duplicate_char('a', 55)))) =
             "9f4390f8d30c2dd92ec9f095b65e2b9ae9b0a925a5258e241c9f1e910f734318"
          then yes else no ), !T, !IO),
    check("sha256 of 56 bytes -- the first that needs a second block",
        ( if hex(sha256(ascii(string.duplicate_char('a', 56)))) =
             "b35439a4ac6f0948b6d6f9e3c6af0f5f590ce20f1bde7090ef7970686ec6738a"
          then yes else no ), !T, !IO),
    % A whole block, then a tail of nothing but padding: a length that is a
    % multiple of 64 leaves an empty tail that still pads.
    check("sha256 of 64 bytes -- one whole block, then the padding's own",
        ( if hex(sha256(ascii(string.duplicate_char('a', 64)))) =
             "ffe054fe7ae0cb6dc65c3af9b61d5209f439851db43d0ba5997337df154668eb"
          then yes else no ), !T, !IO),
    % FIPS 180-4's long message: a million `a`s, 15,625 blocks.
    check("sha256 of a million `a`s -- FIPS 180-4's long message",
        ( if hex(sha256(list.duplicate(1000000, 0x61u8))) =
             "cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0"
          then yes else no ), !T, !IO).

    % [RFCS.23.3]: a temporal slot's declared type is in the hash. The
    % expected bytes are `Stamp`'s SchemaShape written out by hand, the bytes
    % libds's test_assert_external hashes, so neither runtime's encoder is
    % the oracle: the name, then each slot in byte order of name
    % (day, k, seen, span) as field 2; a slot writes its name (field 1), omits
    % kind KIND_INT, nullable false and an empty ref_schema, and a temporal
    % slot adds temporal_kind (field 5): TIME 8, DATE 9, DURATION 10.
    %
    % The shapes go in in declaration order, so `schema_hash`'s own sort is
    % what puts them in the vector's order. And an `Int` slot of the same name
    % hashes otherwise, though both are `kind_int`.
    %
% @spec [RFCS.23.3]
:- pred test_temporal_schema_hash(tally::in, tally::out, io::di, io::uo) is det.

test_temporal_schema_hash(!T, !IO) :-
    Shapes = [
        slot_shape("k", kind_int, no, "", no),
        slot_shape("seen", kind_int, no, "", yes(tk_time)),
        slot_shape("day", kind_int, no, "", yes(tk_date)),
        slot_shape("span", kind_int, no, "", yes(tk_duration))
    ],
    ByHand = list.map(uint8.cast_from_int, [
        0x0A, 0x05] ++ ascii_codes("Stamp") ++ [
        0x12, 0x07, 0x0A, 0x03] ++ ascii_codes("day") ++ [0x28, 0x09,
        0x12, 0x03, 0x0A, 0x01] ++ ascii_codes("k") ++ [
        0x12, 0x08, 0x0A, 0x04] ++ ascii_codes("seen") ++ [0x28, 0x08,
        0x12, 0x08, 0x0A, 0x04] ++ ascii_codes("span") ++ [0x28, 0x0A]),
    check("RFCS.23.3: schema_hash of a schema with Time, Date and Duration "
            ++ "slots is the SHA-256 of the hand-encoded SchemaShape",
        ( if schema_hash("Stamp", Shapes) = sha256(ByHand) then yes else no ),
        !T, !IO),
    IntSeen = [
        slot_shape("k", kind_int, no, "", no),
        slot_shape("seen", kind_int, no, "", no),
        slot_shape("day", kind_int, no, "", yes(tk_date)),
        slot_shape("span", kind_int, no, "", yes(tk_duration))
    ],
    check("RFCS.23.3: a Time slot and an Int slot of the same name hash "
            ++ "apart",
        ( if schema_hash("Stamp", IntSeen) \= schema_hash("Stamp", Shapes)
          then yes else no ),
        !T, !IO).

:- func ascii_codes(string) = list(int).

ascii_codes(S) = Codes :-
    string.to_utf8_code_unit_list(S, Codes).

:- func ascii(string) = list(uint8).

ascii(S) = Bytes :-
    string.to_utf8_code_unit_list(S, Codes),
    Bytes = list.map(uint8.cast_from_int, Codes).

    % The bytes before and after the first `08 0c 10 02` -- a FactWithdraw body's
    % fact_id 12 and cause 2 -- for `test_rfcs_writer`'s reserved-cause check.
    % Semidet, the first match only: `list.append` would be nondet there, and
    % a nondet condition cannot thread `!IO`.
    %
:- pred fwth_cause_site(list(uint8)::in, list(uint8)::out, list(uint8)::out)
    is semidet.

fwth_cause_site(Bytes, Pre, Post) :-
    ( if Bytes = [0x08u8, 0x0cu8, 0x10u8, 0x02u8 | After] then
        Pre = [],
        Post = After
    else
        Bytes = [B | Bs],
        fwth_cause_site(Bs, Pre0, Post),
        Pre = [B | Pre0]
    ).


    % [LSTR.1.5]: a recorded String holding U+0000 refuses the stream, as any
    % body that does not decode does ([RFCS.19.3]): never cut short at the
    % NUL, and never skipped. The body is made by writing a fact whose String
    % is "a~b" and overwriting the `~` with a zero byte, the lengths intact.
    % libds's `test_rfcs_fact` pins the same refusal. Path:
    % `ds.wire.reader_string`, whose UTF-8 decode admits no NUL, failing
    % `ds.rfcs.slot_value` and so the atom.
    %
:- pred test_rfcs_reader_nul(tally::in, tally::out, io::di, io::uo) is det.

test_rfcs_reader_nul(!T, !IO) :-
    intern("Reading", NameRef, init_interns, IT1),
    intern("a~b", TextRef, IT1, IT),
    Slots = [rslot(0, k_int), rslot(1, k_string)],
    Schema = schema(make_schema_id(1u32), make_schema_name(NameRef),
        lc_logical(Slots, no), no, no),
    Ctx = rfcs_ctx([Schema], IT),
    Meta = stream_meta(ds.version.ds_version, [], [], [], "", ""),
    Records = [{make_seq(0u64), se_fact_assert(make_fact_id(1u64),
        make_schema_id(1u32), [int(7i64), str(TextRef)], no)}],
    encode_stream(Meta, Ctx, from_ns(0u64), Records, Bytes, _),
    Good = from_bytes(list.map(uint8.cast_to_int, Bytes)),
    decode_stream(Good, init_interns, GoodResult),
    check("LSTR.1.5: the stream with \"a~b\" decodes (the control)",
        ( if GoodResult = decoded(_) then yes else no ), !T, !IO),
    ( if replace_tilde_in_a_b(Bytes, WithNul) then
        decode_stream(from_bytes(list.map(uint8.cast_to_int, WithNul)),
            init_interns, NulResult),
        check("LSTR.1.5: a recorded String holding U+0000 refuses the stream",
            ( if NulResult = decode_failed("RFCS.19.3", _) then yes else no ),
            !T, !IO)
    else
        check("LSTR.1.5: the written stream carries \"a~b\"", no, !T, !IO)
    ).

    % [RFCS.6.3]: a fact reference is recorded as its target's handle, the
    % `fact_id` the target's own record was written under, and a reader takes
    % only a handle an earlier record gave. `Tag.owner` names the `Owner`
    % recorded first as fact 5; `Tag.alt` is nullable and null, so its field
    % is absent. The same stream with the handle 9, which no record gave, is
    % refused; libds's `test_rfcs_fact` pins the same refusal.
    %
    % Paths: `encode_slot` and `rfcs_6_3_encode_present` on `k_schema`;
    % `encode_slot_atom`'s `schema_ref`; the reader's Slot arm building
    % `k_schema` from it; `slot_value` on `k_schema`; `read_fcem`'s
    % `refs_recorded`.
    %
:- pred test_rfcs_reader_ref(tally::in, tally::out, io::di, io::uo) is det.

test_rfcs_reader_ref(!T, !IO) :-
    intern("Owner", OwnerRef, init_interns, IT1),
    intern("Tag", TagRef, IT1, IT),
    OwnerName = make_schema_name(OwnerRef),
    Owner = schema(make_schema_id(1u32), OwnerName,
        lc_logical([rslot(0, k_int)], no), no, no),
    Tag = schema(make_schema_id(2u32), make_schema_name(TagRef),
        lc_logical([rslot(0, k_int), rslot(1, k_schema(OwnerName)),
            nslot(2, k_schema(OwnerName))], no), no, no),
    Ctx = rfcs_ctx([Owner, Tag], IT),
    Meta = stream_meta(ds.version.ds_version, [], [], [], "", ""),
    OwnerRec = {make_seq(0u64), se_fact_assert(make_fact_id(5u64),
        make_schema_id(1u32), [int(1i64)], no)},
    TagRec = (func(Handle) = {make_seq(1u64), se_fact_assert(make_fact_id(6u64),
        make_schema_id(2u32), [int(1i64), fact_ref(make_fact_id(Handle)), null],
        no)}),
    encode_stream(Meta, Ctx, from_ns(0u64), [OwnerRec, TagRec(5u64)], Good, _),
    decode_stream(from_bytes(list.map(uint8.cast_to_int, Good)), init_interns,
        GoodResult),
    check("RFCS.6.3: a reference decodes as the handle an earlier record gave",
        ( if
            GoodResult = decoded(DS),
            DS ^ dsm_events = [_, {_, se_fact_assert(_, _,
                [int(1i64), fact_ref(F), null], _)}],
            fact_id_value(F) = 5u64
          then yes else no ), !T, !IO),
    encode_stream(Meta, Ctx, from_ns(0u64), [OwnerRec, TagRec(9u64)], Bad, _),
    decode_stream(from_bytes(list.map(uint8.cast_to_int, Bad)), init_interns,
        BadResult),
    check("RFCS.6.3: a handle no earlier record gave refuses the stream",
        ( if BadResult = decode_failed("RFCS.19.3", _) then yes else no ),
        !T, !IO),
    test_rfcs_6_3_an_absent_json_field_is_malformed(!T, !IO),
    test_rfcs_6_3_ill_formed_text_is_malformed(!T, !IO),
    test_rfcs_6_3_a_root_null_json_field(!T, !IO).

    % @spec [RFCS.6.3]
    % A `String` or `Json` field's text that is not well-formed UTF-8 refuses
    % the stream, and the same field unedited decodes. A written stream is
    % edited with its lengths intact: one byte of the text becomes 0xFF.
    % libds's `test_rfcs_6_3__*` pin the same. This is the decode path;
    % `test_ncbk_10_4_ill_formed_text` is the delivery's. Path: `read_fcem`
    % -> `decode_fact_body` -> `rebuild` -> `slot_value` -> `reader_string`.
    %
:- pred test_rfcs_6_3_ill_formed_text_is_malformed(tally::in, tally::out,
    io::di, io::uo) is det.

test_rfcs_6_3_ill_formed_text_is_malformed(!T, !IO) :-
    intern("Doc", NameRef, init_interns, IT1),
    intern("hello", Hello, IT1, IT),
    Stream = (func(Slot, Value) = Bytes :-
        Schema = schema(make_schema_id(1u32), make_schema_name(NameRef),
            lc_logical([rslot(0, k_int), Slot], no), no, no),
        encode_stream(stream_meta(ds.version.ds_version, [], [], [], "", ""),
            rfcs_ctx([Schema], IT), from_ns(0u64),
            [{make_seq(0u64), se_fact_assert(make_fact_id(1u64),
                make_schema_id(1u32), [int(1i64), Value], no)}], Bytes, _)
    ),
    Decode = (pred(Bytes::in, Result::out) is det :-
        decode_stream(from_bytes(list.map(uint8.cast_to_int, Bytes)),
            init_interns, Result)),
    StringOk = Stream(rslot(1, k_string), str(Hello)),
    JsonOk = Stream(rslot(1, k_json), json(j_bool(yes))),
    ( if
        replace_run([0x12u8, 0x05u8] ++ ascii("hello"),
            [0x12u8, 0x05u8, 0x68u8, 0xFFu8] ++ ascii("llo"), StringOk,
            StringBad),
        replace_run([0x12u8, 0x04u8] ++ ascii("true"),
            [0x12u8, 0x04u8, 0x74u8, 0xFFu8] ++ ascii("ue"), JsonOk, JsonBad)
    then
        Decode(StringBad, StringBadResult),
        check("RFCS.6.3: a String field's ill-formed text refuses the stream",
            ( if StringBadResult = decode_failed("RFCS.19.3", _)
              then yes else no ), !T, !IO),
        Decode(StringOk, StringOkResult),
        check("RFCS.6.3: and the same String field well-formed decodes",
            ( if
                StringOkResult = decoded(SD),
                SD ^ dsm_events = [{_, se_fact_assert(_, _,
                    [int(1i64), str(_)], _)}]
              then yes else no ), !T, !IO),
        Decode(JsonBad, JsonBadResult),
        check("RFCS.6.3: a Json field's ill-formed text refuses the stream",
            ( if JsonBadResult = decode_failed("RFCS.19.3", _)
              then yes else no ), !T, !IO),
        Decode(JsonOk, JsonOkResult),
        check("RFCS.6.3: and the same Json field well-formed decodes",
            ( if
                JsonOkResult = decoded(JD),
                JD ^ dsm_events = [{_, se_fact_assert(_, _,
                    [int(1i64), json(j_bool(yes))], _)}]
              then yes else no ), !T, !IO)
    else
        check("RFCS.6.3: the written streams carry the text", no, !T, !IO)
    ).

    % @spec [RFCS.6.3]
    % A `Json` field whose document is `null` at its root is the canonical
    % `null`: `null` in a nullable slot, a refused stream in a non-nullable
    % one, and in a body that has already parsed an earlier `Json` field. A
    % written stream's `true` is edited to `null`, its lengths intact. The
    % control: a null inside a document stays a document ([LNUL.3.4]).
    % libds's `test_rfcs_6_3__a_root_null_json_field` pins the same. Path:
    % `read_fcem` -> `decode_fact_body` -> `rebuild`.
    %
:- pred test_rfcs_6_3_a_root_null_json_field(tally::in, tally::out,
    io::di, io::uo) is det.

test_rfcs_6_3_a_root_null_json_field(!T, !IO) :-
    intern("Doc", NameRef, init_interns, IT),
    Stream = (func(Slots, Values) = Bytes :-
        Schema = schema(make_schema_id(1u32), make_schema_name(NameRef),
            lc_logical([rslot(0, k_int) | Slots], no), no, no),
        encode_stream(stream_meta(ds.version.ds_version, [], [], [], "", ""),
            rfcs_ctx([Schema], IT), from_ns(0u64),
            [{make_seq(0u64), se_fact_assert(make_fact_id(1u64),
                make_schema_id(1u32), [int(1i64) | Values], no)}], Bytes, _)
    ),
    Decode = (pred(Bytes::in, Result::out) is det :-
        decode_stream(from_bytes(list.map(uint8.cast_to_int, Bytes)),
            init_interns, Result)),
    True = json(j_bool(yes)),
    TextIn = (func(Tag, Word) = [Tag, 0x04u8] ++ ascii(Word)),
    Doc = j_object(object(["a" - j_null])),
    Holds = Stream([rslot(1, k_json)], [json(Doc)]),
    ( if
        replace_run(TextIn(0x12u8, "true"), TextIn(0x12u8, "null"),
            Stream([rslot(1, k_json)], [True]), Req),
        replace_run(TextIn(0x12u8, "true"), TextIn(0x12u8, "null"),
            Stream([nslot(1, k_json)], [True]), Nul),
        replace_run(TextIn(0x1Au8, "true"), TextIn(0x1Au8, "null"),
            Stream([rslot(1, k_json), rslot(2, k_json)], [True, True]), Two)
    then
        Decode(Req, ReqResult),
        check("RFCS.6.3: a root-null Json field in a non-nullable slot refuses "
                ++ "the stream",
            ( if ReqResult = decode_failed("RFCS.19.3", _) then yes else no ),
            !T, !IO),
        Decode(Nul, NulResult),
        check("RFCS.6.3: and in a nullable slot it is null",
            ( if
                NulResult = decoded(ND),
                ND ^ dsm_events = [{_, se_fact_assert(_, _,
                    [int(1i64), null], _)}]
              then yes else no ), !T, !IO),
        Decode(Two, TwoResult),
        check("RFCS.6.3: and it refuses a stream after an earlier Json field",
            ( if TwoResult = decode_failed("RFCS.19.3", _) then yes else no ),
            !T, !IO),
        Decode(Holds, HoldsResult),
        check("RFCS.6.3: a document holding a null decodes as a document",
            ( if
                HoldsResult = decoded(HD),
                HD ^ dsm_events = [{_, se_fact_assert(_, _,
                    [int(1i64), json(j_object(_))], _)}]
              then yes else no ), !T, !IO)
    else
        check("RFCS.6.3: the written streams carry `true`", no, !T, !IO)
    ).

    % @spec [RFCS.6.3]
    % A non-nullable `Json` slot has no zero, so a body with its field absent
    % refuses the stream, and a nullable slot's reads `null`. The written
    % stream is edited with its lengths intact: the tag `0x12` of `Doc.j`'s
    % text becomes field 3, which no slot reads. The same room holds an empty
    % field and two fields no slot reads. libds's
    % `test_rfcs_6_3__an_absent_json_field_is_malformed` pins the same. Path:
    % `read_fcem` -> `decode_fact_body` -> `rebuild`.
    %
:- pred test_rfcs_6_3_an_absent_json_field_is_malformed(tally::in, tally::out,
    io::di, io::uo) is det.

test_rfcs_6_3_an_absent_json_field_is_malformed(!T, !IO) :-
    Stream = (func(Slot) = Bytes :-
        intern("Doc", NameRef, init_interns, IT),
        Schema = schema(make_schema_id(1u32), make_schema_name(NameRef),
            lc_logical([rslot(0, k_int), Slot], no), no, no),
        encode_stream(stream_meta(ds.version.ds_version, [], [], [], "", ""),
            rfcs_ctx([Schema], IT), from_ns(0u64),
            [{make_seq(0u64), se_fact_assert(make_fact_id(1u64),
                make_schema_id(1u32), [int(1i64), json(j_null)], no)}], Bytes, _)
    ),
    Text = [0x04u8] ++ ascii("null"),
    Absent = [0x1Au8] ++ Text,
    Empty = [0x12u8, 0x00u8, 0x18u8, 0x01u8, 0x18u8, 0x01u8],
    Decode = (pred(Bytes::in, Result::out) is det :-
        decode_stream(from_bytes(list.map(uint8.cast_to_int, Bytes)),
            init_interns, Result)),
    ( if
        replace_run([0x12u8] ++ Text, Absent, Stream(rslot(1, k_json)), Req),
        replace_run([0x12u8] ++ Text, Absent, Stream(nslot(1, k_json)), Nul),
        replace_run([0x12u8] ++ Text, Empty, Stream(rslot(1, k_json)), Emp)
    then
        Decode(Req, ReqResult),
        check("RFCS.6.3: a non-nullable Json slot's absent field refuses the "
                ++ "stream",
            ( if ReqResult = decode_failed("RFCS.19.3", _) then yes else no ),
            !T, !IO),
        Decode(Nul, NulResult),
        check("RFCS.6.3: a nullable Json slot's absent field is null",
            ( if
                NulResult = decoded(DS),
                DS ^ dsm_events = [{_, se_fact_assert(_, _,
                    [int(1i64), null], _)}]
              then yes else no ), !T, !IO),
        Decode(Emp, EmpResult),
        check("RFCS.6.3: a present empty Json field refuses the stream",
            ( if EmpResult = decode_failed("RFCS.19.3", _) then yes else no ),
            !T, !IO)
    else
        check("RFCS.6.3: the written stream carries the Json field", no, !T,
            !IO)
    ).

    % `Bytes` with the first run of `From` replaced by `To`.
    %
:- pred replace_run(list(uint8)::in, list(uint8)::in, list(uint8)::in,
    list(uint8)::out) is semidet.

replace_run(From, To, Bytes, Out) :-
    ( if list.append(From, Rest, Bytes) then
        Out = To ++ Rest
    else
        Bytes = [B | Bs],
        replace_run(From, To, Bs, Out1),
        Out = [B | Out1]
    ).

    % A `Bytes` or `Json` slot is recorded as libds's codec records it
    % (`rfcs/codec.c`, `emit_fact_fields`): `Bytes` as its octets and `Json` as
    % `ds_json_serialize`'s canonical text, each a length-delimited field, the
    % empty `Bytes` omitted in a non-nullable slot and written in a nullable
    % one ([RFCS.6.3]).
    %
    % The expected bytes are written out, not derived from the writer: the
    % Json text below is what libds's serializer gives, with no whitespace and
    % keys in byte order, and `0x22` is field 4, length-delimited. The read
    % half of `Json` is `ds.rfcs.slot_value`'s `k_json` arm, through
    % `ds.json_text`.
    %
:- pred test_rfcs_bytes_json(tally::in, tally::out, io::di, io::uo) is det.

test_rfcs_bytes_json(!T, !IO) :-
    intern("Blob", NameRef, init_interns, IT),
    Slots = [rslot(0, k_int), rslot(1, k_bytes), nslot(2, k_bytes),
        rslot(3, k_json)],
    Schema = schema(make_schema_id(1u32), make_schema_name(NameRef),
        lc_logical(Slots, no), no, no),
    Ctx = rfcs_ctx([Schema], IT),
    Octets = from_bytes([0x00, 0xff, 0x7f, 0x80]),
    Doc = j_object(object(["b" - j_bool(yes), "a" - j_int(1i64)])),
    A = [int(1i64), bytes(Octets), bytes(bitmap.init(0)), json(Doc)],
    B = [int(2i64), bytes(bitmap.init(0)), null, json(j_null)],
    ( if
        encode_fact_body(Ctx, Schema, A, ABytes),
        encode_fact_body(Ctx, Schema, B, BBytes)
    then
        check("recorded slot: a Bytes slot is its octets, NUL and non-UTF-8 "
                ++ "included; a nullable empty Bytes is a present empty field; "
                ++ "a Json slot is its canonical text",
            ( if
                ABytes = [0x08u8, 0x01u8, 0x12u8, 0x04u8,
                          0x00u8, 0xffu8, 0x7fu8, 0x80u8, 0x1Au8, 0x00u8,
                          0x22u8, 0x10u8] ++ ascii("{\"a\":1,\"b\":true}")
              then yes else no ), !T, !IO),
        check("recorded slot: a non-nullable empty Bytes and a null Bytes? are "
                ++ "absent; a Json null is the text `null`",
            ( if BBytes = [0x08u8, 0x02u8, 0x22u8, 0x04u8] ++ ascii("null")
              then yes else no ), !T, !IO)
    else
        check("recorded slot: a fact with Bytes and Json slots encodes", no,
            !T, !IO)
    ),
    Meta = stream_meta(ds.version.ds_version, [], [], [], "", ""),
    BSlots = [rslot(0, k_int), rslot(1, k_bytes), nslot(2, k_bytes)],
    BSchema = schema(make_schema_id(2u32), make_schema_name(NameRef),
        lc_logical(BSlots, no), no, no),
    BCtx = rfcs_ctx([BSchema], IT),
    BVals = [int(1i64), bytes(Octets), bytes(bitmap.init(0))],
    encode_stream(Meta, BCtx, from_ns(0u64),
        [{make_seq(0u64), se_fact_assert(make_fact_id(1u64),
            make_schema_id(2u32), BVals, no)}], BStream, BUnencodable),
    ( if
        BUnencodable = [],
        decode_stream(from_bytes(list.map(uint8.cast_to_int, BStream)),
            init_interns, decoded(BDS)),
        BDS ^ dsm_events = [{_, se_fact_assert(_, _, Got, _)}]
    then
        check("recorded slot: the Bytes fact records and decodes as asserted, "
                ++ "octets and the present empty value",
            ( if Got = BVals then yes else no ), !T, !IO)
    else
        check("recorded slot: the Bytes fact records and decodes", no, !T, !IO)
    ),
    encode_stream(Meta, Ctx, from_ns(0u64),
        [{make_seq(0u64), se_fact_assert(make_fact_id(1u64),
            make_schema_id(1u32), A, no)}], JStream, JUnencodable),
    check("recorded slot: the Json fact is recorded, not left out",
        ( if JUnencodable = [] then yes else no ), !T, !IO),
    decode_stream(from_bytes(list.map(uint8.cast_to_int, JStream)),
        init_interns, JResult),
    check("recorded slot: the Json fact records and decodes as asserted",
        ( if
            JResult = decoded(JDS),
            JDS ^ dsm_events = [{_, se_fact_assert(_, _, JGot, _)}],
            JGot = A
          then yes else no ),
        !T, !IO).

    % The first `a ~ b` in the bytes, with the `~` made a zero byte.
    %
:- pred replace_tilde_in_a_b(list(uint8)::in, list(uint8)::out) is semidet.

replace_tilde_in_a_b([B0 | Bs0], Out) :-
    ( if B0 = 0x61u8, Bs0 = [0x7eu8, 0x62u8 | Rest] then
        Out = [0x61u8, 0x00u8, 0x62u8 | Rest]
    else
        replace_tilde_in_a_b(Bs0, Out1),
        Out = [B0 | Out1]
    ).

    % The offset of every frame in a well-formed container.
    %
:- func frame_starts(reader) = list(int).

frame_starts(R0) = Starts :-
    next_frame(FR, R0, R1),
    ( if FR = fr_ok(F) then
        Starts = [F ^ fr_offset | frame_starts(R1)]
    else
        Starts = []
    ).

    % One cut of `Bytes` at `K`. `Bounds` holds every offset where a frame
    % ends, so `B` below is the end of the last complete atom before the cut.
    % The prefix reader must decode what the whole stream up to `B` decodes
    % and report `K - B` as the tail; the whole-buffer reader must accept the
    % cut exactly when it falls on a boundary. Before the `StreamHeader` is
    % whole, no version has arrived and both refuse under [LDET.1.10].
    %
:- pred check_cut(list(uint8)::in, list(int)::in, int::in,
                  list(int)::in, list(int)::out, io::di, io::uo) is det.

check_cut(Bytes, Bounds, K, !Bad, !IO) :-
    B = list.foldl((func(X, M) = ( if X =< K, X > M then X else M )),
        Bounds, 0),
    Bm = (func(N) = from_bytes(list.map(uint8.cast_to_int,
        list.take_upto(N, Bytes)))),
    decode_stream_prefix(Bm(K), init_interns, R, Tail),
    decode_stream(Bm(B), init_interns, RB),
    decode_stream(Bm(K), init_interns, RS),
    ( if
        R = decoded(D),
        RB = decoded(DB),
        Tail = K - B,
        D ^ dsm_events = DB ^ dsm_events,
        ( if K = B then RS = decoded(_) else RS = decode_failed(_, B) )
    then
        true
    else if
        R = decode_failed("LDET.1.10", _),
        RB = decode_failed("LDET.1.10", _)
    then
        true
    else
        io.format("  note: cut %d (last boundary %d) misread\n",
            [i(K), i(B)], !IO),
        !:Bad = [K | !.Bad]
    ).

    % The reader against the writer: encode a stream, decode it back, check
    % the events survive. Both halves are this runtime's, so agreement shows
    % they share a convention; a replay of a recording libds wrote is the
    % stronger test.
    %
    % Fact asserts, retracts and clock ticks come back; `RuleFireAnnotation`
    % and `CallIssued` do not, because both carry a `fire_id` whose
    % `intern_ref` half means something only in the table that minted it.
    % Their absence is asserted.
    %
:- pred test_rfcs_reader(tally::in, tally::out, io::di, io::uo) is det.

test_rfcs_reader(!T, !IO) :-
    intern("Reading", NameRef, init_interns, IT1),
    intern("kitchen", ZoneRef, IT1, IT2),
    intern("my_rule", RuleRef, IT2, IT),
    Slots = [rslot(0, k_int), rslot(1, k_string), rslot(2, k_float)],
    Schema = schema(make_schema_id(1u32), make_schema_name(NameRef),
        lc_logical(Slots, no), no, no),
    Ctx = rfcs_ctx([Schema], IT),
    Meta = stream_meta(ds.version.ds_version, [], [], [], "", ""),
    Fire = fire_id(make_timetag(9u64), RuleRef),

    % A negative float and an interned string.
    Values = [int(42i64), str(ZoneRef), float(-0.25)],
    Records = [
        {make_seq(0u64), se_fact_assert(make_fact_id(11u64),
            make_schema_id(1u32), Values, no)},
        {make_seq(1u64), se_fact_retract(make_fact_id(11u64))},
        % A wall sample before the epoch: `int64`, so a negative writes ten
        % bytes and must read back negative, not as a huge positive.
        {make_seq(2u64), se_clock_tick(from_ns(5000u64), yes(-7000i64))},
        {make_seq(3u64), se_fire_begin(Fire)}
    ],
    encode_stream(Meta, Ctx, from_ns(0u64), Records, Bytes, Unencodable),
    check("the stream encodes with nothing left over",
        ( if Unencodable = [] then yes else no ), !T, !IO),

    % The struck header field 15, `fire_cadence`, is skipped, not refused: an
    % unknown field inside a known atom's body is skipped ([RFCS.16.3],
    % [RFCS.22]), so a header that sets it decodes like any other.
    put_string(10u32, ds.version.ds_version, init_builder, H1),
    put_uint32(15u32, 1u32, H1, H2),
    put_delimited(258u32, builder_bytes(H2), init_builder, HA),
    put_delimited(1u32, builder_bytes(HA), init_builder, HF),
    ( if
        list.drop(list.length(encode_header(Meta)), Bytes, AfterHeader)
    then
        decode_stream(from_bytes(list.map(uint8.cast_to_int,
            builder_bytes(HF) ++ AfterHeader)), init_interns, CadenceResult),
        check("[RFCS.22] a header carrying the struck field 15 decodes",
            ( if CadenceResult = decoded(_) then yes else no ), !T, !IO)
    else
        check("the stream begins with its header", no, !T, !IO)
    ),

    % [RFCS.19.3]: a field number with no registry entry names no member of
    % `Atom`'s oneof, wherever it lies. Each case is the good stream with one
    % empty unknown atom appended, and each refuses the stream: 15 and field
    % 0, what zero-fill decodes as, with a one-byte tag, and 200 and 2047 with
    % a two-byte one.
    list.foldl2(
        (pred(Case::in, T0::in, T1::out,
                IO0::di, IO1::uo) is det :-
            Case = {Field, Label},
            WithUnknown = from_bytes(list.map(uint8.cast_to_int, Bytes)
                ++ [0x0a, 2, Field * 8 + 2, 0]),
            decode_stream(WithUnknown, init_interns, UR),
            check(Label,
                ( if UR = decode_failed("RFCS.19.3", _) then yes else no ),
                T0, T1, IO0, IO1)),
        [{15, "[RFCS.19.3] an unknown atom (15) refuses the stream"},
         {0, "[RFCS.19.3] field 0 is no atom and refuses the stream"}],
        !T, !IO),
    list.foldl2(
        (pred(Case2::in, T0::in, T1::out,
                IO0::di, IO1::uo) is det :-
            Case2 = {B0, B1, Label},
            WithUnknown = from_bytes(list.map(uint8.cast_to_int, Bytes)
                ++ [0x0a, 3, B0, B1, 0]),
            decode_stream(WithUnknown, init_interns, UR),
            check(Label,
                ( if UR = decode_failed("RFCS.19.3", _) then yes else no ),
                T0, T1, IO0, IO1)),
        [{0xc2, 0x0c, "[RFCS.19.3] an unknown atom (200) refuses the stream"},
         {0xfa, 0x7f, "[RFCS.19.3] an unknown atom (2047) refuses the stream"}],
        !T, !IO),

    % [RFCS.19.3] between two known atoms, as libds's test_rfcs_replay and
    % test_rfcs_codec pin it: after the StreamHeader, ahead of the events.
    % The atom is hand-framed at an unallocated number with the body field
    % 1 = 1, at 322 and at 100: each refuses the stream where it stands.
    % Path: `read_frames`'s unknown-atom arm.
    ( if
        list.split_list(list.length(encode_header(Meta)), Bytes,
            PlantHdr, PlantRest),
        PlantRest = [_ | _]
    then
        Planted = (func(Mid) = from_bytes(list.map(uint8.cast_to_int, PlantHdr)
            ++ Mid ++ list.map(uint8.cast_to_int, PlantRest))),
        decode_stream(Planted([]), init_interns, Plain),
        check("the stream with nothing planted decodes",
            ( if Plain = decoded(_) then yes else no ), !T, !IO),
        decode_stream(Planted([0x0a, 5, 0x92, 0x14, 2, 8, 1]), init_interns,
            At322),
        check("[RFCS.19.3] an unknown atom (322) between two known atoms "
                ++ "refuses the stream",
            ( if At322 = decode_failed("RFCS.19.3", _) then yes else no ),
            !T, !IO),
        decode_stream(Planted([0x0a, 5, 0xa2, 0x06, 2, 8, 1]), init_interns,
            At100),
        check("[RFCS.19.3] an unknown atom (100) between two known atoms "
                ++ "refuses the stream",
            ( if At100 = decode_failed("RFCS.19.3", _) then yes else no ),
            !T, !IO)
    else
        check("[RFCS.19.3] the stream has atoms after its header", no, !T, !IO)
    ),

    % [RFCS.19.2] / [RFCS.19.8]: the incremental reader, cut at every byte. A
    % recording being written, or cut off by a crash, is a prefix of a valid
    % stream. `decode_stream_prefix` must read every complete atom in it and
    % report the rest as a tail, never an error, while `decode_stream`, told
    % the buffer is the whole stream, refuses exactly the cuts that fall
    % inside an atom. libds's `test_rfcs_chunked` pins the same property.
    FullBM = from_bytes(list.map(uint8.cast_to_int, Bytes)),
    decode_stream_prefix(FullBM, init_interns, FullR, FullTail),
    check("[RFCS.19.2] the uncut stream reads whole, with no tail",
        ( if FullR = decoded(_), FullTail = 0 then yes else no ), !T, !IO),
    % Where each frame starts, from the framing alone; each start is also
    % where the frame before it ends.
    Starts = frame_starts(init_reader(FullBM)),
    Bounds = Starts ++ [list.length(Bytes)],
    list.foldl2(check_cut(Bytes, Bounds), 0 .. list.length(Bytes),
        [], BadCuts, !IO),
    check("[RFCS.19.2] every cut reads its complete atoms and reports the tail",
        ( if BadCuts = [], list.length(Starts) >= 3 then yes else no ),
        !T, !IO),

    % A frame no append can repair is refused by both readers. The last
    % atom's container tag, 0x0a, becomes 0x0b: field 1 as a start-group, a
    % wire type proto3 does not have.
    ( if
        list.last(Starts, LastStart),
        list.split_list(LastStart, Bytes, Head, [0x0au8 | Rest])
    then
        Corrupt = from_bytes(list.map(uint8.cast_to_int,
            Head ++ [0x0bu8 | Rest])),
        decode_stream_prefix(Corrupt, init_interns, CR, _),
        check("[RFCS.19.2] a malformed frame is refused, not taken as a tail",
            ( if CR = decode_failed(_, LastStart) then yes else no ), !T, !IO)
    else
        check("[RFCS.19.2] the malformed-frame case found its frame", no,
            !T, !IO)
    ),

    % [RFCS.10.1] `has_wall`: a wall clock at the epoch is a value and an
    % unset one is not, though proto3 writes no `wall_ns` for either.
    encode_stream(Meta, Ctx, from_ns(0u64),
        [{make_seq(0u64), se_clock_tick(from_ns(1u64), yes(0i64))},
         {make_seq(1u64), se_clock_tick(from_ns(2u64), no)}],
        WallBytes, _),
    decode_stream(from_bytes(list.map(uint8.cast_to_int, WallBytes)),
        init_interns, WallResult),
    check("[RFCS.10.1] the epoch reads back set, and unset reads back unset",
        ( if
            WallResult = decoded(WDS),
            list.map((func({_, WE}) = WE), WDS ^ dsm_events) =
                [se_clock_tick(_, yes(0i64)), se_clock_tick(_, no)]
          then yes else no ), !T, !IO),

    BM2 = from_bytes(list.map(uint8.cast_to_int, Bytes)),
    decode_stream(BM2, init_interns, Decoded),
    (
        Decoded = decode_failed(Clause, Offset),
        io.format("  note: decode failed %s at %d\n",
            [s(Clause), i(Offset)], !IO),
        check("the written stream decodes", no, !T, !IO)
    ;
        Decoded = unannounced_schema(_, _, Offset),
        io.format("  note: decode stopped RFCS.5.4 at %d\n", [i(Offset)], !IO),
        check("the written stream decodes", no, !T, !IO)
    ;
        Decoded = decoded(DS),
        check("the written stream decodes", yes, !T, !IO),
        check("the header round-trips",
            ( if DS ^ dsm_meta ^ sm_ds_version = ds.version.ds_version
              then yes else no ), !T, !IO),
        Events = list.map((func({_, E}) = E), DS ^ dsm_events),
        check("assert, retract and tick survive; RuleFireAnnotation does not",
            ( if Events = [se_fact_assert(_, _, _, _), se_fact_retract(_),
                           se_clock_tick(_, _)]
              then yes else no ), !T, !IO),
        % [RFCS.7.5]: the FactRetract carries the retract event's own seq, so
        % the retraction reads back at its place in the stream: 1 here,
        % between the assert's 0 and the tick's 2.
        check("RFCS.7.5: the retract's seq round-trips through the FactRetract",
            ( if DS ^ dsm_events = [{make_seq(0u64), _},
                                    {make_seq(1u64), se_fact_retract(_)} | _]
              then yes else no ), !T, !IO),
        check("[RFCS.10.3] both clocks of a ClockAdvance round-trip, a negative wall "
            ++ "sample included",
            ( if list.last(Events, se_clock_tick(To, Wall)),
                 To = from_ns(5000u64), Wall = yes(-7000i64)
              then yes else no ), !T, !IO),
        ( if Events = [se_fact_assert(RId, _, RValues, _) | _] then
            check("the fact id round-trips",
                ( if RId = make_fact_id(11u64) then yes else no ), !T, !IO),
            % The values are compared through the reader's own table: a
            % String value is an `intern_ref`, and the reader minted its own.
            check("Int and Float slot values round-trip exactly",
                ( if RValues = [int(42i64), _, float(-0.25)] then yes else no ),
                !T, !IO),
            check("the String slot value round-trips as TEXT",
                ( if RValues = [_, str(R), _],
                     expand(DS ^ dsm_interns, R, "kitchen")
                  then yes else no ), !T, !IO)
        else
            check("the decoded stream starts with the assert", no, !T, !IO)
        )
    ).

    % [RFCS.6.3]: a nullable slot has presence in a fact body. Two
    % facts over one schema, an `Int` key beside a `Float?` and a `String?`:
    %   A: x = null, s = ""    -> x absent, s PRESENT and empty
    %   B: x = 0.0,  s = null  -> x PRESENT (+0.0), s absent
    % Each body is pinned byte for byte, the bytes libds's `test_rfcs_fact`
    % pins, and a stream carrying both decodes back to exactly what was
    % asserted. Path: `ds.rfcs.encode_slots` / `rfcs_6_3_encode_present` out,
    % `read_fcem` / `rebuild` in, with the recorded Slot atoms' `nullable`
    % flag deciding what an absent field means.
    %
:- pred test_rfcs_nullable(tally::in, tally::out, io::di, io::uo) is det.

test_rfcs_nullable(!T, !IO) :-
    intern("Maybe", NameRef, init_interns, IT1),
    intern("", EmptyRef, IT1, IT),
    Slots = [rslot(0, k_int),
             nslot(1, k_float),
             nslot(2, k_string)],
    Schema = schema(make_schema_id(7u32), make_schema_name(NameRef),
        lc_logical(Slots, no), no, no),
    Ctx = rfcs_ctx([Schema], IT),
    Meta = stream_meta(ds.version.ds_version, [], [], [], "", ""),
    A = [int(3i64), null, str(EmptyRef)],
    B = [int(4i64), float(0.0), null],
    ( if
        encode_fact_body(Ctx, Schema, A, ABytes),
        encode_fact_body(Ctx, Schema, B, BBytes)
    then
        check("[RFCS.6.3] A: a null x is absent, a \"\" s is a present empty "
                ++ "field",
            ( if list.map(uint8.cast_to_int, ABytes) = [0x08, 0x03, 0x1A, 0x00]
              then yes else no ), !T, !IO),
        check("[RFCS.6.3] B: a nullable +0.0 is written, a null s is absent",
            ( if list.map(uint8.cast_to_int, BBytes)
                    = [0x08, 0x04, 0x11, 0, 0, 0, 0, 0, 0, 0, 0]
              then yes else no ), !T, !IO)
    else
        check("[RFCS.6.3] both nullable fact bodies encode", no, !T, !IO)
    ),
    Records = [
        {make_seq(0u64), se_fact_assert(make_fact_id(11u64),
            make_schema_id(7u32), A, no)},
        {make_seq(1u64), se_fact_assert(make_fact_id(12u64),
            make_schema_id(7u32), B, no)}
    ],
    encode_stream(Meta, Ctx, from_ns(0u64), Records, Bytes, Unencodable),
    check("[RFCS.6.3] a stream with null and zero nullable slots encodes whole",
        ( if Unencodable = [] then yes else no ), !T, !IO),
    ( if
        decode_stream(from_bytes(list.map(uint8.cast_to_int, Bytes)),
            init_interns, decoded(DS)),
        DS ^ dsm_events = [{_, se_fact_assert(_, _, DA, _)},
                           {_, se_fact_assert(_, _, DB, _)}]
    then
        check("[RFCS.6.3] A decodes as asserted: x null, s the empty string",
            ( if
                DA = [int(3i64), null, str(R)],
                expand(DS ^ dsm_interns, R, "")
              then yes else no ), !T, !IO),
        check("[RFCS.6.3] B decodes as asserted: x 0.0, s null",
            ( if DB = [int(4i64), float(F), null], F = 0.0
              then yes else no ), !T, !IO)
    else
        check("[RFCS.6.3] the stream decodes to its two asserts", no, !T, !IO)
    ),
    % The temporal kinds have presence too ([RDSC.5.5.8]: Int-represented). A
    % `Time?` at the epoch is a present zero, written as field 2's varint 0;
    % a null `Duration?` is absent.
    C = [int(5i64), int(0i64), null],
    TSlots = [rslot(0, k_int), nslot(1, k_time), nslot(2, k_duration)],
    TSchema = schema(make_schema_id(8u32), make_schema_name(NameRef),
        lc_logical(TSlots, no), no, no),
    TCtx = rfcs_ctx([TSchema], IT),
    ( if encode_fact_body(TCtx, TSchema, C, CBytes) then
        check("[RFCS.6.3] a nullable Time at the epoch is written, a null "
                ++ "Duration is absent",
            ( if list.map(uint8.cast_to_int, CBytes) = [0x08, 0x05, 0x10, 0x00]
              then yes else no ), !T, !IO)
    else
        check("[RFCS.6.3] a fact with nullable temporal slots encodes", no,
            !T, !IO)
    ),
    encode_stream(Meta, TCtx, from_ns(0u64),
        [{make_seq(0u64), se_fact_assert(make_fact_id(13u64),
            make_schema_id(8u32), C, no)}], TBytes, TUnencodable),
    ( if
        TUnencodable = [],
        decode_stream(from_bytes(list.map(uint8.cast_to_int, TBytes)),
            init_interns, decoded(TDS)),
        TDS ^ dsm_events = [{_, se_fact_assert(_, _, DC, _)}]
    then
        check("[RFCS.6.3] the temporal fact decodes as asserted: Time 0, "
                ++ "Duration null",
            ( if DC = [int(5i64), int(0i64), null] then yes else no ), !T, !IO)
    else
        check("[RFCS.6.3] the temporal fact records and decodes", no, !T, !IO)
    ).

    % A nullable, payload slot: what a `T?` `mutable` declaration becomes.
    %
:- func nslot(int, slot_kind) = logical_slot.

nslot(Ix, Kind) =
    logical_slot(
        slot_common(make_intern_ref(1u32), Kind, S, nullable, no, no, no,
            unbounded, no),
        role_mutable, exact) :-
    ( if slot_index(uint32.det_from_int(Ix), S0) then
        S = S0
    else
        unexpected($pred, "slot index")
    ).

:- func rslot(int, slot_kind) = logical_slot.

rslot(Ix, Kind) =
    logical_slot(
        slot_common(make_intern_ref(1u32), Kind, S, non_null, no, no, no, unbounded, no),
        role_key, exact) :-
    ( if slot_index(uint32.det_from_int(Ix), S0) then
        S = S0
    else
        unexpected($pred, "slot index")
    ).

    % [RDSC.16.2.8]: `requires` is trusted: the runtime compares it only
    % against its build ([RDSC.16.2.7]), never against what the content uses. The compiled `07_action_verbs` uses verbs
    % `requires` names; re-framed with its CapabilityInfo's `requires` emptied
    % (and `enabled` kept, so [RDSC.16.2.3]'s shape still holds), it still
    % loads. The re-framed artefact is resealed, or [RDSC.3.6] refuses it
    % first and the check reaches nothing.
    %
:- pred test_rdsc_16_2_8(tally::in, tally::out, io::di, io::uo) is det.

test_rdsc_16_2_8(!T, !IO) :-
    io.open_binary_input("fixtures/07_action_verbs.dsc", OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, Res, !IO),
        io.close_binary_input(Stream, !IO)
    ;
        OpenRes = error(OpenErr),
        Res = error(OpenErr)
    ),
    ( if
        Res = ok(BM),
        load_dsc(BM, loaded(P)),
        capb_of(P) = capb(Enabled, Requires)
    then
        % The positive control: without it, a fixture that needed nothing would
        % pass the refusal below vacuously.
        check("[RDSC.16.2.8] 07_action_verbs requires `call`",
            ( if set.contains(Requires, cap_call) then yes else no ), !T, !IO),
        EnabledNs = list.map(capability_number, ascending(Enabled)),
        replace_capb(list.map(uint8.det_from_int, packed(0x12, EnabledNs)),
            init_reader(BM), init_builder, Rebuilt),
        check("[RDSC.16.2.8] ...and with `requires` emptied it still loads",
            ( if
                load_dsc(sealed(list.map(uint8.to_int,
                    builder_bytes(Rebuilt))), loaded(PEmpty)),
                capb_of(PEmpty) = capb(_, RequiresEmpty),
                set.is_empty(RequiresEmpty)
              then yes else no ), !T, !IO)
    else
        check("[RDSC.16.2.8] 07_action_verbs.dsc loads", no, !T, !IO)
    ).

    % `reframe`, with the CapabilityInfo atom's body replaced.
    %
:- pred replace_capb(list(uint8)::in, reader::in, builder::in, builder::out)
    is det.

replace_capb(Capb, R0, B0, B) :-
    next_frame(Result, R0, R1),
    ( if Result = fr_ok(F) then
        Ref = F ^ fr_atom,
        (
            Ref = known(A),
            Field = atom_field(A)
        ;
            Ref = unknown(Field)
        ),
        Body = ( if Field = 265u32 then Capb else reader_bytes(F ^ fr_body) ),
        put_delimited(Field, Body, init_builder, Inner),
        put_message(1u32, Inner, B0, B1),
        replace_capb(Capb, R1, B1, B)
    else
        B = B0
    ).

    % Walk every frame and re-emit it through the encoder.
    %
:- pred reframe(reader::in, builder::in, builder::out, frame_result::out)
    is det.

reframe(R0, B0, B, Outcome) :-
    next_frame(Result, R0, R1),
    (
        Result = fr_ok(F),
        % Both levels are rebuilt: `fr_body` is bounded to the innermost
        % payload, past the outer and the inner `oneof` tag and length.
        % Rebuilding the inner tag from the atom's identity also puts
        % `put_tag` under test.
        %
        % Bound to a variable first so this is a switch and stays `det`.
        Ref = F ^ fr_atom,
        (
            Ref = known(A),
            Field = atom_field(A)
        ;
            Ref = unknown(Field)
        ),
        put_delimited(Field, reader_bytes(F ^ fr_body), init_builder, Inner),
        put_message(1u32, Inner, B0, B1),
        reframe(R1, B1, B, Outcome)
    ;
        Result = fr_eof,
        B = B0, Outcome = fr_eof
    ;
        Result = fr_error(E, Off),
        B = B0, Outcome = fr_error(E, Off)
    ).

    % Semidet, because `bitmap.num_bytes` is: a bitmap whose length is not a
    % whole number of bytes has no byte list.
    %
:- pred bitmap_bytes(bitmap::in, list(uint8)::out) is semidet.

bitmap_bytes(BM, Bytes) :-
    N = bitmap.num_bytes(BM),
    bitmap_bytes_loop(BM, 0, N, [], Rev),
    list.reverse(Rev, Bytes).

:- pred bitmap_bytes_loop(bitmap::in, int::in, int::in,
                          list(uint8)::in, list(uint8)::out) is det.

bitmap_bytes_loop(BM, I, N, !Acc) :-
    ( if I < N then
        !:Acc = [uint8.cast_from_int(bitmap.byte(I, BM)) | !.Acc],
        bitmap_bytes_loop(BM, I + 1, N, !Acc)
    else
        true
    ).

    % Index of the first differing byte, or -1 if one is a prefix of the other.
    %
:- func first_diff(list(uint8), list(uint8), int) = int.

first_diff([], _, _) = -1.
first_diff([_ | _], [], _) = -1.
first_diff([A | As], [B | Bs], I) =
    ( if A = B then first_diff(As, Bs, I + 1) else I ).

    % A copy with one byte changed, near the end so the header survives.
    %
:- pred flip_a_byte(bitmap::in, bitmap::out) is semidet.

flip_a_byte(BM0, BM) :-
    N = bitmap.num_bytes(BM0),
    N > 8,
    I = N - 4,
    Old = bitmap.byte(I, BM0),
    bitmap.set_uint8(I, uint8.cast_from_int((Old + 1) /\ 0xFF),
        bitmap.copy(BM0), BM).

:- pred all_known(list(atom_ref)::in) is semidet.

all_known([]).
all_known([known(_) | As]) :- all_known(As).

    % A retired atom number: no registry entry.
    %
:- pred retired_magic(uint32::in) is semidet.

retired_magic(N) :-
    not atom_of_field(N, _).

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% ds.effect -- the spine
%-----------------------------------------------------------------------------%

:- func a_fire_id = fire_id.

a_fire_id = fire_id(make_timetag(7u64), make_intern_ref(1u32)).

:- pred test_effect_log(tally::in, tally::out, io::di, io::uo) is det.

test_effect_log(!T, !IO) :-
    check("an empty log is empty",
        ( if log_effects(empty_log) = [] then yes else no ), !T, !IO),

    % Emission order is preserved. The accumulator builds in reverse, and the
    % abstraction is what stops a caller seeing that and prepending.
    some [!L] (
        !:L = empty_log,
        emit_event(se_clock_tick(from_ns(1u64), no), !L),
        emit_event(se_clock_tick(from_ns(2u64), no), !L),
        emit_event(se_clock_tick(from_ns(3u64), no), !L),
        check("emission order is preserved",
            ( if log_effects(!.L) =
                    [eff_event(se_clock_tick(A, _)), _,
                     eff_event(se_clock_tick(C, _))],
                 instant_ns(A) = 1u64, instant_ns(C) = 3u64
              then yes else no ), !T, !IO),
        check("length tracks emission",
            ( if log_length(!.L) = 3 then yes else no ), !T, !IO)
    ),

    % [RARC.5.8.12] -- the record precedes the callback, and `acted/4` is the
    % only way to emit an action with its event, so there is no wrong order to
    % write.
    some [!L2] (
        !:L2 = empty_log,
        acted(se_log_emitted(log_critical, "x"), a_log(log_critical, e_now), !L2),
        check("acted emits the EVENT first, then the action",
            ( if log_effects(!.L2) = [eff_event(_), eff_action(_)]
              then yes else no ), !T, !IO)
    ).

:- pred test_firing_frame(tally::in, tally::out, io::di, io::uo) is det.

test_firing_frame(!T, !IO) :-
    Id = a_fire_id,
    Body = [eff_event(se_log_emitted(log_critical, "x")),
            eff_action(a_log(log_critical, e_now))],

    F = firing(Id, yes([make_fact_id(1u64)]), Body),

    % The LHS event comes first and sits outside the bracket, adjacent to the
    % begin: what `firing_event_frame.als`'s "atomically" means.
    check("the LHS facts come FIRST, as their own event",
        ( if F = [eff_event(se_rule_lhs_facts(_, [_])) | _] then yes else no ),
        !T, !IO),
    check("then the bracket opens",
        ( if F = [_, eff_event(se_fire_begin(_)) | _] then yes else no ),
        !T, !IO),
    check("FIRE_END is last, unconditionally",
        ( if list.last(F, Last), Last = eff_event(se_fire_end(_))
          then yes else no ), !T, !IO),
    check("and the body sits inside the bracket, in order",
        ( if F = [_, _, eff_event(se_log_emitted(_, _)), eff_action(_), _]
          then yes else no ), !T, !IO),

    % `no` is the conditionality the model states -- a firing that matched no
    % live fact -- and it means no LHS event at all rather than a begin
    % carrying `no`.
    G = firing(Id, no, []),
    check("a firing matching no live fact emits no LHS event",
        ( if G = [eff_event(se_fire_begin(_)),
                  eff_event(se_fire_end(_))]
          then yes else no ), !T, !IO),
    check("an empty body still gets a complete bracket",
        ( if list.length(G) = 2 then yes else no ), !T, !IO).

:- pred test_recorder(tally::in, tally::out, io::di, io::uo) is det.

test_recorder(!T, !IO) :-
    check("a fresh recorder has issued nothing",
        ( if record_count(init_recorder) = 0 then yes else no ), !T, !IO),

    some [!R] (
        !:R = init_recorder,
        record(se_clock_tick(from_ns(1u64), no), S0, !R),
        record(se_clock_tick(from_ns(2u64), no), S1, !R),
        record(se_clock_tick(from_ns(3u64), no), S2, !R),

        % `stream_seq.tla`: starts at zero, strictly increasing, contiguous.
        % The k-th record carries seq k-1.
        check("seq starts at 0",
            ( if seq_value(S0) = 0u64 then yes else no ), !T, !IO),
        check("seq is contiguous",
            ( if seq_value(S1) = 1u64, seq_value(S2) = 2u64
              then yes else no ), !T, !IO),
        check("the counter equals the record count",
            ( if record_count(!.R) = 3,
                 list.length(records(!.R)) = 3
              then yes else no ), !T, !IO),
        check("records come back in seq order",
            ( if records(!.R) = [{F, _} | _], seq_value(F) = 0u64
              then yes else no ), !T, !IO)
    ).

    % No allocate-then-discard path exists: `record/4` is the only producer of
    % a `seq`, and it appends in the same step. No test can assert the absence
    % of an operation, so add no `allocate_seq`.

:- pred test_replay_gate(tally::in, tally::out, io::di, io::uo) is det.

test_replay_gate(!T, !IO) :-
    % [RFCS.3.4]: "a `call` is never a replay input." Both failure modes are
    % silent: delivering a compare-class atom corrupts determinism, skipping an
    % inject-class one drops a real input.
    check("a fact assert is deliverable",
        ( if deliverable(se_fact_assert(make_fact_id(1u64),
                make_schema_id(1u32), [], no))
          then yes else no ), !T, !IO),
    check("a clock advance is deliverable",
        ( if deliverable(se_clock_advance(from_ns(1u64))) then yes else no ),
        !T, !IO),
    % The service is a bare name here: `ActionCall` carries no `module_id`, so
    % neither can the event recording it.
    check("a CallIssued is NOT deliverable",
        ( if deliverable(se_call_issued(a_fire_id, make_intern_ref(1u32),
                correlated(make_intern_ref(2u32)), [], co_call_verb))
          then no else yes ), !T, !IO),
    % A derived retraction delivered as a host input would double-retract.
    check("an engine withdrawal is NOT deliverable",
        ( if deliverable(se_fact_withdraw(make_fact_id(1u64), rc_ttl))
          then no else yes ), !T, !IO),
    check("a rule firing annotation is NOT deliverable",
        ( if deliverable(se_fire_end(a_fire_id)) then no else yes ), !T, !IO),
    check("an engine error is NOT deliverable",
        ( if deliverable(se_engine_error(ee_duplicate_order_key, no_site))
          then no else yes ), !T, !IO),

    % CacheGet has no constructor at all, so "cache_get is re-derived on replay
    % rather than recorded" [RARC.5.7.9] cannot be broken by emitting one.
    check("a cache SET is compare-class, not inject",
        ( if event_class(se_cache_set("k", "1", no)) = compare then yes
          else no ),
        !T, !IO).

:- func a_module = module_id.

a_module = M :-
    ( if module_id(1u32, M0) then M = M0 else unexpected($pred, "module_id 1") ).

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% ds.dsc -- the loader
%-----------------------------------------------------------------------------%

    % A minimal well-formed DscHeader frame: outer 0A len; inner BA 10 (field 263)
    % len; then the DscHeader body -- `compiler_version` and a 32-byte
    % dsc_sha256.
    %
    % The version must be in this runtime's series [LDET.1.10], so it is
    % taken from `ds.version` rather than spelled.
    %
:- func dsco_frame = list(int).

dsco_frame = dsco_frame_ver(ds.version.ds_version).

    % The same, stamping a chosen `compiler_version`.
    %
:- func dsco_frame_ver(string) = list(int).

dsco_frame_ver(Ver) = dsco_only_ver(Ver) ++ capb_frame.

    % The header atom alone, with no CapabilityInfo after it: what
    % [RDSC.16.2.4] refuses.
    %
:- func dsco_only_ver(string) = list(int).

dsco_only_ver(Ver) = dsco_atom(dsco_base(Ver)).

    % A DscHeader body (field 263, tag BA 10) in the two-level framing, both
    % lengths as varints: a header is near 128 bytes, so a one-byte length
    % would not do.
    %
:- func dsco_atom(list(int)) = list(int).

dsco_atom(Body) = Outer :-
    Atom = [0xBA, 0x10] ++ varint(list.length(Body)) ++ Body,
    Outer = [0x0A] ++ varint(list.length(Atom)) ++ Atom.

    % A non-negative int as a protobuf varint.
    %
:- func varint(int) = list(int).

varint(N) =
    ( if N < 0x80 then
        [N]
    else
        [(N /\ 0x7F) \/ 0x80 | varint(N >> 7)]
    ).

    % An empty CapabilityInfo atom (265): nothing enabled, nothing required.
    % Well-formed by [RDSC.16.2.3] and required by [RDSC.16.2.4], so every
    % `dsco_frame*` helper emits one after the header.
    %
:- func capb_frame = list(int).

capb_frame = frame(265, []).

    % A CapabilityInfo atom carrying `enabled` (field 2) and `requires` (field
    % 3), each packed as proto3 writes a `repeated` enum.
    %
:- func capb_frame_of(list(int), list(int)) = list(int).

capb_frame_of(Enabled, Requires) = frame(265, packed(0x12, Enabled)
    ++ packed(0x1A, Requires)).

:- func packed(int, list(int)) = list(int).

packed(_, []) = [].
packed(Tag, Vs @ [_ | _]) = [Tag, list.length(Vs) | Vs].

    % Fields 1 and 2 are emitted on purpose: both are `reserved` under
    % [LDET.1.10], so every loader test's frame carries unknown fields.
    %
:- func dsco_base(string) = list(int).

dsco_base(Ver) = dsco_base_no_binding(Ver) ++ def_sha_field(32).

    % The same, without `dialect_def_sha256`: what [RDSC.3.7] refuses.
    %
:- func dsco_base_no_binding(string) = list(int).

dsco_base_no_binding(Ver) =
    [0x08, 0x04,             % field 1 varint       (RESERVED)
     0x10, 0x05]             % field 2 varint       (RESERVED)
    ++ compiler_version_field(Ver)
    ++ [0x30, 0x01,          % field 6 varint = 1   (RESERVED)
        0x3A, 0x20]          % field 7, len 32      (dsc_sha256)
    ++ list.duplicate(32, 0x00).

    % `dialect_def_sha256` (field 10, bytes) of `N` bytes. Tag 10<<3|2 = 0x52.
    % [RDSC.3.7] requires 32, so every loader test's header carries 32 and a
    % test about the rule appends another: a bytes field is last-wins under
    % protobuf, in both runtimes' decoders.
    %
:- func def_sha_field(int) = list(int).

def_sha_field(N) = [0x52, N] ++ list.duplicate(N, 0xD5).

    % The same, with one header field overridden.
    %
:- func dsco_frame_with(int, int) = list(int).

dsco_frame_with(Tag, Val) =
    dsco_atom(dsco_base(ds.version.ds_version) ++ [Tag, Val]) ++ capb_frame.

    % The same, with arbitrary extra header bytes appended.
    %
:- func dsco_frame_plus(list(int)) = list(int).

dsco_frame_plus(Extra) = dsco_frame_ver_plus(ds.version.ds_version, Extra).

    % Both at once: a chosen `compiler_version` and extra header bytes.
    %
:- func dsco_frame_ver_plus(string, list(int)) = list(int).

dsco_frame_ver_plus(Ver, Extra) =
    dsco_atom(dsco_base(Ver) ++ Extra) ++ capb_frame.

    % `compiler_version` (field 3, string) carrying `S`. Tag 3<<3|2 = 0x1a.
    %
:- func compiler_version_field(string) = list(int).

compiler_version_field(S) = [0x1a] ++ varint(string.length(S)) ++
    list.map(char.to_int, string.to_char_list(S)).

    % The reserved field 12 as a string carrying `S`. Tag 12<<3|2 = 0x62.
    %
:- func retired_unicode_field(string) = list(int).

retired_unicode_field(S) = [0x62, string.length(S)] ++
    list.map(char.to_int, string.to_char_list(S)).

    % `capabilities` (field 13, repeated Capability, packed as proto3 writes
    % it) carrying `Cs`, each below 128 so one varint byte. Tag 13<<3|2 = 0x6A.
    %
:- func caps_field(list(int)) = list(int).

caps_field(Cs) = [0x6A, list.length(Cs)] ++ Cs.

    % A fixture whose `Calls` `CallExpr`s name `Op`, at `Site`, with that op
    % rewritten to `To`: refused at load with DS_ERR_FN_NOT_FOUND citing
    % [RDSC.4a.9.3] when this runtime has no handler for `To` there
    % (`edit_refused`), and loaded when it has one (`edit_loads`).
    %
    % Edited, because no source reaches it: the compiler emits each op only
    % where a clause has it. A runtime holds a handler for an op at a site
    % ([RDSC.4a.9.3]), and this one's are positional: a verb or a bind's op
    % has none in an expression, where libds, whose handlers run anywhere,
    % loads it. libds's counterpart is
    % `test_rdsc_4a_9_3__only_an_op_with_no_handler_is_refused`. Neither
    % outcome checks the operand count: the rewrite keeps the fixture's.
    %
    % The edit must hit the call and nothing else. `op` is `CallExpr` field
    % 3, a varint, so the call is the byte pair `0x18, wire(Op)`, and the
    % rewrite keeps every length. The pair must occur exactly as often as the
    % source calls `Op`: one more is some other message's field 3, such as
    % SchemaSource.line, so a fixture's layout keeps every declaration off a
    % line numbered `wire(Op)`. The control: the unedited fixture loads.
    %
:- type edit_want
    --->    edit_refused
    ;       edit_loads.

:- pred op_rewritten(edit_want::in, string::in, string::in, builtin_fn::in,
                     int::in, {string, int}::in,
                     tally::in, tally::out, io::di, io::uo) is det.

op_rewritten(Want, Site, Fixture, Op, Calls, {ToName, To}, !T, !IO) :-
    io.open_binary_input("fixtures/" ++ Fixture, OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, ReadRes, !IO),
        io.close_binary_input(Stream, !IO)
    ;
        OpenRes = error(OpenErr),
        ReadRes = error(OpenErr)
    ),
    (
        ReadRes = ok(BM),
        load_dsc(BM, Control),
        check("[RDSC.4a.9.3] control: " ++ Fixture ++ " as compiled loads",
            ( if Control = loaded(_) then yes else no ), !T, !IO),
        From = uint32.cast_to_int(builtin_fn_wire(Op)),
        ( if bitmap_bytes(BM, Bytes8) then
            Bytes = list.map(uint8.cast_to_int, Bytes8)
        else
            Bytes = []
        ),
        Hits = pair_count(0x18, From, Bytes),
        check("[RDSC.4a.9.3] " ++ Fixture ++ " carries its "
                ++ string.from_int(Calls) ++ " call(s) to "
                ++ string.string(Op) ++ " as the byte pair edited",
            ( if Hits = Calls then yes else no ), !T, !IO),
        ( if Hits = Calls then
            load_dsc(sealed(replace_pair(0x18, From, To, Bytes)), Load),
            (
                Want = edit_refused,
                check("[RDSC.4a.9.3] " ++ Site ++ " naming " ++ ToName
                        ++ " is refused, DS_ERR_FN_NOT_FOUND (" ++ Fixture
                        ++ ", its call rewritten)",
                    ( if
                        Load = load_failed(E),
                        E ^ le_kind = lek_fn_not_found,
                        clause_id_string(E ^ le_clause) = "RDSC.4a.9.3"
                      then yes else no ), !T, !IO)
            ;
                Want = edit_loads,
                check("[RDSC.4a.9.3] " ++ Site ++ " naming " ++ ToName
                        ++ " loads (" ++ Fixture ++ ", its call rewritten)",
                    ( if Load = loaded(_) then yes else no ), !T, !IO)
            ),
            ( if
                Load = load_failed(Got),
                ( Want = edit_loads ; Got ^ le_kind \= lek_fn_not_found )
            then
                io.format("    %s: refused %s %s\n", [s(Fixture),
                    s(string.string(Got ^ le_kind)),
                    s(clause_id_string(Got ^ le_clause))], !IO)
            else
                true
            )
        else
            io.format("    %s: the pair 0x18, %d occurs %d times\n",
                [s(Fixture), i(From), i(Hits)], !IO)
        )
    ;
        ReadRes = error(Err),
        check(Fixture ++ " readable: " ++ io.error_message(Err), no, !T, !IO)
    ).

    % How many times `A, B` occurs as adjacent bytes.
    %
:- func pair_count(int, int, list(int)) = int.

pair_count(_, _, []) = 0.
pair_count(_, _, [_]) = 0.
pair_count(A, B, [X, Y | Rest]) =
    ( if X = A, Y = B then
        1 + pair_count(A, B, Rest)
    else
        pair_count(A, B, [Y | Rest])
    ).

    % The bytes with every adjacent `A, From` made `A, To`.
    %
:- func replace_pair(int, int, int, list(int)) = list(int).

replace_pair(_, _, _, []) = [].
replace_pair(_, _, _, [X]) = [X].
replace_pair(A, From, To, [X, Y | Rest]) =
    ( if X = A, Y = From then
        [A, To | replace_pair(A, From, To, Rest)]
    else
        [X | replace_pair(A, From, To, [Y | Rest])]
    ).

    % [RBND.1.3]: a header whose `capabilities` list is malformed is refused
    % at load with DS_ERR_DSC_SEMANTIC (-504), citing the clause. Sealed, so
    % the list is the only thing wrong with it.
    %
:- pred malformed_caps_refused({string, list(int)}::in, tally::in, tally::out,
                               io::di, io::uo) is det.

malformed_caps_refused({Name, Caps}, !T, !IO) :-
    check("[RBND.1.3] " ++ Name ++ " in the header's capabilities is refused, "
            ++ "-504",
        ( if load_dsc(sealed(dsco_frame_plus(caps_field(Caps))), load_failed(E)),
             E ^ le_kind = lek_semantic,
             clause_id_string(E ^ le_clause) = "RBND.1.3"
          then yes else no ), !T, !IO).

:- pred test_loader(tally::in, tally::out, io::di, io::uo) is det.

test_loader(!T, !IO) :-
    check("a minimal artefact loads",
        ( if load_dsc(sealed(dsco_frame), loaded(P)),
             header(P) ^ dh_compiler_version = ds.version.ds_version,
             list.length(header(P) ^ dh_sha256) = 32
          then yes else no ), !T, !IO),

    % ── CapabilityInfo -- [RDSC.16.2] ───────────────────────────────────────────────
    Dsco = dsco_only_ver(ds.version.ds_version),
    check("[RDSC.16.2.4] an artefact with no CapabilityInfo is refused",
        ( if load_dsc(sealed(Dsco), load_failed(ENoCapb)),
             ENoCapb ^ le_kind = lek_semantic
          then yes else no ), !T, !IO),
    % A second CapabilityInfo is not checked for ([RDSC.16.2.5], [RDSC.7.2]):
    % it is read as the first, and replaces it.
    check("[RDSC.16.2.5] a second CapabilityInfo is not checked: the last is kept",
        ( if load_dsc(sealed(Dsco ++ capb_frame ++ capb_frame_of([4, 6], [])),
                loaded(PTwo)),
             capb_of(PTwo) = capb(EnabledTwo, _),
             set.to_sorted_list(EnabledTwo) = [cap_logical, cap_regex]
          then yes else no ), !T, !IO),

    % ── DialectInfo -- [RDSC.15] ────────────────────────────────────────────
    % `0x0A, 7, "default"`: field 1, the dialect's name. Never read.
    DialFrame = frame(264, [0x0A, 7, 0x64, 0x65, 0x66, 0x61, 0x75, 0x6C, 0x74]),
    check("[RDSC.15.6] one DialectInfo atom loads",
        ( if load_dsc(sealed(Dsco ++ capb_frame ++ DialFrame), loaded(_))
          then yes else no ), !T, !IO),
    % A second DialectInfo is not checked for ([RDSC.15.6], [RDSC.7.2]), as
    % libds's `test_rdsc_15_6__two_dialect_infos_load`.
    check("[RDSC.15.6] a second DialectInfo is not checked: two atoms load",
        ( if load_dsc(sealed(Dsco ++ capb_frame ++ DialFrame ++ DialFrame),
                loaded(_))
          then yes else no ), !T, !IO),
    check("[RDSC.16.2.2] `enabled` and `requires` decode as settings",
        ( if load_dsc(sealed(Dsco ++ capb_frame_of([4, 6, 8], [6])),
                loaded(PCapb)),
             capb_of(PCapb) = capb(Enabled, Requires),
             set.to_sorted_list(Enabled) =
                [cap_logical, cap_regex, cap_call],
             set.to_sorted_list(Requires) = [cap_regex]
          then yes else no ), !T, !IO),
    check("[RDSC.16.2.3] `enabled` out of order is refused",
        ( if load_dsc(sealed(Dsco ++ capb_frame_of([8, 4], [])),
                load_failed(EOrder)),
             EOrder ^ le_kind = lek_semantic
          then yes else no ), !T, !IO),
    check("[RDSC.16.2.3] a repeated capability is refused",
        ( if load_dsc(sealed(Dsco ++ capb_frame_of([4, 4], [])),
                load_failed(ERep)),
             ERep ^ le_kind = lek_semantic
          then yes else no ), !T, !IO),
    check("[RDSC.16.2.3] CAPABILITY_UNSPECIFIED is refused",
        ( if load_dsc(sealed(Dsco ++ capb_frame_of([0, 4], [])),
                load_failed(EZero)),
             EZero ^ le_kind = lek_semantic
          then yes else no ), !T, !IO),
    check("[RDSC.16.2.3] `requires` outside `enabled` is refused",
        ( if load_dsc(sealed(Dsco ++ capb_frame_of([4], [6])),
                load_failed(ESub)),
             ESub ^ le_kind = lek_semantic
          then yes else no ), !T, !IO),
    % A number this build does not know is a capability it lacks, and that is
    % checked before the shape: 99 is in `requires` and not in `enabled`, and
    % the answer is still -514, naming it.
    check("[RDSC.16.2.7] an unknown required capability is absent, named",
        ( if load_dsc(sealed(Dsco ++ capb_frame_of([4, 99], [99])),
                load_failed(EAbsent)),
             EAbsent ^ le_kind = lek_capability_absent(99)
          then yes else no ), !T, !IO),
    % 12 is `reserved` in `capabilities.proto`: inside the registry's range,
    % and still a number this build does not know. libds's
    % `test_rdsc_16_2__capb` pins the same case.
    check("[RDSC.16.2.7] the reserved 12 required is absent, named",
        ( if load_dsc(sealed(Dsco ++ capb_frame_of([12], [12])),
                load_failed(EReserved12)),
             EReserved12 ^ le_kind = lek_capability_absent(12)
          then yes else no ), !T, !IO),
    % 17 to 19 are `reserved` too: absent, and the lowest of the three named.
    % 20 is `storage_hydrate_facts`, so an artefact enabling it loads. libds
    % pins both.
    check("[RDSC.16.2.7] the reserved 17 to 19 required are absent, 17 named",
        ( if load_dsc(sealed(Dsco ++ capb_frame_of([17, 18, 19],
                    [17, 18, 19])),
                load_failed(E17)),
             E17 ^ le_kind = lek_capability_absent(17)
          then yes else no ), !T, !IO),
    check("[LCAP.1] 20 is `storage_hydrate_facts`, still a member",
        ( if capability_of_number(20, cap_storage_hydrate_facts),
             capability_named("storage_hydrate_facts", Cap20),
             capability_number(Cap20) = 20,
             not capability_named("storage_hydrate_events", _),
             not capability_of_number(17, _),
             load_dsc(sealed(Dsco ++ capb_frame_of([8, 20], [])),
                loaded(_))
          then yes else no ), !T, !IO),
    % [NLFC.10.2]: the admission policy, the libds cases value for value.
    CallTrue = sealed(Dsco ++ capb_frame_of([4, 8], [])),
    check("[NLFC.10.2] call true, admitted true only, loads",
        ( if load_dsc_admitted(map.singleton(cap_call, admit_true_only),
                CallTrue, loaded(_))
          then yes else no ), !T, !IO),
    check("[NLFC.10.2] call true, admitted false only, is refused, named",
        ( if load_dsc_admitted(map.singleton(cap_call, admit_false_only),
                CallTrue, load_failed(ENotAdmitted)),
             ENotAdmitted ^ le_kind = lek_not_admitted(8, yes)
          then yes else no ), !T, !IO),
    check("[NLFC.10.2] call false, admitted true only, is refused",
        ( if load_dsc_admitted(map.singleton(cap_call, admit_true_only),
                sealed(Dsco ++ capb_frame_of([4], [])),
                load_failed(ENotTrue)),
             ENotTrue ^ le_kind = lek_not_admitted(8, no)
          then yes else no ), !T, !IO),
    check("[RDSC.16.2.9] the build's capabilities come before the policy",
        ( if load_dsc_admitted(map.singleton(cap_logical, admit_false_only),
                sealed(Dsco ++ capb_frame_of([4, 99], [99])),
                load_failed(EFirst)),
             EFirst ^ le_kind = lek_capability_absent(99)
          then yes else no ), !T, !IO),
    check("[RDSC.16.2.7] the lowest lacking capability is the one named",
        ( if load_dsc(sealed(Dsco ++ capb_frame_of([98, 99], [98, 99])),
                load_failed(ELow)),
             ELow ^ le_kind = lek_capability_absent(98)
          then yes else no ), !T, !IO),

    % [LDET.1.10]: the struck fields are ignored, not read. The frame above
    % carries fields 1 and 2 as unknown fields and loads; overriding one
    % changes nothing.
    check("a struck header field 1 is ignored, not gated on",
        ( if load_dsc(sealed(dsco_frame_with(0x08, 0x02)), loaded(_))
          then yes else no ), !T, !IO),

    % [LDET.1.10]: another minor series is refused. The probe derives from
    % this runtime's own version, so no release moves it.
    check("an artefact from another minor series is refused",
        ( if load_dsc(sealed(dsco_frame_ver("9" ++ ds.version.ds_version)),
                load_failed(EOther)),
             EOther ^ le_kind = lek_version
          then yes else no ), !T, !IO),

    % An unstamped artefact sits in no series. Under protobuf an absent string
    % and an empty one are the same bytes.
    check("an artefact stamping no version is refused",
        ( if load_dsc(sealed(dsco_frame_ver("")), load_failed(EBlank)),
             EBlank ^ le_kind = lek_version
          then yes else no ), !T, !IO),

    % The same series with a different patch is accepted, so the two
    % refusals above cannot pass against a loader that refuses everything.
    check("the same minor series with another patch loads",
        ( if load_dsc(sealed(dsco_frame_ver(
                    ds.dsc.ds_version_series ++ "99999")), loaded(_))
          then yes else no ), !T, !IO),

    % Field 12 is reserved, and no value of it means anything: an artefact
    % carrying it loads whatever it says, as libds skips it as an unknown
    % field. The compiler version implies the Unicode version ([LNAM.2.2.5]).
    check("a reserved field 12 loads whatever it holds",
        ( if load_dsc(sealed(dsco_frame_plus(retired_unicode_field("16.0.0"))),
                loaded(_)),
             load_dsc(sealed(dsco_frame_plus(retired_unicode_field("15.1.0"))),
                loaded(_)),
             load_dsc(sealed(dsco_frame_plus(retired_unicode_field(""))),
                loaded(_))
          then yes else no ), !T, !IO),

    % [RDSC.3.7]: `dialect_def_sha256` is 32 bytes, or the file is refused
    % with DS_ERR_BND_INCOMPLETE (-703). libds's `test_dsc_basic.c` pins the
    % same three cases (`test_def_sha_*`), so the two runtimes answer alike.
    check("[RDSC.3.7] a 32-byte dialect_def_sha256 loads, and is decoded",
        ( if load_dsc(sealed(dsco_frame), loaded(DefP)),
             list.length(header(DefP) ^ dh_dialect_sha) = 32
          then yes else no ), !T, !IO),
    check("[RDSC.3.7] a 31-byte dialect_def_sha256 is refused, -703",
        ( if load_dsc(sealed(dsco_frame_plus(def_sha_field(31))),
                load_failed(EDef31)),
             EDef31 ^ le_kind = lek_binding_incomplete,
             clause_id_string(EDef31 ^ le_clause) = "RDSC.3.7"
          then yes else no ), !T, !IO),
    check("[RDSC.3.7] a 33-byte dialect_def_sha256 is refused, -703",
        ( if load_dsc(sealed(dsco_frame_plus(def_sha_field(33))),
                load_failed(EDef33)),
             EDef33 ^ le_kind = lek_binding_incomplete
          then yes else no ), !T, !IO),
    NoBinding = dsco_atom(dsco_base_no_binding(ds.version.ds_version)),
    check("[RDSC.3.7] an ABSENT dialect_def_sha256 is refused, -703",
        ( if load_dsc(sealed(NoBinding ++ capb_frame), load_failed(EDef0)),
             EDef0 ^ le_kind = lek_binding_incomplete
          then yes else no ), !T, !IO),
    % [RBND.1.3]: the header's `capabilities` list is strictly
    % ascending over the live members of `Capability`, or the file is refused
    % with DS_ERR_DSC_SEMANTIC. libds's test_dsc_basic.c pins the same cases
    % (`test_rbnd_1_3__malformed_capability_list_refused_at_load`). The
    % control first: ascending live members load, kept as written.
    check("[RBND.1.3] ascending live capabilities load, kept as written",
        ( if load_dsc(sealed(dsco_frame_plus(caps_field([4, 6]))), loaded(CapP)),
             header(CapP) ^ dh_capabilities = [4, 6]
          then yes else no ), !T, !IO),
    list.foldl2(malformed_caps_refused, [
        {"a capability twice", [4, 4]},
        {"two out of order", [6, 4]},
        {"a reserved number (12)", [4, 12]},
        {"an unallocated number (99)", [4, 99]},
        {"CAPABILITY_UNSPECIFIED (0)", [0]}
    ], !T, !IO),
    % [RDSC.4a.9.3]: a `CallExpr` naming an op this runtime has no
    % handler for is `DS_ERR_FN_NOT_FOUND` at load, a fire guard's included,
    % and nothing else about an op is checked. A `where` test, an expression
    % in an action and a fire guard, each with its call edited: see
    % `op_rewritten`. Every op is one wire byte, so the edit keeps every
    % length.
    Unhandled = [
        {"a reserved number (42)", 42},
        {"FN_UPPER (66), a tombstone", 66},
        {"FN_BIT_AND (59), which lowers to a BinOp", 59},
        {"100, `reserved`", 100},
        % No expression handler here, and one in libds ([RDSC.4a.9.3]: a
        % handler is held at a site): the pure evaluator performs no effect,
        % and `FN_GENSYM`'s handler is the executor's bind.
        {"FN_LOG (47), a verb", 47},
        {"FN_GENSYM (111), a bind's op", 111},
        % No handler at any site: `FN_JSON_BUILD` is a hydration body's op,
        % and this runtime has none for hydration, so it is refused here at
        % load whatever its count. libds holds one and judges the count when
        % it runs (`test_rete_builtins`). The clause takes both: "refused by a
        % runtime that holds no handler for it there, and run by one that
        % does" ([RDSC.4a.9.3]).
        {"FN_JSON_BUILD (78), a hydration body's op, at any count", 78},
        % `none` rows of [RDSC.4a.9.5], which "admit no count": no clause in
        % force has the compiler emit either as a call, and neither runtime
        % holds a handler for either. libds's
        % `test_rdsc_4a_9_3__only_an_op_with_no_handler_is_refused` refuses
        % the same two at the same three sites.
        {"FN_EMIT (45), a `none` row: `emit` is ACTION_ASSERT", 45},
        {"FN_HYDRATION_CALL (52), a `none` row: hydration is deferred", 52}
    ],
    % Each has a handler here and in libds.
    Handled = [
        {"FN_NOW (40), which no clause emits as a call", 40},
        {"FN_CURRENCY_ROUND (122), which only a deferred clause specifies",
            122}
    ],
    list.foldl2(op_rewritten(edit_refused, "a `where` test",
        "68_where_unsupported.dsc", fn_floor_time, 2), Unhandled, !T, !IO),
    list.foldl2(op_rewritten(edit_loads, "a `where` test",
        "68_where_unsupported.dsc", fn_floor_time, 2), Handled, !T, !IO),
    list.foldl2(op_rewritten(edit_refused, "an action's operand",
        "142_action_unhandled_op.dsc", fn_degrees, 1), Unhandled, !T, !IO),
    list.foldl2(op_rewritten(edit_loads, "an action's operand",
        "142_action_unhandled_op.dsc", fn_degrees, 1), Handled, !T, !IO),
    % And a fire guard. `67_rate`'s `cooled` carries one call, its rule
    % cooldown's rate gate, the guard `ds_rate_allow(...)`: the control loads
    % it, and rewritten it is the guard `ds.dsc.unevaluable_guard` asks about.
    list.foldl2(op_rewritten(edit_refused, "a fire guard",
        "67_rate.dsc", fn_rate_allow, 1), Unhandled, !T, !IO),
    list.foldl2(op_rewritten(edit_loads, "a fire guard",
        "67_rate.dsc", fn_rate_allow, 1), Handled, !T, !IO),

    % After the dialect_def_sha256 length, as libds checks it
    % (`handle_dsco`): a header wrong in both ways is -703 in both.
    check("[RBND.1.3] a missing dialect_def_sha256 outranks a malformed list",
        ( if load_dsc(sealed(dsco_atom(dsco_base_no_binding(
                    ds.version.ds_version) ++ caps_field([6, 4])) ++ capb_frame),
                load_failed(ECapDef)),
             ECapDef ^ le_kind = lek_binding_incomplete
          then yes else no ), !T, !IO),

    % The version outranks it ([RDSC.9.2]), as libds checks it first. An
    % artefact wrong on both must cite the version in both runtimes.
    check("[RDSC.3.7] a bad version outranks a missing dialect_def_sha256",
        ( if load_dsc(sealed(dsco_frame_ver_plus("9" ++
                    ds.version.ds_version, def_sha_field(31))),
                load_failed(EDefV)),
             EDefV ^ le_kind = lek_version
          then yes else no ), !T, !IO),

    % Field 6 is reserved and neither value means anything: both load.
    check("a reserved field 6 loads whatever it holds",
        ( if load_dsc(sealed(dsco_frame_with(0x30, 0x00)), loaded(_)),
             load_dsc(sealed(dsco_frame_with(0x30, 0x01)), loaded(_))
          then yes else no ), !T, !IO),

    % [RDSC.11.1]'s Framing and No padding, one row per case
    % the clause codes: `rdsc_11_1_framing_rows` below.
    list.foldl2(rdsc_11_1_framing_row, rdsc_11_1_framing_rows, !T, !IO),

    % [LDET.1.10]: field 1 is reserved, so any value is an unknown field and
    % none of them gates.
    check("a struck header field 1 of value 3 does not refuse the artefact",
        ( if load_dsc(sealed(dsco_frame_with(0x08, 0x03)), loaded(_))
          then yes else no ), !T, !IO),

    % Every load error names the clause it violated [RDSC.11.2], and the field
    % is mandatory, so there is no uncited path.
    check("a load error cites a clause and an offset",
        ( if load_dsc(sealed(dsco_frame_ver("9" ++ ds.version.ds_version)),
                load_failed(E4)),
             clause_id_string(E4 ^ le_clause) = "LDET.1.10",
             E4 ^ le_offset = yes(_)
          then yes else no ), !T, !IO),

    % [RDSC.9.2]: the header is verified before anything else is processed,
    % so an artefact not opening with DscHeader is not a `.dsc` at all.
    check("an artefact not opening with DscHeader is refused",
        ( if load_dsc(sealed([0x0A, 0x04, 0x82, 0x10, 0x01, 0x00]),
                load_failed(E5)),
             E5 ^ le_kind = lek_bad_first_atom
          then yes else no ), !T, !IO),

    % [RDSC.11.1]: the first atom is not a DscHeader whatever its field
    % number, so an unknown one is refused as libds refuses it
    % (DS_ERR_DSC_BAD_MAGIC): 999, with a header after it, which it does not
    % reach, 100, 200 and 5000.
    check("[RDSC.11.1] an unknown first atom is refused, whatever its number",
        ( if load_dsc(from_bytes([0x0A, 0x04, 0xBA, 0x3E, 0x01, 0x00]
                    ++ dsco_frame), load_failed(ESkip)),
             ESkip ^ le_kind = lek_bad_first_atom,
             load_dsc(from_bytes([0x0A, 0x04, 0xA2, 0x06, 0x01, 0x00]),
                load_failed(EInject)),
             EInject ^ le_kind = lek_bad_first_atom,
             load_dsc(from_bytes([0x0A, 0x04, 0xC2, 0x0C, 0x01, 0x00]),
                load_failed(EVersion)),
             EVersion ^ le_kind = lek_bad_first_atom,
             load_dsc(from_bytes([0x0A, 0x05, 0xC2, 0xB8, 0x02, 0x01, 0x00]),
                load_failed(EPast)),
             EPast ^ le_kind = lek_bad_first_atom
          then yes else no ), !T, !IO),

    % [RDSC.11.1]: too short to contain a DscHeader atom. No container
    % at all is DS_ERR_DSC_TRUNCATED, as libds answers it.
    check("[RDSC.11.1] an empty artefact is truncated",
        ( if load_dsc(sealed([]), load_failed(E6)),
             E6 ^ le_kind = lek_truncated,
             clause_id_string(E6 ^ le_clause) = "RDSC.11.1"
          then yes else no ), !T, !IO),

    % [RDSC.1.5]'s "exactly one header" is the compiler's to keep: a second is
    % not checked for, so no test pins a refusal.

    % [RDSC.11.1], [RFCS.19.3]: a later frame whose field number has no
    % registry entry is malformed, DS_ERR_DSC_DECODE as libds answers it,
    % wherever the number lies, and nothing is logged as skipped. Field 100
    % -> tag 802 -> A2 06; field 999 -> tag 7994 -> BA 3E; field 5000, wire
    % type 2 -> tag 40002 -> varint C2 B8 02 (40002 = 312*128 + 66;
    % 312 = 2*128 + 56).
    list.foldl2(
        ( pred(Case::in, T0::in, T1::out, IO0::di, IO1::uo) is det :-
            Case = {What, Frame},
            check("[RDSC.11.1] an unknown later atom is malformed: " ++ What,
                ( if load_dsc(sealed(dsco_frame ++ Frame), load_failed(EU)),
                     EU ^ le_kind = lek_malformed_field_number
                  then yes else no ), T0, T1, IO0, IO1)
        ),
        [{"100", [0x0A, 0x04, 0xA2, 0x06, 0x01, 0x00]},
         {"999", [0x0A, 0x04, 0xBA, 0x3E, 0x01, 0x00]},
         {"5000", [0x0A, 0x05, 0xC2, 0xB8, 0x02, 0x01, 0x00]}],
        !T, !IO),

    % [RDSC.9.4]: a DocString is stepped over by name, recorded, and logged
    % at info under `dsc-load`, naming the field, the message and the byte
    % offset its frame starts at: right after the minimal frame, which is
    % where it was appended. Field 304 -> tag 2434 -> 82 13.
    SkipAt = list.length(dsco_frame),
    check("[RDSC.9.4] a DocString loads, and is skipped by name",
        ( if load_dsc(sealed(dsco_frame ++
                [0x0A, 0x04, 0x82, 0x13, 0x01, 0x00]), loaded(P2)),
             skipped_at(P2) = [{at_doc_string, SkipAt}]
          then yes else no ), !T, !IO),
    check("[RDSC.9.4] a DocString is logged with its field, message and offset",
        ( if load_dsc(sealed(dsco_frame ++
                [0x0A, 0x04, 0x82, 0x13, 0x01, 0x00]), loaded(P2b)),
             load_logs(P2b) = [eff_host_log(log_info, "dsc-load", Msg)],
             string.sub_string_search(Msg, "304", _),
             string.sub_string_search(Msg, "DocString", _),
             string.sub_string_search(Msg,
                 "byte offset " ++ string.int_to_string(SkipAt), _)
          then yes else no ), !T, !IO),
    check("[RDSC.9.4] an artefact with nothing skipped logs nothing at load",
        ( if load_dsc(sealed(dsco_frame), loaded(P2c)), load_logs(P2c) = []
          then yes else no ), !T, !IO),

    % [RFCS.19.2]: for a `Dsc`, truncation is an error, not EOF. A `Stream`
    % reader decides the other way, which is why ds.wire does not decide it.
    check("a truncated Dsc is an error, not EOF",
        ( if load_dsc(sealed(dsco_frame ++ [0x0A, 0x40, 0xBA]),
                load_failed(E10)),
             E10 ^ le_kind = lek_truncated
          then yes else no ), !T, !IO),

    % [RDSC.3.6]: `load_dsc` verifies the artefact's own `dsc_sha256` and
    % refuses a mismatch. Every check above loads a sealed artefact, so this
    % is the one place the seal is left off.
    check("an unsealed artefact is refused (RDSC.3.6)",
        ( if load_dsc(from_bytes(dsco_frame), load_failed(E11)),
             E11 ^ le_kind = lek_semantic,
             clause_id_string(E11 ^ le_clause) = "RDSC.3.6"
          then yes else no ), !T, !IO),
    % One byte of the stored hash, and nothing else, differs from the seal.
    ( if
        Sealed = seal(dsco_frame),
        seal_field_offset(array.from_list(Sealed), HashAt)
    then
        check("a sealed artefact with one hash byte flipped is refused",
            ( if load_dsc(from_bytes(flip_at(HashAt, Sealed)), load_failed(E12)),
                 E12 ^ le_kind = lek_semantic,
                 clause_id_string(E12 ^ le_clause) = "RDSC.3.6"
              then yes else no ), !T, !IO)
    else
        check("the minimal frame has a dsc_sha256 to seal", no, !T, !IO)
    ),
    % A body byte after the header, with the header as sealed: the hash covers
    % the whole artefact, not only the header. The skip atom is one the loader
    % accepts when the seal matches, so a refusal here is the hash's alone.
    Skip = seal(dsco_frame ++ [0x0A, 0x04, 0xBA, 0x3E, 0x01, 0x00]),
    check("...and so is one with a later atom's byte flipped",
        ( if load_dsc(from_bytes(flip_at(list.length(Skip) - 1, Skip)),
                load_failed(E13)),
             E13 ^ le_kind = lek_semantic,
             clause_id_string(E13 ^ le_clause) = "RDSC.3.6"
          then yes else no ), !T, !IO),
    % The order: another series is refused as such, whatever its hash, because
    % its layout is not one this runtime reads ([LDET.1.10]). Unsealed, so a
    % hash check that ran first would answer RDSC.3.6 here.
    check("another series is a version refusal even unsealed",
        ( if load_dsc(from_bytes(dsco_frame_ver("9" ++ ds.version.ds_version)),
                load_failed(E14)),
             E14 ^ le_kind = lek_version
          then yes else no ), !T, !IO).

    % `Bs` with the byte at `I` changed.
    %
:- func flip_at(int, list(int)) = list(int).

flip_at(I, Bs) = put_range(I, [(list.det_index0(Bs, I) + 1) /\ 0xFF], Bs).

%-----------------------------------------------------------------------------%
% Hydration -- the atom nothing produces
%-----------------------------------------------------------------------------%
%
% `ds.dsc_schema.decode_hydr` cannot be reached by any artefact the compiler
% builds, so these checks are what run it. The artefact is a real one with
% one atom spliced in: `55_hydr_base.dsc` supplies a genuine schema group and
% a genuine `(schema, slot)` to name.

:- pred test_hydr(tally::in, tally::out, io::di, io::uo) is det.

test_hydr(!T, !IO) :-
    read_bitmap("fixtures/55_hydr_base.dsc", Res, !IO),
    (
        Res = yes(BM),
        % [RDSC.5.6.3]: presence makes the slot eligible. `severity` is a real
        % slot of a real schema in this artefact.
        check("a Hydration atom marks its slot hydratable",
            ( if splice(BM, [hydr_atom("AlarmTriggered", "severity")], BM1),
                 load_dsc(BM1, loaded(P)),
                 hydratable_slots(P) = ["AlarmTriggered.severity"]
              then yes else no ), !T, !IO),

        % [RDSC.5.6.4]: "The runtime must reject a Hydration atom that names an
        % unknown slot." libds answers DS_ERR_DSC_DANGLING; so does this.
        check("a Hydration naming an unknown slot is DANGLING",
            ( if splice(BM, [hydr_atom("AlarmTriggered", "nosuchslot")], BM2),
                 load_dsc(BM2, load_failed(HE1)),
                 HE1 ^ le_kind = lek_dangling,
                 clause_id_string(HE1 ^ le_clause) = "RDSC.5.6.4"
              then yes else no ), !T, !IO),

        % A Hydration naming a slot of a different schema is the same rejection:
        % `hydrated_corr` exists on `AlarmTriggered` and not on `Untouched`, so
        % a decoder matching on slot name alone accepts this one and passes the
        % check above.
        check("a Hydration crossing schemas is DANGLING too",
            ( if splice(BM, [hydr_atom("Untouched", "hydrated_corr")], BM3),
                 load_dsc(BM3, load_failed(HE2)),
                 HE2 ^ le_kind = lek_dangling
              then yes else no ), !T, !IO),

        % [RDSC.5.6.5]'s "at most one per (schema_name, slot_name)" is
        % deferred with hydration, and a second is not checked for: the slot
        % is hydratable once.
        check("a second Hydration for one slot is not checked",
            ( if splice(BM, [hydr_atom("AlarmTriggered", "severity"),
                             hydr_atom("AlarmTriggered", "severity")], BM4),
                 load_dsc(BM4, loaded(P4)),
                 hydratable_slots(P4) = ["AlarmTriggered.severity"]
              then yes else no ), !T, !IO),

        % Two Hydrations for two different slots are not a duplicate.
        check("two HYDRs for different slots both take",
            ( if splice(BM, [hydr_atom("AlarmTriggered", "severity"),
                             hydr_atom("AlarmTriggered", "note")], BM5),
                 load_dsc(BM5, loaded(P5)),
                 hydratable_slots(P5) =
                    ["AlarmTriggered.note", "AlarmTriggered.severity"]
              then yes else no ), !T, !IO),

        % [RDSC.5.6]'s empty names are not checked: a Hydration with an empty
        % `slot_name` names no slot, and is the dangling case above.

        % The control: every check above splices, so `splice` must leave the
        % artefact loadable.
        check("splicing nothing leaves the artefact loadable",
            ( if splice(BM, [], BM7), load_dsc(BM7, loaded(P7)),
                 hydratable_slots(P7) = []
              then yes else no ), !T, !IO)
    ;
        Res = no,
        check("fixtures/55_hydr_base.dsc is readable", no, !T, !IO)
    ).

%-----------------------------------------------------------------------------%
% ServiceDef kwargs -- a service's declared kwargs, read for a host
%-----------------------------------------------------------------------------%
%
% `ds.dsc` reads `ServiceDef.kwargs` (field 2) into `ds.service`'s type, the
% one the compiler encodes from. The compiler's own round trip is in
% test_encode; these are the cases no compiler writes, spliced into a real
% artefact as the Hydration checks above are.
%
% libds reads field 2 too (`handle_svcd`, [NDBG.2.4]'s view), and its
% `test_ndbg_2_4__kwargs_edge_cases` holds the same cases. A ServiceDef whose
% kwargs do not decode fails its protobuf decode, so both runtimes refuse it
% DS_ERR_DSC_DECODE ([RDSC.11.1]).

:- pred test_svcd_kwargs(tally::in, tally::out, io::di, io::uo) is det.

test_svcd_kwargs(!T, !IO) :-
    read_bitmap("fixtures/55_hydr_base.dsc", Res, !IO),
    (
        Res = yes(BM),
        % [RDSC.6a.2.4]: every field of a kwarg, in the wire's order.
        Full = svcd_atom("probe.full", [
            kwarg_body("Int", "n", yes, no, yes, "-3"),
            kwarg_body("String", "s", no, yes, no, "")]),
        check("ServiceDef: a service's kwargs are read, every field",
            ( if
                splice(BM, [Full], BM1),
                load_dsc(BM1, loaded(P1)),
                assoc_list.search(service_kwargs(P1), "probe.full", Got1),
                Got1 = [
                    service_kwarg("n", "Int", yes, no, default_text("-3")),
                    service_kwarg("s", "String", no, yes, no_default)]
              then yes else no ), !T, !IO),

        % `has_default` with no text: a default the artefact does not state,
        % such as one whose unit the compiling file could not see, an
        % imported service's (`dsc.encode.rdsc_6a_2_4_text`; `ds.service`'s
        % `default_unstated`). Not `no_default`, which would say the kwarg is
        % missing when a call omits it.
        Unstated = svcd_atom("probe.unstated",
            [kwarg_body("celsius", "t", no, no, yes, "")]),
        check("ServiceDef: `has_default` with an empty `default_value` is unstated",
            ( if
                splice(BM, [Unstated], BM2),
                load_dsc(BM2, loaded(P2)),
                assoc_list.search(service_kwargs(P2), "probe.unstated", Got2),
                Got2 = [
                    service_kwarg("t", "celsius", no, no, default_unstated)]
              then yes else no ), !T, !IO),

        % `has_default` decides. [RDSC.6a.2.4] says the text is empty when it
        % is false; one that is not is ignored, not refused, in both runtimes.
        Stray = svcd_atom("probe.stray",
            [kwarg_body("Int", "x", no, no, no, "7")]),
        check("ServiceDef: a `default_value` without `has_default` is no default",
            ( if
                splice(BM, [Stray], BM3),
                load_dsc(BM3, loaded(P3)),
                assoc_list.search(service_kwargs(P3), "probe.stray", Got3),
                Got3 = [service_kwarg("x", "Int", no, no, no_default)]
              then yes else no ), !T, !IO),

        % A kwarg that does not decode: the atom's body fails its protobuf
        % decode, DS_ERR_DSC_DECODE ([RDSC.11.1]), as in libds.
        Garbled = svcd_atom("probe.garbled", [[0xFFu8]]),
        check("ServiceDef: a kwarg that does not decode is refused, DECODE",
            ( if
                splice(BM, [Garbled], BM4),
                load_dsc(BM4, load_failed(E4)),
                E4 ^ le_kind = lek_decode
              then yes else no ), !T, !IO),

        % Field 2 with the wrong wire type: refused the same way.
        put_string(1u32, "probe.varint", init_builder, V1),
        put_tag(2u32, wt_varint, V1, V2),
        put_varint(1u64, V2, V3),
        Varint = framed_atom(at_service_def, builder_bytes(V3)),
        check("ServiceDef: a kwargs field that is not a message is refused, DECODE",
            ( if
                splice(BM, [Varint], BM5),
                load_dsc(BM5, load_failed(E5)),
                E5 ^ le_kind = lek_decode
              then yes else no ), !T, !IO),

        % No kwargs is the empty list, and the response read is untouched:
        % the name and `response` are still what `service_responses` gives.
        Bare = svcd_atom("probe.bare", []),
        check("ServiceDef: a service with no kwargs has none; its response is read",
            ( if
                splice(BM, [Bare, Full], BM6),
                load_dsc(BM6, loaded(P6)),
                assoc_list.search(service_kwargs(P6), "probe.bare", Got6),
                Got6 = [],
                assoc_list.search(service_responses(P6), "probe.bare", ""),
                assoc_list.search(service_responses(P6), "probe.full", "")
              then yes else no ), !T, !IO)
    ;
        Res = no,
        check("fixtures/55_hydr_base.dsc is readable for ServiceDef", no, !T, !IO)
    ).

    % [NDBG.2.4]: the services, as libds's `ds_engine_service_*` gives
    % them and its `test_ndbg_2_4__services_read_back` checks them: one view
    % per ServiceDef in the artefact's order, its name, response (`""` for
    % `no response`), the `no response` flag exactly when declared, and the
    % kwargs in order with every field. `search_service` finds the later of
    % two that share a name, and fails on a miss. A ServiceDef with no name
    % is left out, as libds leaves it out. Spliced after the fixture's own
    % atoms, so the order checked is these services' order among the rest.
    % Path: `ds.dsc.decode_svcd` and `declared_services` / `search_service`.
    % Linked by the `@spec` line: a `__` in a Mercury name is a module
    % qualifier, so the test cannot be named for its clause.
    %
    % @spec [NDBG.2.4]
:- pred test_ndbg_2_4_services_view(tally::in, tally::out, io::di, io::uo)
    is det.

test_ndbg_2_4_services_view(!T, !IO) :-
    read_bitmap("fixtures/55_hydr_base.dsc", Res, !IO),
    (
        Res = yes(BM),
        Page = svcd_atom_full("alert.page", "Ack", no, [
            kwarg_body("Int", "level", no, no, yes, "3"),
            kwarg_body("String", "msg", yes, no, no, ""),
            kwarg_body("String", "target", no, yes, yes, "\"ops\"")]),
        Write = svcd_atom_full("log.write", "", yes,
            [kwarg_body("String", "line", yes, no, no, "")]),
        Nameless = svcd_atom_full("", "Ack", no, []),
        DupFirst = svcd_atom_full("dup.svc", "Ack", no, []),
        DupLater = svcd_atom_full("dup.svc", "", yes, []),
        ( if
            splice(BM, [Page, Write, Nameless, DupFirst, DupLater], BM1),
            load_dsc(BM1, loaded(P))
        then
            Mine = list.filter(
                ( pred(S::in) is semidet :-
                    list.member(S ^ sv_name, ["alert.page", "log.write",
                        "dup.svc"]) ),
                declared_services(P)),
            check("[NDBG.2.4] one view per ServiceDef, in the artefact's order",
                ( if list.map(( func(S) = S ^ sv_name ), Mine)
                        = ["alert.page", "log.write", "dup.svc", "dup.svc"]
                  then yes else no ), !T, !IO),
            check("[NDBG.2.4] a ServiceDef with no name is left out",
                ( if list.member(S0, declared_services(P)), S0 ^ sv_name = ""
                  then no else yes ), !T, !IO),
            check("[NDBG.2.4] a `response T` service: its schema, no flag, "
                    ++ "its kwargs in order with every field",
                ( if
                    search_service(P, "alert.page", Pg),
                    Pg = svcd("alert.page", "Ack", no, [
                        service_kwarg("level", "Int", no, no, default_text("3")),
                        service_kwarg("msg", "String", yes, no, no_default),
                        service_kwarg("target", "String", no, yes,
                            default_text("\"ops\""))])
                  then yes else no ), !T, !IO),
            check("[NDBG.2.4] a `no response` service: empty schema, the flag set",
                ( if
                    search_service(P, "log.write", Wr),
                    Wr ^ sv_response = "",
                    Wr ^ sv_no_response = yes,
                    Wr ^ sv_kwargs = [service_kwarg("line", "String", yes, no,
                        no_default)]
                  then yes else no ), !T, !IO),
            check("[NDBG.2.4] of two ServiceDefs for one name, the later is found",
                ( if
                    search_service(P, "dup.svc", Dup),
                    Dup ^ sv_no_response = yes
                  then yes else no ), !T, !IO),
            check("[NDBG.2.4] a name no ServiceDef bears is a miss",
                ( if search_service(P, "nope", _) then no else yes ), !T, !IO)
        else
            check("[NDBG.2.4] the spliced services load", no, !T, !IO)
        )
    ;
        Res = no,
        check("fixtures/55_hydr_base.dsc is readable for NDBG.2.4", no, !T, !IO)
    ).

    % A framed ServiceDef with every field NDBG.2.4 reads: the name (1), the
    % kwarg bodies (2), `response` (3) and `no_response` (5), each omitted
    % when it is proto3's default.
    %
:- func svcd_atom_full(string, string, bool, list(list(uint8))) = list(uint8).

svcd_atom_full(Name, Response, NoResponse, Kwargs) =
        framed_atom(at_service_def, builder_bytes(Body)) :-
    put_string(1u32, Name, init_builder, B1),
    list.foldl(
        ( pred(K::in, B0::in, B::out) is det :- put_delimited(2u32, K, B0, B) ),
        Kwargs, B1, B2),
    put_string(3u32, Response, B2, B3),
    put_bool(5u32, NoResponse, B3, Body).

    % One framed ServiceDef atom: field 1 the name, then each kwarg body as field 2.
    %
:- func svcd_atom(string, list(list(uint8))) = list(uint8).

svcd_atom(Name, Kwargs) = framed_atom(at_service_def, builder_bytes(Body)) :-
    put_string(1u32, Name, init_builder, B1),
    list.foldl(
        ( pred(K::in, B0::in, B::out) is det :- put_delimited(2u32, K, B0, B) ),
        Kwargs, B1, Body).

    % One `ServiceKwarg` body, `proto/service_def.proto`'s fields 1 to 6, the
    % defaults omitted as proto3 omits them.
    %
:- func kwarg_body(string, string, bool, bool, bool, string) = list(uint8).

kwarg_body(Type, Name, Required, Literal, HasDefault, Default) =
        builder_bytes(B6) :-
    put_string(1u32, Type, init_builder, B1),
    put_string(2u32, Name, B1, B2),
    put_bool(3u32, Required, B2, B3),
    put_bool(4u32, Literal, B3, B4),
    put_bool(5u32, HasDefault, B4, B5),
    put_string(6u32, Default, B5, B6).

:- func framed_atom(atom_id, list(uint8)) = list(uint8).

framed_atom(Atom, Body) = builder_bytes(Outer) :-
    put_delimited(atom_field(Atom), Body, init_builder, Inner),
    put_message(1u32, Inner, init_builder, Outer).

%-----------------------------------------------------------------------------%

    % `SchemaLogical` is every lifecycle but `ttl`, and its field 3 says which
    % ([RDSC.5.4.5]). Read as a logical schema with no key, a bare
    % `schema Foo:` would project the empty identity and hold one live fact,
    % ever; that case is pinned.
    %
    % `probe_scopes.dsc` is one schema per scope and nothing else, beside the
    % two fault schemas every artefact carries ([LERR.9.4]), which arrive as
    % `explicit` (`internal` is compile-time only, [LSCP.2.6.1]), and beside
    % `TimeZoneOffset` ([LIMP.12.2]), `logical` with the ambient flag.
    %
:- pred test_scopes(tally::in, tally::out, io::di, io::uo) is det.

test_scopes(!T, !IO) :-
    read_bitmap("fixtures/probe_scopes.dsc", Res, !IO),
    (
        Res = yes(BM),
        check("the four scopes decode to four lifecycles (RDSC.5.4.5)",
            ( if load_dsc(BM, loaded(P)),
                 lifecycles_of(P) = ["Act:activation", "Bare:explicit",
                     "ComputationError:explicit", "Exp:explicit",
                     "Log:logical", "Out:ttl", "TimeZoneOffset:logical",
                     "TypeError:explicit"]
              then yes else no ), !T, !IO),

        % [LSCP.1.4]: bare `schema Foo:` is `scope explicit`, so `Bare` and
        % `Exp` must agree.
        check("bare and `scope explicit` agree",
            ( if load_dsc(BM, loaded(P2)),
                 lifecycle_named(P2, "Bare") = lifecycle_named(P2, "Exp")
              then yes else no ), !T, !IO),

        % `scope activation` is its own lifecycle on the wire ([RDSC.5.4.5]).
        check("`scope activation` is distinguished from `explicit`",
            ( if load_dsc(BM, loaded(P3)),
                 lifecycle_named(P3, "Act") = "activation",
                 lifecycle_named(P3, "Bare") = "explicit"
              then yes else no ), !T, !IO),

        % [NDBG.2.2]: the built-ins enumerate as `internal` although they
        % decode as `explicit`; author schemas answer what libds's
        % enumeration does, an explicit one `logical`.
        check("the fault schemas enumerate as internal, author schemas not",
            ( if load_dsc(BM, loaded(P5)),
                 enumerated_lifecycles(P5) = ["Act:logical", "Bare:logical",
                     "ComputationError:internal", "Exp:logical",
                     "Log:logical", "Out:ttl", "TimeZoneOffset:logical",
                     "TypeError:internal"]
              then yes else no ), !T, !IO)
    ;
        Res = no,
        check("fixtures/probe_scopes.dsc is readable", no, !T, !IO)
    ),
    % A `logical` schema is allowed no `key` slot, and then it is a
    % singleton. The SchemaLogical atom says `logical`, so it stays logical.
    read_bitmap("fixtures/probe_logical_nokey.dsc", Res2, !IO),
    (
        Res2 = yes(BM2),
        check("an all-`mutable` logical schema is still logical",
            ( if load_dsc(BM2, loaded(P4)),
                 lifecycle_named(P4, "NoKey") = "logical"
              then yes else no ), !T, !IO)
    ;
        Res2 = no,
        check("fixtures/probe_logical_nokey.dsc is readable", no, !T, !IO)
    ).

    % `<name>:<lifecycle>` for every schema, sorted.
    %
:- func lifecycles_of(program) = list(string).

lifecycles_of(P) = list.sort(list.map(
    func(S) = text(interns(P), schema_name_ref(S ^ s_name)) ++ ":" ++
        lifecycle_word(S ^ s_lifecycle),
    schemas(P))).

:- func lifecycle_named(program, string) = string.

lifecycle_named(P, Name) = Word :-
    ( if list.find_first_match(
            pred(S::in) is semidet :-
                text(interns(P), schema_name_ref(S ^ s_name)) = Name,
            schemas(P), Found)
      then Word = lifecycle_word(Found ^ s_lifecycle)
      else Word = "<absent>"
    ).

    % `<name>:<lifecycle>` as the schema enumerates ([NDBG.2.2]), sorted.
    %
:- func enumerated_lifecycles(program) = list(string).

enumerated_lifecycles(P) = list.sort(list.map(
    func(S) = text(interns(P), schema_name_ref(S ^ s_name)) ++ ":" ++
        ndbg_lifecycle_word(ndbg_2_2_lifecycle(P, S)),
    schemas(P))).

:- func ndbg_lifecycle_word(ndbg_lifecycle) = string.

ndbg_lifecycle_word(nl_logical) = "logical".
ndbg_lifecycle_word(nl_ttl) = "ttl".
ndbg_lifecycle_word(nl_internal) = "internal".

:- func lifecycle_word(lifecycle) = string.

lifecycle_word(lc_logical(_, _)) = "logical".
lifecycle_word(lc_ttl(_, _)) = "ttl".
lifecycle_word(lc_explicit(_)) = "explicit".
lifecycle_word(lc_activation(_)) = "activation".

%-----------------------------------------------------------------------------%

    % `<schema>.<slot>` for every slot carrying the flag, sorted.
    %
:- func hydratable_slots(program) = list(string).

hydratable_slots(P) = list.sort(list.condense(
    list.map(schema_hydratable(interns(P)), schemas(P)))).

:- func schema_hydratable(intern_table, schema) = list(string).

schema_hydratable(IT, S) = Names :-
    Name = text(IT, schema_name_ref(S ^ s_name)),
    (
        S ^ s_lifecycle = lc_logical(Slots, _),
        Commons = list.map(func(L) = L ^ ls_common, Slots)
    ;
        S ^ s_lifecycle = lc_ttl(Slots, _),
        Commons = list.map(func(T) = T ^ ps_common, Slots)
    ;
        S ^ s_lifecycle = lc_explicit(Slots),
        Commons = list.map(func(T) = T ^ ps_common, Slots)
    ;
        S ^ s_lifecycle = lc_activation(Slots),
        Commons = list.map(func(T) = T ^ ps_common, Slots)
    ),
    Names = list.filter_map(
        func(C) = (Name ++ "." ++ text(IT, C ^ sc_name)) is semidet :-
            C ^ sc_hydratable = yes,
        Commons).

    % One framed Hydration atom: the outer `[0x0A][len]`, the inner tag whose
    % field number 301 is the atom's identity, then the `Hydration` body.
    %
:- func hydr_atom(string, string) = list(uint8).

hydr_atom(Schema, Slot) = Bytes :-
    put_string_always(1u32, Schema, init_builder, B1),
    put_string_always(2u32, Slot, B1, B2),
    put_delimited(atom_field(at_hydration), builder_bytes(B2), init_builder, Inner),
    put_message(1u32, Inner, init_builder, Outer),
    Bytes = builder_bytes(Outer).

    % Re-frame an artefact, inserting the given atoms after its last `Slot`.
    % [RDSC.8.1]'s grammar puts `Hydration*` after `Slot*` within one schema
    % group, and the loader checks only that the named slot has arrived.
    %
:- pred splice(bitmap::in, list(list(uint8))::in, bitmap::out) is semidet.

splice(BM, Atoms, Out) :-
    count_slots(init_reader(BM), 0, Total),
    Total > 0,
    respool(init_reader(BM), list.condense(Atoms), Total, 0, init_builder, B),
    % Re-sealed: the spliced artefact is a different file, and its old
    % `dsc_sha256` would refuse it at load before the Hydration is reached.
    Out = sealed(list.map(uint8.cast_to_int, builder_bytes(B))).

:- pred count_slots(reader::in, int::in, int::out) is semidet.

count_slots(R0, N0, N) :-
    next_frame(Result, R0, R1),
    (
        Result = fr_ok(F),
        ( if F ^ fr_atom = known(at_slot) then N1 = N0 + 1 else N1 = N0 ),
        count_slots(R1, N1, N)
    ;
        Result = fr_eof,
        N = N0
    ).

:- pred respool(reader::in, list(uint8)::in, int::in, int::in,
                builder::in, builder::out) is semidet.

respool(R0, Extra, Total, Seen0, !B) :-
    next_frame(Result, R0, R1),
    (
        Result = fr_ok(F),
        Ref = F ^ fr_atom,
        ( Ref = known(A), Field = atom_field(A) ; Ref = unknown(Field) ),
        put_delimited(Field, reader_bytes(F ^ fr_body), init_builder, Inner),
        put_message(1u32, Inner, !B),
        ( if Ref = known(at_slot) then Seen = Seen0 + 1 else Seen = Seen0 ),
        ( if Seen = Total, Seen0 = Total - 1 then
            put_bytes(Extra, !B)
        else
            true
        ),
        respool(R1, Extra, Total, Seen, !B)
    ;
        Result = fr_eof
    ).

:- func from_uint8s(list(uint8)) = bitmap.

from_uint8s(Bs) = from_bytes(list.map(uint8.cast_to_int, Bs)).

:- pred test_load_real(tally::in, tally::out, io::di, io::uo) is det.

test_load_real(!T, !IO) :-
    io.open_binary_input("fixtures/07_action_verbs.dsc", OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, Res, !IO),
        io.close_binary_input(Stream, !IO)
    ;
        OpenRes = error(OpenErr),
        Res = error(OpenErr)
    ),
    (
        Res = ok(BM),
        load_dsc(BM, LoadResult),
        (
            LoadResult = loaded(P),
            check("the compiled artefact LOADS", yes, !T, !IO),
            % [LDET.1.10]: the compiler stamped a version in this runtime's
            % minor series, or the artefact would not have loaded.
            check("it stamps a compiler_version in this minor series",
                ( if header(P) ^ dh_compiler_version \= "" then yes else no ),
                !T, !IO),
            check("dsc_sha256 is 32 raw bytes",
                ( if list.length(header(P) ^ dh_sha256) = 32 then yes else no ),
                !T, !IO),
            % An atom with no registry entry would have refused the load
            % ([RDSC.11.1]), so loading is what shows none is in the bytes.
            check("the first atom recorded is the header",
                ( if atoms(P) = [at_dsc_header | _] then yes else no ), !T, !IO),
            io.format("  note: loaded %d atoms from the real artefact\n",
                [i(list.length(atoms(P)))], !IO)
        ;
            LoadResult = load_failed(E),
            check("the compiled artefact loads (kind "
                ++ string(E ^ le_kind) ++ ", clause "
                ++ clause_id_string(E ^ le_clause) ++ ")", no, !T, !IO)
        )
    ;
        Res = error(E2),
        check("fixture readable: " ++ io.error_message(E2), no, !T, !IO)
    ).

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% CompiledCode atoms are skipped ([RDSC.4c.3])
%-----------------------------------------------------------------------------%
%
% In this edition a runtime skips every `CompiledCode` atom, whatever its
% `arch`, as [RDSC.9.4] disposes of every atom it lists: logged at info under
% `dsc-load` and stepped over. libds's test_dsc_basic
% (`test_rdsc_4c_3__compiled_code_atom_is_skipped`) holds libds to the same
% line, word for word.

:- pred test_no_aot(tally::in, tally::out, io::di, io::uo) is det.

test_no_aot(!T, !IO) :-
    % A CompiledCode atom: field 298 -> tag 2386 -> varint D2 12.
    % (2386 = 18*128 + 82; 82 = 0x52 -> 0xD2, 18 -> 0x12.)
    Code = [0x0A, 0x04, 0xD2, 0x12, 0x01, 0x00],
    % A DocString, field 304 -> tag 2434 -> 82 13.
    Docs = [0x0A, 0x04, 0x82, 0x13, 0x01, 0x00],
    CodeAt = list.length(dsco_frame),
    CodeLog = eff_host_log(log_info, "dsc-load",
        "skipping atom 298 (CompiledCode) at byte offset "
        ++ string.int_to_string(CodeAt)
        ++ ": this edition runs no compiled code (RDSC.4c.3)"),

    check("[RDSC.4c.3] an artefact carrying CompiledCode loads",
        ( if load_dsc(sealed(dsco_frame ++ Code), loaded(_))
          then yes else no ), !T, !IO),
    check("[RDSC.4c.3] the CompiledCode atom is skipped, and counted",
        ( if load_dsc(sealed(dsco_frame ++ Code), loaded(P)),
             skipped_code(P) = 1
          then yes else no ), !T, !IO),
    check("[RDSC.4c.3] and it is not among the accepted atoms",
        ( if load_dsc(sealed(dsco_frame ++ Code), loaded(P2)),
             not list.member(at_compiled_code, atoms(P2))
          then yes else no ), !T, !IO),
    % Its own kind of skip, not one `skipped_at` lists.
    check("[RDSC.4c.3] a skipped CompiledCode atom is not a named skip",
        ( if load_dsc(sealed(dsco_frame ++ Code), loaded(P3)),
             skipped_at(P3) = []
          then yes else no ), !T, !IO),
    check("[RDSC.4c.3] the skip is logged as [RDSC.9.4] logs one, in libds's "
            ++ "words",
        ( if load_dsc(sealed(dsco_frame ++ Code), loaded(P4)),
             load_logs(P4) = [CodeLog]
          then yes else no ), !T, !IO),
    % Both kinds in one artefact log in the order they were met, as libds
    % logs them while it walks.
    check("[RDSC.4c.3] its line keeps its place among the skip lines",
        ( if load_dsc(sealed(dsco_frame ++ Code ++ Docs), loaded(P5)),
             load_logs(P5) = [CodeLog, eff_host_log(log_info, "dsc-load", _)],
             skipped_at(P5) = [{at_doc_string, CodeAt + list.length(Code)}]
          then yes else no ), !T, !IO),
    % [RDSC.9.2] comes first: an artefact opening with a CompiledCode atom is
    % not a `.dsc`, as libds refuses it.
    check("[RDSC.9.2] an artefact opening with CompiledCode is refused",
        ( if load_dsc(sealed(Code ++ dsco_frame), load_failed(E)),
             E ^ le_kind = lek_bad_first_atom
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% ds.intern
%-----------------------------------------------------------------------------%

:- pred test_intern(tally::in, tally::out, io::di, io::uo) is det.

test_intern(!T, !IO) :-
    T0 = init_interns,

    % [RHIM.2.4]: `hydrated_corr` defaults to the interned empty string, and
    % the series skip tests `hydrated_corr == ""` on every assertion of a
    % series-tracked schema, so it must always be present.
    check("the empty string is interned at construction",
        ( if expand(T0, empty_ref(T0), "") then yes else no ), !T, !IO),

    some [!I] (
        !:I = T0,
        intern("alpha", A, !I),
        intern("beta", B, !I),
        intern("alpha", A2, !I),

        check("interning the same string twice gives the same ref",
            ( if A = A2 then yes else no ), !T, !IO),
        check("different strings get different refs",
            ( if A = B then no else yes ), !T, !IO),
        check("a ref expands back to its string",
            ( if expand(!.I, B, "beta") then yes else no ), !T, !IO),
        check("re-interning does not grow the table",
            ( if intern_count(!.I) = 3 then yes else no ), !T, !IO),

        % `intern_bytes_cap` ([RTCT.7.1]) is counted in UTF-8 code units, as
        % the wire carries them.
        check("bytes are counted in UTF-8 code units",
            ( if intern_bytes(!.I) = 9 then yes else no ), !T, !IO),

        % What a `+realtime` live lookup does: checks without interning.
        check("a known string is found without interning it",
            ( if interned(!.I, "alpha", A) then yes else no ), !T, !IO),
        check("an unknown string is not found",
            ( if interned(!.I, "gamma", _) then no else yes ), !T, !IO)
    ).

%-----------------------------------------------------------------------------%
% Schemas out of the real artefact
%-----------------------------------------------------------------------------%

:- pred test_real_schemas(tally::in, tally::out, io::di, io::uo) is det.

test_real_schemas(!T, !IO) :-
    io.open_binary_input("fixtures/07_action_verbs.dsc", OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, Res, !IO),
        io.close_binary_input(Stream, !IO)
    ;
        OpenRes = error(OpenErr),
        Res = error(OpenErr)
    ),
    (
        Res = ok(BM),
        load_dsc(BM, LoadResult),
        (
            LoadResult = loaded(P),
            Schemas = schemas(P),
            IT = interns(P),
            io.format("  note: %d schemas from the real artefact\n",
                [i(list.length(Schemas))], !IO),

            check("the artefact declares schemas",
                ( if Schemas = [_ | _] then yes else no ), !T, !IO),

            % 07_action_verbs.ds declares:
            %     schema Trig scope logical: v: Int key
            %     schema Alert scope ttl 1_h: severity: Int, zone: String
            check("Trig is there, and it is logical",
                ( if find_schema(Schemas, IT, "Trig", Trig),
                     Trig ^ s_lifecycle = lc_logical(_, _)
                  then yes else no ), !T, !IO),
            check("Alert is there, and it is ttl",
                ( if find_schema(Schemas, IT, "Alert", Alert),
                     Alert ^ s_lifecycle = lc_ttl(_, _)
                  then yes else no ), !T, !IO),

            % `scope ttl 1_h` -- one hour in nanoseconds.
            check("Alert's TTL decoded as one hour",
                ( if find_schema(Schemas, IT, "Alert", A2),
                     A2 ^ s_lifecycle = lc_ttl(_, D),
                     duration_ns(D) = 3600000000000u64
                  then yes else no ), !T, !IO),

            % `v: Int key`: one slot, and it is the key.
            check("Trig has one slot",
                ( if find_schema(Schemas, IT, "Trig", T3),
                     T3 ^ s_lifecycle = lc_logical(TSlots, _),
                     list.length(TSlots) = 1
                  then yes else no ), !T, !IO),
            check("and it is marked KEY, not defaulted to MUTABLE",
                ( if find_schema(Schemas, IT, "Trig", T4),
                     T4 ^ s_lifecycle = lc_logical([S1], _),
                     S1 ^ ls_role = role_key
                  then yes else no ), !T, !IO),
            check("its kind decoded as Int",
                ( if find_schema(Schemas, IT, "Trig", T5),
                     T5 ^ s_lifecycle = lc_logical([S2], _),
                     S2 ^ ls_common ^ sc_kind = k_int
                  then yes else no ), !T, !IO),

            % The index is not on the wire: it comes from arrival order
            % [RFCS.5.1]. Alert has `severity: Int` then `zone: String`.
            check("Alert's slots are indexed 0 and 1 BY ARRIVAL ORDER",
                ( if find_schema(Schemas, IT, "Alert", A3),
                     A3 ^ s_lifecycle = lc_ttl([Sev, Zone], _),
                     slot_index_int(Sev ^ ps_common ^ sc_index) = 0,
                     slot_index_int(Zone ^ ps_common ^ sc_index) = 1
                  then yes else no ), !T, !IO),
            check("and in declaration order, severity before zone",
                ( if find_schema(Schemas, IT, "Alert", A4),
                     A4 ^ s_lifecycle = lc_ttl([Sv, Zn], _),
                     expand(IT, Sv ^ ps_common ^ sc_name, "severity"),
                     expand(IT, Zn ^ ps_common ^ sc_name, "zone")
                  then yes else no ), !T, !IO),
            check("with their kinds, Int then String",
                ( if find_schema(Schemas, IT, "Alert", A5),
                     A5 ^ s_lifecycle = lc_ttl([Sv2, Zn2], _),
                     Sv2 ^ ps_common ^ sc_kind = k_int,
                     Zn2 ^ ps_common ^ sc_kind = k_string
                  then yes else no ), !T, !IO),

            % Every name the artefact used is in the table, which is what makes
            % it usable as the engine's table [RTCT.12.4].
            check("every schema and slot name was interned",
                ( if interned(IT, "Trig", _), interned(IT, "Alert", _),
                     interned(IT, "severity", _), interned(IT, "zone", _)
                  then yes else no ), !T, !IO)
        ;
            LoadResult = load_failed(E),
            check("artefact loads (kind " ++ string(E ^ le_kind) ++ ")",
                no, !T, !IO)
        )
    ;
        Res = error(E2),
        check("fixture readable: " ++ io.error_message(E2), no, !T, !IO)
    ).

:- pred find_schema(list(schema)::in, intern_table::in, string::in,
                    schema::out) is semidet.

find_schema([S | Ss], IT, Name, Found) :-
    ( if expand(IT, schema_name_ref(S ^ s_name), Name) then
        Found = S
    else
        find_schema(Ss, IT, Name, Found)
    ).

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% Slot decoding, on hand-built bytes
%-----------------------------------------------------------------------------%
%
% The real artefact declares no tolerance and no nullable slot, so those paths
% need vectors of their own. Hand-encoded, with every number worked out in the
% comment beside it.

:- pred test_slot_decode(tally::in, tally::out, io::di, io::uo) is det.

test_slot_decode(!T, !IO) :-
    % SchemaLogical for schema "S": field 1 (len 1) "S", field 3 lifecycle = 2
    % (LOGICAL, RDSC.5.4.5).
    Slog = frame(299, [0x0A, 0x01, 0x53, 0x18, 0x02]),

    % Slot: schema "S", slot "t", kind 2 (FLOAT), tolerance 0.5, role 2
    % (MUTABLE), nullable.
    %
    % 0.5 as IEEE-754 double is 0x3FE0000000000000, little-endian on the wire:
    %     00 00 00 00 00 00 E0 3F
    Slot = frame(257,
        [0x0A, 0x01, 0x53,                          % 1: schema_name "S"
         0x12, 0x01, 0x74,                          % 2: slot_name "t"
         0x18, 0x02,                                % 3: kind = FLOAT
         0x39, 0x00, 0x00, 0x00, 0x00,              % 7: tolerance, fixed64...
               0x00, 0x00, 0xE0, 0x3F,              %    ...0.5
         0x48, 0x02,                                % 9: role = MUTABLE
         0x58, 0x01]),                              % 11: nullable = true

    % `float.cast_from_uint64` is a numeric conversion, not a bit
    % reinterpretation: it would decode this to 4.6e18, a tolerance that
    % suppresses every re-assert.
    check("a float slot's tolerance decodes from its IEEE-754 bits",
        ( if load_dsc(sealed(dsco_frame ++ Slog ++ Slot), loaded(P)),
             schemas(P) = [S],
             S ^ s_lifecycle = lc_logical([L], _),
             L ^ ls_tolerance = within(Tol),
             Tol = 0.5
          then yes else no ), !T, !IO),

    % ±Inf is a DS value [LEXP.4.2] and decodes as one.
    check("+Inf bits decode to +infinity",
        ( if F1 = float_from_bits(0x7FF0000000000000u64),
             float.is_infinite(F1), F1 > 0.0
          then yes else no ), !T, !IO),
    check("-Inf bits decode to -infinity",
        ( if F2 = float_from_bits(0xFFF0000000000000u64),
             float.is_infinite(F2), F2 < 0.0
          then yes else no ), !T, !IO),
    check("a NaN pattern is never a DS value and decodes as 0.0",
        ( if float_from_bits(0x7FF8000000000000u64) = 0.0
          then yes else no ), !T, !IO),

    % ...and so is a +Inf tolerance, `within(+inf)`, which suppresses every
    % finite re-assert: `abs(new - old) <= T` ([RLOW.3.7.4]), and [RDSC.9.10]
    % does not refuse an infinity. libds reads it so.
    SlotInf = frame(257,
        [0x0A, 0x01, 0x53, 0x12, 0x01, 0x74, 0x18, 0x02,
         0x39, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xF0, 0x7F,
         0x48, 0x02]),
    check("[RLOW.3.7.4] a +inf tolerance is within(+inf)",
        ( if load_dsc(sealed(dsco_frame ++ Slog ++ SlotInf), loaded(PI)),
             schemas(PI) = [SI],
             SI ^ s_lifecycle = lc_logical([LI], _),
             LI ^ ls_tolerance = within(Inf),
             float.is_infinite(Inf), Inf > 0.0
          then yes else no ), !T, !IO),

    check("its kind decoded as Float",
        ( if load_dsc(sealed(dsco_frame ++ Slog ++ Slot), loaded(P2)),
             schemas(P2) = [S2],
             S2 ^ s_lifecycle = lc_logical([L2], _),
             L2 ^ ls_common ^ sc_kind = k_float
          then yes else no ), !T, !IO),

    check("nullable decoded from field 11",
        ( if load_dsc(sealed(dsco_frame ++ Slog ++ Slot), loaded(P3)),
             schemas(P3) = [S3],
             S3 ^ s_lifecycle = lc_logical([L3], _),
             L3 ^ ls_common ^ sc_nullable = nullable
          then yes else no ), !T, !IO),

    % [RDSC.5.3.3]: the compiler must omit SchemaTtl rather than emit a zero.
    % The load does not check: a zero ttl_ns is a ttl schema whose facts
    % expire at once, not "no TTL".
    SttlZero = frame(300, [0x0A, 0x01, 0x5A, 0x10, 0x00]),  % "Z", ttl_ns = 0
    check("[RDSC.5.3.3] SchemaTtl with ttl_ns = 0 is not checked: a ttl schema",
        ( if load_dsc(sealed(dsco_frame ++ SttlZero), loaded(PZ)),
             schemas(PZ) = [SZ],
             SZ ^ s_lifecycle = lc_ttl(_, _)
          then yes else no ), !T, !IO),

    % [LFAC.1.1] gives a schema SchemaTtl XOR SchemaLogical. One with both is
    % not refused: it is one schema, built ttl, whichever atom came first
    % (`lfac_1_1_one_lifecycle`), as libds builds it (test_dsc_basic.c,
    % test_schema_sttl_slog_conflict).
    SttlS = frame(300, [0x0A, 0x01, 0x53, 0x10, 0xE8, 0x07]),  % "S", 1000 ns
    check("[LFAC.1.1] SchemaTtl then SchemaLogical is one ttl schema",
        ( if load_dsc(sealed(dsco_frame ++ SttlS ++ Slog ++ Slot), loaded(PB1)),
             schemas(PB1) = [SB1],
             SB1 ^ s_lifecycle = lc_ttl([_], _)
          then yes else no ), !T, !IO),
    check("[LFAC.1.1] SchemaLogical then SchemaTtl is one ttl schema",
        ( if load_dsc(sealed(dsco_frame ++ Slog ++ SttlS ++ Slot), loaded(PB2)),
             schemas(PB2) = [SB2],
             SB2 ^ s_lifecycle = lc_ttl([_], _)
          then yes else no ), !T, !IO),

    % SLOT_KIND_UNSPECIFIED is proto3's zero, not a kind.
    SlotNoKind = frame(257, [0x0A, 0x01, 0x53, 0x12, 0x01, 0x74]),
    check("a slot with no declared kind is refused",
        ( if load_dsc(sealed(dsco_frame ++ Slog ++ SlotNoKind),
                load_failed(_))
          then yes else no ), !T, !IO),

    % [RDSC.5.4.5]: a SchemaLogical whose `lifecycle` is UNSPECIFIED, the
    % zero proto3 omits, so a body with no field 3 at all, is refused.
    SlogNoLifecycle = frame(299, [0x0A, 0x01, 0x53]),
    check("[RDSC.5.4.5] a SchemaLogical with no lifecycle is refused",
        ( if load_dsc(sealed(dsco_frame ++ SlogNoLifecycle ++ Slot),
                load_failed(E1)),
             clause_id_string(E1 ^ le_clause) = "RDSC.5.4.5"
          then yes else no ), !T, !IO),

    % A lifecycle past the enum is refused the same way: there is nothing to
    % drive it by. Field 3 = 9.
    SlogBadLifecycle = frame(299, [0x0A, 0x01, 0x53, 0x18, 0x09]),
    check("[RDSC.5.4.5] a SchemaLogical with an unknown lifecycle is refused",
        ( if load_dsc(sealed(dsco_frame ++ SlogBadLifecycle ++ Slot),
                load_failed(E2)),
             clause_id_string(E2 ^ le_clause) = "RDSC.5.4.5"
          then yes else no ), !T, !IO),

    % The roles are not cross-checked against the field: `explicit` (1) over
    % a MUTABLE-marked slot, and `logical` (2) over an unmarked one, load as
    % the atom says.
    SlogExplicit = frame(299, [0x0A, 0x01, 0x53, 0x18, 0x01]),
    check("[RDSC.5.4.5] `explicit` over a role-marked slot loads as explicit",
        ( if load_dsc(sealed(dsco_frame ++ SlogExplicit ++ Slot), loaded(PE)),
             schemas(PE) = [SE],
             SE ^ s_lifecycle = lc_explicit([_])
          then yes else no ), !T, !IO),
    SlotUnmarked = frame(257,
        [0x0A, 0x01, 0x53, 0x12, 0x01, 0x74, 0x18, 0x02]),  % "S"."t" FLOAT
    check("[RDSC.5.4.5] `logical` over an unmarked slot loads as logical",
        ( if load_dsc(sealed(dsco_frame ++ Slog ++ SlotUnmarked), loaded(PL)),
             schemas(PL) = [SL],
             SL ^ s_lifecycle = lc_logical([_], _)
          then yes else no ), !T, !IO),
    % And the agreeing pair loads as what it says: `activation` (3) over an
    % unmarked slot is `lc_activation`, its own constructor.
    SlogActivation = frame(299, [0x0A, 0x01, 0x53, 0x18, 0x03]),
    check("[RDSC.5.4.5] `activation` over an unmarked slot decodes as such",
        ( if load_dsc(sealed(dsco_frame ++ SlogActivation ++ SlotUnmarked),
                loaded(PA)),
             schemas(PA) = [SA],
             SA ^ s_lifecycle = lc_activation([_])
          then yes else no ), !T, !IO),

    % [RDSC.5.5.5]: `schema_ref` required iff kind == SCHEMA. The reference is
    % folded into the constructor, so kind SCHEMA with an empty ref cannot be
    % built.
    SlotBadRef = frame(257,
        [0x0A, 0x01, 0x53, 0x12, 0x01, 0x74, 0x18, 0x06]),  % kind SCHEMA, no ref
    check("kind SCHEMA with no schema_ref is refused",
        ( if load_dsc(sealed(dsco_frame ++ Slog ++ SlotBadRef),
                load_failed(_))
          then yes else no ), !T, !IO),
    test_srcs_decode(!T, !IO).

    % `SchemaSource` [RDSC.5.7]: where a schema is declared, which libds
    % answers through `ds_schema_get_source`. Each case is one libds's
    % `test_dsc_basic.c` pins: `test_srcs_round_trip`,
    % `test_rdsc_5_7__srcs_without_dsrc_keeps_position` and
    % `test_rdsc_5_7_4__srcs_refusals`.
    %
:- pred test_srcs_decode(tally::in, tally::out, io::di, io::uo) is det.

test_srcs_decode(!T, !IO) :-
    % An `explicit` schema "S" with one unmarked FLOAT slot "t".
    Slog = frame(299, [0x0A, 0x01, 0x53, 0x18, 0x01]),
    Slot = frame(257, [0x0A, 0x01, 0x53, 0x12, 0x01, 0x74, 0x18, 0x02]),
    Schema = dsco_frame ++ Slog ++ Slot,
    Srcs = frame(302,
        [0x0A, 0x01, 0x53,                          % 1: schema_name "S"
         0x18, 0x11,                                % 3: line = 17
         0x20, 0x04]),                              % 4: col = 4
    % Clip 0's DsSource: file "m.ds", compression NONE, no text.
    Dsrc = frame(267, [0x0A, 0x04, 0x6D, 0x2E, 0x64, 0x73, 0x10, 0x01]),

    check("[RDSC.5.7] a SchemaSource's line and column are the schema's source",
        ( if load_dsc(sealed(Schema ++ Srcs), loaded(P1)),
             schema_source_for(P1, "S", source_pos(17u32, 4u32, 0u32))
          then yes else no ), !T, !IO),
    check("[RDSC.4.7] with no DsSource for its module there is no display path",
        ( if load_dsc(sealed(Schema ++ Srcs), loaded(P2)),
             schema_source_for(P2, "S", At2),
             not source_file(P2, At2 ^ sp_clip, _)
          then yes else no ), !T, !IO),
    check("[RDSC.4.7] the display path is its module's DsSource file",
        ( if load_dsc(sealed(dsco_frame ++ Dsrc ++ Slog ++ Slot ++ Srcs),
                loaded(P3)),
             schema_source_for(P3, "S", At3),
             source_file(P3, At3 ^ sp_clip, "m.ds")
          then yes else no ), !T, !IO),
    check("[RDSC.5.7] a schema with no SchemaSource has no source",
        ( if load_dsc(sealed(Schema), loaded(P4)),
             schemas(P4) = [_],
             not schema_source_for(P4, "S", _)
          then yes else no ), !T, !IO),

    % Field 2 is reserved, as on RuleSource: a reader taking "the second real
    % field" for the line would read the path instead.
    SrcsWithFile = frame(302,
        [0x0A, 0x01, 0x53,                          % 1: schema_name "S"
         0x12, 0x04, 0x78, 0x2E, 0x64, 0x73,        % 2: (reserved) "x.ds"
         0x18, 0x11,                                % 3: line = 17
         0x20, 0x04]),                              % 4: col = 4
    check("[RDSC.5.7] reserved field 2 is skipped; the line is field 3's",
        ( if load_dsc(sealed(Schema ++ SrcsWithFile), loaded(P5)),
             schema_source_for(P5, "S", source_pos(17u32, 4u32, 0u32))
          then yes else no ), !T, !IO),

    % A second SchemaSource is not checked for ([RDSC.5.7.4], [RDSC.7.2]):
    % its position is the schema's.
    Srcs2 = frame(302, [0x0A, 0x01, 0x53, 0x18, 0x12, 0x20, 0x05]),  % 18:5
    check("[RDSC.5.7.4] a second SchemaSource is not checked: it replaces the first",
        ( if load_dsc(sealed(Schema ++ Srcs ++ Srcs2), loaded(P6)),
             schema_source_for(P6, "S", source_pos(18u32, 5u32, 0u32))
          then yes else no ), !T, !IO),
    % An empty name is not checked either; a SchemaSource for "" names a schema
    % no lifecycle atom declares, and is refused as such an orphan is
    % ([LFAC.1.1]), as libds refuses it.
    SrcsNameless = frame(302, [0x18, 0x11, 0x20, 0x04]),
    check("[RDSC.5.7] a SchemaSource with no schema_name names no schema",
        ( if load_dsc(sealed(Schema ++ SrcsNameless), load_failed(E7)),
             E7 ^ le_kind = lek_semantic,
             clause_id_string(E7 ^ le_clause) = "LFAC.1.1"
          then yes else no ), !T, !IO),
    % `line` sent length-delimited: the body does not decode.
    SrcsBadWire = frame(302, [0x0A, 0x01, 0x53, 0x1A, 0x01, 0x00]),
    check("[RDSC.5.7] a SchemaSource body that does not decode is refused",
        ( if load_dsc(sealed(Schema ++ SrcsBadWire), load_failed(E8)),
             E8 ^ le_kind = lek_decode
          then yes else no ), !T, !IO),
    test_orphan_schema_atoms(!T, !IO).

    % A schema atom naming a schema that no lifecycle atom declares.
    % [RDSC.8.1]'s `schema_group` opens with exactly one lifecycle atom, and
    % libds refuses the group without one, DS_ERR_DSC_SEMANTIC (LFAC.1.1):
    % `test_schema_no_lifecycle` and `test_lfac_1_1__orphan_schema_atoms_refused`
    % in `test_dsc_basic.c`, case for case.
    %
:- pred test_orphan_schema_atoms(tally::in, tally::out, io::di, io::uo) is det.

test_orphan_schema_atoms(!T, !IO) :-
    Slog = frame(299, [0x0A, 0x01, 0x53, 0x18, 0x01]),      % "S", EXPLICIT
    SlogT = frame(299, [0x0A, 0x01, 0x54, 0x18, 0x01]),     % "T", EXPLICIT
    Slot = frame(257, [0x0A, 0x01, 0x53, 0x12, 0x01, 0x74, 0x18, 0x02]),
                                                            % "S"."t" FLOAT
    Hydr = frame(301, [0x0A, 0x01, 0x53, 0x12, 0x01, 0x74]),% "S"."t"
    Srcs = frame(302, [0x0A, 0x01, 0x53, 0x18, 0x03, 0x20, 0x01]),
                                                            % "S" at 3:1
    Sdef = frame(256, [0x0A, 0x01, 0x53, 0x10, 0x01]),      % "S", NONE

    check("[RDSC.8.1] a whole schema group loads",
        ( if load_dsc(sealed(dsco_frame ++ Slog ++ Slot ++ Hydr ++ Srcs
                ++ Sdef), loaded(P)),
             schemas(P) = [_]
          then yes else no ), !T, !IO),
    list.foldl2(
        ( pred({What, Atoms}::in, !.T::in, !:T::out, !.IO::di, !:IO::uo)
                is det :-
            check("[LFAC.1.1] " ++ What ++ " is refused",
                ( if load_dsc(sealed(dsco_frame ++ Atoms), load_failed(E)),
                     E ^ le_kind = lek_semantic,
                     clause_id_string(E ^ le_clause) = "LFAC.1.1"
                  then yes else no ), !T, !IO)
        ),
        [{"a Slot naming no lifecycle", Slot},
         {"a SchemaDef naming no lifecycle", Sdef},
         {"a SchemaSource naming no lifecycle", Srcs},
         {"a Slot beside another schema's lifecycle", SlogT ++ Slot}],
        !T, !IO),
    check("[RDSC.5.6.4] a Hydration alone names no slot, so it dangles first",
        ( if load_dsc(sealed(dsco_frame ++ Hydr), load_failed(EH)),
             EH ^ le_kind = lek_dangling
          then yes else no ), !T, !IO).

    % `N` nested `not`s over `true` (Expr `unop` = 7, UnopExpr `operand` = 2,
    % `lit_bool` = 4): the literal sits at depth `N` ([RDSC.11.3]).
    %
:- func not_chain(int) = list(int).

not_chain(N) = Bytes :-
    ( if N =< 0 then
        Bytes = [0x20, 0x01]
    else
        Inner = not_chain(N - 1),
        Unop = [0x12] ++ varint(list.length(Inner)) ++ Inner,
        Bytes = [0x3A] ++ varint(list.length(Unop)) ++ Unop
    ).

    % BetaNode 2 over AlphaNode 1 with `Test` as its one join test (field 4).
    %
:- func beta_with_test(list(int)) = list(int).

beta_with_test(Test) =
    [0x08, 0x02, 0x10, 0x01, 0x22] ++ varint(list.length(Test)) ++ Test.

    % AlphaNode 1 over schema "S" with `Test` as its one AlphaTest (field 3).
    %
:- func alpha_with_test(list(int)) = list(int).

alpha_with_test(Test) =
    [0x08, 0x01, 0x12, 0x01, 0x53, 0x1A] ++ varint(list.length(Test)) ++ Test.

    % TerminalNode 3 under BetaNode 2, rule "R", with `Action` as its one
    % action (field 6).
    %
:- func term_with_action(list(int)) = list(int).

term_with_action(Action) =
    [0x08, 0x03, 0x10, 0x02, 0x1A, 0x01, 0x52, 0x32]
        ++ varint(list.length(Action)) ++ Action.

    % Wrap a body in the two-level framing: outer 0A len, then the atom's own
    % tag and length. Only for field numbers whose tag fits two bytes, 16
    % through 2047.
    %
:- func frame(int, list(int)) = list(int).

frame(Field, Body) = Outer :-
    Tag = Field * 8 + 2,                        % wire type 2
    Lo = (Tag /\ 0x7F) \/ 0x80,
    Hi = Tag >> 7,
    Atom = [Lo, Hi] ++ varint(list.length(Body)) ++ Body,
    Outer = [0x0A] ++ varint(list.length(Atom)) ++ Atom.

    % The schema group of the schema "S" the hand-built network vectors' alphas
    % name: `explicit`, one unmarked FLOAT slot "t" -- `test_srcs_decode`'s.
    % An AlphaNode names a schema the artefact declares [RDSC.8.7], so every
    % vector carrying one carries this ahead of it.
    %
:- func network_schema_s = list(int).

network_schema_s =
    frame(299, [0x0A, 0x01, 0x53, 0x18, 0x01]) ++               % "S", EXPLICIT
    frame(257, [0x0A, 0x01, 0x53, 0x12, 0x01, 0x74, 0x18, 0x02]).
                                                            % "S"."t" FLOAT

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% The Rete network: decode
%-----------------------------------------------------------------------------%
%
% Every byte vector below is generated, not written by hand. Regenerate them
% if one needs to change.

:- pred test_network(tally::in, tally::out, io::di, io::uo) is det.

test_network(!T, !IO) :-
    % AlphaNode: node_id 1, schema "S", no tests
    Alfa = network_schema_s ++
        [0x0A, 0x08, 0xE2, 0x10, 0x05, 0x08, 0x01, 0x12, 0x01, 0x53],
    % BetaNode: node_id 2, right_alpha 1, no left parent = ROOT
    Beta = [0x0A, 0x07, 0xEA, 0x10, 0x04, 0x08, 0x02, 0x10,
         0x01],
    % TerminalNode: node_id 3, parent_beta 2, rule "R"
    Term = [0x0A, 0x0A, 0xF2, 0x10, 0x07, 0x08, 0x03, 0x10,
         0x02, 0x1A, 0x01, 0x52],

    Bytes = dsco_frame ++ Alfa ++ Beta ++ Term,

    check("a three-atom network loads",
        ( if load_dsc(sealed(Bytes), loaded(_)) then yes else no ),
        !T, !IO),

    check("the alpha carries its schema name and an empty test list",
        ( if load_dsc(sealed(Bytes), loaded(P1)),
             alpha_nodes(network(P1)) = [A],
             expand(interns(P1), schema_name_ref(A ^ an_schema), "S"),
             A ^ an_tests = []
          then yes else no ), !T, !IO),

    % The beta holds its right input as an `alpha_node`, not as an id, so a
    % dangling one cannot be built.
    check("the beta holds its right ALPHA NODE, not its id",
        ( if load_dsc(sealed(Bytes), loaded(P2)),
             beta_nodes(network(P2)) = [B],
             B ^ bn_right ^ an_id = A_Id,
             alpha_nodes(network(P2)) = [A2],
             A2 ^ an_id = A_Id
          then yes else no ), !T, !IO),

    % `left_parent_id` omitted is proto3's zero, which is a root beta rather
    % than an absent optional [RDSC.4a.7].
    check("an omitted left_parent_id is a ROOT beta, not a missing field",
        ( if load_dsc(sealed(Bytes), loaded(P3)),
             beta_nodes(network(P3)) = [B3],
             B3 ^ bn_parent = no
          then yes else no ), !T, !IO),

    check("and it is reported as one, so the loader can seed its nil token",
        ( if load_dsc(sealed(Bytes), loaded(P4)),
             root_betas(network(P4)) = [_]
          then yes else no ), !T, !IO),

    check("the terminal holds its parent BETA NODE",
        ( if load_dsc(sealed(Bytes), loaded(P5)),
             terminal_nodes(network(P5)) = [Tm],
             beta_nodes(network(P5)) = [B5],
             Tm ^ tn_parent ^ bn_id = B5 ^ bn_id
          then yes else no ), !T, !IO),

    check("and its rule name, interned",
        ( if load_dsc(sealed(Bytes), loaded(P6)),
             terminal_nodes(network(P6)) = [Tm6],
             expand(interns(P6), Tm6 ^ tn_rule, "R")
          then yes else no ), !T, !IO),

    check("is_negative defaults to false -- a plain join, not a NOT node",
        ( if load_dsc(sealed(Bytes), loaded(P7)),
             beta_nodes(network(P7)) = [B7],
             B7 ^ bn_negative = no
          then yes else no ), !T, !IO),

    % `TerminalNode` field 9 is reserved: an artefact carrying it loads, the
    % field skipped as unknown. The bytes are a ten-byte sign-extended varint
    % for -10000, so skipping must get the length right.
    TermRetiredSalience = [0x0A, 0x15, 0xF2, 0x10, 0x12, 0x08, 0x03, 0x10,
         0x02, 0x1A, 0x01, 0x52, 0x48, 0xF0, 0xB1, 0xFF,
         0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0x01],

    check("a reserved TerminalNode field 9 is SKIPPED, and the terminal "
            ++ "still decodes",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta
                    ++ TermRetiredSalience), loaded(P8)),
             terminal_nodes(network(P8)) = [_]
          then yes else no ), !T, !IO),

    % TerminalNode carrying the retired field 8 -- skipped
    TermRetiredVars = [0x0A, 0x15, 0xF2, 0x10, 0x12, 0x08, 0x03, 0x10,
         0x02, 0x1A, 0x01, 0x52, 0x42, 0x09, 0x0A, 0x01,
         0x74, 0x10, 0x00, 0x18, 0xFF, 0xFF, 0x03],

    % `TerminalNode` field 8 is `reserved`: an unknown field, skipped as any
    % other is. The body holds a 0xFFFF slot index, which a decoder reading
    % the field as a slot would refuse.
    check("a TerminalNode carrying the reserved field 8 decodes, the field "
            ++ "skipped",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ TermRetiredVars),
                loaded(P11)),
             terminal_nodes(network(P11)) = [_]
          then yes else no ), !T, !IO),

    % `TerminalNode` field 5 is `reserved`: truth maintenance is the action's
    % ([IRET.12.1]). The field arrives length-delimited (`0x2A`, one byte), so
    % a decoder reading it as a varint refuses the body, and one that meets it
    % as an unknown field skips it.
    TermRetiredLogical = [0x0A, 0x0D, 0xF2, 0x10, 0x0A, 0x08, 0x03, 0x10,
         0x02, 0x1A, 0x01, 0x52, 0x2A, 0x01, 0x00],
    check("a TerminalNode carrying the reserved field 5 decodes, the field "
            ++ "skipped",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta
                    ++ TermRetiredLogical), loaded(PLogical)),
             terminal_nodes(network(PLogical)) = [_]
          then yes else no ), !T, !IO),

    % TerminalNode carrying a malformed field 6
    TermActions = [0x0A, 0x13, 0xF2, 0x10, 0x10, 0x08, 0x03, 0x10,
         0x02, 0x1A, 0x01, 0x52, 0x32, 0x07, 0x08, 0x01,
         0x12, 0x03, 0xFF, 0xFF, 0xFF],

    % Field 6 is the action list, and it is read. The body is
    % `kind = ACTION_ASSERT` followed by three `0xFF` bytes where the
    % expression belongs: a varint that never ends, so the action does not
    % decode. A decoder that ignored field 6 would load the terminal; this
    % one refuses the body `lek_decode`, before the ASSERT's missing
    % `schema_name` ([RDSC.8.7]) is judged ([RDSC.11.4]), as libds's
    % protobuf-c unpack refuses it.
    check("TerminalNode-inline actions (field 6) ARE decoded",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ TermActions),
                load_failed(ETi)),
             ETi ^ le_kind = lek_decode
          then yes else no ), !T, !IO),

    % The other half: the same terminal with no field 6 at all still loads.
    % An `after`-only rule produces exactly that, and the RHS grammar
    % `(action+ after_clause* | after_clause+)` makes it legal.
    check("a terminal with no actions AND no inline list still loads",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ Term),
                loaded(_))
          then yes else no ), !T, !IO),

    % AlphaNode with a CMP test: slot 0 > int 42
    AlfaTested = network_schema_s ++
        [0x0A, 0x14, 0xE2, 0x10, 0x11, 0x08, 0x01, 0x12,
         0x01, 0x53, 0x1A, 0x0A, 0x08, 0x01, 0x10, 0x00,
         0x18, 0x03, 0x22, 0x02, 0x08, 0x2A],

    check("an AlphaNode test decodes: slot 0 > int 42",
        ( if load_dsc(sealed(dsco_frame ++ AlfaTested ++ Beta ++ Term),
                loaded(P12)),
             alpha_nodes(network(P12)) = [A12],
             A12 ^ an_tests = [at_cmp(Slot, op_gt, al_int(42i64))],
             slot_index_value(Slot) = 0u32
          then yes else no ), !T, !IO),

    check("and op 3 is GT, not LTE -- the alpha enum orders LT, GT, LE, GE",
        ( if load_dsc(sealed(dsco_frame ++ AlfaTested ++ Beta ++ Term),
                loaded(P13)),
             alpha_nodes(network(P13)) = [A13],
             A13 ^ an_tests = [at_cmp(_, Op13, _)],
             Op13 = op_gt
          then yes else no ), !T, !IO),

    % AlphaNode with an EQ test: slot 1 == "x" (kind 0 is VALID)
    AlfaEqTest = network_schema_s ++
        [0x0A, 0x13, 0xE2, 0x10, 0x10, 0x08, 0x01, 0x12,
         0x01, 0x53, 0x1A, 0x09, 0x08, 0x00, 0x10, 0x01,
         0x22, 0x03, 0x1A, 0x01, 0x78],

    % ALPHA_TEST_EQ = 0, so proto3's default is a valid kind, unlike
    % `SlotKind`, where zero is UNSPECIFIED and the loader refuses it.
    check("kind 0 is a VALID alpha test kind (EQ), not an unset field",
        ( if load_dsc(sealed(dsco_frame ++ AlfaEqTest ++ Beta ++ Term),
                loaded(P14)),
             alpha_nodes(network(P14)) = [A14],
             A14 ^ an_tests = [at_eq(_, al_string(Ref))],
             expand(interns(P14), Ref, "x")
          then yes else no ), !T, !IO),

    % AlphaNode with a REGEX test
    AlfaRegex = network_schema_s ++
        [0x0A, 0x16, 0xE2, 0x10, 0x13, 0x08, 0x01, 0x12,
         0x01, 0x53, 0x1A, 0x0C, 0x08, 0x02, 0x10, 0x00,
         0x2A, 0x06, 0x5E, 0x61, 0x2E, 0x2A, 0x7A, 0x24],

    % A regex alpha test needs `regex` [RDSC.16.2.8], so these two carry a
    % CapabilityInfo requiring it (6 is CAPABILITY_REGEX) and differ in the
    % pattern alone.
    RegexDsco = dsco_only_ver(ds.version.ds_version) ++
        capb_frame_of([6], [6]),

    % [RDSC.4a.6], [RLOW.5.2.2]: a REGEX alpha test loads, and `ds.match`
    % answers it through `fn_regex_match`. The pattern is carried verbatim:
    % the decoder must build `at_regex` with exactly these bytes, since the
    % compiler folds the author's flags into them as `(?f:p)`.
    check("a REGEX alpha test loads, its pattern verbatim",
        ( if load_dsc(sealed(RegexDsco ++ AlfaRegex ++ Beta ++ Term),
                loaded(P15)),
             alpha_nodes(network(P15)) = [A15],
             A15 ^ an_tests = [at_regex(_, "^a.*z$")]
          then yes else no ), !T, !IO),

    % AlphaNode with a REGEX test RE2 refuses: `a(`, an unclosed group.
    AlfaBadRegex = network_schema_s ++
        [0x0A, 0x12, 0xE2, 0x10, 0x0F, 0x08, 0x01, 0x12,
         0x01, 0x53, 0x1A, 0x08, 0x08, 0x02, 0x10, 0x00,
         0x2A, 0x02, 0x61, 0x28],

    % [IRET.6.3]: the pattern is compiled at load, so one RE2 refuses fails
    % the load (`ds.dsc.invalid_alpha_regex`), as libds refuses it in
    % `rete/loader.c`. The same bytes with another pattern load above, so
    % this failure is the pattern's.
    check("a REGEX alpha test whose pattern RE2 refuses REFUSES the bundle",
        ( if load_dsc(sealed(RegexDsco ++ AlfaBadRegex ++ Beta ++ Term),
                R16),
             R16 = load_failed(load_error(lek_semantic, _, _, _, _))
          then yes else no ), !T, !IO),

    % AlphaNode with a CMP test carrying no literal
    AlfaNoLiteral = network_schema_s ++
        [0x0A, 0x10, 0xE2, 0x10, 0x0D, 0x08, 0x01, 0x12,
         0x01, 0x53, 0x1A, 0x06, 0x08, 0x01, 0x10, 0x00,
         0x18, 0x03],

    % There is no zero literal that would be right for all four types, so
    % absent is not defaultable.
    check("a comparison with no literal to compare against is refused",
        ( if load_dsc(sealed(dsco_frame ++ AlfaNoLiteral ++ Beta ++ Term),
                load_failed(_))
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%
% The Rete network: referential integrity
%-----------------------------------------------------------------------------%
%
% [RDSC.8.7]'s side conditions and [RDSC.11.1]'s `node_id` cross-references,
% which `ds.dsc`'s header claims collapse into `load_dsc`'s return type. Each
% case builds an artefact whose every atom decodes and whose network does not
% resolve.

    % One `rule_group` atom ahead of `Net`: naming the terminal's rule, the
    % artefact loads; naming another, it is refused as [RDSC.8.7]'s.
    %
:- pred check_rule_group_case(list(int)::in,
                              {string, int, list(int), list(int)}::in,
                              tally::in, tally::out, io::di, io::uo) is det.

check_rule_group_case(Net, {Label, Atom, Named, Ghost}, !T, !IO) :-
    check("[RDSC.8.7] a " ++ Label ++ " naming the terminal's rule loads",
        ( if load_dsc(sealed(dsco_frame ++ frame(Atom, Named) ++ Net),
                loaded(_))
          then yes else no ), !T, !IO),
    check("[RDSC.8.7] a " ++ Label ++ " naming no terminal's rule is "
            ++ "DSC_DANGLING",
        ( if load_dsc(sealed(dsco_frame ++ frame(Atom, Ghost) ++ Net),
                load_failed(E)),
             E ^ le_kind = lek_dangling,
             clause_id_string(E ^ le_clause) = "RDSC.8.7"
          then yes else no ), !T, !IO).

    % [RDSC.11.1]'s Framing and No padding: each row loaded as
    % the artefact's first frame and after a valid header, sealed with the bad
    % bytes in place ([RDSC.3.6]) so the header passes and the walk reaches
    % them. The same rows libds loads (test_dsc_basic.c,
    % test_rdsc_11_1__framing_table):
    %
    %   - a malformed frame is `lek_bad_first_atom` first (DS_ERR_DSC_BAD_MAGIC:
    %     not an atom container) and `lek_decode` later; an `Atom` with no
    %     oneof member keeps its own kind later, `lek_empty_atom`, which is
    %     DS_ERR_DSC_DECODE too;
    %   - the bytes running out inside a frame are `lek_truncated` wherever;
    %   - a body that ends early inside a complete frame is `lek_decode`
    %     wherever.
    %
    % A trailing 0x00 or 0xFF is a malformed frame, so an artefact padded with
    % either is refused, never loaded up to the padding.
    %
:- type framing_row
    --->    framing_row(string, list(int), load_error_kind, load_error_kind).

:- func rdsc_11_1_framing_rows = list(framing_row).

rdsc_11_1_framing_rows = [
    framing_row("an outer tag that is not 0x0A", [0x12, 0x00],
        lek_bad_first_atom, lek_decode),
    framing_row("a 0x00 (zero padding)", [0x00],
        lek_bad_first_atom, lek_decode),
    framing_row("a 0xFF (erased padding)", [0xFF],
        lek_bad_first_atom, lek_decode),
    framing_row("a run of 0xFF (erased padding)", [0xFF, 0xFF, 0xFF, 0xFF],
        lek_bad_first_atom, lek_decode),
    framing_row("an inner tag that is not length-delimited",
        [0x0A, 0x02, 0x08, 0x01], lek_bad_first_atom, lek_decode),
    framing_row("an inner fixed64 tag, its value cut short",
        [0x0A, 0x02, 0x09, 0x00], lek_bad_first_atom, lek_decode),
    framing_row("a varint past ten bytes",
        [0x0A, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80],
        lek_bad_first_atom, lek_decode),
    framing_row("a tenth varint byte past bit 63",
        [0x0A, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0x02],
        lek_bad_first_atom, lek_decode),
    framing_row("an Atom with no oneof member", [0x0A, 0x00],
        lek_bad_first_atom, lek_empty_atom),
    framing_row("a field number past 2^32",
        [0x0A, 0x06, 0x82, 0x80, 0x80, 0x80, 0x80, 0x01],
        lek_bad_first_atom, lek_decode),
    % An inner field number no atom has: 2048, key 16386 = 82 80 01, with an
    % empty body; and 0, key 0x02. Later, the kind is the runtime's own,
    % `lek_malformed_field_number`, which is DS_ERR_DSC_DECODE.
    framing_row("an inner field number no atom has (2048)",
        [0x0A, 0x04, 0x82, 0x80, 0x01, 0x00],
        lek_bad_first_atom, lek_malformed_field_number),
    framing_row("an inner field number of 0",
        [0x0A, 0x02, 0x02, 0x00],
        lek_bad_first_atom, lek_malformed_field_number),
    framing_row("bytes that run out inside a length", [0x0A, 0x80],
        lek_truncated, lek_truncated),
    framing_row("a length longer than the bytes that remain",
        [0x0A, 0x05, 0xBA, 0x10], lek_truncated, lek_truncated),
    framing_row("a length past 2^31",
        [0x0A, 0xFF, 0xFF, 0xFF, 0xFF, 0x0F, 0xBA],
        lek_truncated, lek_truncated),
    framing_row("a body that ends early inside its frame",
        [0x0A, 0x03, 0xBA, 0x10, 0x05], lek_decode, lek_decode),
    framing_row("an Atom's tag cut short inside its frame", [0x0A, 0x01, 0xBA],
        lek_decode, lek_decode)
].

    %@spec [RDSC.11.1]
:- pred rdsc_11_1_framing_row(framing_row::in, tally::in, tally::out,
                              io::di, io::uo) is det.

rdsc_11_1_framing_row(framing_row(What, Bytes, First, Later), !T, !IO) :-
    check("[RDSC.11.1] first frame, " ++ What,
        ( if load_dsc(sealed(Bytes), load_failed(EF)),
             EF ^ le_kind = First,
             clause_id_string(EF ^ le_clause) = "RDSC.11.1"
          then yes else no ), !T, !IO),
    check("[RDSC.11.1] after a header, " ++ What,
        ( if load_dsc(sealed(dsco_frame ++ Bytes), load_failed(EL)),
             EL ^ le_kind = Later,
             clause_id_string(EL ^ le_clause) = "RDSC.11.1"
          then yes else no ), !T, !IO).

    % [RDSC.9.5] before [RDSC.8.7]: `Ghost`, a `rule_group` atom
    % naming no terminal's rule, ahead of a network whose `Atom` body does not
    % decode. The load is refused for the body, at the frame it starts, and
    % not for the name: a resolution failure has offset 0 and no atom, so the
    % offset alone tells the two apart.
    %
:- pred check_undecodable_body_case(list(int)::in,
                                    {string, list(int), list(int), list(int)}::in,
                                    tally::in, tally::out, io::di, io::uo) is det.

check_undecodable_body_case(Ghost, {Atom, Before, Bad, After}, !T, !IO) :-
    Prefix = dsco_frame ++ Ghost ++ Before,
    check("[RDSC.9.5] an undecodable " ++ Atom ++ " body beside a dangling "
            ++ "name is refused for the body",
        ( if load_dsc(sealed(Prefix ++ Bad ++ After), load_failed(E)),
             E ^ le_kind = lek_decode,
             E ^ le_atom = yes(Atom),
             E ^ le_offset = yes(list.length(Prefix))
          then yes else no ), !T, !IO).

    % [RDSC.9.5]: "The error names the atom, the byte offset, and the
    % protobuf decoder's reason." An AlphaNode body carrying each of the
    % reader's four wire errors in turn, and a CapabilityInfo body of wire
    % type 7. libds is held to the same bodies and the same words
    % (test_dsc_basic.c, test_rdsc_9_5__the_refusal_names_the_decoders_reason).
    %
    %@spec [RDSC.9.5]
:- pred test_rdsc_9_5_decoder_reason(list(int)::in, tally::in, tally::out,
                                     io::di, io::uo) is det.

test_rdsc_9_5_decoder_reason(After, !T, !IO) :-
    list.foldl2(
        ( pred({Bad, Reason}::in, T0::in, T1::out, IO0::di, IO1::uo) is det :-
            check("[RDSC.9.5] an AlphaNode body refused: " ++ Reason,
                ( if
                    load_dsc(sealed(dsco_frame ++ network_schema_s
                        ++ frame(268, Bad) ++ After), load_failed(EA)),
                    EA ^ le_kind = lek_decode,
                    EA ^ le_atom = yes("AlphaNode"),
                    EA ^ le_offset = yes(_),
                    EA ^ le_reason = yes(Reason)
                  then yes else no ), T0, T1, IO0, IO1)
        ),
        [{[0x0F], "wire type 7 is not one DS writes"},
         {[0x08], "the body ends mid-value"},
         {[0x08, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF,
            0x01], "a varint is longer than ten bytes or carries bits above 64"},
         {[0x12, 0xFF, 0xFF, 0xFF, 0xFF, 0x0F],
            "a declared length does not fit"}],
        !T, !IO),
    check("[RDSC.9.5] a CapabilityInfo body refused: wire type 7 is not one "
            ++ "DS writes",
        ( if
            load_dsc(sealed(dsco_only_ver(ds.version.ds_version)
                ++ frame(265, [0x0F])), load_failed(EC)),
            EC ^ le_kind = lek_decode,
            EC ^ le_atom = yes("CapabilityInfo"),
            EC ^ le_reason = yes("wire type 7 is not one DS writes")
          then yes else no ), !T, !IO).

    % [RDSC.8.7]: the stream is parsed when every body is decoded in
    % full, a network node's shape included. `Ghost` ahead of a network one
    % of whose bodies, `Bad`, its own clause refuses: the load is refused for
    % the body, with that clause, and not for the name.
    %
:- pred check_body_shape_case(list(int)::in,
    {string, list(int), list(int), list(int), load_error_kind, string}::in,
    tally::in, tally::out, io::di, io::uo) is det.

check_body_shape_case(Ghost, {Label, Before, Bad, After, Kind, Clause},
        !T, !IO) :-
    check("[RDSC.8.7] " ++ Label ++ " beside a dangling name is refused for "
            ++ "the body",
        ( if load_dsc(sealed(dsco_frame ++ Ghost ++ Before ++ Bad ++ After),
                load_failed(E)),
             E ^ le_kind = Kind,
             clause_id_string(E ^ le_clause) = Clause
          then yes else no ), !T, !IO).

:- pred test_network_integrity(tally::in, tally::out, io::di, io::uo) is det.

test_network_integrity(!T, !IO) :-
    Alfa = network_schema_s ++
        [0x0A, 0x08, 0xE2, 0x10, 0x05, 0x08, 0x01, 0x12, 0x01, 0x53],
    Beta = [0x0A, 0x07, 0xEA, 0x10, 0x04, 0x08, 0x02, 0x10,
         0x01],

    % BetaNode whose right_alpha_id names no AlphaNode
    BetaDangling = [0x0A, 0x07, 0xEA, 0x10, 0x04, 0x08, 0x02, 0x10,
         0x63],

    % A `node_id` naming no node is `DS_ERR_RETP_INDEX_OOB` [RDSC.11.1], not
    % [RDSC.8.7]'s `DS_ERR_DSC_DANGLING`, which is for names.
    check("a BetaNode whose right_alpha_id names no AlphaNode is "
            ++ "RETP_INDEX_OOB",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaDangling),
                load_failed(E1)),
             E1 ^ le_kind = lek_retp_index_oob,
             clause_id_string(E1 ^ le_clause) = "RDSC.11.1"
          then yes else no ), !T, !IO),

    % A BetaNode with no alpha at all in the bundle: the same fault, and its
    % own case because an empty map and a map missing one key are different
    % code paths.
    check("and so is one in a bundle with no AlphaNode at all",
        ( if load_dsc(sealed(dsco_frame ++ Beta), load_failed(E2)),
             E2 ^ le_kind = lek_retp_index_oob
          then yes else no ), !T, !IO),

    % BetaNode 2 whose left_parent_id names BetaNode 9, which no atom is
    BetaNoParent = frame(269, [0x08, 0x02, 0x10, 0x01, 0x18, 0x09]),
    check("a BetaNode whose left_parent_id names no BetaNode is "
            ++ "RETP_INDEX_OOB",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaNoParent),
                load_failed(E2b)),
             E2b ^ le_kind = lek_retp_index_oob,
             clause_id_string(E2b ^ le_clause) = "RDSC.11.1"
          then yes else no ), !T, !IO),

    % TerminalNode whose parent_beta_id names no BetaNode
    TermDangling = [0x0A, 0x0A, 0xF2, 0x10, 0x07, 0x08, 0x03, 0x10,
         0x58, 0x1A, 0x01, 0x52],

    check("a TerminalNode whose parent_beta_id names no BetaNode is "
            ++ "RETP_INDEX_OOB",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ TermDangling),
                load_failed(E3)),
             E3 ^ le_kind = lek_retp_index_oob,
             clause_id_string(E3 ^ le_clause) = "RDSC.11.1"
          then yes else no ), !T, !IO),

    % [RDSC.9.9]: a TERM with an empty `rule_name` loads, as in libds
    % (test_dsc_basic.c, test_rdsc_9_9__terminal_with_empty_rule_name_loads),
    % and its rule is "": the field omitted (proto3's "") and the field
    % written empty.
    TermNoName = frame(270, [0x08, 0x03, 0x10, 0x02]),
    TermEmptyName = frame(270, [0x08, 0x03, 0x10, 0x02, 0x1A, 0x00]),
    check("[RDSC.9.9] a TERM with rule_name omitted loads, its rule \"\"",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ TermNoName),
                loaded(PNoName)),
             terminal_nodes(network(PNoName)) = [TmNoName],
             expand(interns(PNoName), TmNoName ^ tn_rule, "")
          then yes else no ), !T, !IO),
    check("[RDSC.9.9] a TERM with rule_name written empty loads, its rule \"\"",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ TermEmptyName),
                loaded(PEmptyName)),
             terminal_nodes(network(PEmptyName)) = [TmEmptyName],
             expand(interns(PEmptyName), TmEmptyName ^ tn_rule, "")
          then yes else no ), !T, !IO),

    % [RDSC.8.7]: an AlphaNode's schema is one the artefact declares.
    % The same alpha, beta and terminal as `Alfa ++ Beta ++ Term`, with the
    % schema group the alpha names left out.
    AlfaBare = frame(268, [0x08, 0x01, 0x12, 0x01, 0x53]),     % 1, "S"
    Term = frame(270, [0x08, 0x03, 0x10, 0x02, 0x1A, 0x01, 0x52]),
                                                            % 3, parent 2, "R"
    check("[RDSC.8.7] the same network with its schema group loads",
        ( if load_dsc(sealed(dsco_frame ++ network_schema_s ++ AlfaBare
                ++ Beta ++ Term), loaded(_))
          then yes else no ), !T, !IO),
    check("[RDSC.8.7] an AlphaNode naming a schema no schema group declares "
            ++ "is DSC_DANGLING",
        ( if load_dsc(sealed(dsco_frame ++ AlfaBare ++ Beta ++ Term),
                load_failed(E6)),
             E6 ^ le_kind = lek_dangling,
             clause_id_string(E6 ^ le_clause) = "RDSC.8.7"
          then yes else no ), !T, !IO),
    % A schema group for "T" is a schema group, and not the one "S" names: the
    % refusal is about the name, not about the artefact having no schemas.
    SlogT = frame(299, [0x0A, 0x01, 0x54, 0x18, 0x01]),     % "T", EXPLICIT
    SlotT = frame(257, [0x0A, 0x01, 0x54, 0x12, 0x01, 0x74, 0x18, 0x02]),
    check("[RDSC.8.7] and so is one beside another schema's group",
        ( if load_dsc(sealed(dsco_frame ++ SlogT ++ SlotT ++ AlfaBare ++ Beta
                ++ Term), load_failed(E7)),
             E7 ^ le_kind = lek_dangling
          then yes else no ), !T, !IO),

    % [RDSC.8.7]: a `rule_group`'s atoms name a rule a TerminalNode
    % realizes. `Term` is rule "R" (0x52); each atom, on its own, names "R"
    % (which loads) or "G" (0x47, no terminal's). A `RuleDebugName` with no
    % template sets nothing and still names a rule. libds is held to the same
    % cases (test_dsc_basic.c, test_rdsc_8_7__rule_group_names_a_terminal).
    list.foldl2(check_rule_group_case(network_schema_s ++ AlfaBare ++ Beta
            ++ Term),
        [{"RuleCooldown", 307,
            [0x0A, 0x01, 0x52, 0x10, 0x05], [0x0A, 0x01, 0x47, 0x10, 0x05]},
         {"RuleSource", 309,
            [0x0A, 0x01, 0x52, 0x18, 0x01, 0x20, 0x01],
            [0x0A, 0x01, 0x47, 0x18, 0x01, 0x20, 0x01]},
         {"RuleDebugName", 310,
            [0x0A, 0x01, 0x52, 0x12, 0x01, 0x78],
            [0x0A, 0x01, 0x47, 0x12, 0x01, 0x78]},
         {"RuleDebugName with no template", 310,
            [0x0A, 0x01, 0x52], [0x0A, 0x01, 0x47]}],
        !T, !IO),

    % [RDSC.9.5] before [RDSC.8.7]: each node body in turn is one byte, field
    % 1 with wire type 7, which no protobuf field has, beside a RuleCooldown
    % naming "G". With every body intact that artefact is refused as dangling
    % (`check_rule_group_case` above). libds is held to the same cases
    % (test_dsc_basic.c, test_rdsc_9_5__undecodable_body_before_dangling_name).
    list.foldl2(check_undecodable_body_case(
            frame(307, [0x0A, 0x01, 0x47, 0x10, 0x05])),
        [{"AlphaNode", network_schema_s, frame(268, [0x0F]), Beta ++ Term},
         {"BetaNode", network_schema_s ++ AlfaBare, frame(269, [0x0F]), Term},
         {"TerminalNode", network_schema_s ++ AlfaBare ++ Beta,
            frame(270, [0x0F]), []}],
        !T, !IO),
    test_rdsc_9_5_decoder_reason(Beta ++ Term, !T, !IO),

    % [RDSC.8.7]: and a body that decodes, but whose shape its own clause
    % refuses, beside the same RuleCooldown: a node id of 0 on each node atom
    % [RDSC.4a.3], an AlphaNode naming no schema [RDSC.4a.6], and a BetaNode
    % join test that is an `Expr` of no kind [RDSC.11.3]. libds is held to the
    % same cases (test_dsc_basic.c,
    % test_rdsc_8_7__body_shape_before_dangling_name).
    list.foldl2(check_body_shape_case(
            frame(307, [0x0A, 0x01, 0x47, 0x10, 0x05])),
        [{"an AlphaNode with node_id 0", network_schema_s,
            frame(268, [0x12, 0x01, 0x53]), Beta ++ Term,
            lek_retp_invalid, "RDSC.4a.3"},
         {"a BetaNode with node_id 0", network_schema_s ++ AlfaBare,
            frame(269, [0x10, 0x01]), Term,
            lek_retp_invalid, "RDSC.4a.3"},
         {"a TerminalNode with node_id 0", network_schema_s ++ AlfaBare ++ Beta,
            frame(270, [0x10, 0x02, 0x1A, 0x01, 0x52]), [],
            lek_retp_invalid, "RDSC.4a.3"},
         {"an AlphaNode naming no schema", network_schema_s,
            frame(268, [0x08, 0x01]), Beta ++ Term,
            lek_semantic, "RDSC.4a.6"},
         {"a BetaNode join test of no kind", network_schema_s ++ AlfaBare,
            frame(269, [0x08, 0x02, 0x10, 0x01, 0x22, 0x00]), Term,
            lek_semantic, "RDSC.11.3"}],
        !T, !IO),

    % [RDSC.4a.6.1]: each malformed `AlphaTest` shape, refused as the
    % AlphaNode's body is decoded, and so for the body beside the same
    % RuleCooldown. libds is held to the same cases (test_dsc_basic.c,
    % test_rdsc_4a_6_1__malformed_alpha_test). "an AlphaNode test decodes:
    % slot 0 > int 42" (test_network) is the CMP test these edit, loading.
    list.foldl2(check_body_shape_case(
            frame(307, [0x0A, 0x01, 0x47, 0x10, 0x05])),
        list.map(
            ( func(Case) = Row :-
                Case = {Label, Test},
                Row = {Label, network_schema_s,
                    frame(268, alpha_with_test(Test)), Beta ++ Term,
                    lek_semantic, "RDSC.4a.6.1"} ),
            [{"an AlphaTest of no AlphaTestKind",
                [0x08, 0x03, 0x10, 0x00, 0x22, 0x02, 0x08, 0x2A]},
             {"an EQ AlphaTest with no literal",
                [0x10, 0x00]},
             {"an EQ AlphaTest whose literal sets no member",
                [0x10, 0x00, 0x22, 0x00]},
             {"a CMP AlphaTest with no literal",
                [0x08, 0x01, 0x10, 0x00, 0x18, 0x03]},
             {"a CMP AlphaTest whose op is no AlphaCmpOp",
                [0x08, 0x01, 0x10, 0x00, 0x18, 0x06, 0x22, 0x02, 0x08, 0x2A]},
             {"a REGEX AlphaTest with no pattern",
                [0x08, 0x02, 0x10, 0x00]},
             {"an AlphaTest slot_index of 255",
                [0x08, 0x01, 0x10, 0xFF, 0x01, 0x18, 0x03,
                 0x22, 0x02, 0x08, 0x2A]}]),
        !T, !IO),

    % [RDSC.4a.6.1] with [RDSC.4a.9.1]: AlphaTest's index has no marker, so
    % 254 is the last, and loads.
    check("[RDSC.4a.6.1] an AlphaTest slot_index of 254 loads",
        ( if load_dsc(sealed(dsco_frame ++ network_schema_s
                ++ frame(268, alpha_with_test(
                    [0x08, 0x01, 0x10, 0xFE, 0x01, 0x18, 0x03,
                     0x22, 0x02, 0x08, 0x2A]))
                ++ Beta ++ Term), loaded(P254)),
             alpha_nodes(network(P254)) = [A254],
             A254 ^ an_tests = [at_cmp(S254, op_gt, al_int(42i64))],
             slot_index_value(S254) = 254u32
          then yes else no ), !T, !IO),

    % An enum is its varint's low 32 bits, as protobuf-c reads it, so a kind of
    % 2^32 is EQ and an op of 2^32 + 3 is GT. libds is held to the same bytes.
    check("[RDSC.4a.6.1] an AlphaTest kind of 2^32 is EQ, its low 32 bits",
        ( if load_dsc(sealed(dsco_frame ++ network_schema_s
                ++ frame(268, alpha_with_test(
                    [0x08, 0x80, 0x80, 0x80, 0x80, 0x10, 0x10, 0x00,
                     0x22, 0x02, 0x08, 0x2A]))
                ++ Beta ++ Term), loaded(PKind)),
             alpha_nodes(network(PKind)) = [AKind],
             AKind ^ an_tests = [at_eq(_, al_int(42i64))]
          then yes else no ), !T, !IO),
    check("[RDSC.4a.6.1] an AlphaTest op of 2^32 + 3 is GT, its low 32 bits",
        ( if load_dsc(sealed(dsco_frame ++ network_schema_s
                ++ frame(268, alpha_with_test(
                    [0x08, 0x01, 0x10, 0x00, 0x18, 0x83, 0x80, 0x80, 0x80,
                     0x10, 0x22, 0x02, 0x08, 0x2A]))
                ++ Beta ++ Term), loaded(POp)),
             alpha_nodes(network(POp)) = [AOp],
             AOp ^ an_tests = [at_cmp(_, op_gt, al_int(42i64))]
          then yes else no ), !T, !IO),

    % Two betas naming each other as left parent. Every id resolves and the
    % structure still cannot be built, because a Mercury term cannot contain
    % itself ([RDSC.4a.5]).
    % BetaNode 2, left parent 4
    BetaCycleA = [0x0A, 0x09, 0xEA, 0x10, 0x06, 0x08, 0x02, 0x10,
         0x01, 0x18, 0x04],
    % BetaNode 4, left parent 2 -- the cycle
    BetaCycleB = [0x0A, 0x09, 0xEA, 0x10, 0x06, 0x08, 0x04, 0x10,
         0x01, 0x18, 0x02],

    check("a CYCLE in the left-parent chain is refused, not followed",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaCycleA ++ BetaCycleB),
                load_failed(E4)),
             clause_id_string(E4 ^ le_clause) = "RDSC.4a.5"
          then yes else no ), !T, !IO),

    % BetaNode reusing AlphaNode 1's node_id -- bundle-global clash
    BetaDupId = [0x0A, 0x07, 0xEA, 0x10, 0x04, 0x08, 0x01, 0x10,
         0x01],

    % `node_id` is bundle-global across the three atom types [RDSC.4a.3], so a
    % per-type uniqueness check misses this. DS_ERR_RETP_INVALID, libds's code
    % for a second key in its node map.
    check("a node_id shared between an AlphaNode and a BetaNode is refused, "
            ++ "RETP_INVALID",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaDupId),
                load_failed(E5)),
             E5 ^ le_kind = lek_retp_invalid,
             clause_id_string(E5 ^ le_clause) = "RDSC.4a.3"
          then yes else no ), !T, !IO),

    % Zero is the reserved null, so no node may be named by it.
    % DS_ERR_RETP_INVALID, as libds's node map refuses it.
    AlfaZeroId = frame(268, [0x08, 0x00, 0x12, 0x01, 0x53]),
    check("a node_id of zero is refused, RETP_INVALID -- zero is the "
            ++ "reserved null",
        ( if load_dsc(sealed(dsco_frame ++ AlfaZeroId), load_failed(EZeroId)),
             EZeroId ^ le_kind = lek_retp_invalid
          then yes else no ), !T, !IO),

    % A BetaNode arriving before the BetaNode it names as parent. The emission
    % grammar guarantees AlphaNode-before-BetaNode and nothing else, so this
    % must work.
    BetaChild = frame(269, [0x08, 0x04, 0x10, 0x01, 0x18, 0x02]),
    check("a forward left_parent_id reference resolves -- child before parent",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaChild ++ Beta),
                loaded(P)),
             beta_nodes(network(P)) = [Child, _Parent],
             Child ^ bn_parent = yes(Resolved),
             node_id_value(Resolved ^ bn_id) = 2u32
          then yes else no ), !T, !IO),

    % ...and the encounter order survives resolution's internal reordering.
    % Nothing on the wire records it and it is semantic.
    check("and the emitted order survives resolution",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaChild ++ Beta),
                loaded(P2)),
             beta_nodes(network(P2)) = [First, Second],
             node_id_value(First ^ bn_id) = 4u32,
             node_id_value(Second ^ bn_id) = 2u32
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%
% [RDSC.9.10] No NaN in an artefact's doubles
%-----------------------------------------------------------------------------%
%
% Each of the four `double` fields holding a quiet NaN and a signalling one is
% refused, `lek_semantic` under the clause, and holding +inf loads. A NaN is
% judged on what the decoded atom holds: one a later member or field
% replaced is not held, in an `Expr`, an `AlphaLiteral`, a `Slot` and an
% `InitialFact`'s literal alike; and a body that fails to decode is
% `lek_decode` [RDSC.11.1] whatever NaN it carries, as is a seed with a second
% `value` ([RDSC.9.5]; `test_rdsc_9_5_repeated`). A malformed test is refused
% for its shape first, as libds's `decode_alfa` orders it.
% Path: `ds.dsc`'s `literal_field`, `test_slot_literal` and
% `lgra_24_3_decode_ifct` / `_icac`, against libds's `initial_literal` and
% `handle_initial`. libds is held to the same bytes (test_dsc_basic.c,
% test_rdsc_9_10__nan_doubles_refused).

:- pred test_rdsc_9_10_nan_doubles(tally::in, tally::out, io::di, io::uo)
    is det.

test_rdsc_9_10_nan_doubles(!T, !IO) :-
    % Little-endian binary64: a quiet NaN (0x7FF8000000000000), a signalling
    % one (0x7FF0000000000001), +inf (0x7FF0000000000000) and 1.5
    % (0x3FF8000000000000).
    QNaN = [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xF8, 0x7F],
    SNaN = [0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0xF0, 0x7F],
    PInf = [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xF0, 0x7F],
    OnePointFive = [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xF8, 0x3F],

    Alfa = network_schema_s ++ frame(268, [0x08, 0x01, 0x12, 0x01, 0x53]),
    Slog = frame(299, [0x0A, 0x01, 0x53, 0x18, 0x02]),     % "S", LOGICAL
    % Expr.lit_float: field 2, fixed64, tag 0x11; BetaNode 2's join test.
    ExprArt = ( func(Bits) =
        dsco_frame ++ Alfa ++ frame(269, beta_with_test([0x11] ++ Bits)) ),
    % An EQ AlphaTest on slot 0 whose AlphaLiteral's float_val (field 2,
    % tag 0x11) is Bits.
    AlphaArt = ( func(Bits) =
        dsco_frame ++ network_schema_s ++ frame(268, alpha_with_test(
            [0x10, 0x00, 0x22, 0x09, 0x11] ++ Bits)) ),
    % Slot "S"."t", FLOAT, MUTABLE, whose tolerance (field 7, tag 0x39) is
    % Bits.
    TolArt = ( func(Bits) =
        dsco_frame ++ Slog ++ frame(257,
            [0x0A, 0x01, 0x53, 0x12, 0x01, 0x74, 0x18, 0x02, 0x39] ++ Bits
                ++ [0x48, 0x02]) ),
    % InitialFact (131): clip 1, schema "S", one TestSlotLiteral "t" whose
    % f_val (field 3, tag 0x19) is Bits.
    IfctArt = ( func(Bits) =
        dsco_frame ++ network_schema_s ++ frame(131,
            [0x08, 0x01, 0x12, 0x01, 0x53, 0x1A, 0x0C, 0x0A, 0x01, 0x74, 0x19]
                ++ Bits) ),
    % InitialCacheSeed (132): clip 1, key "k", a value whose f_val is Bits.
    IcacArt = ( func(Bits) =
        dsco_frame ++ network_schema_s ++ frame(132,
            [0x08, 0x01, 0x12, 0x01, 0x6B, 0x1A, 0x09, 0x19] ++ Bits) ),

    % A NaN tolerance, then a second tolerance of 1.5.
    TolReplaced = dsco_frame ++ Slog ++ frame(257,
        [0x0A, 0x01, 0x53, 0x12, 0x01, 0x74, 0x18, 0x02, 0x39] ++ QNaN
            ++ [0x39] ++ OnePointFive ++ [0x48, 0x02]),
    % A seed whose first `value` holds a NaN f_val and whose second holds 1.5.
    IcacReplaced = dsco_frame ++ network_schema_s ++ frame(132,
        [0x08, 0x01, 0x12, 0x01, 0x6B, 0x1A, 0x09, 0x19] ++ QNaN
            ++ [0x1A, 0x09, 0x19] ++ OnePointFive),

    Refused = yes({lek_semantic, "RDSC.9.10"}),
    Undecoded = yes({lek_decode, "RDSC.11.1"}),
    Fields = ( func(What, Bits, Want) =
        [{"an Expr.lit_float holding " ++ What, ExprArt(Bits), Want},
         {"an AlphaLiteral.float_val holding " ++ What, AlphaArt(Bits), Want},
         {"a Slot.tolerance holding " ++ What, TolArt(Bits), Want},
         {"an InitialFact's TestSlotLiteral.f_val holding " ++ What,
            IfctArt(Bits), Want},
         {"an InitialCacheSeed's TestSlotLiteral.f_val holding " ++ What,
            IcacArt(Bits), Want}] ),
    Cases =
        Fields("a quiet NaN", QNaN, Refused) ++
        Fields("a signalling NaN", SNaN, Refused) ++
        Fields("+inf", PInf, no) ++
        [{"an Expr whose NaN lit_float a later lit_bool replaces",
            dsco_frame ++ Alfa ++ frame(269,
                beta_with_test([0x11] ++ QNaN ++ [0x20, 0x01])), no},
         {"an AlphaLiteral whose NaN float_val a later int_val replaces",
            dsco_frame ++ network_schema_s ++ frame(268, alpha_with_test(
                [0x10, 0x00, 0x22, 0x0B, 0x11] ++ QNaN ++ [0x08, 0x2A])), no},
         {"a Slot whose NaN tolerance a later 1.5 replaces", TolReplaced, no},
         {"a CMP AlphaTest whose op is no AlphaCmpOp, before its NaN literal,",
            dsco_frame ++ network_schema_s ++ frame(268, alpha_with_test(
                [0x08, 0x01, 0x10, 0x00, 0x18, 0x06, 0x22, 0x09, 0x11]
                    ++ QNaN)),
            yes({lek_semantic, "RDSC.4a.6.1"})},
         % RDSC_9_10_IFCT_TRUNCATED: f_val NaN, then a `slot_name` whose
         % length runs past the literal. The body fails decode, so DECODE.
         {"a TestSlotLiteral whose NaN f_val a field that does not parse "
                ++ "follows, as DECODE,",
            dsco_frame ++ network_schema_s ++ frame(131,
                [0x08, 0x01, 0x12, 0x01, 0x53, 0x1A, 0x0E, 0x0A, 0x01, 0x74,
                 0x19] ++ QNaN ++ [0x0A, 0x05]),
            Undecoded},
         % RDSC_9_10_IFCT_REPLACED: an InitialFact slot "t", f_val NaN, then
         % i_val 1 (field 2, tag 0x10). The literal's oneof ends on i_val.
         {"an InitialFact literal whose NaN f_val a later i_val replaces",
            dsco_frame ++ network_schema_s ++ frame(131,
                [0x08, 0x01, 0x12, 0x01, 0x53, 0x1A, 0x0E, 0x0A, 0x01, 0x74,
                 0x19] ++ QNaN ++ [0x10, 0x01]),
            no},
         % RDSC_9_10_ICAC_REPLACED: a second `value` is no replacement
         % ([RDSC.9.5]).
         {"a seed whose NaN value a second value of 1.5 follows, as DECODE,",
            IcacReplaced, yes({lek_decode, "RDSC.9.5"})}],
    list.foldl2(
        ( pred(Case::in, T0::in, T1::out, IO0::di, IO1::uo) is det :-
            Case = {Label, Bytes, Want},
            check("[RDSC.9.10] " ++ Label
                    ++ ( if Want = no then " loads" else " is refused" ),
                ( if
                    load_dsc(sealed(Bytes), R),
                    (
                        Want = no,
                        R = loaded(_)
                    ;
                        Want = yes({Kind, Clause}),
                        R = load_failed(E),
                        E ^ le_kind = Kind,
                        clause_id_string(E ^ le_clause) = Clause
                    )
                  then yes else no ), T0, T1, IO0, IO1)
        ),
        Cases, !T, !IO),

    % The tolerance the later field gave is the one kept.
    check("[RDSC.9.10] the replacing tolerance is the slot's",
        ( if load_dsc(sealed(TolReplaced), loaded(P)),
             schemas(P) = [S],
             S ^ s_lifecycle = lc_logical([L], _),
             L ^ ls_tolerance = within(1.5)
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%
% [RDSC.9.5] A message field that is not repeated, more than once
%-----------------------------------------------------------------------------%
%
% A body in which a singular message field, or a message-typed member of a
% oneof, occurs more than once, at any depth, is refused `lek_decode` under
% the clause, and the refusal names the atom; the same body holding the field
% once loads. So is a header holding `dsc_sha256` twice. A scalar twice is
% held as its last, as a control. Path: for the network atoms,
% `ds.dsc_judge`'s walk, which `ds.dsc_network` asks before its decoders run
% ([RDSC.11.4]), so each case pins its field's row in the judge's tables,
% which are generated from the protos where
% libds reads protobuf-c's descriptors of them: an Action's `expr`,
% `ttl_override` and `withdraw_fact_id`, a SlotAssign's `expr`, an Expr's
% `if_` and `binop`, a binop's `left`, a CoalesceExpr's `right`, a
% FormatPrim's `value`, a TimePrim's `value`, a TerminalNode's `fire_guard`
% and an AlphaTest's `literal`. For the others,
% `ds.dsc.decode_svcd`, `lgra_24_3_decode_icac` and `check_header`. libds is
% held to the same bytes (test_dsc_basic.c,
% test_rdsc_9_5__repeated_message_field_refused), but for the TerminalNode
% the network atoms carry there.

:- pred test_rdsc_9_5_repeated(tally::in, tally::out, io::di, io::uo) is det.

test_rdsc_9_5_repeated(!T, !IO) :-
    % Little-endian binary64: 1.0 and 1.5.
    One = [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xF0, 0x3F],
    OnePointFive = [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xF8, 0x3F],
    Alfa = network_schema_s ++ frame(268, [0x08, 0x01, 0x12, 0x01, 0x53]),
    % An EQ AlphaTest on slot 0 whose literal's float_val is 1.5, and a
    % second, empty literal.
    LitOnce = [0x10, 0x00, 0x22, 0x09, 0x11] ++ OnePointFive,
    AlphaArt = ( func(Test) =
        dsco_frame ++ network_schema_s ++ frame(268, alpha_with_test(Test)) ),
    % A join test `1 == 1`: an Expr's binop (field 6), a BinopExpr's op EQ
    % (6), left (2) and right (3), each an Expr's lit_int (1).
    Binop = [0x32, 0x0A, 0x08, 0x06, 0x12, 0x02, 0x08, 0x01,
             0x1A, 0x02, 0x08, 0x01],
    Nested = [0x32, 0x0E, 0x08, 0x06, 0x12, 0x02, 0x08, 0x01,
              0x12, 0x02, 0x08, 0x02, 0x1A, 0x02, 0x08, 0x01],
    BetaArt = ( func(Test) =
        dsco_frame ++ Alfa ++ frame(269, beta_with_test(Test)) ),
    % TerminalNode 3 under BetaNode 2, rule "R", whose fire_guard (field 7)
    % is lit_bool true, twice.
    Guard = [0x3A, 0x02, 0x20, 0x01],
    GuardTwice = dsco_frame ++ Alfa ++ frame(269, [0x08, 0x02, 0x10, 0x01])
        ++ frame(270, [0x08, 0x03, 0x10, 0x02, 0x1A, 0x01, 0x52]
            ++ Guard ++ Guard),
    % A second `dsc_sha256` (field 7, length 32) in the header.
    ShaTwice = dsco_frame_plus([0x3A, 0x20] ++ list.duplicate(32, 0x00)),
    % InitialCacheSeed (132): module 1, key "k", value f_val 1.0, then value
    % f_val 1.5.
    IcacTwice = dsco_frame ++ network_schema_s ++ frame(132,
        [0x08, 0x01, 0x12, 0x01, 0x6B, 0x1A, 0x09, 0x19] ++ One
            ++ [0x1A, 0x09, 0x19] ++ OnePointFive),
    % Slot "S"."t", FLOAT, MUTABLE, whose tolerance (field 7) is 1.0, then
    % 1.5: a scalar.
    Slog = frame(299, [0x0A, 0x01, 0x53, 0x18, 0x02]),     % "S", LOGICAL
    TolTwice = dsco_frame ++ Slog ++ frame(257,
        [0x0A, 0x01, 0x53, 0x12, 0x01, 0x74, 0x18, 0x02, 0x39] ++ One
            ++ [0x39] ++ OnePointFive ++ [0x48, 0x02]),

    % Join tests, each Expr body whole. `if true then true else
    % true`: Expr.if_ (field 12), an IfExpr whose cond, then_ and else_ are
    % each lit_bool true.
    If = [0x62, 0x0C, 0x0A, 0x02, 0x20, 0x01, 0x12, 0x02, 0x20, 0x01,
          0x1A, 0x02, 0x20, 0x01],
    % `true ?? true`: Expr.coalesce (field 17), a CoalesceExpr's left and
    % right; then the same with right twice.
    Coalesce = [0x8A, 0x01, 0x08, 0x0A, 0x02, 0x20, 0x01,
                0x12, 0x02, 0x20, 0x01],
    CoalesceRight2 = [0x8A, 0x01, 0x0C, 0x0A, 0x02, 0x20, 0x01,
                      0x12, 0x02, 0x20, 0x01, 0x12, 0x02, 0x20, 0x01],
    % An interpolated string, Expr.interp (field 20), of one FormatPrim
    % whose `value` member (field 2) is a ValuePrim of lit_int 1; then that
    % member twice.
    ValuePrim = [0xA2, 0x01, 0x08, 0x0A, 0x06,
                 0x12, 0x04, 0x0A, 0x02, 0x08, 0x01],
    ValuePrim2 = [0xA2, 0x01, 0x0E, 0x0A, 0x0C,
                  0x12, 0x04, 0x0A, 0x02, 0x08, 0x01,
                  0x12, 0x04, 0x0A, 0x02, 0x08, 0x01],
    % The same, the FormatPrim's `time` member (field 3) a TimePrim whose
    % `value` is lit_int 1, with no items; then that `value` twice.
    TimePrim = [0xA2, 0x01, 0x08, 0x0A, 0x06,
                0x1A, 0x04, 0x0A, 0x02, 0x08, 0x01],
    TimePrim2 = [0xA2, 0x01, 0x0C, 0x0A, 0x0A,
                 0x1A, 0x08, 0x0A, 0x02, 0x08, 0x01, 0x0A, 0x02, 0x08, 0x01],

    % TerminalNode 3's one action, with `Binds` after it. A runtime
    % `let`: ACTION_CALL (kind 0, absent) whose expr (field 2) is Expr.bind
    % (field 13), bind_index 0 := lit_int 1, under a bind_count of 1.
    TermArt = ( func(Action, Binds) =
        dsco_frame ++ Alfa ++ frame(269, [0x08, 0x02, 0x10, 0x01])
            ++ frame(270, term_with_action(Action) ++ Binds) ),
    Let = [0x12, 0x06, 0x6A, 0x04, 0x12, 0x02, 0x08, 0x01],
    BindCount = [0x20, 0x01],
    % ACTION_ASSERT "S" whose one SlotAssign sets slot 0 := lit_int 1
    % (`test_rdsc_4a_9_1_index_bounds`'s); then that assignment's expr twice;
    % then the assert with a ttl_override (field 5) of lit_int 1, once and
    % twice.
    Assert = [0x08, 0x01, 0x1A, 0x01, 0x53, 0x22, 0x04, 0x12, 0x02, 0x08, 0x01],
    Assign2 = [0x08, 0x01, 0x1A, 0x01, 0x53,
               0x22, 0x08, 0x12, 0x02, 0x08, 0x01, 0x12, 0x02, 0x08, 0x01],
    Ttl = [0x2A, 0x02, 0x08, 0x01],
    % ACTION_WITHDRAW_BY_ID whose withdraw_fact_id (field 7) is the fact at
    % pattern 0 itself (VarExpr slot 255); then that field twice.
    FactId = [0x3A, 0x05, 0x2A, 0x03, 0x10, 0xFF, 0x01],
    ById = [0x08, 0x04] ++ FactId,
    % ServiceDef (311) "s", `no response`, whose hydration (field 4) is an
    % empty ServiceHydration, once and twice.
    SvcdArt = ( func(Hydration) =
        dsco_frame ++ frame(311, [0x0A, 0x01, 0x73, 0x28, 0x01] ++ Hydration) ),
    Hydration = [0x22, 0x00],

    Cases =
        [{"an AlphaTest holding its literal once", AlphaArt(LitOnce), no},
         {"an AlphaTest holding its literal twice",
            AlphaArt(LitOnce ++ [0x22, 0x00]), yes("AlphaNode")},
         {"an Expr holding its binop member once", BetaArt(Binop), no},
         {"an Expr holding its binop member twice", BetaArt(Binop ++ Binop),
            yes("BetaNode")},
         {"a binop holding its left operand twice", BetaArt(Nested),
            yes("BetaNode")},
         {"a TerminalNode holding its fire_guard twice", GuardTwice,
            yes("TerminalNode")},
         {"a DscHeader holding its dsc_sha256 twice", ShaTwice,
            yes("DscHeader")},
         {"a seed holding its value twice", IcacTwice,
            yes("InitialCacheSeed")},
         {"a Slot holding its tolerance, a scalar, twice", TolTwice, no},
         {"an Action holding its expr once", TermArt(Let, BindCount), no},
         {"an Action holding its expr twice", TermArt(Let ++ Let, BindCount),
            yes("TerminalNode")},
         {"an Action holding its ttl_override once", TermArt(Assert ++ Ttl, []),
            no},
         {"an Action holding its ttl_override twice",
            TermArt(Assert ++ Ttl ++ Ttl, []), yes("TerminalNode")},
         {"an Action holding its withdraw_fact_id once", TermArt(ById, []), no},
         {"an Action holding its withdraw_fact_id twice",
            TermArt(ById ++ FactId, []), yes("TerminalNode")},
         {"a SlotAssign holding its expr once", TermArt(Assert, []), no},
         {"a SlotAssign holding its expr twice", TermArt(Assign2, []),
            yes("TerminalNode")},
         {"a ServiceDef holding its hydration once", SvcdArt(Hydration), no},
         {"a ServiceDef holding its hydration twice",
            SvcdArt(Hydration ++ Hydration), yes("ServiceDef")},
         {"an Expr holding its if_ member once", BetaArt(If), no},
         {"an Expr holding its if_ member twice", BetaArt(If ++ If),
            yes("BetaNode")},
         {"a CoalesceExpr holding its right operand once", BetaArt(Coalesce),
            no},
         {"a CoalesceExpr holding its right operand twice",
            BetaArt(CoalesceRight2), yes("BetaNode")},
         {"a FormatPrim holding its value member once", BetaArt(ValuePrim),
            no},
         {"a FormatPrim holding its value member twice", BetaArt(ValuePrim2),
            yes("BetaNode")},
         {"a TimePrim holding its value once", BetaArt(TimePrim), no},
         {"a TimePrim holding its value twice", BetaArt(TimePrim2),
            yes("BetaNode")}],
    list.foldl2(
        ( pred(Case::in, T0::in, T1::out, IO0::di, IO1::uo) is det :-
            Case = {Label, Bytes, Want},
            check("[RDSC.9.5] " ++ Label
                    ++ ( if Want = no then " loads" else " is refused" ),
                ( if
                    load_dsc(sealed(Bytes), R),
                    (
                        Want = no,
                        R = loaded(_)
                    ;
                        Want = yes(Atom),
                        R = load_failed(E),
                        E ^ le_kind = lek_decode,
                        clause_id_string(E ^ le_clause) = "RDSC.9.5",
                        E ^ le_atom = yes(Atom)
                    )
                  then yes else no ), T0, T1, IO0, IO1)
        ),
        Cases, !T, !IO),

    % The tolerance the last field gave is the one kept.
    check("[RDSC.9.5] a scalar twice holds its last",
        ( if load_dsc(sealed(TolTwice), loaded(P)),
             schemas(P) = [S],
             S ^ s_lifecycle = lc_logical([L], _),
             L ^ ls_tolerance = within(1.5)
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%
% [RDSC.11.4] A body is decoded before it is judged
%-----------------------------------------------------------------------------%
%
% A body that fails protobuf decode, or holds a field more than once as
% [RDSC.9.5] refuses, is `lek_decode` whatever other defect it carries; and
% nothing inside an `Expr` nested past [RDSC.11.3]'s 48 is read, so a body
% that decodes down to that limit and nests deeper is `lek_semantic` whatever
% the unread bytes hold, and the load returns however deep they nest
% ([RDSC.9.9]). Path: `ds.dsc_judge.rdsc_11_4_judge`, asked
% by `ds.dsc_network`'s `decode_beta` and `decode_term` before their
% decoders read the body, and those decoders on a body it passes. libds is
% held to the same bytes (test_dsc_basic.c,
% test_rdsc_11_4__decoded_before_judged).

:- pred test_rdsc_11_4_decoded_before_judged(tally::in, tally::out,
                                             io::di, io::uo) is det.

test_rdsc_11_4_decoded_before_judged(!T, !IO) :-
    True = [0x20, 0x01],                                    % Expr.lit_bool
    Alfa = network_schema_s ++ frame(268, [0x08, 0x01, 0x12, 0x01, 0x53]),
    Term = frame(270, [0x08, 0x03, 0x10, 0x02, 0x1A, 0x01, 0x52]),
    BetaArt = ( func(Beta) = dsco_frame ++ Alfa ++ frame(269, Beta) ++ Term ),

    % 1. A join test `binop { EQ, left: <an Expr whose
    %    innermost is 49 deep>, right: 1, right: 1 }`. The left operand is at
    %    depth 1, so 48 NOTs put its literal at 49. The second `right` is a
    %    repeat ([RDSC.9.5]): DECODE, the left operand's depth unread.
    Left = not_chain_over(48, True),
    Right = [0x1A, 0x02, 0x08, 0x01],
    Binop = [0x08, 0x06, 0x12] ++ varint(list.length(Left)) ++ Left
        ++ Right ++ Right,
    Case1 = BetaArt(beta_with_test([0x32] ++ varint(list.length(Binop))
        ++ Binop)),

    % 2. A join test that is an Expr with no member set ([RDSC.11.3]'s
    %    SEMANTIC), then, later in the same body, `is_negative` (field 5) as a
    %    varint of eleven bytes: DECODE. 6b, its control: without the wire
    %    error the same body is SEMANTIC.
    Overlong = [0x28] ++ list.duplicate(10, 0xFF) ++ [0x01],
    Case2 = BetaArt(beta_with_test([]) ++ Overlong),
    Case6b = BetaArt(beta_with_test([])),

    % 3. A TerminalNode whose first action is an ACTION_CALL with no `expr`
    %    (an Action with nothing set), and whose `fire_guard` occurs twice:
    %    DECODE, before the action is judged.
    Guard = [0x3A, 0x02, 0x20, 0x01],
    Case3 = dsco_frame ++ Alfa ++ frame(269, [0x08, 0x02, 0x10, 0x01])
        ++ frame(270, [0x08, 0x03, 0x10, 0x02, 0x1A, 0x01, 0x52, 0x32, 0x00]
            ++ Guard ++ Guard),

    % 4. A join test 100 000 NOTs deep, otherwise well formed: SEMANTIC, and
    %    the load returns.
    Case4 = BetaArt(beta_with_test(not_chain_over(100000, True))),

    % 5. A join test 60 deep whose Expr at depth 55 opens with a tag of wire
    %    type 7 (field 1), which no decoder reads: SEMANTIC, because those
    %    bytes are not read.
    Case5 = BetaArt(beta_with_test(
        not_chain_over(55, [0x0F] ++ not_chain_over(5, True)))),

    % 6a. The control: a join test whose literal sits at depth 48 loads.
    Case6a = BetaArt(beta_with_test(not_chain_over(48, True))),

    Cases =
        [{"a binop whose left nests 49 deep and whose right occurs twice",
            Case1, refused(lek_decode, "RDSC.9.5", yes("BetaNode"))},
         {"an empty join test, then an eleven-byte varint", Case2,
            refused(lek_decode, "RDSC.11.1", yes("BetaNode"))},
         {"a CALL action with no expr, then fire_guard twice", Case3,
            refused(lek_decode, "RDSC.9.5", yes("TerminalNode"))},
         {"a join test 100000 deep", Case4,
            refused(lek_semantic, "RDSC.11.3", yes("BetaNode"))},
         {"a join test 60 deep, malformed at depth 55", Case5,
            refused(lek_semantic, "RDSC.11.3", yes("BetaNode"))},
         {"a join test 48 deep", Case6a, loads},
         {"an empty join test, and no wire error", Case6b,
            refused(lek_semantic, "RDSC.11.3", yes("BetaNode"))}],
    list.foldl2(
        ( pred(Case::in, T0::in, T1::out, IO0::di, IO1::uo) is det :-
            Case = {Label, Bytes, Want},
            % @spec [RDSC.11.4]
            check("[RDSC.11.4] " ++ Label
                    ++ ( if Want = loads then " loads" else " is refused" ),
                ( if
                    load_dsc(sealed(Bytes), R),
                    (
                        Want = loads,
                        R = loaded(_)
                    ;
                        Want = refused(Kind, Clause, Atom),
                        R = load_failed(E),
                        E ^ le_kind = Kind,
                        clause_id_string(E ^ le_clause) = Clause,
                        E ^ le_atom = Atom
                    )
                  then yes else no ), T0, T1, IO0, IO1)
        ),
        Cases, !T, !IO).

:- type rdsc_11_4_want
    --->    loads
    ;       refused(load_error_kind, string, maybe(string)).

%-----------------------------------------------------------------------------%
% [RDSC.9.12] A string field is well-formed UTF-8, and holds no U+0000
%-----------------------------------------------------------------------------%
%
% An atom body in which a field of protobuf type `string`, at any depth read,
% holds bytes that are not well-formed UTF-8, or that hold U+0000, is
% `lek_decode`; the string is neither repaired nor cut at the NUL. A string
% inside an `Expr` past [RDSC.11.3]'s 48 is not read ([RDSC.11.4]), so that
% body is `lek_semantic`. Path: `ds.dsc_judge`'s
% `s_len` arm for a network body, and `ds.dsc_schema.slot_field`'s
% `reader_string` for the Slot. libds is held to the same bytes
% (test_dsc_basic.c, test_rdsc_9_12__string_fields_refused).

:- pred test_rdsc_9_12_string_fields(tally::in, tally::out,
                                     io::di, io::uo) is det.

test_rdsc_9_12_string_fields(!T, !IO) :-
    Slog = frame(299, [0x0A, 0x01, 0x53, 0x18, 0x01]),      % "S", EXPLICIT
    Slot0 = [0x0A, 0x01, 0x53, 0x12, 0x01, 0x74, 0x18, 0x02],  % "S"."t" FLOAT
    Alfa0 = [0x08, 0x01, 0x12, 0x01, 0x53],
    Beta0 = [0x08, 0x02, 0x10, 0x01],
    Term0 = [0x08, 0x03, 0x10, 0x02, 0x1A, 0x01, 0x52],
    Art = ( func(Slot, Alfa, Beta, Term) =
        dsco_frame ++ Slog ++ frame(257, Slot) ++ frame(268, Alfa)
            ++ frame(269, Beta) ++ frame(270, Term) ),
    % A join test `binop { EQ, left: lit_str <S>, right: lit_str "x" }`.
    StrBeta = ( func(S) = Bytes :-
        Left = [0x1A] ++ varint(list.length(S)) ++ S,
        Binop = [0x08, 0x06, 0x12] ++ varint(list.length(Left)) ++ Left
            ++ [0x1A, 0x03, 0x1A, 0x01, 0x78],
        Bytes = beta_with_test([0x32] ++ varint(list.length(Binop)) ++ Binop)
    ),

    % 1. TerminalNode.rule_name the single byte 0xFF.
    Case1 = Art(Slot0, Alfa0, Beta0, [0x08, 0x03, 0x10, 0x02, 0x1A, 0x01, 0xFF]),
    % 2. Expr.lit_str holding a\0b, in a BetaNode join test.
    Case2 = Art(Slot0, Alfa0, StrBeta([0x61, 0x00, 0x62]), Term0),
    % 3. AlphaNode.schema_name an overlong form, 0xC0 0xAF.
    Case3 = Art(Slot0, [0x08, 0x01, 0x12, 0x02, 0xC0, 0xAF], Beta0, Term0),
    % 4. A Slot atom's name a lone surrogate's encoding, 0xED 0xA0 0x80: an
    %    atom outside the network, so every atom is covered.
    Case4 = Art([0x0A, 0x01, 0x53, 0x12, 0x03, 0xED, 0xA0, 0x80, 0x18, 0x02],
        Alfa0, Beta0, Term0),
    % 5b. A join test whose deepest lit_str, at depth 49, is 0xFF: not read.
    Case5b = Art(Slot0, Alfa0, beta_with_test(
        not_chain_over(49, [0x1A, 0x01, 0xFF])), Term0),

    Cases =
        [{"a rule_name of 0xFF", Case1,
            refused(lek_decode, "RDSC.9.12", yes("TerminalNode"))},
         {"a lit_str holding U+0000", Case2,
            refused(lek_decode, "RDSC.9.12", yes("BetaNode"))},
         {"a schema_name in an overlong form", Case3,
            refused(lek_decode, "RDSC.9.12", yes("AlphaNode"))},
         {"a 0xFF lit_str past depth 48", Case5b,
            refused(lek_semantic, "RDSC.11.3", yes("BetaNode"))}],
    list.foldl2(
        ( pred(Case::in, T0::in, T1::out, IO0::di, IO1::uo) is det :-
            Case = {Label, Bytes, Want},
            % @spec [RDSC.9.12]
            check("[RDSC.9.12] " ++ Label ++ " is refused",
                ( if
                    load_dsc(sealed(Bytes), load_failed(E)),
                    Want = refused(Kind, Clause, Atom),
                    E ^ le_kind = Kind,
                    clause_id_string(E ^ le_clause) = Clause,
                    E ^ le_atom = Atom
                  then yes else no ), T0, T1, IO0, IO1)
        ),
        Cases, !T, !IO),

    % Case 4's clause is the schema decoder's, RDSC.11.1: a Slot's string is
    % read by `reader_string` inside the field's fold, whose failure is the
    % body not decoding. The code and the atom are what both runtimes share.
    % @spec [RDSC.9.12]
    check("[RDSC.9.12] a Slot name holding a surrogate is refused",
        ( if
            load_dsc(sealed(Case4), load_failed(E4)),
            E4 ^ le_kind = lek_decode,
            E4 ^ le_atom = yes("Slot")
          then yes else no ), !T, !IO),

    % 5a. The control: case 2 with a well-formed two-byte string loads, and
    %     the literal holds the two bytes.
    % @spec [RDSC.9.12]
    check("[RDSC.9.12] a lit_str of U+00E9 loads, and holds C3 A9",
        ( if
            load_dsc(sealed(Art(Slot0, Alfa0, StrBeta([0xC3, 0xA9]), Term0)),
                loaded(P)),
            beta_nodes(network(P)) = [B],
            B ^ bn_tests = [e_binop(op_eq, e_lit(str(Ref)), _)],
            expand(interns(P), Ref, "é")
          then yes else no ), !T, !IO),

    % The two `bytes` fields that carry text: DsSource `data` and SchemaDef
    % `proto_source`, judged as strings under COMPRESSION_NONE, the one
    % compression a loader reads them as text in. Path: `ds.dsc.decode_dsrc`
    % and `ds.dsc_schema.decode_sdef`, each after the compression.
    % 6. A DsSource "m.ds", NONE, whose `data` is the single byte 0xFF.
    Dsrc = ( func(Comp, Data) = dsco_frame ++ frame(267,
        [0x0A, 0x04, 0x6D, 0x2E, 0x64, 0x73, 0x10, Comp, 0x1A]
            ++ varint(list.length(Data)) ++ Data) ),
    % @spec [RDSC.9.12]
    check("[RDSC.9.12] a DsSource data of 0xFF is refused",
        ( if
            load_dsc(sealed(Dsrc(0x01, [0xFF])), load_failed(E6)),
            E6 ^ le_kind = lek_decode,
            clause_id_string(E6 ^ le_clause) = "RDSC.9.12",
            E6 ^ le_atom = yes("DsSource")
          then yes else no ), !T, !IO),
    % 7. A SchemaDef "S", NONE, whose `proto_source` is a\0b.
    % @spec [RDSC.9.12]
    check("[RDSC.9.12] a SchemaDef proto_source holding U+0000 is refused",
        ( if
            load_dsc(sealed(dsco_frame ++ frame(256,
                [0x0A, 0x01, 0x53, 0x10, 0x01, 0x1A, 0x03, 0x61, 0x00, 0x62])),
                load_failed(E7)),
            E7 ^ le_kind = lek_decode,
            clause_id_string(E7 ^ le_clause) = "RDSC.9.12",
            E7 ^ le_atom = yes("SchemaDef")
          then yes else no ), !T, !IO),
    % 8. The control: case 6 with `data` C3 A9 loads, and the source reads
    %    back as those two bytes.
    % @spec [RDSC.9.12]
    check("[RDSC.9.12] a DsSource data of U+00E9 loads, and holds C3 A9",
        ( if
            load_dsc(sealed(Dsrc(0x01, [0xC3, 0xA9])), loaded(P8)),
            sources(P8) = [Src],
            Src ^ src_text = "é"
          then yes else no ), !T, !IO),
    % 9. Case 6 with compression 2, ZLIB's number: refused for its
    %    compression ([RDSC.4.5.1]), its bytes never read as text.
    % @spec [RDSC.9.12]
    check("[RDSC.9.12] a ZLIB DsSource is refused for its compression, not "
            ++ "its bytes",
        ( if
            load_dsc(sealed(Dsrc(0x02, [0xFF])), load_failed(E9)),
            E9 ^ le_kind = lek_decompress,
            clause_id_string(E9 ^ le_clause) = "RDSC.4.5.1"
          then yes else no ), !T, !IO).

    % `N` nested `not`s over the Expr body `Inner`, as `not_chain` lays them
    % out, written from the inside out by length so a chain 100 000 deep is
    % one pass: `not_chain(N)` is `not_chain_over(N, [0x20, 0x01])`.
    %
:- func not_chain_over(int, list(int)) = list(int).

not_chain_over(N, Inner) =
    list.condense(not_chain_heads(N, list.length(Inner), [])) ++ Inner.

    % The heads of the `K` NOTs above an Expr body `Len` bytes long, the
    % outermost first: an Expr's `unop` (field 7) and its length, then the
    % UnopExpr's `operand` (field 2) and its length.
    %
:- func not_chain_heads(int, int, list(list(int))) = list(list(int)).

not_chain_heads(K, Len, Acc) = Heads :-
    ( if K =< 0 then
        Heads = Acc
    else
        Unop = 1 + list.length(varint(Len)) + Len,
        Head = [0x3A] ++ varint(Unop) ++ [0x12] ++ varint(Len),
        Heads = not_chain_heads(K - 1, Len + list.length(Head), [Head | Acc])
    ).

%-----------------------------------------------------------------------------%
% [RDSC.9.11] No negative tolerance
%-----------------------------------------------------------------------------%
%
% A Slot.tolerance of -1.0 and of -inf is refused, `lek_semantic` under the
% clause, and the load yields no program, so there is no engine to hold a
% schema ([RDSC.9.8]). -0.0 is not less than zero: it loads, and is exact.
% The bytes are `test_rdsc_9_10_nan_doubles`'s tolerance shape, which libds is
% held to too (test_dsc_basic.c, test_rdsc_9_11__negative_tolerance_refused).
% Path: `ds.dsc_schema.decode_slot`.

:- pred test_rdsc_9_11_negative_tolerance(tally::in, tally::out,
                                          io::di, io::uo) is det.

test_rdsc_9_11_negative_tolerance(!T, !IO) :-
    % Little-endian binary64: -1.0 (0xBFF0000000000000), -inf
    % (0xFFF0000000000000) and -0.0 (0x8000000000000000).
    MinusOne = [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xF0, 0xBF],
    MinusInf = [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xF0, 0xFF],
    MinusZero = [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80],
    Slog = frame(299, [0x0A, 0x01, 0x53, 0x18, 0x02]),     % "S", LOGICAL
    % Slot "S"."t", FLOAT, MUTABLE, whose tolerance (field 7, tag 0x39) is
    % Bits.
    TolArt = ( func(Bits) =
        dsco_frame ++ Slog ++ frame(257,
            [0x0A, 0x01, 0x53, 0x12, 0x01, 0x74, 0x18, 0x02, 0x39] ++ Bits
                ++ [0x48, 0x02]) ),
    list.foldl2(
        ( pred(Case::in, T0::in, T1::out, IO0::di, IO1::uo) is det :-
            Case = {Label, Bits},
            % @spec [RDSC.9.11]
            check("[RDSC.9.11] a Slot.tolerance of " ++ Label
                    ++ " is refused, SEMANTIC, and loads nothing",
                ( if
                    load_dsc(sealed(TolArt(Bits)), load_failed(E)),
                    E ^ le_kind = lek_semantic,
                    clause_id_string(E ^ le_clause) = "RDSC.9.11"
                  then yes else no ), T0, T1, IO0, IO1)
        ),
        [{"-1.0", MinusOne}, {"-inf", MinusInf}], !T, !IO),
    % @spec [RDSC.9.11]
    check("[RDSC.9.11] a Slot.tolerance of -0.0 loads, and is exact",
        ( if load_dsc(sealed(TolArt(MinusZero)), loaded(P)),
             schemas(P) = [S],
             S ^ s_lifecycle = lc_logical([L], _),
             L ^ ls_tolerance = exact
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%
% [RDSC.9.8] A failed load spends the engine
%-----------------------------------------------------------------------------%
%
% libds sets its halt latch on a load error, and every later call on that
% engine is refused (test_dsc_basic.c,
% test_rdsc_9_8__failed_load_spends_the_engine). This runtime has no engine
% before a load succeeds: `load_failed` carries no program, so no later call
% can reach one. What is representable is the error the load returns:
% libds's case (a), an artefact whose last frame is cut short, sealed after
% the cut, refused `lek_truncated` ([RDSC.9.7]). The control: the same
% artefact uncut loads. libds's (c), a NULL buffer, has no counterpart: a
% bitmap is never null. Path: `ds.dsc.load_dsc`.

:- pred test_rdsc_9_8_failed_load_spends(tally::in, tally::out,
                                         io::di, io::uo) is det.

test_rdsc_9_8_failed_load_spends(!T, !IO) :-
    Good = dsco_frame ++ network_schema_s,
    Cut = list.take_upto(list.length(Good) - 1, Good),
    check("[RDSC.9.8] control: the artefact uncut loads",
        ( if load_dsc(sealed(Good), loaded(P)), schemas(P) = [_]
          then yes else no ), !T, !IO),
    % @spec [RDSC.9.8]
    check("[RDSC.9.8] a failed load returns the error that stopped it, "
            ++ "and no program to make an engine from",
        ( if load_dsc(sealed(Cut), load_failed(E)),
             E ^ le_kind = lek_truncated
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%
% The Rete Expr tree
%-----------------------------------------------------------------------------%

:- pred test_rete_expr(tally::in, tally::out, io::di, io::uo) is det.

test_rete_expr(!T, !IO) :-
    Alfa = network_schema_s ++
        [0x0A, 0x08, 0xE2, 0x10, 0x05, 0x08, 0x01, 0x12, 0x01, 0x53],

    % BetaNode with join test: var(0,0) > 5   [BINOP_GT = 9]
    BetaJoin = [0x0A, 0x19, 0xEA, 0x10, 0x16, 0x08, 0x02, 0x10,
         0x01, 0x22, 0x10, 0x32, 0x0E, 0x08, 0x09, 0x12,
         0x06, 0x2A, 0x04, 0x08, 0x00, 0x10, 0x00, 0x1A,
         0x02, 0x08, 0x05],
    % BetaNode with join test: var(0,0) <= 5  [BINOP_LE = 10]
    BetaJoinLe = [0x0A, 0x19, 0xEA, 0x10, 0x16, 0x08, 0x02, 0x10,
         0x01, 0x22, 0x10, 0x32, 0x0E, 0x08, 0x0A, 0x12,
         0x06, 0x2A, 0x04, 0x08, 0x00, 0x10, 0x00, 0x1A,
         0x02, 0x08, 0x05],

    check("a join test decodes to a binop over a var and a literal",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaJoin), loaded(P1)),
             beta_nodes(network(P1)) = [B1],
             B1 ^ bn_tests = [e_binop(op_gt, e_slot(token_fact(0), slot(_)),
                 e_lit(int(5i64)))]
          then yes else no ), !T, !IO),

    check("BINOP_GT = 9 and BINOP_LE = 10, in THAT order",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaJoinLe), loaded(P2)),
             beta_nodes(network(P2)) = [B2],
             B2 ^ bn_tests = [e_binop(op_le, _, _)]
          then yes else no ), !T, !IO),

    % BetaNode join test using both VarExpr markers: var(255,0) == var(0,255)
    BetaSentinels = [0x0A, 0x1F, 0xEA, 0x10, 0x1C, 0x08, 0x02, 0x10,
         0x01, 0x22, 0x16, 0x32, 0x14, 0x08, 0x06, 0x12,
         0x07, 0x2A, 0x05, 0x08, 0xFF, 0x01, 0x10, 0x00,
         0x1A, 0x07, 0x2A, 0x05, 0x08, 0x00, 0x10, 0xFF,
         0x01],

    % [RDSC.4a.9.1]: `pattern_index = 255` is the candidate fact, and
    % `slot_index = 255` "the fact itself as a fact-reference". Missing the
    % second reads a bare binding as a slot access, wrong data rather than an
    % error.
    check("VarExpr pattern_index 255 is the CANDIDATE fact, not index 255",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaSentinels),
                loaded(P3)),
             beta_nodes(network(P3)) = [B3],
             B3 ^ bn_tests = [e_binop(op_eq, e_slot(candidate, _), _)]
          then yes else no ), !T, !IO),

    check("VarExpr slot_index 255 is the WHOLE FACT",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaSentinels),
                loaded(P4)),
             beta_nodes(network(P4)) = [B4],
             B4 ^ bn_tests = [e_binop(_, _, e_slot(_, whole_fact))]
          then yes else no ), !T, !IO),

    % [RDSC.4a.9.1]: each index field at its bound loads
    % and one past it is refused, `lek_semantic` under the clause. 255 is the
    % marker in `VarExpr`'s two fields and `entry_stamp`, so each takes 255
    % and refuses 256; `SlotAssign.slot_index` and
    % `Action.withdraw_pattern_index` have none, so each takes 254 and refuses
    % 255. An index in range that names no slot of "S" is not refused at load.
    % VarExpr and entry_stamp are BetaNode 2's join test, the others
    % TerminalNode 3's one action. libds is held to the same
    % (test_dsc_basic.c, test_rdsc_4a_9_1__index_bounds).
    Var = ( func(P, S) = [0x2A, 0x05, 0x08] ++ P ++ [0x10] ++ S ),
    Stamp = ( func(P) = [0xA8, 0x01] ++ P ),
    Assert = ( func(S) =
        [0x08, 0x01, 0x1A, 0x01, 0x53, 0x22, 0x07, 0x08] ++ S
            ++ [0x12, 0x02, 0x08, 0x01] ),
    Withdraw = ( func(P) = [0x08, 0x03, 0x30] ++ P ),
    Byte255 = [0xFF, 0x01], Byte254 = [0xFE, 0x01], Byte256 = [0x80, 0x02],
    list.foldl2(
        ( pred(Case::in, T0::in, T1::out, IO0::di, IO1::uo) is det :-
            Case = {Label, Net, Loads},
            check("[RDSC.4a.9.1] " ++ Label
                    ++ ( if Loads = yes then " loads" else " is refused" ),
                ( if
                    load_dsc(sealed(dsco_frame ++ Alfa ++ Net), R),
                    (
                        Loads = yes,
                        R = loaded(_)
                    ;
                        Loads = no,
                        R = load_failed(E),
                        E ^ le_kind = lek_semantic,
                        clause_id_string(E ^ le_clause) = "RDSC.4a.9.1"
                    )
                  then yes else no ), T0, T1, IO0, IO1)
        ),
        [{"VarExpr.pattern_index 255, the candidate",
            frame(269, beta_with_test(Var(Byte255, [0x00]))), yes},
         {"VarExpr.pattern_index 256",
            frame(269, beta_with_test(Var(Byte256, [0x00]))), no},
         {"VarExpr.slot_index 255, the fact itself",
            frame(269, beta_with_test(Var([0x00], Byte255))), yes},
         {"VarExpr.slot_index 256",
            frame(269, beta_with_test(Var([0x00], Byte256))), no},
         {"Expr.entry_stamp 255, the candidate",
            frame(269, beta_with_test(Stamp(Byte255))), yes},
         {"Expr.entry_stamp 256",
            frame(269, beta_with_test(Stamp(Byte256))), no},
         {"SlotAssign.slot_index 254",
            Beta ++ frame(270, term_with_action(Assert(Byte254))), yes},
         {"SlotAssign.slot_index 255",
            Beta ++ frame(270, term_with_action(Assert(Byte255))), no},
         {"Action.withdraw_pattern_index 254",
            Beta ++ frame(270, term_with_action(Withdraw(Byte254))), yes},
         {"Action.withdraw_pattern_index 255",
            Beta ++ frame(270, term_with_action(Withdraw(Byte255))), no}],
        !T, !IO),

    % BetaNode whose join test has no oneof member set
    BetaEmptyExpr = [0x0A, 0x09, 0xEA, 0x10, 0x06, 0x08, 0x02, 0x10,
         0x01, 0x22, 0x00],

    check("[RDSC.11.3] an Expr with no oneof member set is refused",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaEmptyExpr),
                load_failed(E1)),
             E1 ^ le_kind = lek_semantic,
             clause_id_string(E1 ^ le_clause) = "RDSC.11.3"
          then yes else no ), !T, !IO),

    % BetaNode calling builtin 1 (FN_ABS) with one argument
    BetaCall = [0x0A, 0x11, 0xEA, 0x10, 0x0E, 0x08, 0x02, 0x10,
         0x01, 0x22, 0x08, 0x42, 0x06, 0x12, 0x02, 0x08,
         0x01, 0x18, 0x01],

    % CallExpr field 1 is a tombstone, so args is 2 and op is 3.
    check("CallExpr reads args from field 2 and op from field 3",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaCall), loaded(P5)),
             beta_nodes(network(P5)) = [B5],
             B5 ^ bn_tests = [e_call(fn_abs, [e_lit(int(1i64))])]
          then yes else no ), !T, !IO),

    % BetaNode calling builtin 42, which `builtin_fn.proto` reserves.
    BetaTombstone = [0x0A, 0x11, 0xEA, 0x10, 0x0E, 0x08, 0x02, 0x10,
         0x01, 0x22, 0x08, 0x42, 0x06, 0x12, 0x02, 0x08,
         0x01, 0x18, 0x2A],

    check("[RDSC.4a.9.3] a call to a tombstoned builtin is DS_ERR_FN_NOT_FOUND",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaTombstone),
                load_failed(E2)),
             E2 ^ le_kind = lek_fn_not_found
          then yes else no ), !T, !IO),

    % BetaNode with interp [text "a", text "b"]; order is semantic. Expr field
    % 20 (tag A2 01), InterpExpr.prims field 1, each FormatPrim.text field 1.
    BetaInterp = [0x0A, 0x16, 0xEA, 0x10, 0x13, 0x08, 0x02, 0x10,
         0x01, 0x22, 0x0D, 0xA2, 0x01, 0x0A, 0x0A, 0x03, 0x0A,
         0x01, 0x61, 0x0A, 0x03, 0x0A, 0x01, 0x62],

    check("an InterpExpr keeps its primitives in wire order",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaInterp), loaded(P6)),
             beta_nodes(network(P6)) = [B6],
             B6 ^ bn_tests = [e_interp([fp_text("a"), fp_text("b")])]
          then yes else no ), !T, !IO),

    % BetaNode with interp [value 5 under `d`]: ValuePrim { value: lit_int 5,
    % type: FORMAT_TYPE_D (field 8 = 1) }.
    BetaInterpD = [0x0A, 0x16, 0xEA, 0x10, 0x13, 0x08, 0x02, 0x10,
         0x01, 0x22, 0x0D, 0xA2, 0x01, 0x0A, 0x0A, 0x08, 0x12,
         0x06, 0x0A, 0x02, 0x08, 0x05, 0x40, 0x01],
    % The same with `has_precision` set (field 6 = 1): a precision on `d`.
    BetaInterpDPrec = [0x0A, 0x18, 0xEA, 0x10, 0x15, 0x08, 0x02, 0x10,
         0x01, 0x22, 0x0F, 0xA2, 0x01, 0x0C, 0x0A, 0x0A, 0x12,
         0x08, 0x0A, 0x02, 0x08, 0x05, 0x30, 0x01, 0x40, 0x01],

    % [IARC.1.16]'s loader half checks the enumerations and no spec part
    % against its type: a precision on `d` loads,
    % and rendering it is the node's type error (`ds.format`).
    check("a ValuePrim under `d` loads",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaInterpD),
                loaded(PInterpD)),
             beta_nodes(network(PInterpD)) = [BInterpD],
             BInterpD ^ bn_tests = [e_interp([fp_value(value_prim(
                 e_lit(int(5i64)), align_default, no, no, 0u32, no, ft_d))])]
          then yes else no ), !T, !IO),
    check("[IARC.1.16] a precision on `d` is not checked at load",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaInterpDPrec),
                loaded(PInterpDPrec)),
             beta_nodes(network(PInterpDPrec)) = [BInterpDPrec],
             BInterpDPrec ^ bn_tests = [e_interp([fp_value(value_prim(
                 e_lit(int(5i64)), align_default, no, no, 0u32, yes(0u32),
                 ft_d))])]
          then yes else no ), !T, !IO),

    % TerminalNode bind_count 2, fire_guard = bind_ref 1
    TermGuard = [0x0A, 0x10, 0xF2, 0x10, 0x0D, 0x08, 0x03, 0x10,
         0x02, 0x1A, 0x01, 0x52, 0x20, 0x02, 0x3A, 0x02,
         0x70, 0x01],
    % TerminalNode bind_count 2, fire_guard = bind_ref 9 -- outside the frame
    TermGuardPast = [0x0A, 0x10, 0xF2, 0x10, 0x0D, 0x08, 0x03, 0x10,
         0x02, 0x1A, 0x01, 0x52, 0x20, 0x02, 0x3A, 0x02,
         0x70, 0x09],
    Beta = [0x0A, 0x07, 0xEA, 0x10, 0x04, 0x08, 0x02, 0x10,
         0x01],

    check("a fire_guard's bind_ref loads, with its terminal's bind_count",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ TermGuard),
                loaded(P7)),
             terminal_nodes(network(P7)) = [Tm7],
             Tm7 ^ tn_guard = yes(e_bind_ref(Ix7)),
             bind_index_int(Ix7) = 1,
             Tm7 ^ tn_binds = 2
          then yes else no ), !T, !IO),

    % @spec [RDSC.4a.9.6]
    check("[RDSC.4a.9.6] one outside the frame loads, its index kept",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ TermGuardPast),
                loaded(P7Past)),
             terminal_nodes(network(P7Past)) = [Tm7Past],
             Tm7Past ^ tn_guard = yes(e_bind_ref(IxPast)),
             bind_index_int(IxPast) = 9
          then yes else no ), !T, !IO),

    % TerminalNode bind_count 2, fire_guard = bind { bind_index 0,
    % expr lit_int 1 }, then the same bind with its expression absent. A missing operand is a
    % rule violation (DS_ERR_DSC_SEMANTIC), not a dangling reference: the
    % index is in range. libds's `decode_child` answers the same.
    TermBind = frame(270, [0x08, 0x03, 0x10, 0x02, 0x1A, 0x01, 0x52,
        0x20, 0x02, 0x3A, 0x06, 0x6A, 0x04, 0x12, 0x02, 0x08, 0x01]),
    TermBindNoExpr = frame(270, [0x08, 0x03, 0x10, 0x02, 0x1A, 0x01, 0x52,
        0x20, 0x02, 0x3A, 0x02, 0x6A, 0x00]),
    check("a bind with its expression loads",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ TermBind),
                loaded(P8)),
             terminal_nodes(network(P8)) = [Tm8],
             Tm8 ^ tn_guard = yes(e_bind(_, e_lit(int(1i64))))
          then yes else no ), !T, !IO),
    check("a bind with no expression is a SEMANTIC refusal, not a dangling one",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ TermBindNoExpr),
                load_failed(E4)),
             E4 ^ le_kind = lek_semantic
          then yes else no ), !T, !IO),

    % [RDSC.11.3]: an `Expr` nested deeper than 48 is refused with
    % DS_ERR_DSC_SEMANTIC, the outermost at depth 0, and depth 48 loads. The
    % join test is `not_chain(N)`: N `not`s over `true`, the literal at depth
    % N. libds is held to the same (test_dsc_basic.c,
    % test_rdsc_11_3__expr_shape_refused_at_load).
    check("[RDSC.11.3] a join test nested 48 deep loads",
        ( if load_dsc(sealed(dsco_frame ++ Alfa
                ++ frame(269, beta_with_test(not_chain(48)))), loaded(_))
          then yes else no ), !T, !IO),
    check("[RDSC.11.3] a join test nested 49 deep is refused",
        ( if load_dsc(sealed(dsco_frame ++ Alfa
                ++ frame(269, beta_with_test(not_chain(49)))),
                load_failed(EDeep)),
             EDeep ^ le_kind = lek_semantic,
             clause_id_string(EDeep ^ le_clause) = "RDSC.11.3"
          then yes else no ), !T, !IO),

    % [RDSC.11.3]: a `SlotAssign` with no `expr` is refused with
    % DS_ERR_DSC_SEMANTIC. TerminalNode 3's one action is an ASSERT of `S`
    % whose one assign carries `lit_int 1`, then the same with the assign
    % empty.
    TermAssign = frame(270, [0x08, 0x03, 0x10, 0x02, 0x1A, 0x01, 0x52,
        0x32, 0x0B, 0x08, 0x01, 0x1A, 0x01, 0x53,
        0x22, 0x04, 0x12, 0x02, 0x08, 0x01]),
    TermAssignNoExpr = frame(270, [0x08, 0x03, 0x10, 0x02, 0x1A, 0x01, 0x52,
        0x32, 0x07, 0x08, 0x01, 0x1A, 0x01, 0x53, 0x22, 0x00]),
    check("[RDSC.11.3] a SlotAssign with an expression loads",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ TermAssign),
                loaded(_))
          then yes else no ), !T, !IO),
    check("[RDSC.11.3] a SlotAssign with no expression is refused",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ TermAssignNoExpr),
                load_failed(EAssign)),
             EAssign ^ le_kind = lek_semantic,
             clause_id_string(EAssign ^ le_clause) = "RDSC.11.3"
          then yes else no ), !T, !IO),

    % TerminalNode 3's one action is kind 0 (`ACTION_CALL`, omitted) whose
    % `expr` (field 2) is `FN_LOG(1, "R", "m")` (`Expr` field 8, `CallExpr`
    % args 2 and op 3, `FN_LOG` = 47), then an `Action` with nothing set.
    % libds is held to the same (test_dsc_basic.c,
    % test_rdsc_11_3__expr_shape_refused_at_load).
    TermCall = frame(270, [0x08, 0x03, 0x10, 0x02, 0x1A, 0x01, 0x52,
        0x32, 0x14, 0x12, 0x12, 0x42, 0x10,
        0x12, 0x02, 0x08, 0x01,
        0x12, 0x03, 0x1A, 0x01, 0x52,
        0x12, 0x03, 0x1A, 0x01, 0x6D,
        0x18, 0x2F]),
    TermCallNoExpr = frame(270, [0x08, 0x03, 0x10, 0x02, 0x1A, 0x01, 0x52,
        0x32, 0x00]),
    check("[RDSC.11.3] an ACTION_CALL with an expression loads",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ TermCall),
                loaded(_))
          then yes else no ), !T, !IO),
    check("[RDSC.11.3] an ACTION_CALL with no expression is refused",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ TermCallNoExpr),
                load_failed(ECall)),
             ECall ^ le_kind = lek_semantic,
             clause_id_string(ECall ^ le_clause) = "RDSC.11.3"
          then yes else no ), !T, !IO),

    % [RDSC.4a.9.3]: no load-time operand count. TerminalNode 3's one action
    % is `FN_LOG(1, "R")`, one operand short, then `FN_CALL("s", "c", "k")`,
    % an odd pair count. `ia_operands_not_admitted` raises ARTEFACT_LIED when
    % it runs (`test_rdsc_4a_9_3_verbs`).
    TermLogShort = frame(270, [0x08, 0x03, 0x10, 0x02, 0x1A, 0x01, 0x52,
        0x32, 0x0F, 0x12, 0x0D, 0x42, 0x0B,
        0x12, 0x02, 0x08, 0x01,
        0x12, 0x03, 0x1A, 0x01, 0x52,
        0x18, 0x2F]),
    TermCallOdd = frame(270, [0x08, 0x03, 0x10, 0x02, 0x1A, 0x01, 0x52,
        0x32, 0x15, 0x12, 0x13, 0x42, 0x11,
        0x12, 0x03, 0x1A, 0x01, 0x73,
        0x12, 0x03, 0x1A, 0x01, 0x63,
        0x12, 0x03, 0x1A, 0x01, 0x6B,
        0x18, 0x31]),
    check("[RDSC.4a.9.3] a `log` one operand short loads, decoded as not "
            ++ "admitted",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ TermLogShort),
                loaded(PLog)),
             terminal_nodes(network(PLog)) = [TmLog],
             TmLog ^ tn_inline_actions =
                [ia_operands_not_admitted(fn_log, [_, _], no)]
          then yes else no ), !T, !IO),
    check("[RDSC.4a.9.3] a `call` with an odd pair count loads, decoded as "
            ++ "not admitted",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ Beta ++ TermCallOdd),
                loaded(PCall)),
             terminal_nodes(network(PCall)) = [TmCall],
             TmCall ^ tn_inline_actions =
                [ia_operands_not_admitted(fn_call, [_, _, _], no)]
          then yes else no ), !T, !IO),

    BetaBindRef = frame(269, [0x08, 0x02, 0x10, 0x01,
        0x22, 0x02, 0x70, 0x09]),
    check("a bind_ref in a BetaNode join test is accepted -- there is no "
            ++ "frame "
            ++ "to check it against",
        ( if load_dsc(sealed(dsco_frame ++ Alfa ++ BetaBindRef), loaded(_))
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%
% A compiled network
%-----------------------------------------------------------------------------%

:- pred test_real_network(tally::in, tally::out, io::di, io::uo) is det.

test_real_network(!T, !IO) :-
    io.open_binary_input("fixtures/07_action_verbs.dsc", OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, Res, !IO),
        io.close_binary_input(Stream, !IO)
    ;
        OpenRes = error(OpenErr),
        Res = error(OpenErr)
    ),
    (
        Res = ok(BM),
        load_dsc(BM, LoadResult),
        (
            LoadResult = loaded(P),
            N = network(P),
            IT = interns(P),

            check("the compiled artefact's NETWORK resolves",
                ( if alpha_nodes(N) = [_ | _] then yes else no ), !T, !IO),

            % `Trig t ->` is one positive pattern, so: one alpha, one root beta
            % over it, one terminal.
            check("one rule with one pattern gives one alpha, one beta, "
                    ++ "one terminal",
                ( if alpha_nodes(N) = [_], beta_nodes(N) = [_],
                     terminal_nodes(N) = [_]
                  then yes else no ), !T, !IO),

            check("the alpha dispatches on Trig",
                ( if alpha_nodes(N) = [A],
                     expand(IT, schema_name_ref(A ^ an_schema), "Trig")
                  then yes else no ), !T, !IO),

            check("and carries no tests -- the rule has no `where`",
                ( if alpha_nodes(N) = [A2], A2 ^ an_tests = []
                  then yes else no ), !T, !IO),

            check("its single beta is a ROOT, seeded with a nil token",
                ( if root_betas(N) = [_] then yes else no ), !T, !IO),

            check("with no join tests -- one pattern has nothing to join",
                ( if beta_nodes(N) = [B], B ^ bn_tests = []
                  then yes else no ), !T, !IO),

            check("and is not a NOT node",
                ( if beta_nodes(N) = [B2], B2 ^ bn_negative = no
                  then yes else no ), !T, !IO),

            check("the terminal's parent IS that beta, by identity",
                ( if terminal_nodes(N) = [Tm], beta_nodes(N) = [B3],
                     Tm ^ tn_parent = B3
                  then yes else no ), !T, !IO),

            check("the terminal names its rule",
                ( if terminal_nodes(N) = [Tm2],
                     expand(IT, Tm2 ^ tn_rule, RuleName),
                     RuleName \= ""
                  then yes else no ), !T, !IO),

            check("and carries no fire_guard -- the rule has no rate limit",
                ( if terminal_nodes(N) = [Tm3], Tm3 ^ tn_guard = no
                  then yes else no ), !T, !IO),

            io.format("  note: real network = %d alpha, %d beta, %d terminal\n",
                [i(list.length(alpha_nodes(N))),
                 i(list.length(beta_nodes(N))),
                 i(list.length(terminal_nodes(N)))], !IO)
        ;
            LoadResult = load_failed(E),
            check("the compiled artefact's network resolves (kind "
                ++ string(E ^ le_kind) ++ ", clause "
                ++ clause_id_string(E ^ le_clause) ++ ")", no, !T, !IO)
        )
    ;
        Res = error(E2),
        check("fixture readable: " ++ io.error_message(E2), no, !T, !IO)
    ).

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% Compiled networks: the shapes 07_action_verbs cannot reach
%-----------------------------------------------------------------------------%

:- pred with_fixture(string, pred(program, tally, tally, io, io),
                     tally, tally, io, io).
:- mode with_fixture(in, pred(in, in, out, di, uo) is det, in, out, di, uo)
    is det.

with_fixture(Name, Body, !T, !IO) :-
    io.open_binary_input("fixtures/" ++ Name, OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, Res, !IO),
        io.close_binary_input(Stream, !IO)
    ;
        OpenRes = error(OpenErr),
        Res = error(OpenErr)
    ),
    (
        Res = ok(BM),
        load_dsc(BM, LoadResult),
        (
            LoadResult = loaded(P),
            Body(P, !T, !IO)
        ;
            LoadResult = load_failed(E),
            check(Name ++ " loads (kind " ++ string(E ^ le_kind) ++ ", clause "
                ++ clause_id_string(E ^ le_clause) ++ ")", no, !T, !IO)
        )
    ;
        Res = error(E2),
        check(Name ++ " readable: " ++ io.error_message(E2), no, !T, !IO)
    ).

:- pred note_shape(string::in, program::in, io::di, io::uo) is det.

note_shape(Name, P, !IO) :-
    N = network(P),
    Negatives = list.filter(is_negative_beta, beta_nodes(N)),
    Joined = list.filter(has_join_tests, beta_nodes(N)),
    io.format("  note: %s = %d alpha, %d beta (%d NOT, %d joined), "
            ++ "%d terminal\n",
        [s(Name), i(list.length(alpha_nodes(N))),
         i(list.length(beta_nodes(N))), i(list.length(Negatives)),
         i(list.length(Joined)), i(list.length(terminal_nodes(N)))], !IO).

:- pred is_negative_beta(beta_node::in) is semidet.

is_negative_beta(B) :- B ^ bn_negative = yes.

:- pred has_join_tests(beta_node::in) is semidet.

has_join_tests(B) :- B ^ bn_tests = [_ | _].

:- pred is_chained_beta(beta_node::in) is semidet.

is_chained_beta(B) :- B ^ bn_parent = yes(_).

