%-----------------------------------------------------------------------------%
% ds.rfcs / ds.replay: an input holding a reference, recorded as one
% ExternalAssert and replayed from it ([RFCS.24])
%-----------------------------------------------------------------------------%
%
% A check named for a scenario runs that `.scn`'s steps, written here because
% the scenario files are not in this suite's build tree. Keep the two in step.

    % [NSTG.2.4.2]: `88_cache_ttl.scn`. The last pump's instant is "k"'s
    % deadline, and the program has no TTL fact and no `$ClockTick`, so the
    % sweep's notification is the first effect after the pump boundary, ahead
    % of `r3`'s firing, where libds's `engine_pump_body` calls the handler.
    %
:- pred check_cache_expired_notified(program::in, tally::in, tally::out,
                                     io::di, io::uo) is det.

check_cache_expired_notified(P, !T, !IO) :-
    Steps = [
        st_assert("Trig", ["tag" - rv_string("w")]), st_pump,
        st_assert("Trig", ["tag" - rv_string("r1")]), st_pump,
        st_advance(9999999999),
        st_assert("Trig", ["tag" - rv_string("r2")]), st_pump,
        st_advance(1),
        st_assert("Trig", ["tag" - rv_string("r3")]), st_pump],
    engine_use_mock_clock(init_engine(P), E0),
    list.foldl4(run_step(rm_silent, P), Steps, E0, _, [], _, [], Effects,
        !IO),
    Expired = list.filter_map(
        ( func(Ef) = K is semidet :- Ef = eff_cache_expired(K) ), Effects),
    check("[NSTG.2.4.2] the sweep that removes \"k\" tells the host, once",
        ( if Expired = ["k"] then yes else no ), !T, !IO),
    list.reverse(Effects, Rev),
    list.take_while(not_pump_boundary, Rev, LastPumpRev),
    list.reverse(LastPumpRev, LastPump),
    check("[NSTG.2.4.2] at the last pump's entry, before its firing",
        ( if LastPump = [eff_cache_expired("k") | _] then yes else no ),
        !T, !IO).

    % [NLFC.9.4], as libds's
    % `test_nlfc_9_4__seed_ttl_counts_from_first_sample`. The mock clock is
    % set to 10 s before the engine samples it and "k" is seeded with a 5 s
    % TTL, so the deadline is 15 s. The tags fire none of the fixture's rules.
    %
% @spec [NLFC.9.4]
:- pred check_seed_ttl_from_first_sample(program::in, tally::in, tally::out,
                                         io::di, io::uo) is det.

check_seed_ttl_from_first_sample(P, !T, !IO) :-
    Sec = 1000000000,
    engine_use_mock_clock(init_engine(P), E0),
    run_step(rm_silent, P, st_set(10 * Sec), E0, E1, [], _, [], _, !IO),
    seed_cache("k", j_int(1i64), yes(duration_from_ns(5u64 * 1000000000u64)),
        Seeded, E1, E2),
    Step = ( func(At, Tag) = [st_set(At),
        st_assert("Trig", ["tag" - rv_string(Tag)]), st_pump] ),
    list.foldl4(run_step(rm_silent, P), Step(10 * Sec, "x1"), E2, E3,
        [], H3, [], Fx3, !IO),
    list.foldl4(run_step(rm_silent, P), Step(15 * Sec - 1, "x2"), E3, E4,
        H3, H4, [], Fx4, !IO),
    list.foldl4(run_step(rm_silent, P), Step(15 * Sec, "x3"), E4, E5,
        H4, _, [], Fx5, !IO),
    IsExpiry = ( func(Ef) = K is semidet :- Ef = eff_cache_expired(K) ),
    check("NLFC.9.4: a seed's TTL counts from the first sample",
        ( if
            Seeded = seeded,
            k_live(E3), list.filter_map(IsExpiry, Fx3) = [],
            k_live(E4), list.filter_map(IsExpiry, Fx4) = [],
            not cache_get(engine_cache(E5), "k", _),
            list.filter_map(IsExpiry, Fx5) = ["k"]
          then yes else no ), !T, !IO).

    % [NLFC.9.5], as libds's `test_nlfc_9_5__*` in test_cache_spec.c.
    %   a. A TTL of 2^63 ns is refused at the call.
    %   b. Seeded with 1 h at a mock clock of INT64_MAX - 1 s, the first
    %      sample would give "k" a deadline past the range.
    %   c. `set` back to 0, admitted only before the first sample, shows
    %      neither refusal sampled the clock; "k" live at 1 h - 1 ns and not
    %      at 1 h shows neither fixed its deadline.
    %
% @spec [NLFC.9.5]
:- pred check_seed_deadline_past_range(program::in, tally::in, tally::out,
                                       io::di, io::uo) is det.

check_seed_deadline_past_range(P, !T, !IO) :-
    Max = uint64.cast_from_int64(int64.max_int64),
    HourNs = 3600u64 * 1000000000u64,
    engine_use_mock_clock(init_engine(P), E0),
    seed_cache("k", j_int(1i64), yes(duration_from_ns(Max + 1u64)), RPast,
        E0, EP),
    check("NLFC.9.5 a: a seed's TTL of 2^63 ns is refused, the cache "
            ++ "unchanged",
        ( if
            RPast = seed_time_range,
            not cache_get(engine_cache(EP), "k", _)
          then yes else no ), !T, !IO),
    ( if find_schema(schemas(P), interns(P), "Trig", Trig) then
        set_clock(from_ns(Max - 1000000000u64), _, E0, E1),
        seed_cache("k", j_int(1i64), yes(duration_from_ns(HourNs)), RS,
            E1, E2),
        engine_intern("x1", X1, E2, E3),
        host_assert(Trig, [str(X1)], no, RA, FxA, E3, E4),
        pump(default_budget, FxP, E4, E5),
        check("NLFC.9.5 b: the first assert and pump are refused, recording "
                ++ "nothing",
            ( if
                RS = seeded,
                RA = refused_ttl_range,
                FxA = [],
                FxP = [eff_pump_status(ps_time_range)],
                engine_event_count(E5) = 0u64
              then yes else no ), !T, !IO),
        set_clock(from_ns(0u64), _, E5, E6),
        seed_cache("j", j_int(1i64), no, RS2, E6, E7),
        list.foldl4(run_step(rm_silent, P),
            [st_assert("Trig", ["tag" - rv_string("x2")]), st_pump],
            E7, E8, [], _, [], _, !IO),
        Cache = engine_cache(E8),
        check("NLFC.9.5 c: set back to 0 and j seeded, the first step reads "
                ++ "the original k with its deadline at 1 h",
            ( if
                RS2 = seeded,
                k_live(E8),
                cache_get_live(Cache, from_ns(HourNs - 1u64), "k", _),
                not cache_get_live(Cache, from_ns(HourNs), "k", _)
              then yes else no ), !T, !IO)
    else
        check("NLFC.9.5: the fixture declares `Trig`", no, !T, !IO)
    ).

:- pred k_live(engine::in) is semidet.

k_live(E) :-
    cache_get_live(engine_cache(E), engine_now(E), "k", _).

    % [RFCS.10.5]: a `ClockAdvance` whose `clock_ns` is negative ends the replay
    % with -205, as libds's
    % `test_rfcs_10_5__a_clock_outside_the_range_ends_the_replay` in
    % test_rfcs_replay.c. Written
    % by hand, since no run records one and no fixture can edit one. Path:
    % `replay_event`'s `se_clock_tick` arm -> `ntst_3_1_set_past_range`.
    %
% @spec [RFCS.10.5]
:- pred test_rfcs_10_5_a_clock_outside_the_range_ends_the_replay(program::in,
    tally::in, tally::out, io::di, io::uo) is det.

test_rfcs_10_5_a_clock_outside_the_range_ends_the_replay(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    Negative = from_ns(uint64.cast_from_int64(-1i64)),
    Meta = session_header(init_engine(P)),
    encode_recording(Meta, rfcs_ctx(engine_schemas(E0), engine_interns(E0)),
        engine_now(E0), prelude_seeds(E0),
        record_items(0u64, [eff_event(se_clock_tick(Negative, no))]), Bytes, _),
    decode_stream(from_bytes(list.map(uint8.cast_to_int, Bytes)),
        init_interns, Decoded),
    ( if Decoded = decoded(DS) then
        replay_stream(P, DS, Steps, E0, _),
        check("RFCS.10.5: a ClockAdvance outside the clock's range ends the "
                ++ "replay with -205",
            ( if Steps = [input_refused(_, -205, _)] then yes else no ),
            !T, !IO)
    else
        check("RFCS.10.5: the recording decodes", no, !T, !IO)
    ).

    % [RFCS.6.7]: a replayed pump refused before its step ends the replay, as
    % libds's `test_rfcs_6_7_time_range_pump_ends_the_replay` in
    % test_rfcs_replay.c. The run, with no seed: a pump at a mock clock of
    % INT64_MAX - 1 s, then Trig "x1" and a second pump. Replayed into an engine
    % the host seeded with "k" for 1 h, which [RFCS.26.2] forbids, the first
    % pump would give "k" a deadline past the `Time` range ([NLFC.9.5]): the
    % replay stops there with -205 and delivers nothing after it. The control
    % replays the same recording into an unseeded engine, which reproduces the
    % run: the seed is the only difference, so the refusal is the pump's.
    %
% @spec [RFCS.6.7]
:- pred check_replay_pump_time_range(program::in, tally::in, tally::out,
                                     io::di, io::uo) is det.

check_replay_pump_time_range(P, !T, !IO) :-
    Max = uint64.cast_from_int64(int64.max_int64),
    HourNs = 3600u64 * 1000000000u64,
    ( if find_schema(schemas(P), interns(P), "Trig", Trig) then
        engine_use_mock_clock(init_engine(P), E0),
        set_clock(from_ns(Max - 1000000000u64), _, E0, E1),
        pump(default_budget, Fx1, E1, E2),
        engine_intern("x1", X1, E2, E3),
        host_assert(Trig, [str(X1)], no, RA, FxA, E3, E4),
        pump(default_budget, Fx2, E4, E),
        check("RFCS.6.7: the run's pumps and its Trig are admitted",
            ( if
                RA = inserted(_),
                first_pump_status(Fx1) = no,
                first_pump_status(Fx2) = no
              then yes else no ), !T, !IO),
        Meta = session_header(init_engine(P)),
        encode_recording(Meta, rfcs_ctx(engine_schemas(E), engine_interns(E)),
            engine_now(E0), prelude_seeds(E),
            record_items(0u64, Fx1 ++ FxA ++ Fx2), Bytes, _),
        decode_stream(from_bytes(list.map(uint8.cast_to_int, Bytes)),
            init_interns, Decoded),
        ( if Decoded = decoded(DS) then
            engine_use_mock_clock(init_engine(P), S0),
            seed_cache("k", j_int(1i64), yes(duration_from_ns(HourNs)), RS,
                S0, S1),
            replay_stream(P, DS, SSteps, S1, S),
            check("RFCS.6.7: on a seeded engine the first replayed pump is "
                    ++ "refused before its step, and the replay ends there "
                    ++ "with -205",
                ( if
                    RS = seeded,
                    SSteps = [pumped([eff_pump_status(ps_time_range)]),
                        input_refused(_, -205, _)],
                    engine_fact_count(S) = 0
                  then yes else no ), !T, !IO),
            engine_use_mock_clock(init_engine(P), C0),
            replay_stream(P, DS, CSteps, C0, C),
            check("RFCS.6.7 control: on an unseeded engine the replay "
                    ++ "delivers both pumps and the Trig, and refuses nothing",
                ( if
                    list.filter(is_replayed_pump, CSteps) = [_, _],
                    not (
                        list.member(CS, CSteps),
                        replay_refusal_code(CS) = _
                    ),
                    engine_fact_count(C) = engine_fact_count(E),
                    engine_fact_count(E) = 1
                  then yes else no ), !T, !IO)
        else
            check("RFCS.6.7: the run's recording decodes", no, !T, !IO)
        )
    else
        check("RFCS.6.7: the fixture declares `Trig`", no, !T, !IO)
    ).

:- pred is_replayed_pump(replay_step::in) is semidet.

is_replayed_pump(pumped(_)).

    % [NSTG.2.4.2]: `112_cache_read_expiry.scn`, with one more pump. The
    % clock reaches "k"'s deadline with no pump, so no sweep has run; the
    % assert of `q` runs `rq1`'s and `rq2`'s join tests, which read
    % `cached("k")`. The read tells the host, as libds's `ds_cache_get` does,
    % and the two reads are one notification.
    %
:- pred check_cache_read_expiry_notified(program::in, tally::in, tally::out,
                                         io::di, io::uo) is det.

check_cache_read_expiry_notified(P, !T, !IO) :-
    Steps = [
        st_assert("Trig", ["tag" - rv_string("w")]), st_pump,
        st_advance(10000000000),
        st_assert("Trig", ["tag" - rv_string("q")]), st_pump],
    engine_use_mock_clock(init_engine(P), E0),
    list.foldl4(run_step(rm_silent, P), Steps, E0, _, [], _, [], Effects,
        !IO),
    IsExpiry = ( func(Ef) = K is semidet :- Ef = eff_cache_expired(K) ),
    check("[NSTG.2.4.2] the reads that find \"k\" expired tell the host, once",
        ( if list.filter_map(IsExpiry, Effects) = ["k"] then yes else no ),
        !T, !IO),
    list.reverse(Effects, Rev),
    list.take_while(not_pump_boundary, Rev, LastPumpRev),
    check("[NSTG.2.4.2] during the assert, not at the next pump's sweep",
        ( if list.filter_map(IsExpiry, LastPumpRev) = [] then yes else no ),
        !T, !IO).

    % [LEXP.4.2]: `95_nan_call_arg.scn`. Pump 1's `svc.diff` gets Inf - Inf;
    % pump 2 refuses nothing.
    %
:- pred check_nan_call_status(program::in, tally::in, tally::out,
                              io::di, io::uo) is det.

check_nan_call_status(P, !T, !IO) :-
    E0 = init_engine(P),
    list.foldl4(run_step(rm_silent, P),
        [st_assert("Trig", ["k" - rv_int(1i64), "a" - rv_float(1.0e308)]),
         st_pump],
        E0, E1, [], Handles1, [], First, !IO),
    list.foldl4(run_step(rm_silent, P),
        [st_assert("Trig", ["k" - rv_int(2i64), "a" - rv_float(2.0)]),
         st_pump],
        E1, _, Handles1, _, [], Second, !IO),
    Statuses = list.filter_map(
        ( func(Ef) = S is semidet :- Ef = eff_pump_status(S) ), First),
    check("[LEXP.4.2] a NaN call argument sets the pump's status, once",
        ( if Statuses = [ps_nan_rejected] then yes else no ), !T, !IO),
    Issued = list.filter(
        ( pred(Ef::in) is semidet :-
            Ef = eff_event(se_call_issued(_, _, _, _, _)) ), First),
    Logged = list.filter(
        ( pred(Ef::in) is semidet :-
            Ef = eff_event(se_log_emitted(_, _)) ), First),
    check("[LEXP.4.2] the firing goes on: the other call and the log run",
        ( if Issued = [_], Logged = [_] then yes else no ), !T, !IO),
    check("[LEXP.4.2] a pump that refuses no call has no status",
        ( if first_pump_status(Second) = no then yes else no ), !T, !IO).

:- pred not_pump_boundary(effect::in) is semidet.

not_pump_boundary(Effect) :-
    Effect \= eff_event(se_pump_boundary).

    % `98_fcxt.scn`, recorded, read back and replayed (`round_trip`).
    %
:- pred check_fcxt_round_trip(program::in, tally::in, tally::out,
                              io::di, io::uo) is det.

check_fcxt_round_trip(P, !T, !IO) :-
    Steps = [
        st_assert("Inner", ["v" - rv_int(10i64)]),
        st_assert("MakeMid", ["k" - rv_int(1i64)]), st_pump,
        st_assert("MakeOuter", ["n" - rv_int(1i64)]), st_pump,
        st_assert("SendOuter", ["n" - rv_int(1i64)]), st_pump,
        st_assert("DropMid", ["n" - rv_int(1i64)]), st_pump,
        st_resend(0), st_pump,
        st_retract(5), st_pump,
        st_assert("MakeMid", ["k" - rv_int(2i64)]), st_pump,
        st_assert("Holder", ["h" - rv_int(1i64), "m" - rv_live("Mid")]),
        st_pump],
    round_trip("fcxt", P, Steps, Externals, !T, !IO),
    check("fcxt: two ExternalAsserts, listing 2 and 1 handles",
        ( if
            list.map((func(X) = list.length(X ^ re_fact_ids)), Externals)
                = [2, 1]
        then yes else no ), !T, !IO).

    % `92_resend.scn`, the same way. Five of its resends are delivered and
    % two are refused before anything is asserted, too deep and a key taken,
    % and a refused delivery is not recorded.
    %
:- pred check_resend_round_trip(program::in, tally::in, tally::out,
                                io::di, io::uo) is det.

check_resend_round_trip(P, !T, !IO) :-
    Steps = [
        st_assert("Ref", ["id" - rv_string("a"), "note" - rv_string("x")]),
        st_assert("Seed", ["k" - rv_int(1i64)]),
        st_assert("N0", ["n" - rv_int(0i64)]), st_pump,
        st_assert("SendMain", ["n" - rv_int(1i64)]),
        st_assert("SendPair", ["n" - rv_int(1i64)]),
        st_assert("SendN16", ["n" - rv_int(1i64)]),
        st_assert("SendN17", ["n" - rv_int(1i64)]), st_pump,
        st_resend(0), st_resend(1), st_resend(2),
        st_resend(3),
        st_assert("Ref", ["id" - rv_string("a"), "note" - rv_string("y")]),
        st_pump,
        st_resend(0),
        st_retract(7), st_pump,
        st_resend(1), st_pump,
        st_retract(2), st_pump,
        st_resend(2), st_pump],
    round_trip("resend", P, Steps, Externals, !T, !IO),
    check("resend: five ExternalAsserts, one per delivered resend",
        ( if list.length(Externals) = 5 then yes else no ), !T, !IO).

    % [RFCS.24.1]: a delivery [RFCS.23.7] refuses whole is not recorded, and
    % the refusal is the call's status ([NCBK.10.4]), as libds's
    % test_assert_external test 11. `92_resend.scn`'s third case, the key
    % taken: the Ref is replaced with another note, so the sent Main's
    % inlined Ref is equal to no live fact. Path: `ds.fact_receive`'s plan
    % refuses with `xr_fact_ref_conflict` before anything is asserted or
    % sampled.
    %
% @spec [RFCS.24.1]
:- pred check_refused_records_nothing(program::in, tally::in, tally::out,
                                      io::di, io::uo) is det.

check_refused_records_nothing(P, !T, !IO) :-
    Before = [
        st_assert("Ref", ["id" - rv_string("a"), "note" - rv_string("x")]),
        st_assert("Seed", ["k" - rv_int(1i64)]),
        st_assert("N0", ["n" - rv_int(0i64)]), st_pump,
        st_assert("SendMain", ["n" - rv_int(1i64)]), st_pump,
        st_assert("Ref", ["id" - rv_string("a"), "note" - rv_string("y")]),
        st_pump],
    After = [st_assert("Seed", ["k" - rv_int(2i64)]), st_pump],
    record_around_resend(P, Before, no, After, Without, _, !IO),
    record_around_resend(P, Before, yes(0), After, With, Refusal, !IO),
    check("refused: the resend is refused, its key taken (-220)",
        ( if Refusal = yes(ext_refused(xr_fact_ref_conflict)) then yes
        else no ), !T, !IO),
    check("refused: the recording is byte-identical with and without the call",
        ( if With = Without then yes else no ), !T, !IO),
    round_trip("refused", P, Before ++ [st_resend(0)] ++ After, _, !T, !IO).

    % Run `Before`, then -- given `yes(K)` -- hand the K-th sent fact back
    % through `assert_external_with`, then run `After`, and record the whole
    % run as `round_trip` does. `Result` is the resend's outcome.
    %
:- pred record_around_resend(program::in, list(step)::in, maybe(int)::in,
                             list(step)::in, list(uint8)::out,
                             maybe(external_result)::out, io::di, io::uo)
    is det.

record_around_resend(P, Before, Resend, After, Bytes, Result, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    list.foldl4(run_step(rm_silent, P), Before, E0, E1, [], H1, [], Acc1,
        !IO),
    ( if
        Resend = yes(K),
        list.index0(list.condense(list.map(sent_facts, Acc1)), K, Sent)
    then
        assert_external_with(Sent, no, R, _, Effects1, E1, E2),
        Result = yes(R),
        Acc2 = Acc1 ++ Effects1
    else
        E2 = E1,
        Result = no,
        Acc2 = Acc1
    ),
    list.foldl4(run_step(rm_silent, P), After, E2, E, H1, _, Acc2, Effects,
        !IO),
    Meta = session_header(init_engine(P)),
    encode_recording(Meta, rfcs_ctx(engine_schemas(E), engine_interns(E)),
        engine_now(E0), prelude_seeds(E), record_items(0u64, Effects), Bytes,
        _).

    % Run `Steps`, record them, read the recording back and replay it into a
    % fresh engine; check that it decodes, that no step diverged, that the
    % replay's events are the run's one by one -- the first difference
    % printed in full -- and that both end with the same facts.
    %
:- pred round_trip(string::in, program::in, list(step)::in,
                   list(recorded_external)::out, tally::in, tally::out,
                   io::di, io::uo) is det.

round_trip(Name, P, Steps, Externals, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    list.foldl4(run_step(rm_silent, P), Steps, E0, E, [], _, [], Effects,
        !IO),
    Meta = session_header(init_engine(P)),
    encode_recording(Meta, rfcs_ctx(engine_schemas(E), engine_interns(E)),
        engine_now(E0), prelude_seeds(E), record_items(0u64, Effects), Bytes,
        _),
    decode_stream(from_bytes(list.map(uint8.cast_to_int, Bytes)),
        init_interns, Decoded),
    (
        Decoded = decoded(DS),
        Externals = DS ^ dsm_external,
        engine_use_mock_clock(init_engine(P), F0),
        replay_stream(P, DS, RSteps, F0, F),
        check(Name ++ ": the replay does not diverge",
            ( if
                list.find_first_match(
                    (pred(S::in) is semidet :- S = diverged(_)), RSteps, _)
            then no else yes ), !T, !IO),
        Run = list.filter_map(
            (func(Ef) = Ev is semidet :- Ef = eff_event(Ev)), Effects),
        Replayed = list.filter_map(
            (func(Ef) = Ev is semidet :- Ef = eff_event(Ev)),
            list.condense(list.map(replay_step_effects, RSteps))),
        first_event_difference(0, Run, Replayed, Difference),
        (
            Difference = no,
            check(Name ++ ": the replay's events are the run's", yes, !T,
                !IO)
        ;
            Difference = yes(Why),
            io.format("    %s: %s\n", [s(Name), s(Why)], !IO),
            check(Name ++ ": the replay's events are the run's", no, !T, !IO)
        ),
        check(Name ++ ": the replay ends with the run's facts",
            ( if engine_fact_count(F) = engine_fact_count(E) then yes
            else no ), !T, !IO)
    ;
        Decoded = decode_failed(Clause, Offset),
        Externals = [],
        io.format("    %s: the recording does not decode: %s at %d\n",
            [s(Name), s(Clause), i(Offset)], !IO),
        check(Name ++ ": the recording decodes", no, !T, !IO)
    ;
        Decoded = unannounced_schema(_, _, Offset),
        Externals = [],
        io.format("    %s: the recording stops at RFCS.5.4, byte %d\n",
            [s(Name), i(Offset)], !IO),
        check(Name ++ ": the recording decodes", no, !T, !IO)
    ).

:- func replay_step_effects(replay_step) = list(effect).

replay_step_effects(delivered(In)) = In.
replay_step_effects(pumped(Pump)) = Pump.
replay_step_effects(unknown_schema(_)) = [].
replay_step_effects(unknown_fact_id(_)) = [].
replay_step_effects(recording_incomplete(_)) = [].
replay_step_effects(binding_refused(_, _)) = [].
replay_step_effects(diverged(_)) = [].
replay_step_effects(input_refused(_, _, _)) = [].

    % The first position at which two event lists part, said in full.
    %
:- pred first_event_difference(int::in, list(stream_event)::in,
                               list(stream_event)::in, maybe(string)::out)
    is det.

first_event_difference(_, [], [], no).
first_event_difference(N, [A | As], [], yes(Why)) :-
    Why = string.format("event %d: the replay ends; the run has %s (%d more)",
        [i(N), s(string.string(A)), i(list.length(As))]).
first_event_difference(N, [], [B | Bs], yes(Why)) :-
    Why = string.format("event %d: the run ends; the replay has %s (%d more)",
        [i(N), s(string.string(B)), i(list.length(Bs))]).
first_event_difference(N, [A | As], [B | Bs], Difference) :-
    ( if A = B then
        first_event_difference(N + 1, As, Bs, Difference)
    else
        Difference = yes(string.format("event %d: the run has %s, the replay %s",
            [i(N), s(string.string(A)), s(string.string(B))]))
    ).

    % [LGRA.24.3]: a refused step whose input is an external delivery records
    % its sample and nothing else, since a stream holds only the
    % `ExternalAssert`s the engine admitted ([RFCS.24.1]). The block stays
    % pending, and the next step applies it. `140_initial_external`'s block
    % places `Seed` and seeds "a" and "b"; the engine is bounded to one cache
    % key, then the bound is raised. A replay takes no step for a recorded
    % sample (`ds.replay`'s `se_clock_tick` arm), so the T1 sample applies
    % nothing and the block goes in under T2, as it did live.
    %
    % Path: `ds.fact_receive.assert_external_with` -> `input_step_begin` ->
    % `clock_step`, whose `lgra_24_3_apply` refuses on `seed_capped`. libds's
    % counterpart is test_assert_external.c's test 14 (`fx_deliver` ->
    % `ds_engine_clock_step` -> `ds_engine_initial_apply`).
    %
:- pred check_initial_external(program::in, tally::in, tally::out,
                               io::di, io::uo) is det.

check_initial_external(P, !T, !IO) :-
    IT = interns(P),
    T1 = from_ns(1000000000u64),
    T2 = from_ns(5000000000u64),
    ( if
        find_schema(schemas(P), IT, "Ref", Ref),
        find_schema(schemas(P), IT, "Seed", Seed),
        ref_fe(P, "r1", "hello", FE),
        body_of(FE, Body)
    then
        engine_use_mock_clock(init_engine(P), E0),
        check("LGRA.24.3: between the load and the first step the block waits",
            ( if
                engine_fact_count(E0) = 0,
                not cache_get(engine_cache(E0), "a", _)
              then yes else no ), !T, !IO),
        set_cache_cap(1u32, 0u64, E0, E1),
        set_clock(T1, _, E1, E2),
        assert_external(from_bytes(Body), Refused, Eff1, E2, E3),

        check("LGRA.24.3 a: the block's bound refuses a first external delivery",
            ( if Refused = ext_stopped(rejected(_)) then yes else no ), !T,
            !IO),
        check("LGRA.24.3 a: nothing of the block or the record is placed",
            ( if
                engine_fact_count(E3) = 0,
                not cache_get(engine_cache(E3), "a", _),
                not cache_get(engine_cache(E3), "b", _)
              then yes else no ), !T, !IO),

        Events1 = list.filter_map(
            (func(Ef) = Ev is semidet :- Ef = eff_event(Ev)), Eff1),
        check("LGRA.24.3 b: the refused step records its sample and nothing else",
            ( if
                Events1 = [se_clock_tick(_, _)],
                not (list.member(Ef1, Eff1), Ef1 = eff_input(_))
              then yes else no ), !T, !IO),

        set_cache_cap(0u32, 0u64, E3, E4),
        set_clock(T2, _, E4, E5),
        engine_intern("r2", Id, E5, E6),
        engine_intern("after", Note, E6, E7),
        host_assert(Ref, [str(Id), str(Note)], no, _, Eff2, E7, E8),
        check("LGRA.24.3 c: once the bound is raised the next step applies it",
            ( if
                engine_fact_count(E8) = 2,
                facts_of_schema(engine_wm(E8), Seed ^ s_id) = [S],
                S ^ f_asserted = T2,
                cache_get(engine_cache(E8), "a", _),
                cache_get(engine_cache(E8), "b", _)
              then yes else no ), !T, !IO),

        Meta = session_header(init_engine(P)),
        encode_recording(Meta,
            rfcs_ctx(engine_schemas(E8), engine_interns(E8)),
            engine_now(E0), prelude_seeds(E8),
            record_items(0u64, Eff1 ++ Eff2), Bytes, _),
        decode_stream(from_bytes(list.map(uint8.cast_to_int, Bytes)),
            init_interns, Decoded),
        (
            Decoded = decoded(DS),
            check("LGRA.24.3 d: the recording holds no ExternalAssert",
                ( if DS ^ dsm_external = [] then yes else no ), !T, !IO),
            engine_use_mock_clock(init_engine(P), F0),
            replay_stream(P, DS, RSteps, F0, F),
            check("LGRA.24.3 d: the recording replays without diverging",
                ( if
                    list.find_first_match(
                        (pred(St::in) is semidet :- St = diverged(_)),
                        RSteps, _)
                  then no else yes ), !T, !IO),
            check("LGRA.24.3 d: the replay applies the block under T2",
                ( if
                    engine_fact_count(F) = 2,
                    facts_of_schema(engine_wm(F), Seed ^ s_id) = [RS],
                    RS ^ f_asserted = T2,
                    cache_get(engine_cache(F), "a", _),
                    cache_get(engine_cache(F), "b", _)
                  then yes else no ), !T, !IO)
        ;
            Decoded = decode_failed(Clause, Offset),
            io.format("    initial_external: does not decode: %s at %d\n",
                [s(Clause), i(Offset)], !IO),
            check("LGRA.24.3 d: the recording decodes", no, !T, !IO)
        ;
            Decoded = unannounced_schema(_, _, Offset),
            io.format("    initial_external: stops at RFCS.5.4, byte %d\n",
                [i(Offset)], !IO),
            check("LGRA.24.3 d: the recording decodes", no, !T, !IO)
        )
    else
        check("LGRA.24.3: 140_initial_external's schemas and record", no, !T,
            !IO)
    ).

    % [RFCS.26.1], [RFCS.26.2]: the host's cache seeds are in the prelude
    % and the `initial` block's items are not. `140_initial_external`'s block
    % seeds "a" = 1 and "b" = 2; the host seeds "c" = 3, then "a" = 9, before
    % the first step, a host assert. The prelude is what the cache held at the
    % first event: "a" = 9 ([NLFC.9.3]) and "c" = 3, by key. In g, "t" is
    % seeded with a 5000 ns TTL and the first step is at 1 s, so its deadline
    % is 1 s + 5000 ns ([NLFC.9.4]).
    %
    % Path: `ds.engine.clock_step`'s `rfcs_26_1_snapshot`,
    % `ds.rfcs.encode_recording` and its `at_cache_seed` arm, `ds.replay`'s
    % `rfcs_26_2_apply` and its `Late` arm. libds's counterparts are
    % test_assert_external.c's test 16 and test_rfcs_prelude.c's tests 5
    % and 7.
    %
:- pred check_prelude_seeds(program::in, tally::in, tally::out,
                            io::di, io::uo) is det.

check_prelude_seeds(P, !T, !IO) :-
    IT = interns(P),
    T1 = from_ns(1000000000u64),
    ( if find_schema(schemas(P), IT, "Ref", Ref) then
        engine_use_mock_clock(init_engine(P), E0),
        seed_cache_text("c", "3", no, RC, E0, E1),
        seed_cache_text("a", "9", no, RA, E1, E2),
        check("RFCS.26: the host seeds c and a before the first step",
            ( if RC = seeded, RA = seeded then yes else no ), !T, !IO),
        set_clock(T1, _, E2, E3),
        engine_intern("r1", Id, E3, E4),
        engine_intern("first", Note, E4, E5),
        host_assert(Ref, [str(Id), str(Note)], no, _, Eff, E5, E),

        check("RFCS.26 a: the block keeps the host's a and places b",
            ( if
                cache_text(E, "a") = "9",
                cache_text(E, "b") = "2",
                cache_text(E, "c") = "3"
              then yes else no ), !T, !IO),

        check("RFCS.26.1 b: the prelude's seeds are the host's, by key",
            ( if
                prelude_seeds(E) = [cache_seed("a", "9", 0u64),
                                    cache_seed("c", "3", 0u64)]
              then yes else no ), !T, !IO),

        engine_use_mock_clock(init_engine(P), G0),
        seed_cache_text("t", "1", yes(duration_from_ns(5000u64)), RG, G0, G1),
        set_clock(T1, _, G1, G2),
        engine_intern("r1", GId, G2, G3),
        engine_intern("first", GNote, G3, G4),
        host_assert(Ref, [str(GId), str(GNote)], no, _, _, G4, G),
        check("RFCS.26.1 g: a seed's deadline is the first sample plus its "
                ++ "TTL ([NLFC.9.4])",
            ( if
                RG = seeded,
                prelude_seeds(G) = [cache_seed("t", "1", 1000005000u64)]
              then yes else no ), !T, !IO),

        Meta = session_header(init_engine(P)),
        Ctx = rfcs_ctx(engine_schemas(E), engine_interns(E)),
        encode_recording(Meta, Ctx, engine_now(E0), prelude_seeds(E),
            record_items(0u64, Eff), Bytes, _),
        decode_stream(from_bytes(list.map(uint8.cast_to_int, Bytes)),
            init_interns, Decoded),
        (
            Decoded = decoded(DS),
            check("RFCS.26.1 c: the recording carries a and c, neither late",
                ( if
                    list.map((func(Sd) = {Sd ^ rsd_late, Sd ^ rsd_seed}),
                        DS ^ dsm_seeds)
                        = [{no, cache_seed("a", "9", 0u64)},
                           {no, cache_seed("c", "3", 0u64)}]
                  then yes else no ), !T, !IO),

            engine_use_mock_clock(init_engine(P), F0),
            replay_stream(P, DS, RSteps, F0, F),
            check("RFCS.26.2 d: an unseeded engine replays it without diverging",
                ( if
                    list.find_first_match(
                        (pred(St::in) is semidet :- St = diverged(_)),
                        RSteps, _)
                  then no else yes ), !T, !IO),
            check("RFCS.26.2 d: and ends with the run's cache",
                ( if
                    cache_text(F, "a") = "9",
                    cache_text(F, "b") = "2",
                    cache_text(F, "c") = "3"
                  then yes else no ), !T, !IO),

            engine_use_mock_clock(init_engine(P), B0),
            set_cache_cap(1u32, 0u64, B0, B1),
            replay_stream(P, DS, BSteps, B1, _),
            check("RFCS.26.2 e: a recorded seed the bound refuses diverges",
                ( if BSteps = [diverged(_)] then yes else no ), !T, !IO),

            Spans = list.reverse(frame_spans(init_reader(
                from_bytes(list.map(uint8.cast_to_int, Bytes))), [])),
            ( if
                list.find_first_match(
                    ( pred({A, _, _}::in) is semidet :- A = yes(at_cache_seed) ),
                    Spans, {_, SStart, SEnd}),
                list.find_first_match(
                    ( pred({A, _, _}::in) is semidet :-
                        A = yes(at_clock_advance) ),
                    Spans, {_, _, TEnd}),
                SEnd < TEnd
            then
                list.det_split_list(SStart, Bytes, Before, Rest0),
                list.det_split_list(SEnd - SStart, Rest0, Seed, Rest1),
                list.det_split_list(TEnd - SEnd, Rest1, Tick, After),
                Moved = Before ++ Tick ++ Seed ++ After,
                decode_stream(from_bytes(list.map(uint8.cast_to_int, Moved)),
                    init_interns, MovedDecoded),
                % The move takes "a", the first seed, past the ClockAdvance and
                % leaves "c" ahead of it: "c" stays in the prelude, "a" is late.
                ( if
                    MovedDecoded = decoded(MDS),
                    MDS ^ dsm_seeds = [InPrelude, Moved1],
                    InPrelude ^ rsd_late = no,
                    InPrelude ^ rsd_seed ^ cs_key = "c",
                    Moved1 ^ rsd_late = yes,
                    Moved1 ^ rsd_seed ^ cs_key = "a"
                then
                    check("RFCS.26.2 f: the moved seed decodes late", yes,
                        !T, !IO),
                    engine_use_mock_clock(init_engine(P), M0),
                    replay_stream(P, MDS, MSteps, M0, _),
                    check("RFCS.26.2 f: a seed after an event atom diverges",
                        ( if list.last(MSteps, diverged(_)) then yes else no ),
                        !T, !IO)
                else
                    check("RFCS.26.2 f: the moved seed decodes late", no,
                        !T, !IO)
                )
            else
                check("RFCS.26.2 f: a CacheSeed precedes the first ClockAdvance",
                    no, !T, !IO)
            )
        ;
            Decoded = decode_failed(Clause, Offset),
            io.format("    prelude_seeds: does not decode: %s at %d\n",
                [s(Clause), i(Offset)], !IO),
            check("RFCS.26 c: the recording decodes", no, !T, !IO)
        ;
            Decoded = unannounced_schema(_, _, Offset),
            io.format("    prelude_seeds: stops at RFCS.5.4, byte %d\n",
                [i(Offset)], !IO),
            check("RFCS.26 c: the recording decodes", no, !T, !IO)
        )
    else
        check("RFCS.26: 140_initial_external's Ref", no, !T, !IO)
    ).

    % The JSON text the cache holds for `Key`, deadlines ignored; "" for a
    % miss, which no value here renders as.
    %
:- func cache_text(engine, string) = string.

cache_text(E, Key) = Text :-
    ( if
        cache_get(engine_cache(E), Key, str(Ref)),
        expand(engine_interns(E), Ref, T)
    then
        Text = T
    else
        Text = ""
    ).

    % Each frame of a recording, newest first: its atom (`no` for one the
    % registry does not name), and where it starts and ends.
    %
:- func frame_spans(reader, list({maybe(atom_id), int, int}))
    = list({maybe(atom_id), int, int}).

frame_spans(R0, Rev) = Spans :-
    next_frame(FrameResult, R0, R1),
    (
        FrameResult = fr_ok(Frame),
        ( if Frame ^ fr_atom = known(A) then Atom = yes(A) else Atom = no ),
        Spans = frame_spans(R1, [{Atom, position(R0), position(R1)} | Rev])
    ;
        ( FrameResult = fr_eof
        ; FrameResult = fr_error(_, _)
        ),
        Spans = Rev
    ).

    % [LGRA.24.3], [LTIM.2.8.3]: an `initial` block's domain fault is
    % recorded after the step's input. `147_initial_domain_order`'s block
    % places a `Marker`, whose `ts` a mock clock with no wall value cannot
    % fill. libds's counterpart is test_assert_external.c's test 15, and the
    % runtime differential compares the two runtimes' traces.
    %
    % Path: `ds.engine.clock_step` -> `lgra_24_3_apply` raises the fault, and
    % `lgra_24_3_after_input` places it in `host_assert_core` and in
    % `pump_live`.
    %
% @spec [LGRA.24.3]
:- pred check_initial_domain_order(program::in, tally::in, tally::out,
                                   io::di, io::uo) is det.

check_initial_domain_order(P, !T, !IO) :-
    IsDomain = (pred(Ev::in) is semidet :-
        Ev = se_engine_error(ee_expr_fault(rf_domain), _)),
    ( if find_schema(schemas(P), interns(P), "Trig", Trig) then
        T1 = from_ns(1000000000u64),
        engine_use_mock_clock(init_engine(P), E0),
        set_clock(T1, _, E0, E1),

        host_assert(Trig, [int(3i64)], no, RA, FxA, E1, EA),
        EvA = stream_events_of(FxA),
        check("[LGRA.24.3] a first host assert: its TICK, its FactAssert, then "
            ++ "the `initial` block's DOMAIN fault",
            ( if
                RA = inserted(TrigId),
                EvA = [se_clock_tick(_, _), se_fact_assert(TrigId, _, _, _),
                    DA | _],
                IsDomain(DA)
              then yes else no ), !T, !IO),

        pump(default_budget, FxP, E1, EP),
        EvP = stream_events_of(FxP),
        check("[LGRA.24.3] a first pump: its TICK, its PumpBoundary, then "
            ++ "the `initial` block's DOMAIN fault",
            ( if
                EvP = [se_clock_tick(_, _), se_pump_boundary, DP | _],
                IsDomain(DP)
              then yes else no ), !T, !IO),

        RecA = recorded_atoms(P, E0, EA, FxA),
        OkA = ( if
                RecA = [at_clock_advance, at_fact_assert, at_computation_error
                    | _]
              then yes else no ),
        print_recorded_if(OkA, "host assert", RecA, !IO),
        check("[LGRA.24.3] a first host assert's recording: ClockAdvance, "
            ++ "FactAssert, then ComputationError", OkA, !T, !IO),
        RecP = recorded_atoms(P, E0, EP, FxP),
        OkP = ( if
                RecP = [at_clock_advance, at_pump_boundary, at_computation_error
                    | _]
              then yes else no ),
        print_recorded_if(OkP, "pump", RecP, !IO),
        check("[LGRA.24.3] a first pump's recording: ClockAdvance, "
            ++ "PumpBoundary, then ComputationError", OkP, !T, !IO)
    else
        check("[LGRA.24.3] 147_initial_domain_order declares Trig", no, !T,
            !IO)
    ).

    % On a failed recording check, what the recording read back, so the
    % failure says which event is out of place.
    %
:- pred print_recorded_if(bool::in, string::in, list(atom_id)::in,
                          io::di, io::uo) is det.

print_recorded_if(yes, _, _, !IO).
print_recorded_if(no, Shape, Recorded, !IO) :-
    io.format("    initial_domain_order, %s: the recording read back %s\n",
        [s(Shape), s(string.string(Recorded))], !IO).

    % A step's stream events, in order: the effects that are events.
    %
:- func stream_events_of(list(effect)) = list(stream_event).

stream_events_of(Fx) =
    list.filter_map((func(Ef) = Ev is semidet :- Ef = eff_event(Ev)), Fx).

    % One step's effects recorded, and the recording's atoms read back in file
    % order from its first ClockAdvance, the step's sample: everything before
    % it is the prelude (StreamHeader, SchemaDef, Slot). The atoms, not
    % `decode_stream`'s events, because a fault atom decodes to no event
    % (`ds.rfcs.read_known`), so the decoded list cannot show where the fault
    % sits. A frame that does not read ends the list, so the caller's pattern
    % fails. `E0` is the engine as loaded, whose clock the recording starts
    % from; `E` the engine after the step, whose schemas and interns it names.
    %
:- func recorded_atoms(program, engine, engine, list(effect)) = list(atom_id).

recorded_atoms(P, E0, E, Fx) = Atoms :-
    encode_recording(session_header(init_engine(P)),
        rfcs_ctx(engine_schemas(E), engine_interns(E)),
        engine_now(E0), prelude_seeds(E), record_items(0u64, Fx), Bytes, _),
    frame_atoms(init_reader(from_bytes(list.map(uint8.cast_to_int, Bytes))),
        [], RevAtoms),
    Atoms = list.drop_while(
        ( pred(A::in) is semidet :- A \= at_clock_advance ),
        list.reverse(RevAtoms)).

:- pred frame_atoms(reader::in, list(atom_id)::in, list(atom_id)::out) is det.

frame_atoms(R0, !RevAtoms) :-
    next_frame(FrameResult, R0, R1),
    (
        FrameResult = fr_ok(Frame),
        ( if Frame ^ fr_atom = known(A) then
            !:RevAtoms = [A | !.RevAtoms]
        else
            true
        ),
        frame_atoms(R1, !RevAtoms)
    ;
        ( FrameResult = fr_eof
        ; FrameResult = fr_error(_, _)
        )
    ).

%-----------------------------------------------------------------------------%
% ds.fact_receive: `assert_external` ([NCBK.10.4], [RFCS.23.7]), the cases
% of libds's runtime/tests/libds/impl/test_assert_external.c and the ones
% only a decoder written apart from protobuf-c can get wrong.
%-----------------------------------------------------------------------------%

    % A FactExternal of one of `125_assert_external`'s schemas, with the
    % given fields, as the program's own schema hashes it.
    %
:- pred fe_of(program::in, string::in, list(arg)::in, fact_external::out)
    is semidet.

fe_of(P, SchemaName, Fields, fact_external(Name, Hash, Fields, no)) :-
    IT = interns(P),
    find_schema(schemas(P), IT, SchemaName, Schema),
    schema_name_and_hash(IT, Schema, Name, Hash).

:- pred body_of(fact_external::in, list(int)::out) is semidet.

body_of(FE, list.map(uint8.cast_to_int, Bytes)) :-
    encode_fact_external(FE, Bytes).

:- pred ref_fe(program::in, string::in, string::in, fact_external::out)
    is semidet.

ref_fe(P, Id, Note, FE) :-
    fe_of(P, "Ref", [arg("id", av_string(Id)), arg("note", av_string(Note))],
        FE).

    % `Main`: `k`, a nested `Ref(Id, Note)`, and the given field for `x`.
    %
:- pred main_body(program::in, int64::in, string::in, string::in, arg::in,
                  list(int)::out) is semidet.

main_body(P, K, Id, Note, XArg, Body) :-
    ref_fe(P, Id, Note, RefFE),
    fe_of(P, "Main", [arg("k", av_int(K)), arg("r", av_fact_ref(RefFE)), XArg],
        MainFE),
    body_of(MainFE, Body).

:- pred doc_body(program::in, string::in, list(int)::out) is semidet.

doc_body(P, JsonText, Body) :-
    fe_of(P, "Doc",
        [arg("body", av_json(JsonText)), arg("raw", av_bytes([1u8, 2u8]))],
        FE),
    body_of(FE, Body).

    % `Tagged(1, -> Tag("t"))`.
    %
:- pred tagged_body(program::in, list(int)::out) is semidet.

tagged_body(P, Body) :-
    fe_of(P, "Tag", [arg("name", av_string("t"))], TagFE),
    fe_of(P, "Tagged", [arg("k", av_int(1i64)), arg("t", av_fact_ref(TagFE))],
        FE),
    body_of(FE, Body).

    % `Pair(7, -> Ref("r1", NoteA), -> Ref("r1", NoteB))`.
    %
:- pred pair_body(program::in, string::in, string::in, list(int)::out)
    is semidet.

pair_body(P, NoteA, NoteB, Body) :-
    ref_fe(P, "r1", NoteA, A),
    ref_fe(P, "r1", NoteB, B),
    fe_of(P, "Pair", [arg("k", av_int(7i64)), arg("a", av_fact_ref(A)),
        arg("b", av_fact_ref(B))], FE),
    body_of(FE, Body).

    % `Ni` of the chain, inlining `N(i-1)` .. `N0`: N0 at depth i.
    %
:- pred chain_fe(program::in, int::in, fact_external::out) is semidet.

chain_fe(P, I, FE) :-
    Name = "N" ++ string.int_to_string(I),
    N = arg("n", av_int(int64.cast_from_int(I))),
    ( if I = 0 then
        fe_of(P, Name, [N], FE)
    else
        chain_fe(P, I - 1, Inner),
        fe_of(P, Name, [N, arg("r", av_fact_ref(Inner))], FE)
    ).

    % The first occurrence of `Old` in the bytes, replaced by `New`.
    %
:- func replace_bytes(list(int), list(int), list(int)) = list(int).

replace_bytes(Old, New, Bs) =
    ( if list.append(Old, Rest, Bs) then
        New ++ Rest
    else if Bs = [B | Bs1] then
        [B | replace_bytes(Old, New, Bs1)]
    else
        []
    ).

    % [LTIM.1.2.2], as libds's
    % `test_a_date_outside_its_range_refuses_the_record`. A Stamp on the last
    % Date, 2262-04-11, packs as it leaves the engine and arrives; the same
    % record with `day`'s varint replaced by 106752's (2262-04-12) is
    % refused. Both varints are three bytes, behind `int_value`'s tag 0x18, so
    % no length moves. Path: `ds.fact_receive.plan_field`'s `kind_int` arm.
    %
:- pred check_external_date_range(program::in, tally::in, tally::out,
                                  io::di, io::uo) is det.

check_external_date_range(P, !T, !IO) :-
    ( if
        find_schema(schemas(P), interns(P), "Stamp", Stamp),
        engine_use_mock_clock(init_engine(P), A0),
        host_assert(Stamp, [int(1i64), int(1700000000000000000i64),
            int(106751i64), int(90000000000i64)], no, inserted(Id), _, A0, A1),
        SchemaMap = map.from_assoc_list(list.map(
            ( func(S) = schema_id_value(S ^ s_id) - S ), schemas(P))),
        recorded_external_bytes(SchemaMap, engine_interns(A1), engine_wm(A1),
            no, Id, Bytes),
        Body = list.map(uint8.cast_to_int, Bytes)
    then
        Past = replace_bytes([0x18, 0xFF, 0xC1, 0x06], [0x18, 0x80, 0xC2, 0x06],
            Body),
        engine_use_mock_clock(init_engine(P), B0),
        assert_external(from_bytes(Body), LastRes, _, B0, B1),
        check("[LTIM.1.2.2] the last Date crosses tiers",
            ( if LastRes = ext_asserted, engine_fact_count(B1) = 1
              then yes else no ), !T, !IO),
        check("[LTIM.1.2.2] the crafted record differs from the original",
            ( if Past \= Body then yes else no ), !T, !IO),
        assert_external(from_bytes(Past), PastRes, _, B0, B2),
        check("[LTIM.1.2.2] a Date past the last refuses the record as "
                ++ "DS_ERR_TIME_RANGE, nothing asserted",
            ( if PastRes = ext_refused(xr_time_range), engine_fact_count(B2) = 0
              then yes else no ), !T, !IO)
    else
        check("[LTIM.1.2.2] the Stamp asserts and packs", no, !T, !IO)
    ).

    % A FactExternal nested `Wraps` deep: every level names `Schema` (its
    % bytes) and holds one field `r` whose fact is the next, the innermost a
    % bare `Ref`. Written innermost first, each level's header put in front of
    % the bytes it wraps, so a level costs its header and no copy.
    %
:- func deep_record(int, list(int)) = list(int).

deep_record(Wraps, Schema) = Bytes :-
    Ref = [0x0A, 3, 0x52, 0x65, 0x66],
    deep_wrap(Wraps, Schema, Ref, list.length(Ref), Bytes).

:- pred deep_wrap(int::in, list(int)::in, list(int)::in, int::in,
                  list(int)::out) is det.

deep_wrap(N, Schema, Inner, Len, Out) :-
    ( if N =< 0 then
        Out = Inner
    else
        ArgHead = [0x0A, 1, 0x72, 0x4A] ++ varint(Len),
        ArgLen = list.length(ArgHead) + Len,
        FactHead = [0x0A, list.length(Schema)] ++ Schema ++ [0x1A]
            ++ varint(ArgLen),
        deep_wrap(N - 1, Schema, FactHead ++ (ArgHead ++ Inner),
            list.length(FactHead) + ArgLen, Out)
    ).

:- pred str_slot(engine::in, fact::in, int::in, string::out) is semidet.

str_slot(E, F, I, S) :-
    array.lookup(F ^ f_slots, I) = str(Ref),
    expand(engine_interns(E), Ref, S).

% @spec [LGRA.5.8.6] [LGRA.5.8.7a] [NCBK.10.4] [RFCS.23.7]
:- pred check_assert_external(program::in, tally::in, tally::out,
                              io::di, io::uo) is det.

check_assert_external(P, !T, !IO) :-
    IT = interns(P),
    ( if
        find_schema(schemas(P), IT, "Ref", Ref),
        find_schema(schemas(P), IT, "Main", Main),
        find_schema(schemas(P), IT, "Doc", Doc),
        main_body(P, 1i64, "r1", "hello", arg("x", av_float(2.5)), Body)
    then
        Bytes = from_bytes(Body),

        % 1. A ROUND TRIP: the record's fact and the fact it references both
        % arrive, the reference resolved to the inlined copy.
        engine_use_mock_clock(init_engine(P), B0),
        assert_external(Bytes, RoundTrip, _, B0, B1),
        check("assert_external: a record and the fact it references arrive",
            ( if RoundTrip = ext_asserted, engine_fact_count(B1) = 2
              then yes else no ), !T, !IO),
        check("assert_external: the reference is the inlined copy, intact",
            ( if
                facts_of_schema(engine_wm(B1), Main ^ s_id) = [M],
                facts_of_schema(engine_wm(B1), Ref ^ s_id) = [RF],
                array.lookup(M ^ f_slots, 0) = int(1i64),
                array.lookup(M ^ f_slots, 1) = fact_ref(RF ^ f_id),
                array.lookup(M ^ f_slots, 2) = float(2.5),
                str_slot(B1, RF, 1, "hello")
              then yes else no ), !T, !IO),

        % 2. [RFCS.23.7] STEP 1: tier A holds Ref("r1", "hello"), and the
        % record's nested Ref is EQUAL to it, so it IS that fact: no second
        % Ref and no conflict -- what a fact sent back to its publisher meets.
        engine_use_mock_clock(init_engine(P), A0),
        engine_intern("r1", AId, A0, A1),
        engine_intern("hello", ANote, A1, A2),
        host_assert(Ref, [str(AId), str(ANote)], no, _, _, A2, A3),
        assert_external(Bytes, Back, _, A3, A4),
        check("[RFCS.23.7] 1: a reference equal to a live fact is taken",
            ( if Back = ext_asserted then yes else no ), !T, !IO),
        check("[RFCS.23.7] 1: it IS the live fact: no second Ref",
            ( if
                engine_fact_count(A4) = 2,
                facts_of_schema(engine_wm(A4), Ref ^ s_id) = [Own],
                facts_of_schema(engine_wm(A4), Main ^ s_id) = [AM],
                array.lookup(AM ^ f_slots, 1) = fact_ref(Own ^ f_id)
              then yes else no ), !T, !IO),

        % 2b. Step 1 on a schema with no key: `Tag` (scope explicit) holds two
        % equal facts, and the reference is the earliest, not a third copy.
        ( if
            tagged_body(P, TaggedBody),
            find_schema(schemas(P), IT, "Tag", Tag),
            find_schema(schemas(P), IT, "Tagged", Tagged)
        then
            engine_use_mock_clock(init_engine(P), G0),
            engine_intern("t", GT, G0, G1),
            host_assert(Tag, [str(GT)], no, _, _, G1, G2),
            host_assert(Tag, [str(GT)], no, _, _, G2, G3),
            assert_external(from_bytes(TaggedBody), TagRes, _, G3, G4),
            check("[RFCS.23.7] 1: a reference equal to two live facts, taken",
                ( if TagRes = ext_asserted then yes else no ), !T, !IO),
            check("[RFCS.23.7] 1: it is the earliest of the two; no third Tag",
                ( if
                    facts_of_schema(engine_wm(G4), Tag ^ s_id) = [T1, _],
                    facts_of_schema(engine_wm(G4), Tagged ^ s_id) = [TG],
                    array.lookup(TG ^ f_slots, 1) = fact_ref(T1 ^ f_id)
                  then yes else no ), !T, !IO)
        else
            check("assert_external: the Tagged record encodes", no, !T, !IO)
        ),

        % 2c. ONE FACT INLINED TWICE: `Pair`'s two slots carry one Ref. The
        % second copy meets the first, which the record asserts ahead of it,
        % and is that fact, not a key conflict with the first.
        ( if
            pair_body(P, "hello", "hello", SameBody),
            pair_body(P, "hello", "other", SplitBody),
            find_schema(schemas(P), IT, "Pair", Pair)
        then
            engine_use_mock_clock(init_engine(P), D0),
            assert_external(from_bytes(SameBody), Same, _, D0, D1),
            check("[RFCS.23.7] 1: one fact inlined twice is one fact",
                ( if
                    Same = ext_asserted,
                    engine_fact_count(D1) = 2,
                    facts_of_schema(engine_wm(D1), Ref ^ s_id) = [DR],
                    facts_of_schema(engine_wm(D1), Pair ^ s_id) = [DP],
                    array.lookup(DP ^ f_slots, 1) = fact_ref(DR ^ f_id),
                    array.lookup(DP ^ f_slots, 2) = fact_ref(DR ^ f_id)
                  then yes else no ), !T, !IO),
            % ... and two copies with one key and different values are not.
            assert_external(from_bytes(SplitBody), Split, SplitEffects,
                D0, D2),
            check("[RFCS.23.7] 3: one key, two values in one record: refused",
                ( if
                    Split = ext_refused(xr_fact_ref_conflict),
                    SplitEffects = [],
                    engine_fact_count(D2) = 0
                  then yes else no ), !T, !IO)
        else
            check("assert_external: the Pair records encode", no, !T, !IO)
        ),

        % 2d. [RFCS.23.4]: N0 at depth 16 is accepted, at depth 17 refused
        % whole as malformed.
        ( if
            chain_fe(P, 16, Chain16),
            chain_fe(P, 17, Chain17),
            body_of(Chain16, Deep16),
            body_of(Chain17, Deep17)
        then
            engine_use_mock_clock(init_engine(P), H0),
            assert_external(from_bytes(Deep16), Res16, _, H0, H16),
            check("[RFCS.23.4] references nested 16 deep are accepted",
                ( if Res16 = ext_asserted, engine_fact_count(H16) = 17
                  then yes else no ), !T, !IO),
            assert_external(from_bytes(Deep17), Res17, _, H0, H17),
            check("[RFCS.23.4] 17 deep is DS_ERR_PARSE, nothing asserted",
                ( if Res17 = ext_refused(xr_parse), engine_fact_count(H17) = 0
                  then yes else no ), !T, !IO)
        else
            check("assert_external: the chain records encode", no, !T, !IO)
        ),

        % 2e. [NCBK.10.4]: a record nested 100 000 deep is
        % DS_ERR_PARSE and asserts nothing; and one nested too deep under a
        % schema this program does not declare is DS_ERR_PARSE too, not
        % DS_ERR_SCHEMA_UNKNOWN: the cap is checked over the whole record
        % before the plan, as libds's raw walk checks it before its unpack.
        engine_use_mock_clock(init_engine(P), Deep0),
        assert_external(from_bytes(deep_record(100000, [0x4D, 0x61, 0x69, 0x6E])),
            DeepRes, DeepEffects, Deep0, Deep1),
        check("[NCBK.10.4] a record 100 000 deep is DS_ERR_PARSE, nothing "
                ++ "asserted",
            ( if
                DeepRes = ext_refused(xr_parse),
                DeepEffects = [],
                engine_fact_count(Deep1) = 0
              then yes else no ), !T, !IO),
        assert_external(from_bytes(deep_record(17, [0x4E, 0x6F, 0x70, 0x65])),
            NopeRes, _, Deep0, Deep2),
        check("[NCBK.10.4] too deep under an unknown schema is DS_ERR_PARSE",
            ( if NopeRes = ext_refused(xr_parse), engine_fact_count(Deep2) = 0
              then yes else no ), !T, !IO),

        % 3. [RFCS.23.7] STEP 3: a live Ref holding the key with a different
        % note refuses the WHOLE record.
        engine_use_mock_clock(init_engine(P), C0),
        engine_intern("r1", CId, C0, C1),
        engine_intern("other", CNote, C1, C2),
        host_assert(Ref, [str(CId), str(CNote)], no, _, _, C2, C3),
        assert_external(Bytes, Conflict, ConflictEffects, C3, C4),
        check("[RFCS.23.7] 3: the key with different values refuses it",
            ( if Conflict = ext_refused(xr_fact_ref_conflict)
              then yes else no ), !T, !IO),
        check("[RFCS.23.7] 3: nothing asserted, nothing replaced, no event",
            ( if
                engine_fact_count(C4) = 1,
                ConflictEffects = [],
                facts_of_schema(engine_wm(C4), Ref ^ s_id) = [CF],
                str_slot(C4, CF, 1, "other")
              then yes else no ), !T, !IO),

        % 6. Bytes that are not a FactExternal.
        assert_external(from_bytes([0xFF, 0xFF, 0xFF, 0xFF]), Junk, _,
            B0, BJ),
        check("assert_external: bytes that are not a FactExternal: parse",
            ( if Junk = ext_refused(xr_parse), engine_fact_count(BJ) = 0
              then yes else no ), !T, !IO),

        % A NaN FLOAT is refused (LEXP.4.2), seen from its bits: the decoder's
        % `float_from_bits` would read it as 0.0. The record is 2.5's with
        % that field's eight bytes replaced by a quiet NaN's.
        TwoPointFive = [0x21, 0, 0, 0, 0, 0, 0, 0x04, 0x40],
        QuietNaN = [0x21, 0, 0, 0, 0, 0, 0, 0xF8, 0x7F],
        NaNBody = replace_bytes(TwoPointFive, QuietNaN, Body),
        assert_external(from_bytes(NaNBody), NaN, _, B0, BN),
        check("assert_external: the NaN record differs from the original",
            ( if NaNBody \= Body then yes else no ), !T, !IO),
        check("assert_external: a NaN Float is DS_ERR_NAN_REJECTED",
            ( if NaN = ext_refused(xr_nan_rejected), engine_fact_count(BN) = 0
              then yes else no ), !T, !IO),

        % A KIND ITS SLOT DOES NOT TAKE: `x` is a Float slot.
        ( if
            main_body(P, 1i64, "r1", "hello", arg("x", av_int(3i64)), IntBody)
        then
            assert_external(from_bytes(IntBody), WrongKind, _, B0, BW),
            check("assert_external: an Int for a Float slot is a mismatch",
                ( if WrongKind = ext_refused(xr_slot_type_mismatch),
                     engine_fact_count(BW) = 0
                  then yes else no ), !T, !IO)
        else
            check("assert_external: the Int record encodes", no, !T, !IO)
        ),

        % JSON TEXT through `ds.json_text`, and Bytes.
        ( if
            doc_body(P, "{\"a\":[1,2.5]}", GoodDoc),
            doc_body(P, "{\"a\":", BadDoc),
            doc_body(P, " null ", NullDoc)
        then
            assert_external(from_bytes(GoodDoc), Good, _, B0, BG),
            check("assert_external: a Json field parses into the slot",
                ( if
                    Good = ext_asserted,
                    facts_of_schema(engine_wm(BG), Doc ^ s_id) = [D],
                    array.lookup(D ^ f_slots, 0) = json(j_object(object(
                        ["a" - j_array([j_int(1i64), j_float(2.5)])]))),
                    array.lookup(D ^ f_slots, 1) = bytes(from_bytes([1, 2]))
                  then yes else no ), !T, !IO),
            assert_external(from_bytes(BadDoc), Bad, _, B0, BB),
            check("assert_external: Json that does not parse: parse",
                ( if Bad = ext_refused(xr_parse), engine_fact_count(BB) = 0
                  then yes else no ), !T, !IO),
            assert_external(from_bytes(NullDoc), Null, _, B0, BL),
            check("assert_external: a root-null Json document is a mismatch",
                ( if Null = ext_refused(xr_slot_type_mismatch),
                     engine_fact_count(BL) = 0
                  then yes else no ), !T, !IO)
        else
            check("assert_external: the Doc records encode", no, !T, !IO)
        ),

        % [LGRA.5.8.6]: a received Json field has its own text limit, 106496
        % bytes (`ds.json.max_fx_text_bytes`), not the host's 24576. libds's
        % values (test_assert_external.c, `json_text_limits`), each premise
        % measured here:
        %   - one string of 4095 U+0001 written as the six bytes `\u0001`
        %     each, then `aaaa` or `aaaaa`: 24576 and 24577 bytes, inside the
        %     three tree limits, both admitted;
        %   - `1` and 106495 spaces, 106496 bytes: admitted, as the Int 1;
        %   - 106497 bytes of `x`: refused with xr_json_limit. It is not JSON,
        %     so xr_json_limit shows the length is checked unread;
        %   - 16384 U+0001, at the string-bytes limit and inside the other two,
        %     is 98306 bytes of text as `ds.format.json_text` writes it, the
        %     text the packer writes (`ds.exec`'s `slot_arg_value`): the bound
        %     is reachable.
        TLCtl = string.append_list(list.duplicate(4095, "\\u0001")),
        TLAtText = "\"" ++ TLCtl ++ "aaaa\"",
        TLOverText = "\"" ++ TLCtl ++ "aaaaa\"",
        FxAtText = "1" ++ string.duplicate_char(' ', 106495),
        FxOverText = string.duplicate_char('x', 106497),
        BoundJ = j_string(string.duplicate_char(char.det_from_int(1), 16384)),
        check("assert_external: the Json text limits' premises",
            ( if
                string.count_utf8_code_units(TLAtText) = 24576,
                string.count_utf8_code_units(TLOverText) = 24577,
                string.count_utf8_code_units(FxAtText) = 106496,
                string.count_utf8_code_units(FxOverText) = 106497,
                ds.json.max_fx_text_bytes = 106496,
                ds.json.limit_breach(BoundJ) = no,
                ds.format.json_text(BoundJ, PremiseText),
                string.count_utf8_code_units(PremiseText) = 98306
              then yes else no ), !T, !IO),
        ( if
            doc_body(P, TLAtText, TLAtDoc),
            doc_body(P, TLOverText, TLOverDoc),
            doc_body(P, FxAtText, FxAtDoc),
            doc_body(P, FxOverText, FxOverDoc),
            ds.format.json_text(BoundJ, BoundText),
            doc_body(P, BoundText, BoundDoc)
        then
            assert_external(from_bytes(TLAtDoc), TLAt, _, B0, TLBA),
            check("LGRA.5.8.6 a received Json field: 24576 bytes admitted",
                ( if TLAt = ext_asserted, engine_fact_count(TLBA) = 1
                  then yes else no ), !T, !IO),
            assert_external(from_bytes(TLOverDoc), TLOver, _, B0, TLBO),
            check("LGRA.5.8.6 a received Json field: 24577 bytes admitted",
                ( if TLOver = ext_asserted, engine_fact_count(TLBO) = 1
                  then yes else no ), !T, !IO),
            assert_external(from_bytes(FxAtDoc), FxAt, _, B0, FxBA),
            check("LGRA.5.8.6 a received Json field: 106496 bytes admitted",
                ( if
                    FxAt = ext_asserted,
                    facts_of_schema(engine_wm(FxBA), Doc ^ s_id) = [FxD],
                    array.lookup(FxD ^ f_slots, 0) = json(j_int(1i64))
                  then yes else no ), !T, !IO),
            assert_external(from_bytes(FxOverDoc), FxOver, FxOverEffects,
                B0, FxBO),
            check("LGRA.5.8.6 a received Json field: 106497 bytes refused "
                    ++ "unread, nothing asserted",
                ( if
                    FxOver = ext_refused(xr_json_limit),
                    FxOverEffects = [],
                    engine_fact_count(FxBO) = 0
                  then yes else no ), !T, !IO),
            assert_external(from_bytes(BoundDoc), Bound, _, B0, BoundB),
            check("LGRA.5.8.6 the bound is reachable: 16384 U+0001 arrive",
                ( if
                    Bound = ext_asserted,
                    facts_of_schema(engine_wm(BoundB), Doc ^ s_id) = [BoundD],
                    array.lookup(BoundD ^ f_slots, 0) = json(BoundJ)
                  then yes else no ), !T, !IO)
        else
            check("assert_external: the Json text-limit records encode", no,
                !T, !IO)
        ),

        % [LGRA.5.8.7a]: the one text a runtime writes for a Json value. A
        % `Doc` holds an object built with its keys out of order;
        % the fact is packed as it leaves the engine
        % (`ds.exec.recorded_external_bytes`, the encoder `call` and
        % `publish` use) and decoded, and its field's text is compared byte
        % for byte with the text libds's test_assert_external.c pins:
        % members by key bytes (`B` before `a`); `"`, `\`, U+0008, U+000C,
        % U+000A, U+000D and U+0009 as their short forms; U+0001 and U+001F
        % as `\u00` and two LOWERCASE hex digits; U+00E9 verbatim; no
        % whitespace.
        ExactJ = j_object(object([
            "b" - j_int(-7i64),
            "a" - j_string("\"\\\b\f\n\r\t" ++ ctl_char(1) ++ ctl_char(0x1f)
                ++ "é"),
            "B" - j_array([j_bool(yes), j_null, j_float(1.5)])
        ])),
        ExactWant = "{\"B\":[true,null,1.5],"
            ++ "\"a\":\"\\\"\\\\\\b\\f\\n\\r\\t\\u0001\\u001fé\","
            ++ "\"b\":-7}",
        ( if
            engine_use_mock_clock(init_engine(P), X0),
            host_assert(Doc, [json(ExactJ), bytes(from_bytes([1, 2]))], no,
                inserted(XId), _, X0, X1),
            SchemaMap = map.from_assoc_list(list.map(
                ( func(S) = schema_id_value(S ^ s_id) - S ), schemas(P))),
            recorded_external_bytes(SchemaMap, engine_interns(X1),
                engine_wm(X1), no, XId, XBytes),
            XBody = list.map(uint8.cast_to_int, XBytes),
            decode_fact_external(from_bytes(XBody),
                raw_fact_external(_, _, XFields)),
            list.find_first_match(
                ( pred(A::in) is semidet :- A ^ ra_name = "body" ),
                XFields, XField),
            XField ^ ra_value = yes(fev_json(XText))
        then
            check("LGRA.5.8.7a a Json value's text, packed, is the one text",
                ( if XText = ExactWant then yes else no ), !T, !IO),
            assert_external(from_bytes(XBody), XBack, _, B0, XB),
            check("LGRA.5.8.7a and it arrives as the value it was",
                ( if
                    XBack = ext_asserted,
                    facts_of_schema(engine_wm(XB), Doc ^ s_id) = [XD],
                    array.lookup(XD ^ f_slots, 0) = json(ExactJ)
                  then yes else no ), !T, !IO)
        else
            check("LGRA.5.8.7a the Doc fact asserts, packs and decodes", no,
                !T, !IO)
        ),

        % [LGRA.5.8.8] on the receive path: a received FactExternal whose
        % Json field's text holds `-0.0` arrives as +0.0, so `1.0 / v` is
        % +inf, and the `-1.5` beside it keeps its sign. libds pins the same
        % (test_assert_external.c, `a_received_zero_has_no_sign`). Path:
        % `ds.fact_receive`'s Json field -> `ds.json_text.parse_with` ->
        % `number`'s fold of the leaf.
        ( if doc_body(P, "{\"v\":-0.0,\"w\":-1.5}", ZeroDoc) then
            assert_external(from_bytes(ZeroDoc), ZeroRes, _, B0, BZ),
            check("LGRA.5.8.8 a received Json field's -0.0 arrives as +0.0, "
                    ++ "and -1.5 keeps its sign",
                ( if
                    ZeroRes = ext_asserted,
                    facts_of_schema(engine_wm(BZ), Doc ^ s_id) = [ZD],
                    array.lookup(ZD ^ f_slots, 0) = json(j_object(ZMs)),
                    lookup_member(ZMs, "v", j_float(V)),
                    lookup_member(ZMs, "w", j_float(W)),
                    float.unchecked_quotient(1.0, V) > 0.0,
                    W = -1.5
                  then yes else no ), !T, !IO)
        else
            check("LGRA.5.8.8 the -0.0 record encodes", no, !T, !IO)
        ),

        % [LSTR.1.5]: a text field holding U+0000 refuses the record, as
        % libds's `fx_scan_nul` refuses it (test_assert_external.c, 9). The
        % NUL is planted in the encoded bytes, since no Mercury string holds
        % one: a String field `heZlo` (Arg field 5) becomes `he\0lo`, and a
        % Json field `12345` (Arg field 7) becomes `12\0` `45`. Refused here by
        % the UTF-8 decode (`ds.wire.reader_string`), which admits no NUL.
        ( if
            main_body(P, 1i64, "r1", "heZlo", arg("x", av_float(2.5)),
                NoteBody),
            patch_nul([0x2A, 0x05, 0x68, 0x65, 0x5A, 0x6C, 0x6F], 4,
                NoteBody, NoteNul),
            doc_body(P, "12345", TextBody),
            patch_nul([0x3A, 0x05, 0x31, 0x32, 0x33, 0x34, 0x35], 4,
                TextBody, TextNul)
        then
            assert_external(from_bytes(NoteNul), NulNote, _, B0, BS),
            check("[LSTR.1.5] a String field holding U+0000: parse, nothing",
                ( if NulNote = ext_refused(xr_parse), engine_fact_count(BS) = 0
                  then yes else no ), !T, !IO),
            assert_external(from_bytes(TextNul), NulText, _, B0, BT),
            check("[LSTR.1.5] a Json field holding U+0000: parse, nothing",
                ( if NulText = ext_refused(xr_parse), engine_fact_count(BT) = 0
                  then yes else no ), !T, !IO)
        else
            check("[LSTR.1.5] the NUL records encode and patch", no, !T, !IO)
        ),

        test_ncbk_10_4_ill_formed_text(P, B0, !T, !IO),
        test_nfct_2_3_wrong_target(P, B0, !T, !IO),
        test_nfct_2_3_dead_target(P, B0, !T, !IO),
        test_idat_3_3_10_path_grammar(!T, !IO),

        % [RFCS.23.6]: no TTL travels. Whatever the sender held a `Lease`
        % under (libds's test 13: a 10 s schema with a 60 s per-emit
        % override), the receiver applies its own `scope ttl 30_s`. Path:
        % `ds.fact_receive`'s assert, whose deadline is the receiving schema's
        % TTL from the receive's clock, then the pump's sweep.
        ( if
            find_schema(schemas(P), IT, "Lease", Lease),
            fe_of(P, "Lease", [arg("id", av_string("l1"))], LeaseFE),
            body_of(LeaseFE, LeaseBody)
        then
            assert_external(from_bytes(LeaseBody), LeaseRes, _, B0, L1),
            check("RFCS.23.6 a received Lease's deadline is the receiver's 30 s",
                ( if
                    LeaseRes = ext_asserted,
                    facts_of_schema(engine_wm(L1), Lease ^ s_id) = [LF],
                    LF ^ f_deadline = yes(LAt),
                    instant_ns(LAt) = 30000000000u64
                  then yes else no ), !T, !IO),
            advance(duration_from_ns(29999999999u64), _, L1, L2),
            pump(default_budget, _, L2, L3),
            check("RFCS.23.6 live at 30 s - 1 ns",
                ( if facts_of_schema(engine_wm(L3), Lease ^ s_id) = [_]
                  then yes else no ), !T, !IO),
            advance(duration_from_ns(1u64), _, L3, L4),
            pump(default_budget, _, L4, L5),
            check("RFCS.23.6 gone at 30 s",
                ( if facts_of_schema(engine_wm(L5), Lease ^ s_id) = []
                  then yes else no ), !T, !IO)
        else
            check("RFCS.23.6 the Lease record encodes", no, !T, !IO)
        ),

        % 4 AND 5: the same bytes at a tier with no `Main`, and at one whose
        % `Main.x` is an Int.
        with_fixture("06_rule_with_where.dsc",
            check_external_refused(Bytes, xr_schema_unknown,
                "4: a schema the receiver does not declare"), !T, !IO),
        with_fixture("126_assert_external_int.dsc",
            check_external_refused(Bytes, xr_schema_hash_mismatch,
                "5: a schema of another shape"), !T, !IO)
    else
        check("assert_external: 125_assert_external's records encode", no,
            !T, !IO)
    ).

    % @spec [RFCS.23.7]
    % A target a delivery's own asserts remove reads as gone, and the
    % delivery goes on, as libds's `test_rfcs_23_7__*` pin. Path:
    % `assert_external_with` -> `assert_plan` -> `host_assert_in_step`, which
    % judges no liveness (`Own = no` in `host_assert_core`). The live control
    % of each is `check_assert_external`'s round trip.
    %
:- pred check_rfcs_23_7_gone_target(program::in, tally::in, tally::out,
                                    io::di, io::uo) is det.

check_rfcs_23_7_gone_target(P, !T, !IO) :-
    IT = interns(P),
    ( if
        find_schema(schemas(P), IT, "Ans", Ans),
        find_schema(schemas(P), IT, "CallError", Err),
        find_schema(schemas(P), IT, "D", D),
        find_schema(schemas(P), IT, "R", R),
        find_schema(schemas(P), IT, "Rd", Rd),
        find_schema(schemas(P), IT, "Re", Re),
        AnsFE = (pred(V::in, FE::out) is semidet :-
            fe_of(P, "Ans", [arg("corr", av_string("c")), arg("v", av_int(V))],
                FE)),
        AnsFE(1i64, Copy1),
        AnsFE(2i64, Copy2),
        fe_of(P, "R", [arg("k", av_int(1i64)), arg("a", av_fact_ref(Copy1)),
            arg("b", av_fact_ref(Copy2))], RFE),
        body_of(RFE, RBody),
        fe_of(P, "D", [arg("k", av_int(1i64))], DFE),
        fe_of(P, "Rd", [arg("k", av_int(1i64)), arg("d", av_fact_ref(DFE)),
            arg("y", av_fact_ref(Copy2))], RdFE),
        body_of(RdFE, RdBody),
        fe_of(P, "CallError", [arg("corr", av_string("c")),
            arg("code", av_string("internal.bug")),
            arg("message", av_string("m")), arg("ts", av_int(0i64))], ErrFE),
        fe_of(P, "Re", [arg("k", av_int(1i64)), arg("a", av_fact_ref(Copy1)),
            arg("e", av_fact_ref(ErrFE))], ReFE),
        body_of(ReFE, ReBody)
    then
        engine_use_mock_clock(init_engine(P), E0),
        engine_intern("c", C, E0, E1),
        host_assert(Ans, [str(C), int(1i64)], no, First, Fx1, E1, E2),
        ( if First = inserted(X) then
            % A live answer, superseded by the delivery.
            assert_external(from_bytes(RBody), Live, Fx2, E2, L),
            check("[RFCS.23.7] a live target the delivery supersedes: it "
                ++ "asserts every node, and the slot names the gone fact",
                ( if
                    Live = ext_asserted,
                    facts_of_schema(engine_wm(L), Ans ^ s_id) = [Y],
                    Y ^ f_id \= X,
                    facts_of_schema(engine_wm(L), R ^ s_id) = [RF],
                    array.lookup(RF ^ f_slots, 1) = fact_ref(X),
                    not lookup_fact(engine_wm(L), X, _),
                    array.lookup(RF ^ f_slots, 2) = fact_ref(Y ^ f_id)
                  then yes else no ), !T, !IO),
            % And its recording replays ([RFCS.24.2]).
            replay_items(P, session_header(init_engine(P)),
                rfcs_ctx(engine_schemas(L), engine_interns(L)),
                record_items(0u64, Fx1 ++ Fx2), Replayed),
            check("[RFCS.24.2] the recording of it replays with the same "
                ++ "fact_ids",
                ( if
                    Replayed = yes({Steps, Again}),
                    not diverges(Steps),
                    engine_fact_count(Again) = engine_fact_count(L)
                  then yes else no ), !T, !IO),

            % A `CallError` in the new answer's place.
            assert_external(from_bytes(ReBody), Errored, _, E2, ER),
            check("[RFCS.23.7] a CallError that supersedes the target",
                ( if
                    Errored = ext_asserted,
                    facts_of_schema(engine_wm(ER), Ans ^ s_id) = [],
                    facts_of_schema(engine_wm(ER), Err ^ s_id) = [_],
                    facts_of_schema(engine_wm(ER), Re ^ s_id) = [ReF],
                    array.lookup(ReF ^ f_slots, 1) = fact_ref(X)
                  then yes else no ), !T, !IO),

            % A cascade: D derived from X alone, and X not in the record.
            pump(default_budget, _, E2, P1),
            ( if facts_of_schema(engine_wm(P1), D ^ s_id) = [DF] then
                assert_external(from_bytes(RdBody), Cascaded, _, P1, CF),
                check("[RFCS.23.7] a target the supersede's cascade removes",
                    ( if
                        Cascaded = ext_asserted,
                        facts_of_schema(engine_wm(CF), D ^ s_id) = [],
                        facts_of_schema(engine_wm(CF), Rd ^ s_id) = [RdF],
                        array.lookup(RdF ^ f_slots, 1) = fact_ref(DF ^ f_id),
                        not lookup_fact(engine_wm(CF), DF ^ f_id, _)
                      then yes else no ), !T, !IO)
            else
                check("[RFCS.23.7] the rule derives D from the answer", no,
                    !T, !IO)
            )
        else
            check("[RFCS.23.7] the live answer asserts", no, !T, !IO)
        ),

        % An inlined copy the delivery asserted and then superseded.
        assert_external(from_bytes(RBody), Inlined, _, E0, IN),
        check("[RFCS.23.7] an inlined copy the delivery superseded itself",
            ( if
                Inlined = ext_asserted,
                facts_of_schema(engine_wm(IN), Ans ^ s_id) = [Kept],
                facts_of_schema(engine_wm(IN), R ^ s_id) = [InF],
                array.lookup(InF ^ f_slots, 1) = fact_ref(Gone),
                not lookup_fact(engine_wm(IN), Gone, _),
                array.lookup(InF ^ f_slots, 2) = fact_ref(Kept ^ f_id)
              then yes else no ), !T, !IO)
    else
        check("[RFCS.23.7] 150_gone_target's records encode", no, !T, !IO)
    ).

    % KIND_NULL in a fact-reference slot is a reference with no target,
    % as libds's `test_rfcs_23_7__*` and `test_ncbk_10_4__a_root_null_*` pin.
    % The schemas are `151_no_target`'s.
    %
:- pred check_rfcs_23_7_no_target(program::in, tally::in, tally::out,
                                  io::di, io::uo) is det.

check_rfcs_23_7_no_target(P, !T, !IO) :-
    IT = interns(P),
    ( if
        find_schema(schemas(P), IT, "U", U),
        find_schema(schemas(P), IT, "F", F),
        find_schema(schemas(P), IT, "Fn", Fn),
        find_schema(schemas(P), IT, "Fk", Fk),
        find_schema(schemas(P), IT, "R", R),
        find_schema(schemas(P), IT, "Rn", Rn),
        find_schema(schemas(P), IT, "Rk", Rk),
        find_schema(schemas(P), IT, "Rr", Rr),
        find_schema(schemas(P), IT, "Rrn", Rrn),
        find_schema(schemas(P), IT, "Rrk", Rrk)
    then
        test_rfcs_23_7_a_no_target_copy_inlined_twice(P, F, Rr, "F", "Rr",
            !T, !IO),
        test_rfcs_23_7_a_no_target_copy_inlined_twice(P, Fn, Rrn, "Fn", "Rrn",
            !T, !IO),
        test_rfcs_23_7_a_replay_of_a_gone_nested_target(P, U, F, R, "F", !T,
            !IO),
        test_rfcs_23_7_a_replay_of_a_gone_nested_target(P, U, Fn, Rn, "Fn",
            !T, !IO),
        test_rfcs_23_7_null_elsewhere_stays_refused(P, !T, !IO),
        test_rfcs_23_7_no_target_copy_against_a_live_slot(P, U, F, Fn, R, Rn,
            !T, !IO),
        test_rfcs_23_7_a_no_target_key(P, U, Fk, Rk, !T, !IO),
        test_rfcs_23_7_two_copies_of_one_no_target_key(P, Fk, Rrk, !T, !IO),
        test_rfcs_23_7_received_no_target_is_a_no_op(P, U, F, !T, !IO),
        test_ncbk_10_4_a_root_null_json_field_is_refused(P, !T, !IO)
    else
        check("[RFCS.23.7] 151_no_target declares its schemas", no, !T, !IO)
    ).

    % A live `Schema` fact, k 1, whose reference's target has gone.
    %
:- pred no_target_gone(schema::in, schema::in, fact_id::out, fact_id::out,
                       list(effect)::out, engine::in, engine::out) is semidet.

no_target_gone(U, Schema, UId, Id, Effects, !E) :-
    host_assert(U, [int(1i64)], no, inserted(UId), Fx1, !E),
    host_assert(Schema, [int(1i64), fact_ref(UId)], no, inserted(Id), Fx2, !E),
    host_retract(UId, Fx3, !E),
    Effects = Fx1 ++ Fx2 ++ Fx3.

    % `Outer`'s record, k 1, inlining `Inner` with its reference as KIND_NULL.
    %
:- pred no_target_body(program::in, string::in, string::in, list(int)::out)
    is semidet.

no_target_body(P, Inner, Outer, Body) :-
    fe_of(P, Inner, [arg("k", av_int(1i64)), arg("u", av_null)], I),
    fe_of(P, Outer, [arg("k", av_int(1i64)), arg("f", av_fact_ref(I))], O),
    body_of(O, Body).

    % @spec [RFCS.23.7]
    % @spec [RFCS.24.2]
    % A run a host makes: `U`, a fact referring to it, the `U` retracted, and an
    % outer fact referring to the first. It records as an ExternalAssert
    % inlining the first with KIND_NULL, and replays with the same ids and no
    % second copy. Path: `bracket_external` -> `slot_arg_value` on the way in,
    % `plan_field`'s `kind_null` arm -> `live_equal_fact` on replay.
    %
:- pred test_rfcs_23_7_a_replay_of_a_gone_nested_target(program::in,
    schema::in, schema::in, schema::in, string::in, tally::in, tally::out,
    io::di, io::uo) is det.

test_rfcs_23_7_a_replay_of_a_gone_nested_target(P, U, Inner, Outer, What, !T,
        !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        no_target_gone(U, Inner, _, FId, Fx1, E0, E1),
        host_assert(Outer, [int(1i64), fact_ref(FId)], no, inserted(OId), Fx2,
            E1, L)
    then
        replay_items(P, session_header(init_engine(P)),
            rfcs_ctx(engine_schemas(L), engine_interns(L)),
            record_items(0u64, Fx1 ++ Fx2), Replayed),
        check("[RFCS.24.2] a gone nested target replays, with no second copy: "
                ++ What,
            ( if
                Replayed = yes({Steps, Again}),
                not diverges(Steps),
                facts_of_schema(engine_wm(Again), Inner ^ s_id) = [AF],
                AF ^ f_id = FId,
                facts_of_schema(engine_wm(Again), Outer ^ s_id) = [AO],
                AO ^ f_id = OId,
                array.lookup(AO ^ f_slots, 1) = fact_ref(FId)
              then yes else no ), !T, !IO)
    else
        check("[RFCS.24.2] the gone-target run asserts: " ++ What, no, !T, !IO)
    ).

    % @spec [RFCS.23.7]
    % @spec [NCBK.10.4]
    % The control: KIND_NULL in a non-nullable `Int` slot stays a mismatch.
    % Path: `plan_field`'s `kind_null` arm, past its `k_schema` branch.
    %
:- pred test_rfcs_23_7_null_elsewhere_stays_refused(program::in, tally::in,
    tally::out, io::di, io::uo) is det.

test_rfcs_23_7_null_elsewhere_stays_refused(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        fe_of(P, "Num", [arg("k", av_int(1i64)), arg("i", av_null)], FE),
        body_of(FE, Body),
        fe_of(P, "Num", [arg("k", av_int(1i64)), arg("i", av_int(5i64))], OkFE),
        body_of(OkFE, OkBody)
    then
        assert_external(from_bytes(Body), Res, _, E0, E1),
        check("[RFCS.23.7] KIND_NULL in an Int slot stays a mismatch",
            ( if Res = ext_refused(xr_slot_type_mismatch),
                 engine_fact_count(E1) = 0
              then yes else no ), !T, !IO),
        assert_external(from_bytes(OkBody), OkRes, _, E0, _),
        check("[RFCS.23.7] and the same record with an Int is admitted",
            ( if OkRes = ext_asserted then yes else no ), !T, !IO)
    else
        check("[RFCS.23.7] the Num records encode", no, !T, !IO)
    ).

    % @spec [RFCS.23.7]
    % A copy with KIND_NULL against a live slot that is null and one whose
    % target has gone, the same fact, and one whose target is live, not the same
    % fact: step 3 refuses. With nothing live the copy is asserted, referring to
    % no fact. Path: `resolve` -> `live_equal` -> `live_no_target`, and
    % `key_taken` -> `live_key_eq`.
    %
:- pred test_rfcs_23_7_no_target_copy_against_a_live_slot(program::in,
    schema::in, schema::in, schema::in, schema::in, schema::in,
    tally::in, tally::out, io::di, io::uo) is det.

test_rfcs_23_7_no_target_copy_against_a_live_slot(P, U, F, Fn, R, Rn, !T,
        !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        no_target_body(P, "F", "R", ToF),
        no_target_body(P, "Fn", "Rn", ToFn),
        host_assert(Fn, [int(1i64), null], no, inserted(NullId), _, E0, N1),
        no_target_gone(U, F, _, GoneF, _, E0, G1),
        no_target_gone(U, Fn, _, GoneFn, _, E0, H1),
        host_assert(U, [int(1i64)], no, inserted(LiveU), _, E0, L0),
        host_assert(F, [int(1i64), fact_ref(LiveU)], no, inserted(_), _, L0, L1)
    then
        assert_external(from_bytes(ToFn), ResN, _, N1, N2),
        check("[RFCS.23.7] a copy with no target is a live fact's null slot",
            ( if
                ResN = ext_asserted,
                facts_of_schema(engine_wm(N2), Fn ^ s_id) = [_],
                facts_of_schema(engine_wm(N2), Rn ^ s_id) = [NR],
                array.lookup(NR ^ f_slots, 1) = fact_ref(NullId)
              then yes else no ), !T, !IO),
        assert_external(from_bytes(ToF), ResG, _, G1, G2),
        check("[RFCS.23.7] a copy with no target is a live gone slot: F",
            ( if
                ResG = ext_asserted,
                facts_of_schema(engine_wm(G2), F ^ s_id) = [_],
                facts_of_schema(engine_wm(G2), R ^ s_id) = [GR],
                array.lookup(GR ^ f_slots, 1) = fact_ref(GoneF)
              then yes else no ), !T, !IO),
        assert_external(from_bytes(ToFn), ResH, _, H1, H2),
        check("[RFCS.23.7] a copy with no target is a live gone slot: Fn",
            ( if
                ResH = ext_asserted,
                facts_of_schema(engine_wm(H2), Fn ^ s_id) = [_],
                facts_of_schema(engine_wm(H2), Rn ^ s_id) = [HR],
                array.lookup(HR ^ f_slots, 1) = fact_ref(GoneFn)
              then yes else no ), !T, !IO),
        assert_external(from_bytes(ToF), ResL, _, L1, L2),
        check("[RFCS.23.7] a copy with no target is not a live target's fact",
            ( if
                ResL = ext_refused(xr_fact_ref_conflict),
                facts_of_schema(engine_wm(L2), R ^ s_id) = []
              then yes else no ), !T, !IO),
        assert_external(from_bytes(ToF), ResF, _, E0, F1),
        check("[RFCS.23.7] with nothing live the copy refers to no fact",
            ( if
                ResF = ext_asserted,
                facts_of_schema(engine_wm(F1), F ^ s_id) = [Copy],
                array.lookup(Copy ^ f_slots, 1) = fact_ref(make_fact_id(0u64)),
                facts_of_schema(engine_wm(F1), R ^ s_id) = [FR],
                array.lookup(FR ^ f_slots, 1) = fact_ref(Copy ^ f_id)
              then yes else no ), !T, !IO)
    else
        check("[RFCS.23.7] the no-target copies' runs", no, !T, !IO)
    ).

    % @spec [RFCS.23.7]
    % One no-target copy inlined twice, as a publisher's fact holding both slots
    % on one fact whose target has gone writes it, with nothing live here: one
    % copy is asserted, and both slots refer to it. Path: `equal_earlier` ->
    % `pair_value`.
    %
:- pred test_rfcs_23_7_a_no_target_copy_inlined_twice(program::in, schema::in,
    schema::in, string::in, string::in, tally::in, tally::out,
    io::di, io::uo) is det.

test_rfcs_23_7_a_no_target_copy_inlined_twice(P, Inner, Outer, InnerName,
        OuterName, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        fe_of(P, InnerName, [arg("k", av_int(1i64)), arg("u", av_null)], I),
        fe_of(P, OuterName, [arg("k", av_int(1i64)), arg("a", av_fact_ref(I)),
            arg("b", av_fact_ref(I))], O),
        body_of(O, Body)
    then
        assert_external(from_bytes(Body), Res, _, E0, E1),
        check("[RFCS.23.7] one no-target copy inlined twice is one fact: "
                ++ InnerName,
            ( if
                Res = ext_asserted,
                facts_of_schema(engine_wm(E1), Inner ^ s_id) = [Copy],
                facts_of_schema(engine_wm(E1), Outer ^ s_id) = [Got],
                array.lookup(Got ^ f_slots, 1) = fact_ref(Copy ^ f_id),
                array.lookup(Got ^ f_slots, 2) = fact_ref(Copy ^ f_id)
              then yes else no ), !T, !IO)
    else
        check("[RFCS.23.7] the twice-inlined record encodes: " ++ InnerName, no,
            !T, !IO)
    ).

    % @spec [RFCS.23.7]
    % A no-target slot in a key: equal to a live key whose target has gone, in
    % step 1 and in step 3's identity comparison, and not to a live key whose
    % target is live. Path: `live_equal_fact`, and `live_key_eq`'s
    % `pv_no_target` clause.
    %
:- pred test_rfcs_23_7_a_no_target_key(program::in, schema::in, schema::in,
    schema::in, tally::in, tally::out, io::di, io::uo) is det.

test_rfcs_23_7_a_no_target_key(P, U, Fk, Rk, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    Keyed = (pred(V::in, Id::out, E::out) is semidet :-
        host_assert(U, [int(1i64)], no, inserted(UId), _, E0, E1),
        host_assert(Fk, [fact_ref(UId), int(V)], no, inserted(Id), _, E1, E2),
        host_retract(UId, _, E2, E)),
    ( if
        fe_of(P, "Fk", [arg("u", av_null), arg("v", av_int(1i64))], I),
        fe_of(P, "Rk", [arg("k", av_int(1i64)), arg("f", av_fact_ref(I))], O),
        body_of(O, Body),
        Keyed(1i64, SameId, Same0),
        Keyed(2i64, _, Other0),
        host_assert(U, [int(1i64)], no, inserted(LiveU), _, E0, L0),
        host_assert(Fk, [fact_ref(LiveU), int(1i64)], no, inserted(_), _, L0,
            Live0)
    then
        assert_external(from_bytes(Body), ResS, _, Same0, Same1),
        check("[RFCS.23.7] a no-target key is a live key whose target has gone",
            ( if
                ResS = ext_asserted,
                facts_of_schema(engine_wm(Same1), Fk ^ s_id) = [_],
                facts_of_schema(engine_wm(Same1), Rk ^ s_id) = [SR],
                array.lookup(SR ^ f_slots, 1) = fact_ref(SameId)
              then yes else no ), !T, !IO),
        assert_external(from_bytes(Body), ResO, _, Other0, Other1),
        check("[RFCS.23.7] with values that differ, step 3 refuses it",
            ( if
                ResO = ext_refused(xr_fact_ref_conflict),
                facts_of_schema(engine_wm(Other1), Rk ^ s_id) = []
              then yes else no ), !T, !IO),
        assert_external(from_bytes(Body), ResL, _, Live0, Live1),
        check("[RFCS.23.7] and a live target's key is another's",
            ( if
                ResL = ext_asserted,
                facts_of_schema(engine_wm(Live1), Fk ^ s_id) = [_, _]
              then yes else no ), !T, !IO)
    else
        check("[RFCS.23.7] the no-target key's runs", no, !T, !IO)
    ).

    % @spec [RFCS.23.7]
    % One record inlining two copies of `Fk` whose key slots are both KIND_NULL:
    % with different `v` the key is the earlier copy's, with values that differ,
    % so step 3 refuses and nothing is asserted. The control: with one `v` the
    % second copy is the first, so the refusal is the differing value's. As
    % libds's `test_rfcs_23_7__two_copies_of_one_no_target_key` pins. Path:
    % `key_taken`'s planned arm -> `planned_key_eq`'s `pv_no_target` clause.
    %
:- pred test_rfcs_23_7_two_copies_of_one_no_target_key(program::in, schema::in,
    schema::in, tally::in, tally::out, io::di, io::uo) is det.

test_rfcs_23_7_two_copies_of_one_no_target_key(P, Fk, Rrk, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    Copy = (pred(V::in, FE::out) is semidet :-
        fe_of(P, "Fk", [arg("u", av_null), arg("v", av_int(V))], FE)),
    Record = (pred(A::in, B::in, Body::out) is semidet :-
        fe_of(P, "Rrk", [arg("k", av_int(1i64)), arg("a", av_fact_ref(A)),
            arg("b", av_fact_ref(B))], O),
        body_of(O, Body)),
    ( if
        Copy(1i64, One),
        Copy(2i64, Two),
        Record(One, Two, Differ),
        Record(One, One, Same)
    then
        assert_external(from_bytes(Differ), ResD, _, E0, E1),
        check("[RFCS.23.7] two copies of one no-target key that differ conflict",
            ( if
                ResD = ext_refused(xr_fact_ref_conflict),
                engine_fact_count(E1) = 0
              then yes else no ), !T, !IO),
        assert_external(from_bytes(Same), ResS, _, E0, E2),
        check("[RFCS.23.7] and two that do not are one fact",
            ( if
                ResS = ext_asserted,
                facts_of_schema(engine_wm(E2), Fk ^ s_id) = [C],
                facts_of_schema(engine_wm(E2), Rrk ^ s_id) = [Got],
                array.lookup(Got ^ f_slots, 1) = fact_ref(C ^ f_id),
                array.lookup(Got ^ f_slots, 2) = fact_ref(C ^ f_id)
              then yes else no ), !T, !IO)
    else
        check("[RFCS.23.7] the two-copy records encode", no, !T, !IO)
    ).

    % @spec [RFCS.23.7]
    % The received fact itself holding KIND_NULL, against a live fact whose
    % target has gone: a no-op reassertion, whose slot keeps what it named.
    % Path: `plan_node`'s top arm -> `top_no_target`.
    %
:- pred test_rfcs_23_7_received_no_target_is_a_no_op(program::in, schema::in,
    schema::in, tally::in, tally::out, io::di, io::uo) is det.

test_rfcs_23_7_received_no_target_is_a_no_op(P, U, F, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        fe_of(P, "F", [arg("k", av_int(1i64)), arg("u", av_null)], FE),
        body_of(FE, Body),
        no_target_gone(U, F, UId, FId, _, E0, E1)
    then
        assert_external(from_bytes(Body), Res, _, E1, E2),
        check("[RFCS.23.7] a received fact with no target is a no-op",
            ( if
                Res = ext_asserted,
                facts_of_schema(engine_wm(E2), F ^ s_id) = [Stands],
                Stands ^ f_id = FId,
                array.lookup(Stands ^ f_slots, 1) = fact_ref(UId)
              then yes else no ), !T, !IO)
    else
        check("[RFCS.23.7] the no-op's run", no, !T, !IO)
    ).

    % @spec [NCBK.10.4]
    % A Json field's document that is null at its root is a mismatch in a
    % non-nullable slot and in a `Json?`, and nothing is asserted. Path:
    % `plan_field`'s `kind_json` arm.
    %
:- pred test_ncbk_10_4_a_root_null_json_field_is_refused(program::in,
    tally::in, tally::out, io::di, io::uo) is det.

test_ncbk_10_4_a_root_null_json_field_is_refused(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        fe_of(P, "Doc", [arg("body", av_json("null"))], DocFE),
        body_of(DocFE, DocBody),
        fe_of(P, "DocN", [arg("body", av_json("null"))], NullableFE),
        body_of(NullableFE, NullableBody)
    then
        assert_external(from_bytes(DocBody), DocRes, _, E0, E1),
        check("[NCBK.10.4] a root-null Json field: a non-nullable slot",
            ( if DocRes = ext_refused(xr_slot_type_mismatch),
                 engine_fact_count(E1) = 0
              then yes else no ), !T, !IO),
        assert_external(from_bytes(NullableBody), NullableRes, _, E0, E2),
        check("[NCBK.10.4] a root-null Json field: a Json? slot",
            ( if NullableRes = ext_refused(xr_slot_type_mismatch),
                 engine_fact_count(E2) = 0
              then yes else no ), !T, !IO)
    else
        check("[NCBK.10.4] the root-null records encode", no, !T, !IO)
    ).

    % The one-character string of the code point `N`.
    %
:- func ctl_char(int) = string.

ctl_char(N) = string.char_to_string(char.det_from_int(N)).

    % The bytes with the one at `At` past the first match of `Pattern` set to
    % zero. A field's tag and length lead the pattern, so it names one field.
    %
:- pred patch_nul(list(int)::in, int::in, list(int)::in, list(int)::out)
    is semidet.

patch_nul(Pattern, At, Bytes0, Bytes) :-
    patch_byte(Pattern, At, 0, Bytes0, Bytes).

    % The bytes with the one at `At` past the first match of `Pattern` set to
    % `Value`.
    %
:- pred patch_byte(list(int)::in, int::in, int::in, list(int)::in,
                   list(int)::out) is semidet.

patch_byte(Pattern, At, Value, Bytes0, Bytes) :-
    ( if list.append(Pattern, _, Bytes0) then
        list.split_list(At, Bytes0, Keep, [_ | Tail]),
        Bytes = Keep ++ [Value | Tail]
    else
        Bytes0 = [B | Rest],
        patch_byte(Pattern, At, Value, Rest, Bytes1),
        Bytes = [B | Bytes1]
    ).

    % @spec [NCBK.10.4]
    % Text that is not well-formed UTF-8, at any depth, refuses the record as
    % DS_ERR_PARSE with no effects and nothing asserted, as libds's
    % `test_ncbk_10_4__ill_formed_text_is_a_parse_refusal` pins. A lone 0xFF
    % is planted in the encoded bytes, since no Mercury string holds one.
    % Path: `assert_external_with` -> `decode_fact_external` ->
    % `ds.wire.reader_string`, whose failure is `ext_refused(xr_parse)`.
    %
:- pred test_ncbk_10_4_ill_formed_text(program::in, engine::in,
                                       tally::in, tally::out,
                                       io::di, io::uo) is det.

test_ncbk_10_4_ill_formed_text(P, B0, !T, !IO) :-
    NoteField = [0x2A, 0x05, 0x68, 0x65, 0x5A, 0x6C, 0x6F],
    ( if
        ref_fe(P, "r1", "heZlo", RefFE),
        body_of(RefFE, RefBody),
        patch_byte(NoteField, 4, 0xFF, RefBody, RefBad),
        main_body(P, 1i64, "r1", "heZlo", arg("x", av_float(2.5)), MainBody),
        patch_byte(NoteField, 4, 0xFF, MainBody, MainBad),
        doc_body(P, "12345", DocBody),
        patch_byte([0x3A, 0x05, 0x31, 0x32, 0x33, 0x34, 0x35], 4, 0xFF,
            DocBody, DocBad)
    then
        check_ill_formed("the received fact's String", RefBad, B0, !T, !IO),
        check_ill_formed("an inlined copy's String", MainBad, B0, !T, !IO),
        check_ill_formed("a Json field's text", DocBad, B0, !T, !IO),
        % Each record unpatched is admitted, so each refusal above is its
        % planted byte's.
        check_well_formed("Ref", RefBody, 1, B0, !T, !IO),
        check_well_formed("Main and its inlined Ref", MainBody, 2, B0,
            !T, !IO),
        check_well_formed("Doc", DocBody, 1, B0, !T, !IO)
    else
        check("[NCBK.10.4] the ill-formed records encode and patch", no, !T,
            !IO)
    ).

    % @spec [NFCT.2.3]
    % @spec [NFCT.2.11]
    % A reference to a live fact of a schema other than its slot's is refused,
    % with no effects and nothing asserted, at step 4: ahead of a NaN in a later
    % slot, and behind a kind mismatch in an earlier one. As libds's
    % `test_nfct_2_3__a_reference_of_another_schema_is_a_mismatch` pins. The
    % control: the same assert naming a `Ref` is admitted, so the refusal is
    % the target's. Path: `host_assert` -> `host_assert_core` ->
    % `slot_ref_fault`, `nfct_2_3_refused_target`.
    %
:- pred test_nfct_2_3_wrong_target(program::in, engine::in,
                                   tally::in, tally::out,
                                   io::di, io::uo) is det.

test_nfct_2_3_wrong_target(P, B0, !T, !IO) :-
    ( if
        find_schema(schemas(P), interns(P), "Ref", Ref),
        find_schema(schemas(P), interns(P), "Tag", Tag),
        find_schema(schemas(P), interns(P), "Main", Main)
    then
        engine_intern("r1", R1, B0, E1),
        engine_intern("note", Note, E1, E2),
        engine_intern("t", TagName, E2, E3),
        host_assert(Ref, [str(R1), str(Note)], no, RefResult, _, E3, E4),
        host_assert(Tag, [str(TagName)], no, TagResult, _, E4, E5),
        ( if RefResult = inserted(RefId), TagResult = inserted(TagId) then
            NaN = float(float.infinity - float.infinity),
            Refused = (pred(What::in, Values::in, Index::in, Tin::in, Tout::out,
                    IOin::di, IOout::uo) is det :-
                host_assert(Main, Values, no, Result, Effects, E5, E6),
                check("[NFCT.2.3] " ++ What ++ ": a mismatch, nothing happens",
                    ( if
                        Result = invalid(Index, sr_kind_mismatch),
                        not list.member(eff_event(_), Effects),
                        engine_fact_count(E6) = 2
                      then yes else no ), Tin, Tout, IOin, IOout)
            ),
            Refused("a reference of another schema",
                [int(1i64), fact_ref(TagId), float(1.0)], 1, !T, !IO),
            Refused("the reference ahead of a NaN in a later slot",
                [int(1i64), fact_ref(TagId), NaN], 1, !T, !IO),
            Refused("a kind mismatch in an earlier slot ahead of the reference",
                [str(Note), fact_ref(TagId), float(1.0)], 0, !T, !IO),
            host_assert(Main, [int(1i64), fact_ref(RefId), float(1.0)], no,
                Good, _, E5, E7),
            check("[NFCT.2.3] a reference of the slot's schema is admitted",
                ( if Good = inserted(_), engine_fact_count(E7) = 3
                  then yes else no ), !T, !IO)
        else
            check("[NFCT.2.3] the Ref and Tag facts assert", no, !T, !IO)
        )
    else
        check("[NFCT.2.3] the fixture declares Ref, Tag and Main", no, !T, !IO)
    ).

    % @spec [NFCT.2.3]
    % @spec [NFCT.2.11]
    % A reference that names no live fact is refused, with no effects and
    % nothing asserted, at step 4: a fact that was retracted and an id never
    % issued, and ahead of a NaN in a later slot. The control: the same assert
    % naming the fact while it is live is admitted, so the refusal is the
    % target's death, and retracting the target afterwards leaves the
    % referring fact live. Path: `host_assert` -> `host_assert_core` ->
    % `slot_ref_fault`, `nfct_2_3_refused_target`.
    %
:- pred test_nfct_2_3_dead_target(program::in, engine::in,
                                  tally::in, tally::out,
                                  io::di, io::uo) is det.

test_nfct_2_3_dead_target(P, B0, !T, !IO) :-
    ( if
        find_schema(schemas(P), interns(P), "Ref", Ref),
        find_schema(schemas(P), interns(P), "Main", Main)
    then
        engine_intern("r1", R1, B0, E1),
        engine_intern("note", Note, E1, E2),
        host_assert(Ref, [str(R1), str(Note)], no, RefResult, _, E2, E3),
        ( if RefResult = inserted(RefId) then
            host_retract(RefId, _, E3, Dead),
            Never = make_fact_id(fact_id_value(RefId) + 1000000u64),
            NaN = float(float.infinity - float.infinity),
            Refused = (pred(What::in, Values::in, Tin::in, Tout::out,
                    IOin::di, IOout::uo) is det :-
                host_assert(Main, Values, no, Result, Effects, Dead, After),
                check("[NFCT.2.3] " ++ What ++ ": a mismatch, nothing happens",
                    ( if
                        Result = invalid(1, sr_kind_mismatch),
                        Effects = [],
                        engine_fact_count(After) = 0
                      then yes else no ), Tin, Tout, IOin, IOout)
            ),
            Refused("a reference to a retracted fact",
                [int(1i64), fact_ref(RefId), float(1.0)], !T, !IO),
            Refused("a reference to an id never issued",
                [int(1i64), fact_ref(Never), float(1.0)], !T, !IO),
            Refused("the dead reference ahead of a NaN in a later slot",
                [int(1i64), fact_ref(RefId), NaN], !T, !IO),
            host_assert(Main, [int(1i64), fact_ref(RefId), float(1.0)], no,
                Good, _, E3, E4),
            ( if Good = inserted(MainId) then
                check("[NFCT.2.3] the same reference is admitted while it lives",
                    ( if engine_fact_count(E4) = 2 then yes else no ), !T, !IO),
                host_retract(RefId, _, E4, E5),
                check("[NFCT.2.3] a target that leaves does not undo the assert",
                    ( if
                        not lookup_fact(engine_wm(E5), RefId, _),
                        lookup_fact(engine_wm(E5), MainId, _)
                      then yes else no ), !T, !IO)
            else
                check("[NFCT.2.3] the same reference is admitted while it lives",
                    no, !T, !IO)
            )
        else
            check("[NFCT.2.3] the Ref fact asserts", no, !T, !IO)
        )
    else
        check("[NFCT.2.3] the fixture declares Ref and Main", no, !T, !IO)
    ).

    % @spec [IDAT.3.3.10]
    % `parse_path` admits what libds's `json_path` production admits, so a path
    % is read the same way by both runtimes' rule-side walks. The compiler
    % writes only well-formed paths, so no vector reaches a refusal.
    %
:- pred test_idat_3_3_10_path_grammar(tally::in, tally::out,
                                      io::di, io::uo) is det.

test_idat_3_3_10_path_grammar(!T, !IO) :-
    Good = ["a", "a.b", "a[0]", "[0].a", "a[0][1]", "a[01]"],
    Bad = ["", ".a", "a..b", "a.", "a[0]b", "a[ 1]", "a[-0]", "a[+1]", "a[]",
        "a[1", "a.[0]"],
    check("[IDAT.3.3.10] parse_path admits every well-formed path",
        ( if list.all_true((pred(S::in) is semidet :- parse_path(S, _)), Good)
          then yes else no ), !T, !IO),
    check("[IDAT.3.3.10] parse_path refuses every malformed path",
        ( if list.all_false((pred(S::in) is semidet :- parse_path(S, _)), Bad)
          then yes else no ), !T, !IO),
    ds.json_text.parse("{\"a\":[1,2]}", Parsed),
    check("[IDAT.3.3.10] an index past every integer is a miss, not a wrap",
        ( if
            Parsed = parsed(Doc),
            parse_path("a[1]", Hit),
            resolve(Hit, Doc, _),
            parse_path("a[99999999999999999999999]", Past),
            not resolve(Past, Doc, _)
          then yes else no ), !T, !IO).

    % [NCBK.10.4]: a value over its slot's `capacity`, a malformed
    % `TimeZoneOffset` and a TTL deadline out of range, each in a copy after
    % another, refuse the whole record, as libds's
    % `test_ncbk_10_4__a_value_over_capacity_refuses_the_record` and its two
    % siblings. Over capacity is here a record whose hash is the receiver's
    % own: `capacity` is outside `schema_hash` ([RFCS.23.3]), so a publisher's
    % bytes look the same. Path: `ds.fact_receive.plan_judged`, before
    % `input_step_begin`, so no tick and no event, and no `BoundsError`.
    %
    %@spec [NCBK.10.4]
:- pred check_ncbk_10_4_plan_refusals(program::in, tally::in, tally::out,
                                      io::di, io::uo) is det.

check_ncbk_10_4_plan_refusals(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    Max = uint64.cast_from_int64(int64.max_int64),
    set_clock(from_ns(Max - 1000000000u64), _, E0, ETop),
    Line = ( func(Text) = [arg("k", av_int(1i64)), arg("text", av_string(Text))] ),
    Zone = ( func(Offset) = [arg("zone", av_string("Europe/London")),
        arg("valid_from", av_int(0i64)), arg("valid_until", av_int(100i64)),
        arg("offset_s", av_int(Offset))] ),
    Lease = [arg("id", av_string("l1"))],
    ( if
        held_body(P, "WithLine", "Line", Line("four"), LongLine),
        held_body(P, "WithLine", "Line", Line("abc"), ShortLine),
        held_body(P, "WithZone", "TimeZoneOffset", Zone(64801i64), BadZone),
        held_body(P, "WithZone", "TimeZoneOffset", Zone(3600i64), GoodZone),
        held_body(P, "WithLease", "Lease", Lease, Leased)
    then
        check_plan_refused("a value over capacity", LongLine,
            xr_contract_breach, E0, !T, !IO),
        check_plan_admitted("a value at capacity", ShortLine, E0, !T, !IO),
        check_plan_refused("a malformed TimeZoneOffset", BadZone, xr_inval,
            E0, !T, !IO),
        check_plan_admitted("a good TimeZoneOffset", GoodZone, E0, !T, !IO),
        check_plan_refused("a TTL deadline past the top", Leased,
            xr_time_range, ETop, !T, !IO),
        check_plan_admitted("the same Lease at 0", Leased, E0, !T, !IO)
    else
        check("[NCBK.10.4] 152_plan_refusals' records encode", no, !T, !IO)
    ).

    % `Holder(1, -> Ref("r1", "hello"), -> Inner(Fields))`.
    %
:- pred held_body(program::in, string::in, string::in, list(arg)::in,
                  list(int)::out) is semidet.

held_body(P, Holder, Inner, Fields, Body) :-
    ref_fe(P, "r1", "hello", RefFE),
    fe_of(P, Inner, Fields, InnerFE),
    fe_of(P, Holder, [arg("k", av_int(1i64)), arg("a", av_fact_ref(RefFE)),
        arg("b", av_fact_ref(InnerFE))], FE),
    body_of(FE, Body).

:- pred check_plan_refused(string::in, list(int)::in, external_refusal::in,
                           engine::in, tally::in, tally::out,
                           io::di, io::uo) is det.

check_plan_refused(What, Body, Want, E0, !T, !IO) :-
    assert_external_with(from_bytes(Body), no, Result, Ids, Effects, E0, E1),
    check("[NCBK.10.4] " ++ What ++ " refuses the record: no fact, no sample, "
            ++ "no event",
        ( if
            Result = ext_refused(Want),
            Ids = [],
            Effects = [],
            engine_fact_count(E1) = engine_fact_count(E0),
            engine_event_count(E1) = engine_event_count(E0)
          then yes else no ), !T, !IO).

:- pred check_plan_admitted(string::in, list(int)::in, engine::in, tally::in,
                            tally::out, io::di, io::uo) is det.

check_plan_admitted(What, Body, E0, !T, !IO) :-
    assert_external_with(from_bytes(Body), no, Result, _, _, E0, E1),
    check("[NCBK.10.4] " ++ What ++ " is admitted, all three facts",
        ( if Result = ext_asserted, engine_fact_count(E1) = 3
          then yes else no ), !T, !IO).

    % [LIMP.13.3]: a library's schema and a program's of the same name and
    % shape are two schemas, as libds's
    % `test_limp_13_3__a_program_schema_is_not_a_librarys`. The artefacts are
    % built by hand, so each names its schema as a compile gives a library's
    % and a program's. Path: `ds.fact_receive.receivable`, which finds a
    % record's schema by its whole name.
    %
    %@spec [LIMP.13.3]
:- pred check_limp_13_3_a_program_schema_is_not_a_librarys(tally::in,
    tally::out, io::di, io::uo) is det.

check_limp_13_3_a_program_schema_is_not_a_librarys(!T, !IO) :-
    Holding = ( func(Name) = sealed(dsco_frame ++ Atoms) :-
        Bytes = list.map(char.to_int, string.to_char_list(Name)),
        Named = [0x0A, list.length(Bytes)] ++ Bytes,
        Atoms = frame(299, Named ++ [0x18, 0x01])
            ++ frame(257, Named ++ [0x12, 0x01, 0x74, 0x18, 0x02]) ),
    ( if
        load_dsc(Holding("lib.Reply"), loaded(Sender)),
        load_dsc(Holding("Reply"), loaded(Mine)),
        fe_of(Sender, "lib.Reply", [arg("t", av_float(1.0))], FE),
        body_of(FE, Body)
    then
        engine_use_mock_clock(init_engine(Mine), C0),
        assert_external_with(from_bytes(Body), no, Refused, Ids, Effects, C0, C1),
        check("[LIMP.13.3] a program's Reply is not lib.Reply: nothing asserted",
            ( if
                Refused = ext_refused(xr_schema_unknown),
                Ids = [],
                Effects = [],
                engine_fact_count(C1) = 0
              then yes else no ), !T, !IO),
        engine_use_mock_clock(init_engine(Sender), K0),
        assert_external_with(from_bytes(Body), no, Admitted, _, _, K0, K1),
        check("[LIMP.13.3] the control: a receiver holding lib.Reply admits it",
            ( if Admitted = ext_asserted, engine_fact_count(K1) = 1
              then yes else no ), !T, !IO)
    else
        check("[LIMP.13.3] the artefacts load and the record encodes", no, !T, !IO)
    ).

    % [RFCS.24.2]: an assert's own halt stops a delivery part-way, and the
    % recording replays, as libds's
    % `test_rfcs_24_2__a_delivery_halted_part_way_replays`. "S" has an
    % AlphaTest naming no slot of it ([RDSC.4a.9.1]), and `M` refers to an
    % `S`, so the record's first assert, the copy of S, raises ARTEFACT_LIED,
    % and M is never asserted. A compiled program cannot lie this way, so the
    % artefact is built by hand, as `test_rdsc_4a_9_1_index_faults`'s is.
    % Path: `ds.fact_receive.assert_plan`'s `ext_stopped`, then
    % `ds.replay.replay_external`, which reads it as an outcome.
    %
    %@spec [RFCS.24.2]
:- pred check_rfcs_24_2_halted_part_way(tally::in, tally::out,
                                        io::di, io::uo) is det.

check_rfcs_24_2_halted_part_way(!T, !IO) :-
    Bad = [0x08, 0x01, 0x10, 0x01, 0x18, 0x03, 0x22, 0x02, 0x08, 42],
    SchemaM = frame(299, [0x0A, 0x01, 0x4D, 0x18, 0x01])
        ++ frame(257, [0x0A, 0x01, 0x4D, 0x12, 0x01, 0x72, 0x18, 0x06,
            0x22, 0x01, 0x53]),
    Alfa = frame(268, alpha_with_tests([Bad])),
    Beta = [0x0A, 0x07, 0xEA, 0x10, 0x04, 0x08, 0x02, 0x10, 0x01],
    Term = [0x0A, 0x0A, 0xF2, 0x10, 0x07, 0x08, 0x03, 0x10, 0x02,
        0x1A, 0x01, 0x52],
    ( if
        load_dsc(sealed(dsco_frame ++ network_schema_s ++ SchemaM ++ Alfa
            ++ Beta ++ Term), loaded(P)),
        fe_of(P, "S", [arg("t", av_float(1.0))], SFE),
        fe_of(P, "M", [arg("r", av_fact_ref(SFE))], MFE),
        body_of(MFE, Body)
    then
        engine_use_mock_clock(init_engine(P), E0),
        assert_external_with(from_bytes(Body), no, Result, Ids, Effects, E0, E),
        check("[RFCS.24.2] the copy's assert halts, and the record's own fact "
                ++ "is not asserted",
            ( if
                Result = ext_stopped(refused_halted(_)),
                Ids = [_],
                engine_errors(Effects) = [_],
                engine_halted(E) = yes(_),
                engine_fact_count(E) = 1
              then yes else no ), !T, !IO),
        Meta = session_header(init_engine(P)),
        encode_recording(Meta, rfcs_ctx(engine_schemas(E), engine_interns(E)),
            engine_now(E0), prelude_seeds(E), record_items(0u64, Effects),
            Bytes, _),
        decode_stream(from_bytes(list.map(uint8.cast_to_int, Bytes)),
            init_interns, Decoded),
        ( if Decoded = decoded(DS) then
            check("[RFCS.24.2] the recording holds the delivery, its fact_ids "
                    ++ "the one fact asserted before the halt",
                ( if
                    DS ^ dsm_external = [X],
                    X ^ re_fact_ids = list.map(fact_id_value, Ids)
                  then yes else no ), !T, !IO),
            engine_use_mock_clock(init_engine(P), F0),
            replay_stream(P, DS, RSteps, F0, F),
            check("[RFCS.24.2] the recording replays: no divergence",
                ( if
                    list.find_first_match(
                        (pred(S::in) is semidet :- S = diverged(_)), RSteps, _)
                  then no else yes ), !T, !IO),
            check("[RFCS.24.2] the replay re-derives the halt",
                ( if engine_halted(F) = yes(_) then yes else no ), !T, !IO)
        else
            check("[RFCS.24.2] the recording decodes", no, !T, !IO)
        )
    else
        check("[RFCS.24.2] the artefact loads and the record encodes", no, !T,
            !IO)
    ).

:- pred check_ill_formed(string::in, list(int)::in, engine::in, tally::in,
                         tally::out, io::di, io::uo) is det.

check_ill_formed(What, Bytes, B0, !T, !IO) :-
    assert_external_with(from_bytes(Bytes), no, Result, Ids, Effects, B0, B1),
    check("[NCBK.10.4] ill-formed UTF-8 in " ++ What
            ++ ": parse, no effects, nothing asserted",
        ( if
            Result = ext_refused(xr_parse),
            Ids = [],
            Effects = [],
            engine_fact_count(B1) = 0
          then yes else no ), !T, !IO).

:- pred check_well_formed(string::in, list(int)::in, int::in, engine::in,
                          tally::in, tally::out, io::di, io::uo) is det.

check_well_formed(What, Bytes, WantFacts, B0, !T, !IO) :-
    assert_external_with(from_bytes(Bytes), no, Result, _, Effects, B0, B1),
    check("[NCBK.10.4] " ++ What ++ " with no ill-formed byte is admitted",
        ( if
            Result = ext_asserted,
            Effects = [_ | _],
            engine_fact_count(B1) = WantFacts
          then yes else no ), !T, !IO).

:- pred check_external_refused(bitmap::in, external_refusal::in, string::in,
                               program::in, tally::in, tally::out,
                               io::di, io::uo) is det.

check_external_refused(Bytes, Want, Name, P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    assert_external(Bytes, Result, _, E0, E1),
    check("assert_external " ++ Name,
        ( if Result = ext_refused(Want), engine_fact_count(E1) = 0
          then yes else no ), !T, !IO).

    % Not called. Every fixture here opens with `use ... (realtime)` and
    % sizes its caps through a sibling `.dsrt`; the compiler refuses that
    % `use` line with DS_VALIDATE_REALTIME_DEFERRED, so none has a `.dsc`.
    %
:- pred test_realtime_fixtures(tally::in, tally::out, io::di, io::uo) is det.

test_realtime_fixtures(!T, !IO) :-
    with_fixture("79_capbreach.dsc", check_wm_cap, !T, !IO),
    with_fixture("cap_cache_cap.dsc", check_cache_seed_cap, !T, !IO),
    with_fixture("cap_node_alpha.dsc", check_alpha_cap, !T, !IO),
    with_fixture("cap_node_beta.dsc", check_beta_cap, !T, !IO),
    with_fixture("cap_node_term.dsc", check_term_cap, !T, !IO),
    with_fixture("cap_node_term.dsc", check_term_cap_survives_firing, !T, !IO),
    with_fixture("cap_node_term.dsc", check_term_cap_falls_on_retract,
        !T, !IO),
    with_fixture("cap_cache_vs_bytes.dsc", check_cache_cap_order, !T, !IO),
    with_fixture("cap_agenda_cap.dsc", check_agenda_cap, !T, !IO),
    with_fixture("cap_agenda_cap.dsc", check_agenda_cap_falls_on_firing,
        !T, !IO),
    with_fixture("cap_term_vs_agenda.dsc", check_agenda_beats_terminal,
        !T, !IO),
    check_realtime_contract(!T, !IO).

    % [NFCT.1.1]: "A schema reaches the engine from a compiled artefact, and
    % in no other way." A schema the engine does not hold reaching
    % `host_assert` is refused there, whenever it is tried. The schema is well
    % formed and its slots are right, so the refusal is its own arm rather
    % than `invalid`.
    %
% @spec [RFCS.6.7]
:- pred check_unregistered_schema(program::in, tally::in, tally::out,
                                  io::di, io::uo) is det.

check_unregistered_schema(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Sensor", Known) then
        engine_intern("dev1", Dev, E0, E1),
        host_assert(Known, [str(Dev), float(1.0)], no, KnownResult, _, E1, E2),
        check("a schema the artefact declared is asserted",
            ( if KnownResult = inserted(_) then yes else no ), !T, !IO),

        % The same shape under a name this artefact never declared.
        engine_intern("Stranger", StrangerRef, E2, E3),
        Stranger = (Known ^ s_name := make_schema_name(StrangerRef)),
        host_assert(Stranger, [str(Dev), float(1.0)], no, StrangerResult, _,
            E3, E4),
        check("[NFCT.1.1] a schema the engine does not hold is refused",
            ( if StrangerResult = refused_unregistered(_) then yes else no ),
            !T, !IO),

        check("[NFCT.1.1] and the refusal changed nothing",
            ( if engine_fact_count(E4) = engine_fact_count(E2) then yes
              else no ), !T, !IO),

        % [RFCS.6.7]: a host call that is not a well-formed input records
        % nothing. Tried as the first call on a fresh engine, where a consumed
        % input would record its TICK; the refusal comes before `clock_step`.
        engine_intern("Stranger", FirstRef, E0, F1),
        FirstStranger = (Known ^ s_name := make_schema_name(FirstRef)),
        engine_intern("dev1", FirstDev, F1, F2),
        host_assert(FirstStranger, [str(FirstDev), float(1.0)], no,
            FirstResult, FirstFx, F2, _),
        check("[RFCS.6.7] an unknown schema's assert records nothing",
            ( if
                FirstResult = refused_unregistered(_),
                FirstFx = []
              then yes else no ), !T, !IO),

        % [NFCT.2.2]: one value per slot. `Sensor` has two; a row of
        % one and a row of three are refused with the slot count and the
        % number given, and neither enters.
        host_assert(Known, [str(Dev)], no, ShortResult, _, E4, E5),
        check("[NFCT.2.2] a row shorter than the schema is refused",
            ( if ShortResult = refused_arity(2, 1) then yes else no ),
            !T, !IO),
        host_assert(Known, [str(Dev), float(1.0), float(2.0)], no,
            LongResult, _, E5, E6),
        check("[NFCT.2.2] a row longer than the schema is refused",
            ( if LongResult = refused_arity(2, 3) then yes else no ),
            !T, !IO),
        check("[NFCT.2.2] and neither refusal changed anything",
            ( if engine_fact_count(E6) = engine_fact_count(E2) then yes
              else no ), !T, !IO)
    else
        check("[NFCT.1.1] the fixture declares `Sensor`", no, !T, !IO)
    ).

    % [NSTG.9.1], on `53_cached`, whose `writer` rule caches `42` under
    % "counter". A seed and a rule's write store the same bytes, as `libds.h`
    % states for `ds_engine_cache_seed`. The comparison is on the store, not
    % through `read_hit`: `cached()` answers a String, which its Int slot
    % `got` refuses (`30_cached`).
    %
:- pred check_cache_seed(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_cache_seed(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    seed_cache("counter", j_int(42i64), no, R1, E0, E1),
    check("[IARC.12.1] a seed before the first pump is taken",
        ( if R1 = seeded then yes else no ), !T, !IO),
    ( if find_schema(schemas(P), interns(P), "Trig", Trig) then
        host_assert(Trig, [int(1i64)], no, _, _, E0, W1),
        seed_cache("after_assert", j_int(1i64), no, RA, W1, WA),
        check("[NLFC.9.1] a seed after the first stream event, before any "
            ++ "pump, is refused, changing nothing",
            ( if
                RA = seed_after_pump,
                not cached_text(WA, "after_assert", _)
              then yes else no ), !T, !IO),
        pump(default_budget, _, W1, E3),
        check("[IARC.12.1] a seed stores what the rule's write stores",
            ( if
                cached_text(E1, "counter", Seeded),
                cached_text(E3, "counter", Written),
                Seeded = Written, Seeded = "42"
              then yes else no ), !T, !IO),
        seed_cache("late", j_int(1i64), no, R2, E3, E4),
        check("[NLFC.9.1] a seed after the first pump is refused, "
            ++ "changing nothing",
            ( if R2 = seed_after_pump, engine_now(E4) = engine_now(E3)
              then yes else no ), !T, !IO)
    else
        check("[IARC.12.1] the fixture declares `Trig`", no, !T, !IO)
    ),
    seed_cache("inf", j_array([j_float(float.infinity)]), no, R3, E0, _),
    check("[IARC.12.1] a non-finite Float is refused, as "
        ++ "DS_ERR_JSON_NONFINITE",
        ( if R3 = seed_nonfinite then yes else no ), !T, !IO).

    % The cache bound is engine configuration, `set_cache_cap`, as libds's
    % `ds_engine_set_cache_cap` ([NDET.8.1]), on `53_cached`, a bundle with no
    % contract. With one key allowed and one seeded, `writer`'s write of a
    % second key is refused: a breach naming `cache_cap`, no `cache_set`, the
    % cache unchanged. The control is the same run with no bound, where the
    % write lands.
    %
% @spec [LSTO.4.7.5] [NSTG.2.6.1]
:- pred check_set_cache_cap(program::in, tally::in, tally::out,
                            io::di, io::uo) is det.

check_set_cache_cap(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    set_cache_cap(1u32, 0u64, E0, B0),
    seed_cache("other", j_int(1i64), no, R1, B0, B1),
    seed_cache("more", j_int(2i64), no, R2, B1, _),
    check("set_cache_cap: a seed within the bound it gives is taken",
        ( if R1 = seeded then yes else no ), !T, !IO),
    check("set_cache_cap: a seed past it is refused, with no contract loaded",
        ( if R2 = seed_capped(cap_cache) then yes else no ), !T, !IO),
    ( if find_schema(schemas(P), interns(P), "Trig", Trig) then
        host_assert(Trig, [int(1i64)], no, _, _, B1, B2),
        pump(default_budget, Bounded, B2, B3),
        check("set_cache_cap: a rule's write past the bound is refused as "
                ++ "cache_cap",
            ( if list.member(eff_event(se_engine_error(Err, _)), Bounded),
                 Err = ee_contract_breach(cap_cache)
              then yes else no ), !T, !IO),
        check("set_cache_cap: ...records no cache_set, and leaves the key "
                ++ "unwritten",
            ( if
                not (
                    list.member(Effect, Bounded),
                    Effect = eff_event(se_cache_set(_, _, _))
                ),
                not cached_text(B3, "counter", _)
              then yes else no ), !T, !IO),
        % The pump returns the breach, as libds's `ds_engine_pump` returns the
        % DS_ERR_CONTRACT_BREACH `bridge_cache_set` stashes
        % (test_ldet_2_7_config_precondition.c, test_rfcs_replay.c).
        check("set_cache_cap: the pump whose rule breached the bound returns "
                ++ "it, naming cache_cap",
            ( if first_pump_status(Bounded) = yes(ps_contract_breach(cap_cache))
              then yes else no ),
            !T, !IO),

        host_assert(Trig, [int(1i64)], no, _, _, E0, U1),
        pump(default_budget, Unbounded, U1, U2),
        check("set_cache_cap control: unbounded, the same write lands",
            ( if
                list.member(Written, Unbounded),
                Written = eff_event(se_cache_set(_, _, _)),
                cached_text(U2, "counter", "42")
              then yes else no ), !T, !IO),
        check("set_cache_cap control: a pump that breaches nothing has no "
                ++ "status",
            ( if first_pump_status(Unbounded) = no then yes else no ),
            !T, !IO)
    else
        check("set_cache_cap: the fixture declares `Trig`", no, !T, !IO)
    ).

    % A cached `String` is [IDSP.13.4]'s `String` row, libds's `jt_string`.
    % `keep` caches a `String` holding U+0008, U+000C and U+0001, and the
    % text is `"\u0008\u000c\u0001"`, where a `Json` value writes the same
    % characters as `"\b\f\u0001"` ([LGRA.5.8.7a], `ds.format.json_string`).
    % Path: `ds.exec`'s `cache_set_verb` -> `cache_value` ->
    % `json_value_text` -> `json_scalar`'s `str` arm ->
    % `ds.format.string_value_json`.
    %
:- pred check_cache_string_text(program::in, tally::in, tally::out,
                                io::di, io::uo) is det.

check_cache_string_text(P, !T, !IO) :-
    Value = ctl_char(8) ++ ctl_char(12) ++ ctl_char(1),
    ( if find_schema(schemas(P), interns(P), "S", S) then
        engine_use_mock_clock(init_engine(P), E0),
        engine_intern(Value, Ref, E0, E1),
        host_assert(S, [int(1i64), str(Ref)], no, _, _, E1, E2),
        pump(default_budget, _, E2, E3),
        check("cached String: U+0008 U+000C U+0001 are \\u00xx",
            ( if cached_text(E3, "s", "\"\\u0008\\u000c\\u0001\"")
              then yes else no ), !T, !IO),
        check("cached String: ...and a Json value's strings keep \\b and \\f",
            ( if
                ds.format.json_text(j_string(Value), "\"\\b\\f\\u0001\"")
              then yes else no ), !T, !IO)
    else
        check("cached String: the fixture declares `S`", no, !T, !IO)
    ).

    % The Json text an engine's cache holds under a key.
    %
:- pred cached_text(engine::in, string::in, string::out) is semidet.

cached_text(E, Key, Text) :-
    cache_get(engine_cache(E), Key, str(Ref)),
    expand(engine_interns(E), Ref, Text).

    % `cap_cache_cap.dsrt` sets `cache_cap: 1`: a seed counts against it as a
    % rule's write does.
    %
:- pred check_cache_seed_cap(program::in, tally::in, tally::out,
                             io::di, io::uo) is det.

check_cache_seed_cap(P, !T, !IO) :-
    E0 = init_engine(P),
    seed_cache("one", j_int(1i64), no, R1, E0, E1),
    seed_cache("two", j_int(1i64), no, R2, E1, E2),
    seed_cache("one", j_int(2i64), no, R3, E2, _),
    check("[RTCT.7.1] the seed within cache_cap is taken",
        ( if R1 = seeded then yes else no ), !T, !IO),
    check("[RTCT.7.1] the seed past cache_cap is refused",
        ( if R2 = seed_capped(cap_cache) then yes else no ), !T, !IO),
    check("[RTCT.7.1] an existing key is an upsert, not a new key",
        ( if R3 = seeded then yes else no ), !T, !IO).

    % `ds.format.json_text` against libds's `ds_json_serialize`: keys in byte
    % order, no whitespace, its escape table.
    %
:- pred check_json_text(tally::in, tally::out, io::di, io::uo) is det.

check_json_text(!T, !IO) :-
    Doc = j_object(object(["b" - j_int(-1i64),
        "a" - j_array([j_float(1.5), j_null, j_bool(yes)]),
        "\"q\"" - j_string("tab\tnl\n\x01\")])),
    check("json_text writes libds's canonical form",
        ( if json_text(Doc, Text),
             Text = "{\"\\\"q\\\"\":\"tab\\tnl\\n\\u0001\","
                ++ "\"a\":[1.5,null,true],\"b\":-1}"
          then yes else no ), !T, !IO),
    check("json_text refuses a non-finite Float",
        ( if json_text(j_float(float.infinity), _) then no else yes ),
        !T, !IO),
    % [LGRA.5.8.8]: `unsigned_zeros` makes every float zero +0.0, at
    % any depth, and leaves a nonzero negative and an Int zero alone. Signs
    % are read with `negative_zero`, since `=` cannot tell the zeros apart.
    Zeros0 = j_object(object([
        "a" - j_array([j_float(neg_zero)]),
        "b" - j_object(object(["c" - j_float(neg_zero)])),
        "d" - j_float(-1.5),
        "e" - j_int(0i64)])),
    Zeros = unsigned_zeros(Zeros0),
    check("[LGRA.5.8.8] the input's zeros are negative",
        ( if
            resolve([key("a"), index(0)], Zeros0, j_float(A0)),
            negative_zero(A0),
            resolve([key("b"), key("c")], Zeros0, j_float(C0)),
            negative_zero(C0)
          then yes else no ), !T, !IO),
    check("[LGRA.5.8.8] unsigned_zeros folds a zero in an array and an object",
        ( if
            resolve([key("a"), index(0)], Zeros, j_float(A)),
            A = 0.0, not negative_zero(A),
            resolve([key("b"), key("c")], Zeros, j_float(C)),
            C = 0.0, not negative_zero(C)
          then yes else no ), !T, !IO),
    check("[LGRA.5.8.8] unsigned_zeros keeps -1.5 and Int 0",
        ( if
            resolve([key("d")], Zeros, j_float(D)), D = -1.5,
            resolve([key("e")], Zeros, j_int(0i64))
          then yes else no ), !T, !IO).

    % [RDSC.14.2], [RDSC.14.3], [RDSC.6.7] on `07_action_verbs`, one module
    % whose one rule is declared on line 14 of the file and line 15 of what
    % was compiled: the fixture has no `use` line, so the corpus build
    % supplies `use default` ahead of it ([LDIA.2.10.1]), and the DsSource text and every position are the
    % compiled text's.
    %
:- pred check_source_spans(program::in, tally::in, tally::out,
                           io::di, io::uo) is det.

check_source_spans(P, !T, !IO) :-
    ( if sources(P) = [Src] then
        check("[RDSC.14.2] the module's DsSource carries its path and text",
            ( if
                string.suffix(Src ^ src_file, "07_action_verbs.ds"),
                source_line(Src ^ src_text, 15, RuleLine),
                string.prefix(RuleLine, "rule fire_them_all")
              then yes else no ), !T, !IO),
        Spans = line_spans(P),
        check("[RDSC.14.3] every span is 1-based and in the one module",
            ( if
                Spans = [_ | _],
                list.all_true(
                    ( pred(S::in) is semidet :-
                        S ^ ls_line >= 1u32, S ^ ls_col >= 1u32,
                        S ^ ls_clip = Src ^ src_clip
                    ), Spans)
              then yes else no ), !T, !IO),
        check("[RDSC.14.3] every terminal resolves to a span in its rule",
            ( if
                list.all_true(
                    ( pred(Tn::in) is semidet :-
                        line_span_for(P, node_id_value(Tn ^ tn_id), Sp),
                        Sp ^ ls_line >= 15u32
                    ), terminal_nodes(network(P)))
              then yes else no ), !T, !IO),
        check("[RDSC.14.3] a node no LineSpan names has none",
            ( if line_span_for(P, 999999u32, _) then no else yes ), !T, !IO),
        check("[RDSC.6.7] the rule's RuleSource is line 15 of the same module",
            ( if
                rule_metas(P) = [M],
                M ^ rm_where = yes(source_pos(15u32, Col, Clip)),
                Col >= 1u32,
                source_file(P, Clip, File),
                File = Src ^ src_file
              then yes else no ), !T, !IO),
        % `Trig` is declared on line 3 of the file and `Alert` on line
        % 6, so lines 4 and 7 of what was compiled.
        check("[RDSC.5.7.1] each schema's SchemaSource is its declaration, in the module",
            ( if
                schema_source_for(P, "Trig", TrigAt),
                TrigAt ^ sp_line = 4u32, TrigAt ^ sp_col >= 1u32,
                schema_source_for(P, "Alert", AlertAt),
                AlertAt ^ sp_line = 7u32, AlertAt ^ sp_col >= 1u32,
                source_file(P, TrigAt ^ sp_clip, TrigFile),
                TrigFile = Src ^ src_file
              then yes else no ), !T, !IO),
        check("[RDSC.5.7.1] a builtin schema has no SchemaSource",
            ( if schema_source_for(P, "ComputationError", _) then no else yes ),
            !T, !IO)
    else
        check("[RDSC.14.2] 07_action_verbs carries one DsSource", no, !T, !IO)
    ).

    % The 1-based line `N` of a text.
    %
:- pred source_line(string::in, int::in, string::out) is semidet.

source_line(Text, N, Line) :-
    list.index1(string.split_at_char('\n', Text), N, Line).

    % [LTIM.1.1.3]: a `Time` written to a slot is stored as its UTC
    % nanoseconds, as libds writes it.
    %
:- pred check_time_slot(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_time_slot(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Alert", Alert) then
        engine_intern("hall", Hall, E0, E1),
        Zoned = time(ds_time(5000i64, 3600000000000i64)),
        host_assert(Alert, [Zoned, str(Hall)], no, Result, Effects, E1, E2),
        ( if Result = inserted(Id) then
            check("[LTIM.1.1.3] a Time in an Int slot stores its utc_ns",
                ( if lookup_fact(engine_wm(E2), Id, F),
                     array.to_list(F ^ f_slots) = [int(5000i64), str(Hall)]
                  then yes else no ), !T, !IO),
            check("[LTIM.1.1.3] and the assert event carries the same Int",
                ( if list.member(Effect, Effects),
                     Effect = eff_event(se_fact_assert(Id, _, Announced, _)),
                     Announced = [int(5000i64), str(Hall)]
                  then yes else no ), !T, !IO)
        else
            check("[LTIM.1.1.3] a Time is admitted into an Int slot", no,
                !T, !IO)
        )
    else
        check("[LTIM.1.1.3] the fixture declares `Alert`", no, !T, !IO)
    ).

    % [LTIM.2.8.5], [LFST.5.3]: a recording whose first event has seq 2, as
    % from a stream callback attached after a first pump took seq 0 and 1, is
    % refused, as libds refuses it with DS_ERR_FS_RECORDING_INCOMPLETE. Path:
    % `ds.rfcs.note_first_seq` and `ds.replay`'s check.
    %
:- pred check_late_recording_refused(program::in, tally::in, tally::out,
                                     io::di, io::uo) is det.

check_late_recording_refused(P, !T, !IO) :-
    Ctx = rfcs_ctx(schemas(P), interns(P)),
    Meta = stream_meta(ds.version.ds_version, [], [], [], "", ""),
    Late = [{make_seq(2u64), se_pump_boundary}],
    Whole = [{make_seq(0u64), se_clock_tick(from_ns(0u64), no)},
             {make_seq(1u64), se_pump_boundary}],
    encode_stream(Meta, Ctx, from_ns(0u64), Late, LateBytes, _),
    encode_stream(Meta, Ctx, from_ns(0u64), Whole, WholeBytes, _),
    ( if
        decode_stream(from_bytes(list.map(uint8.cast_to_int, LateBytes)),
            interns(P), decoded(LateDS)),
        decode_stream(from_bytes(list.map(uint8.cast_to_int, WholeBytes)),
            interns(P), decoded(WholeDS))
    then
        engine_use_mock_clock(init_engine(P), E0),
        replay_stream(P, LateDS, LateSteps, E0, _),
        replay_stream(P, WholeDS, WholeSteps, E0, _),
        check("[LTIM.2.8.5] a recording whose first event has seq 2 is "
            ++ "refused, and nothing is delivered",
            ( if LateSteps = [recording_incomplete(2u64)] then yes else no ),
            !T, !IO),
        check("[LFST.5.3] one whose first event has seq 0 replays",
            ( if
                WholeSteps = [_ | _],
                not list.member(recording_incomplete(_), WholeSteps)
              then yes else no ), !T, !IO)
    else
        check("both recordings decode", no, !T, !IO)
    ).

    % [RFCS.7.3], [RFCS.5.4]: a replay stops at a `FactRetract` of an unknown
    % `fact_id`, and at a `FactAssert` of a schema the engine does not hold,
    % wherever in the stream it falls. It delivers nothing after it, and the
    % step carries libds's code: -730 and -101.
    %
    % One run: Sensor A, then Sensor X, then Sensor B, then B retracted, each
    % step followed by a pump. Its recording, replayed:
    %   - as recorded: it replays;
    %   - with B's FactAssert taken out: the FactRetract names an id no
    %     earlier atom carries, partway through -- `unknown_fact_id`, last;
    %   - with every FactAssert taken out: the same, at the opening, with
    %     nothing delivered before it;
    %   - with X's FactAssert naming `Stranger`, a schema the prelude announces
    %     and the engine does not hold, after A was delivered --
    %     `unknown_schema`, last, and B is never delivered;
    %   - that, with A's FactAssert taken out: the same at the opening.
    % libds refuses the same recordings with DS_ERR_FS_UNKNOWN_FACT_ID and
    % DS_ERR_SCHEMA_UNKNOWN (test_rfcs_replay.c).
    %
    % `Stranger` is `Sensor` renamed, with the next schema id, as
    % `check_unregistered_schema` builds one; the recording is what names it
    % ([NFCT.1.1]).
    %
:- pred check_reader_refusals(program::in, tally::in, tally::out,
                              io::di, io::uo) is det.

check_reader_refusals(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), R1),
    ( if
        find_schema(schemas(P), interns(P), "Sensor", Sensor)
    then
        engine_intern("a", DevA, R1, R2),
        host_assert(Sensor, [str(DevA), float(1.0)], no, ResA, Fx1, R2, R3),
        pump(default_budget, Fx2, R3, R4),
        engine_intern("x", DevX, R4, R4a),
        host_assert(Sensor, [str(DevX), float(3.0)], no, ResX, Fx3, R4a, R5),
        pump(default_budget, Fx4, R5, R6),
        engine_intern("b", DevB, R6, R7),
        host_assert(Sensor, [str(DevB), float(2.0)], no, ResB, Fx5, R7, R8),
        pump(default_budget, Fx6, R8, R9),
        ( if
            ResA = inserted(IdA),
            ResX = inserted(IdX),
            ResB = inserted(IdB)
        then
            host_retract(IdB, Fx7, R9, R10),
            pump(default_budget, Fx8, R10, R11),
            Items = record_items(0u64,
                Fx1 ++ Fx2 ++ Fx3 ++ Fx4 ++ Fx5 ++ Fx6 ++ Fx7 ++ Fx8),
            Meta = session_header(init_engine(P)),
            Ctx = rfcs_ctx(engine_schemas(R11), engine_interns(R11)),
            engine_intern("Stranger", StrangerRef, R11, R12),
            % An id no schema has: one past the largest, as the ids need not
            % run 0..N-1. No `.proto` text or clip: Sensor's text names
            % Sensor.
            MaxId = list.foldl(
                ( func(S, M) = ( if V > M then V else M ) :-
                    V = schema_id_value(S ^ s_id) ),
                engine_schemas(R12), 0u32),
            StrangerId = make_schema_id(MaxId + 1u32),
            Stranger = ((((Sensor ^ s_name := make_schema_name(StrangerRef))
                ^ s_id := StrangerId) ^ s_module := no) ^ s_proto := no),
            StrangerCtx = rfcs_ctx(engine_schemas(R12) ++ [Stranger],
                engine_interns(R12)),
            StrangerItems = list.map(as_stranger(IdX, StrangerId), Items),
            engine_use_mock_clock(init_engine(P), Fresh),

            replay_items_into(Fresh, P, Meta, Ctx, Items, AsRecorded),
            check("[RFCS.7.3] the run's recording replays, refusing nothing",
                ( if
                    AsRecorded = yes(Steps0),
                    list.filter(step_refuses, Steps0) = []
                  then yes else no ), !T, !IO),

            replay_items_into(Fresh, P, Meta, Ctx,
                list.negated_filter(asserts(IdB), Items), NoB),
            check("[RFCS.7.3] a FactRetract of a fact_id no earlier atom "
                ++ "carries stops the replay there, partway through: "
                ++ "unknown_fact_id, the last step, -730",
                ( if
                    NoB = yes(StepsB),
                    list.last(StepsB, LastB),
                    LastB = unknown_fact_id(_),
                    replay_refusal_code(LastB) = -730,
                    list.filter(is_delivered, StepsB) = [_ | _]
                  then yes else no ), !T, !IO),

            replay_items_into(Fresh, P, Meta, Ctx,
                list.negated_filter(is_fact_assert, Items), NoAsserts),
            check("[RFCS.7.3] the same at the stream's opening, with nothing "
                ++ "delivered before it: -730",
                ( if
                    NoAsserts = yes(StepsO),
                    list.last(StepsO, LastO),
                    LastO = unknown_fact_id(_),
                    replay_refusal_code(LastO) = -730,
                    list.filter(is_delivered, StepsO) = []
                  then yes else no ), !T, !IO),

            replay_items_into(Fresh, P, Meta, StrangerCtx, StrangerItems,
                NoExtra),
            check("[RFCS.5.4] a FactAssert of a schema the engine does not "
                ++ "hold stops the replay there, partway through: "
                ++ "unknown_schema, the last step, -101, and nothing after it "
                ++ "is delivered",
                ( if
                    NoExtra = yes(StepsX),
                    list.last(StepsX, LastX),
                    LastX = unknown_schema(_),
                    replay_refusal_code(LastX) = -101,
                    list.length(list.filter(is_delivered, StepsX)) = 1
                  then yes else no ), !T, !IO),

            replay_items_into(Fresh, P, Meta, StrangerCtx,
                list.negated_filter(asserts(IdA), StrangerItems), NoA),
            check("[RFCS.5.4] the same at the stream's opening: -101",
                ( if
                    NoA = yes(StepsXO),
                    list.last(StepsXO, LastXO),
                    LastXO = unknown_schema(_),
                    replay_refusal_code(LastXO) = -101,
                    list.filter(is_delivered, StepsXO) = []
                  then yes else no ), !T, !IO),

            % [RFCS.5.4]'s first case: no SchemaDef announced the
            % schema ([RFCS.5.3]). Sensor's announcement is taken out of the
            % recording as recorded: the engine holds Sensor, the stream never
            % names it, and A's FactAssert opens the events. The reader stops
            % there, and the replay refuses it with nothing delivered.
            encode_recording(Meta, Ctx, from_ns(0u64), [], Items, AsBytes, _),
            unannounced_replay(Fresh, P, without_announcement("Sensor", AsBytes),
                NoSensor),
            check("[RFCS.5.4] a FactAssert of a schema the engine holds and no "
                ++ "SchemaDef announced: the reader stops at it, and the "
                ++ "replay refuses it, -101, nothing delivered",
                ( if
                    NoSensor = yes(StepsU),
                    list.last(StepsU, LastU),
                    LastU = unknown_schema(_),
                    replay_refusal_code(LastU) = -101,
                    list.filter(is_delivered, StepsU) = []
                  then yes else no ), !T, !IO),

            % And partway through: Stranger's announcement taken out, so A is
            % delivered and X's FactAssert, naming Stranger, is the one the
            % reader stops at. B is never delivered. The decode is
            % `unannounced_schema`, so the refusal is the reader's case and not
            % the engine's lookup above.
            encode_recording(Meta, StrangerCtx, from_ns(0u64), [],
                StrangerItems, StrangerBytes, _),
            unannounced_replay(Fresh, P,
                without_announcement("Stranger", StrangerBytes), NoStranger),
            check("[RFCS.5.4] the same partway through: A delivered, then "
                ++ "-101 at X's FactAssert, and nothing after it",
                ( if
                    NoStranger = yes(StepsUP),
                    list.last(StepsUP, LastUP),
                    LastUP = unknown_schema(_),
                    replay_refusal_code(LastUP) = -101,
                    list.length(list.filter(is_delivered, StepsUP)) = 1
                  then yes else no ), !T, !IO),

            % The control: the recording with its announcements in place
            % decodes whole.
            check("[RFCS.5.4] with its SchemaDef in place the recording reads "
                ++ "to its end",
                ( if
                    decode_stream(from_bytes(list.map(uint8.cast_to_int,
                        AsBytes)), init_interns, decoded(_))
                  then yes else no ), !T, !IO)
        else
            check("[RFCS.7.3] the run asserts its three facts", no, !T, !IO)
        )
    else
        check("[RFCS.7.3] the fixture declares `Sensor`", no, !T, !IO)
    ).

    % A recording the reader stops at an unannounced FactAssert, replayed into
    % the given engine as `ds.replay.replay_unannounced` replays one. `no`
    % for a recording that decodes otherwise -- whole, or refused -- so a
    % check reading `yes` knows the reader took [RFCS.5.4]'s first case.
    %
:- pred unannounced_replay(engine::in, program::in, list(uint8)::in,
                           maybe(list(replay_step))::out) is det.

unannounced_replay(E0, P, Bytes, Replayed) :-
    ( if
        decode_stream(from_bytes(list.map(uint8.cast_to_int, Bytes)),
            init_interns, unannounced_schema(DS, Seq, _))
    then
        replay_unannounced(P, DS, Seq, Steps, E0, _),
        Replayed = yes(Steps)
    else
        Replayed = no
    ).

    % `Bytes` without the `SchemaDef` and `Slot` atoms that announce `Name`,
    % every other atom as it was: RCTS.1.2.18's `drop_schema_def`, by this
    % module's own walk of the frames. Both atoms carry the schema's name in
    % field 1 (`schema_def.proto`, `slot.proto`).
    %
:- func without_announcement(string, list(uint8)) = list(uint8).

without_announcement(Name, Bytes) = list.condense(list.reverse(RevKept)) :-
    Frames = all_frames(init_reader(from_bytes(
        list.map(uint8.cast_to_int, Bytes)))),
    Starts = list.map((func(F) = F ^ fr_offset), Frames),
    ( if Starts = [_ | Later] then
        Ends = Later ++ [list.length(Bytes)]
    else
        Ends = []
    ),
    list.foldl_corresponding(keep_unless_announcing(Name, Bytes), Frames, Ends,
        [], RevKept).

:- pred keep_unless_announcing(string::in, list(uint8)::in, ds.atom.frame::in,
                               int::in, list(list(uint8))::in,
                               list(list(uint8))::out) is det.

keep_unless_announcing(Name, Bytes, F, End, !Kept) :-
    ( if
        ( F ^ fr_atom = known(at_schema_def)
        ; F ^ fr_atom = known(at_slot) ),
        fold_fields(F ^ fr_body, field_1_string, "", ff_ok(Name))
    then
        true
    else
        list.det_split_list(F ^ fr_offset, Bytes, _, From),
        list.take_upto(End - F ^ fr_offset, From, Frame),
        !:Kept = [Frame | !.Kept]
    ).

:- pred field_1_string(uint32::in, field_value::in, string::in, string::out)
    is semidet.

field_1_string(Num, Value, S0, S) :-
    ( if Num = 1u32 then
        Value = fv_bytes(R),
        reader_string(R, S)
    else
        S = S0
    ).

    % Every frame of a well-formed container, in order.
    %
:- func all_frames(reader) = list(ds.atom.frame).

all_frames(R0) = Frames :-
    next_frame(FR, R0, R1),
    ( if FR = fr_ok(F) then
        Frames = [F | all_frames(R1)]
    else
        Frames = []
    ).

    % The recorded FactAssert of `Id`, naming the schema `Schema` instead;
    % every other item as it was.
    %
:- func as_stranger(fact_id, schema_id, record_item) = record_item.

as_stranger(Id, Schema, Item0) = Item :-
    ( if Item0 = ri_event(Seq, se_fact_assert(Id, _, Values, Ttl)) then
        Item = ri_event(Seq, se_fact_assert(Id, Schema, Values, Ttl))
    else
        Item = Item0
    ).

    % As `replay_items`, into the given engine.
    %
:- pred replay_items_into(engine::in, program::in, stream_meta::in,
                          rfcs_ctx::in, list(record_item)::in,
                          maybe(list(replay_step))::out) is det.

replay_items_into(E0, P, Meta, Ctx, Items, Replayed) :-
    % Items made by hand: no engine was seeded, so no `CacheSeed`.
    encode_recording(Meta, Ctx, from_ns(0u64), [], Items, Bytes, _),
    ( if
        decode_stream(from_bytes(list.map(uint8.cast_to_int, Bytes)),
            init_interns, decoded(DS))
    then
        replay_stream(P, DS, Steps, E0, _),
        Replayed = yes(Steps)
    else
        Replayed = no
    ).

:- pred step_refuses(replay_step::in) is semidet.

step_refuses(Step) :-
    _ = replay_refusal_code(Step).

:- pred is_delivered(replay_step::in) is semidet.

is_delivered(delivered(_)).

:- pred asserts(fact_id::in, record_item::in) is semidet.

asserts(Id, ri_event(_, se_fact_assert(Id, _, _, _))).

:- pred is_fact_assert(record_item::in) is semidet.

is_fact_assert(ri_event(_, se_fact_assert(_, _, _, _))).

    % [RFCS.6.2], [RFCS.7.4]: a replayed host assert takes its recorded TTL,
    % and a TTL withdrawal is compared. The run asserts a `Sensor` with a 2 s
    % window at mock instant 0, an override the FactAssert's `ttl_ns`
    % carries, then sets the clock to 10 s and pumps: the fact is withdrawn,
    % `ttl`. Without the window, the replay asserts with the schema's own:
    % none, `logical`. libds's `ds_engine_assert_with_ttl` takes `ttl_ns`
    % (codec.c), and `verify_match` / `ds_rfcs_replay_finish` refuse a
    % missing and an extra compare atom with DS_ERR_FS_DIVERGENCE.
    %
:- pred check_replay_ttl_window(program::in, tally::in, tally::out,
                                io::di, io::uo) is det.

check_replay_ttl_window(P, !T, !IO) :-
    ( if find_schema(schemas(P), interns(P), "Sensor", Sensor) then
        engine_use_mock_clock(init_engine(P), E0),
        engine_intern("dev1", Dev, E0, E1),
        host_assert(Sensor, [str(Dev), float(1.0)],
            yes(from_ns(2000000000u64)), Result, Fx1, E1, E2),
        pump(default_budget, Fx2, E2, E3),
        set_clock(from_ns(10000000000u64), Fx3, E3, E4),
        pump(default_budget, Fx4, E4, E5),
        Items = record_items(0u64, Fx1 ++ Fx2 ++ Fx3 ++ Fx4),
        Meta = session_header(init_engine(P)),
        Ctx = rfcs_ctx(engine_schemas(E5), engine_interns(E5)),
        ( if Result = inserted(Id) then
            check("[RFCS.6.2] the run withdraws the fact at 10 s, `ttl`",
                ( if list.member(eff_event(se_fact_withdraw(Id, rc_ttl)), Fx4)
                  then yes else no ), !T, !IO),
            % [RFCS.6.7]: an input refused for a reason that is not a bound
            % ends the replay with its status, as libds's FactAssert arm does.
            % A recorded window past the `Time` range: DS_ERR_TIME_RANGE, and
            % nothing enters. Path: `replay_event` -> `rfcs_6_7_refused`.
            replay_items(P, Meta, Ctx, list.map(with_window_past_range, Items),
                Refused),
            check("[RFCS.6.7] a recorded assert the engine refuses ends the "
                ++ "replay with the refusal's status, and nothing enters",
                ( if
                    Refused = yes({RSteps, RF}),
                    list.last(RSteps, input_refused(_, -205, _)),
                    engine_fact_count(RF) = 0
                  then yes else no ), !T, !IO),
            replay_items(P, Meta, Ctx, Items, AsRecorded),
            check("[RFCS.6.2] a replayed FactAssert takes its recorded "
                ++ "ttl_ns: the replay withdraws the fact at 10 s and ends "
                ++ "with the run's facts",
                ( if
                    AsRecorded = yes({Steps, F}),
                    not diverges(Steps),
                    list.member(eff_event(se_fact_withdraw(Id, rc_ttl)),
                        list.condense(list.map(replay_step_effects, Steps))),
                    engine_fact_count(F) = engine_fact_count(E5)
                  then yes else no ), !T, !IO),
            replay_items(P, Meta, Ctx, list.map(without_window, Items),
                NoWindow),
            check("[RFCS.7.4] a recorded TTL withdrawal the replay does not "
                ++ "re-derive is a divergence",
                ( if NoWindow = yes({NWSteps, _}), diverges(NWSteps)
                  then yes else no ), !T, !IO),
            replay_items(P, Meta, Ctx,
                list.negated_filter(is_withdrawal, Items), NoWithdrawal),
            check("[LFST.9.3.1] a withdrawal the replay re-derives and the "
                ++ "recording does not hold is a divergence",
                ( if NoWithdrawal = yes({NDSteps, _}), diverges(NDSteps)
                  then yes else no ), !T, !IO),
            % The withdrawal recorded for another cause.
            ( if first_item(is_withdrawal, Items, W) then
                check_compare_atom(P, E5, "FactWithdraw", Items, W,
                    with_event(W, se_fact_withdraw(Id, rc_supersede)),
                    !T, !IO)
            else
                check("[RFCS.6.2] the recording holds the withdrawal", no,
                    !T, !IO)
            )
        else
            check("[RFCS.6.2] the run asserts its Sensor", no, !T, !IO)
        ),
        % [RFCS.6.7]: a window whose deadline, the sample plus the window,
        % would pass INT64_MAX is refused, DS_ERR_TIME_RANGE, as libds's
        % `test_nfct_2_6_1_ttl_range.c` asks. The clock is moved to 1 s first,
        % so the bound is the sum: INT64_MAX - 1 s is admitted and one
        % nanosecond more is refused. The call is not a step, so the check
        % comes before the sample ([LTIM.2.8.5]), and neither a TICK nor a
        % FactAssert is recorded.
        Max = uint64.cast_from_int64(int64.max_int64),
        Sec = 1000000000u64,
        Past = duration_from_ns(Max - Sec + 1u64),
        IsTick = (pred(Ev::in) is semidet :-
            Ev = eff_event(se_clock_tick(_, _))),
        IsAssert = (pred(Ev::in) is semidet :-
            Ev = eff_event(se_fact_assert(_, _, _, _))),
        engine_use_mock_clock(init_engine(P), R0),
        advance(duration_from_ns(Sec), _, R0, R1),
        engine_intern("dev1", RDev, R1, R2),
        host_assert_with_ttl(Sensor, [str(RDev), float(1.0)], Past,
            Over, OverFx, R2, R3),
        check("[RFCS.6.7] a TTL deadline past INT64_MAX is refused before "
            ++ "the step: no TICK, and nothing is asserted",
            ( if
                Over = refused_ttl_range,
                engine_fact_count(R3) = 0,
                not list.any_true(IsTick, OverFx),
                not list.any_true(IsAssert, OverFx)
              then yes else no ), !T, !IO),
        % A value the schema does not admit is refused in libds's argument
        % check, before the sample and so before the range check: `invalid`,
        % whatever the window, and no TICK. From R2, where a sample would
        % record one.
        host_assert_with_ttl(Sensor, [str(RDev), str(RDev)], Past,
            Bad, BadFx, R2, _),
        check("[NFCT.2.11] a value the schema does not admit is refused as "
            ++ "invalid before the TTL range is asked, and samples nothing",
            ( if
                Bad = invalid(_, _),
                not list.any_true(IsTick, BadFx)
              then yes else no ), !T, !IO),
        host_assert_with_ttl(Sensor, [str(RDev), float(1.0)],
            duration_from_ns(Max - Sec), AtMax, _, R3, _),
        check("[RFCS.6.7] a deadline reaching exactly INT64_MAX is admitted",
            ( if AtMax = inserted(_) then yes else no ), !T, !IO)
    else
        check("[RFCS.6.2] the fixture declares `Sensor`", no, !T, !IO)
    ).

    % Encode `Items` as a recording, read it back, and replay it into a fresh
    % mock-clocked engine. `no` if the recording does not decode.
    %
:- pred replay_items(program::in, stream_meta::in, rfcs_ctx::in,
                     list(record_item)::in,
                     maybe({list(replay_step), engine})::out) is det.

replay_items(P, Meta, Ctx, Items, Replayed) :-
    % Items made by hand: no engine was seeded, so no `CacheSeed`.
    encode_recording(Meta, Ctx, from_ns(0u64), [], Items, Bytes, _),
    ( if
        decode_stream(from_bytes(list.map(uint8.cast_to_int, Bytes)),
            init_interns, decoded(DS))
    then
        engine_use_mock_clock(init_engine(P), F0),
        replay_stream(P, DS, Steps, F0, F),
        Replayed = yes({Steps, F})
    else
        Replayed = no
    ).

:- pred diverges(list(replay_step)::in) is semidet.

diverges(Steps) :-
    list.find_first_match((pred(S::in) is semidet :- S = diverged(_)), Steps,
        _).

    % A recorded assert with a TTL window no deadline can hold.
    %
:- func with_window_past_range(record_item) = record_item.

with_window_past_range(Item) =
    ( if Item = ri_event(S, se_fact_assert(I, Sc, Vs, _)) then
        ri_event(S, se_fact_assert(I, Sc, Vs, yes(duration_from_ns(
            uint64.cast_from_int64(int64.max_int64) + 1u64))))
    else
        Item
    ).

:- func without_window(record_item) = record_item.

without_window(Item) =
    ( if Item = ri_event(S, se_fact_assert(I, Sc, Vs, yes(_))) then
        ri_event(S, se_fact_assert(I, Sc, Vs, no))
    else
        Item
    ).

:- pred is_withdrawal(record_item::in) is semidet.

is_withdrawal(ri_event(_, se_fact_withdraw(_, _))).

    % [LFST.9.6], [LFST.9.3.1]: a replay compares every compare-class atom,
    % as libds's does: `RuleFireAnnotation`, `CallIssued`, `FactEmit`,
    % `BoundsError` and `FactWithdraw`.
    %
    % Each run is recorded, and the recording replayed into a fresh engine
    % three ways (`check_compare_atom`): as recorded, which replays clean;
    % with one compare-class record altered, which parts from the recording
    % at that record's `seq`; and with it taken out, which parts from the
    % recording, because the replay re-derives an atom the recording does
    % not hold. libds's `verify_match` and `ds_rfcs_replay_finish` refuse both
    % with DS_ERR_FS_DIVERGENCE (`codec.c`).
    %
    % A record is altered as the recorder sees it, as an event, so the atom it
    % writes differs and no other atom changes:
    %   - RuleFireAnnotation: the last firing's end names the first firing;
    %   - FactEmit: the first emit written as a publish, so a `FactPublish`
    %     stands where the FactEmit was ([RFCS.27.1]);
    %   - CallIssued: the call fire-and-forget, so no `correlation`;
    %   - BoundsError: the refusal's cap named `wm_max`;
    %   - FactWithdraw (`check_replay_ttl_window`): another cause.
    %
    % And [LFST.9.2.1]: a `pump_wcet_ns` BoundsError is observed time, left
    % uncompared, so a recording holding one the replay does not re-derive
    % replays clean (`check_replay_compare_bounds`).
    %
:- pred check_replay_compare_cascade(program::in, tally::in, tally::out,
                                     io::di, io::uo) is det.

check_replay_compare_cascade(P, !T, !IO) :-
    ( if find_schema(schemas(P), interns(P), "Trigger", Trig) then
        engine_use_mock_clock(init_engine(P), E0),
        host_assert(Trig, [int(1i64)], no, _, Fx1, E0, E1),
        pump(default_budget, Fx2, E1, E2),
        Items = record_items(0u64, Fx1 ++ Fx2),
        ( if
            first_item(is_fire_begin, Items,
                ri_event(_, se_fire_begin(First))),
            last_item(is_fire_end, Items, LastEnd)
        then
            check_compare_atom(P, E2, "RuleFireAnnotation", Items, LastEnd,
                with_event(LastEnd, se_fire_end(First)), !T, !IO)
        else
            check("[LFST.9.6] 30_cascade's rules fire", no, !T, !IO)
        ),
        ( if
            first_item(is_emit, Items, Emit),
            Emit = ri_event(_, se_emit(_, Schema))
        then
            check_compare_atom(P, E2, "FactEmit", Items, Emit,
                with_event(Emit, se_publish(Schema, [], no)), !T, !IO)
        else
            check("[LFST.9.6] 30_cascade's rules emit", no, !T, !IO)
        )
    else
        check("[LFST.9.6] the fixture declares `Trigger`", no, !T, !IO)
    ).

:- pred check_replay_compare_call(program::in, tally::in, tally::out,
                                  io::di, io::uo) is det.

check_replay_compare_call(P, !T, !IO) :-
    ( if find_schema(schemas(P), interns(P), "Reading", Reading) then
        engine_use_mock_clock(init_engine(P), E0),
        engine_intern("kitchen", Zone, E0, E1),
        host_assert(Reading, [int(1i64), str(Zone), int(7i64)], no, _, Fx1,
            E1, E2),
        pump(default_budget, Fx2, E2, E3),
        Items = record_items(0u64, Fx1 ++ Fx2),
        ( if
            first_item(is_call_issued, Items, Call),
            Call = ri_event(_, se_call_issued(Fire, Service, correlated(_),
                Args, Origin))
        then
            % Every call carries a correlation ([LCRS.3.1]), so the altered
            % atom carries another one rather than none.
            engine_intern("not-this-call", Other, E3, E4),
            check_compare_atom(P, E4, "CallIssued", Items, Call,
                with_event(Call, se_call_issued(Fire, Service,
                    correlated(Other), Args, Origin)), !T, !IO)
        else
            check("[LFST.9.6] 43_interp_call's rule calls, correlated", no,
                !T, !IO)
        )
    else
        check("[LFST.9.6] the fixture declares `Reading`", no, !T, !IO)
    ).

:- pred check_replay_compare_bounds(program::in, tally::in, tally::out,
                                    io::di, io::uo) is det.

check_replay_compare_bounds(P, !T, !IO) :-
    ( if find_schema(schemas(P), interns(P), "Line", Line) then
        engine_use_mock_clock(init_engine(P), E0),
        engine_intern("too long", Text, E0, E1),
        host_assert(Line, [int(1i64), str(Text)], no, _, Fx1, E1, E2),
        pump(default_budget, Fx2, E2, E3),
        Items = record_items(0u64, Fx1 ++ Fx2),
        ( if
            first_item(is_bounds_error, Items, Refusal),
            Refusal = ri_event(_, se_engine_error(_, Site))
        then
            check_compare_atom(P, E3, "BoundsError", Items, Refusal,
                with_event(Refusal,
                    se_engine_error(ee_contract_breach(cap_wm_max), Site)),
                !T, !IO),
            Wcet = ri_event(make_seq(past_last_item(Items)),
                se_engine_error(ee_contract_breach(cap_pump_wcet), Site)),
            replay_items(P, session_header(init_engine(P)),
                rfcs_ctx(engine_schemas(E3), engine_interns(E3)),
                Items ++ [Wcet], WithWcet),
            check("[LFST.9.2.1] a recorded pump_wcet_ns BoundsError is not "
                ++ "compared: the replay re-derives none and replays clean",
                ( if WithWcet = yes({WSteps, _}), not diverges(WSteps)
                  then yes else no ), !T, !IO)
        else
            check("[LFST.9.6] 122_capacity_refused's assert is refused", no,
                !T, !IO)
        )
    else
        check("[LFST.9.6] the fixture declares `Line`", no, !T, !IO)
    ).

    % @spec [LFST.9.3.1]
    % @spec [RFCS.3.1]
    % A `ComputationError` is compared: as recorded it replays clean, another
    % trap at its seq diverges, and one taken out diverges with the re-derived
    % one left over (`check_compare_atom`). A recorded `TypeError` or
    % `EngineError` this run does not raise diverges too, the reverse of taking
    % one out. As libds's `test_lfst_9_3_1__a_fault_atom_is_compared` and
    % `test_rfcs_6_7__a_recorded_engine_error_the_replay_does_not_raise`.
    % Path: `ds.rfcs.lfst_9_3_1_compared` -> `ds.replay.lfst_9_3_1_match`.
    %
:- pred check_replay_compare_faults(program::in, tally::in, tally::out,
                                    io::di, io::uo) is det.

check_replay_compare_faults(P, !T, !IO) :-
    ( if find_schema(schemas(P), interns(P), "Reading", Reading) then
        engine_use_mock_clock(init_engine(P), E0),
        host_assert(Reading, [int(1i64), int(0i64)], no, _, Fx1, E0, E1),
        pump(default_budget, Fx2, E1, E2),
        Items = record_items(0u64, Fx1 ++ Fx2),
        ( if first_item(is_expr_fault, Items, Trap) then
            check_compare_atom(P, E2, "ComputationError", Items, Trap,
                with_fault(Trap, rf_domain), !T, !IO),
            check_fault_not_raised(P, E2, "TypeError", Items, rf_type_error,
                !T, !IO),
            check_fault_not_raised(P, E2, "EngineError", Items,
                rf_artefact_lied, !T, !IO)
        else
            check("[LFST.9.3.1] 52_div_zero's rule traps", no, !T, !IO)
        )
    else
        check("[LFST.9.3.1] the fixture declares `Reading`", no, !T, !IO)
    ).

    % @spec [RFCS.6.7]
    % @spec [RFCS.3.1]
    % An `EngineError` is compared, in the recording of a run that halted: as
    % recorded it replays clean, another fault at its seq diverges, and one
    % taken out diverges. As libds's
    % `test_rfcs_6_7__a_replay_re_derives_another_engine_error`.
    %
:- pred test_rfcs_6_7_engine_error_compared(program::in, tally::in, tally::out,
                                            io::di, io::uo) is det.

test_rfcs_6_7_engine_error_compared(P, !T, !IO) :-
    ( if find_schema(schemas(P), interns(P), "In", In) then
        engine_use_mock_clock(init_engine(P), E0),
        engine_intern("ab", Txt, E0, E1),
        host_assert(In, [int(1i64), str(Txt)], no, _, Fx1, E1, E2),
        pump(default_budget, Fx2, E2, E3),
        Items = record_items(0u64, Fx1 ++ Fx2),
        ( if first_item(is_expr_fault, Items, Halt) then
            check_compare_atom(P, E3, "EngineError", Items, Halt,
                with_fault(Halt, rf_pattern_index), !T, !IO)
        else
            check("[RFCS.6.7] 47_emit_softfail's rule halts", no, !T, !IO)
        )
    else
        check("[RFCS.6.7] the fixture declares `In`", no, !T, !IO)
    ).

    % The recording with `Fault` appended, which the replay does not raise.
    %
:- pred check_fault_not_raised(program::in, engine::in, string::in,
                               list(record_item)::in, runtime_fault::in,
                               tally::in, tally::out, io::di, io::uo) is det.

check_fault_not_raised(P, Run, Atom, Items, Fault, !T, !IO) :-
    Extra = ri_event(make_seq(past_last_item(Items)),
        se_engine_error(ee_expr_fault(Fault), no_site)),
    replay_items(P, session_header(init_engine(P)),
        rfcs_ctx(engine_schemas(Run), engine_interns(Run)),
        Items ++ [Extra], Replayed),
    check("[RFCS.6.7] a recorded " ++ Atom
            ++ " the replay does not raise is a divergence",
        ( if Replayed = yes({Steps, _}), diverges(Steps)
          then yes else no ), !T, !IO).

:- pred is_expr_fault(record_item::in) is semidet.

is_expr_fault(ri_event(_, se_engine_error(ee_expr_fault(_), _))).

:- func with_fault(record_item, runtime_fault) = record_item.

with_fault(Item, Fault) =
    ( if Item = ri_event(Seq, se_engine_error(_, Site)) then
        ri_event(Seq, se_engine_error(ee_expr_fault(Fault), Site))
    else
        Item
    ).

    % [RFCS.11.2], [LFST.9.3.6]: `timetag` is compared by pairing, not by
    % value, as libds's `verify_match` compares it (test_rfcs_verify's case
    % 8). Each run is recorded, and the recording replayed with its timetags
    % rewritten as another conforming engine's recording might carry them:
    %   - every timetag renamed by a constant: replays clean;
    %   - (30_cascade) the second firing given the first's timetag: two
    %     firings the engine keeps apart share one, so the replay parts from
    %     the recording at the second firing's begin;
    %   - (43_interp_call) the CallIssued alone given a timetag no firing has:
    %     its RuleFireAnnotation paired the re-derived timetag with another,
    %     so the replay parts at the CallIssued, the pairing broken from the
    %     re-derived side.
    %
:- pred check_replay_timetag_cascade(program::in, tally::in, tally::out,
                                     io::di, io::uo) is det.

check_replay_timetag_cascade(P, !T, !IO) :-
    ( if find_schema(schemas(P), interns(P), "Trigger", Trig) then
        engine_use_mock_clock(init_engine(P), E0),
        host_assert(Trig, [int(1i64)], no, _, Fx1, E0, E1),
        pump(default_budget, Fx2, E1, E2),
        Items = record_items(0u64, Fx1 ++ Fx2),
        Meta = session_header(init_engine(P)),
        Ctx = rfcs_ctx(engine_schemas(E2), engine_interns(E2)),
        replay_items(P, Meta, Ctx,
            list.map(retimetag((func(V) = V + 50u64)), Items), Renamed),
        check("[LFST.9.3.6] 30_cascade: every timetag renamed replays clean",
            ( if Renamed = yes({RSteps, _}), not diverges(RSteps)
              then yes else no ), !T, !IO),
        ( if
            first_item(is_fire_begin, Items, ri_event(_, se_fire_begin(F1))),
            A = timetag_value(F1 ^ fi_timetag),
            first_item(begins_other_than(A), Items, Second),
            Second = ri_event(SecondSeq, se_fire_begin(F2)),
            B = timetag_value(F2 ^ fi_timetag)
        then
            replay_items(P, Meta, Ctx,
                list.map(retimetag((func(V) = ( if V = B then A else V ))),
                    Items),
                Merged),
            check("[LFST.9.3.6] 30_cascade: two firings sharing one timetag "
                ++ "part the replay from the recording at the second's begin",
                ( if
                    Merged = yes({MSteps, _}),
                    list.last(MSteps, diverged(seq_value(SecondSeq)))
                  then yes else no ), !T, !IO)
        else
            check("[LFST.9.3.6] 30_cascade fires twice", no, !T, !IO)
        )
    else
        check("[LFST.9.3.6] the fixture declares `Trigger`", no, !T, !IO)
    ).

:- pred check_replay_timetag_call(program::in, tally::in, tally::out,
                                  io::di, io::uo) is det.

check_replay_timetag_call(P, !T, !IO) :-
    ( if find_schema(schemas(P), interns(P), "Reading", Reading) then
        engine_use_mock_clock(init_engine(P), E0),
        engine_intern("kitchen", Zone, E0, E1),
        host_assert(Reading, [int(1i64), str(Zone), int(7i64)], no, _, Fx1,
            E1, E2),
        pump(default_budget, Fx2, E2, E3),
        Items = record_items(0u64, Fx1 ++ Fx2),
        Meta = session_header(init_engine(P)),
        Ctx = rfcs_ctx(engine_schemas(E3), engine_interns(E3)),
        replay_items(P, Meta, Ctx,
            list.map(retimetag((func(V) = V + 50u64)), Items), Renamed),
        check("[LFST.9.3.6] 43_interp_call: every timetag renamed, the "
            ++ "CallIssued's with its firing's, replays clean",
            ( if Renamed = yes({RSteps, _}), not diverges(RSteps)
              then yes else no ), !T, !IO),
        ( if first_item(is_call_issued, Items, ri_event(CallSeq, _)) then
            replay_items(P, Meta, Ctx,
                list.map(retimetag_call((func(V) = V + 70u64)), Items),
                Split),
            check("[LFST.9.3.6] 43_interp_call: the CallIssued alone given a "
                ++ "timetag no firing has parts the replay from the recording "
                ++ "at its seq",
                ( if
                    Split = yes({SSteps, _}),
                    list.last(SSteps, diverged(seq_value(CallSeq)))
                  then yes else no ), !T, !IO)
        else
            check("[LFST.9.3.6] 43_interp_call's rule calls", no, !T, !IO)
        )
    else
        check("[LFST.9.3.6] the fixture declares `Reading`", no, !T, !IO)
    ).

    % Every firing's timetag in a record, through `F`: a RuleFireAnnotation's
    % begin and end and a CallIssued alike, so the join key stays a pair.
    %
:- func retimetag(func(uint64) = uint64, record_item) = record_item.

retimetag(F, Item) =
    ( if Item = ri_event(S, se_fire_begin(Fire)) then
        ri_event(S, se_fire_begin(refire(F, Fire)))
    else if Item = ri_event(S, se_fire_end(Fire)) then
        ri_event(S, se_fire_end(refire(F, Fire)))
    else
        retimetag_call(F, Item)
    ).

    % A CallIssued's timetag alone, through `F`.
    %
:- func retimetag_call(func(uint64) = uint64, record_item) = record_item.

retimetag_call(F, Item) =
    ( if Item = ri_event(S, se_call_issued(Fire, Service, Corr, Args, Origin))
    then
        ri_event(S, se_call_issued(refire(F, Fire), Service, Corr, Args,
            Origin))
    else
        Item
    ).

:- func refire(func(uint64) = uint64, fire_id) = fire_id.

refire(F, Fire) =
    Fire ^ fi_timetag :=
        make_timetag(apply(F, timetag_value(Fire ^ fi_timetag))).

:- pred begins_other_than(uint64::in, record_item::in) is semidet.

begins_other_than(A, ri_event(_, se_fire_begin(Fire))) :-
    timetag_value(Fire ^ fi_timetag) \= A.

    % The three replays of one compare-class record, `Target`, in the
    % recording of a run that ended in `Run`.
    %
:- pred check_compare_atom(program::in, engine::in, string::in,
                           list(record_item)::in, record_item::in,
                           record_item::in, tally::in, tally::out,
                           io::di, io::uo) is det.

check_compare_atom(P, Run, Atom, Items, Target, Altered, !T, !IO) :-
    Meta = session_header(init_engine(P)),
    Ctx = rfcs_ctx(engine_schemas(Run), engine_interns(Run)),
    replay_items(P, Meta, Ctx, Items, AsRecorded),
    check("[LFST.9.6] " ++ Atom ++ ": the recording replays clean",
        ( if AsRecorded = yes({Steps, _}), not diverges(Steps)
          then yes else no ), !T, !IO),
    ( if Target = ri_event(Seq, _) then
        replay_items(P, Meta, Ctx,
            list.map((func(I) = ( if I = Target then Altered else I )),
                Items),
            AlteredRun),
        check("[LFST.9.3.1] " ++ Atom ++ ": one altered parts the replay "
            ++ "from the recording at its seq",
            ( if
                AlteredRun = yes({ASteps, _}),
                list.last(ASteps, diverged(seq_value(Seq)))
              then yes else no ), !T, !IO),
        replay_items(P, Meta, Ctx, list.delete_all(Items, Target), Removed),
        check("[LFST.9.3.1] " ++ Atom ++ ": one missing is a divergence",
            ( if Removed = yes({RSteps, _}), diverges(RSteps)
              then yes else no ), !T, !IO)
    else
        check("[LFST.9.6] " ++ Atom ++ ": the record is an event", no, !T, !IO)
    ).

:- pred first_item(pred(record_item)::in(pred(in) is semidet),
                   list(record_item)::in, record_item::out) is semidet.

first_item(Test, Items, Item) :-
    list.find_first_match(Test, Items, Item).

:- pred last_item(pred(record_item)::in(pred(in) is semidet),
                  list(record_item)::in, record_item::out) is semidet.

last_item(Test, Items, Item) :-
    list.find_first_match(Test, list.reverse(Items), Item).

:- func with_event(record_item, stream_event) = record_item.

with_event(Item, Event) =
    ( if Item = ri_event(Seq, _) then ri_event(Seq, Event) else Item ).

    % One past the last `seq` among `Items`.
    %
:- func past_last_item(list(record_item)) = uint64.

past_last_item(Items) = list.foldl(
    ( func(I, Max) =
        ( if I = ri_event(S, _), seq_value(S) + 1u64 > Max then
            seq_value(S) + 1u64
        else
            Max
        ) ),
    Items, 0u64).

:- pred is_fire_begin(record_item::in) is semidet.

is_fire_begin(ri_event(_, se_fire_begin(_))).

:- pred is_fire_end(record_item::in) is semidet.

is_fire_end(ri_event(_, se_fire_end(_))).

:- pred is_emit(record_item::in) is semidet.

is_emit(ri_event(_, se_emit(_, _))).

:- pred is_call_issued(record_item::in) is semidet.

is_call_issued(ri_event(_, se_call_issued(_, _, _, _, _))).

:- pred is_bounds_error(record_item::in) is semidet.

is_bounds_error(ri_event(_, se_engine_error(ee_contract_breach(Cap), _))) :-
    Cap \= cap_pump_wcet.

    % [RBND.5.1], [RBND.5.2], [RBND.2.1]: a recording binds to the program by
    % its whole dialect-binding tuple, through the one comparator
    % ([RBND.6.1], `ds.binding.compare_dialect`), before anything is delivered.
    % The recording carrying the program's tuple, as its engine records it,
    % replays. Each other one differs from it in one field and nothing else, so
    % its refusal can only be that field's.
    %
    % The `capabilities` and `dialect_def_sha256` cases are re-written headers.
    % A real recording of another bundle differs in `dsc_sha256` whatever else
    % it differs in, because the hash covers the header that carries the other
    % two ([RDSC.3.6]). RBND.8.1's fourth case, two dialect names that resolve
    % alike, has no form here: neither tuple carries a name (`test_binding`
    % has the comparator's half).
    %
    % Path: `ds.replay.replay_stream` -> `ds.binding.compare_dialect`.
    % libds's counterpart is test_dsc_basic.c's
    % `test_rbnd_5_1__replay_binds_the_whole_tuple` (`replay_verify_header` ->
    % `ds_binding_compare_dialect`).
    %
:- pred check_replay_dsc_binding(program::in, tally::in, tally::out,
                                 io::di, io::uo) is det.

check_replay_dsc_binding(P, !T, !IO) :-
    Ctx = rfcs_ctx(schemas(P), interns(P)),
    H = header(P),
    Good = session_header(init_engine(P)),
    Events = [{make_seq(0u64), se_clock_tick(from_ns(0u64), no)},
              {make_seq(1u64), se_pump_boundary}],
    check("[RBND.1.3] the engine records the program's whole tuple",
        ( if
            Good ^ sm_dsc_hash = H ^ dh_sha256,
            Good ^ sm_capabilities = H ^ dh_capabilities,
            Good ^ sm_def_sha = H ^ dh_dialect_sha
          then yes else no ), !T, !IO),
    ( if
        H ^ dh_sha256 = [B0 | Rest],
        list.length(H ^ dh_sha256) = 32,
        H ^ dh_dialect_sha = [D0 | DRest],
        Good ^ sm_capabilities = [C0, C1 | CRest]
    then
        NoTuple = ((Good ^ sm_dsc_hash := []) ^ sm_capabilities := [])
            ^ sm_def_sha := [],
        Cases = [
            {"identical tuples", Good, bw_replays},
            {"another dsc_sha256",
                Good ^ sm_dsc_hash := [uint8.xor(B0, 1u8) | Rest],
                bw_refused(-700, "dsc_sha256")},
            % Still ascending live members, so a well-formed tuple that is
            % another program's: -701.
            {"one capability fewer",
                Good ^ sm_capabilities := [C0 | CRest],
                bw_refused(-701, "capabilities")},
            % [RBND.1.3]: a malformed list is refused where the stream
            % header is read, DS_ERR_PARSE, before any comparison -- not cut,
            % sorted or de-duplicated. libds's `test_rbnd_5_1__replay_binds_
            % the_whole_tuple` pins the same four.
            {"a number no Capability names (99)",
                Good ^ sm_capabilities := Good ^ sm_capabilities ++ [99],
                bw_decode_refused("RBND.1.3")},
            {"two capabilities out of order",
                Good ^ sm_capabilities := [C1, C0 | CRest],
                bw_decode_refused("RBND.1.3")},
            {"a capability twice",
                Good ^ sm_capabilities := [C0, C0, C1 | CRest],
                bw_decode_refused("RBND.1.3")},
            {"CAPABILITY_UNSPECIFIED (0)",
                Good ^ sm_capabilities := [0, C0, C1 | CRest],
                bw_decode_refused("RBND.1.3")},
            {"another dialect_def_sha256",
                Good ^ sm_def_sha := [uint8.xor(D0, 1u8) | DRest],
                bw_refused(-701, "dialect_def_sha256")},
            % [RBND.2.1]: a trace holding one of `dsc_sha256` and
            % `dialect_def_sha256` and not the other is incomplete, whichever
            % one it holds.
            {"a DSC hash and no dialect_def_sha256",
                Good ^ sm_def_sha := [], bw_refused(-703, "dialect_def_sha256")},
            {"a dialect_def_sha256 and no DSC hash",
                Good ^ sm_dsc_hash := [], bw_refused(-703, "dsc_hash")},
            % [RBND.2.1]: no tuple at all replays without a binding check.
            % libds's test also replays into an engine with no DSC, which
            % this runtime has no form of: `ds.dsc` refuses a DSC without a
            % 32-byte `dsc_sha256`.
            {"no tuple", NoTuple, bw_replays}
        ],
        list.foldl2(binding_case(P, Ctx, Events), Cases, !T, !IO)
    else
        check("the fixture's header carries a 32-byte dsc_sha256, a "
            ++ "dialect_def_sha256 and two capabilities", no, !T, !IO)
    ).

:- type binding_want
    --->    bw_replays
    ;       bw_refused(int, string)
            % The code, and a field name the detail must contain.
    ;       bw_decode_refused(string).
            % The stream does not decode, refused citing this clause
            % (libds: DS_ERR_PARSE from ds_rfcs_decode_header).

:- pred binding_case(program::in, rfcs_ctx::in, list({seq, stream_event})::in,
                     {string, stream_meta, binding_want}::in,
                     tally::in, tally::out, io::di, io::uo) is det.

binding_case(P, Ctx, Events, {Name, Meta, Want}, !T, !IO) :-
    encode_stream(Meta, Ctx, from_ns(0u64), Events, Bytes, _),
    decode_stream(from_bytes(list.map(uint8.cast_to_int, Bytes)), interns(P),
        Decoded),
    ( if Want = bw_decode_refused(WantClause) then
        check("[RBND.1.3] " ++ Name ++ ": the stream header is refused where "
                ++ "it is read, citing " ++ WantClause,
            ( if Decoded = decode_failed(WantClause, _) then yes else no ),
            !T, !IO),
        ( if Decoded = decode_failed(Clause, _), Clause \= WantClause then
            io.format("    %s: refused citing %s\n", [s(Name), s(Clause)], !IO)
        else
            true
        )
    else if
        Decoded = decoded(DS)
    then
        % The header round-trips, fields 9 and 16 with the rest, so the replay
        % below compares the tuple written.
        Read = DS ^ dsm_meta,
        check("[RBND.2] " ++ Name ++ ": the stream header's tuple reads back",
            ( if
                Read ^ sm_dsc_hash = Meta ^ sm_dsc_hash,
                Read ^ sm_capabilities = Meta ^ sm_capabilities,
                Read ^ sm_def_sha = Meta ^ sm_def_sha
              then yes else no ), !T, !IO),
        engine_use_mock_clock(init_engine(P), E0),
        replay_stream(P, DS, Steps, E0, _),
        (
            Want = bw_decode_refused(_)    % answered above
        ;
            Want = bw_replays,
            check("[RBND.5.1] " ++ Name ++ ": the recording replays",
                ( if
                    Steps = [_ | _],
                    not list.member(binding_refused(_, _), Steps)
                  then yes else no ), !T, !IO)
        ;
            Want = bw_refused(Code, Field),
            ( if Steps = [binding_refused(Got, Detail)] then
                check("[RBND.5.2] " ++ Name ++ ": refused with "
                    ++ string.from_int(Code) ++ " before anything is "
                    ++ "delivered, the detail naming " ++ Field,
                    ( if
                        Got = Code,
                        string.sub_string_search(Detail, Field, _)
                      then yes
                      else no ), !T, !IO),
                ( if Got = Code then
                    true
                else
                    io.format("    %s: refused with %d: %s\n",
                        [s(Name), i(Got), s(Detail)], !IO)
                )
            else
                check("[RBND.5.2] " ++ Name ++ ": refused with "
                    ++ string.from_int(Code) ++ ", and nothing delivered",
                    no, !T, !IO)
            )
        )
    else
        check("[RBND.2] " ++ Name ++ ": the recording decodes", no, !T, !IO)
    ).

    % [RFCS.19.3]: atoms 260 and 323, in no `ds.atom` entry, name no member
    % of `Atom`'s oneof, so a recording carrying them is refused. The same
    % recording decodes as written, and is refused with both appended: a 260
    % holding a `sig_alg`, a `key_id`, a time, a signature and a public key,
    % and a 323 with a tag and a text. libds's `test_rfcs_replay` pins the
    % same on its reader.
    %
% @spec [RFCS.19.3]
:- pred check_retired_atoms_replay(program::in, tally::in, tally::out,
                                   io::di, io::uo) is det.

check_retired_atoms_replay(P, !T, !IO) :-
    Ctx = rfcs_ctx(schemas(P), interns(P)),
    % The program's own tuple, as its engine records it: [RBND.5.1] refuses a
    % recording bound to any other, and then both replays would stop at that
    % refusal and agree vacuously.
    Meta = session_header(init_engine(P)),
    Whole = [{make_seq(0u64), se_clock_tick(from_ns(0u64), no)},
             {make_seq(1u64), se_pump_boundary},
             {make_seq(2u64), se_clock_tick(from_ns(1000u64), no)},
             {make_seq(3u64), se_pump_boundary}],
    encode_stream(Meta, Ctx, from_ns(0u64), Whole, Bytes, _),
    Sig = list.duplicate(64, uint8.cast_from_int(0xa5)),
    Key = list.duplicate(32, uint8.cast_from_int(0x3c)),
    put_uint32(1u32, 99u32, init_builder, S1),
    put_string(2u32, "not-a-fingerprint", S1, S2),
    put_string(3u32, "2026-10-11T00:00:00Z", S2, S3),
    put_delimited(4u32, Sig, S3, S4),
    put_delimited(5u32, Key, S4, S5),
    put_delimited(260u32, builder_bytes(S5), init_builder, SealAtom),
    put_delimited(1u32, builder_bytes(SealAtom), init_builder, SealFrame),
    Tag = list.map(uint8.cast_from_int, [0x6C, 0x69, 0x63])  % "lic"
        ++ list.duplicate(13, 0u8),
    put_delimited(1u32, Tag, init_builder, N1),
    put_delimited(2u32, list.duplicate(5, uint8.cast_from_int(0x41)), N1, N2),
    put_delimited(323u32, builder_bytes(N2), init_builder, NoteAtom),
    put_delimited(1u32, builder_bytes(NoteAtom), init_builder, NoteFrame),
    WithBoth = Bytes ++ builder_bytes(SealFrame) ++ builder_bytes(NoteFrame),
    decode_stream(from_bytes(list.map(uint8.cast_to_int, Bytes)),
        interns(P), PlainResult),
    check("RFCS.19.3: the recording decodes as written",
        ( if PlainResult = decoded(_) then yes else no ), !T, !IO),
    decode_stream(from_bytes(list.map(uint8.cast_to_int, WithBoth)),
        interns(P), BothResult),
    check("RFCS.19.3: a recording with a 260 and a 323 appended is refused "
            ++ "at the 260",
        ( if BothResult = decode_failed("RFCS.19.3", list.length(Bytes))
          then yes else no ), !T, !IO).

    % A null reading is no sample. A Meter asserted with no reading, then
    % superseded with 5.0, puts one sample in its row: libds skips the null
    % before the absorb (`rete_val_to_sample`), so `count` reads 1.
    %
:- pred check_null_is_no_sample(program::in, tally::in, tally::out,
                                io::di, io::uo) is det.

check_null_is_no_sample(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Meter", S) then
        engine_intern("m", M, E0, E1),
        host_assert(S, [str(M), null], no, _, _, E1, E2),
        pump(default_budget, _, E2, E3),
        host_assert(S, [str(M), float(5.0)], no, _, _, E3, E4),
        pump(default_budget, _, E4, E5),
        Key = series_key("Meter", "reading", "id", "m", 600000000000u64),
        query(agg_count, Key, engine_now(E5), engine_series(E5),
            cold_value(agg_count, no), Count),
        check("series: a null reading is no sample: one null, one 5.0 count 1",
            ( if Count = int(1i64) then yes else no ), !T, !IO)
    else
        check("112_series_null declares Meter", no, !T, !IO)
    ).

    % Each fact is absorbed once, however many pumps follow: two live
    % readings of one sensor share a row.
    %
:- pred check_shared_row_once(program::in, tally::in, tally::out,
                              io::di, io::uo) is det.

check_shared_row_once(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Reading", S) then
        engine_intern("s", Sensor, E0, E1),
        host_assert(S, [str(Sensor), float(1.0)], no, _, _, E1, E2),
        host_assert(S, [str(Sensor), float(2.0)], no, _, _, E2, E3),
        pump(default_budget, _, E3, E4),
        pump(default_budget, _, E4, E5),
        Key = series_key("Reading", "level", "sensor", "s", 600000000000u64),
        query(agg_count, Key, engine_now(E5), engine_series(E5),
            cold_value(agg_count, no), Count),
        check("series: two live facts in one row, two pumps: count 2",
            ( if Count = int(2i64) then yes else no ), !T, !IO)
    else
        check("113_series_shared_row declares Reading", no, !T, !IO)
    ).

    % A live engine sees wall time pass, so a TTL expires on it.
    %
:- pred check_live_ttl(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_live_ttl(P, !T, !IO) :-
    read_wall_clock(R0, !IO),
    observe_wall_clock(R0, init_engine(P), E0),
    check("live clock: a live engine's first reading anchors it at instant 0",
        ( if engine_now(E0) = from_ns(0u64) then yes else no ), !T, !IO),
    ( if find_schema(schemas(P), interns(P), "Sensor", Sensor) then
        engine_intern("dev1", Dev, E0, E1),
        host_assert(Sensor, [str(Dev), float(1.0)], yes(from_ns(1u64)),
            Result, _, E1, E2),
        pump(default_budget, _, E2, E3),
        ( if Result = inserted(Id) then
            check("live clock: a fact whose deadline has not come stays live",
                ( if lookup_fact(engine_wm(E3), Id, _) then yes else no ),
                !T, !IO),
            next_reading(R0, 100000000, R1, !IO),
            observe_wall_clock(R1, E3, E4),
            pump(default_budget, _, E4, E5),
            check("live clock: wall time passing expires it at the next pump",
                ( if lookup_fact(engine_wm(E5), Id, _) then no else yes ),
                !T, !IO),
            % A fresh engine: E3 has consumed an input, so its switch to mock
            % is refused ([NLFC.5.4]), which is the next check.
            engine_use_mock_clock(init_engine(P), M0),
            observe_wall_clock(R1, M0, M1),
            pump(default_budget, _, M1, M2),
            check("live clock: a reading does not move a mock clock",
                ( if engine_now(M2) = from_ns(0u64) then yes else no ),
                !T, !IO),
            engine_use_mock_clock(E3, Still),
            observe_wall_clock(R1, Still, S1),
            pump(default_budget, _, S1, S2),
            check("[NLFC.5.4] live -> mock after the first input is refused: "
                ++ "the clock stays live and a reading moves it",
                ( if before(engine_now(E3), engine_now(S2)) then yes else no ),
                !T, !IO)
        else
            check("live clock: Sensor is asserted on a live engine", no, !T,
                !IO)
        )
    else
        check("live clock: the fixture declares `Sensor`", no, !T, !IO)
    ).

    % [RTCT.7]: `79_capbreach.dsrt` caps live facts at two, and the third
    % assert is refused as `rejected(cap_wm_max)`, not fatal ([RTCT.7.2]).
    % libds refuses it at the assert, not at the following pump.
    %
:- pred check_wm_cap(program::in, tally::in, tally::out, io::di, io::uo) is det.

check_wm_cap(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Reading", S) then
        engine_intern("a", A, E0, Ea),
        engine_intern("b", B, Ea, Eb),
        engine_intern("c", C, Eb, Ec),
        % Three distinct keys, so each assert is an insert rather than a
        % replace: `Reading` is `logical` with `entity_id` as its key.
        host_assert(S, [str(A), float(35.0)], no, R1, _, Ec, E1),
        host_assert(S, [str(B), float(36.0)], no, R2, _, E1, E2),
        host_assert(S, [str(C), float(37.0)], no, R3, Eff3, E2, E3),
        check("two facts fit under a wm_max of two",
            ( if R1 = inserted(_), R2 = inserted(_) then yes else no ),
            !T, !IO),
        check("the third is rejected, naming the cap (RTCT.7)",
            ( if R3 = rejected(cap_wm_max) then yes else no ), !T, !IO),
        % libds's `limit` / `observed` for `wm_max`: the cap, and the live
        % count the refused insert would have made (`wm_rete.c`). No
        % activation: the host asserted it.
        check("fault site: the wm_max breach carries limit 2, observed 3",
            ( if events_of(Eff3) = [eff_event(se_engine_error(_, Site))],
                 Site = fault_site(no, no, no, yes(fault_bound(2u64, 3u64)),
                    no, no, no, fr_engine)
              then yes else no ), !T, !IO),
        % Rejected is not fatal: the two facts that fit are still there.
        check("...and the engine keeps the two it had",
            ( if engine_fact_count(E3) = 2 then yes else no ), !T, !IO),
        % [LEXP.4.2] -- NaN never enters working memory; Inf does. Asserted
        % against the engine the cap left with room: a NaN refused first
        % changes nothing, so the later Inf is still an insert.
        engine_intern("n", N, E0, En),
        NaN = float.infinity - float.infinity,
        host_assert(S, [str(N), float(NaN)], no, RN, _, En, En1),
        check("[LEXP.4.2] a NaN Float slot is refused at assert",
            ( if RN = invalid(1, sr_nan_rejected) then yes else no ),
            !T, !IO),
        host_assert(S, [str(N), float(float.infinity)], no, RI, _, En1, _),
        check("[LEXP.4.2] ...and an Inf one is admitted",
            ( if RI = inserted(_) then yes else no ), !T, !IO)
    else
        check("79_capbreach declares Reading", no, !T, !IO)
    ).

    % A join test's fault is located at its beta node. `div_where` divides in
    % its `where`, which raises and so is a join test, not an alpha one
    % ([IRET.6.4]); a Sensor with `b = 0` faults it, an all-Int division
    % ([LEXP.7.15.1]). A matching-time fault has no activation, so the node is
    % its identity (`type_error.proto`).
    %
% @spec [RFCS.6.7]
:- pred check_match_fault_node(program::in, tally::in, tally::out,
                               io::di, io::uo) is det.

check_match_fault_node(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Sensor", S) then
        engine_intern("s1", Id, E0, E1),
        host_assert(S, [str(Id), null, int(1i64), int(0i64)], no, R, Fx,
            E1, E2),
        check("fault site: a join test's fault names its beta node and no "
                ++ "firing",
            ( if
                list.member(Effect, Fx),
                Effect = eff_event(se_engine_error(ee_expr_fault(_), Site)),
                Site ^ fs_activation = no,
                Site ^ fs_node = yes(Node),
                list.member(Beta, beta_nodes(network(P))),
                Beta ^ bn_id = Node
              then yes else no ), !T, !IO),
        % [LERR.9.11]: with no activation, the fault is named from its node.
        check("[LERR.9.11] ...and names the rule $beta_<id>",
            ( if
                list.member(Named, Fx),
                Named = eff_event(se_engine_error(ee_expr_fault(_), NSite)),
                NSite ^ fs_node = yes(NNode),
                fault_rule_name(engine_interns(E2), NSite ^ fs_rule) =
                    "$beta_" ++ string.int_to_string(
                        uint32.cast_to_int(node_id_value(NNode)))
              then yes else no ), !T, !IO),
        % The origin is the divisor, `s.b`, read from the candidate fact.
        check("fault site: ...and the divisor it was raised over: Sensor.b, "
                ++ "Int",
            ( if
                R = inserted(FactId),
                list.member(Divided, Fx),
                Divided = eff_event(se_engine_error(ee_expr_fault(_), Origin)),
                Origin ^ fs_fact = yes(FactId),
                reads_as(E2, Origin ^ fs_schema, "Sensor"),
                reads_as(E2, Origin ^ fs_slot, "b"),
                Origin ^ fs_actual = yes("Int")
              then yes else no ), !T, !IO),
        % [RFCS.6.7]: the arriving assert precedes everything its evaluation
        % produces. No fault before the Sensor's FactAssert, and the
        % division's fault after it.
        NotAssert = (pred(Ev::in) is semidet :-
            not Ev = eff_event(se_fact_assert(_, _, _, _))),
        list.take_while(NotAssert, events_of(Fx), Before, FromAssert),
        IsFault = (pred(Ev::in) is semidet :-
            Ev = eff_event(se_engine_error(ee_expr_fault(_), _))),
        check("[RFCS.6.7] a host insert's FactAssert precedes its match fault",
            ( if
                R = inserted(AssertedId),
                FromAssert = [eff_event(se_fact_assert(AssertedId, _, _, _))
                    | After],
                not list.any_true(IsFault, Before),
                list.any_true(IsFault, After)
              then yes else no ), !T, !IO)
    else
        check("101_match_faults declares Sensor", no, !T, !IO)
    ).

    % [RFCS.6.7]: a host retract is recorded before the faults it raises. In
    % `105_released_trap`, `a1` passes, `b1` blocks it, `c1` (y = 0) arrives
    % with no left token at the C node, and retracting `b1` releases `(a1)`
    % into `c1`'s trapping division.
    %
% @spec [RFCS.6.7]
:- pred check_released_trap_order(program::in, tally::in, tally::out,
                                  io::di, io::uo) is det.

check_released_trap_order(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        find_schema(schemas(P), interns(P), "A", SA),
        find_schema(schemas(P), interns(P), "B", SB),
        find_schema(schemas(P), interns(P), "C", SC)
    then
        engine_intern("k1", K1, E0, E1),
        engine_intern("c1", C1, E1, E2),
        host_assert(SA, [str(K1)], no, _, _, E2, E3),
        host_assert(SB, [str(K1)], no, RB, _, E3, E4),
        host_assert(SC, [str(C1), int(1i64), int(0i64)], no, _, _, E4, E5),
        ( if RB = inserted(BId) then
            host_retract(BId, Fx, E5, _),
            IsFault = (pred(Ev::in) is semidet :-
                Ev = eff_event(se_engine_error(ee_expr_fault(_), _))),
            NotRetract = (pred(Ev::in) is semidet :-
                not Ev = eff_event(se_fact_retract(_))),
            list.take_while(NotRetract, events_of(Fx), Before, FromRetract),
            check("[RFCS.6.7] a host retract's FactRetract precedes the "
                ++ "fault its release raises",
                ( if
                    FromRetract = [eff_event(se_fact_retract(BId)) | After],
                    not list.any_true(IsFault, Before),
                    list.any_true(IsFault, After)
                  then yes else no ), !T, !IO)
        else
            check("105_released_trap: b1 is inserted", no, !T, !IO)
        )
    else
        check("105_released_trap declares A, B and C", no, !T, !IO)
    ).

    % [LERR.1.4.12]: a match-time trap is recorded for each pair an operation
    % derives, and for no other. `145_derived_traps`: the NOT node and the
    % trapping join read one schema.
    %
    %   transient    with `a1` live, `b1` (a1's key, y = 0) blocks `(a1)` in
    %                the same assert that offers `((a1), b1)` to the trapping
    %                join: not live when the assert completes, so no trap.
    %   re-derived   `c1` (y = 0) traps; `b1` (y = 1) ends the pair; retracting
    %                `b1` derives it again, and it traps again.
    %
% @spec [LERR.1.4.12]
:- pred check_derived_traps(program::in, tally::in, tally::out,
                            io::di, io::uo) is det.

check_derived_traps(P, !T, !IO) :-
    IsFault = (pred(Ev::in) is semidet :-
        Ev = eff_event(se_engine_error(ee_expr_fault(_), _))),
    ( if
        find_schema(schemas(P), interns(P), "A", SA),
        find_schema(schemas(P), interns(P), "B", SB)
    then
        engine_use_mock_clock(init_engine(P), E0),
        engine_intern("k1", K1, E0, E1),
        engine_intern("k2", K2, E1, E2),
        host_assert(SA, [str(K1)], no, _, _, E2, E3),
        host_assert(SB, [str(K1), int(1i64), int(0i64)], no, _, FxT, E3, _),
        check("[LERR.1.4.12] a pair the assert ends before it completes "
            ++ "records no trap",
            ( if list.any_true(IsFault, events_of(FxT)) then no else yes ),
            !T, !IO),

        host_assert(SA, [str(K1)], no, _, _, E2, F3),
        host_assert(SB, [str(K2), int(1i64), int(0i64)], no, _, Fx1, F3, F4),
        host_assert(SB, [str(K1), int(1i64), int(1i64)], no, RB, Fx2, F4, F5),
        list.filter(IsFault, events_of(Fx1), Traps1),
        list.filter(IsFault, events_of(Fx2), Traps2),
        check("[LERR.1.4.12] c1 derives ((a1), c1): one trap",
            ( if Traps1 = [_] then yes else no ), !T, !IO),
        check("[LERR.1.4.12] b1 ends ((a1), c1) and derives nothing that traps",
            ( if Traps2 = [] then yes else no ), !T, !IO),
        ( if RB = inserted(BId) then
            host_retract(BId, Fx3, F5, _),
            list.filter(IsFault, events_of(Fx3), Traps3),
            check("[LERR.1.4.12] releasing (a1) derives ((a1), c1) again, "
                ++ "and it traps again",
                ( if Traps3 = [_] then yes else no ), !T, !IO)
        else
            check("145_derived_traps: b1 is inserted", no, !T, !IO)
        )
    else
        check("145_derived_traps declares A and B", no, !T, !IO)
    ).

    % [LERR.1.4.12]: one operation's traps in the clause's order.
    % `146_trap_order`: `a1` and `a2` (d = 0), then `c1`, whose assert derives
    % `((a1), c1)` and `((a2), c1)` at `early`'s join and at `late`'s. Each
    % trap names its divisor's A. The order is the rule's terminal ordinal,
    % then the pair's facts by entry rank: early a1, early a2, late a1, late
    % a2, and not propagation order.
    %
% @spec [LERR.1.4.12]
:- pred check_trap_order(program::in, tally::in, tally::out,
                         io::di, io::uo) is det.

check_trap_order(P, !T, !IO) :-
    ( if
        find_schema(schemas(P), interns(P), "A", SA),
        find_schema(schemas(P), interns(P), "C", SC),
        list.find_first_match(
            ( pred(T1::in) is semidet :-
                expand(interns(P), T1 ^ tn_rule, "early") ),
            terminal_nodes(network(P)), TE),
        list.find_first_match(
            ( pred(T2::in) is semidet :-
                expand(interns(P), T2 ^ tn_rule, "late") ),
            terminal_nodes(network(P)), TL)
    then
        Early = TE ^ tn_parent ^ bn_id,
        Late = TL ^ tn_parent ^ bn_id,
        engine_use_mock_clock(init_engine(P), E0),
        engine_intern("a1", KA1, E0, E1),
        engine_intern("a2", KA2, E1, E2),
        engine_intern("c1", KC1, E2, E3),
        host_assert(SA, [str(KA1), int(0i64)], no, RA1, _, E3, E4),
        host_assert(SA, [str(KA2), int(0i64)], no, RA2, _, E4, E5),
        host_assert(SC, [str(KC1), int(1i64)], no, _, Fx, E5, _),
        Sites = list.filter_map(
            ( func(Ev) = {Node, Fact} is semidet :-
                Ev = eff_event(se_engine_error(ee_expr_fault(_), Site)),
                Site ^ fs_node = yes(Node),
                Site ^ fs_fact = yes(Fact) ),
            events_of(Fx)),
        check("[LERR.1.4.12] one assert's traps: rule by ordinal, then the "
            ++ "pair's facts by entry rank",
            ( if
                RA1 = inserted(A1),
                RA2 = inserted(A2),
                Sites = [{Early, A1}, {Early, A2}, {Late, A1}, {Late, A2}]
              then yes else no ), !T, !IO)
    else
        check("146_trap_order declares A, C, early and late", no, !T, !IO)
    ).

    % A fault in a rule's actions names what it was raised over.
    % `52_div_zero` emits `100 / r.divisor`; a Reading with divisor 0 faults
    % it, and the site names the firing, the rule's terminal, the Reading, its
    % `divisor` slot and the value's tag.
    %
:- pred check_body_fault_origin(program::in, tally::in, tally::out,
                                io::di, io::uo) is det.

check_body_fault_origin(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Reading", S) then
        host_assert(S, [int(1i64), int(0i64)], no, R, _, E0, E1),
        pump(default_budget, Fx, E1, E2),
        check("fault site: a rule-body fault names its firing, terminal, fact "
            ++ "and slot: Reading.divisor, Int",
            ( if
                R = inserted(FactId),
                list.member(Effect, Fx),
                Effect = eff_event(se_engine_error(ee_expr_fault(_), Site)),
                Site ^ fs_activation = yes(_),
                Site ^ fs_node = yes(Node),
                list.member(Term, terminal_nodes(network(P))),
                Term ^ tn_id = Node,
                Site ^ fs_fact = yes(FactId),
                reads_as(E2, Site ^ fs_schema, "Reading"),
                reads_as(E2, Site ^ fs_slot, "divisor"),
                Site ^ fs_actual = yes("Int")
              then yes else no ), !T, !IO),
        % [LERR.9.11]: a fault in an activation names that activation's rule.
        check("[LERR.9.11] ...and names the firing rule",
            ( if
                list.member(Named, Fx),
                Named = eff_event(se_engine_error(ee_expr_fault(_), NSite)),
                NSite ^ fs_activation = yes(Fire),
                expand(engine_interns(E2), Fire ^ fi_rule, RuleName),
                fault_rule_name(engine_interns(E2), NSite ^ fs_rule) = RuleName,
                RuleName \= ""
              then yes else no ), !T, !IO)
    else
        check("52_div_zero declares Reading", no, !T, !IO)
    ).

    % An interned name, read back.
    %
:- pred reads_as(engine::in, maybe(intern_ref)::in, string::in) is semidet.

reads_as(E, yes(Ref), Name) :-
    expand(engine_interns(E), Ref, Name).

    % [RTCT.7]: per-node capacity, one check per node kind, each with its own
    % fixture, since the alpha a fact reaches first would hide the beta and
    % the terminal. Each pins the node id in `rejected(cap_node(Id))`: the
    % breach reaches the stream as `ee_contract_breach(cap_node(Id))`.
    %
:- pred check_alpha_cap(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_alpha_cap(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Zone", S) then
        engine_intern("a", A, E0, Ea),
        engine_intern("b", B, Ea, Eb),
        host_assert(S, [str(A), float(10.0)], no, R1, _, Eb, E1),
        host_assert(S, [str(B), float(20.0)], no, R2, Eff2, E1, E2),
        check("one Zone fits an alpha capacity of one",
            ( if R1 = inserted(_) then yes else no ), !T, !IO),
        check("the second breaches the ALPHA, at the assert (RTCT.7)",
            ( if R2 = rejected(cap_node(Id)), node_id_value(Id) = 1u32
              then yes else no ), !T, !IO),
        % The breach names its node and its bound: the capacity, and the
        % count the overfilled alpha held before the assert was undone.
        check("fault site: the node breach names node 1, limit 1, observed 2",
            ( if
                events_of(Eff2) = [eff_event(se_engine_error(_, Site))],
                Site ^ fs_node = yes(N),
                node_id_value(N) = 1u32,
                Site ^ fs_bound = yes(fault_bound(1u64, 2u64))
              then yes else no ), !T, !IO),
        % Rejected is not fatal, and here the whole match is discarded: the
        % engine that comes back is the one from before the call.
        check("...and the rejected assert left the engine alone",
            ( if engine_fact_count(E2) = 1 then yes else no ), !T, !IO)
    else
        check("cap_node_alpha declares Zone", no, !T, !IO)
    ).

:- pred check_beta_cap(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_beta_cap(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Zone", S) then
        engine_intern("a", A, E0, Ea),
        engine_intern("b", B, Ea, Eb),
        host_assert(S, [str(A), float(10.0)], no, R1, _, Eb, E1),
        host_assert(S, [str(B), float(20.0)], no, R2, _, E1, E2),
        % The same two asserts as the alpha case; what differs is which node
        % is named. With the alphas generous, the second Zone reaches the root
        % beta, whose token memory is the one over.
        check("one Zone fits a beta capacity of one",
            ( if R1 = inserted(_) then yes else no ), !T, !IO),
        check("the second breaches the BETA, not the alpha (RTCT.7)",
            ( if R2 = rejected(cap_node(Id)), node_id_value(Id) = 2u32
              then yes else no ), !T, !IO),
        check("...and the rejected assert left the engine alone",
            ( if engine_fact_count(E2) = 1 then yes else no ), !T, !IO)
    else
        check("cap_node_beta declares Zone", no, !T, !IO)
    ).

:- pred check_term_cap(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_term_cap(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        find_schema(schemas(P), interns(P), "Zone", Z),
        find_schema(schemas(P), interns(P), "Reading", R)
    then
        engine_intern("a", A, E0, Ea),
        engine_intern("r1", One, Ea, Eb),
        engine_intern("r2", Two, Eb, Ec),
        host_assert(Z, [str(A), float(10.0)], no, _, _, Ec, E1),
        % `state > 30.0` is the rule's guard, so both readings match and each
        % produces one activation at the terminal.
        host_assert(R, [str(One), str(A), float(35.0)], no, R1, _, E1, E2),
        host_assert(R, [str(Two), str(A), float(36.0)], no, R2, _, E2, E3),
        check("one match fits a terminal capacity of one",
            ( if R1 = inserted(_) then yes else no ), !T, !IO),
        check("the second breaches the TERMINAL (RTCT.7)",
            ( if R2 = rejected(cap_node(Id)), node_id_value(Id) = 5u32
              then yes else no ), !T, !IO),
        check("...and the rejected assert left the engine alone",
            ( if engine_fact_count(E3) = 2 then yes else no ), !T, !IO)
    else
        check("cap_node_term declares Zone and Reading", no, !T, !IO)
    ).

    % Firing does not free a terminal's slot: libds refuses the second
    % reading even with a pump in between.
    %
:- pred check_term_cap_survives_firing(program::in, tally::in, tally::out,
                                       io::di, io::uo) is det.

check_term_cap_survives_firing(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        find_schema(schemas(P), interns(P), "Zone", Z),
        find_schema(schemas(P), interns(P), "Reading", R)
    then
        engine_intern("a", A, E0, Ea),
        engine_intern("r1", One, Ea, Eb),
        engine_intern("r2", Two, Eb, Ec),
        host_assert(Z, [str(A), float(10.0)], no, _, _, Ec, E1),
        host_assert(R, [str(One), str(A), float(35.0)], no, _, _, E1, E2),
        pump(default_budget, _, E2, E3),
        host_assert(R, [str(Two), str(A), float(36.0)], no, R2, _, E3, E4),
        check("a drained agenda does not free the terminal's slot (RTCT.7)",
            ( if R2 = rejected(cap_node(_)) then yes else no ), !T, !IO),
        % Three: the pump fired `warm`, whose RHS emits an `Alarm`, and the
        % rejection unwound the second assert, not that firing.
        check("...and the engine keeps the pump's own emission",
            ( if engine_fact_count(E4) = 3 then yes else no ), !T, !IO)
    else
        check("cap_node_term declares Zone and Reading", no, !T, !IO)
    ).

    % Retraction does free a terminal's slot: the count is of live
    % activations, and libds runs this script to completion against a
    % terminal capacity of one.
    %
:- pred check_term_cap_falls_on_retract(program::in, tally::in, tally::out,
                                        io::di, io::uo) is det.

check_term_cap_falls_on_retract(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        find_schema(schemas(P), interns(P), "Zone", Z),
        find_schema(schemas(P), interns(P), "Reading", R)
    then
        engine_intern("a", A, E0, Ea),
        engine_intern("r1", One, Ea, Eb),
        engine_intern("r2", Two, Eb, Ec),
        host_assert(Z, [str(A), float(10.0)], no, _, _, Ec, E1),
        host_assert(R, [str(One), str(A), float(35.0)], no, R1, _, E1, E2),
        ( if R1 = inserted(FirstId) then
            host_retract(FirstId, _, E2, E3),
            host_assert(R, [str(Two), str(A), float(36.0)], no, R2, _, E3, E4),
            check("retracting the match gives the terminal its slot back",
                ( if R2 = inserted(_) then yes else no ), !T, !IO),
            check("...leaving the Zone and the second Reading",
                ( if engine_fact_count(E4) = 2 then yes else no ), !T, !IO)
        else
            check("the first Reading was inserted", no, !T, !IO)
        )
    else
        check("cap_node_term declares Zone and Reading", no, !T, !IO)
    ).

    % [RTCT.7]: which cache cap is named when one write breaches both.
    % `cap_cache_vs_bytes` sets `cache_cap: 1` and `cache_bytes_cap: 5`
    % against a rule writing two entries whose JSON is three bytes each, so
    % the second write takes the count to 2 and the bytes to 6 together.
    % libds answers `cache: contract cache_cap (live keys) exceeded`. A unit
    % test, since libds's trace carries only the driver's generic
    % `engine_error` marker, which names neither cap.
    %
:- pred check_cache_cap_order(program::in, tally::in, tally::out,
                              io::di, io::uo) is det.

check_cache_cap_order(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        find_schema(schemas(P), interns(P), "Zone", Z),
        find_schema(schemas(P), interns(P), "Reading", R)
    then
        engine_intern("a", A, E0, Ea),
        engine_intern("r1", One, Ea, Eb),
        host_assert(Z, [str(A), float(10.0)], no, _, _, Eb, E1),
        host_assert(R, [str(One), str(A), float(35.0)], no, _, _, E1, E2),
        pump(default_budget, Effects, E2, _),
        check("a write over both cache caps names cache_cap (RTCT.7)",
            ( if list.member(eff_event(se_engine_error(Err, _)), Effects),
                 Err = ee_contract_breach(cap_cache)
              then yes else no ), !T, !IO),
        check("...and not cache_bytes, which the same write also crossed",
            ( if list.member(eff_event(se_engine_error(Other, _)), Effects),
                 Other = ee_contract_breach(cap_cache_bytes)
              then no else yes ), !T, !IO),
        % The site names the firing and the bound: the cap, and a size past
        % it.
        check("fault site: the cache breach names its firing and its bound",
            ( if list.member(eff_event(se_engine_error(
                    ee_contract_breach(cap_cache), Site)), Effects),
                 Site ^ fs_activation = yes(_),
                 Site ^ fs_bound = yes(fault_bound(Limit, Observed)),
                 Observed > Limit
              then yes else no ), !T, !IO),
        % A fault in a rule's actions is located at the rule's terminal, the
        % node LineSpan maps to the rule ([RDSC.14.3]).
        check("fault site: the cache breach names the rule's terminal as its "
                ++ "node",
            ( if list.member(Effect, Effects),
                 Effect = eff_event(se_engine_error(
                    ee_contract_breach(cap_cache), Site2)),
                 Site2 ^ fs_node = yes(Node),
                 list.member(Term, terminal_nodes(network(P))),
                 Term ^ tn_id = Node
              then yes else no ), !T, !IO)
    else
        check("cap_cache_vs_bytes declares Zone and Reading", no, !T, !IO)
    ).

    % [RTCT.7]: `agenda_cap`. libds reports it and the terminal capacity from
    % one site, `terminal_left_activate`, and a terminal's own capacity
    % survives a drained agenda where this one does not.
    %
:- pred check_agenda_cap(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_agenda_cap(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        find_schema(schemas(P), interns(P), "Zone", Z),
        find_schema(schemas(P), interns(P), "Reading", R)
    then
        engine_intern("a", A, E0, Ea),
        engine_intern("r1", One, Ea, Eb),
        engine_intern("r2", Two, Eb, Ec),
        host_assert(Z, [str(A), float(10.0)], no, _, _, Ec, E1),
        host_assert(R, [str(One), str(A), float(35.0)], no, R1, _, E1, E2),
        host_assert(R, [str(Two), str(A), float(36.0)], no, R2, _, E2, E3),
        check("one activation fits an agenda_cap of one",
            ( if R1 = inserted(_) then yes else no ), !T, !IO),
        check("the second breaches agenda_cap at the activation (RTCT.7)",
            ( if R2 = rejected(cap_agenda) then yes else no ), !T, !IO),
        check("...and the rejected assert left the engine alone",
            ( if engine_fact_count(E3) = 2 then yes else no ), !T, !IO)
    else
        check("cap_agenda_cap declares Zone and Reading", no, !T, !IO)
    ).

    % Firing does free an agenda slot.
    %
:- pred check_agenda_cap_falls_on_firing(program::in, tally::in, tally::out,
                                         io::di, io::uo) is det.

check_agenda_cap_falls_on_firing(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        find_schema(schemas(P), interns(P), "Zone", Z),
        find_schema(schemas(P), interns(P), "Reading", R)
    then
        engine_intern("a", A, E0, Ea),
        engine_intern("r1", One, Ea, Eb),
        engine_intern("r2", Two, Eb, Ec),
        host_assert(Z, [str(A), float(10.0)], no, _, _, Ec, E1),
        host_assert(R, [str(One), str(A), float(35.0)], no, _, _, E1, E2),
        pump(default_budget, _, E2, E3),
        host_assert(R, [str(Two), str(A), float(36.0)], no, R2, _, E3, _E4),
        check("draining the agenda gives the slot back (RTCT.7)",
            ( if R2 = inserted(_) then yes else no ), !T, !IO)
    else
        check("cap_agenda_cap declares Zone and Reading", no, !T, !IO)
    ).

    % Which cap is named when one assert breaches two: `cap_term_vs_agenda`
    % tightens `agenda_cap` and the terminal's capacity to one, so the second
    % reading is over both, and libds names `agenda_cap`. The cap is in the
    % recorded event.
    %
:- pred check_agenda_beats_terminal(program::in, tally::in, tally::out,
                                    io::di, io::uo) is det.

check_agenda_beats_terminal(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        find_schema(schemas(P), interns(P), "Zone", Z),
        find_schema(schemas(P), interns(P), "Reading", R)
    then
        engine_intern("a", A, E0, Ea),
        engine_intern("r1", One, Ea, Eb),
        engine_intern("r2", Two, Eb, Ec),
        host_assert(Z, [str(A), float(10.0)], no, _, _, Ec, E1),
        host_assert(R, [str(One), str(A), float(35.0)], no, _, _, E1, E2),
        host_assert(R, [str(Two), str(A), float(36.0)], no, R2, _, E2, _E3),
        check("agenda_cap is named ahead of the terminal capacity (RTCT.7)",
            ( if R2 = rejected(cap_agenda) then yes else no ), !T, !IO)
    else
        check("cap_term_vs_agenda declares Zone and Reading", no, !T, !IO)
    ).

    % The control for the cap checks: an ordinary bundle carries no
    % RealtimeContract, so `en_contract` is `no` and no cap applies.
    %
:- pred check_no_cap_without_contract(program::in, tally::in, tally::out,
                                      io::di, io::uo) is det.

check_no_cap_without_contract(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Sensor", S) then
        engine_intern("a", A, E0, Ea),
        engine_intern("b", B, Ea, Eb),
        engine_intern("c", C, Eb, Ec),
        host_assert(S, [str(A), float(1.0)], no, _, _, Ec, E1),
        host_assert(S, [str(B), float(2.0)], no, _, _, E1, E2),
        host_assert(S, [str(C), float(3.0)], no, R3, _, E2, E3),
        check("a bundle with no contract has no cap to breach",
            ( if R3 = inserted(_), engine_fact_count(E3) = 3
              then yes else no ), !T, !IO)
    else
        check("06_rule_with_where declares Sensor", no, !T, !IO)
    ).

    % [RTCT.6.3]: a `+realtime` bundle carries its `RealtimeContract`. The
    % fixtures are crafted from a
    % compiled artefact, not compiled, so they are pinned here rather than in
    % the MANIFEST. libds refuses `75_nodsrt` with `[-711] +realtime DSC
    % missing RealtimeContract atom`; `76_nodsrt_stale` is refused on its
    % hash, read first ([RDSC.3.6]). `test_realtime_fixtures`, which calls
    % this, is not called.
    %
:- pred check_realtime_contract(tally::in, tally::out, io::di, io::uo) is det.

check_realtime_contract(!T, !IO) :-
    refuses("75_nodsrt.dsc",
        "a +realtime bundle with no RealtimeContract is refused (RTCT.6.3)",
        lek_contract_missing, "RTCT.6.3", !T, !IO),
    % The same strip with the hash left stale: refused on the hash, which is
    % read first ([RDSC.3.6]).
    refuses("76_nodsrt_stale.dsc",
        "...and its stale-hash twin is refused on the hash (RDSC.3.6)",
        lek_semantic, "RDSC.3.6", !T, !IO),
    % [RTCT.6.5]: a malformed payload is DS_ERR_CONTRACT_INVALID. The
    % RealtimeContract's body is four bytes short, with both length prefixes
    % rewritten so the frame stays well-formed. libds answers `[-712]
    % RealtimeContract: protobuf decode failed`, not 75_nodsrt's -711.
    refuses("77_baddsrt.dsc",
        "a RealtimeContract that will not decode is refused (RTCT.6.5)",
        lek_contract_invalid, "RTCT.6.5", !T, !IO),

    % [RTCT.6.5]: the stored `rt_config_sha256` is cross-checked against a
    % recomputation over the materialized logical contract ([RBND.4b.8]).
    % One byte of the stored value is flipped, so the body decodes and only
    % the comparison fails. It is checked at commit, not at the atom: the
    % recomputation needs the resolved network, and [RTCT.6.4] puts the
    % RealtimeContract before the first per-module group. libds answers
    % `[-712] RealtimeContract: rt_config_sha256 disagrees with recomputed
    % canonical hash`.
    refuses("78_rtsha.dsc",
        "a RealtimeContract whose stored hash disagrees is refused (RTCT.6.5)",
        lek_contract_invalid, "RTCT.6.5", !T, !IO),

    % [RTCT.7] at load: the two caps the artefact's own strings breach. A
    % bundle's schema names, rule names and string literals are interned
    % while it loads, so libds refuses both at load (`[-710] intern: contract
    % intern_cap exceeded`). `lek_contract_breach`, not
    % `lek_contract_invalid`: the contract is well formed and the artefact
    % does not fit inside it.
    refuses("cap_intern_cap.dsc",
        "an artefact exceeding its own intern_cap is refused (RTCT.7)",
        lek_contract_breach(cap_intern), "RTCT.7", !T, !IO),
    refuses("cap_intern_bytes_cap.dsc",
        "...and its intern_bytes_cap, counted separately",
        lek_contract_breach(cap_intern_bytes), "RTCT.7", !T, !IO),

    % The control: a `+realtime` bundle with its contract loads.
    with_fixture("74_realtime.dsc",
        (pred(P::in, !.T2::in, !:T2::out, !.IO2::di, !:IO2::uo) is det :-
            check("a +realtime bundle WITH its RealtimeContract loads",
                ( if list.member(at_realtime_contract, atoms(P)) then yes else no ),
                !T2, !IO2)),
        !T, !IO).

    % Load a fixture expecting a refusal of a named kind and clause.
    %
:- pred refuses(string::in, string::in, load_error_kind::in, string::in,
                tally::in, tally::out, io::di, io::uo) is det.

refuses(Name, What, Kind, Clause, !T, !IO) :-
    read_bitmap("fixtures/" ++ Name, Res, !IO),
    (
        Res = yes(BM),
        check(What,
            ( if load_dsc(BM, load_failed(E)),
                 E ^ le_kind = Kind,
                 clause_id_string(E ^ le_clause) = Clause
              then yes else no ), !T, !IO)
    ;
        Res = no,
        check(What ++ " (fixture unreadable)", no, !T, !IO)
    ).

    % The fire guard the compiler writes: every [LCDB.3.3] decision about
    % which values key a cooldown is made before the artefact is written, so
    % the runtime evaluates a call and walks no pattern.
    %
:- pred check_rate_guard(program::in, tally::in, tally::out,
                         io::di, io::uo) is det.

check_rate_guard(P, !T, !IO) :-
    IT = interns(P),
    list.foldl(dump_guard(IT), rule_metas(P), !IO),

    check("a rule with no rate modifier has NO fire guard",
        ( if guard_of(IT, P, "plain") = no then yes else no ), !T, !IO),

    % `Sensor` is `entity_id: String key` and `reading: Int mutable`, and the
    % guard binds one key value ([LCDB.3.3.1]: the declared `key` slots, not
    % every bound slot), so a churning `reading` cannot reset the cooldown.
    check("a cooldown lowers to rate_allow(name, ONE key value, cool)",
        ( if guard_of(IT, P, "cooled") = yes(e_call(fn_rate_allow, CoolArgs)),
             CoolArgs = [e_lit(str(_)), e_slot(_, _), e_lit(int(30000000000i64))]
          then yes else no ), !T, !IO).

:- func guard_of(intern_table, program, string) = maybe(expr) is semidet.

guard_of(IT, P, Name) = Meta ^ rm_fire_guard :-
    list.find_first_match(named_rule(IT, Name), rule_metas(P), Meta).

:- pred named_rule(intern_table::in, string::in, rule_meta::in) is semidet.

named_rule(IT, Name, Meta) :-
    expand(IT, Meta ^ rm_name, Name).

:- pred dump_guard(intern_table::in, rule_meta::in, io::di, io::uo) is det.

dump_guard(IT, Meta, !IO) :-
    ( if expand(IT, Meta ^ rm_name, Name) then N = Name else N = "?" ),
    io.format("  note: guard %s = %s\n",
        [s(N), s(string(Meta ^ rm_fire_guard))], !IO).

    % [NLFC.1.2] -- the run id and tier id are the integrator's, and an empty
    % string is the same as giving none: `yes("")` reads back `no`, as libds's
    % getters answer NULL for a "". Any fixture will do; the ids are engine
    % configuration, not artefact content.
    %
:- pred check_run_and_tier_ids(program::in, tally::in, tally::out,
                               io::di, io::uo) is det.

check_run_and_tier_ids(P, !T, !IO) :-
    E0 = init_engine(P),
    check("a fresh engine has no run id and no tier id",
        ( if run_id(E0) = no, tier_id(E0) = no then yes else no ), !T, !IO),
    set_run_id(yes("r1"), R1, E0, E1),
    set_tier_id(yes("t1"), T1, E1, E2),
    check("the ids given are the ids read back",
        ( if R1 = id_set, T1 = id_set,
             run_id(E2) = yes("r1"), tier_id(E2) = yes("t1")
          then yes else no ), !T, !IO),
    set_run_id(yes(""), R3, E2, E3),
    set_tier_id(yes(""), T3, E3, E4),
    check("an id given as \"\" reads back absent",
        ( if R3 = id_set, T3 = id_set, run_id(E4) = no, tier_id(E4) = no
          then yes else no ), !T, !IO),
    check_nlfc_1_2_ids(E0, !T, !IO).

    % [NLFC.1.2], [LSTR.8.5]: a run id or tier id that is not
    % well-formed UTF-8 is refused, `id_encoding`, and the engine keeps what
    % it had, as libds's `ds_engine_new` refuses it with DS_ERR_ENCODING and
    % creates no engine. An encoded surrogate (`r` ED A0 80) and a lone C0,
    % each as either id; and a well-formed non-ASCII id (`r` C3 A9, "ré")
    % read back as given. libds is held to the same bytes (test_fact_stamps.c,
    % test_nlfc_1_2__ill_formed_run_id_is_refused and _tier_id_).
    %
% @spec [LSTR.8.5]
:- pred check_nlfc_1_2_ids(engine::in, tally::in, tally::out,
                           io::di, io::uo) is det.

check_nlfc_1_2_ids(E0, !T, !IO) :-
    Ill = [{"an encoded surrogate", [0x72, 0xED, 0xA0, 0x80]},
           {"a lone C0", [0xC0]}],
    list.foldl2(
        ( pred(Case::in, T0::in, T1::out, IO0::di, IO1::uo) is det :-
            Case = {Label, Units},
            ( if string.from_code_unit_list_allow_ill_formed(Units, Bad) then
                set_run_id(yes(Bad), RR, E0, ER),
                set_tier_id(yes(Bad), RT, E0, ET),
                check("[LSTR.8.5] a run_id holding " ++ Label
                        ++ " is refused, and the engine keeps no run id",
                    ( if RR = id_encoding, run_id(ER) = no then yes else no ),
                    T0, T0a, IO0, IO0a),
                check("[LSTR.8.5] a tier_id holding " ++ Label
                        ++ " is refused, and the engine keeps no tier id",
                    ( if RT = id_encoding, tier_id(ET) = no then yes else no ),
                    T0a, T1, IO0a, IO1)
            else
                check("[LSTR.8.5] the ill-formed id " ++ Label
                        ++ " could be built", no, T0, T1, IO0, IO1)
            )
        ), Ill, !T, !IO),
    ( if string.from_code_unit_list_allow_ill_formed([0x72, 0xC3, 0xA9], Re)
    then
        set_run_id(yes(Re), RRe, E0, ERe),
        set_tier_id(yes(Re), TRe, ERe, ERe2),
        check("[LSTR.8.5] a well-formed non-ASCII id is accepted, as given",
            ( if RRe = id_set, TRe = id_set,
                 run_id(ERe2) = yes(Re), tier_id(ERe2) = yes(Re)
              then yes else no ), !T, !IO)
    else
        check("[LSTR.8.5] the id \"ré\" could be built", no, !T, !IO)
    ).

    % [RFCS.4] -- the session header a host reads, libds's
    % `ds_engine_get_session_header`: this runtime's DS version, the
    % artefact's own `dsc_sha256`, and the ids the engine was given, "" for
    % one not given. What libds answers for the same engine is checked by the
    % lockstep recordings comparison, since a recording's `StreamHeader` is this value;
    % that comparison sees only scenarios, which give no ids, so the ids are
    % checked here.
    %
:- pred check_session_header(program::in, tally::in, tally::out,
                             io::di, io::uo) is det.

check_session_header(P, !T, !IO) :-
    E0 = init_engine(P),
    H0 = session_header(E0),
    check("[RFCS.4] the session header carries this runtime's DS version",
        ( if H0 ^ sm_ds_version = ds.version.ds_version then yes else no ),
        !T, !IO),
    check("[RFCS.4.5] and the artefact's own dsc_sha256, all 32 bytes",
        ( if H0 ^ sm_dsc_hash = header(P) ^ dh_sha256,
             list.length(H0 ^ sm_dsc_hash) = 32
          then yes else no ), !T, !IO),
    check("[RFCS.4.3] [RFCS.4.4] and \"\" for a run id and tier id not given",
        ( if H0 ^ sm_session = "", H0 ^ sm_tier = "" then yes else no ),
        !T, !IO),
    set_run_id(yes("r1"), _, E0, E1),
    set_tier_id(yes("t1"), _, E1, E2),
    H2 = session_header(E2),
    check("and the run id and tier id once given",
        ( if H2 ^ sm_session = "r1", H2 ^ sm_tier = "t1" then yes else no ),
        !T, !IO).

    % [NMET.4.1]: each metric in all four fields its row states, and in count
    % and order, as libds's own suite checks them
    % (`test_nmet_4_4_owed_metrics.c`). Where each sits among libds's events
    % and callbacks is the differential's: every scenario's trace carries the
    % metric lines. On `06_rule_with_where` (Sensor, keyed on `entity_id`;
    % `kitchen_high` logs above 75):
    %
    %   advance 1 s     `ds.clock.advance_total`, and nothing else
    %   assert kitchen  the first sample's tick, then the FactAssert: each
    %                   dispatch counted before its event, the tick counted
    %                   after it
    %   the same again  a no-op: counted, and its FactAssert dispatched
    %   pump            the boundary, then the four intern gauges before the
    %                   firing; every entry pinned, no arena
    %
:- pred check_metrics(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_metrics(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Sensor", S) then
        advance(duration_from_ns(1000000000u64), AdvFx, E0, E1),
        check("[NMET.4.1] an advance counts ds.clock.advance_total, once",
            ( if AdvFx = [eff_metric(metric("ds.clock.advance_total",
                    mk_counter, 1.0, []))]
              then yes else no ), !T, !IO),
        engine_intern("kitchen", K, E1, E2),
        host_assert(S, [str(K), float(80.0)], no, _, AssertFx, E2, E3),
        check("[NMET.4.1] a dispatch counts its kind before the event, the "
                ++ "tick after it",
            ( if AssertFx = [
                    eff_metric(metric("ds.recorder.events_emitted_total",
                        mk_counter, 1.0, [{"kind", "tick"}])),
                    eff_event(se_clock_tick(_, _)),
                    eff_metric(metric("ds.clock.tick_total", mk_counter, 1.0,
                        [])),
                    eff_metric(metric("ds.recorder.events_emitted_total",
                        mk_counter, 1.0, [{"kind", "fact_assert"}])),
                    eff_event(se_fact_assert(_, _, _, _))]
              then yes else no ), !T, !IO),
        host_assert(S, [str(K), float(80.0)], no, Noop, NoopFx, E3, E4),
        check("[NMET.4.1] a suppressed reassertion is counted, with its schema",
            ( if
                Noop = noop(_),
                NoopFx = [
                    eff_metric(metric(
                        "ds.facts.noop_reassert_suppressed_total",
                        mk_counter, 1.0, [{"schema", "Sensor"}])),
                    eff_metric(metric("ds.recorder.events_emitted_total",
                        mk_counter, 1.0, [{"kind", "fact_assert"}])),
                    eff_event(se_fact_assert(_, _, _, _))]
              then yes else no ), !T, !IO),
        pump(default_budget, PumpFx, E4, _),
        Gauges = list.filter_map(
            ( func(Ef) = M is semidet :-
                Ef = eff_metric(M), M ^ m_kind = mk_gauge ), PumpFx),
        check("[NMET.4.1] [NMET.4.7] a pump reads the four intern gauges, in "
                ++ "libds's order, every entry pinned and no arena",
            ( if
                list.map((func(M) = M ^ m_name), Gauges) = [
                    "ds.intern.entries", "ds.intern.bytes",
                    "ds.intern.pinned_entries",
                    "ds.intern.arena_high_water_bytes"],
                Gauges = [Entries, _, Pinned, Arena],
                Pinned ^ m_value = Entries ^ m_value,
                Arena ^ m_value = 0.0,
                list.all_true((pred(M::in) is semidet :- M ^ m_labels = []),
                    Gauges)
              then yes else no ), !T, !IO),
        check("[NMET.4.1] ...after the boundary and before the firing",
            ( if
                precedes_str(effect_names(PumpFx), "pump", "LHS"),
                list.index0(PumpFx, 1, Boundary),
                Boundary = eff_event(se_pump_boundary),
                list.index0(PumpFx, 2, AfterBoundary),
                AfterBoundary = eff_metric(First),
                First ^ m_name = "ds.intern.entries"
              then yes else no ), !T, !IO)
    else
        check("06_rule_with_where declares Sensor", no, !T, !IO)
    ).

    % [NDBG.4.2], [NDBG.4.3]: the two introspection reads, on
    % `131_introspection`: `high` (an alpha filter, `level > 50`) and `any`
    % over Reading, and Noise in no pattern. What libds answers for the same
    % program is compared by the differential (`103_introspection`); this
    % pins this runtime's answer by itself, so a failure says which side.
    %
:- pred check_introspection_reads(program::in, tally::in, tally::out,
                                  io::di, io::uo) is det.

check_introspection_reads(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        find_schema(schemas(P), interns(P), "Reading", Reading),
        find_schema(schemas(P), interns(P), "Noise", Noise)
    then
        host_assert(Reading, [int(1i64), int(10i64)], no_deadline, R1, _,
            E0, E1),
        host_assert(Reading, [int(2i64), int(90i64)], no_deadline, R2, _,
            E1, E2),
        pump(default_budget, _, E2, E3),
        L3 = engine_refracted_activations(E3, no),
        check("[NDBG.4.3] three fired matches are listed, `high`'s first "
                ++ "(terminal ordinal)",
            ( if list.map((func(R) = R ^ ra_rule), L3) = ["high", "any", "any"]
              then yes else no ), !T, !IO),
        check("each entry names its reason, the fixed detail and one fact",
            ( if
                list.all_true(
                    ( pred(R::in) is semidet :-
                        R ^ ra_reason = "refraction",
                        R ^ ra_detail = "fired, and not re-created since",
                        R ^ ra_facts = [_] ),
                    L3)
              then yes else no ), !T, !IO),
        check("the rule filter keeps one rule's entries",
            ( if engine_refracted_activations(E3, yes("high")) = [_]
              then yes else no ), !T, !IO),
        ( if R1 = inserted(Id1), R2 = inserted(Id2) then
            T1 = engine_rete_match_trace(E3, Id1),
            T2 = engine_rete_match_trace(E3, Id2),
            list.sort(list.map((func(S) = S ^ ts_result), T1), Results1),
            check("[NDBG.4.2] Reading 1 (level 10) is filtered by one alpha "
                    ++ "and passed by the other",
                ( if Results1 = ["filtered", "passed"] then yes else no ),
                !T, !IO),
            check("and Reading 2 (level 90) passes both",
                ( if list.map((func(S) = S ^ ts_result), T2) = ["passed", "passed"]
                  then yes else no ), !T, !IO),
            check("[NDBG.4.1] every traced node is named by a decimal node_id",
                ( if
                    list.all_true(
                        ( pred(S::in) is semidet :-
                            string.to_int(S ^ ts_node, _),
                            S ^ ts_kind = "alpha" ),
                        T1 ++ T2)
                  then yes else no ), !T, !IO),
            check("the filtered row names the filter as libds formats it",
                ( if
                    list.member(Row, T1),
                    Row ^ ts_result = "filtered",
                    Row ^ ts_detail = "alpha filter failed: level > 50"
                  then yes else no ), !T, !IO),
            host_assert(Noise, [int(1i64)], no_deadline, _, _, E3, E4),
            pump(default_budget, _, E4, E5),
            check("[IRET.11.3.2] an unrelated assert and a pump boundary "
                    ++ "remove nothing",
                ( if engine_refracted_activations(E5, no) = [_, _, _]
                  then yes else no ), !T, !IO),
            host_retract(Id2, _, E5, E6),
            pump(default_budget, _, E6, E7),
            check("retracting Reading 2 ends both its matches, and only "
                    ++ "Reading 1's `any` entry is left",
                ( if
                    engine_refracted_activations(E7, no) = [Only],
                    Only ^ ra_rule = "any",
                    Only ^ ra_facts = [Id1]
                  then yes else no ), !T, !IO),
            check("a retracted fact traces nothing",
                ( if engine_rete_match_trace(E7, Id2) = [] then yes else no ),
                !T, !IO)
        else
            check("premise: both Readings were inserted", no, !T, !IO)
        )
    else
        check("premise: the fixture declares Reading and Noise", no, !T, !IO)
    ).

    % `ds_engine_mem` ([NDBG.2.1]): the half the differential
    % cannot see. Scenarios `104_mem_network` and `105_mem_interns` compare
    % the logical counts with libds's. The byte fields and the intern fields
    % are implementation-defined ([NDBG.2.1], [NMET.4.7]), so this runtime's
    % own are pinned here and compared with nothing: the layout-sized byte
    % fields are 0 by choice (`mem-layout-bytes`), `total_bytes` is the sum of
    % what is reported, and the intern table is this runtime's
    % (`mem-intern-set`).
    %
:- pred check_engine_mem(program::in, tally::in, tally::out,
                         io::di, io::uo) is det.

check_engine_mem(P, !T, !IO) :-
    M = engine_mem(init_engine(P)),
    check("[NDBG.2.1] every layout-sized byte field is 0 (mem-layout-bytes)",
        ( if
            M ^ em_wm_fact_bytes = 0, M ^ em_wm_index_bytes = 0,
            M ^ em_alpha_index_bytes = 0, M ^ em_beta_token_bytes = 0,
            M ^ em_beta_index_bytes = 0, M ^ em_intern_index_bytes = 0,
            M ^ em_pool_reserved_bytes = 0
          then yes else no ), !T, !IO),
    check("[NDBG.2.1] total_bytes is the sum of the byte fields reported",
        ( if
            M ^ em_total_bytes = M ^ em_intern_string_bytes,
            M ^ em_intern_string_bytes > 0
          then yes else no ), !T, !IO),
    check("[NDBG.2.1] the network counts are the artefact's, not zero",
        ( if
            M ^ em_alpha_node_count > 0, M ^ em_beta_node_count > 0,
            M ^ em_intern_count > 0
          then yes else no ), !T, !IO).

    % [LTAC.3.5]'s capture fact: two parent activations arm two timers, each
    % with its own `ds_gensym` correlation and capture, and each follow-up
    % logs its own zone once.
    %
:- pred check_after_capture(program::in, tally::in, tally::out,
                            io::di, io::uo) is det.

check_after_capture(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Motion", Motion) then
        host_assert(Motion, [int(1i64)], no, _, _, E0, E1),
        host_assert(Motion, [int(2i64)], no, _, _, E1, E2),
        pump(default_budget, _, E2, E3),
        advance(duration_from_ns(301000000000u64), _, E3, E4),
        pump(default_budget, Deferred, E4, E5),
        Logs = list.sort(list.filter_map(capture_log_text, Deferred)),
        io.format("  note: after-capture follow-ups logged %s, %d live\n",
            [s(string(Logs)), i(live_count(engine_wm(E5)))], !IO),
        check("[LTAC.3.5] each follow-up reads its own activation's capture",
            ( if Logs = ["off 1", "off 2"] then yes else no ), !T, !IO),
        check("and retracts its timer and its capture",
            ( if live_count(engine_wm(E5)) = 3 then yes else no ), !T, !IO)
    else
        check("95_after_capture declares Motion", no, !T, !IO)
    ).

:- func capture_log_text(effect) = string is semidet.

capture_log_text(eff_event(se_log_emitted(_, Text))) = Text.

    % The `$ClockTick` cycle, which makes an `after` clause fire. [LTAC]'s
    % deferred body lands on a follow-up terminal joining the synthesised
    % timer against a clock tick, with a `fire_at <= now` guard. The tick is
    % a new fact each pump: refraction is per-token, so a fresh tick makes a
    % fresh token and the terminal re-checks its guard. Pinned at the engine,
    % since `ds.schema.synthetic` keeps the tick out of the trace.
    %
:- pred check_clock_tick(program::in, tally::in, tally::out,
                         io::di, io::uo) is det.

check_clock_tick(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Trig", Trig) then
        host_assert(Trig, [int(1i64)], no, _, _, E0, E1),
        pump(default_budget, _, E1, E2),
        Live1 = live_count(engine_wm(E2)),
        Seen1 = engine_fact_count(E2),
        pump(default_budget, _, E2, E3),
        Live2 = live_count(engine_wm(E3)),
        Seen2 = engine_fact_count(E3),
        io.format("  note: after one pump = %d live / %d seen; " ++
                  "after two = %d live / %d seen\n",
            [i(Live1), i(Seen1), i(Live2), i(Seen2)], !IO),

        % Trig, the armed timer, and a tick.
        check("a pump asserts a `$ClockTick` fact",
            ( if Live1 = 3 then yes else no ), !T, !IO),

        % One tick, not two: the second pump retracts the first.
        check("and a second pump CYCLES it rather than accumulating",
            ( if Live2 = 3 then yes else no ), !T, !IO),

        % The timer and the tick are compiler-synthesised, so the integrator's
        % count is Trig alone, as libds's `fact_count()` reports it.
        check("neither is visible in the integrator's fact count",
            ( if Seen1 = 1, Seen2 = 1 then yes else no ), !T, !IO),

        % `28_after_timer`'s shape, assert / pump / advance / pump: the
        % deferral clears on the pump right after the advance. `after 5_min`,
        % so 301 seconds clears it: the follow-up fires, and its
        % `ds_retract_token_fact` drops the timer at the end of its own RHS.
        advance(duration_from_ns(301000000000u64), _, E2, E4),
        pump(default_budget, Deferred, E4, E5),
        io.format("  note: past the deferral = %s, %d live\n",
            [s(string(effect_names(Deferred))), i(live_count(engine_wm(E5)))],
            !IO),

        check("past the deferral the follow-up fires",
            ( if list.member("log", effect_names(Deferred))
              then yes else no ), !T, !IO),

        check("and it retracts its own timer, so it fires once",
            ( if live_count(engine_wm(E5)) = 2 then yes else no ), !T, !IO)
    else
        check("51_after declares Trig", no, !T, !IO)
    ).

:- pred check_where(program::in, tally::in, tally::out, io::di, io::uo) is det.

check_where(P, !T, !IO) :-
    N = network(P),
    note_shape("06_rule_with_where", P, !IO),

    check("a rule with a `where` clause loads", yes, !T, !IO),

    % `s.state > 75` and `s.entity_id == "kitchen"` each compare this
    % pattern's own slot to a literal, so both lower onto the alpha.
    check("its predicates ARE alpha tests -- both conjuncts hoisted",
        ( if alpha_nodes(N) = [A | _],
             list.length(A ^ an_tests, 2)
          then yes else no ), !T, !IO),

    check("so the beta carries no join test at all",
        ( if list.filter(has_join_tests, beta_nodes(N)) = []
          then yes else no ), !T, !IO),

    % The operators survive the split: one equality, one greater-than.
    check("an EQ and a CMP, not two of a kind",
        ( if alpha_nodes(N) = [A2 | _],
             list.filter(is_eq_test, A2 ^ an_tests) = [_],
             list.filter(is_cmp_test, A2 ^ an_tests) = [_]
          then yes else no ), !T, !IO),

    % The string literal went through the intern table like every other name.
    check("and its string literal was interned",
        ( if alpha_nodes(N) = [A3 | _],
             list.member(at_eq(_, al_string(Ref3)), A3 ^ an_tests),
             expand(interns(P), Ref3, "kitchen")
          then yes else no ), !T, !IO).

:- pred is_eq_test(alpha_test::in) is semidet.

is_eq_test(at_eq(_, _)).

:- pred is_cmp_test(alpha_test::in) is semidet.

is_cmp_test(at_cmp(_, _, _)).

    % Whether an expression holds a given interned string literal.
    %
:- pred expr_has_interned_string(expr::in, intern_table::in, string::in)
    is semidet.

expr_has_interned_string(E, IT, Want) :-
    (
        E = e_lit(str(Ref)),
        expand(IT, Ref, Want)
    ;
        E = e_binop(_, L, R),
        ( expr_has_interned_string(L, IT, Want)
        ; expr_has_interned_string(R, IT, Want) )
    ;
        E = e_unop(_, Operand),
        expr_has_interned_string(Operand, IT, Want)
    ;
        E = e_call(_, Args),
        list.member(Arg, Args),
        expr_has_interned_string(Arg, IT, Want)
    ).

:- pred check_negation(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_negation(P, !T, !IO) :-
    N = network(P),
    note_shape("09_negation_and_within", P, !IO),

    check("`no Override o` lowers to a NEGATIVE beta node",
        ( if list.filter(is_negative_beta, beta_nodes(N)) = [_ | _]
          then yes else no ), !T, !IO),

    % `DoorOpen d then Motion m` is a left-associative beta chain, so the
    % second beta's left parent is the first -- the forward reference
    % [RDSC.4a.5] does NOT guarantee an ordering for, resolved against a real
    % artefact rather than a hand-built one.
    check("`then` lowers to a beta CHAIN -- a beta whose left parent is a beta",
        ( if list.filter(is_chained_beta, beta_nodes(N)) = [_ | _]
          then yes else no ), !T, !IO),

    check("and that parent resolved to a NODE, not an id",
        ( if list.filter(is_chained_beta, beta_nodes(N)) = [B | _],
             B ^ bn_parent = yes(Parent),
             list.member(Parent, beta_nodes(N))
          then yes else no ), !T, !IO),

    % Every chain still bottoms out at a root, which is what the loader seeds
    % with a nil token [RDSC.4a.7]. Two rules, so at least two roots.
    check("every chain still bottoms out at a root beta to seed",
        ( if root_betas(N) = [_, _ | _] then yes else no ), !T, !IO),

    check("two rules give two terminals",
        ( if terminal_nodes(N) = [_, _] then yes else no ), !T, !IO).
%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% Actions and expressions, decoded
%-----------------------------------------------------------------------------%
%
% `07_action_verbs` is one rule with every RHS verb, so it exercises every
% `A*` atom in one artefact. `20_json_path_probe` isolates the multi-segment
% JSON chain.

:- pred verb_name(action::in, string::out) is det.

verb_name(a_emit(_, _, _, _), "emit").
verb_name(a_publish(_, _), "publish").
verb_name(a_call(_, _, _, _), "call").
verb_name(a_cache_set(_, _, _), "cache_set").
verb_name(a_cache_delete(_), "cache_delete").
verb_name(a_log(_, _), "log").

    % Actions the compiler lowers in, which no author writes, are named with
    % a `!` prefix.
verb_name(a_bind(_, _), "!bind").
verb_name(a_retract_token_fact(_), "!retract_token_fact").
verb_name(a_retract_corr(_), "!retract_corr").
verb_name(a_hydration_call(_, _, _, _, _), "!hydration_call").
verb_name(a_withdraw(_), "withdraw").
verb_name(a_withdraw_by_id(_), "withdraw").
verb_name(a_operands_not_admitted(_, _, _), "!operands_not_admitted").

:- pred test_actions(tally::in, tally::out, io::di, io::uo) is det.

test_actions(!T, !IO) :-
    with_fixture("09_negation_and_within.dsc", check_message_expr, !T, !IO),
    with_fixture("42_interp_slot.dsc", check_slot_expr, !T, !IO),
    with_fixture("40_format_vectors.dsc", check_format_specs, !T, !IO),
    with_fixture("43_interp_call.dsc", check_call_action, !T, !IO),
    with_fixture("44_corr_static.dsc", check_call_action, !T, !IO),
    with_fixture("46_call_order.dsc", check_call_kwargs, !T, !IO),
    with_fixture("07_action_verbs.dsc", check_verbs, !T, !IO),
    with_fixture("20_json_path_probe.dsc", check_json_chain, !T, !IO),
    with_fixture("20_json_path_probe.dsc", check_json_limits, !T, !IO),
    with_fixture("20_json_path_probe.dsc", check_lstr_8_5_host_text, !T, !IO),
    with_fixture("148_refusal_order.dsc", check_nfct_2_11_refusal_order, !T,
        !IO),
    with_fixture("47_emit_softfail.dsc", check_nfct_2_11_halted, !T, !IO),
    with_fixture("06_rule_with_where.dsc", check_where_rhs, !T, !IO),
    with_fixture("08_let_bindings.dsc", check_let_bindings, !T, !IO).

    % `log critical "door open at {d.zone}"` decodes as an `e_interp` of a
    % literal and a slot read.
    %
:- pred check_message_expr(program::in, tally::in, tally::out,
                           io::di, io::uo) is det.

check_message_expr(P, !T, !IO) :-
    Lists = action_lists(P),
    Actions = list.condense(list.map(snd_of, Lists)),
    Msgs = list.filter_map(log_message, Actions),
    io.format("  note: log message exprs = %s\n",
        [s(string(Msgs))], !IO),
    check("every interpolated log message decodes as an interpolation",
        ( if Msgs = [_ | _],
             list.all_true(is_interp, Msgs)
          then yes else no ), !T, !IO).

:- pred is_interp(expr::in) is semidet.

is_interp(e_interp([_ | _])).

:- func snd_of(pair(T, list(action))) = list(action).

snd_of(_ - As) = As.

:- func log_message(action) = expr is semidet.

log_message(a_log(_, M)) = M.

    % `emit Tagged logical label: "{r.zone}-{r.level:03d}" ...` arrives as an
    % `e_interp` holding a `ValuePrim`; its slot expressions are printed.
    %
:- pred check_slot_expr(program::in, tally::in, tally::out,
                        io::di, io::uo) is det.

check_slot_expr(P, !T, !IO) :-
    Actions = list.condense(list.map(snd_of, action_lists(P))),
    Slots = list.condense(list.filter_map(emit_slots, Actions)),
    io.format("  note: interpolated slot exprs = %s\n",
        [s(string(Slots))], !IO),
    check("an interpolating emit carries an interpolation with a value inside",
        ( if list.member(slot_assign(_, e_interp(Prims)), Slots),
             list.member(fp_value(_), Prims)
          then yes else no ), !T, !IO).

:- func emit_slots(action) = list(slot_assign) is semidet.

emit_slots(a_emit(_, Slots, _, _)) = Slots.

    % Every primitive the compiler emitted, printed as it arrives off the
    % wire: `40_format_vectors.ds` writes an interpolation site for each part
    % of [LGRA.2.9.6.1]'s grammar.
    %
:- pred check_format_specs(program::in, tally::in, tally::out,
                           io::di, io::uo) is det.

check_format_specs(P, !T, !IO) :-
    Actions = list.condense(list.map(snd_of, action_lists(P))),
    Prims = list.condense(list.map(format_specs_of, Actions)),
    io.format("  note: compiler-emitted primitives = %s\n",
        [s(string(Prims))], !IO),
    check("the fixture carries value primitives",
        ( if list.member(fp_value(_), Prims) then yes else no ), !T, !IO),
    check("the fixture carries time primitives",
        ( if list.member(fp_time(_, _), Prims) then yes else no ), !T, !IO).

    % The whole call action, decoded and printed.
    %
:- pred check_call_action(program::in, tally::in, tally::out,
                          io::di, io::uo) is det.

check_call_action(P, !T, !IO) :-
    Actions = list.condense(list.map(snd_of, action_lists(P))),
    Calls = list.filter(is_call, Actions),
    io.format("  note: decoded ACAL = %s\n", [s(string(Calls))], !IO),
    check("the fixture carries a call action",
        ( if Calls = [_ | _] then yes else no ), !T, !IO).

:- pred is_call(action::in) is semidet.

is_call(a_call(_, _, _, _)).

    % [RLOW.7.3.1], [RDSC.4a.9.4]: the compiler sorts a call's kwargs by
    % name. `46_call_order.ds` writes `mid, zeta, alpha`; the runtimes take
    % the wire order without sorting again.
    %
:- pred check_call_kwargs(program::in, tally::in, tally::out,
                          io::di, io::uo) is det.

check_call_kwargs(P, !T, !IO) :-
    Actions = list.condense(list.map(snd_of, action_lists(P))),
    Names = list.condense(list.filter_map(call_kwarg_names, Actions)),
    io.format("  note: FN_CALL kwarg order on the wire = %s\n",
        [s(string(Names))], !IO),
    check("RLOW.7.3.1: the call's kwargs arrive sorted by name -- the "
            ++ "compiler sorted them, not the source's `mid, zeta, alpha`",
        ( if Names = ["alpha", "mid", "zeta"] then yes else no ), !T, !IO).

:- func call_kwarg_names(action) = list(string) is semidet.

call_kwarg_names(a_call(_, _, Kwargs, _)) =
    list.map(fst_of, kwarg_list(Kwargs)).

:- func fst_of(pair(string, expr)) = string.

fst_of(N - _) = N.

    % `-` for an empty correlation, as libds's half of the trace prints it;
    % every call carries one ([LCRS.3.1]). A computed correlation prints as
    % `<computed>`: its value is known only at the fire.
    %
:- func correlation_text(intern_table, correlation) = string.

correlation_text(IT, correlated(Ref)) = Text :-
    Name = name_of(IT, Ref),
    ( if Name = "" then Text = "-" else Text = Name ).
correlation_text(_, correlated_expr(_)) = "<computed>".

    % A call's typed arguments on a trace line: `{"name":value,...}` in their
    % order, scalars in DS's canonical text, a Json value as its canonical
    % text, Bytes as a lower-case hex string. `trace_libds.py` renders pyds's
    % `args` the same way; a disagreement is a diff line, as it should be.
    %
:- func trace_args(list(arg)) = string.

trace_args(Args) =
    "{" ++ string.join_list(",", list.map(trace_arg, Args)) ++ "}".

:- func trace_arg(arg) = string.

trace_arg(arg(Name, V)) = json_string(Name) ++ ":" ++ trace_arg_value(V).

:- func trace_arg_value(arg_value) = string.

trace_arg_value(av_int(I)) = bare_int(I).
trace_arg_value(av_float(F)) = bare_float(F).
trace_arg_value(av_string(S)) = json_string(S).
trace_arg_value(av_bool(B)) = bare_bool(B).
trace_arg_value(av_json(T)) = T.
trace_arg_value(av_bytes(Bs)) =
    json_string(string.append_list(list.map(
        (func(B) = string.format("%02x", [i(uint8.cast_to_int(B))])), Bs))).
trace_arg_value(av_null) = "null".
trace_arg_value(av_fact_ref(_)) = "\"<fact>\"".
trace_arg_value(av_encoded_fact(FE)) =
    % The FactExternal's bytes, so the differential compares the two
    % runtimes' encodings of one fact byte for byte.
    ( if encode_fact_external(FE, Bytes) then
        json_string("fact:" ++ hex(Bytes))
    else
        "\"<unencodable fact>\""
    ).

    % A publish's FactExternal on a trace line, spelled as a fact call
    % argument's is (`trace_arg_value`), and as `trace_libds.py` spells the
    % libds event's `external`.
    %
:- func published_external(maybe(fact_external)) = string.

published_external(no) = "-".
published_external(yes(FE)) =
    ( if encode_fact_external(FE, Bytes) then
        "fact:" ++ hex(Bytes)
    else
        "<unencodable fact>"
    ).

:- func format_specs_of(action) = list(format_prim).

format_specs_of(A) = Prims :-
    ( if A = a_log(_, E) then
        Prims = specs_in(E)
    else if A = a_emit(_, Slots, _, _) then
        Prims = list.condense(list.map(specs_in_assign, Slots))
    else
        Prims = []
    ).

:- func specs_in_assign(slot_assign) = list(format_prim).

specs_in_assign(slot_assign(_, E)) = specs_in(E).

:- func specs_in(expr) = list(format_prim).

specs_in(E) = Prims :-
    ( if untainted(E) = e_interp(Ps) then
        Prims = list.filter((pred(P::in) is semidet :- P \= fp_text(_)), Ps)
    else
        Prims = []
    ).

:- pred check_verbs(program::in, tally::in, tally::out, io::di, io::uo) is det.

check_verbs(P, !T, !IO) :-
    Lists = action_lists(P),
    ( if Lists = [_ - As] then Actions = As else Actions = [] ),
    io.format("  note: 07_action_verbs actions = %s\n",
        [s(string(list.map(verb_name_of, Actions)))], !IO),

    check("the artefact's action list resolves",
        ( if Actions = [_ | _] then yes else no ), !T, !IO),

    % One rule with all seven actions, the whole `A*` surface.
    check("all seven RHS actions decode",
        ( if list.length(Actions) >= 7 then yes else no ), !T, !IO),

    % Action order is emission order [IRET.10], with no sequence field to
    % recover it from.
    check("and in source order, with the logs before the `emit`",
        ( if list.map(verb_name_of, Actions) = Names,
             nth_of(Names, "log", LogAt),
             nth_of(Names, "emit", EmitAt),
             LogAt < EmitAt
          then yes else no ), !T, !IO),

    % The action list is keyed on `term_id`, from the `node_id` namespace
    % ([RDSC.8.7]): the key is a terminal.
    check("the action list is keyed on a real terminal",
        ( if Lists = [Term - _],
             terminal_nodes(network(P)) = [T],
             Term = T ^ tn_id
          then yes else no ), !T, !IO),

    check("and actions_for finds it",
        ( if terminal_nodes(network(P)) = [T2],
             actions_for(P, T2 ^ tn_id) = [_ | _]
          then yes else no ), !T, !IO),

    % `emit` resolves its schema name to a schema_id and its slot names to
    % indices against that schema.
    check("an emit's slot names resolved to indices against its schema",
        ( if list.filter_map(as_emit, Actions, Emits),
             Emits = [emit(Sid, Slots) | _],
             list.member(S, schemas(P)),
             S ^ s_id = Sid,
             Slots = [_ | _]
          then yes else no ), !T, !IO),

    % ALOG's level is a real level, not the zero sentinel.
    check("a log action carries a decoded level",
        ( if list.filter_map(as_log, Actions, Levels),
             Levels = [Level | _],
             Level \= log_debug
          then yes else no ), !T, !IO).

:- func verb_name_of(action) = string.

verb_name_of(A) = N :- verb_name(A, N).

:- pred nth_of(list(string)::in, string::in, int::out) is semidet.

nth_of(Names, Want, N) :-
    nth_of_loop(Names, Want, 0, N).

:- pred nth_of_loop(list(string)::in, string::in, int::in, int::out) is semidet.

nth_of_loop([X | Xs], Want, I, N) :-
    ( if X = Want then N = I else nth_of_loop(Xs, Want, I + 1, N) ).

:- type emit_view ---> emit(schema_id, list(slot_assign)).

:- pred as_emit(action::in, emit_view::out) is semidet.

as_emit(a_emit(Sid, Slots, _, _), emit(Sid, Slots)).

:- pred as_log(action::in, log_level::out) is semidet.

as_log(a_log(Level, _), Level).

    % LGRA.5.8.6: the four Json limits, `ds.json.limit_breach`, where a term
    % arrives from the host: a slot and a cache seed. libds refuses to build a
    % tree past them; a host here hands over a finished term. Each breach is
    % the one libds's parser reports for the same document: the first limit
    % crossed, and the count at the crossing.
    %
:- pred check_json_limits(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_json_limits(P, !T, !IO) :-
    AtCap = nested(max_depth),
    Over = nested(max_depth + 1),
    check("LGRA.5.8.6 depth: a term at the limit is within it",
        ( if limit_breach(AtCap) = no then yes else no ), !T, !IO),
    check("LGRA.5.8.6 depth: one level more crosses it, at level 17",
        ( if limit_breach(Over) = yes(json_breach(jl_depth, 16, 17))
        then yes else no ), !T, !IO),
    % The check stops at the cap and walks no further.
    check("LGRA.5.8.6 depth: a million levels is refused without walking them",
        ( if limit_breach(nested(1000000)) = yes(json_breach(jl_depth, _, _))
        then yes else no ), !T, !IO),
    ObjOver = j_object(object(["k" - nested(max_depth)])),
    check("LGRA.5.8.6 depth: an object level counts as an array level does",
        ( if limit_breach(ObjOver) = yes(json_breach(jl_depth, _, _))
        then yes else no ), !T, !IO),
    check("LGRA.5.8.6 nodes: 256 values are within it",
        ( if limit_breach(wide(max_nodes)) = no then yes else no ), !T, !IO),
    check("LGRA.5.8.6 nodes: the 257th crosses it",
        ( if limit_breach(wide(max_nodes + 1))
            = yes(json_breach(jl_nodes, 256, 257))
        then yes else no ), !T, !IO),
    check("LGRA.5.8.6 string bytes: 16384 are within it",
        ( if limit_breach(j_string(a_bytes(max_string_bytes))) = no
        then yes else no ), !T, !IO),
    check("LGRA.5.8.6 string bytes: 16385 cross it",
        ( if limit_breach(j_string(a_bytes(max_string_bytes + 1)))
            = yes(json_breach(jl_string_bytes, 16384, 16385))
        then yes else no ), !T, !IO),
    % A key counts, before its value: "k" + 16383 is at the limit, "kk" +
    % 16383 crosses it on the value -- what libds's parser reports.
    check("LGRA.5.8.6 string bytes: a key counts",
        ( if limit_breach(j_object(object(
                ["k" - j_string(a_bytes(max_string_bytes - 1))]))) = no
        then yes else no ), !T, !IO),
    check("LGRA.5.8.6 string bytes: a key past the limit crosses on the value",
        ( if limit_breach(j_object(object(
                ["kk" - j_string(a_bytes(max_string_bytes - 1))])))
            = yes(json_breach(jl_string_bytes, 16384, 16385))
        then yes else no ), !T, !IO),
    % UTF-8 bytes, not code points: "é" is two.
    check("LGRA.5.8.6 string bytes are UTF-8 bytes",
        ( if limit_breach(j_string(string.duplicate_char('é', 8193)))
            = yes(json_breach(jl_string_bytes, 16384, 16386))
        then yes else no ), !T, !IO),
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Reading", S) then
        engine_intern("a", A, E0, Ea),
        host_assert(S, [str(A), json(Over)], no, ROver, EffOver, Ea, Eb),
        check("LGRA.5.8.6 a Json slot over a limit is refused at assert",
            ( if ROver = invalid(1, sr_json_limit(json_breach(jl_depth, 16, 17)))
            then yes else no ), !T, !IO),
        % The status is the whole refusal: no event of any kind, as in libds.
        check("LGRA.5.8.6 ...and records nothing",
            ( if EffOver = [] then yes else no ), !T, !IO),
        host_assert(S, [str(A), json(AtCap)], no, RCap, _, Eb, _),
        check("LGRA.5.8.6 ...and one at the limit is admitted",
            ( if RCap = inserted(_) then yes else no ), !T, !IO)
    else
        check("20_json_path_probe declares Reading", no, !T, !IO)
    ),
    seed_cache("wide", wide(max_nodes + 1), no, RSeed, E0, _),
    check("LGRA.5.8.6 a cache seed over a limit is refused",
        ( if RSeed = seed_json_limit(json_breach(jl_nodes, 256, 257))
        then yes else no ), !T, !IO),
    seed_cache("cap", AtCap, no, RSeedCap, E0, _),
    check("LGRA.5.8.6 ...and one at the limit is taken",
        ( if RSeedCap = seeded then yes else no ), !T, !IO).

    % [LSTR.8.5]: text a host hands the engine is
    % well-formed UTF-8, or the call is refused with `DS_ERR_ENCODING` and
    % changes nothing. RFC 3629's five malformed classes, made as Mercury
    % strings by `from_code_unit_list_allow_ill_formed` -- a `string` holds
    % them as bytes -- in a `String` slot, in a `Json` slot's string and key,
    % and as a cache seed's key, value and text. Each is refused with no
    % effect; valid 2-, 3- and 4-byte text and U+10FFFF are admitted. libds is
    % held to the same cases (test_dsc_basic.c,
    % test_lstr_8_5__assert_and_seed_refuse_ill_formed_utf8; test_json_basic.c).
    %
:- pred check_lstr_8_5_host_text(program::in, tally::in, tally::out,
                                 io::di, io::uo) is det.

check_lstr_8_5_host_text(P, !T, !IO) :-
    Ill = [{"an overlong form", [0xC0, 0xAF]},
           {"a surrogate", [0xED, 0xA0, 0x80]},
           {"a code point past U+10FFFF", [0xF4, 0x90, 0x80, 0x80]},
           {"a sequence cut short", [0xE2, 0x82]},
           {"a stray continuation byte", [0x80]}],
    Ok = [[0xC3, 0xA9], [0xE2, 0x82, 0xAC], [0xF0, 0x9F, 0x98, 0x80],
          [0xF4, 0x8F, 0xBF, 0xBF]],
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Reading", S) then
        list.foldl2(check_lstr_8_5_ill(S, E0), Ill, !T, !IO),
        list.foldl2(check_lstr_8_5_ok(S, E0), Ok, !T, !IO)
    else
        check("20_json_path_probe declares Reading", no, !T, !IO)
    ).

:- pred check_lstr_8_5_ill(schema::in, engine::in, {string, list(int)}::in,
                           tally::in, tally::out, io::di, io::uo) is det.

check_lstr_8_5_ill(S, E0, {Label, Units}, !T, !IO) :-
    ( if string.from_code_unit_list_allow_ill_formed(Units, Bad) then
        engine_intern(Bad, BadRef, E0, E1),
        engine_intern("a", A, E1, E2),
        host_assert(S, [str(BadRef), json(j_int(1i64))], no, RStr, EffStr,
            E2, _),
        check("[LSTR.8.5] a String slot holding " ++ Label
                ++ " is DS_ERR_ENCODING, with no effect",
            ( if RStr = refused_encoding(0), EffStr = [] then yes else no ),
            !T, !IO),
        host_assert(S, [str(A), json(j_string(Bad))], no, RJs, EffJs, E2, _),
        check("[LSTR.8.5] a Json string holding " ++ Label
                ++ " is DS_ERR_ENCODING, with no effect",
            ( if RJs = refused_encoding(1), EffJs = [] then yes else no ),
            !T, !IO),
        host_assert(S, [str(A), json(j_object(object([Bad - j_int(1i64)])))],
            no, RKey, EffKey, E2, _),
        check("[LSTR.8.5] a Json key holding " ++ Label
                ++ " is DS_ERR_ENCODING, with no effect",
            ( if RKey = refused_encoding(1), EffKey = [] then yes else no ),
            !T, !IO),
        seed_cache(Bad, j_int(1i64), no, RSeedKey, E0, _),
        check("[LSTR.8.5] a cache seed key holding " ++ Label
                ++ " is DS_ERR_ENCODING",
            ( if RSeedKey = seed_encoding then yes else no ), !T, !IO),
        seed_cache("k", j_string(Bad), no, RSeedVal, E0, _),
        check("[LSTR.8.5] a cache seed value holding " ++ Label
                ++ " is DS_ERR_ENCODING",
            ( if RSeedVal = seed_encoding then yes else no ), !T, !IO),
        seed_cache_text("k", "\"" ++ Bad ++ "\"", no, RSeedText, E0, ESeed),
        check("[LSTR.8.5] a cache seed's text holding " ++ Label
                ++ " is DS_ERR_ENCODING, the cache unchanged",
            ( if
                RSeedText = seed_encoding,
                not cache_get(engine_cache(ESeed), "k", _)
            then yes else no ), !T, !IO)
    else
        check("[LSTR.8.5] " ++ Label ++ " makes a Mercury string", no, !T, !IO)
    ).

:- pred check_lstr_8_5_ok(schema::in, engine::in, list(int)::in,
                          tally::in, tally::out, io::di, io::uo) is det.

check_lstr_8_5_ok(S, E0, Units, !T, !IO) :-
    ( if string.from_utf8_code_unit_list(Units, Good) then
        engine_intern(Good, GoodRef, E0, E1),
        host_assert(S, [str(GoodRef), json(j_object(object(
                [Good - j_string(Good)])))], no, R, _, E1, _),
        check("[LSTR.8.5] well-formed text " ++ Good ++ " is admitted at assert",
            ( if R = inserted(_) then yes else no ), !T, !IO),
        seed_cache(Good, j_string(Good), no, RSeed, E0, _),
        check("[LSTR.8.5] well-formed text " ++ Good ++ " is seeded",
            ( if RSeed = seeded then yes else no ), !T, !IO)
    else
        check("[LSTR.8.5] a well-formed sequence makes a Mercury string", no,
            !T, !IO)
    ).

    % [NFCT.2.11], [NLFC.9.6]: where one host assert or seed breaks several
    % refusals, the first in the clause's order decides. One check per
    % adjacent pair, named as libds's `test_nfct_2_11_refusal_order.c` names
    % it: the input breaks exactly the two steps named and answers the
    % earlier, with no record and nothing entered. Before it, its control:
    % the later step's defect alone, answering the later step. That file's
    % header says which two pairs no input can build and the bridges that
    % stand for them.
    %
    % `148_refusal_order`'s `Mix` is d Date, s String, j Json, f Float, n Int:
    % each later step's value sits in an earlier slot than the one it is
    % paired with. The halted pairs are `check_nfct_2_11_halted`'s, on
    % `47_emit_softfail`. Every effect a refusal returns is a metric: a NaN
    % counts `ds.facts.nan_rejected_total`, as libds does.
    %
% @spec [NFCT.2.11]
% @spec [NLFC.9.6]
:- pred check_nfct_2_11_refusal_order(program::in, tally::in, tally::out,
                                      io::di, io::uo) is det.

check_nfct_2_11_refusal_order(P, !T, !IO) :-
    Max = uint64.cast_from_int64(int64.max_int64),
    TtlPast = yes(duration_from_ns(Max + 1u64)),
    Breach = json_breach(jl_nodes, 256, 257),
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        find_schema(schemas(P), interns(P), "Mix", Mix),
        find_schema(schemas(P), interns(P), "TimeZoneOffset", Tzo),
        string.from_code_unit_list_allow_ill_formed([0xC0, 0xAF], Bad)
    then
        engine_intern("x", X, E0, E1),
        engine_intern(Bad, BadRef, E1, E2),
        engine_intern("Asia/Tokyo", Tokyo, E2, E3),
        engine_intern("Stranger", StrangerRef, E3, E),
        Stranger = (Mix ^ s_name := make_schema_name(StrangerRef)),
        Ok = [int(0i64), str(X), json(j_int(1i64)), float(1.0), int(1i64)],
        Over = json(wide(max_nodes + 1)),
        NaN = float(float.infinity - float.infinity),
        InfJson = json(j_array([j_int(1i64), j_float(-float.infinity)])),
        BadDay = int(int64.max_int64),
        Ill = str(BadRef),
        NoKind = str(X),
        Short = list.take_upto(4, Ok),

        refusal_pair("test_nfct_2_11__unknown_schema_before_arity", E,
            Mix, Short, refused_arity(5, 4),
            Stranger, Short, refused_unregistered(Stranger ^ s_name),
            !T, !IO),
        refusal_pair("test_nfct_2_11__arity_before_kind", E,
            Mix, at_slot(0, NoKind, Ok), invalid(0, sr_kind_mismatch),
            Mix, list.take_upto(4, at_slot(0, NoKind, Ok)),
            refused_arity(5, 4),
            !T, !IO),
        refusal_pair("test_nfct_2_11__kind_before_nan", E,
            Mix, at_slot(3, NaN, Ok), invalid(3, sr_nan_rejected),
            Mix, at_slot(4, NoKind, at_slot(3, NaN, Ok)),
            invalid(4, sr_kind_mismatch),
            !T, !IO),
        refusal_pair("test_nfct_2_11__nan_before_json_limit", E,
            Mix, at_slot(2, Over, Ok), invalid(2, sr_json_limit(Breach)),
            Mix, at_slot(3, NaN, at_slot(2, Over, Ok)),
            invalid(3, sr_nan_rejected),
            !T, !IO),
        refusal_pair("test_nfct_2_11__json_limit_before_encoding", E,
            Mix, at_slot(1, Ill, Ok), refused_encoding(1),
            Mix, at_slot(2, Over, at_slot(1, Ill, Ok)),
            invalid(2, sr_json_limit(Breach)),
            !T, !IO),
        % [LGRA.5.8.10]: a Json value holding a non-finite float is
        % refused, `sr_json_nonfinite`, DS_ERR_JSON_NONFINITE with no event.
        % libds cannot be handed one, so [NFCT.2.11] names no step for it;
        % here it is judged after the limits (`ds.fact.slot_fault`) and so
        % after a NaN, and before the encoding, as every `slot_fault` reason
        % is.
        refusal_pair("test_lgra_5_8_10__nan_before_json_non_finite", E,
            Mix, at_slot(2, InfJson, Ok), invalid(2, sr_json_nonfinite),
            Mix, at_slot(3, NaN, at_slot(2, InfJson, Ok)),
            invalid(3, sr_nan_rejected),
            !T, !IO),
        refusal_pair("test_lgra_5_8_10__json_non_finite_before_encoding", E,
            Mix, at_slot(1, Ill, Ok), refused_encoding(1),
            Mix, at_slot(2, InfJson, at_slot(1, Ill, Ok)),
            invalid(2, sr_json_nonfinite),
            !T, !IO),
        refusal_pair("test_nfct_2_11__encoding_before_date_range", E,
            Mix, at_slot(0, BadDay, Ok), refused_time_range(0),
            Mix, at_slot(1, Ill, at_slot(0, BadDay, Ok)), refused_encoding(1),
            !T, !IO),
        % The bridge for the Date range and the row: no row has a Date slot.
        refusal_pair("test_nfct_2_11__encoding_before_tz_row", E,
            Tzo, [str(Tokyo), int(100i64), int(100i64), int(0i64)],
            refused_tz_row(tzf_empty_period),
            Tzo, [Ill, int(100i64), int(100i64), int(0i64)],
            refused_encoding(0),
            !T, !IO),
        % The bridge for the row and the TTL deadline: a row is `logical`.
        % Seeded with 1 h at INT64_MAX - 1 s, this assert's sample would fix
        % the seed's deadline past the `Time` range ([NLFC.9.5]).
        set_clock(from_ns(Max - 1000000000u64), _, E, EL0),
        seed_cache("k", j_int(1i64), yes(duration_from_ns(3600000000000u64)),
            RHeld, EL0, EL),
        check("test_nfct_2_11__tz_row_before_held_seed_deadline: the seed is "
                ++ "held",
            ( if RHeld = seeded then yes else no ), !T, !IO),
        refusal_pair("test_nfct_2_11__tz_row_before_held_seed_deadline", EL,
            Tzo, [str(Tokyo), int(0i64), int(100i64), int(0i64)],
            refused_ttl_range,
            Tzo, [str(Tokyo), int(100i64), int(100i64), int(0i64)],
            refused_tz_row(tzf_empty_period),
            !T, !IO),

        % [NLFC.9.6]. The window closes at the engine's first stream event,
        % an admitted assert's `FactAssert`.
        host_assert(Mix, Ok, no, ROpen, _, E, EW),
        check("test_nlfc_9_6: the window-closing assert is admitted",
            ( if ROpen = inserted(_), engine_event_count(EW) \= 0u64
              then yes else no ), !T, !IO),
        seed_pair("test_nlfc_9_6__window_before_ttl_range",
            E, "k", j_int(1i64), TtlPast, seed_time_range,
            EW, "k", j_int(1i64), TtlPast, seed_after_pump,
            !T, !IO),
        seed_pair("test_nlfc_9_6__ttl_range_before_json_limit",
            E, "k", wide(max_nodes + 1), no, seed_json_limit(Breach),
            E, "k", wide(max_nodes + 1), TtlPast, seed_time_range,
            !T, !IO),
        seed_pair("test_nlfc_9_6__json_limit_before_encoding",
            E, Bad, j_int(1i64), no, seed_encoding,
            E, Bad, wide(max_nodes + 1), no, seed_json_limit(Breach),
            !T, !IO)
    else
        check("148_refusal_order declares Mix and TimeZoneOffset", no, !T, !IO)
    ).

    % The pairs that need a halted engine: `47_emit_softfail`'s pump halts it
    % (`check_halt_latch`). Its assert also closed the seeding window, so the
    % engine before the pump is each pair's control.
    %
% @spec [NFCT.2.11]
% @spec [NLFC.9.6]
:- pred check_nfct_2_11_halted(program::in, tally::in, tally::out,
                               io::di, io::uo) is det.

check_nfct_2_11_halted(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "In", In) then
        engine_intern("ab", Txt, E0, E1),
        engine_intern("Stranger", StrangerRef, E1, E2),
        Stranger = (In ^ s_name := make_schema_name(StrangerRef)),
        host_assert(In, [int(1i64), str(Txt)], no, R1, _, E2, E3),
        pump(default_budget, _, E3, E4),
        Halt = ee_expr_fault(rf_artefact_lied),
        check("test_nfct_2_11: the fixture's pump halts the engine",
            ( if R1 = inserted(_), engine_halted(E4) = yes(Halt)
              then yes else no ), !T, !IO),
        % Not `refusal_pair`, which runs both from one engine: the control
        % runs before the halt and the pair after it.
        host_assert(Stranger, [int(2i64), str(Txt)], no, RU, FxU, E3, EU),
        check("test_nfct_2_11__halted_before_unknown_schema: control, the "
                ++ "later step alone",
            ( if
                RU = refused_unregistered(Stranger ^ s_name),
                refused_quietly(E3, FxU, EU)
              then yes else no ), !T, !IO),
        host_assert(Stranger, [int(2i64), str(Txt)], no, RH, FxH, E4, EH),
        check("test_nfct_2_11__halted_before_unknown_schema: the earlier "
                ++ "step decides, with no record",
            ( if RH = refused_halted(Halt), refused_quietly(E4, FxH, EH)
              then yes else no ), !T, !IO),
        seed_cache("k", j_int(1i64), no, RWin, E3, EWin),
        check("test_nlfc_9_6__halted_before_window: control, the window "
                ++ "alone",
            ( if RWin = seed_after_pump, not cache_get(engine_cache(EWin), "k", _)
              then yes else no ), !T, !IO),
        seed_cache("k", j_int(1i64), no, RHalt, E4, EHalt),
        check("test_nlfc_9_6__halted_before_window: the earlier step decides",
            ( if RHalt = seed_halted(Halt),
                 not cache_get(engine_cache(EHalt), "k", _)
              then yes else no ), !T, !IO),
        check_lstr_8_5_text_before_state(E3, E4, Halt, !T, !IO)
    else
        check("47_emit_softfail declares In", no, !T, !IO)
    ).

    % [LSTR.8.5]: a seed given as JSON text is judged as text
    % first -- its limit, then its encoding, then its parse -- and a refusal
    % of the text comes before every step [NLFC.9.6] orders, the halt and the
    % closed window included. `Open` has closed the seeding window and not
    % halted; `Halted` has halted. Each control is valid text, answering the
    % engine's state; each case is the same position with the text broken, and
    % answers the text. Two more pin the text's own order: text both over the
    % limit and ill-formed is the limit's, and text both ill-formed and
    % malformed is the encoding's. Nothing is seeded by any of them. libds is
    % held to the same order through pyds and @ds-lang/ds
    % (test_nlfc_9_6_text_first.py, engine.test.mjs).
    %
% @spec [LSTR.8.5]
:- pred check_lstr_8_5_text_before_state(engine::in, engine::in,
    engine_error::in, tally::in, tally::out, io::di, io::uo) is det.

check_lstr_8_5_text_before_state(Open, Halted, Halt, !T, !IO) :-
    Over = "0" ++ string.duplicate_char(' ', max_text_bytes),
    ( if string.from_code_unit_list_allow_ill_formed([0xC0, 0xAF], Bad) then
        Ill = "\"" ++ Bad ++ "\"",
        OverIll = Ill ++ string.duplicate_char(' ', max_text_bytes),
        IllMalformed = "{" ++ Bad,
        Cases = [
            {"valid text on a halted engine is the halt", Halted, "1",
                seed_halted(Halt)},
            {"malformed text on a halted engine is the parse", Halted,
                "{not json", seed_text_refused(jr_syntax)},
            {"ill-formed text on a halted engine is the encoding", Halted,
                Ill, seed_encoding},
            {"text over the limit on a halted engine is the limit", Halted,
                Over, seed_json_limit(json_breach(jl_text_bytes,
                    max_text_bytes, max_text_bytes + 1))},
            {"text over the limit and ill-formed is the limit", Halted,
                OverIll, seed_json_limit(json_breach(jl_text_bytes,
                    max_text_bytes, string.count_utf8_code_units(OverIll)))},
            {"text ill-formed and malformed is the encoding", Halted,
                IllMalformed, seed_encoding},
            {"valid text after the window closes is the window", Open, "1",
                seed_after_pump},
            {"malformed text after the window closes is the parse", Open,
                "{not json", seed_text_refused(jr_syntax)}
        ],
        list.foldl2(
            ( pred({Label, E0, Text, Want}::in, T0::in, T1::out,
                    IO0::di, IO1::uo) is det :-
                seed_cache_text("k", Text, no, R, E0, E1),
                check("[LSTR.8.5] " ++ Label,
                    ( if R = Want, not cache_get(engine_cache(E1), "k", _)
                      then yes else no ), T0, T1, IO0, IO1)
            ), Cases, !T, !IO)
    else
        check("[LSTR.8.5] the ill-formed sequence makes a Mercury string", no,
            !T, !IO)
    ).

    % One [NFCT.2.11] pair, both asserts from `E0`: the control, the later
    % step's defect alone, answers `Later`; the pair answers `Earlier`. Each
    % with no record and nothing entered.
    %
:- pred refusal_pair(string::in, engine::in,
    schema::in, list(ds_value)::in, assert_result::in,
    schema::in, list(ds_value)::in, assert_result::in,
    tally::in, tally::out, io::di, io::uo) is det.

refusal_pair(Label, E0, CS, CVs, Later, S, Vs, Earlier, !T, !IO) :-
    host_assert(CS, CVs, no, RC, FxC, E0, EC),
    check(Label ++ ": control, the later step alone",
        ( if RC = Later, refused_quietly(E0, FxC, EC) then yes else no ),
        !T, !IO),
    host_assert(S, Vs, no, R, Fx, E0, E1),
    check(Label ++ ": the earlier step decides, with no record",
        ( if R = Earlier, refused_quietly(E0, Fx, E1) then yes else no ),
        !T, !IO).

    % One [NLFC.9.6] pair: the control's seed, on `CE`, answers `Later`; the
    % pair's, on `E`, answers `Earlier`; neither leaves the key in the cache.
    %
:- pred seed_pair(string::in,
    engine::in, string::in, json::in, maybe(duration)::in, seed_result::in,
    engine::in, string::in, json::in, maybe(duration)::in, seed_result::in,
    tally::in, tally::out, io::di, io::uo) is det.

seed_pair(Label, CE0, CKey, CValue, CTtl, Later, E0, Key, Value, Ttl, Earlier,
        !T, !IO) :-
    seed_cache(CKey, CValue, CTtl, RC, CE0, CE),
    check(Label ++ ": control, the later step alone",
        ( if RC = Later, not cache_get(engine_cache(CE), CKey, _)
          then yes else no ), !T, !IO),
    seed_cache(Key, Value, Ttl, R, E0, E),
    check(Label ++ ": the earlier step decides",
        ( if R = Earlier, not cache_get(engine_cache(E), Key, _)
          then yes else no ), !T, !IO).

    % A refused call recorded nothing -- every effect is a metric -- and
    % entered nothing.
    %
:- pred refused_quietly(engine::in, list(effect)::in, engine::in) is semidet.

refused_quietly(E0, Effects, E) :-
    list.all_true((pred(Ef::in) is semidet :- Ef = eff_metric(_)), Effects),
    engine_fact_count(E) = engine_fact_count(E0).

    % `Vs` with its 0-based `I`th value `V`.
    %
:- func at_slot(int, ds_value, list(ds_value)) = list(ds_value).

at_slot(I, V, Vs) = list.det_replace_nth(Vs, I + 1, V).

    % `N` values: an array of N-1 Ints, so the array is the N-th.
    %
:- func wide(int) = json.

wide(N) = j_array(list.duplicate(N - 1, j_int(0i64))).

    % A string of `N` bytes of 'a'.
    %
:- func a_bytes(int) = string.

a_bytes(N) = string.duplicate_char('a', N).

    % `N` levels: N-1 arrays around an Int. Built from the inside out by an
    % accumulator, so a million levels costs no million-deep recursion here.
    %
:- func nested(int) = json.

nested(N) = nest_up(N - 1, j_int(1i64)).

:- func nest_up(int, json) = json.

nest_up(K, Acc) = ( if K =< 0 then Acc else nest_up(K - 1, j_array([Acc])) ).

:- pred check_json_chain(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_json_chain(P, !T, !IO) :-
    Lists = action_lists(P),
    ( if Lists = [_ - As] then Actions = As else Actions = [] ),

    check("a rule with a multi-segment JSON chain loads",
        ( if Actions = [_ | _] then yes else no ), !T, !IO),

    % `log info "depth {r.payload.depth}"` reaches the runtime as
    %
    %   e_call(fn_json_path, [ e_slot(token_fact(0), slot(1)),
    %                          e_lit(str("depth")) ])
    %
    % a builtin call over the value to walk and the path to walk it by, with
    % the `payload` slot as argument 0.
    list.filter_map(as_log_message, Actions, Msgs),
    io.format("  note: json chain message = %s\n", [s(string(Msgs))], !IO),
    check("the log message is literal text and a JSON-path call",
        ( if Msgs = [Msg | _],
             untainted(Msg) = e_interp([fp_text(_), fp_value(VP)]),
             untainted(VP ^ vp_value) = e_call(fn_json_path, [_, _])
          then yes else no ), !T, !IO),

    check("and the `payload` slot it walks is PRESENT",
        ( if Msgs = [Msg2 | _],
             untainted(Msg2) = e_interp([_, fp_value(VP2)]),
             untainted(VP2 ^ vp_value) = e_call(fn_json_path, [Slot, _]),
             Slot = e_slot(_, _)
          then yes else no ), !T, !IO).

:- pred as_log_message(action::in, expr::out) is semidet.

as_log_message(a_log(_, Message), Message).

:- pred check_where_rhs(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_where_rhs(P, !T, !IO) :-
    Lists = action_lists(P),
    ( if Lists = [_ - As] then Actions = As else Actions = [] ),

    check("a where-clause rule's RHS resolves",
        ( if Actions = [_ | _] then yes else no ), !T, !IO),

    % This fixture's LHS is all alpha tests, so it carries alpha tests
    % (`alpha_test`) and RHS actions (`term.proto`) and no beta join tree
    % (`rete_expr.proto`); `09_negation_and_within`'s joins keep theirs.
    check("so ONE artefact carries an alpha filter AND an RHS action list",
        ( if alpha_nodes(network(P)) = [A | _],
             A ^ an_tests = [_ | _],
             Actions = [_ | _]
          then yes else no ), !T, !IO).

:- pred check_let_bindings(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_let_bindings(P, !T, !IO) :-
    Lists = action_lists(P),
    ( if Lists = [_ - As] then Actions = As else Actions = [] ),
    io.format("  note: 08_let_bindings actions = %s\n",
        [s(string(list.map(verb_name_of, Actions)))], !IO),

    check("a rule using `let` loads",
        ( if Actions = [_ | _] then yes else no ), !T, !IO),

    % A runtime `let` reaches the runtime as an action, a `BindExpr` ahead of
    % the author's three verbs. The rule has two: `scaled` and
    % `firing_at = now()`.
    check("and a binding survives as an action",
        ( if list.filter(is_bind_action, Actions) = [_ | _]
          then yes else no ), !T, !IO),

    % The actions are `!bind, log, emit, cache_set`: the compiler emits a
    % `BindExpr` for one `let` and folds the other at its use site.
    check("ONE bind for two `let`s -- the compiler folded the other",
        ( if list.filter(is_bind_action, Actions) = Binds,
             list.length(Binds) = 1,
             list.length(Actions) = 4
          then yes else no ), !T, !IO).

:- pred is_bind_action(action::in) is semidet.

is_bind_action(a_bind(_, _)).

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% Working memory
%-----------------------------------------------------------------------------%

    % A schema with the given logical slots, id 1. `wslot` builds a slot with a
    % real index, which `project_identity` needs and `lslot` above does not.
:- func wschema(list(logical_slot)) = schema.

wschema(Slots) =
    schema(make_schema_id(1u32), make_schema_name(make_intern_ref(1u32)),
        lc_logical(Slots, no), no, no).

:- func wslot(int, identity_role, tolerance) = logical_slot.

wslot(Ix, Role, Tol) = wslot_kind(Ix, k_int, Role, Tol).

    % A slot of the given kind. A tolerance needs `k_float`.
    %
:- func wslot_kind(int, slot_kind, identity_role, tolerance) = logical_slot.

wslot_kind(Ix, Kind, Role, Tol) =
    logical_slot(
        slot_common(make_intern_ref(1u32), Kind, S, non_null, no, no, no, unbounded, no),
        Role, Tol) :-
    ( if slot_index(uint32.det_from_int(Ix), S0) then
        S = S0
    else
        unexpected($pred, "slot index")
    ).

:- func ttl_schema(int) = schema.

ttl_schema(N) =
    schema(make_schema_id(2u32), make_schema_name(make_intern_ref(2u32)),
        lc_ttl([plain_slot(slot_common(make_intern_ref(1u32), k_int, S,
            non_null, no, no, no, unbounded, no))], duration_from_ns(uint64.det_from_int(N))),
        no, no) :-
    ( if slot_index(0u32, S0) then S = S0 else unexpected($pred, "slot 0") ).

:- func at(int) = instant.

at(N) = from_ns(uint64.det_from_int(N)).

    % [LNUL.3.4]: a `Json` value whose root is null is the canonical `null`.
    % `assert_fact` is the door the host's assert and a rule's emit both
    % pass, so this is both paths: stored as `null` in `Json?`, refused as
    % `sr_null_non_nullable` in `Json` ([RARC.5.2.7]'s TypeError on a rule's
    % path), and a document that only contains a null untouched.
    %
% @spec [LNUL.3.4] [RARC.5.2.7]
:- pred test_lnul_3_4_root_null(tally::in, tally::out, io::di, io::uo) is det.

test_lnul_3_4_root_null(!T, !IO) :-
    Key = wslot(0, role_key, exact),
    Doc = logical_slot(slot_common(make_intern_ref(1u32), k_json, sidx(1),
        non_null, no, no, no, unbounded, no), role_mutable, exact),
    DocQ = logical_slot(slot_common(make_intern_ref(1u32), k_json, sidx(1),
        nullable, no, no, no, unbounded, no), role_mutable, exact),
    J = wschema([Key, Doc]),
    JQ = wschema([Key, DocQ]),
    assert_fact(JQ, [int(1i64), json(j_null)], at(100), no, tms_none, live,
        RQ, init_wm, WQ),
    check("[LNUL.3.4] a root-null Json into a Json? slot is stored as null",
        ( if
            RQ = inserted(IdQ),
            lookup_fact(WQ, IdQ, FQ),
            array.lookup(FQ ^ f_slots, 1) = null
        then yes else no ), !T, !IO),
    assert_fact(J, [int(2i64), json(j_null)], at(100), no, tms_none, live,
        RJ, init_wm, _),
    check("[LNUL.3.4] and refused in a Json slot as null into a non-nullable "
            ++ "one (a TypeError on a rule's path)",
        ( if RJ = invalid(1, sr_null_non_nullable) then yes else no ), !T, !IO),
    % `ds.engine` asks `slot_fault` of the value as the host gave it,
    % before the assert takes its step, so it must answer as the door does.
    check("[LNUL.3.4] slot_fault judges a root-null Json before the door does",
        ( if
            slot_fault(J, [int(2i64), json(j_null)], 1, sr_null_non_nullable),
            not slot_fault(JQ, [int(1i64), json(j_null)], _, _)
        then yes else no ), !T, !IO),
    Obj = j_object(object(["a" - j_null])),
    assert_fact(J, [int(3i64), json(Obj)], at(100), no, tms_none, live,
        RO, init_wm, WO),
    check("[LNUL.3.4] a document that contains a null stays a document",
        ( if
            RO = inserted(IdO),
            lookup_fact(WO, IdO, FO),
            array.lookup(FO ^ f_slots, 1) = json(Obj)
        then yes else no ), !T, !IO).

:- pred test_wm(tally::in, tally::out, io::di, io::uo) is det.

test_wm(!T, !IO) :-
    test_lnul_3_4_root_null(!T, !IO),
    % One key slot, one mutable: entity-state. The commonest shape.
    Entity = wschema([wslot(0, role_key, exact),
                      wslot(1, role_mutable, exact)]),

    W0 = init_wm,
    assert_fact(Entity, [int(1i64), int(10i64)], at(100), no, tms_none, live,
        R1, W0, W1),
    check("a first assert INSERTS",
        ( if R1 = inserted(_) then yes else no ), !T, !IO),
    check("and the fact is live",
        ( if live_count(W1) = 1 then yes else no ), !T, !IO),

    % [LERR.9.10]: the capacity count leaves the named schemas' facts out --
    % the engine names the two fault schemas. A second schema's fact is live
    % and not counted; naming no schema counts everything.
    Excluded = ttl_schema(1000),
    assert_fact(Excluded, [int(5i64)], at(100), no, tms_none, live, _, W1, WX),
    check("[LERR.9.10] an excluded schema's fact does not count",
        ( if
            live_count(WX) = 2,
            lerr_9_10_capacity_count(WX, [Excluded ^ s_id]) = 1,
            lerr_9_10_capacity_count(WX, []) = 2
        then yes else no ), !T, !IO),

    % The no-op: same fact, same fact_id, no event, dwell preserved
    % [LFAC.2.5.1]. The surviving fact_id is the observable part: a consumer
    % holding a reference must still find the same fact.
    assert_fact(Entity, [int(1i64), int(10i64)], at(200), no, tms_none, live,
        R2, W1, W2),
    check("re-asserting an identical fact is a NO-OP",
        ( if R2 = noop(_) then yes else no ), !T, !IO),
    check("and PRESERVES the fact_id",
        ( if R1 = inserted(Id1), R2 = noop(Id2), Id1 = Id2
          then yes else no ), !T, !IO),
    check("and does not create a second fact",
        ( if live_count(W2) = 1 then yes else no ), !T, !IO),

    % A no-op must not re-timestamp: `dwell` is measured from the assert
    % instant, and refreshing it makes a re-asserting sensor look permanently
    % fresh.
    check("nor re-timestamp the stored fact -- dwell is preserved",
        ( if R1 = inserted(Id3), lookup_fact(W2, Id3, F),
             F ^ f_asserted = at(100)
          then yes else no ), !T, !IO),

    % A meaningful change is a visible retract-and-replace: fresh fact_id,
    % exactly one live fact [LFAC.2.5.3]. Never an in-place mutation.
    assert_fact(Entity, [int(1i64), int(99i64)], at(300), no, tms_none, live,
        R3, W2, W3),
    check("a changed payload REPLACES",
        ( if R3 = replaced(_, _) then yes else no ), !T, !IO),
    check("with a FRESH fact_id -- never an in-place mutation",
        ( if R3 = replaced(Old, New), Old \= New then yes else no ), !T, !IO),
    check("and still exactly one live fact",
        ( if live_count(W3) = 1 then yes else no ), !T, !IO),
    check("the old fact_id is gone",
        ( if R3 = replaced(Old2, _), not lookup_fact(W3, Old2, _)
          then yes else no ), !T, !IO),

    % A different key is a different entity: both live.
    assert_fact(Entity, [int(2i64), int(10i64)], at(400), no, tms_none, live,
        R4, W3, W4),
    check("a different key is a different entity, not a supersede",
        ( if R4 = inserted(_), live_count(W4) = 2 then yes else no ), !T, !IO),

    test_tolerance(!T, !IO),
    test_engine_ts(!T, !IO),
    test_key_widths(!T, !IO),
    test_ttl(!T, !IO),
    lnls_4_7_removal_keeps_indexes_agreeing(!T, !IO).

    % [LFAC.9.1], [LFAC.2.5.1]: `ts` is outside the no-op comparison, so a
    % reassertion that differs only in `ts` is a no-op and the live fact keeps
    % its first `ts`.
    %
:- pred test_engine_ts(tally::in, tally::out, io::di, io::uo) is det.

test_engine_ts(!T, !IO) :-
    Stamped = wschema([wslot(0, role_key, exact),
                       wslot(1, role_mutable, exact),
                       wslot(2, role_engine, exact)]),
    assert_fact(Stamped, [int(1i64), int(10i64), int(100i64)], at(100), no,
        tms_none, live, R1, init_wm, W1),
    assert_fact(Stamped, [int(1i64), int(10i64), int(200i64)], at(200), no,
        tms_none, live, R2, W1, W2),
    check("LFAC.9.1: a reassertion differing only in `ts` is a NO-OP",
        ( if R1 = inserted(Id1), R2 = noop(Id2), Id1 = Id2 then yes else no ),
        !T, !IO),
    check("LFAC.9.1: and the live fact keeps the `ts` it entered with",
        ( if R1 = inserted(Id), lookup_fact(W2, Id, F),
             array.lookup(F ^ f_slots, 2) = int(100i64)
          then yes else no ), !T, !IO),
    assert_fact(Stamped, [int(1i64), int(11i64), int(300i64)], at(300), no,
        tms_none, live, R3, W2, _),
    check("LFAC.9.1: a change to a MUTABLE slot still replaces",
        ( if R3 = replaced(_, _) then yes else no ), !T, !IO).

:- pred test_tolerance(tally::in, tally::out, io::di, io::uo) is det.

test_tolerance(!T, !IO) :-
    % `tolerance 0.5` on the mutable slot. Tolerance is legal only on a mutable
    % slot of a logical schema; on a key slot it is rejected at load.
    Tol = wschema([wslot(0, role_key, exact),
                   wslot_kind(1, k_float, role_mutable, within(0.5))]),

    assert_fact(Tol, [int(1i64), float(20.0)], at(100), no, tms_none, live,
        _, init_wm, V1),

    check("a change inside the tolerance is suppressed",
        ( if assert_fact(Tol, [int(1i64), float(20.3)], at(200), no, tms_none,
                live, noop(_), V1, _)
          then yes else no ), !T, !IO),
    check("a change outside it is a replace",
        ( if assert_fact(Tol, [int(1i64), float(20.9)], at(200), no, tms_none,
                live, replaced(_, _), V1, _)
          then yes else no ), !T, !IO),

    % [RLOW.3.7.4]: values are equal if `abs(new - old) <= T`, as
    % `formal/k/lfac.k` has it.
    check("a change of EXACTLY the tolerance is suppressed",
        ( if assert_fact(Tol, [int(1i64), float(20.5)], at(200), no, tms_none,
                live, noop(_), V1, _)
          then yes else no ), !T, !IO),

    % `tolerance 0` is explicit exact-equality [RLOW.3.7.8].
    Zero = wschema([wslot(0, role_key, exact),
                    wslot_kind(1, k_float, role_mutable, within(0.0))]),
    assert_fact(Zero, [int(1i64), float(7.0)], at(100), no, tms_none, live,
        _, init_wm, Z1),
    check("`tolerance 0` still suppresses an IDENTICAL re-assert",
        ( if assert_fact(Zero, [int(1i64), float(7.0)], at(200), no, tms_none,
                live, noop(_), Z1, _)
          then yes else no ), !T, !IO),
    check("but not a different one",
        ( if assert_fact(Zero, [int(1i64), float(7.1)], at(200), no, tms_none,
                live, replaced(_, _), Z1, _)
          then yes else no ), !T, !IO),

    % The dedup relation is reflexive and symmetric but not transitive
    % (`noop_reassert.als`), so suppression compares against the single
    % stored value, never across history.
    assert_fact(Tol, [int(1i64), float(20.3)], at(200), no, tms_none, live,
        _, V1, D1),
    check("drift is measured against the STORED value, so it cannot creep",
        ( if assert_fact(Tol, [int(1i64), float(20.6)], at(300), no, tms_none,
                live, replaced(_, _), D1, _)
          then yes else no ), !T, !IO).

:- pred test_key_widths(tally::in, tally::out, io::di, io::uo) is det.

test_key_widths(!T, !IO) :-
    % SINGLETON: no key slots, so one live fact and the latest payload wins.
    Single = wschema([wslot(0, role_mutable, exact),
                      wslot(1, role_mutable, exact)]),
    assert_fact(Single, [int(1i64), int(1i64)], at(100), no, tms_none, live,
        _, init_wm, S1),
    assert_fact(Single, [int(9i64), int(9i64)], at(200), no, tms_none, live,
        SR, S1, S2),
    check("singleton: a wholly different payload still SUPERSEDES",
        ( if SR = replaced(_, _), live_count(S2) = 1 then yes else no ),
        !T, !IO),

    % RELATION: all slots are key, so distinct tuples coexist and identical
    % tuples coalesce.
    Rel = wschema([wslot(0, role_key, exact), wslot(1, role_key, exact)]),
    assert_fact(Rel, [int(1i64), int(1i64)], at(100), no, tms_none, live,
        _, init_wm, L1),
    assert_fact(Rel, [int(1i64), int(2i64)], at(200), no, tms_none, live,
        RR1, L1, L2),
    check("relation: distinct tuples COEXIST",
        ( if RR1 = inserted(_), live_count(L2) = 2 then yes else no ),
        !T, !IO),
    assert_fact(Rel, [int(1i64), int(1i64)], at(300), no, tms_none, live,
        RR2, L2, L3),
    check("relation: an identical tuple COALESCES",
        ( if RR2 = noop(_), live_count(L3) = 2 then yes else no ), !T, !IO),

    % COMPOSITE: two of three key. Changing a key slot is a new entity;
    % changing the payload supersedes.
    Comp = wschema([wslot(0, role_key, exact), wslot(1, role_key, exact),
                    wslot(2, role_mutable, exact)]),
    assert_fact(Comp, [int(1i64), int(1i64), int(0i64)], at(100), no, tms_none, live,
        _, init_wm, C1),
    assert_fact(Comp, [int(1i64), int(2i64), int(0i64)], at(200), no, tms_none, live,
        CR1, C1, C2),
    check("composite: a different key component is a different entity",
        ( if CR1 = inserted(_), live_count(C2) = 2 then yes else no ),
        !T, !IO),
    assert_fact(Comp, [int(1i64), int(1i64), int(5i64)], at(300), no, tms_none, live,
        CR2, C2, C3),
    check("composite: the same key with a new payload supersedes",
        ( if CR2 = replaced(_, _), live_count(C3) = 2 then yes else no ),
        !T, !IO).

:- pred test_ttl(tally::in, tally::out, io::di, io::uo) is det.

test_ttl(!T, !IO) :-
    Ttl = ttl_schema(1000),

    % `ttl` facts ACCUMULATE: no identity, no dedup, each with its own
    % deadline. Two identical ones are two facts, which is the opposite of the
    % logical case and is what `identity_of` returning `no` buys.
    assert_fact(Ttl, [int(1i64)], at(100), yes(at(1100)), tms_none, live,
        _, init_wm, T1),
    assert_fact(Ttl, [int(1i64)], at(200), yes(at(1200)), tms_none, live,
        TR, T1, T2),
    check("ttl facts ACCUMULATE -- identical ones do not dedup",
        ( if TR = inserted(_), live_count(T2) = 2 then yes else no ), !T, !IO),

    check("nothing is due before the first deadline",
        ( if expire(at(1000), [], T2, _) then yes else no ), !T, !IO),

    expire(at(1100), Due1, T2, T3),
    check("expiry is `deadline <= now`, not `<`",
        ( if Due1 = [_] then yes else no ), !T, !IO),
    check("and removes the fact",
        ( if live_count(T3) = 1 then yes else no ), !T, !IO),

    expire(at(9999), Due2, T3, T4),
    check("a later sweep takes the rest",
        ( if Due2 = [_], live_count(T4) = 0 then yes else no ), !T, !IO),

    % Lifecycle and deadline are independent: an explicit TTL gives a
    % `logical` fact a deadline too ([RHIM.6.2]).
    Entity = wschema([wslot(0, role_key, exact),
                      wslot(1, role_mutable, exact)]),
    assert_fact(Entity, [int(1i64), int(1i64)], at(100), no, tms_none, live,
        _, init_wm, H0),
    expire(at(999999), NoneDue, H0, H1),
    check("a logical fact with NO override is never swept",
        ( if NoneDue = [], live_count(H1) = 1 then yes else no ), !T, !IO),

    assert_fact(Entity, [int(2i64), int(1i64)], at(100), yes(at(500)), tms_none,
        live, _, H1, H2),
    expire(at(500), SomeDue, H2, H3),
    check("but one WITH an override does expire on its deadline (RHIM.6.2)",
        ( if SomeDue = [_], live_count(H3) = 1 then yes else no ), !T, !IO),

    % A deadline armed for a fact that was superseded before it came round.
    % The deadline structure has no disarm, so a stale arming is the normal
    % consequence of any early removal and must not resurrect or error.
    assert_fact(Entity, [int(3i64), int(1i64)], at(100), yes(at(700)), tms_none,
        live, _, H3, H4),
    assert_fact(Entity, [int(3i64), int(2i64)], at(200), no, tms_none, live,
        _, H4, H5),
    expire(at(700), StaleDue, H5, H6),
    check("a deadline armed for a superseded fact is a harmless no-op",
        ( if StaleDue = [], live_count(H6) = 2 then yes else no ), !T, !IO),

    % `facts_of_schema` is an alpha node's memory, and insertion order is
    % semantic: the TTL sweep is specified in it, and a join walking this list
    % mints ascending timetags, which is what produces source-order firing.
    assert_fact(Ttl, [int(7i64)], at(100), no, tms_none, live, _, init_wm, O1),
    assert_fact(Ttl, [int(8i64)], at(200), no, tms_none, live, _, O1, O2),
    assert_fact(Ttl, [int(9i64)], at(300), no, tms_none, live, _, O2, O3),
    check("facts_of_schema returns INSERTION order, not id or map order",
        ( if facts_of_schema(O3, make_schema_id(2u32)) = [F1, F2, F3],
             F1 ^ f_asserted = at(100),
             F2 ^ f_asserted = at(200),
             F3 ^ f_asserted = at(300)
          then yes else no ), !T, !IO),
    check("and a schema with no facts gives an empty memory, not a failure",
        ( if facts_of_schema(O3, make_schema_id(77u32)) = [] then yes else no ),
        !T, !IO).

    % [LNLS.4.7] makes removing a fact O(1) amortized, so working memory's
    % indexes are hashed, its per-schema membership drops a fact lazily, and
    % its deadlines are a FIFO per schema with a heap beside it. This pins
    % that the indexes still agree after many removals by every cause
    % (supersede, retract, withdraw, expire), not the cost ([STYL.5.10.8]).
    %
    % 200 entities. Keys 1-50 carry rising deadlines (the FIFO), 51-60
    % falling ones (51 still rises past 50, so it joins the FIFO; each of
    % 52-60 is earlier than the last, so the heap). Then 61-100 are
    % superseded, 101-140 retracted, 141-160 withdrawn, and two sweeps expire
    % 1-60. 140 removals, far past the point where a `fact_seq` compacts.
    %
:- pred lnls_4_7_removal_keeps_indexes_agreeing(tally::in, tally::out,
                                                 io::di, io::uo) is det.

lnls_4_7_removal_keeps_indexes_agreeing(!T, !IO) :-
    S = wschema([wslot(0, role_key, exact), wslot(1, role_mutable, exact)]),
    list.foldl(removal_assert(S), 1 .. 200, init_wm, W0),
    check("[LNLS.4.7] 200 entities asserted",
        ( if live_count(W0) = 200 then yes else no ), !T, !IO),

    list.foldl(removal_supersede(S), 61 .. 100, W0, W1),
    list.foldl(removal_retract(S, rc_explicit), 101 .. 140, W1, W2),
    list.foldl(removal_retract(S, rc_author_withdrawn), 141 .. 160, W2, W3),

    expire(at(1025), Due1, W3, W4),
    check("[LNLS.4.7] the FIFO expires its due facts, in deadline order",
        ( if list.map(removal_key, Due1) = 1 .. 25 then yes else no ),
        !T, !IO),
    expire(at(1950), Due2, W4, W5),
    check("[LNLS.4.7] FIFO and heap merge in deadline order",
        ( if list.map(removal_key, Due2) = (26 .. 50) ++ list.reverse(51 .. 60)
          then yes else no ), !T, !IO),

    Live = facts_of_schema(W5, S ^ s_id),
    check("[LNLS.4.7] the per-schema membership keeps INSERTION order",
        ( if list.map(removal_key, Live) = (161 .. 200) ++ (61 .. 100)
          then yes else no ), !T, !IO),
    check("[LNLS.4.7] the fact table, the membership and the count agree",
        ( if
            live_count(W5) = 80,
            list.length(Live) = 80,
            live_count(W5) - lerr_9_10_capacity_count(W5, [S ^ s_id]) = 80,
            list.all_true(
                (pred(F::in) is semidet :- lookup_fact(W5, F ^ f_id, F)), Live)
          then yes else no ), !T, !IO),
    check("[LNLS.4.7] the identity index finds each live fact, and no other",
        ( if
            list.all_true(
                (pred(F::in) is semidet :-
                    fact_for_identity(W5, removal_identity(S, removal_key(F)),
                        F)),
                Live),
            list.all_true(
                (pred(K::in) is semidet :-
                    not fact_for_identity(W5, removal_identity(S, K), _)),
                (1 .. 60) ++ (101 .. 160))
          then yes else no ), !T, !IO),
    expire(at(999999), Stale, W5, W6),
    check("[LNLS.4.7] the deadlines of removed facts expire nothing",
        ( if Stale = [], live_count(W6) = 80 then yes else no ), !T, !IO).

:- pred removal_assert(schema::in, int::in, wm::in, wm::out) is det.

removal_assert(S, K, !W) :-
    ( if K =< 50 then
        Deadline = yes(at(1000 + K))
    else if K =< 60 then
        Deadline = yes(at(2000 - K))
    else
        Deadline = no
    ),
    assert_fact(S, [int(int64.from_int(K)), int(0i64)], at(100), Deadline,
        tms_none, live, _, !W).

:- pred removal_supersede(schema::in, int::in, wm::in, wm::out) is det.

removal_supersede(S, K, !W) :-
    assert_fact(S, [int(int64.from_int(K)), int(1i64)], at(200), no,
        tms_none, live, _, !W).

:- pred removal_retract(schema::in, retract_cause::in, int::in,
                        wm::in, wm::out) is det.

removal_retract(S, Cause, K, !W) :-
    ( if
        fact_for_identity(!.W, removal_identity(S, K), F),
        retract_fact(F ^ f_id, Cause, !.W, W1)
    then
        !:W = W1
    else
        unexpected($pred, "no live fact for the key")
    ).

:- func removal_identity(schema, int) = fact_identity.

removal_identity(S, K) = Id :-
    ( if project_identity(S,
            array.from_list([int(int64.from_int(K)), int(0i64)])) = yes(Id0)
    then
        Id = Id0
    else
        unexpected($pred, "a logical schema has an identity")
    ).

:- func removal_key(fact) = int.

removal_key(F) = K :-
    ( if array.semidet_lookup(F ^ f_slots, 0, int(K64)) then
        K = int64.cast_to_int(K64)
    else
        unexpected($pred, "slot 0 is an Int")
    ).

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% The evaluator
%-----------------------------------------------------------------------------%
%
% The `k/` checks are `formal/k/dsexpr.k`'s own vectors, each named with the K
% program it comes from and the value that model reduces it to. The rest cover
% what the model does not have: `err`.

    % A frame of one slot, not yet bound.
    %
:- func ectx = eval_ctx.

ectx = eval_ctx([], no, init_wm, map.init, init_interns, at(0), no, map.init,
    1, init_cache, init_series_state).

    % [LTIM.10.6]-[LTIM.10.7]: `ectx` whose working memory holds these
    % `TimeZoneOffset` rows -- (zone, valid_from, valid_until, offset_s) --
    % asserted as the host asserts them, the zones interned. A zone the rows
    % name reaches the index as an evaluation's `text` does, through the
    % intern table (`ds.eval.ltim_10_7_resolve`).
    %
:- func tz_ectx(list({string, int64, int64, int64})) = eval_ctx.

tz_ectx(Rows) = (ectx ^ ec_wm := WM) ^ ec_interns := IT :-
    list.foldl2(tz_put_row, Rows, init_wm_for([], yes(tzo_schema ^ s_id)), WM,
        init_interns, IT).

    % The built-in schema's shape ([LIMP.12.2]): zone and valid_from the key,
    % valid_until and offset_s mutable.
    %
:- func tzo_schema = schema.

tzo_schema = schema(make_schema_id(9u32), make_schema_name(make_intern_ref(1u32)),
    lc_logical([wslot_kind(0, k_string, role_key, exact),
                wslot_kind(1, k_time, role_key, exact),
                wslot_kind(2, k_time, role_mutable, exact),
                wslot_kind(3, k_int, role_mutable, exact)], no),
    no, no).

:- pred tz_put_row({string, int64, int64, int64}::in, wm::in, wm::out,
                   intern_table::in, intern_table::out) is det.

tz_put_row({Zone, From, Until, Offset}, !WM, !IT) :-
    intern(Zone, Ref, !IT),
    assert_fact(tzo_schema, [str(Ref), int(From), int(Until), int(Offset)],
        at(0), no, tms_none, live, Result, !WM),
    ( if ( Result = inserted(_) ; Result = replaced(_, _) ) then
        true
    else
        unexpected($pred, "a TimeZoneOffset row was refused")
    ).

    % The two zones most tests read, each one offset over the longest period a
    % row can state, [INT64_MIN, INT64_MAX) ([LTIM.10.7]). "UTC" takes no row
    % ([LTIM.10.8]).
    %
:- func two_zones = eval_ctx.

two_zones = tz_ectx([
    {"America/Los_Angeles", int64.min_int64, int64.max_int64, -28800i64},
    {"Asia/Tokyo", int64.min_int64, int64.max_int64, 32400i64}]).

    % Evaluate and compare against an expected value.
:- pred evals(string::in, expr::in, ds_value::in,
              tally::in, tally::out, io::di, io::uo) is det.

evals(Name, E, Want, !T, !IO) :-
    eval(E, ectx, Outcome),
    check(Name, ( if Outcome = ev_ok(Want) then yes else no ), !T, !IO).

:- func lit_int(int64) = expr.
:- func lit_float(float) = expr.
:- func lit_bool(bool) = expr.
:- func lit_null = expr.

    % Evaluate to a Float zero and compare its SIGN. `evals` cannot: Mercury
    % compares -0.0 equal to 0.0, so a wrong sign passes `=`. The sign bit is
    % read the way `ds.wire` reads it.
:- pred evals_zero(string::in, expr::in, bool::in,
                   tally::in, tally::out, io::di, io::uo) is det.

evals_zero(Name, E, WantNegative, !T, !IO) :-
    eval(E, ectx, Outcome),
    check(Name,
        ( if Outcome = ev_ok(float(F)), F = 0.0 then
            ( if negative_zero(F) then WantNegative else bool.not(WantNegative) )
        else
            no
        ), !T, !IO).

:- pred negative_zero(float::in) is semidet.

negative_zero(F) :-
    F = 0.0,
    i64.from_decimal(float.float64_bits_string(F), Bits),
    Bits < 0i64.

    % -0.0, made at run time: a literal's sign is the parser's and the code
    % generator's to keep, and a test of it should not depend on either.
:- func neg_zero = float.

neg_zero = (-1.0) * 0.0.

lit_int(N) = e_lit(int(N)).
lit_float(F) = e_lit(float(F)).
lit_bool(B) = e_lit(bool(B)).
lit_null = e_lit(null).

    % `EQ(x, null-literal)`, which propagates null per [LNUL.4.1]. No
    % loadable artefact holds it, since `== null` is a compile error
    % ([LNUL.4.4]); `test_null_test` pins what the evaluator answers.
:- func eq_null(expr) = expr.

eq_null(E) = e_binop(op_eq, E, lit_null).

:- pred test_eval(tally::in, tally::out, io::di, io::uo) is det.

test_eval(!T, !IO) :-
    % -- formal/k/dsexpr.k's vectors --------------------------------------

    % dsexpr.arith_int: `1 + 2 * 3` -> 7. All-Int arithmetic stays Int
    % [LEXP.7.2].
    evals("k/arith_int: 1 + 2 * 3 = 7",
        e_binop(op_add, lit_int(1i64),
            e_binop(op_mul, lit_int(2i64), lit_int(3i64))),
        int(7i64), !T, !IO),

    % dsexpr.promote: `2 < 1 + 2.0` -> true. Any Float operand promotes
    % [LEXP.7.3].
    evals("k/promote: 1 + 2.0 promotes to Float",
        e_binop(op_add, lit_int(1i64), lit_float(2.0)), float(3.0), !T, !IO),
    evals("k/promote: 2 < 1 + 2.0 is true",
        e_binop(op_lt, lit_int(2i64),
            e_binop(op_add, lit_int(1i64), lit_float(2.0))),
        bool(yes), !T, !IO),

    % dsexpr.div_float: `3 < (7 / 2)` -> true. `/` is always Float, whatever
    % the operands [LEXP.7.4].
    evals("k/div_float: 7 / 2 = 3.5, NOT 3",
        e_binop(op_div, lit_int(7i64), lit_int(2i64)), float(3.5), !T, !IO),
    evals("k/div_float: 3 < (7 / 2) is true",
        e_binop(op_lt, lit_int(3i64),
            e_binop(op_div, lit_int(7i64), lit_int(2i64))),
        bool(yes), !T, !IO),

    % dsexpr.null_add: `is_null(null + 1)` -> true. Arithmetic with a null
    % operand yields null [LNUL.4.1].
    evals("k/null_add: null + 1 = null",
        e_binop(op_add, lit_null, lit_int(1i64)), null, !T, !IO),
    evals("k/null_add: is_null(null + 1) is TRUE",
        is_t(e_binop(op_add, lit_null, lit_int(1i64)), is_null), bool(yes), !T, !IO),

    % dsexpr.null_cmp: `null < 5` -> null. Comparison propagates null too, not
    % false, so a null never fires ([LNUL.4.3]).
    evals("k/null_cmp: null < 5 = null, NOT false",
        e_binop(op_lt, lit_null, lit_int(5i64)), null, !T, !IO),

    % dsexpr.kleene_and / kleene_or: and = min, or = max over
    % false < null < true [LNUL.4.2].
    evals("k/kleene_and: true and null = null",
        e_binop(op_and, lit_bool(yes), lit_null), null, !T, !IO),
    evals("k/kleene_or: false or null = null",
        e_binop(op_or, lit_bool(no), lit_null), null, !T, !IO),

    % dsexpr.coalesce_null / coalesce_val.
    evals("k/coalesce_null: null ?? 7 = 7",
        e_coalesce(lit_null, lit_int(7i64)), int(7i64), !T, !IO),
    evals("k/coalesce_val: 5 ?? 7 = 5",
        e_coalesce(lit_int(5i64), lit_int(7i64)), int(5i64), !T, !IO),

    % dsexpr.is_null_no.
    evals("k/is_null_no: is_null(5) is false",
        is_t(lit_int(5i64), is_null), bool(no), !T, !IO),

    % dsexpr.compound: `is_null(null) and 1 < 2` -> true.
    evals("k/compound: is_null(null) and 1 < 2",
        e_binop(op_and, is_t(lit_null, is_null),
            e_binop(op_lt, lit_int(1i64), lit_int(2i64))),
        bool(yes), !T, !IO),

    % dsexpr.cmp_lt / cmp_le.
    evals("k/cmp_lt: 2 < 3", e_binop(op_lt, lit_int(2i64), lit_int(3i64)),
        bool(yes), !T, !IO),
    evals("k/cmp_le: 3 <= 3", e_binop(op_le, lit_int(3i64), lit_int(3i64)),
        bool(yes), !T, !IO),

    test_kleene_tables(!T, !IO),
    test_one_absent(!T, !IO),
    test_null_test(!T, !IO),
    test_is_test(!T, !IO),
    test_hard_faults(!T, !IO),
    test_int64_width(!T, !IO),
    test_lecc_1_2_segments(!T, !IO),
    test_halt_latch(!T, !IO),
    test_rdsc_4a_9_1_index_faults(!T, !IO),
    test_rdsc_4a_6_2_regex_subject_faults(!T, !IO).

    % [LCCO.8.3.2]'s match is at segment boundaries, and [LECC.1.2]'s segments
    % are separated by `.` alone: `_` is a character inside one. The patterns
    % are under `adapter`, a family [LECC.6.4] admits.
    %
:- pred test_lecc_1_2_segments(tally::in, tally::out, io::di, io::uo) is det.

test_lecc_1_2_segments(!T, !IO) :-
    check("`adapter` does not match `adapter_failed`: `_` is inside a segment",
        ( if code_out("adapter_failed", "adapter") = ev_ok(bool(no)) then yes
          else no ), !T, !IO),
    check("`adapter` matches `adapter.failed` at the `.` boundary",
        ( if code_out("adapter.failed", "adapter") = ev_ok(bool(yes)) then yes
          else no ), !T, !IO),
    check("`adapter.x_y` matches itself and `adapter.x_y.z`",
        ( if
            code_out("adapter.x_y", "adapter.x_y") = ev_ok(bool(yes)),
            code_out("adapter.x_y.z", "adapter.x_y") = ev_ok(bool(yes))
          then yes else no ), !T, !IO),
    check("`adapter` does not match `adapterx`: a character prefix is not one",
        ( if code_out("adapterx", "adapter") = ev_ok(bool(no)) then yes
          else no ), !T, !IO).

:- func code_out(string, string) = eval_outcome.

code_out(Code, Pattern) = Out :-
    eval(e_call(fn_error_code_matches, [e_lit(text(Code)), e_lit(text(Pattern))]),
        ectx, Out).

    % A DS `Int` is `int64` on every host. Values at and past +/-2^31, and at
    % the `int64` edges, through the evaluator's arithmetic and through
    % `ds.i64`'s three hand-written conversions: wrap, not trap; exact
    % truncation; the parse range.
    %
:- pred test_int64_width(tally::in, tally::out, io::di, io::uo) is det.

test_int64_width(!T, !IO) :-
    evals("2^31 - 1 + 1 is 2^31, not a 32-bit wrap",
        e_binop(op_add, lit_int(2147483647i64), lit_int(1i64)),
        int(2147483648i64), !T, !IO),
    evals("-2^31 - 1 is -2^31 - 1",
        e_binop(op_sub, lit_int(-2147483648i64), lit_int(1i64)),
        int(-2147483649i64), !T, !IO),
    evals("2^32 * 2^32 wraps to 0 [LEXP.7.13.1]",
        e_binop(op_mul, lit_int(4294967296i64), lit_int(4294967296i64)),
        int(0i64), !T, !IO),
    evals("INT64_MAX + 1 wraps to INT64_MIN",
        e_binop(op_add, lit_int(int64.max_int64), lit_int(1i64)),
        int(int64.min_int64), !T, !IO),
    % `**` is the `FN_POW` call, as the compiler lowers it ([LEXP.7.3a]).
    evals("2 ** 62",
        e_call(fn_pow, [lit_int(2i64), lit_int(62i64)]),
        int(4611686018427387904i64), !T, !IO),
    evals("2 ** 63 wraps to INT64_MIN",
        e_call(fn_pow, [lit_int(2i64), lit_int(63i64)]),
        int(int64.min_int64), !T, !IO),
    evals("3 ** 40 wraps modulo 2^64",
        e_call(fn_pow, [lit_int(3i64), lit_int(40i64)]),
        int(-6289078614652622815i64), !T, !IO),
    evals("1 << 40",
        e_binop(op_shl, lit_int(1i64), lit_int(40i64)),
        int(1099511627776i64), !T, !IO),
    evals("-1 >> 40 is arithmetic",
        e_binop(op_shr, lit_int(-1i64), lit_int(40i64)),
        int(-1i64), !T, !IO),

    % [LEXP.7.14.1]: the count is never reduced modulo 64, and a negative
    % run-time count is a DOMAIN trap.
    evals("-8 >> 64 is -1, not -8 >> 0",
        e_binop(op_shr, lit_int(-8i64), lit_int(64i64)), int(-1i64), !T, !IO),
    evals("5 >> 64 is 0",
        e_binop(op_shr, lit_int(5i64), lit_int(64i64)), int(0i64), !T, !IO),
    evals("2 >> 65 is 0, not 2 >> 1",
        e_binop(op_shr, lit_int(2i64), lit_int(65i64)), int(0i64), !T, !IO),
    evals("1 << 64 is 0, not 1 << 0",
        e_binop(op_shl, lit_int(1i64), lit_int(64i64)), int(0i64), !T, !IO),
    evals("1 << 63 is INT64_MIN",
        e_binop(op_shl, lit_int(1i64), lit_int(63i64)),
        int(int64.min_int64), !T, !IO),
    evals("a count of 2^40 saturates rather than wrapping on a 32-bit cast",
        e_binop(op_shl, lit_int(3i64), lit_int(1099511627776i64)),
        int(0i64), !T, !IO),
    check("a negative run-time count is a DOMAIN trap, for <<",
        ( if eval(e_binop(op_shl, lit_int(1i64), lit_int(-1i64)), ectx,
                ev_fault(rf_domain))
          then yes else no ), !T, !IO),
    check("and for >>",
        ( if eval(e_binop(op_shr, lit_int(1i64), lit_int(-1i64)), ectx,
                ev_fault(rf_domain))
          then yes else no ), !T, !IO),
    evals("INT64_MIN // 2 floors",
        e_binop(op_floordiv, lit_int(int64.min_int64), lit_int(2i64)),
        int(-4611686018427387904i64), !T, !IO),

    % Int against Int compares exactly, as libds's `val_cmp` INT arm does:
    % 2^53 + 1 and 2^53 both round to the double 2^53.
    evals("2^53 + 1 == 2^53 is false",
        e_binop(op_eq, lit_int(9007199254740993i64),
            lit_int(9007199254740992i64)),
        bool(no), !T, !IO),
    evals("2^53 + 1 != 2^53 is true",
        e_binop(op_ne, lit_int(9007199254740993i64),
            lit_int(9007199254740992i64)),
        bool(yes), !T, !IO),
    evals("2^53 < 2^53 + 1",
        e_binop(op_lt, lit_int(9007199254740992i64),
            lit_int(9007199254740993i64)),
        bool(yes), !T, !IO),
    evals("2^53 + 1 <= 2^53 is false",
        e_binop(op_le, lit_int(9007199254740993i64),
            lit_int(9007199254740992i64)),
        bool(no), !T, !IO),
    evals("INT64_MAX > INT64_MAX - 1",
        e_binop(op_gt, lit_int(int64.max_int64),
            lit_int(9223372036854775806i64)),
        bool(yes), !T, !IO),
    evals("INT64_MIN + 1 >= INT64_MIN",
        e_binop(op_ge, lit_int(-9223372036854775807i64),
            lit_int(int64.min_int64)),
        bool(yes), !T, !IO),
    % The control: a mixed pair still goes through double, as libds's
    % cross-kind arm does, so 2^53 + 1 against 2^53 as a Float is equal.
    evals("2^53 + 1 == 2^53 as Float is true (mixed pair, via double)",
        e_binop(op_eq, lit_int(9007199254740993i64),
            lit_float(9007199254740992.0)),
        bool(yes), !T, !IO),

    check("truncate 1e18 exactly",
        ( if i64.truncate_float(1.0e18, I1), I1 = 1000000000000000000i64
          then yes else no ), !T, !IO),
    check("truncate -(2^52 + 1) exactly",
        ( if i64.truncate_float(-4503599627370497.0, I2),
             I2 = -4503599627370497i64
          then yes else no ), !T, !IO),
    check("truncate is toward zero, negative included",
        ( if i64.truncate_float(-2.5, I3), I3 = -2i64,
             i64.truncate_float(2.999, I4), I4 = 2i64
          then yes else no ), !T, !IO),
    check("truncate -2^63 is INT64_MIN",
        ( if i64.truncate_float(-9223372036854775808.0, I5),
             I5 = int64.min_int64
          then yes else no ), !T, !IO),
    check("truncate 2^63 is out of range",
        ( if i64.truncate_float(9223372036854775808.0, _) then no else yes ),
        !T, !IO),
    check("truncate NaN is refused",
        ( if i64.truncate_float(nan_f, _) then no else yes ), !T, !IO),

    % `Float :: Int` past the Int64 range traps NOT_REPRESENTABLE
    % ([LERR.1.4.9]'s `1e30`), as libds's `adapter_ds_float_to_int` does.
    check("1e30 :: Int traps NOT_REPRESENTABLE",
        ( if eval(e_call(fn_float_to_int, [lit_float(1.0e30)]), ectx,
                ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    check("-1e30 :: Int traps NOT_REPRESENTABLE",
        ( if eval(e_call(fn_float_to_int, [lit_float(-1.0e30)]), ectx,
                ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    check("2^63 :: Int traps -- the first positive past INT64_MAX",
        ( if eval(e_call(fn_float_to_int, [lit_float(9223372036854775808.0)]),
                ectx, ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    evals("-2^63 :: Int is INT64_MIN, in range",
        e_call(fn_float_to_int, [lit_float(-9223372036854775808.0)]),
        int(int64.min_int64), !T, !IO),
    evals("-2.5 :: Int truncates toward zero",
        e_call(fn_float_to_int, [lit_float(-2.5)]), int(-2i64), !T, !IO),
    % Bound, then matched: `rf_cast_non_finite(_)` in the call's output
    % position is a partially instantiated argument, which is a mode error.
    check("inf :: Int is still the non-finite trap",
        ( if eval(e_call(fn_float_to_int, [lit_float(inf_f)]), ectx, InfOut),
             InfOut = ev_fault(rf_cast_non_finite(_))
          then yes else no ), !T, !IO),

    check("parse INT64_MAX",
        ( if i64.from_decimal("9223372036854775807", P1),
             P1 = int64.max_int64 then yes else no ), !T, !IO),
    check("parse INT64_MIN",
        ( if i64.from_decimal("-9223372036854775808", P2),
             P2 = int64.min_int64 then yes else no ), !T, !IO),
    check("parse 2^63 is out of range",
        ( if i64.from_decimal("9223372036854775808", _) then no else yes ),
        !T, !IO),
    check("parse takes string.to_int's leading `+`",
        ( if i64.from_decimal("+5", P3), P3 = 5i64 then yes else no ),
        !T, !IO),
    check("parse refuses empty, a space and trailing text",
        ( if ( i64.from_decimal("", _) ; i64.from_decimal(" 5", _)
             ; i64.from_decimal("5x", _) ; i64.from_decimal("-", _) )
          then no else yes ), !T, !IO),
    check("hex INT64_MAX, either case",
        ( if i64.from_base_digits(16, "7fffffffffffffff", H1),
             H1 = int64.max_int64,
             i64.from_base_digits(16, "FF", H2), H2 = 255i64
          then yes else no ), !T, !IO),
    check("based digits refuse empty and a separator",
        ( if ( i64.from_base_digits(2, "", _)
             ; i64.from_base_digits(10, "1_0", _) )
          then no else yes ), !T, !IO),
    % [LLEX.11.1]: `DIGIT ('_'? DIGIT)*` -- a `_` sits between two
    % digits, one at a time, as a source literal spells it ([LCST.4.5.7]).
    check("[LLEX.11.1] a String::Int? literal takes one `_` between digits",
        ( if i64.from_literal("3_1", L1), L1 = 31i64,
             i64.from_literal("0b1_1111", L2), L2 = 31i64,
             i64.from_literal("-0x1_F", L3), L3 = -31i64
          then yes else no ), !T, !IO),
    check("[LLEX.11.1] a String::Int? literal refuses a doubled `_`",
        ( if ( i64.from_literal("1__2", _) ; i64.from_literal("1__0", _)
             ; i64.from_literal("0x1__F", _) ; i64.from_literal("0b1__1", _) )
          then no else yes ), !T, !IO),
    check("[LLEX.11.1] and a `_` at either end of the digits",
        ( if ( i64.from_literal("31_", _) ; i64.from_literal("_31", _)
             ; i64.from_literal("0x_1F", _) )
          then no else yes ), !T, !IO),
    check("INT64_MIN renders all 19 digits",
        ( if bare_int(int64.min_int64) = "-9223372036854775808"
          then yes else no ), !T, !IO).

    % The halt latch ([LERR.1] rung 7, [NCBK.2.9], [RARC.5.8.13]), driven
    % through a real artefact so the fault is seen to reach it:
    % `47_emit_softfail.ds` writes `zeta: i.txt + i.txt`, and `+` on two
    % Strings is an EngineError on a clean node ([IRET.9.6]).
    %
:- pred test_halt_latch(tally::in, tally::out, io::di, io::uo) is det.

test_halt_latch(!T, !IO) :-
    with_fixture("47_emit_softfail.dsc", check_halt_latch, !T, !IO).

:- pred check_halt_latch(program::in, tally::in, tally::out,
                         io::di, io::uo) is det.

check_halt_latch(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "In", S) then
        engine_intern("ab", Txt, E0, E1),
        check("a fresh engine is not halted",
            ( if engine_halted(E1) = no then yes else no ), !T, !IO),
        host_assert(S, [int(1i64), str(Txt)], no_deadline, R1, _, E1, E2),
        check("the assert itself is admitted -- the fault is at fire time",
            ( if R1 = inserted(_) then yes else no ), !T, !IO),
        pump(default_budget, Fired, E2, E3),
        % The firing's own events stand: rung 7 abandons what comes after.
        check("the pump that faults still reports its effects",
            ( if Fired = [_ | _] then yes else no ), !T, !IO),
        check("and the engine is latched, naming the fault that halted it",
            ( if engine_halted(E3) = yes(ee_expr_fault(rf_artefact_lied))
              then yes else no ), !T, !IO),

        % Every entry point is a no-op afterwards ([NCBK.2.9]).
        pump(default_budget, Again, E3, E4),
        check("a pump on a halted engine does nothing and emits nothing",
            ( if Again = [] then yes else no ), !T, !IO),
        host_assert(S, [int(2i64), str(Txt)], no_deadline, R2, AE, E4, E5),
        check("an assert is refused, carrying the halting error",
            ( if R2 = refused_halted(ee_expr_fault(rf_artefact_lied)),
                 AE = []
              then yes else no ), !T, !IO),
        check("...and nothing entered working memory",
            ( if engine_fact_count(E5) = engine_fact_count(E3)
              then yes else no ), !T, !IO),
        % The source, not the held sample: an advance moves only the source
        % ([NTST.3.3]), so `engine_now` would stand still whether or not the
        % halt refused it. The control is the same advance on E0, not halted.
        advance(duration_from_ns(1000000000u64), ClockEffects, E5, E6),
        advance(duration_from_ns(1000000000u64), _, E0, Control),
        check("the clock does not advance either",
            ( if ClockEffects = [],
                 engine_clock_now(E6) = engine_clock_now(E5),
                 engine_clock_now(Control) \= engine_clock_now(E0)
              then yes else no ), !T, !IO),
        check("and the latch never clears",
            ( if engine_halted(E6) = yes(_) then yes else no ), !T, !IO)
    else
        check("47_emit_softfail declares In", no, !T, !IO)
    ).

    % [RDSC.4a.9.1]: an index in its field's range that names nothing faults
    % where the engine uses it, an EngineError naming the node or rule that
    % used it, and the tier halts; never a failing test, a skipped write or a
    % dropped withdraw.
    %
    % Over the hand-built network vectors: "S" has one slot, `t`, so slot 1
    % names nothing, and the asserted S has `t = 1.0`. AlphaNode 1, BetaNode 2
    % (root) and TerminalNode 3 of rule "R", as `test_network` builds them.
    %
    %   - an AlphaTest whose slot is past the schema: ARTEFACT_LIED, `$alpha_1`,
    %     raised by the assert; beside a test that answers false, first and
    %     second, the fact is rejected and nothing is raised ([IRET.6.4]);
    %     beside one that answers true, either side, it faults;
    %   - a VarExpr join test reading the candidate's slot 1: ARTEFACT_LIED,
    %     `$beta_2`;
    %   - a SlotAssign to slot 1: ARTEFACT_LIED, the rule "R", at the pump;
    %   - a withdraw of token position 1, past the one-fact token:
    %     PATTERN_INDEX, the rule "R", at the pump.
    %
    % libds is held to the same cases (test_fault_emission.c,
    % test_rdsc_4a_9_1__*).
    %
    %@spec [RDSC.4a.9.1]
:- pred test_rdsc_4a_9_1_index_faults(tally::in, tally::out,
                                      io::di, io::uo) is det.

test_rdsc_4a_9_1_index_faults(!T, !IO) :-
    % AlphaTest CMP: slot, op (GT 3, LT 2), int literal.
    Cmp = ( func(Slot, Op, Lit) =
        [0x08, 0x01, 0x10, Slot, 0x18, Op, 0x22, 0x02, 0x08, Lit] ),
    Bad = Cmp(1, 3, 42),        % slot 1 > 42: names no slot of "S"
    False = Cmp(0, 3, 42),      % t > 42: false
    True = Cmp(0, 2, 42),       % t < 42: true
    Alfa = frame(268, [0x08, 0x01, 0x12, 0x01, 0x53]),
    Beta = [0x0A, 0x07, 0xEA, 0x10, 0x04, 0x08, 0x02, 0x10, 0x01],
    Term = [0x0A, 0x0A, 0xF2, 0x10, 0x07, 0x08, 0x03, 0x10, 0x02,
        0x1A, 0x01, 0x52],
    list.foldl2(check_alpha_index_case("[RDSC.4a.9.1]",
            "an AlphaTest slot past the schema", Beta ++ Term),
        [{"alone", [Bad], yes},
         {"first, before a test that answers false", [Bad, False], no},
         {"second, after a test that answers false", [False, Bad], no},
         {"first, before a test that answers true", [Bad, True], yes},
         {"second, after a test that answers true", [True, Bad], yes}],
        !T, !IO),

    % `candidate.1 == 1`: BINOP EQ over VarExpr(255, 1) and an int literal.
    JoinTest = [0x32, 0x0F, 0x08, 0x06,
        0x12, 0x07, 0x2A, 0x05, 0x08, 0xFF, 0x01, 0x10, 0x01,
        0x1A, 0x02, 0x08, 0x01],
    check_index_fault("[RDSC.4a.9.1] a VarExpr join test reading a slot past "
            ++ "the schema faults ARTEFACT_LIED, naming $beta_2",
        Alfa ++ frame(269, [0x08, 0x02, 0x10, 0x01, 0x22]
            ++ varint(list.length(JoinTest)) ++ JoinTest) ++ Term,
        no, rf_artefact_lied, "$beta_2", !T, !IO),

    % ACTION_ASSERT "S" with one SlotAssign, slot 1 := 1.
    AssertSlot1 = [0x08, 0x01, 0x1A, 0x01, 0x53,
        0x22, 0x06, 0x08, 0x01, 0x12, 0x02, 0x08, 0x01],
    check_index_fault("[RDSC.4a.9.1] a SlotAssign past the schema faults "
            ++ "ARTEFACT_LIED, naming the rule",
        Alfa ++ Beta ++ frame(270, term_with_action(AssertSlot1)),
        yes, rf_artefact_lied, "R", !T, !IO),

    % ACTION_WITHDRAW of token position 1.
    Withdraw1 = [0x08, 0x03, 0x30, 0x01],
    check_index_fault("[RDSC.4a.9.1] a withdraw past the token faults "
            ++ "PATTERN_INDEX, naming the rule",
        Alfa ++ Beta ++ frame(270, term_with_action(Withdraw1)),
        yes, rf_pattern_index, "R", !T, !IO).

    % [RDSC.4a.6.2]: a regex test whose subject is not a String faults,
    % ARTEFACT_LIED, naming `$alpha_1`, raised by the assert, and the tier
    % halts; never a failing test. It is one conjunct of the node's tests,
    % held as [RDSC.4a.9.1]'s slot index is: beside a test that answers
    % false, first and second, the fact is rejected and nothing is raised;
    % beside one that answers true, either side, it faults.
    %
    % Over the same network as `test_rdsc_4a_9_1_index_faults`: "S"'s one slot
    % `t` is a Float, asserted 1.0, so `t ~ /1/` reads a slot that is not a
    % String, and the pattern would match the number's text if the test read
    % it as one.
    %
    % libds is held to the same cases, and to the Bytes case this runtime has
    % no other representation for (test_fault_emission.c,
    % test_rdsc_4a_6_2__*).
    %
    %@spec [RDSC.4a.6.2]
:- pred test_rdsc_4a_6_2_regex_subject_faults(tally::in, tally::out,
                                              io::di, io::uo) is det.

test_rdsc_4a_6_2_regex_subject_faults(!T, !IO) :-
    % AlphaTest CMP: slot, op (GT 3, LT 2), int literal.
    Cmp = ( func(Slot, Op, Lit) =
        [0x08, 0x01, 0x10, Slot, 0x18, Op, 0x22, 0x02, 0x08, Lit] ),
    % AlphaTest REGEX (kind 2), slot 0, pattern "1" (field 5).
    Bad = [0x08, 0x02, 0x10, 0x00, 0x2A, 0x01, 0x31],
    False = Cmp(0, 3, 42),      % t > 42: false
    True = Cmp(0, 2, 42),       % t < 42: true
    Beta = [0x0A, 0x07, 0xEA, 0x10, 0x04, 0x08, 0x02, 0x10, 0x01],
    Term = [0x0A, 0x0A, 0xF2, 0x10, 0x07, 0x08, 0x03, 0x10, 0x02,
        0x1A, 0x01, 0x52],
    list.foldl2(check_alpha_index_case("[RDSC.4a.6.2]",
            "a REGEX AlphaTest on a Float slot", Beta ++ Term),
        [{"alone", [Bad], yes},
         {"first, before a test that answers false", [Bad, False], no},
         {"second, after a test that answers false", [False, Bad], no},
         {"first, before a test that answers true", [Bad, True], yes},
         {"second, after a test that answers true", [True, Bad], yes}],
        !T, !IO).

    % One AlphaNode case: the node's tests, and whether the assert faults.
    % `Clause` and `What` name the lie the case's bad test tells.
    %
:- pred check_alpha_index_case(string::in, string::in, list(int)::in,
                               {string, list(list(int)), bool}::in,
                               tally::in, tally::out, io::di, io::uo) is det.

check_alpha_index_case(Clause, What, Below, {Label, Tests, Faults}, !T, !IO) :-
    Net = frame(268, alpha_with_tests(Tests)) ++ Below,
    (
        Faults = yes,
        check_index_fault(Clause ++ " " ++ What ++ ", "
                ++ Label ++ ", faults ARTEFACT_LIED, naming $alpha_1",
            Net, no, rf_artefact_lied, "$alpha_1", !T, !IO)
    ;
        Faults = no,
        check("[IRET.6.4] " ++ What ++ ", " ++ Label
                ++ ": the fact is rejected and nothing is raised",
            ( if
                index_fault_run(Net, no, Fx, E),
                engine_errors(Fx) = [],
                engine_halted(E) = no
              then yes else no ), !T, !IO)
    ).

    % Load `Net` after "S"'s schema group, assert S(t = 1.0), and pump if
    % `Pump`: exactly one EngineError, `Fault`, naming `Rule`, and the tier
    % halted on it.
    %
:- pred check_index_fault(string::in, list(int)::in, bool::in,
                          runtime_fault::in, string::in,
                          tally::in, tally::out, io::di, io::uo) is det.

check_index_fault(Label, Net, Pump, Fault, Rule, !T, !IO) :-
    check(Label,
        ( if
            index_fault_run(Net, Pump, Fx, E),
            engine_errors(Fx) = [ee_expr_fault(Fault) - Site],
            fault_rule_name(engine_interns(E), Site ^ fs_rule) = Rule,
            engine_halted(E) = yes(ee_expr_fault(Fault))
          then yes else no ), !T, !IO).

:- pred index_fault_run(list(int)::in, bool::in, list(effect)::out,
                        engine::out) is semidet.

index_fault_run(Net, Pump, Fx, E) :-
    load_dsc(sealed(dsco_frame ++ network_schema_s ++ Net), loaded(P)),
    find_schema(schemas(P), interns(P), "S", S),
    engine_use_mock_clock(init_engine(P), E0),
    host_assert(S, [float(1.0)], no, _, AssertFx, E0, E1),
    (
        Pump = yes,
        pump(default_budget, PumpFx, E1, E),
        Fx = AssertFx ++ PumpFx
    ;
        Pump = no,
        Fx = AssertFx,
        E = E1
    ).

:- func engine_errors(list(effect)) = list(pair(engine_error, fault_site)).

engine_errors(Fx) = list.filter_map(
    ( func(Effect) = Err - Site is semidet :-
        Effect = eff_event(se_engine_error(Err, Site)) ), Fx).

    % AlphaNode 1 over schema "S" with `Tests` as its AlphaTests (field 3), in
    % order.
    %
:- func alpha_with_tests(list(list(int))) = list(int).

alpha_with_tests(Tests) =
    [0x08, 0x01, 0x12, 0x01, 0x53] ++ list.condense(list.map(
        ( func(Test) = [0x1A] ++ varint(list.length(Test)) ++ Test ), Tests)).

:- pred test_kleene_tables(tally::in, tally::out, io::di, io::uo) is det.

test_kleene_tables(!T, !IO) :-
    % The full boundary rows. `and` = min and `or` = max over the chain
    % false < null < true ([LNUL.4.2]), so `false and null` is false.
    evals("and: false and null = FALSE (min, so the false wins)",
        e_binop(op_and, lit_bool(no), lit_null), bool(no), !T, !IO),
    evals("and: null and false = false",
        e_binop(op_and, lit_null, lit_bool(no)), bool(no), !T, !IO),
    evals("and: null and true = null",
        e_binop(op_and, lit_null, lit_bool(yes)), null, !T, !IO),
    evals("and: null and null = null",
        e_binop(op_and, lit_null, lit_null), null, !T, !IO),

    evals("or: true or null = TRUE (max, so the true wins)",
        e_binop(op_or, lit_bool(yes), lit_null), bool(yes), !T, !IO),
    evals("or: null or true = true",
        e_binop(op_or, lit_null, lit_bool(yes)), bool(yes), !T, !IO),
    evals("or: null or false = null",
        e_binop(op_or, lit_null, lit_bool(no)), null, !T, !IO),
    evals("or: null or null = null",
        e_binop(op_or, lit_null, lit_null), null, !T, !IO),

    evals("not null = null", e_unop(op_not, lit_null), null, !T, !IO),

    % [LNUL.4.3]: null never fires. `admits` is the Rete boundary, and every
    % absent and every non-boolean declines.
    check("`null` does not admit a match at the Rete boundary",
        ( if eval(lit_null, ectx, O1), admits(O1) then no else yes ), !T, !IO),
    check("nor does a fault",
        ( if eval(e_binop(op_div, lit_int(1i64), lit_int(0i64)), ectx, O2),
             admits(O2) then no else yes ), !T, !IO),
    check("nor does a non-boolean -- 7 is not a predicate",
        ( if eval(lit_int(7i64), ectx, O3), admits(O3) then no else yes ),
        !T, !IO),
    check("but `true` does",
        ( if eval(lit_bool(yes), ectx, O4), admits(O4) then yes else no ),
        !T, !IO),

    % [LNUL.4.7], the negated half: `blocks` is not the negation of `admits`.
    % "A fact for which `C` is `true` (a match) or `null` (unknown) blocks
    % satisfaction", so only a definite `false` lets the negation through.
    % `LNUL.4.7a` is the vector.
    check("[LNUL.4.7] `null` BLOCKS a negated existence",
        ( if eval(lit_null, ectx, B1), blocks(B1) then yes else no ),
        !T, !IO),
    check("[LNUL.4.7] so does `true`",
        ( if eval(lit_bool(yes), ectx, B2), blocks(B2) then yes else no ),
        !T, !IO),
    check("[LNUL.4.7] `false` does NOT block -- the negation passes",
        ( if eval(lit_bool(no), ectx, B3), blocks(B3) then no else yes ),
        !T, !IO),
    check("a non-boolean does not block either -- 7 is not a predicate",
        ( if eval(lit_int(7i64), ectx, B4), blocks(B4) then no else yes ),
        !T, !IO),
    check("nor does a fault: [LNUL.4.7] says nothing of a trap",
        ( if eval(e_binop(op_div, lit_int(1i64), lit_int(0i64)), ectx, B5),
             blocks(B5) then no else yes ), !T, !IO),

    % The comparison as the fixture writes it: the value the beta sees for
    % `s.state > 85.0` on a null reading.
    check("[LNUL.4.7] `null > 85.0` blocks, which `LNUL.4.7a` turns on",
        ( if eval(e_binop(op_gt, lit_null, e_lit(float(85.0))), ectx, B6),
             blocks(B6) then yes else no ), !T, !IO),

    % `not (x > 85)` on a missing reading.
    evals("`not (null > 85)` is null, so the rule does NOT fire",
        e_unop(op_not, e_binop(op_gt, lit_null, lit_int(85i64))), null, !T, !IO),

    % [LEXP.3.2]: the rounding table, at the values that tell the four apart.
    % `round` is ties-to-even, which Mercury's own `round_to_int` is not.
    evals("[LEXP.3.2] round(2.5) is 2 -- ties to even, down",
        e_call(fn_round, [lit_float(2.5)]), int(2i64), !T, !IO),
    evals("[LEXP.3.2] round(3.5) is 4 -- ties to even, up",
        e_call(fn_round, [lit_float(3.5)]), int(4i64), !T, !IO),
    evals("[LEXP.3.2] round(-2.5) is -2",
        e_call(fn_round, [lit_float(-2.5)]), int(-2i64), !T, !IO),
    evals("[LEXP.3.2] round(2.6) is 3",
        e_call(fn_round, [lit_float(2.6)]), int(3i64), !T, !IO),
    evals("[LEXP.3.2] floor(-3.5) is -4",
        e_call(fn_floor, [lit_float(-3.5)]), int(-4i64), !T, !IO),
    evals("[LEXP.3.2] ceil(-3.5) is -3",
        e_call(fn_ceil, [lit_float(-3.5)]), int(-3i64), !T, !IO),
    evals("[LEXP.3.2] trunc(-3.5) is -3 -- toward zero, not floor",
        e_call(fn_trunc, [lit_float(-3.5)]), int(-3i64), !T, !IO),
    evals("[LEXP.3.2] sign(-3.5) is the Int -1",
        e_call(fn_sign, [lit_float(-3.5)]), int(-1i64), !T, !IO),
    evals("[LEXP.3.2] sign(-0.0) is 0",
        e_call(fn_sign, [lit_float(-0.0)]), int(0i64), !T, !IO),
    evals("[LEXP.3.2] sqrt(2.0) is the correctly-rounded root",
        e_call(fn_sqrt, [lit_float(2.0)]), float(1.4142135623730951), !T, !IO),
    % [LNUL.4.1] propagates `null` through operators; a builtin that demands
    % a kind raises on it ([LNUL.5.1]) as a TypeError whatever the call's
    % taint ([IRET.9.6] rung 1), libds's DS_FAULT_NULL_OPERAND.
    check("[LNUL.5.1] a math builtin on null is a TypeError, untainted",
        ( if eval(e_call(fn_floor, [lit_null]), ectx, ev_fault(rf_type_error))
          then yes else no ), !T, !IO),
    check("[LNUL.5.1] a null anywhere in the arguments decides it",
        ( if eval(e_call(fn_pow, [lit_float(2.0), lit_null]), ectx,
                ev_fault(rf_type_error))
          then yes else no ), !T, !IO),
    check("[LNUL.5.1] min of a null is a TypeError, not the comparison's null",
        ( if eval(e_call(fn_min, [lit_int(1i64), lit_null]), ectx,
                ev_fault(rf_type_error))
          then yes else no ), !T, !IO),
    % The control: without a null the same untainted mismatch is still the
    % artefact's.
    check("[IRET.9.6] a present wrong kind at a clean node is still the artefact's",
        ( if eval(e_call(fn_floor, [e_lit(bool(yes))]), ectx,
                ev_fault(rf_artefact_lied))
          then yes else no ), !T, !IO),
    % [LCST.4.3.4]: the conversions `::` compiles to are the exception, and
    % convert a null source to null without attempting the conversion.
    evals("[LCST.4.3.4] a conversion of null is null",
        e_call(fn_int_to_float, [lit_null]), null, !T, !IO),
    evals("[LCST.4.3.4] and so is the float-to-string conversion",
        e_call(fn_float_to_string, [lit_null]), null, !T, !IO),
    evals("[LCST.4.3.4] and the int-to-string conversion",
        e_call(fn_int_to_string, [lit_null]), null, !T, !IO),
    evals("[LCST.4.3.4] and the bool-to-string conversion",
        e_call(fn_bool_to_string, [lit_null]), null, !T, !IO),

    % [LEXP.3.7.1]: the two bit builtins, at the values that separate the
    % readings: a negative operand (the word's bits, vs. the magnitude's), 0,
    % and INT64_MIN, where negating in int64 is undefined and |x| = 2^63.
    evals("[LEXP.3.7.1] bit_length(0) is 0",
        e_call(fn_bit_length, [lit_int(0i64)]), int(0i64), !T, !IO),
    evals("[LEXP.3.7.1] bit_length(255) is 8",
        e_call(fn_bit_length, [lit_int(255i64)]), int(8i64), !T, !IO),
    evals("[LEXP.3.7.1] bit_length(-256) is 9 -- the bits of |x|",
        e_call(fn_bit_length, [lit_int(-256i64)]), int(9i64), !T, !IO),
    evals("[LEXP.3.7.1] bit_length(INT64_MIN) is 64",
        e_call(fn_bit_length, [lit_int(int64.min_int64)]), int(64i64), !T, !IO),
    evals("[LEXP.3.7.1] bit_length(INT64_MAX) is 63",
        e_call(fn_bit_length, [lit_int(int64.max_int64)]), int(63i64), !T, !IO),
    evals("[LEXP.3.7.1] bit_count(255) is 8",
        e_call(fn_bit_count, [lit_int(255i64)]), int(8i64), !T, !IO),
    evals("[LEXP.3.7.1] bit_count(-1) is 64 -- the two's-complement word",
        e_call(fn_bit_count, [lit_int(-1i64)]), int(64i64), !T, !IO),
    evals("[LEXP.3.7.1] bit_count(INT64_MIN) is 1",
        e_call(fn_bit_count, [lit_int(int64.min_int64)]), int(1i64), !T, !IO),
    check("[LNUL.5.1] a bit builtin on null is a TypeError",
        ( if eval(e_call(fn_bit_count, [lit_null]), ectx, ev_fault(rf_type_error))
          then yes else no ), !T, !IO),
    % A type mismatch, which `eval` classifies by provenance: untainted, the
    % compiler's type check should have made it impossible, so it is the
    % artefact lying (an EngineError), as `"1" == 1` is below.
    check("[LEXP.3.7.1] bit_length of a Float is a type mismatch",
        ( if eval(e_call(fn_bit_length, [lit_float(2.0)]), ectx,
                  ev_fault(rf_artefact_lied))
          then yes else no ), !T, !IO),

    % [LDET.3.6.1]: "no two operations fused into one", in this binary's own
    % C. GCC fuses `a * b + c` into one FMA when the target has one and
    % nothing says `-ffp-contract=off`. `A * A` is `1 + 2^-26 + 2^-54`, which
    % rounds to `1 + 2^-26`, so two roundings give exactly 0.0 and a fused
    % one gives 2^-54. The operands come from `det_to_float` so no compiler
    % folds them. It can only fail where FMA exists: on arm64, not amd64.
    check("[LDET.3.6.1] a * b + c rounds twice, never fused",
        ( if
            FmaA = string.det_to_float("1.000000007450580596923828125"),
            FmaC = string.det_to_float("-1.00000001490116119384765625"),
            FmaA * FmaA + FmaC = 0.0
          then yes else no ), !T, !IO),

    % [LDET.3.6.2]: `sqrt` of a negative is IEEE's NaN, not a trap.
    % [LEXP.4.2]'s slot check keeps it out of working memory.
    check("[LDET.3.6.2] sqrt(-4.0) is NaN",
        ( if eval(e_call(fn_sqrt, [lit_float(-4.0)]), ectx,
                ev_ok(float(SqrtNeg))),
             float.is_nan(SqrtNeg)
          then yes else no ), !T, !IO),
    check("[LCST.4.5.4] floor of an infinity traps, as Float :: Int does",
        ( if eval(e_call(fn_floor, [lit_float(float.infinity)]), ectx, Inf),
             Inf = ev_fault(rf_cast_non_finite(_))
          then yes else no ), !T, !IO),

    % [LEXP.3.2.1]: a rounding with no `Int` traps NOT_REPRESENTABLE, at the
    % bounds `Float :: Int` uses. The conformance vectors
    % `LEXP.3.2.1.*_range_*` hold libds to the same; these pin the evaluator.
    check("LEXP.3.2.1 floor(2^63) traps NOT_REPRESENTABLE",
        ( if eval(e_call(fn_floor, [lit_float(9223372036854775808.0)]), ectx,
                ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    check("LEXP.3.2.1 ceil(2^63) traps NOT_REPRESENTABLE",
        ( if eval(e_call(fn_ceil, [lit_float(9223372036854775808.0)]), ectx,
                ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    check("LEXP.3.2.1 round(2^63) traps NOT_REPRESENTABLE",
        ( if eval(e_call(fn_round, [lit_float(9223372036854775808.0)]), ectx,
                ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    check("LEXP.3.2.1 trunc of the first double below -2^63 traps",
        ( if eval(e_call(fn_trunc, [lit_float(-9223372036854777856.0)]), ectx,
                ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    evals("LEXP.3.2.1 floor(-2^63) is INT64_MIN",
        e_call(fn_floor, [lit_float(-9223372036854775808.0)]),
        int(int64.min_int64), !T, !IO),
    evals("LEXP.3.2.1 round of the last double below 2^63 converts",
        e_call(fn_round, [lit_float(9223372036854774784.0)]),
        int(9223372036854774784i64), !T, !IO),

    % [LEXP.7.3a]: `**` is `Int` only for a non-negative integer exponent.
    evals("[LEXP.7.3a] 5 ** 2 is the Int 25",
        e_call(fn_pow, [lit_int(5i64), lit_int(2i64)]), int(25i64), !T, !IO),
    evals("[LEXP.7.3a] 2 ** -3 is the Float 0.125",
        e_call(fn_pow, [lit_int(2i64), lit_int(-3i64)]), float(0.125), !T, !IO),
    evals("[LEXP.7.3a] (-2.0) ** 3 keeps the sign",
        e_call(fn_pow, [lit_float(-2.0), lit_int(3i64)]), float(-8.0), !T, !IO),
    check("[LEXP.7.3a] 0 ** -1 is +inf, not a trap ([LEXP.3.9.3])",
        ( if eval(e_call(fn_pow, [lit_int(0i64), lit_int(-1i64)]), ectx,
                ev_ok(float(PowZeroNeg))),
             float.is_inf(PowZeroNeg), PowZeroNeg > 0.0
          then yes else no ), !T, !IO),
    check("[LEXP.7.3a] (-8.0) ** 0.5 is NaN, not a trap",
        ( if eval(e_call(fn_pow, [lit_float(-8.0), lit_float(0.5)]), ectx,
                ev_ok(float(PowNegHalf))),
             float.is_nan(PowNegHalf)
          then yes else no ), !T, !IO),
    evals("[LEXP.3.9.2] 2.0 ** 0.5 is RN(sqrt 2), through CORE-MATH's pow",
        e_call(fn_pow, [lit_float(2.0), lit_float(0.5)]),
        float(1.4142135623730951), !T, !IO),

    % [LEXP.3.9.1] -- the fourteen, through `ds.core_math`, at points whose
    % correctly rounded value is known to the last bit, and the special
    % operands, which answer ±inf and NaN and do not fault. The same rows as
    % libds's test_transcendentals, so the two runtimes are held to one table.
    evals("[LEXP.3.9.1] exp(1.0) is RN(e)",
        e_call(fn_exp, [lit_float(1.0)]), float(2.718281828459045), !T, !IO),
    evals("[LEXP.3.9.1] exp(1) promotes the Int",
        e_call(fn_exp, [lit_int(1i64)]), float(2.718281828459045), !T, !IO),
    evals("[LEXP.3.9.1] ln(2.0) is RN(ln 2)",
        e_call(fn_ln, [lit_float(2.0)]), float(0.6931471805599453), !T, !IO),
    evals("[LEXP.3.9.1] log2(8.0) is 3",
        e_call(fn_log2, [lit_float(8.0)]), float(3.0), !T, !IO),
    evals("[LEXP.3.9.1] log10(1000.0) is 3",
        e_call(fn_log10, [lit_float(1000.0)]), float(3.0), !T, !IO),
    evals("[LEXP.3.9.1] sin(1.0) is RN(sin 1)",
        e_call(fn_sin, [lit_float(1.0)]), float(0.8414709848078965), !T, !IO),
    evals("[LEXP.3.9.1] cos(0.0) is 1",
        e_call(fn_cos, [lit_float(0.0)]), float(1.0), !T, !IO),
    evals("[LEXP.3.9.1] tan(0.0) is 0",
        e_call(fn_tan, [lit_float(0.0)]), float(0.0), !T, !IO),
    evals("[LEXP.3.9.1] asin(1.0) is RN(pi/2)",
        e_call(fn_asin, [lit_float(1.0)]), float(1.5707963267948966), !T, !IO),
    evals("[LEXP.3.9.1] acos(-1.0) is RN(pi)",
        e_call(fn_acos, [lit_float(-1.0)]), float(3.141592653589793), !T, !IO),
    evals("[LEXP.3.9.1] atan(1.0) is RN(pi/4)",
        e_call(fn_atan, [lit_float(1.0)]), float(0.7853981633974483), !T, !IO),
    evals("[LEXP.3.9.1] atan2(1.0, -1.0) is RN(3pi/4) -- y first",
        e_call(fn_atan2, [lit_float(1.0), lit_float(-1.0)]),
        float(2.356194490192345), !T, !IO),
    evals("[LEXP.3.9.1] sinh(0.0) is 0",
        e_call(fn_sinh, [lit_float(0.0)]), float(0.0), !T, !IO),
    evals("[LEXP.3.9.1] cosh(0.0) is 1",
        e_call(fn_cosh, [lit_float(0.0)]), float(1.0), !T, !IO),
    evals("[LEXP.3.9.1] tanh(0.0) is 0",
        e_call(fn_tanh, [lit_float(0.0)]), float(0.0), !T, !IO),
    check("[LEXP.3.9.3] ln(0.0) is -inf, not a fault",
        ( if eval(e_call(fn_ln, [lit_float(0.0)]), ectx,
                ev_ok(float(LnZero))),
             float.is_inf(LnZero), LnZero < 0.0
          then yes else no ), !T, !IO),
    check("[LEXP.3.9.3] asin(2.0) is NaN, not a fault",
        ( if eval(e_call(fn_asin, [lit_float(2.0)]), ectx,
                ev_ok(float(AsinTwo))),
             float.is_nan(AsinTwo)
          then yes else no ), !T, !IO),

    % [LEXP.7.15.1] -- a Float division by zero is IEEE's; only all-Int traps.
    check("[LEXP.7.15.1] 10.0 / 0.0 is +inf",
        ( if eval(e_binop(op_div, lit_float(10.0), lit_float(0.0)), ectx,
                ev_ok(float(DivFloatFloat))),
             float.is_inf(DivFloatFloat), DivFloatFloat > 0.0
          then yes else no ), !T, !IO),
    check("[LEXP.7.15.1] 10 / 0.0 is +inf -- the Float divisor decides",
        ( if eval(e_binop(op_div, lit_int(10i64), lit_float(0.0)), ectx,
                ev_ok(float(DivIntFloat))),
             float.is_inf(DivIntFloat), DivIntFloat > 0.0
          then yes else no ), !T, !IO),
    check("[LEXP.7.15.1] 0.0 / 0.0 is NaN",
        ( if eval(e_binop(op_div, lit_float(0.0), lit_float(0.0)), ectx,
                ev_ok(float(DivZeroZero))),
             float.is_nan(DivZeroZero)
          then yes else no ), !T, !IO),
    check("[LEXP.7.15.1] 10 / 0 still traps: both operands are Int",
        ( if eval(e_binop(op_div, lit_int(10i64), lit_int(0i64)), ectx,
                ev_fault(rf_div_zero))
          then yes else no ), !T, !IO),
    % [LDET.3.6.2]: negating 0.0 is -0.0, read as the sign of 1 / it.
    % Mercury's own unary `-` is `0.0 - X`, which gives +0.0.
    check("[LDET.3.6.2] -(0.0) is -0.0",
        ( if eval(e_unop(op_neg, lit_float(0.0)), ectx,
                ev_ok(float(NegZero))),
             NegZero = 0.0,
             float.is_inf(float.unchecked_quotient(1.0, NegZero)),
             float.unchecked_quotient(1.0, NegZero) < 0.0
          then yes else no ), !T, !IO),

    % A negative zero keeps its sign through `**` where IEEE's `pow` keeps it,
    % as libds's C `pow` answers. The first check is that the input is
    % negative.
    check("[LEXP.7.3a] the -0.0 these rows feed in is negative",
        ( if negative_zero(neg_zero) then yes else no ), !T, !IO),
    evals_zero("[LEXP.7.3a] (-0.0) ** 3.0 is -0.0",
        e_call(fn_pow, [lit_float(neg_zero), lit_float(3.0)]), yes, !T, !IO),
    evals_zero("[LEXP.7.3a] (-0.0) ** 3 is -0.0 -- an Int exponent promotes",
        e_call(fn_pow, [lit_float(neg_zero), lit_int(3i64)]), yes, !T, !IO),
    evals_zero("[LEXP.7.3a] (-0.0) ** 2.0 is +0.0",
        e_call(fn_pow, [lit_float(neg_zero), lit_float(2.0)]), no, !T, !IO),
    evals_zero("[LEXP.7.3a] (-0.0) ** 0.5 is +0.0 -- not an odd integer",
        e_call(fn_pow, [lit_float(neg_zero), lit_float(0.5)]), no, !T, !IO),
    evals_zero("[LEXP.7.3a] 0.0 ** 3.0 is +0.0",
        e_call(fn_pow, [lit_float(0.0), lit_float(3.0)]), no, !T, !IO),
    evals_zero("[LEXP.7.3a] (-1e-200) ** 3.0 underflows to -0.0",
        e_call(fn_pow, [lit_float(-1.0e-200), lit_float(3.0)]), yes, !T, !IO),

    % [LEXP.5] -- the corpus's 3-4-5 triangle, through every geometric shape.
    evals("[LEXP.5.3.1] euclidean over (0,0)-(3,4) is 5.0",
        e_call(fn_euclidean_2d, [lit_float(0.0), lit_float(0.0),
            lit_float(3.0), lit_float(4.0)]), float(5.0), !T, !IO),
    evals("[LEXP.5.3.1] manhattan over (0,0)-(3,4) is 7.0",
        e_call(fn_manhattan_2d, [lit_float(0.0), lit_float(0.0),
            lit_float(3.0), lit_float(4.0)]), float(7.0), !T, !IO),
    evals("[LEXP.5.3.1] chebyshev over (0,0)-(3,4) is 4.0",
        e_call(fn_chebyshev_2d, [lit_float(0.0), lit_float(0.0),
            lit_float(3.0), lit_float(4.0)]), float(4.0), !T, !IO),
    evals("[LEXP.5.3.1] euclidean 3D over (0,0,0)-(1,2,2) is 3.0",
        e_call(fn_euclidean_3d, [lit_int(0i64), lit_int(0i64), lit_int(0i64),
            lit_int(1i64), lit_int(2i64), lit_int(2i64)]), float(3.0), !T, !IO),
    evals("[LEXP.5.5] hypot(3, 4) is the Float 5.0",
        e_call(fn_hypotenuse_2d, [lit_int(3i64), lit_int(4i64)]), float(5.0),
        !T, !IO),

    % [LEXP.5.7.3]: cosine distance, not similarity. The rows are
    % LEXP.5.7.1_cosine_distance's, each exact under the composition: the
    % orthogonal pair is 1.0, the opposite pair 2.0 (where a similarity would
    % answer -1.0), and a vector against itself 0.0.
    evals("[LEXP.5.7.1] cosine (2,0) against (0,3) is 1.0",
        e_call(fn_cosine_2d, [lit_float(2.0), lit_float(0.0),
            lit_float(0.0), lit_float(3.0)]), float(1.0), !T, !IO),
    evals("[LEXP.5.7.1] cosine (2,0) against (-3,0) is 2.0, not -1.0",
        e_call(fn_cosine_2d, [lit_float(2.0), lit_float(0.0),
            lit_float(-3.0), lit_float(0.0)]), float(2.0), !T, !IO),
    evals("[LEXP.5.7.1] cosine 3D (2,3,6) against itself is 0.0",
        e_call(fn_cosine_3d, [lit_float(2.0), lit_float(3.0), lit_float(6.0),
            lit_float(2.0), lit_float(3.0), lit_float(6.0)]), float(0.0),
        !T, !IO),
    evals("[LEXP.7.17.1] cosine promotes Int operands",
        e_call(fn_cosine_2d, [lit_int(2i64), lit_int(0i64),
            lit_int(0i64), lit_int(3i64)]), float(1.0), !T, !IO),
    % A zero vector is `0.0 / 0.0`, NaN, not a trap and not a Mercury
    % exception ([LDET.3.6.2]); [LEXP.4.2] keeps it out of working memory.
    check("[LEXP.5.7.3] cosine with a zero vector is NaN",
        ( if eval(e_call(fn_cosine_2d, [lit_float(0.0), lit_float(0.0),
                    lit_float(1.0), lit_float(1.0)]), ectx,
                ev_ok(float(CosZero))),
             float.is_nan(CosZero)
          then yes else no ), !T, !IO),
    check("[LEXP.5.7.3] cosine 3D with both vectors zero is NaN",
        ( if eval(e_call(fn_cosine_3d, [lit_float(0.0), lit_float(0.0),
                    lit_float(0.0), lit_float(0.0), lit_float(0.0),
                    lit_float(0.0)]), ectx,
                ev_ok(float(CosZero3))),
             float.is_nan(CosZero3)
          then yes else no ), !T, !IO),

    % [LUNI.13.6] -- the six modes at the ties of LUNI.13.6_modes_at_ties, as
    % codes 0..5: half_even, half_up, half_down, ceiling, floor, truncate.
    evals("[LUNI.13.6] 2.5 half_even is 2",
        e_call(fn_currency_round, [lit_float(2.5), lit_int(0i64)]), int(2i64),
        !T, !IO),
    evals("[LUNI.13.6] 3.5 half_even is 4",
        e_call(fn_currency_round, [lit_float(3.5), lit_int(0i64)]), int(4i64),
        !T, !IO),
    evals("[LUNI.13.6] -2.5 half_up is -3, away from zero",
        e_call(fn_currency_round, [lit_float(-2.5), lit_int(1i64)]), int(-3i64),
        !T, !IO),
    evals("[LUNI.13.6] -2.5 half_down is -2, toward zero",
        e_call(fn_currency_round, [lit_float(-2.5), lit_int(2i64)]), int(-2i64),
        !T, !IO),
    evals("[LUNI.13.6] -2.5 ceiling is -2",
        e_call(fn_currency_round, [lit_float(-2.5), lit_int(3i64)]), int(-2i64),
        !T, !IO),
    evals("[LUNI.13.6] -2.5 floor is -3",
        e_call(fn_currency_round, [lit_float(-2.5), lit_int(4i64)]), int(-3i64),
        !T, !IO),
    evals("[LUNI.13.6] -2.5 truncate is -2",
        e_call(fn_currency_round, [lit_float(-2.5), lit_int(5i64)]), int(-2i64),
        !T, !IO),
    evals("[LUNI.13.5] an exact Ratio 7/2 half_even is 4",
        e_call(fn_currency_round, [e_lit(ratio(7i64, 2i64)), lit_int(0i64)]), int(4i64),
        !T, !IO),
    evals("[LUNI.13.5] round_to 250 by 100 half_even is 200, in base units",
        e_call(fn_currency_round_to, [lit_int(250i64), lit_int(100i64),
            lit_int(0i64)]), int(200i64), !T, !IO),
    evals("[LUNI.13.5] round_to -250 by 100 floor is -300",
        e_call(fn_currency_round_to, [lit_int(-250i64), lit_int(100i64),
            lit_int(4i64)]), int(-300i64), !T, !IO),
    check("[LUNI.13.10] a rounding past Int64 refuses rather than wraps",
        ( if eval(e_call(fn_currency_round_to, [lit_int(int64.max_int64),
                lit_int(10i64), lit_int(3i64)]), ectx, ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    check("[LUNI.13.10] an infinite Float has no exact amount",
        ( if eval(e_call(fn_currency_round, [lit_float(float.infinity),
                lit_int(0i64)]), ectx, ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    % [RLOW.7.3.9]: `FN_INT_DIV_EXACT`, a Duration on a `minute` kwarg by the
    % unit's 60e9 ns, as libds's `builtin_int_div_exact`, case for case.
    evals("[RLOW.7.3.9] 120 s in minutes is 2",
        e_call(fn_int_div_exact, [lit_int(120000000000i64),
            lit_int(60000000000i64)]), int(2i64), !T, !IO),
    evals("[RLOW.7.3.9] -120 s in minutes is -2",
        e_call(fn_int_div_exact, [lit_int(-120000000000i64),
            lit_int(60000000000i64)]), int(-2i64), !T, !IO),
    check("[RLOW.7.3.9] 90 s in minutes is NOT_REPRESENTABLE, never truncated",
        ( if eval(e_call(fn_int_div_exact, [lit_int(90000000000i64),
                lit_int(60000000000i64)]), ectx, ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    check("[RLOW.7.3.9] a zero divisor is DIVIDE_BY_ZERO",
        ( if eval(e_call(fn_int_div_exact, [lit_int(60000000000i64),
                lit_int(0i64)]), ectx, ev_fault(rf_div_zero))
          then yes else no ), !T, !IO),
    check("[RLOW.7.3.9] min_int64 / -1 has no Int quotient: NOT_REPRESENTABLE",
        ( if eval(e_call(fn_int_div_exact, [lit_int(int64.min_int64),
                lit_int(-1i64)]), ectx, ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    evals("[RLOW.7.3.9] a null numerator is null",
        e_call(fn_int_div_exact, [e_lit(null), lit_int(60000000000i64)]),
        null, !T, !IO),
    evals("[RLOW.7.3.9] a null divisor is null",
        e_call(fn_int_div_exact, [lit_int(60000000000i64), e_lit(null)]),
        null, !T, !IO),
    % [RLOW.7.3.9]: `FN_INT_MUL_ADD_CHECKED(x, m, a)` at the four edges of the
    % range, the product and then the sum, both signs, as libds's
    % `test_int_mul_add_checked`, case for case.
    evals("[RLOW.7.3.9] 8 · (2^60 - 1) is 2^63 - 8, at the top",
        e_call(fn_int_mul_add_checked, [lit_int(1152921504606846975i64),
            lit_int(8i64), lit_int(0i64)]), int(9223372036854775800i64),
        !T, !IO),
    check("[RLOW.7.3.9] 8 · 2^60 is past the top: NOT_REPRESENTABLE, never wrapped",
        ( if eval(e_call(fn_int_mul_add_checked, [
                lit_int(1152921504606846976i64), lit_int(8i64), lit_int(0i64)]),
                ectx, ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    evals("[RLOW.7.3.9] 8 · -2^60 is -2^63, at the bottom",
        e_call(fn_int_mul_add_checked, [lit_int(-1152921504606846976i64),
            lit_int(8i64), lit_int(0i64)]), int(int64.min_int64), !T, !IO),
    check("[RLOW.7.3.9] 8 · (-2^60 - 1) is past the bottom: NOT_REPRESENTABLE",
        ( if eval(e_call(fn_int_mul_add_checked, [
                lit_int(-1152921504606846977i64), lit_int(8i64), lit_int(0i64)]),
                ectx, ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    evals("[RLOW.7.3.9] (2^63 - 2) + 1 is 2^63 - 1, the sum at the top",
        e_call(fn_int_mul_add_checked, [lit_int(int64.max_int64 - 1i64),
            lit_int(1i64), lit_int(1i64)]), int(int64.max_int64), !T, !IO),
    check("[RLOW.7.3.9] (2^63 - 2) + 2 is past the top: NOT_REPRESENTABLE",
        ( if eval(e_call(fn_int_mul_add_checked, [
                lit_int(int64.max_int64 - 1i64), lit_int(1i64), lit_int(2i64)]),
                ectx, ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    evals("[RLOW.7.3.9] (-2^63 + 1) - 1 is -2^63, the sum at the bottom",
        e_call(fn_int_mul_add_checked, [lit_int(int64.min_int64 + 1i64),
            lit_int(1i64), lit_int(-1i64)]), int(int64.min_int64), !T, !IO),
    check("[RLOW.7.3.9] (-2^63 + 1) - 2 is past the bottom: NOT_REPRESENTABLE",
        ( if eval(e_call(fn_int_mul_add_checked, [
                lit_int(int64.min_int64 + 1i64), lit_int(1i64), lit_int(-2i64)]),
                ectx, ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    check("[RLOW.7.3.9] 3 · 2^62 - 2^63 would be 2^62, but the product passes " ++
            "the range first: NOT_REPRESENTABLE",
        ( if eval(e_call(fn_int_mul_add_checked, [
                lit_int(4611686018427387904i64), lit_int(3i64),
                lit_int(int64.min_int64)]),
                ectx, ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    evals("[RLOW.7.3.9] a null x is null",
        e_call(fn_int_mul_add_checked, [e_lit(null), lit_int(8i64),
            lit_int(0i64)]), null, !T, !IO),
    % [LTIM.7.1]: `t.floor(d)` at the offset the receiver carries, as libds's
    % `test_ltim_7_1__floor_time`, case for case. The zoned
    % receivers are the half the conformance harness cannot reach, which has
    % no resolver. 2024-03-31T10:20:30.5Z floors to Tokyo's (+9 h) midnight,
    % 2024-03-30T15:00:00Z, and to Los Angeles's (-8 h), 2024-03-31T08:00:00Z.
    evals("[LTIM.7.1] an Int, a Time slot read, floors in UTC and stays an Int",
        e_call(fn_floor_time, [lit_int(1711880430500000000i64),
            lit_int(3600000000000i64)]), int(1711879200000000000i64), !T, !IO),
    evals("[LTIM.7.1] -1 ns floors to 1969-12-31T23:00:00Z, toward -inf",
        e_call(fn_floor_time, [lit_int(-1i64), lit_int(3600000000000i64)]),
        int(-3600000000000i64), !T, !IO),
    evals("[LTIM.7.1] a UTC Time floors to the UTC midnight and stays a Time",
        e_call(fn_floor_time, [
            e_lit(time(ds_time(1711880430500000000i64, 0i64))),
            lit_int(86400000000000i64)]),
        time(ds_time(1711843200000000000i64, 0i64)), !T, !IO),
    evals("[LTIM.7.2] a Tokyo Time floors to Tokyo's midnight, offset kept",
        e_call(fn_floor_time, [
            e_lit(time(ds_time(1711880430500000000i64, 32400000000000i64))),
            lit_int(86400000000000i64)]),
        time(ds_time(1711810800000000000i64, 32400000000000i64)), !T, !IO),
    evals("[LTIM.7.2] a Los Angeles Time floors to its own midnight",
        e_call(fn_floor_time, [
            e_lit(time(ds_time(1711880430500000000i64, -28800000000000i64))),
            lit_int(86400000000000i64)]),
        time(ds_time(1711872000000000000i64, -28800000000000i64)), !T, !IO),
    check("[LTIM.7.1] floor to 0_s is DIVIDE_BY_ZERO",
        ( if eval(e_call(fn_floor_time, [lit_int(1i64), lit_int(0i64)]), ectx,
                ev_fault(rf_div_zero))
          then yes else no ), !T, !IO),
    check("[LTIM.1.3.1] a negative Duration floors as 0_s does",
        ( if eval(e_call(fn_floor_time, [lit_int(1i64),
                lit_int(-3600000000000i64)]), ectx, ev_fault(rf_div_zero))
          then yes else no ), !T, !IO),
    check("[LTIM.1.1.5] a floor before 1677 is NOT_REPRESENTABLE, never a wrap",
        ( if eval(e_call(fn_floor_time, [lit_int(int64.min_int64 + 1i64),
                lit_int(3600000000000i64)]), ectx,
                ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    % [LUNI.4.6.1] -- no live rate converts 1:1, an exact Ratio. The
    % greatest-`asof` choice needs working memory and is the four
    % `LUNI.4.6.*` behavioural fixtures' to drive.
    evals("[LUNI.4.6.1] a selector matching nothing converts at 1:1",
        e_call(fn_currency_convert, [lit_int(1234i64), e_lit(text("USD_to_EUR")),
            e_lit(text("FxRate")), e_lit(text("rate_num")),
            e_lit(text("rate_den")), e_lit(text("base_code")),
            e_lit(text("USD"))]),
        ratio(1234i64, 1i64), !T, !IO),

    % [LTIM.8.2.1] -- the fixed identifier set.
    evals("[LTIM.8.1.2] t.to_string() at the epoch is iso8601 with Z",
        e_call(fn_to_string, [e_lit(time(ds_time(0i64, 0i64)))]),
        text("1970-01-01T00:00:00Z"), !T, !IO),
    evals("[LTIM.8.2.1] iso8601 keeps the offset and the local wall clock",
        e_call(fn_to_string, [e_lit(time(ds_time(1705334400000000000i64,
            -28800000000000i64)))]),
        text("2024-01-15T08:00:00-08:00"), !T, !IO),
    evals("[LTIM.8.2.1] a sub-second part is trimmed, not padded",
        e_call(fn_to_string, [e_lit(time(ds_time(1500000000i64, 0i64)))]),
        text("1970-01-01T00:00:01.5Z"), !T, !IO),
    evals("[LTIM.8.2.1a] epoch_micros floors: -1500 ns is -2",
        e_call(fn_to_string, [e_lit(time(ds_time(-1500i64, 0i64))),
            e_lit(text("epoch_micros"))]), text("-2"), !T, !IO),
    evals("[LTIM.8.2.2] the identifier is case-insensitive",
        e_call(fn_to_string, [e_lit(time(ds_time(1705334400000000000i64, 0i64))),
            e_lit(text("EPOCH_SECONDS"))]), text("1705334400"), !T, !IO),
    evals("[LCST.4.5.6] Float::String is the canonical text form",
        e_call(fn_float_to_string, [lit_float(42.0)]), text("42.0"),
        !T, !IO),
    % The exact decimal, at the value whose magnitude int64 cannot hold.
    evals("[LCST.4.5.6] Int::String is the exact decimal",
        e_call(fn_int_to_string, [lit_int(42i64)]), text("42"), !T, !IO),
    evals("[LCST.4.5.6] Int::String puts a `-` before a negative value",
        e_call(fn_int_to_string, [lit_int(-7i64)]), text("-7"), !T, !IO),
    evals("[LCST.4.5.6] Int::String renders INT64_MIN whole",
        e_call(fn_int_to_string, [lit_int(int64.min_int64)]),
        text("-9223372036854775808"), !T, !IO),
    evals("[LCST.4.5.6] Bool::String renders true as \"true\"",
        e_call(fn_bool_to_string, [e_lit(bool(yes))]), text("true"),
        !T, !IO),
    evals("[LCST.4.5.6] Bool::String renders false as \"false\"",
        e_call(fn_bool_to_string, [e_lit(bool(no))]), text("false"),
        !T, !IO),
    check("[LDET.3.2.7] +/-Inf render as `inf` / `-inf` on the text plane",
        ( if
            bare_float(float.infinity) = "inf",
            bare_float(-float.infinity) = "-inf",
            bare_float(42.0) = "42.0"
          then yes else no ), !T, !IO),

    % [LSTR.2.1]: codepoints, as libds's `str_codepoints` counts them.
    evals("[LSTR.2.1] len(\"café\") is 4 codepoints, not 5 bytes",
        e_call(fn_str_length, [e_lit(text("café"))]), int(4i64), !T, !IO),

    % [LEXP.6.1], [LNUL.8.4]: `has` tells a present null from no path, and
    % `len` answers the array's length.
    Doc = json(j_object(object([
        "nulled" - j_null,
        "arr" - j_array([j_int(1i64), j_int(2i64)]),
        "obj" - j_object(object(["k" - j_int(1i64)]))]))),
    evals("[LNUL.8.4] has() is true for a path resolving to JSON null",
        e_call(fn_json_has, [e_lit(Doc), e_lit(text("nulled"))]), bool(yes),
        !T, !IO),
    evals("[LNUL.8.4] has() is false for a path that resolves to nothing",
        e_call(fn_json_has, [e_lit(Doc), e_lit(text("missing"))]), bool(no),
        !T, !IO),
    evals("[LEXP.6.1] len() of a Json array path is its length",
        e_call(fn_json_len, [e_lit(Doc), e_lit(text("arr"))]), int(2i64),
        !T, !IO),
    % An unresolved path is not an array either. It reads as `null`
    % ([LNUL.8.4]), and `len` of anything but an array is [LEXP.6.2]'s
    % TypeError; `has` is the guard. formal/idris/Rete/Eval.idr's
    % `lexp_6_2__len_is_an_arrays_alone` traps on `null`.
    check("[LEXP.6.2] len() of an unresolved path is a TypeError, as its "
            ++ "tainted node",
        ( if eval(e_tainted(e_call(fn_json_len,
                [e_lit(Doc), e_lit(text("missing"))])),
                ectx, TaintedMissingLen),
             TaintedMissingLen = ev_fault(rf_type_error)
          then yes else no ), !T, !IO),
    check("[LEXP.6.2] len() of a Json object is a TypeError, as its tainted node",
        ( if eval(e_tainted(e_call(fn_json_len,
                [e_lit(Doc), e_lit(text("obj"))])),
                ectx, ObjLen),
             ObjLen = ev_fault(rf_type_error)
          then yes else no ), !T, !IO).

:- pred test_one_absent(tally::in, tally::out, io::di, io::uo) is det.

test_one_absent(!T, !IO) :-
    % One absent value. A Json leaf of the wrong kind is a fault at the
    % operation, not a value propagating through the clause; an unresolved
    % path yields `null`, so `??` rescues every absence there is.
    evals("`null ?? 0` is 0",
        e_coalesce(lit_null, lit_int(0i64)), int(0i64), !T, !IO),
    check("a fault is not rescued by `??` -- it is not an absence",
        ( if eval(e_coalesce(e_binop(op_add, lit_bool(yes), lit_int(1i64)),
                lit_int(0i64)), ectx, ev_fault(_))
          then yes else no ), !T, !IO),

    % A JSON path answers a value or `null`, never a marker ([LNUL.8.4],
    % [IRET.9.6]). A string leaf is a computed string, compared by content.
    Doc = json(j_object(object(["s" - j_string("x"),
        "a" - j_array([j_int(1i64), j_int(2i64)])]))),
    check("a Json string leaf reads as a computed String",
        ( if eval(e_call(fn_json_path, [e_lit(Doc), e_lit(text("s"))]), ectx,
                ev_ok(text("x")))
          then yes else no ), !T, !IO),
    check("an unresolved Json path reads as null, not a fault",
        ( if eval(e_call(fn_json_path, [e_lit(Doc), e_lit(text("nope"))]),
                ectx, ev_ok(null))
          then yes else no ), !T, !IO),
    check("a Json array leaf keeps its elements",
        ( if eval(e_call(fn_json_path, [e_lit(Doc), e_lit(text("a"))]), ectx,
                ev_ok(json(j_array([j_int(1i64), j_int(2i64)]))))
          then yes else no ), !T, !IO),
    check("a path that is not a String is a type mismatch, not an absence",
        ( if eval(e_call(fn_json_path, [e_lit(Doc), lit_int(1i64)]), ectx,
                ev_fault(_))
          then yes else no ), !T, !IO),
    % A `null` root, a `Json?` slot holding none, has no document: the read is
    % `null`, through the call and the path node alike, and a path that is not
    % a String is still the mismatch. libds's test_json_path_null_root checks
    % the same answers.
    check("a Json path over a null root reads as null, not a fault",
        ( if eval(e_call(fn_json_path, [lit_null, e_lit(text("c"))]), ectx,
                ev_ok(null))
          then yes else no ), !T, !IO),
    check("a Json path node over a null root reads as null, not a fault",
        ( if eval(e_json_path_expr(lit_null, e_lit(text("c"))), ectx,
                ev_ok(null))
          then yes else no ), !T, !IO),
    check("a path that is not a String over a null root is still a mismatch",
        ( if eval(e_call(fn_json_path, [lit_null, lit_int(1i64)]), ectx,
                ev_fault(_))
          then yes else no ), !T, !IO),

    % JSON text in a String root is parsed and walked, as libds's
    % `json_root_of_text` does. A text that does not parse is the
    % node's type mismatch; one over a limit of [LGRA.5.8.6] is
    % NOT_REPRESENTABLE, never a truncation.
    check("a Json path over Json text walks the parsed document",
        ( if eval(e_call(fn_json_path, [e_lit(text("{\"a\": 42}")),
                e_lit(text("a"))]), ectx, ev_ok(int(42i64)))
          then yes else no ), !T, !IO),
    check("has() over Json text sees a present null",
        ( if eval(e_call(fn_json_has, [e_lit(text("{\"a\": null}")),
                e_lit(text("a"))]), ectx, ev_ok(bool(yes)))
          then yes else no ), !T, !IO),
    check("len() over Json text counts the array",
        ( if eval(e_call(fn_json_len, [e_lit(text("{\"xs\": [1, 2, 3]}")),
                e_lit(text("xs"))]), ectx, ev_ok(int(3i64)))
          then yes else no ), !T, !IO),
    check("Json text that does not parse is a TypeError, as its tainted node",
        ( if eval(e_tainted(e_call(fn_json_path, [e_lit(text("{\"a\":")),
                e_lit(text("a"))])), ectx, ev_fault(rf_type_error))
          then yes else no ), !T, !IO),
    check("Json text over the text limit is NOT_REPRESENTABLE",
        ( if eval(e_tainted(e_call(fn_json_path,
                [e_lit(text(string.duplicate_char(' ',
                    ds.json.max_text_bytes + 1))),
                 e_lit(text("a"))])), ectx, ev_fault(rf_not_representable))
          then yes else no ), !T, !IO),
    check("a computed String compares by content",
        ( if eval(e_binop(op_eq, e_lit(text("x")), e_lit(text("x"))), ectx,
                ev_ok(bool(yes)))
          then yes else no ), !T, !IO),

    % An interpolation, evaluated: the primitives in order, a value's fault
    % propagating, and a kind its type does not take raised as a type error.
    check("`{x:08b}` zero-pads the bits to the width",
        ( if eval(e_interp([fp_value(value_prim(lit_int(5i64), align_default,
                no, yes, 8u32, no, ft_b))]), ectx, ev_ok(text("00000101")))
          then yes else no ), !T, !IO),
    check("a zero-padded negative keeps its sign leading",
        ( if eval(e_interp([fp_value(value_prim(lit_int(-3i64), align_default,
                no, yes, 5u32, no, ft_b))]), ectx, ev_ok(text("-0011")))
          then yes else no ), !T, !IO),
    check("`{x:%Y-%m-%d}` renders the instant's own date",
        ( if eval(e_interp([fp_time(lit_int(0i64), [ti_field(tf_year),
                ti_text("-"), ti_field(tf_month), ti_text("-"),
                ti_field(tf_day)])]), ectx, ev_ok(text("1970-01-01")))
          then yes else no ), !T, !IO),
    check("text and values render in order",
        ( if eval(e_interp([fp_text("n="), fp_value(value_prim(lit_int(7i64),
                align_default, no, no, 0u32, no, ft_canonical)),
                fp_text("!")]), ectx, ev_ok(text("n=7!")))
          then yes else no ), !T, !IO),
    check("a null renders as nothing, unpadded",
        ( if eval(e_interp([fp_text("["), fp_value(value_prim(e_lit(null),
                align_default, no, no, 6u32, no, ft_d)), fp_text("]")]), ectx,
                ev_ok(text("[]")))
          then yes else no ), !T, !IO),
    check("a kind the type does not take is a type mismatch",
        ( if eval(e_interp([fp_value(value_prim(lit_bool(yes), align_default,
                no, no, 0u32, no, ft_d))]), ectx, ev_fault(F_kind)),
             F_kind \= rf_unimplemented
          then yes else no ), !T, !IO),
    check("an empty interpolation is the empty string",
        ( if eval(e_interp([]), ectx, ev_ok(text(""))) then yes else no ),
        !T, !IO),

    % A computed string compares by content, against an interned one as well as
    % another computed one. `text("ab")` has no ref; `content_of` is what
    % makes the two forms one value to `==`.
    evals("two computed strings compare by content",
        e_binop(op_eq, e_lit(text("ab")), e_lit(text("ab"))), bool(yes),
        !T, !IO),
    evals("computed strings order by content, as libds's memcmp",
        e_binop(op_lt, e_lit(text("ab")), e_lit(text("b"))), bool(yes),
        !T, !IO),
    check("a String compared with an Int is a type mismatch, not false",
        ( if eval(e_binop(op_eq, e_lit(text("1")), lit_int(1i64)), ectx,
                ev_fault(rf_artefact_lied))
          then yes else no ), !T, !IO).

:- pred test_null_test(tally::in, tally::out, io::di, io::uo) is det.

test_null_test(!T, !IO) :-
    % `EQ`/`NE` against a null literal propagates per [LNUL.4.1], like any
    % other comparison. Pinned at the evaluator: `== null` is a compile error
    % ([LNUL.4.4]), so no loadable artefact holds the node. libds pins the
    % same four in `test_rete_expr_eval`.
    evals("`null == null` is NULL -- propagation",
        eq_null(lit_null), null, !T, !IO),
    evals("`5 == null` is NULL",
        eq_null(lit_int(5i64)), null, !T, !IO),
    evals("`5 != null` is NULL",
        e_binop(op_ne, lit_int(5i64), lit_null), null, !T, !IO),

    % `formal/k/dsexpr.k` has `rule _:Val == null => null`, as the evaluator
    % does.
    check("the model's `x == null => null` is what the evaluator does",
        ( if eval(eq_null(lit_int(5i64)), ectx, ev_ok(null)) then yes else no ),
        !T, !IO),

    % A computed null propagates as the literal does.
    evals("`5 == (null + 1)` is NULL -- a computed null still propagates",
        e_binop(op_eq, lit_int(5i64),
            e_binop(op_add, lit_null, lit_int(1i64))),
        null, !T, !IO),
    true.

:- pred test_is_test(tally::in, tally::out, io::di, io::uo) is det.

test_is_test(!T, !IO) :-
    % [LNUL.4.9], row for row. The same rows libds's `test_is_test_total` pins:
    % two tables are only parity when both are asked the same questions.

    % A CONSTANT subject tests tag AND value.
    evals("`null is null`", is_t(lit_null, is_null), bool(yes), !T, !IO),
    evals("`true is true`", is_t(lit_bool(yes), is_true), bool(yes), !T, !IO),
    evals("`false is true` is FALSE",
        is_t(lit_bool(no), is_true), bool(no), !T, !IO),
    evals("`false is false`", is_t(lit_bool(no), is_false), bool(yes), !T, !IO),

    % A TAG NAME tests the tag ALONE, so `is Bool` holds of `false`.
    evals("`false is Bool`", is_t(lit_bool(no), is_bool), bool(yes), !T, !IO),
    evals("`5 is Int`", is_t(lit_int(5i64), is_int), bool(yes), !T, !IO),
    evals("`5 is Float` is FALSE -- a tag test does not promote",
        is_t(lit_int(5i64), is_float), bool(no), !T, !IO),
    evals("`1.5 is Float`", is_t(lit_float(1.5), is_float), bool(yes), !T, !IO),

    % `is Float` holds of inf, -inf and NaN alike -- the tag, not the value.
    evals("`inf is Float`",
        is_t(lit_float(inf_f), is_float), bool(yes), !T, !IO),
    evals("`-inf is Float`",
        is_t(lit_float(neg_inf_f), is_float), bool(yes), !T, !IO),
    evals("`NaN is Float`",
        is_t(lit_float(nan_f), is_float), bool(yes), !T, !IO),

    % ...while the constants separate them -- including NaN, which `==` cannot
    % express at all, since `NaN == NaN` is false.
    evals("`inf is inf`", is_t(lit_float(inf_f), is_inf), bool(yes), !T, !IO),
    evals("`-inf is inf` is FALSE -- the sign is part of the constant",
        is_t(lit_float(neg_inf_f), is_inf), bool(no), !T, !IO),
    evals("`-inf is -inf`",
        is_t(lit_float(neg_inf_f), is_neg_inf), bool(yes), !T, !IO),
    evals("`NaN is NaN` is TRUE, where `NaN == NaN` is false",
        is_t(lit_float(nan_f), is_nan), bool(yes), !T, !IO),
    evals("`1.5 is NaN` is false",
        is_t(lit_float(1.5), is_nan), bool(no), !T, !IO),
    evals("`inf is NaN` is false",
        is_t(lit_float(inf_f), is_nan), bool(no), !T, !IO),

    % A null operand answers FALSE to every non-null subject -- never null and
    % never a fault. This is the totality the model's stricter dispositions
    % rest on.
    evals("`null is Int` is FALSE, not null",
        is_t(lit_null, is_int), bool(no), !T, !IO),
    evals("`null is true` is false", is_t(lit_null, is_true), bool(no), !T, !IO),
    evals("`null is NaN` is false", is_t(lit_null, is_nan), bool(no), !T, !IO),

    % `is not` inverts AFTER the test. ONE operator, never `not (is)`.
    evals("`null is not null` is false",
        is_not_t(lit_null, is_null), bool(no), !T, !IO),
    evals("`5 is not null`", is_not_t(lit_int(5i64), is_null), bool(yes), !T, !IO),
    evals("`null is not Int` is TRUE",
        is_not_t(lit_null, is_int), bool(yes), !T, !IO),
    evals("`true is not Bool` is false",
        is_not_t(lit_bool(yes), is_bool), bool(no), !T, !IO),

    % The remaining tag names, each also against a value of another tag.
    evals("`\"x\" is String`",
        is_t(lit_str, is_string), bool(yes), !T, !IO),
    evals("`\"x\" is Int` is false", is_t(lit_str, is_int), bool(no), !T, !IO),
    evals("`<bytes> is Bytes`", is_t(lit_bytes, is_bytes), bool(yes), !T, !IO),
    evals("`<bytes> is String` is FALSE -- Bytes is not a String variant",
        is_t(lit_bytes, is_string), bool(no), !T, !IO),
    evals("`<json> is Json`",
        is_t(e_lit(json(j_string("x"))), is_json), bool(yes), !T, !IO),
    % A Json value carrying a string is Json and not String: `is` reads the tag
    % and extracts nothing.
    evals("`<json holding a string> is String` is false",
        is_t(e_lit(json(j_string("x"))), is_string), bool(no), !T, !IO),

    % [LNUL.4.9]: a Duration answers `is Int`, the nanosecond count that
    % carries it.
    evals("`<duration> is Int` is TRUE, the count that carries it",
        is_t(lit_duration, is_int), bool(yes), !T, !IO),
    evals("`<duration> is Float` is false",
        is_t(lit_duration, is_float), bool(no), !T, !IO),

    % The two value arms with no author-facing subject at all. Checked against
    % all twelve rather than a chosen few, because "no subject matches" is the
    % whole claim.
    no_subject_matches("a Ratio matches no subject", ratio(1i64, 2i64), !T, !IO),
    no_subject_matches("a fact-ref matches no subject",
        fact_ref(make_fact_id(7u64)), !T, !IO),

    % A Time is not one of them ([LNUL.4.9]): a tag names a representation,
    % not a declared type, and the answer is a function of the value alone,
    % so a Time `now()` wrote and an Int the integrator asserted answer alike.
    % libds's `DS_RETE_IS_INT` carries the same pair.
    evals("`<time> is Int` -- the representation, not the type",
        is_t(e_lit(time(ds_time(0i64, 0i64))), is_int), bool(yes), !T, !IO),
    evals("`<time> is Float` is false",
        is_t(e_lit(time(ds_time(0i64, 0i64))), is_float), bool(no), !T, !IO),
    evals("`<time> is null` is false",
        is_t(e_lit(time(ds_time(0i64, 0i64))), is_null), bool(no), !T, !IO),

    % A computed string is a String to the tag test: `text` and `str` are two
    % representations of one tag.
    evals("a computed string `is String`",
        is_t(e_lit(text("x")), is_string), bool(yes), !T, !IO),

    % A fault in the operand still propagates: it is the operand's fault, not
    % this node's.
    check("a fault in the operand propagates through `is`",
        ( if eval(is_t(e_call(fn_float_to_int, [lit_float(inf_f)]), is_null),
                ectx, ev_fault(_))
          then yes else no ), !T, !IO),

    test_is_test_total(!T, !IO).

    % Totality, exhaustively: every arm of `ds_value` against every subject,
    % positive and negated, answers a `bool`, never `null` or a fault, with
    % the negated form the exact complement. `is_hit` is `det` over the whole
    % of `ds_value`; this measures that the arm in `eval` keeps that.
    %
:- pred test_is_test_total(tally::in, tally::out, io::di, io::uo) is det.

test_is_test_total(!T, !IO) :-
    Pairs = list.condense(list.map(
        (func(V) = list.map((func(S) = V - S), all_subjects)),
        every_value_arm)),
    check("TOTAL: every subject x every value arm answers a bool, and "
            ++ "`is not` is exactly its complement",
        ( if
            list.all_true(
                (pred(P::in) is semidet :-
                    P = V0 - S0,
                    eval(e_is_test(e_lit(V0), S0, no), ectx, ev_ok(bool(B))),
                    eval(e_is_test(e_lit(V0), S0, yes), ectx,
                        ev_ok(bool(not B)))),
                Pairs)
        then yes else no ), !T, !IO).

    % Every subject answers `false` for this value.
    %
:- pred no_subject_matches(string::in, ds_value::in,
              tally::in, tally::out, io::di, io::uo) is det.

no_subject_matches(Name, V, !T, !IO) :-
    check(Name,
        ( if
            list.all_true(
                (pred(S::in) is semidet :-
                    eval(e_is_test(e_lit(V), S, no), ectx, ev_ok(bool(no)))),
                all_subjects)
        then yes else no ), !T, !IO).

    % The closed subject set of [LNUL.4.9], in wire order.
:- func all_subjects = list(is_subject).

all_subjects = [is_null, is_true, is_false, is_inf, is_neg_inf, is_nan,
    is_int, is_float, is_bool, is_string, is_bytes, is_json].

    % One representative of every arm of `ds_value`, plus the three floats the
    % constants separate.
:- func every_value_arm = list(ds_value).

every_value_arm = [int(1i64), float(1.5), float(inf_f), float(neg_inf_f),
    float(nan_f), str(make_intern_ref(1u32)), bool(yes), bool(no),
    bytes(from_bytes([1, 2, 3])), json(j_null), json(j_string("x")),
    fact_ref(make_fact_id(7u64)), duration(duration_from_ns(5u64)),
    time(ds_time(0i64, 0i64)), ratio(1i64, 2i64), null, text("x")].

:- func is_t(expr, is_subject) = expr.
:- func is_not_t(expr, is_subject) = expr.

is_t(E, S) = e_is_test(E, S, no).
is_not_t(E, S) = e_is_test(E, S, yes).

:- func lit_str = expr.
:- func lit_bytes = expr.
:- func lit_duration = expr.

lit_str = e_lit(str(make_intern_ref(1u32))).
lit_bytes = e_lit(bytes(from_bytes([1, 2, 3]))).
lit_duration = e_lit(duration(duration_from_ns(5u64))).

    % No float literal spells these and there is no library constant to borrow,
    % so they are built: overflow for the infinities, `inf - inf` for the NaN.
    % `/` cannot be used: an all-Int zero divisor is a hard fault.
:- func inf_f = float.
:- func neg_inf_f = float.
:- func nan_f = float.

inf_f = 1.0e308 * 10.0.
neg_inf_f = 0.0 - inf_f.
nan_f = inf_f - inf_f.

:- pred test_hard_faults(tally::in, tally::out, io::di, io::uo) is det.

test_hard_faults(!T, !IO) :-
    % A hard fault is not a value: it abandons evaluation rather than
    % propagating, and `??` cannot rescue it [LERR.1.4.8].
    check("integer division by zero is a hard FAULT, not a value",
        ( if eval(e_binop(op_floordiv, lit_int(1i64), lit_int(0i64)), ectx,
                ev_fault(rf_div_zero))
          then yes else no ), !T, !IO),
    % [LEXP.7.5]: "`-7 // 2 == -4` (not `-3`)". Mercury's `//` truncates, so
    % a negative dividend is the case that tells floor from truncation.
    evals("[LEXP.7.5] `-7 // 2` floors to -4",
        e_binop(op_floordiv, lit_int(-7i64), lit_int(2i64)), int(-4i64), !T, !IO),
    check("and modulo by zero its own fault",
        ( if eval(e_binop(op_rem, lit_int(1i64), lit_int(0i64)), ectx,
                ev_fault(rf_mod_zero))
          then yes else no ), !T, !IO),
    check("a fault is not rescued by `??` -- it abandons the whole expression",
        ( if eval(e_coalesce(e_binop(op_rem, lit_int(1i64), lit_int(0i64)),
                lit_int(0i64)), ectx, ev_fault(_))
          then yes else no ), !T, !IO),

    % `LNUL.11.1`'s per-verb table covers arguments that evaluate absent; a
    % trap abandons the activation instead [LERR.1.4.9], as
    % `emit Foo value: (a / b)` does when `b` is zero at runtime.
    check("`/` by zero is a fault too",
        ( if eval(e_binop(op_div, lit_int(1i64), lit_int(0i64)), ectx, ev_fault(_))
          then yes else no ), !T, !IO),

    % `dsexpr.k` states `false and _` over an unevaluated right operand, so a
    % hard fault in the dead branch never occurs.
    check("but a fault in a short-circuited branch never happens",
        ( if eval(e_binop(op_and, lit_bool(no),
                e_binop(op_rem, lit_int(1i64), lit_int(0i64))), ectx,
                ev_ok(bool(no)))
          then yes else no ), !T, !IO),

    % [LNUL.4.2]: `and` / `or` absorb a trap. A deciding operand decides
    % wherever it stands; a trap stands only if none does; `null` only if none
    % decides and none traps.
    Trap = e_binop(op_gt,
        e_binop(op_floordiv, lit_int(1i64), lit_int(0i64)), lit_int(1i64)),
    check("[LNUL.4.2] trap and false is false",
        ( if eval(e_binop(op_and, Trap, lit_bool(no)), ectx, ev_ok(bool(no)))
          then yes else no ), !T, !IO),
    check("[LNUL.4.2] false and trap is false",
        ( if eval(e_binop(op_and, lit_bool(no), Trap), ectx, ev_ok(bool(no)))
          then yes else no ), !T, !IO),
    check("[LEXP.7.15.2] y // x > 1 and x != 0, at x = 0, is false",
        ( if eval(e_binop(op_and, Trap,
                e_binop(op_ne, lit_int(0i64), lit_int(0i64))), ectx,
                ev_ok(bool(no)))
          then yes else no ), !T, !IO),
    check("[LNUL.4.2] trap and true is the trap",
        ( if eval(e_binop(op_and, Trap, lit_bool(yes)), ectx,
                ev_fault(rf_div_zero))
          then yes else no ), !T, !IO),
    check("[LNUL.4.2] null and trap is the trap -- a trap outranks null",
        ( if eval(e_binop(op_and, lit_null, Trap), ectx, ev_fault(rf_div_zero))
          then yes else no ), !T, !IO),
    check("[LNUL.4.2] trap or true is true",
        ( if eval(e_binop(op_or, Trap, lit_bool(yes)), ectx, ev_ok(bool(yes)))
          then yes else no ), !T, !IO),
    check("[LNUL.4.2] true or trap is true",
        ( if eval(e_binop(op_or, lit_bool(yes), Trap), ectx, ev_ok(bool(yes)))
          then yes else no ), !T, !IO),
    check("[LNUL.4.2] trap or false is the trap",
        ( if eval(e_binop(op_or, Trap, lit_bool(no)), ectx,
                ev_fault(rf_div_zero))
          then yes else no ), !T, !IO),
    % Two traps of one kind record identically ([LNUL.4.2]: "Two faults that
    % tie on every field record identically"); `%` by zero is DIVIDE_BY_ZERO.
    check("[LNUL.4.2] two traps of one kind: that kind",
        ( if eval(e_binop(op_and, Trap,
                e_binop(op_gt, e_binop(op_rem, lit_int(1i64), lit_int(0i64)),
                    lit_int(1i64))), ectx, ev_fault(F2)),
             expr_trap_kind(F2) = 1u32
          then yes else no ), !T, !IO),
    check("[LNUL.4.2] nested: (trap and true) and false is false",
        ( if eval(e_binop(op_and, e_binop(op_and, Trap, lit_bool(yes)),
                lit_bool(no)), ectx, ev_ok(bool(no)))
          then yes else no ), !T, !IO),

    % Every operand fault is absorbed, and when nothing decides the kind
    % order picks one, whatever the operand's position: EngineError,
    % TypeError, then the TrapKinds in value order.
    Domain = e_binop(op_gt,
        e_binop(op_shl, lit_int(1i64), lit_int(-1i64)), lit_int(0i64)),
    Lied = e_binop(op_add, lit_bool(yes), lit_int(1i64)),
    Typed = e_tainted(e_binop(op_add, lit_bool(yes), lit_int(1i64))),
    check("[LNUL.4.2] a clean mismatch beside a false is absorbed",
        ( if eval(e_binop(op_and, Lied, lit_bool(no)), ectx, ev_ok(bool(no)))
          then yes else no ), !T, !IO),
    check("[LNUL.4.2] a TypeError beside a false is absorbed",
        ( if eval(e_binop(op_and, lit_bool(no), Typed), ectx, ev_ok(bool(no)))
          then yes else no ), !T, !IO),
    check("[LNUL.4.2] DIVIDE_BY_ZERO outranks DOMAIN, either side",
        ( if eval(e_binop(op_and, Domain, Trap), ectx, ev_fault(rf_div_zero)),
             eval(e_binop(op_and, Trap, Domain), ectx, ev_fault(rf_div_zero))
          then yes else no ), !T, !IO),
    check("[LNUL.4.2] a TypeError outranks a trap, either side",
        ( if eval(e_binop(op_and, Trap, Typed), ectx, ev_fault(rf_type_error)),
             eval(e_binop(op_and, Typed, Trap), ectx, ev_fault(rf_type_error))
          then yes else no ), !T, !IO),
    check("[LNUL.4.2] an EngineError outranks a TypeError, either side",
        ( if eval(e_binop(op_or, Typed, Lied), ectx, ev_fault(rf_artefact_lied)),
             eval(e_binop(op_or, Lied, Typed), ectx, ev_fault(rf_artefact_lied))
          then yes else no ), !T, !IO),
    % Within a kind, at the first differing recorded field, the lower value
    % wins. Two EngineErrors differ in their
    % `EngineFault`: ARTEFACT_LIED (1) beats PATTERN_INDEX (2) -- a read of a
    % token position the empty test token does not have -- either side.
    ( if slot_index(0u32, S0) then
        PatIx = e_slot(token_fact(5), slot(S0)),
        check("[LNUL.4.2] within EngineError the lower EngineFault wins",
            ( if eval(e_binop(op_or, PatIx, Lied), ectx,
                    ev_fault(rf_artefact_lied)),
                 eval(e_binop(op_or, Lied, PatIx), ectx,
                    ev_fault(rf_artefact_lied))
              then yes else no ), !T, !IO)
    else
        check("[LNUL.4.2] slot index 0 exists", no, !T, !IO)
    ),
    % [RARC.5.3.3] / [RARC.5.6.11]: the two EngineErrors an expression raises on
    % its own, each asserted alone, beside libds's test_fault_emission cases
    % of the same names.
    % `ectx` holds an empty token and no bindings.
    ( if slot_index(0u32, PastSlot0) then
        check("[RARC.5.3.3] a slot read past the token is PATTERN_INDEX",
            ( if eval(e_slot(token_fact(5), slot(PastSlot0)), ectx,
                    ev_fault(rf_pattern_index))
              then yes else no ), !T, !IO)
    else
        check("[RARC.5.3.3] slot index 0 exists", no, !T, !IO)
    ),
    check("[RARC.5.3.3] an entry stamp past the token is PATTERN_INDEX",
        ( if eval(e_entry_stamp(token_fact(5)), ectx,
                ev_fault(rf_pattern_index))
          then yes else no ), !T, !IO),
    ( if bind_index(1, 0, UnboundIx0) then
        check("[RARC.5.6.11] a read before the binding ran is BINDING_ORDER",
            ( if eval(e_bind_ref(UnboundIx0), ectx, ev_fault(rf_binding_order))
              then yes else no ), !T, !IO)
    else
        check("[RARC.5.6.11] bind index 0 of 1 exists", no, !T, !IO)
    ),
    % @spec [RDSC.4a.9.6]
    check("[RDSC.4a.9.6] a read outside the frame is ARTEFACT_LIED, " ++
        "not BINDING_ORDER",
        ( if eval(e_bind_ref(bind_index_of(1u32)), ectx,
                ev_fault(rf_artefact_lied))
          then yes else no ), !T, !IO),
    check("[RDSC.4a.9.6] a write outside the frame is ARTEFACT_LIED, " ++
        "and its expression is not evaluated",
        ( if eval(e_bind(bind_index_of(1u32),
                    e_binop(op_floordiv, e_lit(int(1i64)), e_lit(int(0i64)))),
                ectx, ev_fault(rf_artefact_lied))
          then yes else no ), !T, !IO),
    % Both are EngineErrors, so both halt the tier, and each carries the
    % EngineFault libds records for it: PATTERN_INDEX 2, BINDING_ORDER 3.
    check("[LERR.1.4.7] both are EngineErrors, latched, as libds numbers them",
        ( if expr_fault_class(rf_pattern_index) = fc_engine,
             expr_fault_class(rf_binding_order) = fc_engine,
             disposition(ee_expr_fault(rf_pattern_index)) = latched,
             disposition(ee_expr_fault(rf_binding_order)) = latched,
             expr_engine_fault(rf_pattern_index) = 2u32,
             expr_engine_fault(rf_binding_order) = 3u32
          then yes else no ), !T, !IO),
    % The connective's own mismatch -- an operand that is neither a Bool nor
    % `null` -- is held too, and classified by the connective's taint.
    check("[LNUL.4.2] a non-Bool operand beside a false is absorbed",
        ( if eval(e_binop(op_and, lit_int(7i64), lit_bool(no)), ectx,
                ev_ok(bool(no)))
          then yes else no ), !T, !IO),
    check("[IRET.9.6] a non-Bool operand of a clean `and` is ARTEFACT_LIED",
        ( if eval(e_binop(op_and, lit_int(7i64), lit_bool(yes)), ectx,
                ev_fault(rf_artefact_lied))
          then yes else no ), !T, !IO),
    check("[IRET.9.6] ... and of a tainted `and`, a TypeError",
        ( if eval(e_tainted(e_binop(op_and, lit_int(7i64), lit_bool(yes))),
                ectx, ev_fault(rf_type_error))
          then yes else no ), !T, !IO),

    % An ill-typed operation is a fault, classified at the node that raised it
    % ([LERR.1]). A clean node's mismatch means the artefact's static types
    % lied -- EngineError; a `Json`-tainted node's is data -- TypeError.
    check("a type mismatch on a clean node is EngineError ARTEFACT_LIED",
        ( if eval(e_binop(op_add, lit_bool(yes), lit_int(1i64)), ectx,
                ev_fault(rf_artefact_lied))
          then yes else no ), !T, !IO),
    check("the same mismatch on a tainted node is a TypeError",
        ( if eval(e_tainted(e_binop(op_add, lit_bool(yes), lit_int(1i64))), ectx,
                ev_fault(rf_type_error))
          then yes else no ), !T, !IO),
    check("a child's class survives a tainted parent -- classified where raised",
        ( if eval(e_tainted(e_binop(op_add,
                e_binop(op_add, lit_bool(yes), lit_int(1i64)), lit_int(2i64))), ectx,
                ev_fault(rf_artefact_lied))
          then yes else no ), !T, !IO),

    % `+` on two Strings is not concatenation: `numeric/5` finds no pair of
    % numbers, as libds does. The refs are never expanded, since `numeric/5`
    % rejects the pair on its constructors alone, so any two distinct refs
    % stand for any two strings.
    check("`+` on two Strings faults, not concatenation",
        ( if eval(e_binop(op_add, e_lit(str(make_intern_ref(1u32))),
                        e_lit(str(make_intern_ref(2u32)))), ectx,
                ev_fault(rf_artefact_lied))
          then yes else no ), !T, !IO),

    % Shift right is arithmetic, sign-preserving [LEXP.7.14].
    evals("`>>` is arithmetic: -8 >> 1 is -4, not a large positive",
        e_binop(op_shr, lit_int(-8i64), lit_int(1i64)), int(-4i64), !T, !IO).

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% The matcher
%-----------------------------------------------------------------------------%
%
% Networks are built through `resolve_network`, the same path the loader takes,
% so these tests exercise resolution as well as matching.

    % A schema with an explicit id and name ref, so several can coexist.
:- func nschema(int, int, list(logical_slot)) = schema.

nschema(Id, NameRef, Slots) =
    schema(make_schema_id(uint32.det_from_int(Id)),
        make_schema_name(make_intern_ref(uint32.det_from_int(NameRef))),
        lc_logical(Slots, no), no, no).

:- func nid(int) = node_id.

nid(N) = Id :-
    ( if node_id(uint32.det_from_int(N), Id0) then
        Id = Id0
    else
        unexpected($pred, "node id")
    ).

:- func schema_map(list(schema)) = map(uint32, schema).

schema_map(Ss) = list.foldl(add_schema_by_id, Ss, map.init).

:- func add_schema_by_id(schema, map(uint32, schema)) = map(uint32, schema).

add_schema_by_id(S, M) = map.set(M, schema_id_value(S ^ s_id), S).

:- pred net_of(list(raw_alpha)::in, list(raw_beta)::in,
               list(raw_terminal)::in, network::out) is semidet.

net_of(As, Bs, Ts, N) :-
    resolve_network(As, Bs, Ts, network_ok(N)).

:- pred test_match(tally::in, tally::out, io::di, io::uo) is det.

test_match(!T, !IO) :-
    Sensor = nschema(1, 1, [wslot(0, role_key, exact),
                            wslot(1, role_mutable, exact)]),

    % AlphaNode 1 on Sensor; BetaNode 2 a ROOT over it; TerminalNode 3 under
    % the beta.
    ( if
        net_of([raw_alpha(nid(1), Sensor ^ s_name, [])],
               [raw_beta(nid(2), 1u32, 0u32, [], no)],
               [raw_terminal(nid(3), 2u32, make_intern_ref(9u32), 0, no,
                    0, [])],
               Net)
    then
        Index = build_index(Net, [Sensor]),

        assert_fact(Sensor, [int(1i64), int(10i64)], at(100), no, tms_none, live,
            R, init_wm, W1),
        ( if R = inserted(F1) then FactId = F1 else FactId = make_fact_id(0u64) ),
        Ctx = match_ctx(W1, schema_map([Sensor]), init_interns, at(100), no, init_cache,init_series_state),

        fact_asserted(Index, Ctx, FactId, D1, init_rete, S1),

        check("a fact reaching a root beta produces ONE activation",
            ( if D1 ^ md_added = [_] then yes else no ), !T, !IO),
        check("and none removed",
            ( if D1 ^ md_removed = [] then yes else no ), !T, !IO),

        % The root beta is seeded with a NIL TOKEN, so a right-activation
        % immediately produces a single-fact token at pattern index 0
        % [RDSC.4a.7].
        check("the token holds exactly that fact, at pattern index 0",
            ( if D1 ^ md_added = [activation(_, Token)],
                 Token ^ t_facts = [FactId]
              then yes else no ), !T, !IO),

        check("the activation names the terminal",
            ( if D1 ^ md_added = [activation(TermId, _)],
                 TermId = nid(3)
              then yes else no ), !T, !IO),

        % The timetag is stamped when the join mints the token [LDET.5.5]; the
        % activation inherits it verbatim, so zero would be the nil token's.
        check("and carries a minted timetag, not the nil token's",
            ( if D1 ^ md_added = [activation(_, Tok2)],
                 timetag_value(Tok2 ^ t_created) \= 0u64
              then yes else no ), !T, !IO),

        check("the alpha memory holds the fact",
            ( if alpha_memory(S1, nid(1)) = [FactId] then yes else no ),
            !T, !IO),
        check("and the beta memory holds the token",
            ( if beta_memory(S1, nid(2)) = [_] then yes else no ), !T, !IO),

        % The delta names the withdrawal explicitly: with a NOT node in the
        % network the direction cannot be inferred from which operation was
        % called.
        retract_wm(FactId, W1, W2),
        Ctx2 = match_ctx(W2, schema_map([Sensor]), init_interns, at(200), no, init_cache,init_series_state),
        fact_retracted(Index, Ctx2, FactId, D2, S1, S2),

        check("retracting the fact WITHDRAWS the activation",
            ( if D2 ^ md_removed = [_], D2 ^ md_added = [] then yes else no ),
            !T, !IO),
        check("and empties both memories",
            ( if alpha_memory(S2, nid(1)) = [],
                 beta_memory(S2, nid(2)) = []
              then yes else no ), !T, !IO),

        test_join(!T, !IO),
        test_not_node(!T, !IO),
        test_chain(!T, !IO)
    else
        check("the hand-built network resolves", no, !T, !IO)
    ).

    % Retract from working memory, ignoring the semidet failure a test would
    % never provoke.
:- pred retract_wm(fact_id::in, wm::in, wm::out) is det.

retract_wm(Id, !W) :-
    ( if retract_fact(Id, rc_explicit, !.W, W1) then !:W = W1 else true ).

:- pred test_join(tally::in, tally::out, io::di, io::uo) is det.

test_join(!T, !IO) :-
    Sensor = nschema(1, 1, [wslot(0, role_key, exact),
                            wslot(1, role_mutable, exact)]),

    % A root beta with a JOIN TEST: the candidate fact's slot 1 must exceed 50.
    % `pattern_index = 255` is the candidate, which is what makes a test on
    % a root beta meaningful at all -- the nil token has no facts to read.
    Guard = e_binop(op_gt, e_slot(candidate, slot(sidx(1))), e_lit(int(50i64))),
    ( if
        net_of([raw_alpha(nid(1), Sensor ^ s_name, [])],
               [raw_beta(nid(2), 1u32, 0u32, [Guard], no)],
               [raw_terminal(nid(3), 2u32, make_intern_ref(9u32), 0, no,
                    0, [])],
               Net)
    then
        Index = build_index(Net, [Sensor]),
        Schemas = schema_map([Sensor]),

        assert_fact(Sensor, [int(1i64), int(10i64)], at(100), no, tms_none, live,
            RLow, init_wm, W1),
        ( if RLow = inserted(Low) then LowId = Low
        else LowId = make_fact_id(0u64) ),
        fact_asserted(Index, match_ctx(W1, Schemas, init_interns, at(100), no, init_cache,init_series_state),
            LowId, DLow, init_rete, S1),

        check("a fact FAILING the join test produces no activation",
            ( if DLow ^ md_added = [] then yes else no ), !T, !IO),
        check("but still enters the alpha memory -- the test is at the JOIN",
            ( if alpha_memory(S1, nid(1)) = [_] then yes else no ), !T, !IO),

        assert_fact(Sensor, [int(2i64), int(90i64)], at(200), no, tms_none, live,
            RHigh, W1, W2),
        ( if RHigh = inserted(High) then HighId = High
        else HighId = make_fact_id(0u64) ),
        fact_asserted(Index, match_ctx(W2, Schemas, init_interns, at(200), no, init_cache,init_series_state),
            HighId, DHigh, S1, _),

        check("a fact PASSING it produces one",
            ( if DHigh ^ md_added = [_] then yes else no ), !T, !IO),

        % Null never fires [LNUL.4.3]: a join test evaluating to null declines
        % (`kleene_logic.als`).
        assert_fact(Sensor, [int(3i64), null], at(300), no, tms_none, live,
            RNull, W2, W3),
        ( if RNull = inserted(N) then NullId = N
        else NullId = make_fact_id(0u64) ),
        fact_asserted(Index, match_ctx(W3, Schemas, init_interns, at(300), no, init_cache,init_series_state),
            NullId, DNull, S1, _),
        check("a join test yielding NULL declines to fire (LNUL.4.3)",
            ( if DNull ^ md_added = [] then yes else no ), !T, !IO)
    else
        check("the join network resolves", no, !T, !IO)
    ).

:- func sidx(int) = slot_index.

sidx(N) = S :-
    ( if slot_index(uint32.det_from_int(N), S0) then
        S = S0
    else
        unexpected($pred, "slot index")
    ).

:- pred test_not_node(tally::in, tally::out, io::di, io::uo) is det.

test_not_node(!T, !IO) :-
    Trig = nschema(1, 1, [wslot(0, role_key, exact)]),
    Block = nschema(2, 2, [wslot(0, role_key, exact)]),

    % Trig t, no Block b  ->  a positive root beta on Trig, then a NEGATIVE
    % beta over Block chained beneath it.
    ( if
        net_of([raw_alpha(nid(1), Trig ^ s_name, []),
                raw_alpha(nid(2), Block ^ s_name, [])],
               [raw_beta(nid(3), 1u32, 0u32, [], no),
                raw_beta(nid(4), 2u32, 3u32, [], yes)],
               [raw_terminal(nid(5), 4u32, make_intern_ref(9u32), 0, no,
                    0, [])],
               Net)
    then
        Index = build_index(Net, [Trig, Block]),
        Schemas = schema_map([Trig, Block]),

        % The trigger alone: nothing blocks, so the NOT node passes it.
        assert_fact(Trig, [int(1i64)], at(100), no, tms_none, live,
            RT, init_wm, W1),
        ( if RT = inserted(Tf) then TrigId = Tf
        else TrigId = make_fact_id(0u64) ),
        fact_asserted(Index, match_ctx(W1, Schemas, init_interns, at(100), no, init_cache,init_series_state),
            TrigId, D1, init_rete, S1),

        check("a NOT node PASSES its token when nothing matches",
            ( if D1 ^ md_added = [_] then yes else no ), !T, !IO),

        check("and passes it UNCHANGED -- a NOT node binds nothing",
            ( if D1 ^ md_added = [activation(_, Tok)],
                 Tok ^ t_facts = [TrigId]
              then yes else no ), !T, !IO),

        % An ASSERT withdraws an activation here, which is why `match_delta`
        % carries both directions rather than letting the caller infer one.
        assert_fact(Block, [int(1i64)], at(200), no, tms_none, live, RB, W1, W2),
        ( if RB = inserted(Bf) then BlockId = Bf
        else BlockId = make_fact_id(0u64) ),
        fact_asserted(Index, match_ctx(W2, Schemas, init_interns, at(200), no, init_cache,init_series_state),
            BlockId, D2, S1, S2),

        check("asserting a BLOCKER withdraws the activation",
            ( if D2 ^ md_removed = [_], D2 ^ md_added = [] then yes else no ),
            !T, !IO),
        check("and the NOT node's output is now empty",
            ( if beta_memory(S2, nid(4)) = [] then yes else no ), !T, !IO),
        check("while the positive beta above it still holds its token",
            ( if beta_memory(S2, nid(3)) = [_] then yes else no ), !T, !IO),

        % Which tokens were blocked is stored nowhere: it is recomputed as the
        % left input minus what is passing. See `ds.match`'s `rete_state`.
        retract_wm(BlockId, W2, W3),
        fact_retracted(Index, match_ctx(W3, Schemas, init_interns, at(300), no, init_cache,init_series_state),
            BlockId, D3, S2, S3),

        check("retracting the blocker UNBLOCKS -- a retract that ADDS",
            ( if D3 ^ md_added = [_], D3 ^ md_removed = [] then yes else no ),
            !T, !IO),
        check("and the NOT node passes again",
            ( if beta_memory(S3, nid(4)) = [_] then yes else no ), !T, !IO)
    else
        check("the NOT network resolves", no, !T, !IO)
    ).

:- pred test_chain(tally::in, tally::out, io::di, io::uo) is det.

test_chain(!T, !IO) :-
    A = nschema(1, 1, [wslot(0, role_key, exact)]),
    B = nschema(2, 2, [wslot(0, role_key, exact)]),

    % Two positive patterns: a root beta on A, then a beta on B chained under
    % it. A complete match needs one fact of each.
    ( if
        net_of([raw_alpha(nid(1), A ^ s_name, []),
                raw_alpha(nid(2), B ^ s_name, [])],
               [raw_beta(nid(3), 1u32, 0u32, [], no),
                raw_beta(nid(4), 2u32, 3u32, [], no)],
               [raw_terminal(nid(5), 4u32, make_intern_ref(9u32), 0, no,
                    0, [])],
               Net)
    then
        Index = build_index(Net, [A, B]),
        Schemas = schema_map([A, B]),

        assert_fact(A, [int(1i64)], at(100), no, tms_none, live, RA, init_wm, W1),
        ( if RA = inserted(Fa) then AId = Fa else AId = make_fact_id(0u64) ),
        fact_asserted(Index, match_ctx(W1, Schemas, init_interns, at(100), no, init_cache,init_series_state),
            AId, D1, init_rete, S1),

        check("one pattern of two produces NO activation",
            ( if D1 ^ md_added = [] then yes else no ), !T, !IO),

        assert_fact(B, [int(2i64)], at(200), no, tms_none, live, RB, W1, W2),
        ( if RB = inserted(Fb) then BId = Fb else BId = make_fact_id(0u64) ),
        fact_asserted(Index, match_ctx(W2, Schemas, init_interns, at(200), no, init_cache,init_series_state),
            BId, D2, S1, S2),

        check("the second completes the match",
            ( if D2 ^ md_added = [_] then yes else no ), !T, !IO),

        % Pattern order is semantic: position i is the fact bound by the i-th
        % positive pattern, and `fact_index` indexes into it.
        check("and the token holds both, in PATTERN order",
            ( if D2 ^ md_added = [activation(_, Tok)],
                 Tok ^ t_facts = [AId, BId]
              then yes else no ), !T, !IO),

        % A second fact of the first pattern joins against the existing second:
        % left activation, the direction the first assert did not exercise.
        assert_fact(A, [int(3i64)], at(300), no, tms_none, live, RA2, W2, W3),
        ( if RA2 = inserted(Fa2) then AId2 = Fa2
        else AId2 = make_fact_id(0u64) ),
        fact_asserted(Index, match_ctx(W3, Schemas, init_interns, at(300), no, init_cache,init_series_state),
            AId2, D3, S2, S3),

        check("a new left fact joins against the existing right memory",
            ( if D3 ^ md_added = [activation(_, Tok2)],
                 Tok2 ^ t_facts = [AId2, BId]
              then yes else no ), !T, !IO),

        % Retracting the SHARED right fact must withdraw BOTH tokens -- the
        % cascade through a node that fed two descendants.
        retract_wm(BId, W3, W4),
        fact_retracted(Index, match_ctx(W4, Schemas, init_interns, at(400), no, init_cache,init_series_state),
            BId, D4, S3, S4),

        check("retracting the shared fact withdraws BOTH activations",
            ( if D4 ^ md_removed = [_, _] then yes else no ), !T, !IO),
        check("leaving the chained beta empty",
            ( if beta_memory(S4, nid(4)) = [] then yes else no ), !T, !IO),
        check("but the root beta still holds both its tokens",
            ( if beta_memory(S4, nid(3)) = [_, _] then yes else no ), !T, !IO)
    else
        check("the chain network resolves", no, !T, !IO)
    ).

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% Rule metadata
%-----------------------------------------------------------------------------%


:- pred test_rule_meta(tally::in, tally::out, io::di, io::uo) is det.

test_rule_meta(!T, !IO) :-
    with_fixture("36_logical_defer.dsc", check_ordinals_meta, !T, !IO),
    with_fixture("36_logical_defer.dsc", check_ordinals_follow_terms, !T,
        !IO),
    with_fixture("07_action_verbs.dsc", check_one_rule_meta, !T, !IO).

    % [RDSC.8.4]: "The order of the `TerminalNode` atoms is the terminal
    % ordinal", and the runtime numbers the terminals "from that sequence and
    % from nothing else", not from the order the rule metadata arrived in,
    % which attaches by name ([RDSC.8.3]), as libds's `rete/loader.c` does.
    % The fixture's two terminals are taken in TerminalNode order and each
    % one's metadata is fed to the resolver in the other order; the ordinals
    % follow the terminals, both ways round.
    %
:- pred check_ordinals_follow_terms(program::in, tally::in, tally::out,
                                    io::di, io::uo) is det.

check_ordinals_follow_terms(P, !T, !IO) :-
    IT0 = interns(P),
    ( if
        terminal_nodes(network(P)) = [T1, T2],
        expand(IT0, T1 ^ tn_rule, N1),
        expand(IT0, T2 ^ tn_rule, N2),
        % The second terminal's metadata first, then the first's.
        decode_rule_atom(at_rule_debug_name, reader_over(dnam_body(N2)),
            init_rules_staging, IT0, rs_ok(Rg1, IT1)),
        decode_rule_atom(at_rule_debug_name, reader_over(dnam_body(N1)), Rg1, IT1,
            rs_ok(Rg, _)),
        resolve_rule_meta(Rg, [T1, T2], rules_ok(Metas)),
        resolve_rule_meta(Rg, [T2, T1], rules_ok(Swapped))
    then
        check("[RDSC.8.4] the ordinals follow the TerminalNode sequence, not "
            ++ "the "
            ++ "order the rule metadata arrived in",
            ( if
                list.map(source_of, Metas) = [0, 1],
                list.map((func(M) = M ^ rm_name), Metas)
                    = [T1 ^ tn_rule, T2 ^ tn_rule]
              then yes else no ), !T, !IO),
        check("[RDSC.8.4] and with the terminals the other way round, the "
            ++ "ordinals follow them there too",
            ( if
                list.map(source_of, Swapped) = [0, 1],
                list.map((func(M) = M ^ rm_name), Swapped)
                    = [T2 ^ tn_rule, T1 ^ tn_rule]
              then yes else no ), !T, !IO)
    else
        check("[RDSC.8.4] 36_logical_defer's two terminals and their RuleDebugName "
            ++ "atoms resolve", no, !T, !IO)
    ).

    % A `RuleDebugName` body: `rule_name` 1 and `name_template` 2.
    %
:- func dnam_body(string) = list(int).

dnam_body(Name) = [0x0A, list.length(NameBytes) | NameBytes]
        ++ [0x12, 1, 0x78] :-
    string.to_utf8_code_unit_list(Name, NameBytes).

:- pred check_ordinals_meta(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_ordinals_meta(P, !T, !IO) :-
    Metas = rule_metas(P),
    io.format("  note: 36_logical_defer ordinals = %s\n",
        [s(string(list.map(source_of, Metas)))], !IO),

    check("two rules give two rule_metas",
        ( if Metas = [_, _] then yes else no ), !T, !IO),

    % The ordinal is the agenda's first key [LDET.5.4], read from the artefact's
    % emission order [RLOW.14.3] and never re-derived: cross-file order is
    % import-DAG topological, leaf libraries first, and a synthesized terminal
    % has no rule in source to derive one from [RLOW.14.7].
    check("the ordinal is assigned from emission order, 0 upwards",
        ( if Sources = list.map(source_of, Metas),
             list.sort(Sources) = [0, 1]
          then yes else no ), !T, !IO),

    % No rule in this fixture declares a rate limit, so the window is absent
    % rather than zero -- "no cooldown" and "a cooldown of zero" are different
    % statements the wire spells the same way.
    check("no RuleCooldown means no rate limit, not a zero window",
        ( if list.all_true(unlimited, Metas) then yes else no ), !T, !IO),

    % The fire guard comes from the terminal, not from the metadata atoms,
    % and these rules have none, since none is rate limited.
    check("and no fire guard, since nothing gates them",
        ( if list.all_true(unguarded, Metas) then yes else no ), !T, !IO).

:- func source_of(rule_meta) = int.

source_of(M) = source_index_int(M ^ rm_source).

:- pred unlimited(rule_meta::in) is semidet.

unlimited(M) :-
    not rate_limited(M ^ rm_rate).

:- pred unguarded(rule_meta::in) is semidet.

unguarded(M) :-
    M ^ rm_fire_guard = no.

    % Whether the first atom kind appears before the second.
:- pred precedes(list(atom_id)::in, atom_id::in, atom_id::in) is semidet.

precedes([A | As], First, Second) :-
    ( if A = First then
        list.member(Second, As)
    else
        A \= Second,
        precedes(As, First, Second)
    ).

:- pred check_one_rule_meta(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_one_rule_meta(P, !T, !IO) :-
    Metas = rule_metas(P),

    check("a single-rule artefact gives that rule ordinal 0",
        ( if Metas = [M], source_index_int(M ^ rm_source) = 0 then yes else no ),
        !T, !IO),

    % TerminalNode carries no module_id, so metadata joins to its terminal on
    % rule name alone.
    check("and is attached to the terminal it names",
        ( if Metas = [M2], terminal_nodes(network(P)) = [T2],
             M2 ^ rm_terminal = T2 ^ tn_id,
             M2 ^ rm_name = T2 ^ tn_rule
          then yes else no ), !T, !IO),

    check("with a rule name that expands",
        ( if Metas = [M3], expand(interns(P), M3 ^ rm_name, N), N \= ""
          then yes else no ), !T, !IO),

    % One place assembles the order key, so the ordering inputs cannot disagree
    % with the rule they came from. See ds.rules.order_key_of.
    check("and an order key derived from the ordinal, not copied alongside it",
        ( if Metas = [M4],
             order_key_of(M4, make_timetag(7u64)) = order_key(Ord, TT),
             Ord = M4 ^ rm_source,
             timetag_value(TT) = 7u64
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% The agenda
%-----------------------------------------------------------------------------%
%
% Firing order is `order_key`'s automatic ordering, so these assert on the
% order things come out in. There is no comparator.

:- func act(int, list(int), int) = activation.

act(Term, Facts, TT) =
    activation(nid(Term),
        token(list.map(fid, Facts), make_timetag(uint64.det_from_int(TT)))).

:- func fid(int) = fact_id.

fid(N) = make_fact_id(uint64.det_from_int(N)).

    % (terminal ordinal, timetag).
:- func key(int, int) = order_key.

key(Ord, TT) = order_key(sidx_of(Ord), make_timetag(uint64.det_from_int(TT))).

    % Drain the agenda, collecting the timetags in firing order.
:- pred drain(refraction::in, list(int)::out, agenda::in, agenda::out) is det.

drain(R, Order, !A) :-
    select(R, set.init, Sel, !A),
    (
        Sel = nothing_to_fire,
        Order = []
    ;
        Sel = fire(order_key(_, TT), _),
        drain(R, Rest, !A),
        Order = [tt_as_int(timetag_value(TT)) | Rest]
    ).

:- func tt_as_int(uint64) = int.

tt_as_int(N) = uint64.cast_to_int(N).

:- pred test_agenda(tally::in, tally::out, io::di, io::uo) is det.

test_agenda(!T, !IO) :-
    % The ordinal beats the timetag [LDET.5.4]: rule 0 fires first though its
    % activation was created last, since source order is the outer key.
    A0 = init_agenda,
    ( if
        enqueue(key(2, 1), act(1, [1], 1), A0, A1),
        enqueue(key(1, 2), act(2, [2], 2), A1, A2),
        enqueue(key(0, 3), act(3, [3], 3), A2, A3)
    then
        drain(init_refraction, Order, A3, _),
        check("ordinal beats timetag: rule 0 fires first though created LAST",
            ( if Order = [3, 2, 1] then yes else no ), !T, !IO)
    else
        check("three distinct keys enqueue", no, !T, !IO)
    ),

    % Within one rule, timetag ascending [LDET.5.5].
    ( if
        enqueue(key(1, 30), act(1, [1], 30), A0, B1),
        enqueue(key(1, 10), act(2, [2], 10), B1, B2),
        enqueue(key(1, 20), act(3, [3], 20), B2, B3)
    then
        drain(init_refraction, Order2, B3, _),
        check("within one rule, ascending creation order",
            ( if Order2 = [10, 20, 30] then yes else no ), !T, !IO)
    else
        check("same-rule keys enqueue", no, !T, !IO)
    ),

    % `determinism.tla` calls two activations under one key a divergent
    % trace. A map holds one entry per key, so within a band a duplicate key
    % is a duplicate timetag.
    check("a DUPLICATE ORDER KEY IS REFUSED, not silently overwritten",
        ( if enqueue(key(1, 5), act(1, [1], 5), A0, C1),
             enqueue(key(1, 5), act(2, [2], 5), C1, _)
          then no else yes ), !T, !IO),

    check("and the entry already there is untouched",
        ( if enqueue(key(1, 5), act(1, [1], 5), A0, C2),
             not enqueue(key(1, 5), act(2, [2], 5), C2, _),
             peek(C2, _, activation(Term, _)),
             Term = nid(1)
          then yes else no ), !T, !IO),

    check("an empty agenda selects nothing rather than failing",
        ( if select(init_refraction, set.init, nothing_to_fire, A0, _)
              then yes else no ),
        !T, !IO),

    % A match withdrawn before it fires -- a NOT node's blocker arriving, a
    % justifying fact retracted -- must leave the agenda.
    check("an activation can be withdrawn before firing",
        ( if enqueue(key(1, 7), act(1, [1], 7), A0, D1),
             withdraw(key(1, 7), D1, D2),
             agenda_count(D2) = 0
          then yes else no ), !T, !IO),
    check("but withdrawing one that is not there FAILS rather than succeeding",
        ( if withdraw(key(1, 7), A0, _) then no else yes ), !T, !IO),

    test_refraction(!T, !IO).

:- pred test_refraction(tally::in, tally::out, io::di, io::uo) is det.

test_refraction(!T, !IO) :-
    A0 = init_agenda,
    Act = act(1, [1, 2], 5),

    latch(set.init, Act, init_refraction, R1),
    check("an activation that has fired is refracted",
        ( if is_refracted(R1, set.init, Act) then yes else no ), !T, !IO),

    % Keyed on the terminal as well as the tuple, so the same facts matching a
    % different rule are not suppressed.
    check("the same facts at a different terminal are NOT",
        ( if is_refracted(R1, set.init, act(2, [1, 2], 5)) then no else yes ), !T, !IO),

    % Keyed on the fact tuple, not the timetag: a re-created activation over
    % the same facts is the same edge.
    check("nor is the timetag part of the key -- the fact tuple is",
        ( if is_refracted(R1, set.init, act(1, [1, 2], 99)) then yes else no ), !T, !IO),

    % A different tuple is a different edge. A meaningful change mints a fresh
    % fact_id [LFAC.2.5.3], so a materially changed fact produces a token the
    % latch has never seen: edge-once, not fire-once.
    check("a different fact tuple is a different edge and fires",
        ( if is_refracted(R1, set.init, act(1, [1, 3], 5)) then no else yes ), !T, !IO),

    % A refracted activation is destroyed without firing [IRET.11.3], not
    % demoted below the others.
    ( if
        enqueue(key(1, 1), Act, A0, E1),
        enqueue(key(1, 2), act(1, [3, 4], 2), E1, E2)
    then
        drain(R1, Order, E2, Left),
        check("a refracted activation is DESTROYED, not demoted",
            ( if Order = [2] then yes else no ), !T, !IO),
        check("and does not reappear at the end of the agenda",
            ( if agenda_count(Left) = 0 then yes else no ), !T, !IO),

        % A suppressed firing is otherwise invisible: nothing emitted, nothing
        % recorded.
        select_counting(R1, set.init, Sel, Suppressed, E2, _),
        check("the suppression is counted, since it is otherwise invisible",
            ( if Suppressed = 1, Sel = fire(_, _) then yes else no ), !T, !IO)
    else
        check("the refraction agenda enqueues", no, !T, !IO)
    ),

    % [IRET.11.3.2]: a fired activation stays refracted until it is
    % re-created, its token removed and back, and nothing else clears it.
    % `forget` is that re-creation, one identity at a time.
    latch(set.init, act(1, [3, 4], 2), R1, R2),
    R3 = forget(set.init, act(1, [1, 2], 7), R2),
    check("[IRET.11.3.2] a removed identity no longer refracts",
        ( if is_refracted(R3, set.init, Act) then no else yes ), !T, !IO),
    check("[IRET.11.3.2] and an identity that was not removed still does",
        ( if is_refracted(R3, set.init, act(1, [3, 4], 2)) then yes else no ),
        !T, !IO),
    check("forget of an identity that never fired changes nothing",
        ( if is_refracted(forget(set.init, act(1, [9], 1), R2), set.init, Act)
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% Truth maintenance
%-----------------------------------------------------------------------------%
%
% Mercury implements the refcount, matching libds; `ds.conform` implements the
% fixpoint as an oracle. So these tests come in two kinds: what the engine does,
% and what the oracle says about it. The orphan case is where they part, and
% that test is a positive control: it asserts the oracle fires.

:- pred test_tms(tally::in, tally::out, io::di, io::uo) is det.

test_tms(!T, !IO) :-
    % A schema for the antecedents and one for the derived facts.
    S = nschema(1, 1, [wslot(0, role_key, exact)]),

    assert_fact(S, [int(1i64)], at(100), no, tms_none, live, R1, init_wm, W1),
    assert_fact(S, [int(2i64)], at(100), no, tms_none, live, R2, W1, W2),
    assert_fact(S, [int(3i64)], at(100), no, tms_derived, live, R3, W2, W3),
    ( if R1 = inserted(A) then Ante1 = A else Ante1 = fid(0) ),
    ( if R2 = inserted(B) then Ante2 = B else Ante2 = fid(0) ),
    ( if R3 = inserted(D) then Derived = D else Derived = fid(0) ),

    % One activation over Ante1 derives the fact.
    Act1 = activation(nid(9), token([Ante1], make_timetag(1u64))),
    justify(Act1, Derived, init_tms, T1),

    check("a justified fact has a refcount of one",
        ( if justif_count(T1, Derived) = 1 then yes else no ), !T, !IO),
    check("and is TMS-linked",
        ( if is_derived(T1, Derived) then yes else no ), !T, !IO),
    check("while an antecedent is not -- linkage is by ASSERTION VERB",
        ( if is_derived(T1, Ante1) then no else yes ), !T, !IO),

    % Multi-justifier survival [IRET.12.3], the safety property
    % `tms_cascade.tla` machine-checks. A second activation over a different
    % fact justifies the same derived fact.
    Act2 = activation(nid(9), token([Ante2], make_timetag(2u64))),
    justify(Act2, Derived, T1, T2),

    check("a second justification raises the count",
        ( if justif_count(T2, Derived) = 2 then yes else no ), !T, !IO),

    activation_ended(Act1, Unsupported1, T2, T3),
    check("losing ONE of two justifiers does NOT unsupport the fact",
        ( if Unsupported1 = [] then yes else no ), !T, !IO),
    check("and the oracle agrees it is still supported",
        ( if supported_fixpoint(T3, W3, Derived) then yes else no ), !T, !IO),

    activation_ended(Act2, Unsupported2, T3, T4),
    check("losing the SECOND retracts it",
        ( if Unsupported2 = [Derived] then yes else no ), !T, !IO),

    % The two formulations part here. Both antecedents are still live: the
    % activations stopped matching, as a NOT node's blocker arriving does, so
    % the count reaches zero while every antecedent survives.
    check("with both antecedents still live, the FIXPOINT calls it supported",
        ( if supported_fixpoint(T4, W3, Derived) then yes else no ), !T, !IO),
    check("though the refcount has reached zero",
        ( if justif_count(T4, Derived) = 0 then yes else no ), !T, !IO),
    check("and the oracle reports the disagreement rather than hiding it",
        ( if desyncs(T4, W3) = [desync(Derived, 0, yes)] then yes else no ),
        !T, !IO),

    test_cascade(!T, !IO),
    test_orphan(!T, !IO).

:- pred test_cascade(tally::in, tally::out, io::di, io::uo) is det.

test_cascade(!T, !IO) :-
    S = nschema(1, 1, [wslot(0, role_key, exact)]),

    % A chain of three: Base justifies Mid, Mid justifies Top.
    assert_fact(S, [int(1i64)], at(100), no, tms_none, live, RB, init_wm, W1),
    assert_fact(S, [int(2i64)], at(100), no, tms_derived, live, RM, W1, W2),
    assert_fact(S, [int(3i64)], at(100), no, tms_derived, live, RT, W2, W3),
    ( if RB = inserted(B) then Base = B else Base = fid(0) ),
    ( if RM = inserted(M) then Mid = M else Mid = fid(0) ),
    ( if RT = inserted(Tp) then Top = Tp else Top = fid(0) ),

    ActMid = activation(nid(9), token([Base], make_timetag(1u64))),
    ActTop = activation(nid(8), token([Mid], make_timetag(2u64))),
    justify(ActMid, Mid, init_tms, T1),
    justify(ActTop, Top, T1, T2),

    check("a three-fact chain is fully supported while its base is live",
        ( if supported_fixpoint(T2, W3, Mid),
             supported_fixpoint(T2, W3, Top)
          then yes else no ), !T, !IO),

    % Retract the base. Under the fixpoint the whole chain collapses at once,
    % because support is recomputed from the live set rather than propagated.
    retract_wm(Base, W3, W4),
    forget_fact(Base, T2, T3),

    check("removing the base collapses the WHOLE chain under the fixpoint",
        ( if quiescent_set(T3, W4) = [] then yes else no ), !T, !IO),
    check("so both derived facts are orphans until the cascade runs",
        ( if list.length(orphans(T3, W4)) = 2 then yes else no ), !T, !IO),

    % The refcount collapses it one level per round, which is why the cascade is
    % a loop in the engine rather than a single step here.
    activation_ended(ActMid, Round1, T3, T4),
    check("the refcount unsupports one LEVEL per round, not the whole chain",
        ( if Round1 = [Mid] then yes else no ), !T, !IO),

    retract_wm(Mid, W4, W5),
    forget_fact(Mid, T4, T5),
    activation_ended(ActTop, Round2, T5, T6),
    check("and the second round takes the next level",
        ( if Round2 = [Top] then yes else no ), !T, !IO),

    retract_wm(Top, W5, W6),
    forget_fact(Top, T6, T7),
    check("after which the oracle reports no orphans -- the cascade completed",
        ( if orphans(T7, W6) = [] then yes else no ), !T, !IO),

    % TTL expiry cascades through TMS: a justifier leaving working memory for
    % any reason unsupports its dependents.
    assert_fact(S, [int(1i64)], at(100), yes(at(500)), tms_none, live,
        RE, init_wm, E1),
    assert_fact(S, [int(2i64)], at(100), no, tms_derived, live, RD, E1, E2),
    ( if RE = inserted(Ex) then Expiring = Ex else Expiring = fid(0) ),
    ( if RD = inserted(Dv) then Dep = Dv else Dep = fid(0) ),
    ActDep = activation(nid(9), token([Expiring], make_timetag(1u64))),
    justify(ActDep, Dep, init_tms, TE1),

    expire(at(500), Expired, E2, E3),
    check("a TTL-bounded justifier expires",
        ( if Expired = [_] then yes else no ), !T, !IO),
    forget_fact(Expiring, TE1, TE2),
    check("and its dependent becomes unsupported -- TTL cascades",
        ( if supported_fixpoint(TE2, E3, Dep) then no else yes ), !T, !IO).

:- pred test_orphan(tally::in, tally::out, io::di, io::uo) is det.

test_orphan(!T, !IO) :-
    % A justification registered after its activation ended has nothing to
    % decrement it, so the fact is live with a count of one and no live
    % support. The engine retracts such a fact as it is made ([LLOG.15.1],
    % `ds.tms.resolve_deferred`); here the pieces are driven directly, as the
    % oracle's positive control.
    S = nschema(1, 1, [wslot(0, role_key, exact)]),
    assert_fact(S, [int(1i64)], at(100), no, tms_none, live, RA, init_wm, W1),
    assert_fact(S, [int(2i64)], at(100), no, tms_derived, live, RD, W1, W2),
    ( if RA = inserted(A) then Ante = A else Ante = fid(0) ),
    ( if RD = inserted(D) then Derived = D else Derived = fid(0) ),

    Act = activation(nid(9), token([Ante], make_timetag(1u64))),

    % The match breaks first, the rule's own RHS retracting its antecedent,
    % and the justification is registered afterwards.
    activation_ended(Act, Nothing, init_tms, T1),
    check("an activation that derived nothing yet ends without complaint",
        ( if Nothing = [] then yes else no ), !T, !IO),

    justify(Act, Derived, T1, T2),
    retract_wm(Ante, W2, W3),
    forget_fact(Ante, T2, T3),

    % The refcount says supported: the activation's entry was consumed by the
    % ending that came first.
    check("the refcount still calls the fact supported -- count is 1",
        ( if justif_count(T3, Derived) = 1 then yes else no ), !T, !IO),

    % The positive control: `iret_12_2__no_unsupported_forever` says every
    % unsupported fact is eventually retracted, and the oracle fires here.
    check("but the ORACLE FIRES: the fact is live, unsupported and permanent",
        ( if orphans(T3, W3) = [Derived] then yes else no ), !T, !IO),

    check("and the two formulations are recorded as disagreeing",
        ( if desyncs(T3, W3) = [desync(Derived, 1, no)] then yes else no ),
        !T, !IO),

    % The property the oracle implements, stated the other way round: a
    % well-behaved run has no orphans and no desyncs at all.
    check("while a well-formed justification produces neither",
        ( if justify(Act, Derived, init_tms, T4),
             orphans(T4, W2) = [], desyncs(T4, W2) = []
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% The executor -- and the whole loop, end to end
%-----------------------------------------------------------------------------%
%
% `07_action_verbs` is one rule with every RHS verb, so firing it once
% exercises the entire action surface against a real artefact. The path is bytes
% on disk, through the loader, the network, working memory, the matcher, the
% agenda and the executor, to a stream.

    % The metrics are left out. A metric rides beside the events whose
    % dispatch emits it ([NMET.4.1]), so every list here would carry one before
    % nearly every name, and each assertion below is about the events and the
    % actions. `metric_names` is the list for a check about the metrics.
    %
:- func effect_names(list(effect)) = list(string).

effect_names(Es) = list.map(effect_name, list.negated_filter(is_metric, Es)).

:- func metric_names(list(effect)) = list(string).

metric_names(Es) = list.map(effect_name, list.filter(is_metric, Es)).

    % A step's effects without its metrics, for a check about its events.
    %
:- func events_of(list(effect)) = list(effect).

events_of(Es) = list.negated_filter(is_metric, Es).

:- pred is_metric(effect::in) is semidet.

is_metric(eff_metric(_)).

    % A settle closure that propagates nothing, for firing a terminal with no
    % network behind it. Threads `unit` as the caller state; `ds.exec.fire` is
    % polymorphic in it.
    %
:- pred no_settle(list(effect)::in, list(effect)::out, list(effect)::out,
                  exec_state::in, exec_state::out, unit::in, unit::out) is det.

no_settle(Own, Own, [], !S, !U).

:- func effect_name(effect) = string.

effect_name(eff_event(E)) = event_name(E).
effect_name(eff_action(A)) = "do:" ++ verb_name_of(A).
effect_name(eff_input(hi_open(_))) = "input:open".
effect_name(eff_input(hi_close)) = "input:close".
effect_name(eff_cache_expired(K)) = "cache_expired:" ++ K.
effect_name(eff_metric(M)) = "metric:" ++ M ^ m_name.
effect_name(eff_host_log(_, Category, _)) = "host_log:" ++ Category.
effect_name(eff_pump_status(ps_nan_rejected)) = "pump_status:nan_rejected".
effect_name(eff_pump_status(ps_contract_breach(_))) =
    "pump_status:contract_breach".
effect_name(eff_pump_status(ps_time_range)) = "pump_status:time_range".

:- func event_name(stream_event) = string.

event_name(se_fact_assert(_, _, _, _)) = "assert".
event_name(se_fact_retract(_)) = "retract".
event_name(se_fact_withdraw(_, _)) = "withdraw".
event_name(se_fact_withdraw_unnamed(_, _)) = "withdraw".
event_name(se_clock_advance(_)) = "clock".
event_name(se_pump_boundary) = "pump".
event_name(se_call_response(_, _)) = "call_response".
event_name(se_call_error(_, _)) = "call_error".
event_name(se_fire_begin(_)) = "BEGIN".
event_name(se_rule_lhs_facts(_, _)) = "LHS".
event_name(se_fire_end(_)) = "END".
event_name(se_timer_armed(_, _, _)) = "timer_armed".
event_name(se_clock_tick(_, _)) = "tick".
event_name(se_engine_error(_, _)) = "engine_error".
event_name(se_call_issued(_, _, _, _, _)) = "call_issued".
event_name(se_cache_set(_, _, _)) = "cache_set".
event_name(se_cache_delete(_)) = "cache_delete".
event_name(se_emit(_, _)) = "emit".
event_name(se_publish(_, _, _)) = "publish".
event_name(se_log_emitted(_, _)) = "log".

:- pred test_exec(tally::in, tally::out, io::di, io::uo) is det.

test_exec(!T, !IO) :-
    with_fixture("07_action_verbs.dsc", check_end_to_end, !T, !IO).

:- pred check_end_to_end(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_end_to_end(P, !T, !IO) :-
    Schemas = schemas(P),
    IT = interns(P),
    ( if
        find_schema(Schemas, IT, "Trig", Trig),
        rule_metas(P) = [Meta],
        terminal_nodes(network(P)) = [Term]
    then
        SchemaMap = schema_map(Schemas),
        Index = build_index(network(P), Schemas),

        % A Trig fact enters working memory.
        assert_fact(Trig, [int(1i64)], at(1000), no, tms_none, live, R,
            init_wm, W1),
        ( if R = inserted(F) then FactId = F else FactId = fid(0) ),

        % ...and the matcher turns it into an activation.
        MatchCtx = match_ctx(W1, SchemaMap, IT, at(1000), no, init_cache, init_series_state),
        fact_asserted(Index, MatchCtx, FactId, Delta, init_rete, _),

        check("a real fact through a real network yields one activation",
            ( if Delta ^ md_added = [_] then yes else no ), !T, !IO),

        ( if Delta ^ md_added = [Activation] then
            % ...which goes on the agenda under the rule's order key.
            Key = order_key_of(Meta, Activation ^ ac_token ^ t_created),
            ( if enqueue(Key, Activation, init_agenda, A1) then
                select(init_refraction, set.init, Sel, A1, _),
                check("the agenda selects it",
                    ( if Sel = fire(_, _) then yes else no ), !T, !IO)
            else
                check("the activation enqueues", no, !T, !IO)
            ),

            % ...and firing it runs all seven actions.
            ExecCtx = exec_ctx(SchemaMap, at(1000), no, Meta, no,
                no_cache_caps, default_hydration_budget, [], [],
                map.init, Term ^ tn_binds),
            State0 = exec_state(W1, init_tms, init_cache, init_series_state,
                init_rate_table, bool.no, IT, 0, [], [], map.init),
            % No settling here: the terminal fires in isolation, with no
            % network to propagate into, so the closure returns no cascade and
            % the effects are the firing's own. `check_multi_justifier` and the
            % differential suite cover the settled path.
            fire(ExecCtx, Activation, actions_for(P, Term ^ tn_id),
                no_settle, Effects, State0, State1, unit, _),

            io.format("  note: firing 07_action_verbs = %s\n",
                [s(string(effect_names(Effects)))], !IO),
            % The bracket, with the LHS event outside it. `RULE_FIRE_END` is
            % last, unconditionally.
            check("the LHS event comes FIRST, then BEGIN, then END last",
                ( if effect_names(Effects) = ["LHS", "BEGIN" | Rest],
                     list.last(Rest, "END")
                  then yes else no ), !T, !IO),

            % A separate event immediately before the bracket, outside the
            % frame the begin opens: the adjacent reading of
            % `firing_event_frame.als`.
            check("and it names the fact the rule matched",
                ( if Effects = [eff_event(se_rule_lhs_facts(_, [FactId])) | _]
                  then yes else no ), !T, !IO),

            % Record before act, for every verb ([IDSP.1.4]).
            check("record precedes act -- log's event comes before its action",
                ( if precedes_str(effect_names(Effects), "log", "do:log")
                  then yes else no ), !T, !IO),
            check("and the CALL records first too",
                ( if precedes_str(effect_names(Effects), "call_issued",
                        "do:call")
                  then yes else no ), !T, !IO),

            % Action order is emission order [IRET.10], and the source lists the
            % logs before the emit before the publish.
            check("action order is source order: logs, then emit, then publish",
                ( if Names = effect_names(Effects),
                     precedes_str(Names, "log", "assert"),
                     precedes_str(Names, "assert", "publish")
                  then yes else no ), !T, !IO),

            % `emit Alert` really asserted, and `publish Alert` asserted
            % NOTHING ([LTIE.4.3]): the Trig and the emitted Alert are all of
            % working memory, and the firing's one `assert` is the emit's.
            check("emit asserted a fact into working memory, and publish none",
                ( if live_count(State1 ^ xs_wm) = 2 then yes else no ),
                !T, !IO),
            check("and publish emitted its event and no assert",
                ( if Names2 = effect_names(Effects),
                     list.member("publish", Names2),
                     list.filter((pred(N::in) is semidet :- N = "assert"),
                        Names2) = ["assert"]
                  then yes else no ), !T, !IO),

            % The delete removes a key that was never set: a no-op, not an
            % error.
            %
            % The stored value is JSON text, not `int(1i64)`. The source writes
            % `value: 1`; the inline encoding wraps it as `ds_json_value(1)`,
            % and libds's `cache_set_cb` takes a `const char *value_json`.
            % Checked through the intern table, since the ref is whatever this
            % load assigned.
            check("cache set stored its value as JSON text under its key",
                ( if cache_get(State1 ^ xs_cache, "last_alert", str(CRef)),
                     expand(State1 ^ xs_interns, CRef, "1")
                  then yes else no ), !T, !IO),
            check("and the cache holds exactly that one entry",
                ( if cache_size(State1 ^ xs_cache) = 1 then yes else no ),
                !T, !IO),
            % The event carries the write, not only its key: [NCBK.2.3]'s
            % `{key, value, ttl_ns}`. The source gives no TTL.
            check("the cache_set event carries key, JSON value and TTL",
                ( if list.member(eff_event(se_cache_set(CKey, CValue, CTtl)),
                        Effects),
                     CKey = "last_alert", CValue = "1", CTtl = no
                  then yes else no ), !T, !IO),

            % Nothing here is `emit ... logical`, so nothing is TMS-linked:
            % justification is keyed on the assertion verb, not the schema.
            check("no verb here is logical, so nothing was TMS-linked",
                ( if derived_facts(State1 ^ xs_tms) = [] then yes else no ),
                !T, !IO),

            % All six verbs left their mark: the fixture holds seven actions
            % over six kinds, two of them `log`.
            check("all six verbs produced their effect",
                ( if All = effect_names(Effects),
                     list.all_true(in_list(All),
                        ["log", "assert", "publish", "call_issued",
                         "cache_set", "cache_delete"])
                  then yes else no ), !T, !IO),

            % Exactly two of them dispatch outward: `log` and `call` reach the
            % integrator; `emit`, `publish` and the two cache verbs are
            % engine-internal and produce events only. The fixture's two
            % `log`s both dispatch, so the outward list holds three entries.
            % No verb requires a synchronous result from the integrator, which
            % lets the rule-evaluation core be a pure function returning an
            % effect list.
            check("two verbs dispatch outward, four are engine-internal",
                ( if list.filter(is_do, effect_names(Effects)) =
                        ["do:log", "do:log", "do:call"]
                  then yes else no ), !T, !IO)
        else
            check("the activation is available to fire", no, !T, !IO)
        )
    else
        check("the fixture has one rule, one terminal and a Trig schema",
            no, !T, !IO)
    ).

:- pred is_do(string::in) is semidet.

is_do(S) :- string.prefix(S, "do:").

:- pred precedes_str(list(string)::in, string::in, string::in) is semidet.

precedes_str([A | As], First, Second) :-
    ( if A = First then
        list.member(Second, As)
    else
        A \= Second,
        precedes_str(As, First, Second)
    ).

%-----------------------------------------------------------------------------%

:- pred in_list(list(string)::in, string::in) is semidet.

in_list(L, X) :- list.member(X, L).

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% The engine
%-----------------------------------------------------------------------------%
%
% One assert, one pump. Everything the previous sections tested separately, run
% as the engine runs it, and the fire budget, the firing limit of
% [LTIM.2.5.1].

:- pred test_engine(tally::in, tally::out, io::di, io::uo) is det.

test_engine(!T, !IO) :-
    with_fixture("07_action_verbs.dsc", check_pump, !T, !IO),
    with_fixture("36_logical_defer.dsc", check_frame_balance, !T, !IO),
    with_fixture("33_multi_justifier.dsc", check_multi_justifier, !T, !IO),
    with_fixture("09_negation_and_within.dsc", check_sweep_at_pump, !T, !IO),
    with_fixture("09_negation_and_within.dsc", check_fact_stamps, !T, !IO),
    with_fixture("09_negation_and_within.dsc", check_edge_at_firing_limit,
        !T, !IO),
    with_fixture("36_logical_defer.dsc", check_action_partition, !T, !IO).

    % Action order is emission order [IRET.10]. `36_logical_defer` has two
    % rules, each `emit` then `log` in source; `07_action_verbs`' message verbs
    % come first anyway, so it cannot show this.
    %
:- pred check_action_partition(program::in, tally::in, tally::out,
                               io::di, io::uo) is det.

check_action_partition(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Trig", Trig) then
        host_assert(Trig, [int(1i64)], no, _, _, E0, E1),
        pump(default_budget, Effects, E1, _),
        Names = effect_names(Effects),
        io.format("  note: partitioned firing = %s\n",
            [s(string(Names))], !IO),

        % The two verbs at issue, in the order they came out. Both rules are
        % `emit` then `log` in source, so both report the assert first.
        Moved = list.filter(is_log_or_assert, Names),
        check("a `log` written AFTER an emit is delivered AFTER it, in both "
                ++ "rules",
            ( if Moved = ["assert", "log", "assert", "log"]
              then yes else no ), !T, !IO)
    else
        check("the fixture declares Trig", no, !T, !IO)
    ).

:- pred is_log_or_assert(string::in) is semidet.

is_log_or_assert("log").
is_log_or_assert("assert").

    % Multi-justifier survival, through the engine [IRET.12.3]: a `logical`
    % emit naming a fact that already exists takes the no-op branch, which
    % must still `justify` it, so the fact holds both justifications.
    %
:- pred check_multi_justifier(program::in, tally::in, tally::out,
                              io::di, io::uo) is det.

check_multi_justifier(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if
        find_schema(schemas(P), interns(P), "Smoke", Smoke),
        find_schema(schemas(P), interns(P), "Heat", Heat)
    then
        host_assert(Smoke, [int(1i64)], no, RS, _, E0, E1),
        host_assert(Heat, [int(1i64)], no, RH, _, E1, E2),
        pump(default_budget, _, E2, E3),

        % Two rules, one derived Alarm: three facts, not four.
        check("both rules fire and derive ONE Alarm between them",
            ( if live_count(engine_wm(E3)) = 3 then yes else no ), !T, !IO),

        ( if RS = inserted(SmokeId), RH = inserted(HeatId) then
            host_retract(SmokeId, _, E3, E4),
            pump(default_budget, _, E4, E5),
            check("withdrawing ONE justifier leaves the Alarm standing",
                ( if live_count(engine_wm(E5)) = 2 then yes else no ),
                !T, !IO),

            host_retract(HeatId, _, E5, E6),
            pump(default_budget, _, E6, E7),
            check("withdrawing the LAST one retracts it",
                ( if live_count(engine_wm(E7)) = 0 then yes else no ),
                !T, !IO)
        else
            check("the antecedents inserted", no, !T, !IO)
        )
    else
        check("the fixture declares Smoke and Heat", no, !T, !IO)
    ).

    % A fact keeps its FactAssert's seq and its entry wall instant
    % ([LFST.5.6], [RFCS.23.5]), the twin of libds's `test_fact_stamps`:
    %
    %   - the stamp's seq is the position of the fact's own FactAssert in the
    %     stream, counted across steps (the tick before it is seq 0);
    %   - its wall is the held wall sample of the step it entered at;
    %   - a no-op reassert emits another FactAssert and leaves the stamp alone.
    %
:- pred check_fact_stamps(program::in, tally::in, tally::out,
                          io::di, io::uo) is det.

check_fact_stamps(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Override", Over) then
        set_wall_clock(1_700_000_000_000_000_000i64, E0, E1),
        engine_intern("lobby", Zone, E1, E2),
        host_assert(Over, [str(Zone)], no, R1, Eff1, E2, E3),
        Events1 = list.filter_map(
            ( func(Eff) = Ev is semidet :- Eff = eff_event(Ev) ), Eff1),
        ( if
            R1 = inserted(Id),
            list.find_first_match(
                ( pred(Ev::in) is semidet :- Ev = se_fact_assert(Id, _, _, _) ),
                Events1, Assert),
            list.index0_of_first_occurrence(Events1, Assert, K),
            lookup_fact(engine_wm(E3), Id, F1),
            F1 ^ f_stamp = yes(fact_stamp(Seq1, Wall1))
        then
            check("the stamp's seq is its FactAssert's position",
                ( if Seq1 = uint64.cast_from_int(K) then yes else no ),
                !T, !IO),
            check("and its wall is the step's held sample",
                ( if Wall1 = yes(1_700_000_000_000_000_000i64)
                  then yes else no ), !T, !IO),

            set_wall_clock(1_700_000_000_500_000_000i64, E3, E4),
            host_assert(Over, [str(Zone)], no, R2, Eff2, E4, E5),
            check("a reassert of the same fact is a no-op",
                ( if R2 = noop(Id) then yes else no ), !T, !IO),
            check("that still records a FactAssert",
                ( if
                    list.find_first_match(
                        ( pred(Eff::in) is semidet :-
                            Eff = eff_event(se_fact_assert(Id, _, _, _)) ),
                        Eff2, _)
                  then yes else no ), !T, !IO),
            check("and leaves the fact's stamp as it was",
                ( if
                    lookup_fact(engine_wm(E5), Id, F2),
                    F2 ^ f_stamp = yes(fact_stamp(Seq1, Wall1))
                  then yes else no ), !T, !IO)
        else
            check("the asserted fact is stamped", no, !T, !IO)
        )
    else
        check("fixture declares Override", no, !T, !IO)
    ).

    % [RARC.7.15]: a pump retracts the expired `ttl` facts at its entry, and a
    % clock advance does not (`ds.engine.sweep_expired`), as libds does.
    %
:- pred check_sweep_at_pump(program::in, tally::in, tally::out,
                            io::di, io::uo) is det.

check_sweep_at_pump(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "DoorOpen", Door) then
        % `DoorOpen` is `ts: Time, zone: String`; a `Time` is an `int` of
        % nanoseconds on the wire.
        engine_intern("lobby", Zone, E0, Ez),
        host_assert(Door, [int(1i64), str(Zone)], no, _, _, Ez, E1),
        pump(default_budget, _, E1, E2),
        % The host's count, which leaves the `$ClockTick` out as libds's
        % `fact_count()` does: the fixture's `within` rule is clock-driven, so
        % working memory itself holds the tick too.
        check("the DoorOpen is live before the clock moves",
            ( if engine_fact_count(E2) = 1 then yes else no ), !T, !IO),

        % DoorOpen is `scope ttl 1_h`; one nanosecond past the hour.
        advance(duration_from_ns(3600000000001u64), AdvEffects, E2, E3),
        check("advancing past the deadline retracts NOTHING yet",
            ( if engine_fact_count(E3) = 1 then yes else no ), !T, !IO),
        check("and the advance emits no retract of its own",
            ( if list.member("retract", effect_names(AdvEffects))
              then no else yes ), !T, !IO),

        pump(default_budget, PumpEffects, E3, E4),
        check("the PUMP is what sweeps it",
            ( if engine_fact_count(E4) = 0 then yes else no ), !T, !IO),
        % An expiry is the engine's withdrawal, not a host retract: FactWithdraw
        % `TTL_EXPIRED` [RFCS.7a].
        check("the sweep withdraws the fact, it does not host-retract it",
            ( if list.member("withdraw", effect_names(PumpEffects)),
                 not list.member("retract", effect_names(PumpEffects))
              then yes else no ), !T, !IO)
    else
        check("the fixture declares DoorOpen", no, !T, !IO)
    ).

    % An edge left unfired at a firing limit ([LTIM.2.5.1]). A pump that
    % stops at its limit leaves the
    % activation unfired, not dropped: it fires on a later pump if its match
    % persists until then, and not if the condition has closed --
    % `edge_once_firing.tla`'s `teeth.limited` and `teeth.starved`.
    %
    % `break_in_alert` is clock-driven (`DoorOpen d within 5_min`, nothing
    % logical), so its window is the maturity guard read under each pump's
    % sample. Two DoorOpens open two edges in the first pump; a budget of one
    % fires one and trips with the other queued. From there the run forks:
    % one second later both windows are still open, and the fired edge stays
    % suppressed while the unfired one fires; six minutes later both have
    % closed, and nothing fires.
    %
:- pred check_edge_at_firing_limit(program::in, tally::in, tally::out,
                                   io::di, io::uo) is det.

check_edge_at_firing_limit(P, !T, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "DoorOpen", Door) then
        engine_intern("hall", Zone, E0, Ez),
        host_assert(Door, [int(1i64), str(Zone)], no, _, _, Ez, E1),
        host_assert(Door, [int(2i64), str(Zone)], no, _, _, E1, E2),
        pump(fire_budget(1), First, E2, E3),
        check("[LTIM.2.5.1] a limit of one fires one of the two edges",
            ( if count_named("BEGIN", First) = 1 then yes else no ),
            !T, !IO),
        check("and stops with the other queued, not dropped",
            ( if
                list.member(eff_event(se_engine_error(Trip, _)), First),
                Trip = ee_fire_budget_exceeded(_)
              then yes else no ),
            !T, !IO),

        advance(duration_from_ns(1000000000u64), _, E3, E4),
        pump(default_budget, Limited, E4, _),
        check("teeth.limited: the unfired edge fires on the next pump, and "
            ++ "the fired one does not fire again",
            ( if count_named("BEGIN", Limited) = 1 then yes else no ),
            !T, !IO),

        advance(duration_from_ns(360000000000u64), _, E3, E5),
        pump(default_budget, Starved, E5, _),
        check("teeth.starved: an unfired edge whose window has closed by "
            ++ "the next pump never fires",
            ( if count_named("BEGIN", Starved) = 0 then yes else no ),
            !T, !IO)
    else
        check("the fixture declares DoorOpen", no, !T, !IO)
    ).

:- func count_named(string, list(effect)) = int.

count_named(Name, Effects) =
    list.length(list.filter((pred(N::in) is semidet :- N = Name),
        effect_names(Effects))).

:- pred check_pump(program::in, tally::in, tally::out, io::di, io::uo) is det.

check_pump(P, !T, !IO) :-
    % Mock clock, matching `engine.clock_set_mode("mock")` in the libds half.
    % A live clock refuses `advance` and makes every run differ.
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Trig", Trig) then
        host_assert(Trig, [int(1i64)], no, R, AssertEffects, E0, E1),

        % The engine's first sample is recorded, before the step's own event
        % ([LTIM.2.8.5]).
        check("a host assert inserts and emits its event, after the first "
            ++ "sample's tick",
            ( if R = inserted(_),
                 effect_names(AssertEffects) = ["tick", "assert"]
              then yes else no ), !T, !IO),

        % Assert matches immediately but does not fire. There is no
        % engine-owned queue: the fact is applied and matched on the spot, and
        % firing is the pump's job.
        check("and matches immediately, queueing an activation without firing",
            ( if pending_activations(E1) = 1 then yes else no ), !T, !IO),

        pump(default_budget, PumpEffects, E1, E2),
        io.format("  note: pump effects = %s\n",
            [s(string(effect_names(PumpEffects)))], !IO),

        check("the pump fires it",
            ( if list.member("BEGIN", effect_names(PumpEffects))
              then yes else no ), !T, !IO),
        check("and drains the agenda",
            ( if pending_activations(E2) = 0 then yes else no ), !T, !IO),

        % The rule emits an Alert and publishes another, and a publish asserts
        % nothing ([LTIE.4.3]), so working memory holds two facts afterwards:
        % the Trig and the emitted Alert.
        check("the rule's own assertion landed in working memory, and the "
                ++ "publish's did not",
            ( if live_count(engine_wm(E2)) = 2 then yes else no ), !T, !IO),

        % ...and those assertions were fed back through the matcher. Nothing
        % matches Alert, so no new activation, but the cascade path ran.
        check("which were re-matched, producing no further activation here",
            ( if pending_activations(E2) = 0 then yes else no ), !T, !IO),

        % A second pump is a no-op: the rule does not re-fire on its own
        % effects, because the activation was consumed. Its one effect is its
        % boundary: every host pump announces itself, including one that does
        % nothing ([RFCS.22]), and the clock did not move, so there is no tick.
        pump(default_budget, Again, E2, _),
        check("a second pump does nothing -- the engine is quiescent",
            ( if events_of(Again) = [eff_event(se_pump_boundary)]
              then yes else no ),
            !T, !IO),

        % The budget. With zero firings allowed and work outstanding, the pump
        % stops, reports, and leaves the survivors queued: a pause, not a
        % discard. libds surfaces the condition only as a return status, which
        % a recording cannot see; here it is an event.
        pump(fire_budget(0), Tripped, E1, E3),
        % The arm is named, not just the event class: `effect_names` renders
        % every `se_engine_error` as `"engine_error"`.
        check("a budget of zero trips rather than firing",
            ( if events_of(Tripped) = [eff_event(se_pump_boundary),
                            eff_event(se_engine_error(Budget, _))],
                 Budget = ee_fire_budget_exceeded(_)
              then yes else no ),
            !T, !IO),
        check("and the survivor stays queued -- a pause, not a discard",
            ( if pending_activations(E3) = 1 then yes else no ), !T, !IO),
        check("so the next pump drains it",
            ( if pump(default_budget, _, E3, E4),
                 pending_activations(E4) = 0
              then yes else no ), !T, !IO),

        % An exhausted budget with nothing queued is not a breach: quiescence
        % and a trip are different outcomes.
        check("but an exhausted budget with an empty agenda reports nothing",
            ( if pump(fire_budget(0), Idle, E2, _),
                 events_of(Idle) = [eff_event(se_pump_boundary)]
              then yes else no ), !T, !IO)
    else
        check("the fixture declares Trig", no, !T, !IO)
    ).

:- pred check_frame_balance(program::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_frame_balance(P, !T, !IO) :-
    % Mock clock, matching `engine.clock_set_mode("mock")` in the libds half.
    % A live clock refuses `advance` and makes every run differ.
    engine_use_mock_clock(init_engine(P), E0),
    ( if find_schema(schemas(P), interns(P), "Trig", Trig) then
        host_assert(Trig, [int(10i64)], no_deadline, AR, _AE, E0, E1),
        check("the fixture's fact inserts",
            ( if AR = inserted(_) then yes else no ), !T, !IO),
        pump(default_budget, Effects, E1, E2),

        io.format("  note: multi-rule pump = %s\n",
            [s(string(effect_names(Effects)))], !IO),

        check("a matching fact fires a rule",
            ( if list.member("BEGIN", effect_names(Effects)) then yes else no ),
            !T, !IO),
        check("and the engine reaches quiescence",
            ( if pending_activations(E2) = 0 then yes else no ), !T, !IO),

        % Every firing frame is balanced, however many fire: `RULE_FIRE_END` is
        % unconditional (`firing_event_frame.als`).
        check("every firing frame is balanced",
            ( if Names = effect_names(Effects),
                 Begins = list.length(list.filter(is_str("BEGIN"), Names)) : int,
                 Ends = list.length(list.filter(is_str("END"), Names)) : int,
                 Begins = Ends
              then yes else no ), !T, !IO)
    else
        check("the fixture declares Trig", no, !T, !IO)
    ).

:- pred is_str(string::in, string::in) is semidet.

is_str(A, A).

%-----------------------------------------------------------------------------%

    % A `maybe(instant)` spelled out, because `no` is a constructor of both
    % `maybe` and `bool` and a clause using both leaves the compiler nothing to
    % disambiguate on.
:- func no_deadline = maybe(instant).

no_deadline = no.

%-----------------------------------------------------------------------------%

%-----------------------------------------------------------------------------%
% Trace mode -- the Mercury half of the differential harness
%-----------------------------------------------------------------------------%
%
% Runs a scenario and emits the canonical trace. The runtime differential
% emits the same trace from the reference runtime and diffs the two.

    % `replay`: drive a fresh engine from a recording and print the trace.
    %
    % The contract the `PumpBoundary` atoms carry ([RFCS.22], [LFST.9.2]): a
    % recording's input events, delivered to a fresh engine in order, must
    % re-derive the same output. This tests the engine, using the codec as the
    % carrier.
    %
    % Only inputs are delivered: [LFST.6.1]'s "minimum set required for
    % replay", asserts, retracts and clock movement. The engine internals in
    % the stream (`RuleFireAnnotation`, and everything the recording drops)
    % are re-derived.
    %
    % The output is the trace format `trace` prints, so the replay and the
    % original run diff directly. The artefact is the whole of the engine's
    % schemas ([NFCT.1.1]).
    %
:- pred replay_recording(string::in, string::in, io::di, io::uo) is det.

replay_recording(ArtefactPath, RecordingPath, !IO) :-
    read_bitmap(ArtefactPath, ArtefactRes, !IO),
    read_bitmap(RecordingPath, RecordingRes, !IO),
    ( if
        ArtefactRes = yes(ABM),
        RecordingRes = yes(RBM)
    then
        load_dsc(ABM, LoadResult),
        (
            LoadResult = loaded(P),
            decode_stream(RBM, init_interns, Decoded),
            (
                Decoded = decode_failed(Clause, Offset),
                io.format("decode refused %s at byte %d\n",
                    [s(Clause), i(Offset)], !IO),
                io.set_exit_status(1, !IO)
            ;
                Decoded = decoded(DS),
                drive_replay(P, DS, no, !IO)
            ;
                % [RFCS.5.4]: what came before the unannounced
                % FactAssert replays, and the replay is refused at it.
                Decoded = unannounced_schema(DS, Seq, _),
                drive_replay(P, DS, yes(Seq), !IO)
            )
        ;
            LoadResult = load_failed(E),
            io.format("load refused %s %s\n",
                [s(string.string(E ^ le_kind)),
                 s(clause_id_string(E ^ le_clause))], !IO)
        )
    else
        io.write_string("OPEN FAILED\n", !IO),
        io.set_exit_status(1, !IO)
    ).

%-----------------------------------------------------------------------------%
% `schemas` -- the loaded slot table, which is where hydration is visible
%-----------------------------------------------------------------------------%
%
% [RHIM.2] makes the compiler responsible for the whole of hydration's schema
% surface: it injects a `hydrated_corr` slot, appends it last, marks it
% `mutable` on a logical schema, and injects it into exactly the literal
% `schema:` targets and nowhere else. Each is a statement about what an
% artefact's Slot atoms look like.
%
% Read through `ds.dsc.schemas`, the loader, for the same reason `atoms` walks
% with `ds.atom.next_frame`: a second decoder is a second implementation of one
% semantic. What prints is what the engine will match against, not a rendering
% of the file.

:- pred list_schemas(string::in, io::di, io::uo) is det.

list_schemas(Path, !IO) :-
    read_bitmap(Path, Res, !IO),
    (
        Res = yes(BM),
        load_dsc(BM, LoadRes),
        (
            LoadRes = loaded(P),
            Interns = interns(P),
            list.foldl(print_schema(Interns), schemas(P), !IO)
        ;
            LoadRes = load_failed(E),
            io.format("load refused %s %s\n",
                [s(string.string(E ^ le_kind)),
                 s(clause_id_string(E ^ le_clause))], !IO),
            io.set_exit_status(1, !IO)
        )
    ;
        Res = no,
        io.format("cannot read %s\n", [s(Path)], !IO),
        io.set_exit_status(2, !IO)
    ).

:- pred print_schema(intern_table::in, schema::in, io::di, io::uo) is det.

print_schema(Interns, S, !IO) :-
    Name = text(Interns, schema_name_ref(S ^ s_name)),
    Lc = S ^ s_lifecycle,
    (
        Lc = lc_logical(Slots, Ambient),
        (
            Ambient = yes,
            Kind = "logical ambient"
        ;
            Ambient = no,
            Kind = "logical"
        ),
        io.format("%s  %s  (%d slots)\n",
            [s(Name), s(Kind), i(list.length(Slots))], !IO),
        list.foldl(print_logical_slot(Interns), Slots, !IO)
    ;
        Lc = lc_ttl(Slots, Default),
        io.format("%s  ttl %s ns  (%d slots)\n",
            [s(Name), s(uint64_to_string(duration_ns(Default))),
             i(list.length(Slots))], !IO),
        list.foldl(print_plain_slot(Interns), Slots, !IO)
    ;
        Lc = lc_explicit(Slots),
        io.format("%s  explicit  (%d slots)\n",
            [s(Name), i(list.length(Slots))], !IO),
        list.foldl(print_plain_slot(Interns), Slots, !IO)
    ;
        % The SchemaLogical atom's `lifecycle` separates it from `explicit`
        % ([RDSC.5.4.5]).
        Lc = lc_activation(Slots),
        io.format("%s  activation  (%d slots)\n",
            [s(Name), i(list.length(Slots))], !IO),
        list.foldl(print_plain_slot(Interns), Slots, !IO)
    ).

:- pred print_logical_slot(intern_table::in, logical_slot::in,
                           io::di, io::uo) is det.

print_logical_slot(Interns, LS, !IO) :-
    C = LS ^ ls_common,
    ( LS ^ ls_role = role_key, Role = "key"
    ; LS ^ ls_role = role_mutable, Role = "mutable"
    ; LS ^ ls_role = role_engine, Role = "engine"
    ),
    io.format("    [%d] %-16s %-10s %s%s\n",
        [i(slot_index_int(C ^ sc_index)), s(text(Interns, C ^ sc_name)),
         s(kind_text(Interns, C ^ sc_kind)), s(Role),
         s(slot_flags(C))], !IO).

:- pred print_plain_slot(intern_table::in, plain_slot::in, io::di, io::uo) is det.

print_plain_slot(Interns, TS, !IO) :-
    C = TS ^ ps_common,
    io.format("    [%d] %-16s %-10s%s\n",
        [i(slot_index_int(C ^ sc_index)), s(text(Interns, C ^ sc_name)),
         s(kind_text(Interns, C ^ sc_kind)), s(slot_flags(C))], !IO).

    % `hydratable` is printed although nothing sets it, so a Hydration atom
    % would show.
    %
:- func slot_flags(slot_common) = string.

slot_flags(C) =
    ( if C ^ sc_nullable = nullable then " nullable" else "" ) ++
    ( if C ^ sc_sampled = yes then " sampled" else "" ) ++
    ( if C ^ sc_retained = yes then " retained" else "" ) ++
    ( if C ^ sc_hydratable = yes then " HYDRATABLE" else "" ).

:- func kind_text(intern_table, slot_kind) = string.

kind_text(_, k_int) = "Int".
kind_text(_, k_float) = "Float".
kind_text(_, k_string) = "String".
kind_text(_, k_bool) = "Bool".
kind_text(_, k_json) = "Json".
kind_text(_, k_bytes) = "Bytes".
kind_text(I, k_schema(N)) = "->" ++ text(I, schema_name_ref(N)).
kind_text(_, k_time) = "Time".
kind_text(_, k_date) = "Date".
kind_text(_, k_duration) = "Duration".

:- func text(intern_table, intern_ref) = string.

text(I, R) = ( if expand(I, R, S) then S else "<unresolved>" ).

%-----------------------------------------------------------------------------%
% SERIES -- the backings, and the read-only invariant
%-----------------------------------------------------------------------------%

:- pred test_series(tally::in, tally::out, io::di, io::uo) is det.

test_series(!T, !IO) :-
    % A 10-second sliding window, so eviction is reachable in a test without
    % large numbers.
    D = series_decl(bk_ring_buffer, "S", "v", "id", el_float,
        10u64 * 1000000000u64, 0u64, 0u32, tm_unspecified, gp_unspecified, np_unspecified),
    K = series_key("S", "v", "id", "kitchen", 0u64),

    % [LSER.8.6.1]: a read before any sample is the ordinary case, and
    % [LSER.19.8] answers it with `null` for every aggregation but the six the
    % clause names. The `null` is the guard; there is no other.
    query(agg_mean, K, at(0), init_series_state, cold_value(agg_mean, no), Cold),
    check("a cold series reads as null",
        ( if Cold = null then yes else no ), !T, !IO),

    % The six that keep a zero are typed, as libds's `series_zero_default`
    % narrowed by `series_slot_is_int`: an Int slot's is `0`, not `0.0`
    % ([LSER.16.2]).
    check("a cold count is Int 0 whatever the slot",
        ( if cold_value(agg_count, no) = int(0i64), cold_value(agg_count, yes) = int(0i64)
          then yes else no ), !T, !IO),
    check("a cold sum is Int 0 over an Int slot and Float 0.0 over any other",
        ( if cold_value(agg_sum, yes) = int(0i64), cold_value(agg_sum, no) = float(0.0)
          then yes else no ), !T, !IO),
    % [LSER.19.8] — bool_and / bool_or are NOT in the keep-a-zero set: `true`
    % and `false` are the vacuous answers over an empty series, and returning
    % one lets a rule fire on a series that has told it nothing.
    check("a cold bool_and / bool_or / mean / min is null",
        ( if
            cold_value(agg_bool_and, no) = null,
            cold_value(agg_bool_or, no) = null,
            cold_value(agg_mean, yes) = null,
            cold_value(agg_min, yes) = null
          then yes else no ), !T, !IO),

    absorb(D, K, float(20.0), at(0), init_series_state, S1),
    absorb(D, K, float(30.0), at(1000000000), S1, S2),
    absorb(D, K, float(40.0), at(2000000000), S2, S3),

    check("mean over three samples",
        ( if query(agg_mean, K, at(2000000000), S3, cold_value(agg_mean, no), float(M)), M = 30.0
          then yes else no ), !T, !IO),
    check("min and max over three samples",
        ( if query(agg_min, K, at(2000000000), S3, cold_value(agg_min, no), float(Lo)), Lo = 20.0,
             query(agg_max, K, at(2000000000), S3, cold_value(agg_max, no), float(Hi)), Hi = 40.0
          then yes else no ), !T, !IO),
    check("count and sum over three samples",
        ( if query(agg_count, K, at(2000000000), S3, cold_value(agg_count, no), int(3i64)),
             query(agg_sum, K, at(2000000000), S3, cold_value(agg_sum, no), float(Sum)), Sum = 90.0
          then yes else no ), !T, !IO),

    % `first` is the oldest in the window and `last` the newest; samples are
    % stored newest-first. A sliding `first` / `last` is SeriesBackendFifoDeque's
    % (`dsc.rete.lser_18_1_backing`); the ring buffer does not answer them, in
    % libds or here (`ds.series.serves`).
    DFifo = D ^ sd_backing := bk_fifo_deque,
    absorb(DFifo, K, float(20.0), at(0), S3, SF1),
    absorb(DFifo, K, float(30.0), at(1000000000), SF1, SF2),
    absorb(DFifo, K, float(40.0), at(2000000000), SF2, SF3),
    check("first is the oldest sample, last the newest",
        ( if query(agg_first, K, at(2000000000), SF3, cold_value(agg_first, no), float(F)), F = 20.0,
             query(agg_last, K, at(2000000000), SF3, cold_value(agg_last, no), float(L)), L = 40.0
          then yes else no ), !T, !IO),
    check("a backing that does not serve the aggregation answers it cold",
        ( if query(agg_first, K, at(2000000000), S3, cold_value(agg_first, no), null)
          then yes else no ), !T, !IO),

    % [RDSC.5a.8.1], [RDSC.5a.8.2]: two backings at one window are parallel,
    % each keyed by the whole tuple, so each absorbs a sample once. The engine
    % absorbs a fact once per declaration (`ds.engine.absorb_decl`), so a `count`
    % beside a `min` reads each sample once, as libds's does.
    DMono = D ^ sd_backing := bk_monotonic_deque,
    KTwo = series_key("T", "v", "", "", 10u64 * 1000000000u64),
    absorb(D, KTwo, float(5.0), at(0), init_series_state, TB1),
    absorb(DMono, KTwo, float(5.0), at(0), TB1, TB2),
    absorb(D, KTwo, float(3.0), at(1000000000), TB2, TB3),
    absorb(DMono, KTwo, float(3.0), at(1000000000), TB3, TB4),
    check("two backings at one window each absorb a sample once",
        ( if query(agg_count, KTwo, at(1000000000), TB4, cold_value(agg_count, no), int(2i64)),
             query(agg_sum, KTwo, at(1000000000), TB4, cold_value(agg_sum, no), float(8.0)),
             query(agg_min, KTwo, at(1000000000), TB4, cold_value(agg_min, no), float(3.0))
          then yes else no ), !T, !IO),

    % SeriesBackendWelfordEwma (`all_time`) and SeriesBackendReservoir
    % (`sample <n>`) both declare window 0, so without the backing in the key
    % they were one row, and the reservoir's shape and the running stats'
    % overwrote each other. An unbounded read takes the running stats where
    % they serve, as libds's `series_pick_backend_slot` does.
    DWel = (D ^ sd_backing := bk_welford) ^ sd_window := 0u64,
    DRes = ((D ^ sd_backing := bk_reservoir) ^ sd_window := 0u64) ^ sd_max := 2u32,
    KZero = series_key("Z", "v", "", "", 0u64),
    absorb(DWel, KZero, float(1.0), at(0), init_series_state, ZR1),
    absorb(DRes, KZero, float(1.0), at(0), ZR1, ZR2),
    absorb(DWel, KZero, float(2.0), at(1000000000), ZR2, ZR3),
    absorb(DRes, KZero, float(2.0), at(1000000000), ZR3, ZR4),
    absorb(DWel, KZero, float(3.0), at(2000000000), ZR4, ZR5),
    absorb(DRes, KZero, float(3.0), at(2000000000), ZR5, ZR6),
    check("a running total and a reservoir at window 0 are two rows",
        ( if query(agg_count, KZero, at(2000000000), ZR6, cold_value(agg_count, no), int(3i64)),
             query(agg_percentile(50), KZero, at(2000000000), ZR6, null, float(_))
          then yes else no ), !T, !IO),

    % Sample vs population variance: over 20/30/40 the sample variance is 100.0
    % (divisor 2) and the population variance 66.67 (divisor 3). The two differ
    % only in a `-1`.
    check("variance is sample (n-1), pvariance is population (n)",
        ( if query(agg_variance, K, at(2000000000), S3, cold_value(agg_variance, no), float(Var)),
             Var = 100.0,
             query(agg_pvariance, K, at(2000000000), S3, cold_value(agg_pvariance, no), float(PVar)),
             PVar > 66.66, PVar < 66.67
          then yes else no ), !T, !IO),

    % One sample measures no dispersion: the sample variance and stdev are
    % `null` there, though the read is warm, and the population forms are +0
    % ([LSER.16.3.3]).
    check("one sample: var / stdev are null, pvar / pstdev are 0.0",
        ( if
            query(agg_variance, K, at(0), S1, cold_value(agg_variance, no), OneVar),
            OneVar = null,
            query(agg_stdev, K, at(0), S1, cold_value(agg_stdev, no), OneSd),
            OneSd = null,
            query(agg_pvariance, K, at(0), S1, cold_value(agg_pvariance, no), float(OnePVar)),
            OnePVar = 0.0,
            query(agg_pstdev, K, at(0), S1, cold_value(agg_pstdev, no), float(OnePSd)),
            OnePSd = 0.0
          then yes else no ), !T, !IO),

    % [RDSC.5a.1a]: a read changes nothing. The `in` mode makes that
    % unviolatable, so this checks the other half: repeated reads agree.
    query(agg_mean, K, at(2000000000), S3, cold_value(agg_mean, no), R1),
    query(agg_mean, K, at(2000000000), S3, cold_value(agg_mean, no), R2),
    query(agg_mean, K, at(2000000000), S3, cold_value(agg_mean, no), R3),
    check("N reads between two absorptions agree",
        ( if R1 = R2, R2 = R3 then yes else no ), !T, !IO),

    % Eviction is by the row's own window, at read time as well as at write
    % time: nothing is absorbed here, and the clock moves past the window. An
    % emptied window is the cold case, so [LSER.19.8] answers `null`.
    check("samples aged out of the window are gone from a later read",
        ( if query(agg_mean, K, at(20000000000), S3, cold_value(agg_mean, no), Aged),
             Aged = null
          then yes else no ), !T, !IO),

    % The boundary: a sample exactly `window_ns` old is out, [LSER.14.1]'s
    % half-open `(t - <dur>, t]`. At t = 11s with a 10s window, the samples at
    % 0s, 1s and 2s are 11s, 10s and 9s old, so the 1s sample is on the
    % boundary: 1 if it is exclusive, 2 if inclusive. At 12s all three are out
    % under either reading.
    check("a sample exactly window_ns old is OUT of the window",
        ( if query(agg_count, K, at(11000000000), S3, cold_value(agg_count, no), int(1i64)) then yes else no ),
        !T, !IO),

    % A second identity is a second row; `35_series_backings` drives this
    % against libds.
    K2 = series_key("S", "v", "id", "garage", 0u64),
    absorb(D, K2, float(100.0), at(2000000000), S3, S4),
    check("a second identity is a second row",
        ( if query(agg_mean, K, at(2000000000), S4, cold_value(agg_mean, no), float(30.0)),
             query(agg_mean, K2, at(2000000000), S4, cold_value(agg_mean, no), float(100.0))
          then yes else no ), !T, !IO),

    % `window_ns = 0` is unbounded, not an empty window:
    % `SeriesBackendWelfordEwma` and `SeriesBackendReservoir` carry zero
    % because their time model is all_time / sample-n.
    DAll = D ^ sd_window := 0u64,
    KAll = series_key("A", "v", "", "", 0u64),
    absorb(DAll, KAll, float(1.0), at(0), init_series_state, A1),
    absorb(DAll, KAll, float(3.0), at(999999999999), A1, A2),
    check("window_ns = 0 means unbounded, not empty",
        ( if query(agg_mean, KAll, at(999999999999), A2, cold_value(agg_mean, no), float(2.0))
          then yes else no ), !T, !IO),

    % [LSER.16.2], [LSER.16.9]: `sum`, `min`, `max`, `first` and `last`
    % return the slot's type; `mean` and the variances return `Float` whatever
    % they read. So an Int-element series answers `int(7i64)` and `float(3.5)`
    % from the same samples, one bag driving both. 3 + 4 = 7 is exact in
    % `double`, so the type is the whole of what this measures.
    DInt = ((D ^ sd_element := el_int) ^ sd_window := 0u64),
    KInt = series_key("I", "v", "", "", 0u64),
    absorb(DInt, KInt, int(3i64), at(0), init_series_state, I1),
    absorb(DInt, KInt, int(4i64), at(1000000000), I1, I2),
    check("sum / min / max over an Int series return Ints",
        ( if query(agg_sum, KInt, at(1000000000), I2, cold_value(agg_sum, no), int(7i64)),
             query(agg_min, KInt, at(1000000000), I2, cold_value(agg_min, no), int(3i64)),
             query(agg_max, KInt, at(1000000000), I2, cold_value(agg_max, no), int(4i64))
          then yes else no ), !T, !IO),
    % An unbounded `first` / `last` is SeriesBackendWelfordEwma's.
    DIntWel = DInt ^ sd_backing := bk_welford,
    absorb(DIntWel, KInt, int(3i64), at(0), I2, IW1),
    absorb(DIntWel, KInt, int(4i64), at(1000000000), IW1, IW2),
    check("first / last over an Int series return Ints",
        ( if query(agg_first, KInt, at(1000000000), IW2, cold_value(agg_first, no), int(3i64)),
             query(agg_last, KInt, at(1000000000), IW2, cold_value(agg_last, no), int(4i64))
          then yes else no ), !T, !IO),
    check("mean over an Int series still returns a Float",
        ( if query(agg_mean, KInt, at(1000000000), I2, cold_value(agg_mean, no), float(3.5))
          then yes else no ), !T, !IO),

    % A Float series is not narrowed by the same code. The two samples are
    % chosen so that a stray narrowing could not pass for right under either
    % rounding rule: 2.5 truncates to 2 and rounds to 3, and neither is 2.5.
    KF = series_key("F", "v", "", "", 0u64),
    absorb(DAll, KF, float(2.0), at(0), init_series_state, F1),
    absorb(DAll, KF, float(0.5), at(1000000000), F1, F2),
    check("sum over a Float series stays a Float",
        ( if query(agg_sum, KF, at(1000000000), F2, cold_value(agg_sum, no), float(2.5))
          then yes else no ), !T, !IO),

    % `max_samples` caps the in-memory count even inside the window.
    DCap = D ^ sd_max := 2u32,
    KCap = series_key("C", "v", "", "", 0u64),
    absorb(DCap, KCap, float(1.0), at(0), init_series_state, C1),
    absorb(DCap, KCap, float(2.0), at(1000000000), C1, C2),
    absorb(DCap, KCap, float(3.0), at(2000000000), C2, C3),
    check("max_samples caps the retained count",
        ( if query(agg_count, KCap, at(2000000000), C3, cold_value(agg_count, no), int(2i64)) then yes
          else no ), !T, !IO),

    % The decoder, against a real artefact carrying two layouts.
    % `SeriesBackendRingBuffer` puts `window_ns` at tag 5 and
    % `SeriesBackendMonotonicDeque` at tag 4, and both windows are 10 minutes
    % here -- so a decoder reading tag 4 for the ring buffer would report 1,
    % the `SERIES_ELEMENT_FLOAT` enum value, rather than failing.
    read_bitmap("fixtures/60_series_backings.dsc", Res, !IO),
    (
        Res = yes(BM),
        check("both series field layouts decode from one artefact",
            ( if load_dsc(BM, loaded(P)),
                 Ds = series_decls(P),
                 list.filter(is_backing(bk_ring_buffer), Ds, [RB, Meter]),
                 RB ^ sd_window = 600000000000u64,
                 RB ^ sd_element = el_float,
                 RB ^ sd_id_slot = "entity_id",
                 Meter ^ sd_window = 300000000000u64,
                 Meter ^ sd_id_slot = "",
                 list.filter(is_backing(bk_monotonic_deque), Ds, [MD]),
                 MD ^ sd_window = 600000000000u64,
                 MD ^ sd_element = el_unspecified
              then yes else no ), !T, !IO)
    ;
        Res = no,
        check("fixtures/60_series_backings.dsc is readable", no, !T, !IO)
    ).

:- pred is_backing(backing::in, series_decl::in) is semidet.

is_backing(B, D) :- D ^ sd_backing = B.

%-----------------------------------------------------------------------------%
% `implemented/1` must not outrun `ds.eval`
%-----------------------------------------------------------------------------%
%
% `ds.builtins.implemented/1` is what the loader consults to decide whether a
% bundle's tests are evaluable, so a builtin claimed there that
% `ds.eval.apply_builtin` has no arm for lets the loader accept an artefact the
% engine then declines. This drives every entry through `apply_builtin` with
% arguments of the right shape and asserts none faults `rf_unimplemented`.

%-----------------------------------------------------------------------------%
% `FN_REGEX_MATCH` -- `~` through RE2
%-----------------------------------------------------------------------------%
%
% [LREG.1.2]: a partial match, with [LREG.5.2]'s three flags, in RE2's own
% syntax ([LREG.8.1]). A null subject answers `null` ([LREG.1.3]).

:- pred test_regex_match(tally::in, tally::out, io::di, io::uo) is det.

test_regex_match(!T, !IO) :-
    intern("error: disk full", Lower, init_interns, IT0),
    intern("ERROR: disk full", Upper, IT0, IT1),
    intern("^error", Anchored, IT1, IT2),
    intern("i", ICase, IT2, IT3),
    intern("", NoFlags, IT3, IT4),
    intern("\\d+", Digits, IT4, IT5),
    intern("code 42", Coded, IT5, IT6),
    intern("full$", Tail, IT6, IT),
    Ctx = eval_ctx([], no, init_wm, map.init, IT, at(0), no, map.init, 0,
        init_cache, init_series_state),
    check("[LREG.1.2] a pattern that matches answers true",
        regex_yes(Ctx, Lower, Anchored, NoFlags), !T, !IO),
    check("[LREG.1.2] matching is partial: `full$` finds the tail",
        regex_yes(Ctx, Lower, Tail, NoFlags), !T, !IO),
    check("[LREG.5.2] case matters without `i`",
        regex_no(Ctx, Upper, Anchored, NoFlags), !T, !IO),
    check("[LREG.5.2] `i` folds case",
        regex_yes(Ctx, Upper, Anchored, ICase), !T, !IO),
    check("[LREG.8.1] `\\d` is RE2's digit class, not a literal `d`",
        regex_yes(Ctx, Coded, Digits, NoFlags), !T, !IO),
    check("[LREG.8.1] `\\d` does not match text with no digit",
        regex_no(Ctx, Lower, Digits, NoFlags), !T, !IO),
    eval(e_call(fn_regex_match, [e_lit(null), e_lit(str(Anchored)),
        e_lit(str(NoFlags))]), Ctx, NullOut),
    % [LNUL.4.1] with [LREG.1.3]: the match propagates a null subject, so
    % `!~`, its `not`, does not continue either.
    check("[LREG.1.3] a null subject answers null, not false and not a fault",
        ( if NullOut = ev_ok(null) then yes else no ), !T, !IO),
    test_regex_capture(!T, !IO),
    test_rdsc_4a_9_3_operands(!T, !IO),
    test_rlow_6_1_7_interval_check(!T, !IO).

    % [RLOW.6.1.7], [LINT.7.2]: the check yields `v`
    % when every pair is `s <= e` or has a `null` endpoint, `null` `v`
    % included; otherwise one fault, chosen by [LNUL.4.2]'s order among the
    % arguments' faults and a `DOMAIN` for each invalid pair, a complete tie
    % keeping the argument's. A `DOMAIN` names its pair's start ([LERR.9.12]).
    % libds's
    % `test_rete_builtins` `test_rlow_6_1_7__interval_check` asks the same
    % questions, with the same answers.
    %
    % @spec [RLOW.6.1.7]
    % @spec [LINT.7.2]
:- pred test_rlow_6_1_7_interval_check(tally::in, tally::out, io::di, io::uo)
    is det.

test_rlow_6_1_7_interval_check(!T, !IO) :-
    intern("a", A, init_interns, IT),
    Ctx = eval_ctx([], no, init_wm, map.init, IT, at(0), no, map.init, 0,
        init_cache, init_series_state),
    I = ( func(N) = e_lit(int(N)) ),
    Check = ( func(Args) = e_call(fn_interval_check, Args) ),
    Cases = [
        "valid (1, 2, true) is true" -
            Check([I(1i64), I(2i64), e_lit(bool(yes))]) - ev_ok(bool(yes)),
        "an empty interval is valid ([LINT.7.1])" -
            Check([I(5i64), I(5i64), e_lit(bool(no))]) - ev_ok(bool(no)),
        "a null endpoint is valid, and a null v is the answer" -
            Check([e_lit(null), I(3i64), e_lit(null)]) - ev_ok(null),
        "inverted (5, 3) is DOMAIN" -
            Check([I(5i64), I(3i64), e_lit(bool(no))]) - ev_fault(rf_domain),
        "a NaN start is DOMAIN: NaN <= 5.0 is false" -
            Check([e_lit(float(nan_f)), e_lit(float(5.0)), e_lit(bool(no))])
            - ev_fault(rf_domain),
        "a null v does not prevent the check ([LNUL.4.10])" -
            Check([I(5i64), I(3i64), e_lit(null)]) - ev_fault(rf_domain),
        "the second pair invalid is DOMAIN" -
            Check([I(1i64), I(2i64), I(5i64), I(3i64), e_lit(bool(no))])
            - ev_fault(rf_domain),
        "v's DIVIDE_BY_ZERO (TrapKind 1) beats a pair's DOMAIN (2)" -
            Check([I(5i64), I(3i64),
                e_binop(op_floordiv, I(1i64), I(0i64))])
            - ev_fault(rf_div_zero),
        "endpoints of two kinds: the artefact lied" -
            Check([I(1i64), e_lit(str(A)), e_lit(bool(yes))])
            - ev_fault(rf_artefact_lied),
        "a count that is not three or five ([RDSC.4a.9.3])" -
            Check([I(1i64), I(2i64), I(3i64), e_lit(bool(yes))])
            - ev_fault(rf_artefact_lied)
    ],
    list.filter((pred((_ - E - Want)::in) is semidet :-
            eval(E, Ctx, Out), Out \= Want),
        Cases, Wrong),
    report_offenders(list.map(( func(Name - _ - _) = Name ), Wrong), !IO),
    check("[RLOW.6.1.7] the interval check yields v or the fault LNUL.4.2 "
        ++ "selects", ( if Wrong = [] then yes else no ), !T, !IO),

    % The offending operand is the invalid pair's start. The first pair is
    % Float and the second Int, so `actual` says which start was named.
    Second = Check([e_lit(float(1.0)), e_lit(float(2.0)), I(5i64), I(3i64),
        e_lit(bool(no))]),
    check("[RLOW.6.1.7] a second pair's DOMAIN names the second start",
        ( if fault_origin(Second, Ctx, rf_domain) ^ fo_actual = yes("Int")
          then yes else no ), !T, !IO),
    % A complete tie keeps the argument's: v's own DOMAIN, a negative shift
    % count ([LEXP.7.14.1]), beside an invalid Float pair, neither naming a
    % slot or a fact, is one record ([LNUL.4.2]; a ComputationError's
    % `actual` is not a field it records). The one named is v's, at v's
    % site, whose first operand is the Int 1.
    Tie = Check([e_lit(float(5.0)), e_lit(float(3.0)),
        e_binop(op_shl, I(1i64), I(-1i64))]),
    eval(Tie, Ctx, TieOut),
    check("[RLOW.6.1.7] v's DOMAIN beside a pair's is v's",
        ( if
            TieOut = ev_fault(rf_domain),
            fault_origin(Tie, Ctx, rf_domain) ^ fo_actual = yes("Int")
          then yes else no ), !T, !IO).

    % [RDSC.4a.9.3]: a call whose operands its op
    % does not admit is ARTEFACT_LIED; every row's counts are
    % `test_rdsc_4a_9_5_every_row`'s. What no row states is asked here: an
    % absorbing `and` still absorbs the fault, a verb at an action's top
    % performs nothing, and a `publish` is judged against its schema's slots
    % (`test_rdsc_4a_9_3_verbs`).
    %
    % @spec [RDSC.4a.9.3]
:- pred test_rdsc_4a_9_3_operands(tally::in, tally::out, io::di, io::uo)
    is det.

test_rdsc_4a_9_3_operands(!T, !IO) :-
    Ctx = eval_ctx([], no, init_wm, map.init, init_interns, at(0), no,
        map.init, 0, init_cache, init_series_state),
    test_rdsc_4a_9_5_every_row(Ctx, !T, !IO),
    % An absorbing `and` still absorbs it ([IRET.9.6], [LERR.1.4.11]).
    eval(e_binop(op_and, e_lit(bool(no)), e_call(fn_abs, [])), Ctx, AndOut),
    check("[RDSC.4a.9.3] `false and <short call>` is false, and nothing is " ++
        "raised",
        ( if AndOut = ev_ok(bool(no)) then yes else no ), !T, !IO),
    test_rdsc_4a_9_3_verbs(!T, !IO),
    test_string_conversion_kinds(Ctx, !T, !IO).

    % [RDSC.4a.9.5], every row: a call one operand short of its row's
    % `Min`, one past its `Max`, or at a `pairs` row's `Min` + 1 is
    % ARTEFACT_LIED. [RDSC.4a.9.3]: "When a call reaches evaluation with fewer
    % operands than its op takes, with more than an op of fixed count takes, or
    % in a shape its op does not admit, the engine must raise an `EngineError`
    % whose fault is `ENGINE_FAULT_ARTEFACT_LIED`." No source reaches it, since
    % the compiler emits the count each op admits, so these are hand-built
    % calls, evaluated as `ds.eval` evaluates any call: the interval check
    % through its own arm, and every other op through `ev_node`'s count. The
    % verbs' site (`ds.dsc_action.verb`) and the rate gate's (`ds.exec.rhs_gate`)
    % ask the same `rdsc_4a_9_5_admits`.
    %
    % The rows are every constructor's, enumerated through the wire table and
    % held to `builtin_count`, not a sample. Every operand is a `null` literal,
    % which evaluates without a fault, so the count is the only thing wrong. A
    % `rdsc_none` row has no count to step past. libds's
    % `test_rdsc_4a_9_5_operands` asks the same of every row of its generated
    % `ds_fn_operands`, with the same answers.
    %
    % The reader is asked the other side too: each row admits its `Min`, its
    % `Max` where it has one, and a `pairs` row its `Min` + 2 below the `Max`.
    %
    % @spec [RDSC.4a.9.5]
:- pred test_rdsc_4a_9_5_every_row(eval_ctx::in, tally::in, tally::out,
    io::di, io::uo) is det.

test_rdsc_4a_9_5_every_row(Ctx, !T, !IO) :-
    Fns = list.filter_map(
        ( func(N) = Fn is semidet :- builtin_fn(uint32.cast_from_int(N), Fn) ),
        0 .. 2047),
    check("[RDSC.4a.9.5] every constructor is asked",
        ( if list.length(Fns) = builtin_count then yes else no ), !T, !IO),
    Cases = list.condense(list.map(rdsc_4a_9_5_not_admitted, Fns)),
    list.filter((pred((_ - E)::in) is semidet :-
            eval(E, Ctx, Out), Out \= ev_fault(rf_artefact_lied)),
        Cases, Wrong),
    report_offenders(assoc_list.keys(Wrong), !IO),
    check("[RDSC.4a.9.5] a call past its row's counts is ARTEFACT_LIED, " ++
        "every row",
        ( if Cases = [_ | _], Wrong = [] then yes else no ), !T, !IO),
    list.filter((pred(Fn::in) is semidet :-
            not rdsc_4a_9_5_admits_its_counts(Fn)),
        Fns, Unread),
    report_offenders(list.map((func(F) = string.string(F)), Unread), !IO),
    check("[RDSC.4a.9.5] every row admits the counts it states",
        ( if Unread = [] then yes else no ), !T, !IO).

    % The calls `Fn`'s row does not admit: `Min` - 1 where `Min` > 0, `Max` + 1
    % where it has a `Max`, and `Min` + 1 for a `pairs` row.
    %
:- func rdsc_4a_9_5_not_admitted(builtin_fn) = assoc_list(string, expr).

rdsc_4a_9_5_not_admitted(Fn) = Cases :-
    Row = rdsc_4a_9_5_operands(Fn),
    (
        Row = rdsc_none,
        Counts = []
    ;
        Row = rdsc_range(Min, Max),
        Counts = rdsc_4a_9_5_short(Min) ++ rdsc_4a_9_5_long(Max)
    ;
        Row = rdsc_pairs(Min, Max),
        Counts = rdsc_4a_9_5_short(Min) ++ rdsc_4a_9_5_long(Max) ++ [Min + 1]
    ),
    Cases = list.map(
        ( func(N) = (string.format("%s with %d operands",
                [s(string.string(Fn)), i(N)])
            - e_call(Fn, list.duplicate(N, e_lit(null)))) ),
        Counts).

:- func rdsc_4a_9_5_short(int) = list(int).

rdsc_4a_9_5_short(Min) = ( if Min > 0 then [Min - 1] else [] ).

:- func rdsc_4a_9_5_long(rdsc_4a_9_5_max) = list(int).

rdsc_4a_9_5_long(rdsc_at_most(Max)) = [Max + 1].
rdsc_4a_9_5_long(rdsc_no_max) = [].

    % Whether `Fn`'s row admits the counts it states, and a `rdsc_none` row
    % none.
    %
:- pred rdsc_4a_9_5_admits_its_counts(builtin_fn::in) is semidet.

rdsc_4a_9_5_admits_its_counts(Fn) :-
    Row = rdsc_4a_9_5_operands(Fn),
    (
        Row = rdsc_none,
        not rdsc_4a_9_5_admits(Fn, 0),
        not rdsc_4a_9_5_admits(Fn, 1)
    ;
        Row = rdsc_range(Min, Max),
        rdsc_4a_9_5_admits(Fn, Min),
        rdsc_4a_9_5_admits(Fn, rdsc_4a_9_5_top(Min, Max))
    ;
        Row = rdsc_pairs(Min, Max),
        rdsc_4a_9_5_admits(Fn, Min),
        ( if
            Max = rdsc_at_most(Top),
            Top < Min + 2
        then
            true
        else
            rdsc_4a_9_5_admits(Fn, Min + 2)
        )
    ).

    % The most a row admits, or for no `Max` a count well past its `Min`.
    %
:- func rdsc_4a_9_5_top(int, rdsc_4a_9_5_max) = int.

rdsc_4a_9_5_top(_, rdsc_at_most(Max)) = Max.
rdsc_4a_9_5_top(Min, rdsc_no_max) = Min + 64.

    % [IRET.9.6]: a `String ::` conversion handed a present value that is not
    % a String is an ill-typed operation, a mismatch `classified/2` splits on
    % provenance (these literals are untainted, so ARTEFACT_LIED), not `null`,
    % which only a string the conversion does not accept answers. libds's
    % `test_rete_builtins` `test_iret_9_6__string_conversion_of_a_non_string`
    % asks the same.
    %
    % @spec [IRET.9.6]
:- pred test_string_conversion_kinds(eval_ctx::in, tally::in, tally::out,
    io::di, io::uo) is det.

test_string_conversion_kinds(Ctx, !T, !IO) :-
    Mismatched = [
        "string_to_int(1)" - e_call(fn_string_to_int, [e_lit(int(1i64))]),
        "string_to_float(true)" - e_call(fn_string_to_float,
            [e_lit(bool(yes))]),
        "string_to_bool(1.0)" - e_call(fn_string_to_bool, [e_lit(float(1.0))])
    ],
    list.filter((pred((_ - E)::in) is semidet :-
            eval(E, Ctx, Out), Out \= ev_fault(rf_artefact_lied)),
        Mismatched, Wrong),
    report_offenders(assoc_list.keys(Wrong), !IO),
    check("[IRET.9.6] a String conversion of a non-String is a mismatch",
        ( if Wrong = [] then yes else no ), !T, !IO),
    eval(e_call(fn_string_to_int, [e_lit(text("x"))]), Ctx, XOut),
    check("[LCST.4.5.7] and a string it does not accept is null",
        ( if XOut = ev_ok(null) then yes else no ), !T, !IO).

    % [RDSC.4a.9.3] at an action's top: a verb, a
    % mechanism or a per-call rate gate whose operands its op does not admit
    % is the EngineError ARTEFACT_LIED, and nothing is performed. Fired
    % through `ds.exec.fire`, on `07_action_verbs`'s activation, with hand-built
    % actions: no source reaches them. A `publish` whose values do not match
    % its schema's slots is found by `resolve_action`, which holds the schema.
    % libds's `test_rete_builtins` `test_rdsc_4a_9_3__what_no_row_states` asks
    % the same of `publish`, and `test_rdsc_4a_9_5_operands` every row's count
    % of its adapters.
    %
    % @spec [RDSC.4a.9.3]
:- pred test_rdsc_4a_9_3_verbs(tally::in, tally::out, io::di, io::uo) is det.

test_rdsc_4a_9_3_verbs(!T, !IO) :-
    with_fixture("07_action_verbs.dsc", check_rdsc_4a_9_3_verbs, !T, !IO).

    % [RDSC.4a.9.6], [NFCT.1.4.6]: a slot's conversion has a frame of one
    % slot. One that reads `bind_ref` 1 raises an EngineError, which the
    % host's conversion raises as any public call does: one `EngineError`
    % ARTEFACT_LIED, naming no node and the `$engine` rule, then the halt.
    % A ComputationError stays NOT_REPRESENTABLE and changes nothing. libds's
    % `test_rdsc_4a_9_6__a_conversion_bind_index_past_0` asks the same.
    %
    % @spec [RDSC.4a.9.6]
    % @spec [NFCT.1.4.6]
:- pred test_rdsc_4a_9_6_conversion(tally::in, tally::out, io::di, io::uo)
    is det.

test_rdsc_4a_9_6_conversion(!T, !IO) :-
    with_fixture("07_action_verbs.dsc", check_rdsc_4a_9_6_conversion, !T,
        !IO).

:- pred check_rdsc_4a_9_6_conversion(program::in, tally::in, tally::out,
                                     io::di, io::uo) is det.

check_rdsc_4a_9_6_conversion(P, !T, !IO) :-
    ( if find_schema(schemas(P), interns(P), "Trig", Trig) then
        E0 = init_engine(P),
        In = bind_index_of(0u32),
        Past = bind_index_of(1u32),
        Through = ( pred(To::in, Out::out, Effects::out, E::out) is det :-
            nfct_1_4_6_convert(with_unit(To, Trig), 0, ud_to_stored,
                int(5i64), Out, Effects, E0, E)
        ),
        Through(e_bind_ref(In), InOut, InEffects, InE),
        check("[RDSC.4a.9.6] a conversion reads its one slot",
            ( if InOut = uo_ok(int(5i64)), InEffects = [],
                 engine_halted(InE) = no
              then yes else no ), !T, !IO),
        Through(e_bind_ref(Past), PastOut, PastEffects, PastE),
        list.filter(
            ( pred(Ef::in) is semidet :-
                Ef = eff_event(se_engine_error(_, _)) ),
            PastEffects, PastErrors),
        check("[NFCT.1.4.6] a conversion reading bind_ref 1 halts the " ++
            "engine with one EngineError ARTEFACT_LIED at $engine",
            ( if
                PastOut = uo_halted,
                PastErrors = [eff_event(se_engine_error(
                    ee_expr_fault(rf_artefact_lied), Site))],
                Site ^ fs_node = no,
                Site ^ fs_rule = fr_engine,
                engine_halted(PastE) = yes(ee_expr_fault(rf_artefact_lied))
              then yes else no ), !T, !IO),
        Through(e_binop(op_floordiv, e_bind_ref(In), e_lit(int(0i64))),
            ZeroOut, ZeroEffects, ZeroE),
        check("[NFCT.1.4.6] a ComputationError is NOT_REPRESENTABLE, " ++
            "and nothing is reported or halted",
            ( if ZeroOut = uo_not_representable, ZeroEffects = [],
                 engine_halted(ZeroE) = no
              then yes else no ), !T, !IO)
    else
        check("07_action_verbs has a Trig schema", no, !T, !IO)
    ).

    % The schema with its first slot's conversion to stored `To`, and the
    % identity back.
    %
:- func with_unit(expr, schema) = schema.

with_unit(To, S) = S ^ s_lifecycle := Lifecycle :-
    Units = yes(unit_conversion(To, e_bind_ref(bind_index_of(0u32)))),
    Common = ( func(C) = C ^ sc_units := Units ),
    L0 = S ^ s_lifecycle,
    (
        L0 = lc_logical(Slots, Ambient),
        Lifecycle = lc_logical(first_slot(
            ( func(Sl) = Sl ^ ls_common := Common(Sl ^ ls_common) ), Slots),
            Ambient)
    ;
        L0 = lc_ttl(Slots, TTL),
        Lifecycle = lc_ttl(first_slot(
            ( func(Sl) = Sl ^ ps_common := Common(Sl ^ ps_common) ), Slots),
            TTL)
    ;
        L0 = lc_explicit(Slots),
        Lifecycle = lc_explicit(first_slot(
            ( func(Sl) = Sl ^ ps_common := Common(Sl ^ ps_common) ), Slots))
    ;
        L0 = lc_activation(Slots),
        Lifecycle = lc_activation(first_slot(
            ( func(Sl) = Sl ^ ps_common := Common(Sl ^ ps_common) ), Slots))
    ).

:- func first_slot(func(T) = T, list(T)) = list(T).

first_slot(_, []) = [].
first_slot(F, [X | Xs]) = [F(X) | Xs].

    % The bind frame of a program's one terminal: its `bind_count`
    % ([RDSC.4a.9.6]).
    %
:- func only_frame(program) = int.

only_frame(P) =
    ( if terminal_nodes(network(P)) = [T] then T ^ tn_binds else 0 ).

:- pred check_rdsc_4a_9_3_verbs(program::in, tally::in, tally::out,
                                io::di, io::uo) is det.

check_rdsc_4a_9_3_verbs(P, !T, !IO) :-
    Schemas = schemas(P),
    intern("svc.op", Svc, interns(P), IT1),
    intern("c1", Corr, IT1, IT2),
    intern("k", K, IT2, IT3),
    intern("r#call0", Tracker, IT3, IT),
    ( if
        find_schema(Schemas, IT, "Trig", Trig),
        rule_metas(P) = [Meta]
    then
        SchemaMap = schema_map(Schemas),
        Index = build_index(network(P), Schemas),
        assert_fact(Trig, [int(1i64)], at(1000), no, tms_none, live, R,
            init_wm, W1),
        ( if R = inserted(F) then FactId = F else FactId = fid(0) ),
        MatchCtx = match_ctx(W1, SchemaMap, IT, at(1000), no, init_cache,
            init_series_state),
        fact_asserted(Index, MatchCtx, FactId, Delta, init_rete, _),
        ( if Delta ^ md_added = [Activation] then
            ExecCtx = exec_ctx(SchemaMap, at(1000), no, Meta, no,
                no_cache_caps, default_hydration_budget, [], [],
                map.init, only_frame(P)),
            State0 = exec_state(W1, init_tms, init_cache, init_series_state,
                init_rate_table, bool.no, IT, 0, [], [], map.init),
            Cases = [
                "short log" - a_operands_not_admitted(fn_log,
                    [e_lit(int(1i64)), e_lit(str(K))], no),
                "short call" - a_operands_not_admitted(fn_call,
                    [e_lit(str(Svc))], no),
                "odd-pair call" - a_operands_not_admitted(fn_call,
                    [e_lit(str(Svc)), e_lit(str(Corr)), e_lit(str(K))], no),
                "short publish" - a_operands_not_admitted(fn_publish, [], no),
                "short cache_set" - a_operands_not_admitted(fn_cache_set,
                    [e_lit(str(K)), e_lit(str(K))], no),
                "short cache_delete" - a_operands_not_admitted(fn_cache_delete,
                    [], no),
                "short retract_token_fact" - a_operands_not_admitted(
                    fn_retract_token_fact, [], no),
                "short retract_corr" - a_operands_not_admitted(fn_retract_corr,
                    [e_lit(str(K)), e_lit(str(K))], no),
                "a call under a short rate gate" - a_call(Svc, correlated(Corr),
                    make_kwargs([]), yes([e_lit(str(Tracker))]))
            ],
            list.filter((pred((_ - Action)::in) is semidet :-
                    fire(ExecCtx, Activation, [Action], no_settle, Effects,
                        State0, _, unit, _),
                    not lied_and_nothing_done(Effects)),
                Cases, Wrong),
            report_offenders(assoc_list.keys(Wrong), !IO),
            check("[RDSC.4a.9.3] a verb, a mechanism or a per-call gate " ++
                "whose operands its op does not admit is ARTEFACT_LIED, " ++
                "and nothing is performed",
                ( if Wrong = [] then yes else no ), !T, !IO),
            % A `publish` of `Trig` with no value for its one slot resolves to
            % the same action rather than being refused at load.
            ( if
                resolve_action(ia_publish(schema_name_ref(Trig ^ s_name), [],
                    no), Schemas, IT, Resolved),
                Resolved = ra_ok(a_operands_not_admitted(fn_publish, _, no))
            then
                PublishOk = yes
            else
                PublishOk = no
            ),
            check("[RDSC.4a.9.3] a publish with fewer values than its " ++
                "schema's slots loads, as ARTEFACT_LIED to come",
                PublishOk, !T, !IO),
            % And with more. libds's `test_rete_builtins` asks the same of its
            % adapter.
            ( if
                resolve_action(ia_publish(schema_name_ref(Trig ^ s_name),
                    [e_lit(int(1i64)), e_lit(int(2i64))], no),
                    Schemas, IT, Surplus),
                Surplus = ra_ok(a_operands_not_admitted(fn_publish, _, no))
            then
                SurplusOk = yes
            else
                SurplusOk = no
            ),
            check("[RDSC.4a.9.3] a publish with more values than its " ++
                "schema's slots loads, as ARTEFACT_LIED to come",
                SurplusOk, !T, !IO)
        else
            check("07_action_verbs yields one activation", no, !T, !IO)
        )
    else
        check("07_action_verbs declares Trig and one rule", no, !T, !IO)
    ).

    % An `EngineError` ARTEFACT_LIED among the effects, and no action
    % performed.
    %
:- pred lied_and_nothing_done(list(effect)::in) is semidet.

lied_and_nothing_done(Effects) :-
    list.member(Lied, Effects),
    Lied = eff_event(se_engine_error(ee_expr_fault(rf_artefact_lied), _)),
    not (
        list.member(Done, Effects),
        Done = eff_action(_)
    ).

    % The builtins a check found wrong, on the line before its verdict.
    %
:- pred report_offenders(list(string)::in, io::di, io::uo) is det.

report_offenders(Names, !IO) :-
    (
        Names = []
    ;
        Names = [_ | _],
        io.format("    wrong for: %s\n", [s(string.join_list(", ", Names))],
            !IO)
    ).

    % `FN_REGEX_CAPTURE` -- [LREG.4.1]'s capture read, answering as libds's
    % `builtin_regex_capture`: the group's text, `""` for a group that did not
    % participate, ARTEFACT for no match or a group past the pattern's count,
    % and a type mismatch for a null subject.
    %
:- pred test_regex_capture(tally::in, tally::out, io::di, io::uo) is det.

test_regex_capture(!T, !IO) :-
    intern("pump on 42", Subject, init_interns, IT0),
    intern("(\\w+) on (\\d+)", TwoGroups, IT0, IT1),
    intern("", NoFlags, IT1, IT2),
    intern("(a)|(b)", Either, IT2, IT3),
    intern("b", JustB, IT3, IT4),
    intern("nothing here", NoMatch, IT4, IT),
    Ctx = eval_ctx([], no, init_wm, map.init, IT, at(0), no, map.init, 0,
        init_cache, init_series_state),
    check("[LREG.4.1] group 1 is the first capture's text",
        ( if capture_out(Ctx, e_lit(str(Subject)), TwoGroups, NoFlags, 1i64)
            = ev_ok(text("pump")) then yes else no ), !T, !IO),
    check("[LREG.4.1] group 2 is the second's",
        ( if capture_out(Ctx, e_lit(str(Subject)), TwoGroups, NoFlags, 2i64)
            = ev_ok(text("42")) then yes else no ), !T, !IO),
    check("a group that did not participate is the empty string",
        ( if capture_out(Ctx, e_lit(str(JustB)), Either, NoFlags, 1i64)
            = ev_ok(text("")) then yes else no ), !T, !IO),
    check("no match is the artefact disagreeing with its own gate",
        ( if capture_out(Ctx, e_lit(str(NoMatch)), TwoGroups, NoFlags, 1i64)
            = ev_fault(rf_artefact_lied) then yes else no ), !T, !IO),
    check("a group past the pattern's count is ARTEFACT, not empty",
        ( if capture_out(Ctx, e_lit(str(Subject)), TwoGroups, NoFlags, 3i64)
            = ev_fault(rf_artefact_lied) then yes else no ), !T, !IO),
    check("a null subject is a TypeError, as libds's ARG_STR guard has it",
        ( if capture_out(Ctx, e_lit(null), TwoGroups, NoFlags, 1i64)
            = ev_fault(rf_type_error) then yes else no ), !T, !IO).

:- func capture_out(eval_ctx, expr, intern_ref, intern_ref, int64)
    = eval_outcome.

capture_out(Ctx, SubjectE, P, F, G) = Out :-
    eval(e_call(fn_regex_capture, [SubjectE, e_lit(str(P)), e_lit(str(F)),
        e_lit(int(G))]), Ctx, Out).

:- func regex_yes(eval_ctx, intern_ref, intern_ref, intern_ref) = bool.

regex_yes(Ctx, S, P, F) =
    ( if regex_out(Ctx, S, P, F) = ev_ok(bool(yes)) then yes else no ).

:- func regex_no(eval_ctx, intern_ref, intern_ref, intern_ref) = bool.

regex_no(Ctx, S, P, F) =
    ( if regex_out(Ctx, S, P, F) = ev_ok(bool(no)) then yes else no ).

:- func regex_out(eval_ctx, intern_ref, intern_ref, intern_ref) = eval_outcome.

regex_out(Ctx, S, P, F) = Out :-
    eval(e_call(fn_regex_match, [e_lit(str(S)), e_lit(str(P)), e_lit(str(F))]),
        Ctx, Out).

:- pred test_implemented_matches_eval(tally::in, tally::out,
                                      io::di, io::uo) is det.

test_implemented_matches_eval(!T, !IO) :-
    solutions(implemented_fn, Fns),
    list.filter(eval_declines, Fns, Declined),
    check("every builtin `implemented/1` claims is one ds.eval can evaluate",
        ( if Declined = [] then yes else no ), !T, !IO),
    (
        Declined = [_ | _],
        io.format("  note: claimed but unevaluable = %s\n",
            [s(string.string(Declined))], !IO)
    ;
        Declined = []
    ),

    % The other half: the list is not empty and is not the whole enum, whose
    % size is `builtin_count`.
    check("the implemented set is a proper, non-empty subset of the builtins",
        ( if implemented_count > 0, implemented_count < builtin_count
          then yes else no ),
        !T, !IO),

    % A spot check in the other direction. FN_BIT_AND is the op
    % `op_rewritten` writes into a fixture's call, and stays unclaimed for
    % that test: `&` lowers to a `BinOp`, so no `CallExpr` the compiler writes
    % names it.
    check("`bit_and` is not claimed -- op_rewritten depends on it",
        ( if implemented(fn_bit_and) then no else yes ), !T, !IO),

    % The executor's set is disjoint from the evaluator's:
    % `exec_implemented/1` is for builtins `apply_builtin` does not handle.
    solutions(implemented_fn, All),
    list.filter(exec_implemented, All, Both),
    check("no builtin is claimed by both the evaluator and the executor",
        ( if Both = [] then yes else no ), !T, !IO),

    % `gensym` is the one the executor answers, not `implemented/1`:
    % `ds.exec`'s `a_bind` arm intercepts it. The loader needs the claim for an
    % `after` carrying a captured binding ([LTAC.3.5], `95_after_capture`).
    check("`gensym` is answered by the executor, not the evaluator",
        ( if exec_implemented(fn_gensym), not implemented(fn_gensym)
          then yes else no ), !T, !IO).

    % True when evaluating this builtin faults `rf_unimplemented` given
    % arguments of the right shape, i.e. when the claim is false. A wrong
    % arity falls to the same `else` an unimplemented builtin does, and a
    % type mismatch is an answer of its own, so each family gets arguments
    % its arm accepts. A series read answers its cold zero here: the probe
    % context has no series state.
    %
:- pred eval_declines(builtin_fn::in) is semidet.

eval_declines(Fn) :-
    eval(e_call(Fn, probe_args(Fn)), probe_ctx, ev_fault(rf_unimplemented)).

:- func probe_args(builtin_fn) = list(expr).

probe_args(Fn) = Args :-
    ( if ( Fn = fn_now ; Fn = fn_monotonic_ns ) then
        % The two nullary clock reads ([LTIM.2.8]).
        Args = []
    else if series_fn(Fn) then
        probe_interns(IT),
        ( if
            interned(IT, "S", S), interned(IT, "v", V), interned(IT, "", E)
        then
            Args = [e_lit(str(S)), e_lit(str(V)), e_lit(str(E)),
                    e_lit(str(E)), e_lit(int(0i64))] ++
                ( if Fn = fn_series_percentile then [e_lit(int(50i64))]
                  else if ( Fn = fn_series_count_of ; Fn = fn_series_contains )
                  then [e_lit(str(V))]
                  else [] )
        else
            Args = []
        )
    else if cast_fn(Fn) then
        ( if Fn = fn_float_to_int then
            Args = [e_lit(float(1.5))]
        else if Fn = fn_int_to_float then
            Args = [e_lit(int(1i64))]
        else
            probe_interns(IT2),
            ( if interned(IT2, "S", S2) then
                Args = [e_lit(str(S2))]
            else
                Args = []
            )
        )
    else if ( Fn = fn_euclidean_2d ; Fn = fn_manhattan_2d
            ; Fn = fn_chebyshev_2d ; Fn = fn_cosine_2d ) then
        Args = [e_lit(int(0i64)), e_lit(int(0i64)), e_lit(int(3i64)), e_lit(int(4i64))]
    else if ( Fn = fn_euclidean_3d ; Fn = fn_manhattan_3d
            ; Fn = fn_chebyshev_3d ; Fn = fn_cosine_3d ) then
        Args = [e_lit(int(0i64)), e_lit(int(0i64)), e_lit(int(0i64)),
                e_lit(int(1i64)), e_lit(int(2i64)), e_lit(int(2i64))]
    else if Fn = fn_hypotenuse_2d then
        Args = [e_lit(int(3i64)), e_lit(int(4i64))]
    else if Fn = fn_hypotenuse_3d then
        Args = [e_lit(int(1i64)), e_lit(int(2i64)), e_lit(int(2i64))]
    else if ( Fn = fn_degrees ; Fn = fn_radians ) then
        Args = [e_lit(int(180i64))]
    else if Fn = fn_great_circle then
        % In range, so the composition runs.
        Args = [e_lit(int(0i64)), e_lit(int(0i64)), e_lit(int(10i64)),
                e_lit(int(20i64))]
    else if Fn = fn_utc then
        Args = [e_lit(int(0i64))]
    else if Fn = fn_calendar_time then
        % A real instant ([LTIM.14.1]).
        Args = list.map((func(I) = e_lit(int(I))),
            [2024i64, 2i64, 29i64, 12i64, 0i64, 0i64, 0i64])
    else if Fn = fn_calendar_date then
        Args = [e_lit(int(2024i64)), e_lit(int(2i64)), e_lit(int(29i64))]
    else if ( Fn = fn_duration_add ; Fn = fn_duration_mul ) then
        Args = [e_lit(int(2i64)), e_lit(int(3i64))]
    else if Fn = fn_int_mul_add_checked then
        % `x`, `m` and `a`, in range, so the answer is `m·x + a`.
        Args = [e_lit(int(2i64)), e_lit(int(3i64)), e_lit(int(4i64))]
    else if Fn = fn_duration_to_string then
        Args = [e_lit(int(5400000000000i64))]
    else if ( Fn = fn_local ; Fn = fn_time_date ) then
        % The probe context has no zone resolver, so the arm answers
        % `rf_artefact_lied`.
        Args = [e_lit(int(0i64)), e_lit(text("UTC"))]
    else if Fn = fn_str_length then
        Args = [e_lit(text("hello"))]
    else if Fn = fn_interval_check then
        % A valid pair and `v` ([RLOW.6.1.7]), so the check answers `v`.
        Args = [e_lit(int(1i64)), e_lit(int(2i64)), e_lit(bool(yes))]
    else if ( Fn = fn_json_has ; Fn = fn_json_len ) then
        % The array at `a` gives `len` a real answer rather than a fault.
        Args = [e_lit(json(j_object(object(["a" - j_array([j_int(1i64)])])))),
                e_lit(text("a"))]
    else if Fn = fn_cache_get then
        % The probe context's cache is empty, so this answers `null`.
        probe_interns(ITC),
        ( if interned(ITC, "S", SC) then
            Args = [e_lit(str(SC))]
        else
            Args = []
        )
    else if Fn = fn_currency_round_to then
        % The amount, the scale and the mode ([LUNI.13.5]).
        Args = [e_lit(int(250i64)), e_lit(int(2i64)), e_lit(int(1i64))]
    else if Fn = fn_currency_convert then
        % The probe context holds no rate schema, so the rate is 1/1 and the
        % amount comes back.
        Args = [e_lit(int(250i64)), e_lit(text("USD/EUR")), e_lit(text("Rate")),
                e_lit(text("num")), e_lit(text("den"))]
    else if Fn = fn_regex_match then
        probe_interns(ITR),
        ( if interned(ITR, "S", SR), interned(ITR, "", ER) then
            Args = [e_lit(str(SR)), e_lit(str(SR)), e_lit(str(ER))]
        else
            Args = []
        )
    else if Fn = fn_regex_capture then
        % The pattern has one group, so group 1 captures `S`.
        probe_interns(ITQ),
        ( if interned(ITQ, "S", SQ), interned(ITQ, "", EQ) then
            Args = [e_lit(str(SQ)), e_lit(text("(S)")), e_lit(str(EQ)),
                    e_lit(int(1i64))]
        else
            Args = []
        )
    else if Fn = fn_float_to_string then
        Args = [e_lit(float(1.5))]
    else if Fn = fn_int_to_string then
        Args = [e_lit(int(-7i64))]
    else if Fn = fn_bool_to_string then
        Args = [e_lit(bool(yes))]
    else if Fn = fn_to_string then
        % The one-argument form.
        Args = [e_lit(int(0i64))]
    else if Fn = fn_currency_convert then
        Args = [e_lit(int(1234i64)), e_lit(text("P")), e_lit(text("FxRate")),
                e_lit(text("rate_num")), e_lit(text("rate_den"))]
    else if Fn = fn_currency_round_to then
        Args = [e_lit(int(250i64)), e_lit(int(100i64)), e_lit(int(0i64))]
    else if Fn = fn_fma then
        Args = [e_lit(float(2.0)), e_lit(float(3.0)), e_lit(float(1.0))]
    else if Fn = fn_bits then
        % Inside [LEXP.3.7.3]'s domain, so the answer is a value.
        Args = [e_lit(int(43981i64)), e_lit(int(4i64)), e_lit(int(8i64))]
    else if ( Fn = fn_sign_extend ; Fn = fn_swap_bytes ) then
        % 16 is in both members' domains.
        Args = [e_lit(int(4660i64)), e_lit(int(16i64))]
    else if ( Fn = fn_abs ; Fn = fn_floor ; Fn = fn_ceil ; Fn = fn_trunc
            ; Fn = fn_round ; Fn = fn_sign ; Fn = fn_sqrt
            ; Fn = fn_bit_count ; Fn = fn_bit_length
            ; Fn = fn_leading_zeros ; Fn = fn_trailing_zeros
            ; Fn = fn_exp ; Fn = fn_ln ; Fn = fn_log2 ; Fn = fn_log10
            ; Fn = fn_sin ; Fn = fn_cos ; Fn = fn_tan ; Fn = fn_asin
            ; Fn = fn_acos ; Fn = fn_atan ; Fn = fn_sinh ; Fn = fn_cosh
            ; Fn = fn_tanh ) then
        Args = [e_lit(int(1i64))]
    else
        Args = [e_lit(int(1i64)), e_lit(int(2i64))]
    ).

    % Named positively, so a builtin added later is not a series read by
    % default.
    %
:- pred series_fn(builtin_fn::in) is semidet.

series_fn(Fn) :- series_builtin(Fn).

:- pred cast_fn(builtin_fn::in) is semidet.

cast_fn(fn_float_to_int).
cast_fn(fn_int_to_float).
cast_fn(fn_string_to_int).
cast_fn(fn_string_to_float).
cast_fn(fn_string_to_bool).

    % The strings a series read's key names, which `series_key_of` expands.
    %
:- pred probe_interns(intern_table::out) is det.

probe_interns(IT) :-
    intern("S", _, init_interns, IT0),
    intern("v", _, IT0, IT1),
    intern("", _, IT1, IT).

:- func probe_ctx = eval_ctx.

probe_ctx = Ctx :-
    probe_interns(IT),
    Ctx = eval_ctx([], no, init_wm, map.init, IT, at(0), no, map.init, 0,
        init_cache, init_series_state).

    % The reservoir's retention, pinned as a golden sequence: a fixed-seed
    % `xorshift64` seeded `0x9e3779b97f4a7c15`, advanced only in the
    % replacement phase, so conforming runtimes retain the same samples from
    % the same stream. Six powers of ten into a 3-deep bag: every 3-subset has
    % a distinct sum under 10^6, so the sum names the survivors exactly.
    %
:- pred test_reservoir(tally::in, tally::out, io::di, io::uo) is det.

test_reservoir(!T, !IO) :-
    D = series_decl(bk_reservoir, "S", "v", "", el_float,
        0u64, 0u64, 3u32, tm_unspecified, gp_unspecified, np_unspecified),
    K = series_key("S", "v", "", "", 0u64),
    list.foldl2(absorb_at(D, K), [1.0, 10.0, 100.0, 1000.0, 10000.0, 100000.0],
        0, _, init_series_state, S),

    query(agg_count, K, at(0), S, cold_value(agg_count, no), Count),
    check("the bag holds exactly k samples after 6 absorptions",
        ( if Count = int(3i64) then yes else no ), !T, !IO),

    % The fill phase draws nothing, so the first three are kept as they
    % arrive.
    list.foldl2(absorb_at(D, K), [1.0, 10.0, 100.0], 0, _,
        init_series_state, Filled),
    check("the fill phase keeps the first k verbatim",
        ( if query(agg_sum, K, at(0), Filled, cold_value(agg_sum, no), float(111.0)) then yes else no ),
        !T, !IO),

    % 1 and 10 are evicted from the fill and 10000 is never taken.
    check("the retained bag is {100, 1000, 100000}",
        ( if query(agg_sum, K, at(0), S, cold_value(agg_sum, no), float(101100.0)) then yes else no ),
        !T, !IO).

:- pred absorb_at(series_decl::in, series_key::in, float::in, int::in, int::out,
                  series_state::in, series_state::out) is det.

absorb_at(D, K, V, I, I + 1, !S) :-
    absorb(D, K, float(V), at(I * 1000000), !S).

:- pred test_signal_aggs(tally::in, tally::out, io::di, io::uo) is det.

test_signal_aggs(!T, !IO) :-
    Min = 60000000000,                      % one minute in ns
    Window = 600000000000u64,               % ten minutes

    % Integral: a left-hand step function over closed intervals, in seconds.
    % Samples 10 at t=0, 20 at t=1min, 30 at t=2min; the newest is open, so
    % 10*60 + 20*60 = 1800.
    DI = series_decl(bk_numeric_integral, "S", "v", "", el_float,
        Window, 0u64, 0u32, tm_sliding, gp_hold, np_unspecified),
    KI = series_key("S", "v", "", "", 0u64),
    absorb(DI, KI, float(10.0), at(0), init_series_state, I1),
    absorb(DI, KI, float(20.0), at(Min), I1, I2),
    absorb(DI, KI, float(30.0), at(2 * Min), I2, I3),
    check("integral is a left-hand step in SECONDS over closed intervals",
        ( if query(agg_integral, KI, at(2 * Min), I3, cold_value(agg_integral, no), float(1800.0))
          then yes else no ), !T, !IO),

    % Under `gap hold` the newest sample holds to the read [LSIG.1.5.1]: two
    % samples read a minute after the second give 10*60 + 20*60 = 1800.
    check("under gap hold the newest sample holds to the read instant",
        ( if query(agg_integral, KI, at(2 * Min), I2, cold_value(agg_integral, no), float(1800.0))
          then yes else no ), !T, !IO),

    % Under `gap zero` it does not [LSIG.3.6]: the same two samples read 600.
    DZ = DI ^ sd_gap := gp_zero,
    absorb(DZ, KI, float(10.0), at(0), init_series_state, Z1),
    absorb(DZ, KI, float(20.0), at(Min), Z1, Z2),
    check("under gap zero the open interval is not integrated",
        ( if query(agg_integral, KI, at(2 * Min), Z2, cold_value(agg_integral, no), float(600.0))
          then yes else no ), !T, !IO),

    % `all_time` carries `window_ns = 0`, which means no clip, not a window of
    % zero width.
    DAll = (DI ^ sd_window := 0u64) ^ sd_time := tm_all_time,
    absorb(DAll, KI, float(10.0), at(0), init_series_state, A1),
    absorb(DAll, KI, float(20.0), at(Min), A1, A2),
    check("an all_time integral (window_ns = 0) does not clip everything away",
        ( if query(agg_integral, KI, at(Min), A2, cold_value(agg_integral, no), float(600.0))
          then yes else no ), !T, !IO),

    % `active_fraction`'s denominator is the declared window: true for one
    % minute of a ten-minute window reads 0.1.
    DA = series_decl(bk_interval_pulse, "P", "b", "", el_bool,
        Window, 0u64, 0u32, tm_sliding, gp_unspecified, np_unspecified),
    KA = series_key("P", "b", "", "", 0u64),
    absorb(DA, KA, bool(yes), at(0), init_series_state, F1),
    absorb(DA, KA, bool(no), at(Min), F1, F2),
    check("active_fraction divides by the WINDOW, not the elapsed span",
        ( if query(agg_active_fraction, KA, at(2 * Min), F2, cold_value(agg_active_fraction, no), float(0.1))
          then yes else no ), !T, !IO),

    % A signal that goes true and stays true counts from its onset to the read
    % [LSIG.2.2.3]: two minutes of a ten-minute window is 0.2.
    absorb(DA, KA, bool(yes), at(0), init_series_state, G1),
    check("a still-open true interval counts up to the read instant",
        ( if query(agg_active_fraction, KA, at(2 * Min), G1, cold_value(agg_active_fraction, no), float(0.2))
          then yes else no ), !T, !IO),

    % `first` is the oldest and `last` the newest. Samples are stored
    % newest-first.
    DF = series_decl(bk_fifo_deque, "R", "v", "", el_float,
        Window, 0u64, 0u32, tm_sliding, gp_unspecified, np_unspecified),
    KF = series_key("R", "v", "", "", 0u64),
    absorb(DF, KF, float(10.0), at(0), init_series_state, E1),
    absorb(DF, KF, float(20.0), at(Min), E1, E2),
    absorb(DF, KF, float(30.0), at(2 * Min), E2, E3),
    check("first is the OLDEST in the window and last the NEWEST",
        ( if query(agg_first, KF, at(2 * Min), E3, cold_value(agg_first, no), float(10.0)),
             query(agg_last, KF, at(2 * Min), E3, cold_value(agg_last, no), float(30.0))
          then yes else no ), !T, !IO),

    % `bool_and` and `bool_or` agree at both extremes, so only a mixed window
    % tells them apart.
    DB = series_decl(bk_fifo_deque, "H", "b", "", el_bool,
        Window, 0u64, 0u32, tm_sliding, gp_unspecified, np_unspecified),
    KB = series_key("H", "b", "", "", 0u64),
    absorb(DB, KB, bool(yes), at(0), init_series_state, B1),
    absorb(DB, KB, bool(no), at(Min), B1, B2),
    check("bool_and and bool_or disagree on a MIXED window",
        ( if query(agg_bool_and, KB, at(Min), B2, cold_value(agg_bool_and, no), bool(no)),
             query(agg_bool_or, KB, at(Min), B2, cold_value(agg_bool_or, no), bool(yes))
          then yes else no ), !T, !IO),
    check("and agree on an all-true one",
        ( if query(agg_bool_and, KB, at(0), B1, cold_value(agg_bool_and, no), bool(yes)),
             query(agg_bool_or, KB, at(0), B1, cold_value(agg_bool_or, no), bool(yes))
          then yes else no ), !T, !IO),

    % [LSER.17.2] pNN interpolates (type 7) over the ten readings 10..100.
    % p50: num = 9*50 = 450, lo 4, frac 50 -> 50 + 0.5*10 = 55; nearest rank
    % would read the observed 50. p95: num = 855, lo 8, frac 55 -> 90 + 5.5.
    % (0.55 * 10 lands exactly half an ulp above 5.5 and ties to even, 5.5.)
    DP = series_decl(bk_ring_buffer, "P", "v", "", el_float,
        Window, 0u64, 0u32, tm_sliding, gp_unspecified, np_unspecified),
    KP = series_key("P", "v", "", "", 0u64),
    list.foldl(
        (pred(I::in, S0::in, S::out) is det :-
            absorb(DP, KP, float(float.float(10 * I)), at(I), S0, S)),
        1 .. 10, init_series_state, P10),
    check("[LSER.17.2] p50 over 10..100 interpolates to 55, not the observed 50",
        ( if query(agg_percentile(50), KP, at(10), P10,
                cold_value(agg_percentile(50), no), float(55.0))
          then yes else no ), !T, !IO),
    check("[LSER.17.2] p95 over 10..100 is 95.5",
        ( if query(agg_percentile(95), KP, at(10), P10,
                cold_value(agg_percentile(95), no), float(95.5))
          then yes else no ), !T, !IO),
    check("[LSER.17.2] a cold pNN is null",
        ( if query(agg_percentile(50), KP, at(10), init_series_state,
                cold_value(agg_percentile(50), no), null)
          then yes else no ), !T, !IO),

    % [LSER.17.2] -0 sorts before +0, so p0 of {+0.0, -0.0} absorbed in that
    % order is -0.0, told apart by the sign of 1/x. -1/inf, because a `-0.0`
    % literal may be read as `-(0.0)`, which is +0.0.
    PzNeg = float.unchecked_quotient(-1.0, float.infinity),
    PzKey = series_key("Z", "v", "", "", 0u64),
    PzDecl = series_decl(bk_ring_buffer, "Z", "v", "", el_float,
        Window, 0u64, 0u32, tm_sliding, gp_unspecified, np_unspecified),
    absorb(PzDecl, PzKey, float(0.0), at(0), init_series_state, Pz1),
    absorb(PzDecl, PzKey, float(PzNeg), at(1), Pz1, Pz2),
    check("[LSER.17.2] -0 sorts before +0: p0 of {+0, -0} is -0",
        ( if
            query(agg_percentile(0), PzKey, at(1), Pz2, null, float(PzOut)),
            float.unchecked_quotient(1.0, PzOut) < 0.0
          then yes else no ), !T, !IO),

    % [LSER.17.2] An infinite neighbour reads its limit, so only a
    % [-inf, +inf] pair reaches the formula's NaN.
    PiKey = series_key("I", "v", "", "", 0u64),
    PiDecl = series_decl(bk_ring_buffer, "I", "v", "", el_float,
        Window, 0u64, 0u32, tm_sliding, gp_unspecified, np_unspecified),
    absorb(PiDecl, PiKey, float(float.infinity), at(0), init_series_state, PiA1),
    absorb(PiDecl, PiKey, float(float.infinity), at(1), PiA1, PiA2),
    absorb(PiDecl, PiKey, float(-float.infinity), at(0), init_series_state, PiB1),
    absorb(PiDecl, PiKey, float(5.0), at(1), PiB1, PiB2),
    absorb(PiDecl, PiKey, float(5.0), at(0), init_series_state, PiC1),
    absorb(PiDecl, PiKey, float(float.infinity), at(1), PiC1, PiC2),
    check("[LSER.17.2] p50 of [inf, inf] is inf; [-inf, 5] is -inf; [5, inf] is inf",
        ( if
            query(agg_percentile(50), PiKey, at(1), PiA2, null, float(PiA)),
            PiA = float.infinity,
            query(agg_percentile(50), PiKey, at(1), PiB2, null, float(PiB)),
            PiB = -float.infinity,
            query(agg_percentile(50), PiKey, at(1), PiC2, null, float(PiC)),
            PiC = float.infinity
          then yes else no ), !T, !IO),

    % [LSER.10.9] `direction` compares the two newest samples: over 10, 30, 20
    % it reads -1, where the sign of `rate` (first to last) would read +1.
    DirKey = series_key("R", "d", "", "", 0u64),
    DirDecl = series_decl(bk_ring_buffer, "R", "d", "", el_int,
        Window, 0u64, 0u32, tm_sliding, gp_unspecified, np_unspecified),
    absorb(DirDecl, DirKey, int(10i64), at(0), init_series_state, Dir1),
    absorb(DirDecl, DirKey, int(30i64), at(1), Dir1, Dir2),
    absorb(DirDecl, DirKey, int(20i64), at(2), Dir2, Dir3),
    check("[LSER.10.9] direction over 10, 30, 20 is -1 (the newest pair)",
        ( if query(agg_direction, DirKey, at(2), Dir3, null, int(-1i64))
          then yes else no ), !T, !IO),
    check("[LSER.10.9] direction over 10, 30 is +1",
        ( if query(agg_direction, DirKey, at(1), Dir2, null, int(1i64))
          then yes else no ), !T, !IO),
    check("[LSER.10.9] direction over one sample is null",
        ( if query(agg_direction, DirKey, at(0), Dir1,
                cold_value(agg_direction, yes), null)
          then yes else no ), !T, !IO),
    % Compared, not subtracted: INT64_MAX - (-1) wraps negative.
    absorb(DirDecl, DirKey, int(-1i64), at(0), init_series_state, DirW1),
    absorb(DirDecl, DirKey, int(int64.max_int64), at(1), DirW1, DirW2),
    check("[LSER.10.9] direction over -1, INT64_MAX is +1",
        ( if query(agg_direction, DirKey, at(1), DirW2, null, int(1i64))
          then yes else no ), !T, !IO),

    % [LSER.16.5.1] A repeated value counts once.
    DD = series_decl(bk_ring_buffer, "D", "v", "", el_int,
        Window, 0u64, 0u32, tm_sliding, gp_unspecified, np_unspecified),
    KD = series_key("D", "v", "", "", 0u64),
    absorb(DD, KD, int(7i64), at(0), init_series_state, D1),
    absorb(DD, KD, int(7i64), at(1), D1, D2),
    absorb(DD, KD, int(9i64), at(2), D2, D3),
    check("[LSER.16.5.1] count_distinct over 7, 7, 9 is 2",
        ( if query(agg_count_distinct, KD, at(2), D3,
                cold_value(agg_count_distinct, yes), int(2i64))
          then yes else no ), !T, !IO),

    % [LSER.16.6.1] / [LSER.16.7.1] over the same 7, 7, 9. Numeric equality
    % crosses kinds: a Float lookup of 7.0 finds the Int 7s.
    check("[LSER.16.6.1] count_of(7) over 7, 7, 9 is 2",
        ( if query(agg_count_of(int(7i64)), KD, at(2), D3, int(0i64), int(2i64))
          then yes else no ), !T, !IO),
    check("[LSER.16.6.1] count_of(7.0) finds the Int samples",
        ( if query(agg_count_of(float(7.0)), KD, at(2), D3, int(0i64), int(2i64))
          then yes else no ), !T, !IO),
    check("[LSER.16.7.1] contains(9) is true, contains(8) false",
        ( if query(agg_contains(int(9i64)), KD, at(2), D3, bool(no), bool(yes)),
             query(agg_contains(int(8i64)), KD, at(2), D3, bool(no), bool(no))
          then yes else no ), !T, !IO),
    check("[LSER.16.7.1] a null lookup matches nothing",
        ( if query(agg_contains(null), KD, at(2), D3, bool(no), bool(no))
          then yes else no ), !T, !IO),

    % [LSIG.1.3.1, LSIG.2.2.3] A value asserted before the window still holds
    % inside it. `LSIG.IN-2`: 10.0 at 0s and 4.0 at 15s, a 10s window read at
    % 20s. The window is [10s, 20s], so 10.0 holds for 5s and 4.0 for 5s: 70.
    S10 = 10000000000,
    DC = series_decl(bk_numeric_integral, "F", "q", "", el_float,
        10000000000u64, 0u64, 0u32, tm_sliding, gp_unspecified,
        np_unspecified),
    KC = series_key("F", "q", "", "", 0u64),
    absorb(DC, KC, float(10.0), at(0), init_series_state, C1),
    absorb(DC, KC, float(4.0), at(15000000000), C1, C2),
    check("[LSIG.1.5.1] a pre-window sample's held value is integrated from the window start",
        ( if query(agg_integral, KC, at(2 * S10), C2,
                cold_value(agg_integral, no), float(70.0))
          then yes else no ), !T, !IO),

    % `LSIG.AF-2`: true from exactly `t - W`, read at `t`, is the whole window.
    DW = series_decl(bk_interval_pulse, "W", "b", "", el_bool,
        60000000000u64, 0u64, 0u32, tm_sliding, gp_unspecified,
        np_unspecified),
    KW = series_key("W", "b", "", "", 0u64),
    absorb(DW, KW, bool(yes), at(0), init_series_state, W1),
    check("[LSIG.1.3.1] true since the window's start is active_fraction 1.0",
        ( if query(agg_active_fraction, KW, at(60000000000), W1,
                cold_value(agg_active_fraction, no), float(1.0))
          then yes else no ), !T, !IO),

    % [LSIG.1.4.1] `LSIG.OR-2`: `true` at 5, 10, 15, 20 and 25 s with a
    % `false` between each, read at 26 s over a 20 s window. The `true` at 5 s
    % is the first absorption, no edge, and out of `(6, 26]` besides, which
    % holds four edges. `elapsed` is 21 s, so the denominator is the window:
    % 4 / 20 = 0.2.
    DO = series_decl(bk_ring_buffer, "D", "s", "", el_bool,
        20000000000u64, 0u64, 0u32, tm_sliding, gp_unspecified,
        np_unspecified),
    KO = series_key("D", "s", "", "", 0u64),
    S1 = 1000000000,
    list.foldl(
        (pred({Sec, B}::in, S0::in, S::out) is det :-
            absorb(DO, KO, bool(B), at(Sec * S1), S0, S)),
        [{5, yes}, {6, no}, {10, yes}, {11, no}, {15, yes}, {16, no},
         {20, yes}, {21, no}, {25, yes}],
        init_series_state, O9),
    check("[LSIG.1.4.1] onset_rate over OR-2's edges is 0.2",
        ( if query(agg_onset_rate, KO, at(26 * S1), O9,
                cold_value(agg_onset_rate, no), float(0.2))
          then yes else no ), !T, !IO),
    % `LSIG.OR-1`: `false` at 2 s, `true` at 3 s, read at 4 s. One edge, and
    % the denominator is the 2 s elapsed, not the 20 s window.
    absorb(DO, KO, bool(no), at(2 * S1), init_series_state, O1),
    absorb(DO, KO, bool(yes), at(3 * S1), O1, O2),
    check("[LSIG.1.4.2] one edge over 2 s elapsed is 0.5",
        ( if query(agg_onset_rate, KO, at(4 * S1), O2,
                cold_value(agg_onset_rate, no), float(0.5))
          then yes else no ), !T, !IO),
    % [LSIG.1.4.1] A first `true` follows nothing, so it is no edge.
    absorb(DO, KO, bool(yes), at(2 * S1), init_series_state, OF1),
    check("[LSIG.1.4.1] a first true is no rising edge",
        ( if query(agg_onset_rate, KO, at(4 * S1), OF1,
                cold_value(agg_onset_rate, no), float(0.0))
          then yes else no ), !T, !IO).

%-----------------------------------------------------------------------------%
% `series` -- the declared backings [RDSC.5a]
%-----------------------------------------------------------------------------%
%
% Prints every field of every backing, including the ones a given backing cannot
% carry, so a field read from the wrong number shows: every field is a varint or
% a string, and a misread lands a plausible value rather than failing to parse.

:- pred list_series(string::in, io::di, io::uo) is det.

list_series(Path, !IO) :-
    read_bitmap(Path, Res, !IO),
    (
        Res = yes(BM),
        load_dsc(BM, LoadRes),
        (
            LoadRes = loaded(P),
            Decls = series_decls(P),
            io.format("%d backing(s)\n", [i(list.length(Decls))], !IO),
            list.foldl(print_series, Decls, !IO)
        ;
            LoadRes = load_failed(E),
            io.format("load refused %s %s\n",
                [s(string.string(E ^ le_kind)),
                 s(clause_id_string(E ^ le_clause))], !IO),
            io.set_exit_status(1, !IO)
        )
    ;
        Res = no,
        io.format("cannot read %s\n", [s(Path)], !IO),
        io.set_exit_status(2, !IO)
    ).

:- pred print_series(series_decl::in, io::di, io::uo) is det.

print_series(D, !IO) :-
    ( if D ^ sd_id_slot = "" then By = "none" else By = D ^ sd_id_slot ),
    io.format("  %s  %s.%s  by=%s\n",
        [s(string.string(D ^ sd_backing)), s(D ^ sd_schema), s(D ^ sd_slot),
         s(By)], !IO),
    io.format("    element=%s window=%s persist=%s max=%d\n",
        [s(string.string(D ^ sd_element)),
         s(uint64_to_string(D ^ sd_window)),
         s(uint64_to_string(D ^ sd_persist)),
         i(uint32.cast_to_int(D ^ sd_max))], !IO),
    ( if D ^ sd_backing = bk_numeric_integral then
        io.format("    time=%s gap=%s\n",
            [s(string.string(D ^ sd_time)),
             s(string.string(D ^ sd_gap))], !IO)
    else
        true
    ).

%-----------------------------------------------------------------------------%

:- pred read_bitmap(string::in, maybe(bitmap)::out, io::di, io::uo) is det.

read_bitmap(Path, Result, !IO) :-
    io.open_binary_input(Path, OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, ReadRes, !IO),
        io.close_binary_input(Stream, !IO),
        ( ReadRes = ok(BM), Result = yes(BM)
        ; ReadRes = error(_), Result = no )
    ;
        OpenRes = error(_),
        Result = no
    ).

    % `Stop` is the `seq` of the unannounced FactAssert the reader stopped at
    % ([RFCS.5.4]), `no` for a recording read to its end.
    %
:- pred drive_replay(program::in, decoded_stream::in, maybe(uint64)::in,
                     io::di, io::uo) is det.

drive_replay(P, DS, Stop, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    % The replayer loads the artefact as the recorded run did, so the load's own
    % log lines come first here too ([RDSC.9.4]), where `run_scenario_mode`
    % prints them for the trace this output is compared with.
    show_effects(rm_trace, schemas(P), interns(P), load_logs(P), !IO),
    (
        Stop = no,
        replay_stream(P, DS, Steps, E0, E)
    ;
        Stop = yes(Seq),
        replay_unannounced(P, DS, Seq, Steps, E0, E)
    ),
    % The final engine's intern table names every string any step produced,
    % since the table only grows. The replay checks read this output.
    IT = engine_interns(E),
    list.foldl(print_replay_step(engine_schemas(E), IT), Steps, !IO),
    % `final halted` on a halted engine, as `run_scenario_mode` prints it:
    % the replay is compared with the trace that line ends.
    ( if engine_halted(E) = yes(_) then
        io.write_string("final halted\n", !IO)
    else
        io.format("final facts=%d\n", [i(engine_fact_count(E))], !IO)
    ).

:- pred print_replay_step(list(schema)::in, intern_table::in, replay_step::in,
                          io::di, io::uo) is det.

print_replay_step(Schemas, IT, delivered(Effects), !IO) :-
    print_effects(Schemas, IT, Effects, !IO).
print_replay_step(Schemas, IT, pumped(PumpEffects), !IO) :-
    % The `-- pump` marker and the status after the effects, where the trace
    % driver and `run_step`'s `st_pump` print them.
    io.write_string("-- pump\n", !IO),
    print_effects(Schemas, IT, PumpEffects, !IO),
    ( if first_pump_status(PumpEffects) = yes(_) then
        io.write_string("engine_error\n", !IO)
    else
        true
    ).
print_replay_step(_, _, unknown_schema(Seq), !IO) :-
    io.format("UNKNOWN SCHEMA: the FactAssert at seq %s names a schema the "
        ++ "engine does not hold\n", [s(string.uint64_to_string(Seq))], !IO).
print_replay_step(_, _, unknown_fact_id(Seq), !IO) :-
    io.format("UNKNOWN FACT ID: the FactRetract at seq %s names a fact no "
        ++ "earlier atom carries\n", [s(string.uint64_to_string(Seq))], !IO).
print_replay_step(_, _, recording_incomplete(Seq), !IO) :-
    io.format("RECORDING INCOMPLETE: the first event has seq %s, not 0\n",
        [s(string.uint64_to_string(Seq))], !IO).
print_replay_step(_, _, binding_refused(Code, Detail), !IO) :-
    io.format("BINDING REFUSED (%d): %s\n", [i(Code), s(Detail)], !IO).
print_replay_step(_, _, diverged(Seq), !IO) :-
    io.format("DIVERGED: the replay parted from the recording at seq %s\n",
        [s(string.uint64_to_string(Seq))], !IO).
print_replay_step(_, _, input_refused(Seq, Code, Detail), !IO) :-
    io.format("INPUT REFUSED (%d) at seq %s: %s\n",
        [i(Code), s(string.uint64_to_string(Seq)), s(Detail)], !IO).

    % `contract`: print the canonical contract serialization ([RBND.4b.7]).
    % [RTCT.6.8.1] does not say where in [RBND.4b.2]'s order the cache caps
    % go, so both candidate positions are hashed against the stored
    % `rt_config_sha256`: after `intern_bytes_cap`, and after `series`.
    %
:- pred probe_contract(string::in, io::di, io::uo) is det.

probe_contract(Path, !IO) :-
    read_bitmap(Path, Res, !IO),
    (
        Res = yes(BM),
        walk_for_dsrt(init_reader(BM), MaybeC),
        (
            MaybeC = dp_ok(C),
            % The hash is over the expanded node list ([RBND.4b.8]), and the
            % compact form's kinds come from the loaded network, so the
            % artefact is loaded and expanded by the loader's own
            % `ds.contract.expanded`.
            ( if load_dsc(BM, loaded(P)) then
                Expanded = expanded(network(P), C)
            else
                Expanded = C
            ),
            AfterIntern = canonical(Expanded, after_intern),
            Appended = canonical(Expanded, appended),
            io.format("stored rt_config_sha256  %s\n",
                [s(hex(C ^ c_stored_sha))], !IO),
            % Which node-cap encoding is in use: [RTCT.6.7] allows exactly one
            % of the `nodes` list and the compact form.
            io.format("legacy nodes=%d  node_count=%d default_cap=%d " ++
                      "overrides=%d packed=%d\n",
                [i(list.length(C ^ c_nodes)),
                 i(uint32.cast_to_int(C ^ c_node_count)),
                 i(uint32.cast_to_int(C ^ c_default_cap)),
                 i(list.length(C ^ c_overrides)),
                 i(list.length(C ^ c_packed))], !IO),
            show_candidate("caps after intern_bytes_cap", AfterIntern,
                C ^ c_stored_sha, !IO),
            show_candidate("caps appended after series", Appended,
                C ^ c_stored_sha, !IO)
        ;
            MaybeC = dp_none,
            io.write_string("no RealtimeContract atom in this artefact\n", !IO),
            io.set_exit_status(1, !IO)
        ;
            MaybeC = dp_undecodable(Body),
            io.format("RealtimeContract PRESENT AND UNDECODABLE -- %d body bytes\n",
                [i(list.length(Body))], !IO),
            io.format("  %s\n", [s(hex(Body))], !IO),
            io.set_exit_status(1, !IO)
        )
    ;
        Res = no,
        io.write_string("OPEN FAILED\n", !IO),
        io.set_exit_status(1, !IO)
    ).

:- pred show_candidate(string::in, string::in, list(uint8)::in,
                       io::di, io::uo) is det.

show_candidate(Label, Text, Stored, !IO) :-
    string.to_utf8_code_unit_list(Text, Codes),
    Digest = sha256(list.map(uint8.cast_from_int, Codes)),
    Mark = ( if Digest = Stored then "   <== MATCHES" else "" ),
    io.format("\n-- %s\n%s%s%s\n",
        [s(Label), s(Text), s(hex(Digest)), s(Mark)], !IO).

    % No contract and a contract that does not decode are kept apart; an
    % undecodable body carries its bytes out so the probe can show them.
    %
:- type dsrt_probe
    --->    dp_none
    ;       dp_undecodable(list(uint8))
    ;       dp_ok(contract).

:- pred walk_for_dsrt(reader::in, dsrt_probe::out) is det.

walk_for_dsrt(R0, Result) :-
    next_frame(FrameResult, R0, R1),
    (
        FrameResult = fr_ok(F),
        ( if F ^ fr_atom = known(at_realtime_contract) then
            ( if decode_contract(F ^ fr_body, C) then
                Result = dp_ok(C)
            else
                Result = dp_undecodable(reader_bytes(F ^ fr_body))
            )
        else
            walk_for_dsrt(R1, Result)
        )
    ;
        FrameResult = fr_eof,
        Result = dp_none
    ;
        FrameResult = fr_error(_, _),
        Result = dp_none
    ).

    % `selfhash`: hash the file as it stands and with the stored 32 bytes
    % zeroed ([RDSC.3.6]), and mark which the artefact's own `dsc_sha256`
    % equals.
    %
:- pred probe_self_hash(string::in, io::di, io::uo) is det.

probe_self_hash(Path, !IO) :-
    io.open_binary_input(Path, OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, ReadRes, !IO),
        io.close_binary_input(Stream, !IO),
        (
            ReadRes = ok(BM),
            load_dsc(BM, LoadResult),
            (
                LoadResult = loaded(P),
                Stored = header(P) ^ dh_sha256,
                io.format("stored   %s\n", [s(hex(Stored))], !IO),
                % The binding tuple, which [RBND.1.3] makes one value.
                io.format("caps     [%s]\n  defsha %s\n  rtsha  %s\n",
                    [s(string.join_list(", ", list.map(string.from_int,
                        header(P) ^ dh_capabilities))),
                     s(hex(header(P) ^ dh_dialect_sha)),
                     s(hex(header(P) ^ dh_rt_config_sha))], !IO),
                ( if bitmap_bytes(BM, Bytes) then
                    AsIs = sha256(Bytes),
                    io.format("as-is    %s%s\n",
                        [s(hex(AsIs)),
                         s(mark(( if AsIs = Stored then yes else no )))], !IO),
                    ( if zero_run(Bytes, Stored, Zeroed) then
                        Z = sha256(Zeroed),
                        io.format("zeroed   %s%s\n",
                            [s(hex(Z)),
                             s(mark(( if Z = Stored then yes else no )))], !IO)
                    else
                        io.write_string(
                            "zeroed   -- the stored hash does not appear in " ++
                            "the file, so there is nothing to zero\n", !IO)
                    )
                else
                    io.write_string("not a whole number of bytes\n", !IO)
                )
            ;
                LoadResult = load_failed(E),
                io.format("load refused %s\n",
                    [s(clause_id_string(E ^ le_clause))], !IO),
                io.set_exit_status(1, !IO)
            )
        ;
            ReadRes = error(Err),
            io.format("READ FAILED %s\n", [s(io.error_message(Err))], !IO),
            io.set_exit_status(1, !IO)
        )
    ;
        OpenRes = error(Err2),
        io.format("OPEN FAILED %s\n", [s(io.error_message(Err2))], !IO),
        io.set_exit_status(1, !IO)
    ).

:- func mark(bool) = string.

mark(yes) = "   <== MATCHES THE STORED FIELD".
mark(no) = "".

    % Replace the first occurrence of `Run` in `Bytes` with zeros. A 32-byte
    % SHA-256 value is found by search rather than by the field's offset.
    %
:- pred zero_run(list(uint8)::in, list(uint8)::in, list(uint8)::out) is semidet.

zero_run(Bytes, Run, Zeroed) :-
    Len = list.length(Run),
    Len > 0,
    find_run(Bytes, Run, 0, At),
    list.det_split_list(At, Bytes, Before, Rest),
    list.det_split_list(Len, Rest, _, After),
    Zeroed = Before ++ list.duplicate(Len, 0u8) ++ After.

:- pred find_run(list(uint8)::in, list(uint8)::in, int::in, int::out) is semidet.

find_run(Bytes @ [_ | Tail], Run, I, At) :-
    ( if list.append(Run, _, Bytes) then
        At = I
    else
        find_run(Tail, Run, I + 1, At)
    ).

    % `read`: decode a recorded stream, such as libds's `record_to` output,
    % and print one canonical line per event. The differential trace format
    % is a run's; this is a file's.
    %
:- pred read_recording(string::in, io::di, io::uo) is det.

read_recording(Path, !IO) :-
    io.open_binary_input(Path, OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, ReadRes, !IO),
        io.close_binary_input(Stream, !IO),
        (
            ReadRes = ok(BM),
            decode_stream(BM, init_interns, Result),
            (
                Result = decode_failed(Clause, Offset),
                io.format("decode refused %s at byte %d\n",
                    [s(Clause), i(Offset)], !IO),
                io.set_exit_status(1, !IO)
            ;
                % An offline reader meets [RFCS.5.4]'s first case only, and it
                % is a fatal stream error.
                Result = unannounced_schema(_, _, Offset),
                io.format("decode refused RFCS.5.4 at byte %d\n",
                    [i(Offset)], !IO),
                io.set_exit_status(1, !IO)
            ;
                Result = decoded(DS),
                io.format("header ds_version=%s hash=%d bytes session=%s\n",
                    [s(DS ^ dsm_meta ^ sm_ds_version),
                     i(list.length(DS ^ dsm_meta ^ sm_dsc_hash)),
                     s(DS ^ dsm_meta ^ sm_session)], !IO),
                print_decoded_all(DS ^ dsm_interns, 0, DS ^ dsm_events,
                    DS ^ dsm_external, !IO),
                io.format("%d events\n", [i(list.length(DS ^ dsm_events))], !IO)
            )
        ;
            ReadRes = error(Err),
            io.format("READ FAILED %s\n", [s(io.error_message(Err))], !IO),
            io.set_exit_status(1, !IO)
        )
    ;
        OpenRes = error(Err2),
        io.format("OPEN FAILED %s\n", [s(io.error_message(Err2))], !IO),
        io.set_exit_status(1, !IO)
    ).

    % The events, with each ExternalAssert at its place in the file (`re_after`). An
    % ExternalAssert is one line: its seq, the handles it lists, its window, and a
    % digest of the FactExternal it carries, so two runtimes' recordings of
    % one input compare on what the bytes were without printing them.
    %
:- pred print_decoded_all(intern_table::in, int::in,
                          list({seq, stream_event})::in,
                          list(recorded_external)::in, io::di, io::uo) is det.

print_decoded_all(IT, N, Events, Externals, !IO) :-
    ( if
        Externals = [X | Xs],
        X ^ re_after =< N
    then
        io.format("%d external fact_ids=[%s] ttl=%d fact=%s\n",
            [i(uint64.cast_to_int(seq_value(X ^ re_seq))),
             s(string.join_list(" ",
                list.map(string.uint64_to_string, X ^ re_fact_ids))),
             i(uint64.cast_to_int(X ^ re_ttl_ns)),
             s(string.left(ds.sha256.hex(ds.sha256.sha256(X ^ re_fact)), 16))],
            !IO),
        print_decoded_all(IT, N, Events, Xs, !IO)
    else
        (
            Events = [Ev | Evs],
            print_decoded(IT, Ev, !IO),
            print_decoded_all(IT, N + 1, Evs, Externals, !IO)
        ;
            Events = []
        )
    ).

:- pred print_decoded(intern_table::in, {seq, stream_event}::in,
                      io::di, io::uo) is det.

print_decoded(IT, {Seq, Event}, !IO) :-
    N = uint64.cast_to_int(seq_value(Seq)),
    (
        Event = se_fact_assert(Id, _, Values, _),
        io.format("%d assert fact=%d [%s]\n",
            [i(N), i(uint64.cast_to_int(fact_id_value(Id))),
             s(string.join_list(" ", list.map(show_value(IT), Values)))], !IO)
    ;
        Event = se_fact_retract(Id),
        io.format("%d retract fact=%d\n",
            [i(N), i(uint64.cast_to_int(fact_id_value(Id)))], !IO)
    ;
        Event = se_fact_withdraw(WId, Cause),
        io.format("%d withdraw fact=%d %s\n",
            [i(N), i(uint64.cast_to_int(fact_id_value(WId))),
             s(string.string(Cause))], !IO)
    ;
        Event = se_fact_withdraw_unnamed(UId, Code),
        io.format("%d withdraw fact=%d cause=%d\n",
            [i(N), i(uint64.cast_to_int(fact_id_value(UId))),
             i(uint32.cast_to_int(Code))], !IO)
    ;
        Event = se_clock_tick(To, Wall),
        WallText = ( if Wall = yes(W) then int64_to_string(W) else "unset" ),
        io.format("%d tick %d wall=%s\n",
            [i(N), i(uint64.cast_to_int(instant_ns(To))), s(WallText)], !IO)
    ;
        Event = se_pump_boundary,
        io.format("%d pump\n", [i(N)], !IO)
    ;
        % Every other kind is unreachable here, and is listed rather than
        % wildcarded so that a newly decodable atom fails to compile.
        ( Event = se_call_response(_, _) ; Event = se_call_error(_, _)
        ; Event = se_rule_lhs_facts(_, _) ; Event = se_fire_begin(_)
        ; Event = se_fire_end(_) ; Event = se_timer_armed(_, _, _)
        ; Event = se_call_issued(_, _, _, _, _)
        ; Event = se_clock_advance(_) ; Event = se_engine_error(_, _)
        ; Event = se_cache_set(_, _, _) ; Event = se_cache_delete(_)
        ; Event = se_emit(_, _)
        ; Event = se_publish(_, _, _)
        ; Event = se_log_emitted(_, _) ),
        io.format("%d (not reconstructed)\n", [i(N)], !IO)
    ).

:- func show_value(intern_table, ds_value) = string.

show_value(IT, V) =
    ( if V = str(R), expand(IT, R, S) then
        "\"" ++ S ++ "\""
    else
        string.string(V)
    ).

    % `record`: run the scenario and write a recorded fact stream, which the
    % recordings check hands to libds's reader.
    %
:- pred emit_recording(string::in, string::in, string::in,
                       io::di, io::uo) is det.

emit_recording(ArtefactPath, ScenarioPath, OutPath, !IO) :-
    io.open_binary_input(ArtefactPath, OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, ReadRes, !IO),
        io.close_binary_input(Stream, !IO),
        (
            ReadRes = ok(BM),
            load_dsc(BM, LoadResult),
            (
                LoadResult = loaded(P),
                read_scenario(ScenarioPath, Steps, !IO),
                record_scenario(P, Steps, OutPath, !IO)
            ;
                LoadResult = load_failed(E),
                io.format("load refused %s %s\n",
                    [s(string.string(E ^ le_kind)),
                     s(clause_id_string(E ^ le_clause))], !IO)
            )
        ;
            ReadRes = error(Err),
            io.format("READ FAILED %s\n", [s(io.error_message(Err))], !IO),
            io.set_exit_status(1, !IO)
        )
    ;
        OpenRes = error(Err2),
        io.format("OPEN FAILED %s\n", [s(io.error_message(Err2))], !IO),
        io.set_exit_status(1, !IO)
    ).

    % A recording's `StreamHeader.dsc_hash` ([RBND.1.3]): the artefact's
    % header `dsc_sha256` ([RBND.3.1]), which `load_dsc` has verified
    % ([RDSC.3.6]). Read through the engine's session header, where
    % `record_scenario` takes it from.
    %
:- func recording_dsc_hash(program) = list(uint8).

recording_dsc_hash(P) = session_header(init_engine(P)) ^ sm_dsc_hash.

:- pred record_scenario(program::in, list(step)::in, string::in,
                        io::di, io::uo) is det.

record_scenario(P, Steps, OutPath, !IO) :-
    engine_use_mock_clock(init_engine(P), E0),
    % The clock when the recording begins, which `encode_stream` advances by
    % each tick.
    Origin = engine_now(E0),
    list.foldl4(record_step(P), Steps, E0, E, [], _Handles, [], RevEffects,
        !IO),
    list.reverse(RevEffects, Effects),
    Events = list.filter_map(
        (func(Ef) = Ev is semidet :- Ef = eff_event(Ev)), Effects),
    % Sequence numbers follow emission order over all events, from zero, so
    % the events a recording drops take their numbers with them and its `seq`
    % values have gaps. libds's first recorded event has no `seq` field,
    % which under proto3 is zero. The brackets around a host input that holds
    % a reference come with the events, numbered nothing, so the input is
    % written as one ExternalAssert ([RFCS.24]).
    Numbered = record_items(0u64, Effects),
    % The engine's intern table, not the program's: a string interned after
    % load lives only in the engine's. The schemas are the artefact's
    % ([NFCT.1.1]), so the engine's at the end are its schemas at its first
    % event, when the prelude is written ([RFCS.5.1]).
    Ctx = rfcs_ctx(engine_schemas(E), engine_interns(E)),
    % The header is the engine's session header ([RFCS.4]), as libds's
    % recorder takes its `StreamHeader` from `ds_engine_get_session_header`.
    Meta = session_header(E),
    % The host's seeds, in the prelude ([RFCS.26.1]): what the cache held at
    % the engine's first event.
    encode_recording(Meta, Ctx, Origin, prelude_seeds(E), Numbered, Bytes0,
        Unencodable),
    % No event, no recording: the header and prelude are written at the
    % engine's first event ([RFCS.5.1]).
    ( if Events = [] then Bytes = [] else Bytes = Bytes0 ),
    % Only the writer knows an event failed to encode, so it names each one.
    (
        Unencodable = []
    ;
        Unencodable = [_ | _],
        io.format("WARNING: %d recordable events did not encode\n",
            [i(list.length(Unencodable))], !IO),
        list.foldl(
            (pred(Ev::in, !.IO::di, !:IO::uo) is det :-
                io.format("WARNING:   %s\n", [s(string.string(Ev))], !IO)),
            Unencodable, !IO)
    ),
    io.open_binary_output(OutPath, OutRes, !IO),
    (
        OutRes = ok(OutStream),
        list.foldl(io.write_binary_uint8(OutStream), Bytes, !IO),
        io.close_binary_output(OutStream, !IO),
        io.format("wrote %d bytes, %d events\n",
            [i(list.length(Bytes)), i(list.length(Events))], !IO)
    ;
        OutRes = error(OutErr),
        io.format("OPEN FAILED %s\n", [s(io.error_message(OutErr))], !IO),
        io.set_exit_status(1, !IO)
    ).

    % The step's events and host-input brackets, newest first: what
    % `record_items` reads. Actions and samples reach no atom.
    %
:- pred record_step(program::in, step::in, engine::in, engine::out,
                    list(fact_id)::in, list(fact_id)::out,
                    list(effect)::in, list(effect)::out,
                    io::di, io::uo) is det.

record_step(P, Step, !E, !Handles, !Events, !IO) :-
    % Through `run_step`, so the recording is the run the trace harness
    % compares. The earlier events go in as the step's history, which a
    % `resend` reads; only what the step added comes back out.
    Prior = list.reverse(!.Events),
    run_step(rm_trace, P, Step, !E, !Handles, Prior, Acc, !IO),
    ( if list.drop(list.length(Prior), Acc, Added) then
        Effects = Added
    else
        unexpected($pred, "run_step returned less than its history")
    ),
    list.foldl(collect_event, Effects, !Events).

:- pred collect_event(effect::in, list(effect)::in, list(effect)::out) is det.

collect_event(eff_event(Event), !Events) :-
    !:Events = [eff_event(Event) | !.Events].
collect_event(eff_input(I), !Events) :-
    !:Events = [eff_input(I) | !.Events].
collect_event(eff_action(_), !Events).
collect_event(eff_cache_expired(_), !Events).
collect_event(eff_metric(_), !Events).    % no recording carries one
collect_event(eff_host_log(_, _, _), !Events).   % nor the engine's own log
collect_event(eff_pump_status(_), !Events).   % nor a pump's status

:- pred emit_trace(string::in, string::in, io::di, io::uo) is det.

emit_trace(ArtefactPath, ScenarioPath, !IO) :-
    io.open_binary_input(ArtefactPath, OpenRes, !IO),
    (
        OpenRes = ok(Stream),
        io.read_binary_file_as_bitmap(Stream, ReadRes, !IO),
        io.close_binary_input(Stream, !IO),
        (
            ReadRes = ok(BM),
            load_dsc(BM, LoadResult),
            (
                LoadResult = loaded(P),
                read_scenario(ScenarioPath, Steps, !IO),
                run_scenario(P, Steps, !IO)
            ;
                LoadResult = load_failed(E),
                % A decoded refusal is a result, not a crash: it exits 0 and
                % goes in the trace. The kind tells an intended refusal from a
                % corrupt artefact.
                io.format("load refused %s %s\n",
                    [s(string.string(E ^ le_kind)),
                     s(clause_id_string(E ^ le_clause))], !IO)
            )
        ;
            ReadRes = error(Err),
            io.format("READ FAILED %s\n", [s(io.error_message(Err))], !IO),
            io.set_exit_status(1, !IO)
        )
    ;
        OpenRes = error(Err2),
        io.format("OPEN FAILED %s\n", [s(io.error_message(Err2))], !IO),
        io.set_exit_status(1, !IO)
    ).

%-----------------------------------------------------------------------------%

:- type step
    --->    st_assert(string, assoc_list(string, raw_value))
    ;       st_retract(int)
    ;       st_refracted
            % [NDBG.4.3]'s listing: one `refracted` line per entry. A read: it
            % changes nothing and samples no clock.
    ;       st_trace(int)
            % [NDBG.4.2]'s match trace of the fact the N-th assert made, as
            % `retract N` names one: one `trace` line per alpha node. A read.
    ;       st_mem
            % `engine_mem`'s counts, one `mem` line ([NDBG.2.1]). A read. The
            % layout-sized byte fields are not printed: they are libds's struct
            % sizes and this runtime's 0, which `check_engine_mem` checks.
    ;       st_advance(int)
    ;       st_set(int)
            % An absolute mock-clock instant, where `st_advance` is a delta.
            % Not a sample: the next input or pump samples it.
    ;       st_wall(int)
            % The mock wall clock, UTC ns ([NTST.3.1]). Unset until a scenario
            % sets it, and `now()` read while it is unset faults. Not a sample.
    ;       st_resend(int)
            % `ds_engine_assert_external` ([NCBK.10.4], [RFCS.23.7]) of the
            % K-th fact, from 0, this run has sent as a call argument, in
            % issue order and then argument order. Each runtime feeds back the
            % bytes it wrote, so nothing is hand-encoded.
    ;       st_convert(string, string, unit_direction, raw_value)
            % `convert <Schema> <slot> <to_stored|from_stored> <number>`:
            % [NFCT.1.4.6]'s conversion of a slot that names a unit
            % ([RDSC.5.5.9]). A read, save for an EngineError it raises.
    ;       st_pump.

%-----------------------------------------------------------------------------%
% `tms` -- the conformance oracle, run against a real scenario
%-----------------------------------------------------------------------------%
%
% The refcount is the engine and the fixpoint is `ds.conform`'s oracle, which
% decides whether the refcount has desynchronised. This points the oracle at
% states a running program produced, through the scenario driver.

    % `order <artefact> <scenario>`, Mercury-only: `fire <timetag> <rule>
    % <fact-id>...` per firing, in agenda order, with the timetag and fact ids
    % the comparison trace drops (`rm_order_audit`).
    %
:- pred order_scenario(string::in, string::in, io::di, io::uo) is det.

order_scenario(ArtefactPath, ScenarioPath, !IO) :-
    read_bitmap(ArtefactPath, Res, !IO),
    (
        Res = yes(BM),
        load_dsc(BM, LoadResult),
        (
            LoadResult = loaded(P),
            read_scenario(ScenarioPath, Steps, !IO),
            run_scenario_mode(rm_order_audit, P, Steps, _, !IO)
        ;
            LoadResult = load_failed(E),
            io.format("load refused %s %s\n",
                [s(string.string(E ^ le_kind)),
                 s(clause_id_string(E ^ le_clause))], !IO)
        )
    ;
        Res = no,
        io.format("cannot read %s\n", [s(ArtefactPath)], !IO)
    ).

:- pred audit_scenario(string::in, string::in, io::di, io::uo) is det.

audit_scenario(ArtefactPath, ScenarioPath, !IO) :-
    read_bitmap(ArtefactPath, Res, !IO),
    (
        Res = yes(BM),
        load_dsc(BM, LoadResult),
        (
            LoadResult = loaded(P),
            read_scenario(ScenarioPath, Steps, !IO),
            run_scenario_mode(rm_tms_audit, P, Steps, _, !IO)
        ;
            LoadResult = load_failed(E),
            % A decoded refusal is a result and exits 0, as under `trace`.
            io.format("load refused %s %s\n",
                [s(string.string(E ^ le_kind)),
                 s(clause_id_string(E ^ le_clause))], !IO)
        )
    ;
        Res = no,
        io.format("cannot read %s\n", [s(ArtefactPath)], !IO),
        io.set_exit_status(2, !IO)
    ).

%-----------------------------------------------------------------------------%

:- pred read_scenario(string::in, list(step)::out, io::di, io::uo) is det.

read_scenario(Path, Steps, !IO) :-
    io.open_input(Path, Res, !IO),
    (
        Res = ok(Stream),
        io.read_file_as_string(Stream, ReadRes, !IO),
        io.close_input(Stream, !IO),
        (
            ReadRes = ok(Text),
            Lines = string.split_at_char('\n', Text),
            Steps = list.filter_map(parse_step, Lines),
            Unknown = unknown_steps(Lines),
            (
                Unknown = []
            ;
                Unknown = [_ | _],
                % Fatal: a partly understood scenario traces like a result.
                list.foldl(
                    (pred(L::in, !.I::di, !:I::uo) is det :-
                        io.format("UNKNOWN SCENARIO STEP %s\n", [s(L)], !I)),
                    Unknown, !IO),
                io.set_exit_status(2, !IO)
            )
        ;
            ReadRes = error(_, _),
            Steps = []
        )
    ;
        Res = error(_),
        Steps = []
    ).

    % The non-blank, non-comment lines that do not parse. `parse_step` is a
    % `semidet` filter, so it skips an unrecognised step silently;
    % `read_scenario` refuses the run on any line this returns.
    %
:- func unknown_steps(list(string)) = list(string).

unknown_steps(Lines) =
    list.filter(unrecognised, list.map(string.strip, Lines)).

:- pred unrecognised(string::in) is semidet.

unrecognised(Line) :-
    Line \= "",
    not string.prefix(Line, "#"),
    not parse_step(Line) = _.

:- func parse_step(string) = step is semidet.

parse_step(Line) = Step :-
    Words = string.words(Line),
    Words = [Head | Rest],
    not string.prefix(Head, "#"),
    (
        Head = "pump",
        Step = st_pump
    ;
        Head = "advance",
        Rest = [NsText],
        string.to_int(NsText, Ns),
        Step = st_advance(Ns)
    ;
        Head = "set",
        Rest = [AtText],
        string.to_int(AtText, At),
        Step = st_set(At)
    ;
        Head = "wall",
        Rest = [UtcText],
        string.to_int(UtcText, Utc),
        Step = st_wall(Utc)
    ;
        Head = "retract",
        Rest = [NText],
        string.to_int(NText, N),
        Step = st_retract(N)
    ;
        Head = "resend",
        Rest = [KText],
        string.to_int(KText, K),
        Step = st_resend(K)
    ;
        Head = "refracted",
        Rest = [],
        Step = st_refracted
    ;
        Head = "trace",
        Rest = [NText],
        string.to_int(NText, N),
        Step = st_trace(N)
    ;
        Head = "mem",
        Rest = [],
        Step = st_mem
    ;
        Head = "convert",
        Rest = [CSchema, CSlot, DirText, ValueText],
        convert_direction(DirText, Dir),
        Value = parse_value(ValueText),
        ( Value = rv_int(_) ; Value = rv_float(_) ),
        Step = st_convert(CSchema, CSlot, Dir, Value)
    ;
        Head = "assert",
        Rest = [Schema | Assigns],
        Step = st_assert(Schema, list.filter_map(parse_assign, Assigns))
    ).

:- pred convert_direction(string::in, unit_direction::out) is semidet.

convert_direction("to_stored", ud_to_stored).
convert_direction("from_stored", ud_from_stored).

:- func convert_direction_name(unit_direction) = string.

convert_direction_name(ud_to_stored) = "to_stored".
convert_direction_name(ud_from_stored) = "from_stored".

    % A scenario's number as the value a host hands the conversion: an `Int`
    % or a `Float`, as its text spells it. `parse_step` lets no other value
    % reach a `convert` step.
    %
:- func raw_number(raw_value) = ds_value.

raw_number(V) = Number :-
    ( if V = rv_int(I) then
        Number = int(I)
    else if V = rv_float(F) then
        Number = float(F)
    else
        Number = null
    ).

    % The end of a `convert` line: the result, or libds's status for the
    % refusal ([NFCT.1.4.6]'s table), as `trace_libds.py` prints pyds's.
    %
:- func convert_ending(unit_outcome) = string.

convert_ending(uo_ok(V)) = Ending :-
    ( if V = int(I) then
        Ending = "int " ++ string.int64_to_string(I)
    else if V = float(F) then
        Ending = "float " ++ float.float64_bits_string(F)
    else
        Ending = "? " ++ string.string(V)
    ).
convert_ending(uo_no_slot) = "refused -3".
convert_ending(uo_no_unit) = "refused -1".
convert_ending(uo_kind_mismatch) = "refused -104".
convert_ending(uo_nan) = "refused -216".
convert_ending(uo_halted) = "refused -10".
convert_ending(uo_not_representable) = "refused -223".

:- type raw_value
    --->    rv_int(int64)
    ;       rv_float(float)
    ;       rv_bool(bool)
    ;       rv_string(string)
    ;       rv_json(string)
            % `json:` and a JSON text with no spaces, for a Json slot: the
            % document, not a String holding it. `trace_libds.parse_value`
            % reads the same form.
    ;       rv_null
    ;       rv_live(string).
            % `@Schema`: a reference to the earliest-asserted live fact of the
            % schema, `null` when none is live, so a host assert can carry a
            % fact the host did not assert. `trace_libds.parse_value` reads it
            % the same way.

:- func parse_assign(string) = pair(string, raw_value) is semidet.

parse_assign(Text) = Name - Value :-
    [Name, ValueText] = string.split_at_char('=', Text),
    Value = parse_value(ValueText).

:- func parse_value(string) = raw_value.

parse_value(Text) = Value :-
    ( if string.remove_prefix("json:", Text, JsonText) then
        Value = rv_json(JsonText)
    else if i64.from_decimal(Text, I) then
        Value = rv_int(I)
    else if string.to_float(Text, F) then
        Value = rv_float(F)
    else if Text = "true" then
        Value = rv_bool(yes)
    else if Text = "false" then
        Value = rv_bool(no)
    else if Text = "null" then
        % The canonical null [LNUL.2.1], as `trace_libds.parse_value` reads it.
        % Bare only: `"null"` quoted falls to the string arm below.
        Value = rv_null
    else if string.remove_prefix("@", Text, Schema), Schema \= "" then
        Value = rv_live(Schema)
    else
        % Quotes are stripped if present, so a scenario may write either
        % `zone="kitchen"` or `zone=kitchen`. The libds half accepts both too.
        Value = rv_string(string.remove_prefix_if_present("\"",
            string.remove_suffix_if_present("\"", Text)))
    ).

%-----------------------------------------------------------------------------%

    % What the one scenario driver prints.
    %
:- type run_mode
    --->    rm_trace        % effects, for `diff` and `record`
    ;       rm_tms_audit    % the conformance oracle, per pump
    ;       rm_silent       % nothing: a unit test driving a scenario
    ;       rm_order_audit. % what the agenda ordered on, per firing
            % Mercury-only; the runtime differential never selects it. The
            % comparison trace drops the timetag and an assert's fact id, which
            % the join mints; this prints them, since a second evaluator agrees
            % with this one iff a key computable from the match reproduces the
            % join's order.

:- pred run_scenario(program::in, list(step)::in, io::di, io::uo) is det.

run_scenario(P, Steps, !IO) :-
    run_scenario_mode(rm_trace, P, Steps, _, !IO).

:- pred run_scenario_mode(run_mode::in, program::in, list(step)::in,
                          engine::out, io::di, io::uo) is det.

run_scenario_mode(Mode, P, Steps, E, !IO) :-
    % Mock clock, matching `engine.clock_set_mode("mock")` in the libds half.
    % A live clock refuses `advance` and makes every run differ.
    engine_use_mock_clock(init_engine(P), E0),
    % The load's own log lines first ([RDSC.9.4]), where libds writes them to
    % the log callback `trace_libds.py` registers before it loads.
    show_effects(Mode, schemas(P), interns(P), load_logs(P), !IO),
    list.foldl4(run_step(Mode, P), Steps, E0, E, [], _Handles, [], _Effects,
        !IO),
    (
        Mode = rm_trace,
        % A halted engine's working memory is undefined ([LERR.1.4.7]) and
        % libds refuses its count ([NCBK.2.9]), so both halves print
        % `final halted`.
        ( if engine_halted(E) = yes(_) then
            io.write_string("final halted\n", !IO)
        else
            io.format("final facts=%d\n", [i(engine_fact_count(E))], !IO)
        )
    ;
        Mode = rm_tms_audit,
        true
    ;
        Mode = rm_silent,
        true
    ;
        Mode = rm_order_audit,
        true
    ).

    % The effects come back as well as being printed, so `record` and `trace`
    % share one driver.
    %
:- pred run_step(run_mode::in, program::in, step::in, engine::in, engine::out,
                 list(fact_id)::in, list(fact_id)::out,
                 list(effect)::in, list(effect)::out, io::di, io::uo) is det.

run_step(Mode, P, st_assert(SchemaName, Assigns), !E, !Handles, !Acc, !IO) :-
    % The engine's schemas and table, as libds's `ds_engine_schema_find`
    % reads the engine's.
    IT0 = engine_interns(!.E),
    ( if find_schema(engine_schemas(!.E), IT0, SchemaName, Schema) then
        ( if
            % An omitted non-nullable slot is refused, as pyds
            % (`pyds_build_slot_values`) refuses it for the libds half.
            % `hydrated_corr` is pyds's one exception; `slot_value_for`
            % fills it.
            list.find_first_match(
                (pred(C::in) is semidet :-
                    C ^ sc_nullable = non_null,
                    expand(IT0, C ^ sc_name, N),
                    N \= "hydrated_corr",
                    not assoc_list.search(Assigns, N, _)),
                slot_commons(Schema), Missing),
            expand(IT0, Missing ^ sc_name, MissingName)
        then
            io.format("REFUSED %s: missing kwarg for slot `%s`\n",
                [s(SchemaName), s(MissingName)], !IO)
        else
            % By slot name, in the schema's declaration order.
            list.map_foldl(slot_value_for(P, Assigns), slot_commons(Schema),
                Values, !E),
            host_assert(Schema, Values, no_deadline, Result, Effects, !E),
            ( if Result = inserted(Id) then
                !:Handles = !.Handles ++ [Id]
            else if Result = replaced(_, Id2) then
                !:Handles = !.Handles ++ [Id2]
            else
                true
            ),
            show_effects(Mode, engine_schemas(!.E), engine_interns(!.E), Effects, !IO),
            !:Acc = !.Acc ++ Effects
        )
    else
        % The artefact declares no such schema. `trace_libds.py` prints the
        % same line. On the trace only.
        (
            Mode = rm_trace,
            io.format("unknown_schema %s\n", [s(SchemaName)], !IO)
        ;
            Mode = rm_tms_audit
        ;
            Mode = rm_silent
        ;
            Mode = rm_order_audit
        )
    ).
run_step(Mode, _P, st_retract(N), !E, !Handles, !Acc, !IO) :-
    ( if list.index0(!.Handles, N, Id) then
        host_retract(Id, Effects, !E),
        show_effects(Mode, engine_schemas(!.E), engine_interns(!.E), Effects, !IO),
        !:Acc = !.Acc ++ Effects
    else
        io.write_string("UNKNOWN HANDLE\n", !IO)
    ).
run_step(Mode, _P, st_refracted, !E, !Handles, !Acc, !IO) :-
    % No fact ids on the line: they are engine-local. The order is the
    % listing's: terminal ordinal, then fact-id tuple.
    (
        Mode = rm_trace,
        ( if engine_halted(!.E) = yes(_) then
            % [NCBK.2.9]: a halted engine's state is undefined and libds
            % refuses the read; `trace_libds.py` prints the same.
            io.write_string("refracted halted\n", !IO)
        else
            list.foldl(
                ( pred(R::in, !.I::di, !:I::uo) is det :-
                    list.length(R ^ ra_facts, NFacts),
                    io.format("refracted %s %s facts=%d | %s\n",
                        [s(R ^ ra_rule), s(R ^ ra_reason), i(NFacts),
                         s(R ^ ra_detail)], !I) ),
                engine_refracted_activations(!.E, no), !IO)
        )
    ;
        Mode = rm_tms_audit
    ;
        Mode = rm_order_audit
    ;
        Mode = rm_silent
    ).
run_step(Mode, _P, st_trace(N), !E, !Handles, !Acc, !IO) :-
    ( if
        Mode = rm_trace,
        engine_halted(!.E) = yes(_)
    then
        % [NCBK.2.9]: a halted engine's state is undefined and libds refuses
        % the read; `trace_libds.py` prints the same, before it looks at the
        % handle.
        io.write_string("trace halted\n", !IO)
    else if list.index0(!.Handles, N, Id) then
        (
            Mode = rm_trace,
            list.foldl(
                ( pred(T::in, !.I::di, !:I::uo) is det :-
                    io.format("trace %s %s %s | %s\n",
                        [s(T ^ ts_node), s(T ^ ts_kind), s(T ^ ts_result),
                         s(T ^ ts_detail)], !I) ),
                engine_rete_match_trace(!.E, Id), !IO)
        ;
            Mode = rm_tms_audit
        ;
            Mode = rm_order_audit
        ;
            Mode = rm_silent
        )
    else
        io.write_string("UNKNOWN HANDLE\n", !IO)
    ).
run_step(Mode, _P, st_advance(Ns), !E, !Handles, !Acc, !IO) :-
    advance(duration_from_ns(uint64.det_from_int(Ns)), Effects, !E),
    show_effects(Mode, engine_schemas(!.E), engine_interns(!.E), Effects, !IO),
    !:Acc = !.Acc ++ Effects.
run_step(Mode, _P, st_set(At), !E, !Handles, !Acc, !IO) :-
    set_clock(from_ns(uint64.det_from_int(At)), Effects, !E),
    show_effects(Mode, engine_schemas(!.E), engine_interns(!.E), Effects, !IO),
    !:Acc = !.Acc ++ Effects.
run_step(Mode, _P, st_mem, !E, !Handles, !Acc, !IO) :-
    % The logical counts only, in `ds_engine_mem_t`'s order and names, as
    % `trace_libds.py` prints pyds's `mem()`: the counts [NDBG.2.1] says two
    % runtimes report alike. The byte and intern fields are
    % implementation-defined ([NDBG.2.1], [NMET.4.7]).
    (
        Mode = rm_trace,
        ( if engine_halted(!.E) = yes(_) then
            % [NCBK.2.9]: a halted engine's state is undefined and libds
            % refuses the read; `trace_libds.py` prints the same.
            io.write_string("mem halted\n", !IO)
        else
            M = engine_mem(!.E),
            io.format("mem wm_fact_count=%d alpha_node_count=%d "
                ++ "alpha_match_count=%d beta_node_count=%d "
                ++ "beta_token_count=%d\n",
                [i(M ^ em_wm_fact_count), i(M ^ em_alpha_node_count),
                 i(M ^ em_alpha_match_count), i(M ^ em_beta_node_count),
                 i(M ^ em_beta_token_count)], !IO)
        )
    ;
        Mode = rm_tms_audit
    ;
        Mode = rm_order_audit
    ;
        Mode = rm_silent
    ).
run_step(Mode, _P, st_convert(SchemaName, SlotName, Dir, Raw), !E, !Handles,
        !Acc, !IO) :-
    % `trace_libds.py`'s `convert` line: `convert <Schema> <slot>
    % <direction>`, then `int N`, `float B` with B the IEEE-754 bits as a
    % signed 64-bit integer, or `refused S` with libds's status for the
    % outcome. A name the engine has no schema or slot by is SCHEMA_UNKNOWN
    % or SLOT_UNKNOWN, as pyds refuses it, and a halted engine's schema read
    % is refused ([NCBK.2.9]).
    IT0 = engine_interns(!.E),
    ( if engine_halted(!.E) = yes(_) then
        Ending = "refused -10"
    else if find_schema(engine_schemas(!.E), IT0, SchemaName, Schema) then
        ( if
            list.find_index_of_match(
                (pred(C::in) is semidet :- expand(IT0, C ^ sc_name, SlotName)),
                slot_commons(Schema), 0, Index)
        then
            nfct_1_4_6_convert(Schema, Index, Dir, raw_number(Raw), Outcome,
                Effects, !E),
            show_effects(Mode, engine_schemas(!.E), engine_interns(!.E),
                Effects, !IO),
            !:Acc = !.Acc ++ Effects,
            Ending = convert_ending(Outcome)
        else
            Ending = "refused -103"
        )
    else
        Ending = "refused -101"
    ),
    (
        Mode = rm_trace,
        io.format("convert %s %s %s %s\n",
            [s(SchemaName), s(SlotName), s(convert_direction_name(Dir)),
             s(Ending)], !IO)
    ;
        Mode = rm_tms_audit
    ;
        Mode = rm_order_audit
    ;
        Mode = rm_silent
    ).
run_step(_Mode, _P, st_wall(Utc), !E, !Handles, !Acc, !IO) :-
    % Not a sample ([NTST.3.3]): the next input or pump samples the wall
    % clock and its tick carries the value.
    set_wall_clock(int64.from_int(Utc), !E).
run_step(Mode, _P, st_resend(K), !E, !Handles, !Acc, !IO) :-
    % The sent facts are read off the run's own effects, `!.Acc`. A handle is
    % added for each fact the delivery put into working memory, in assertion
    % order, as `trace_libds.apply_step` adds them, so a later `retract N`
    % names the same fact in both.
    Sent = list.condense(list.map(sent_facts, !.Acc)),
    ( if list.index0(Sent, K, Bytes) then
        WM0 = engine_wm(!.E),
        assert_external_with(Bytes, no, Result, Asserted, Effects, !E),
        New = list.filter(
            (pred(Id::in) is semidet :- not lookup_fact(WM0, Id, _)),
            Asserted),
        !:Handles = !.Handles ++ New,
        show_effects(Mode, engine_schemas(!.E), engine_interns(!.E), Effects, !IO),
        !:Acc = !.Acc ++ Effects,
        (
            Result = ext_refused(Why),
            % The status number, as the libds half reads it out of pyds's
            % `[status] detail`.
            (
                Mode = rm_trace,
                io.format("external_refused %d\n",
                    [i(external_refusal_status(Why))], !IO)
            ;
                Mode = rm_tms_audit
            ;
                Mode = rm_silent
            ;
                Mode = rm_order_audit
            )
        ;
            Result = ext_asserted
        ;
            % A halt stopped the delivery part-way. Nothing is printed here,
            % where the libds half prints `external_refused` with
            % DS_ERR_ENGINE_HALTED; no scenario reaches it.
            Result = ext_stopped(_)
        )
    else
        io.format("UNKNOWN SENT FACT %d\n", [i(K)], !IO)
    ).
run_step(Mode, P, st_pump, !E, !Handles, !Acc, !IO) :-
    % A pump boundary marker, printed by both drivers from the scenario, so a
    % bare `retract` line shows which pump it fell in ([IRET.12.3],
    % `12_multi_justifier`).
    (
        Mode = rm_trace,
        io.write_string("-- pump\n", !IO)
    ;
        Mode = rm_tms_audit,
        true
    ;
        Mode = rm_silent,
        true
    ;
        Mode = rm_order_audit,
        io.format("-- pump (refraction holds %d)\n",
            [i(engine_refraction_size(!.E))], !IO)
    ),
    pump(default_budget, Effects, !E),
    show_effects(Mode, engine_schemas(!.E), engine_interns(!.E), Effects, !IO),
    % The oracle runs at quiescence: mid-cascade a fact is legitimately live
    % and unsupported. A pump's status is traced once, after its events, as
    % the bare `engine_error` `trace_libds.py` prints for libds.
    (
        Mode = rm_trace,
        ( if first_pump_status(Effects) = yes(_) then
            io.write_string("engine_error\n", !IO)
        else
            true
        )
    ;
        Mode = rm_tms_audit,
        audit_tms(P, !.E, !IO)
    ;
        Mode = rm_silent,
        true
    ;
        Mode = rm_order_audit,
        true
    ),
    !:Acc = !.Acc ++ Effects.

    % The FactExternal bytes of every fact an effect sent as a call argument,
    % in argument order -- the order `trace_args` prints them in.
    %
:- func sent_facts(effect) = list(bitmap).

sent_facts(Effect) = Facts :-
    ( if Effect = eff_event(se_call_issued(_, _, _, Args, _)) then
        Facts = list.filter_map(arg_fact_bytes, Args)
    else
        Facts = []
    ).

    % Fails for a fact that will not encode, which shifts every later index;
    % `trace_args` prints it as `<unencodable fact>`, so its `call` line
    % already differs.
    %
:- func arg_fact_bytes(arg) = bitmap is semidet.

arg_fact_bytes(arg(_, av_encoded_fact(FE))) =
        from_bytes(list.map(uint8.cast_to_int, Bytes)) :-
    encode_fact_external(FE, Bytes).

    % `proto/status.proto`'s numbers.
    %
:- func external_refusal_status(external_refusal) = int.

external_refusal_status(xr_parse) = -100.                % DS_ERR_PARSE
external_refusal_status(xr_json_limit) = -221.           % DS_ERR_JSON_LIMIT
external_refusal_status(xr_schema_unknown) = -101.       % DS_ERR_SCHEMA_UNKNOWN
external_refusal_status(xr_schema_hash_mismatch) = -219. % DS_ERR_SCHEMA_HASH_MISMATCH
external_refusal_status(xr_fact_ref_conflict) = -220.    % DS_ERR_FACT_REF_CONFLICT
external_refusal_status(xr_slot_type_mismatch) = -104.   % DS_ERR_SLOT_TYPE_MISMATCH
external_refusal_status(xr_nan_rejected) = -216.         % DS_ERR_NAN_REJECTED
external_refusal_status(xr_time_range) = -205.           % DS_ERR_TIME_RANGE
external_refusal_status(xr_inval) = -1.                  % DS_ERR_INVAL
external_refusal_status(xr_contract_breach) = -710.      % DS_ERR_CONTRACT_BREACH
external_refusal_status(xr_halted(_)) = -10.             % DS_ERR_ENGINE_HALTED

    % The intern table is the engine's, not the program's: a firing adds to
    % the engine's, so a ref minted during a run does not expand against
    % `interns(P)`, and both tables have one type. The schemas are the
    % engine's too.
    %
:- pred show_effects(run_mode::in, list(schema)::in, intern_table::in,
                     list(effect)::in, io::di, io::uo) is det.

show_effects(rm_trace, Schemas, IT, Effects, !IO) :-
    print_effects(Schemas, IT, Effects, !IO).
show_effects(rm_tms_audit, _, _, _, !IO).
show_effects(rm_silent, _, _, _, !IO).
show_effects(rm_order_audit, _, IT, Effects, !IO) :-
    list.foldl(print_order_row(IT), Effects, !IO).

    % `fire <timetag> <rule> <fact-id>...` -- one row per firing, in the order
    % the agenda released them.
    %
    % `se_rule_lhs_facts` carries both the timetag the agenda sorted on and
    % the token's facts, which a content-derived key would sort on.
    %
:- pred print_order_row(intern_table::in, effect::in, io::di, io::uo) is det.

print_order_row(IT, Effect, !IO) :-
    ( if
        Effect = eff_event(se_rule_lhs_facts(fire_id(TT, Rule), Facts))
    then
        io.format("fire %d %s %s\n",
            [i(uint64.cast_to_int(timetag_value(TT))),
             s(name_of(IT, Rule)),
             s(string.join_list(",",
                 list.map(fact_id_str, Facts)))], !IO)
    else
        true
    ).

:- func fact_id_str(fact_id) = string.

fact_id_str(Id) = string.uint64_to_string(fact_id_value(Id)).

    % One line per pump. `orphans` is `iret_12_2__no_unsupported_forever`
    % executed: live facts the `tms_cascade.tla` fixpoint says are
    % unsupported. `desyncs` is every fact on which this engine's activation
    % refcount and the model's support relation disagree.
    %
:- pred audit_tms(program::in, engine::in, io::di, io::uo) is det.

audit_tms(Prog, E, !IO) :-
    ( if engine_halted(E) = yes(_) then
        % [LERR.1.4.7]: a halted engine's state is undefined, so the pump is
        % counted and not audited, as `tms_libds.py` counts libds's.
        io.write_string("pump halted\n", !IO)
    else
        audit_tms_live(Prog, E, !IO)
    ).

:- pred audit_tms_live(program::in, engine::in, io::di, io::uo) is det.

audit_tms_live(Prog, E, !IO) :-
    T = engine_tms(E),
    W = engine_wm(E),
    audit_match_paths(E, PathProblems),
    io.format("pump live=%d orphans=%d desyncs=%d rete_path=%d\n",
        [i(live_count(W)),
         i(list.length(orphans(T, W))),
         i(list.length(desyncs(T, W))),
         i(list.length(PathProblems))], !IO),
    list.foldl(
        (pred(P::in, !.S::di, !:S::uo) is det :-
            io.format("  RETE PATH DEPENDENCE: %s\n", [s(P)], !.S, !:S)),
        PathProblems, !IO),
    dump_tms_state(Prog, E, !IO).

    % The state the TMS checker's negation evaluator judges, after the
    % pump line: every live fact, and every live justification as its rule,
    % its token's facts in pattern order and the facts it derived.
    %
    %   tms_fact<TAB><id><TAB><schema>[<TAB><slot>=<value>]...
    %   tms_act<TAB><rule><TAB><token ids or ->TAB><derived ids>
    %
    % `ds.conform` judges positive antecedents only. The `no` half is judged
    % by the evaluator both legs use, from the artefact's own atoms, so this
    % prints what the engine holds and nothing it decided.
    %
    % A value is `i<int>`, `b0` / `b1`, `s<utf-8 hex>` (a tab or an `=` in a
    % String cannot break the line), `n` for null, or `x<kind>` for a kind the
    % evaluator does not judge.
    %
:- pred dump_tms_state(program::in, engine::in, io::di, io::uo) is det.

dump_tms_state(Prog, E, !IO) :-
    IT = engine_interns(E),
    W = engine_wm(E),
    list.foldl(dump_tms_schema(IT, W), engine_schemas(E), !IO),
    list.foldl(dump_tms_justification(IT, rule_metas(Prog)),
        live_justifications(engine_tms(E)), !IO).

:- pred dump_tms_schema(intern_table::in, wm::in, schema::in,
                        io::di, io::uo) is det.

dump_tms_schema(IT, W, Schema, !IO) :-
    Name = tms_ref_text(IT, schema_name_ref(Schema ^ s_name)),
    list.foldl(dump_tms_fact(IT, Name, slot_commons(Schema)),
        facts_of_schema(W, Schema ^ s_id), !IO).

:- pred dump_tms_fact(intern_table::in, string::in, list(slot_common)::in,
                      fact::in, io::di, io::uo) is det.

dump_tms_fact(IT, Schema, Commons, Fact, !IO) :-
    Slots = list.map(tms_slot_text(IT, Fact ^ f_slots), Commons),
    io.write_string(string.join_list("\t",
        ["  tms_fact", fact_id_str(Fact ^ f_id), Schema | Slots]) ++ "\n",
        !IO).

:- func tms_slot_text(intern_table, array(ds_value), slot_common) = string.

tms_slot_text(IT, Values, Common) = tms_ref_text(IT, Common ^ sc_name)
        ++ "=" ++ Text :-
    ( if
        array.semidet_lookup(Values, slot_index_int(Common ^ sc_index), V)
    then
        Text = tms_value_text(IT, V)
    else
        Text = "xmissing"
    ).

:- func tms_value_text(intern_table, ds_value) = string.

tms_value_text(_, int(I)) = "i" ++ string.int64_to_string(I).
tms_value_text(_, float(_)) = "xfloat".
tms_value_text(IT, str(Ref)) =
    ( if expand(IT, Ref, S) then "s" ++ tms_hex(S) else "xstr" ).
tms_value_text(_, text(S)) = "s" ++ tms_hex(S).
tms_value_text(_, bool(yes)) = "b1".
tms_value_text(_, bool(no)) = "b0".
tms_value_text(_, bytes(_)) = "xbytes".
tms_value_text(_, json(_)) = "xjson".
tms_value_text(_, fact_ref(_)) = "xref".
tms_value_text(_, duration(_)) = "xduration".
tms_value_text(_, time(_)) = "xtime".
tms_value_text(_, ratio(_, _)) = "xratio".
tms_value_text(_, null) = "n".

:- func tms_hex(string) = string.

tms_hex(S) = ds.sha256.hex(list.map(uint8.det_from_int, Units)) :-
    string.to_utf8_code_unit_list(S, Units).

:- func tms_ref_text(intern_table, intern_ref) = string.

tms_ref_text(IT, Ref) = ( if expand(IT, Ref, S) then S else "?" ).

:- pred dump_tms_justification(intern_table::in, list(rule_meta)::in,
                               {uint32, list(fact_id), list(fact_id)}::in,
                               io::di, io::uo) is det.

dump_tms_justification(IT, Metas, {Terminal, Token, Derived}, !IO) :-
    ( if
        list.find_first_match(
            (pred(M::in) is semidet :-
                node_id_value(M ^ rm_terminal) = Terminal),
            Metas, Meta)
    then
        Rule = tms_ref_text(IT, Meta ^ rm_name)
    else
        Rule = "?"
    ),
    TokenText = ( if Token = [] then "-"
                  else string.join_list(",", list.map(fact_id_str, Token)) ),
    io.write_string(string.join_list("\t",
        ["  tms_act", Rule, TokenText,
         string.join_list(",", list.map(fact_id_str, Derived))]) ++ "\n",
        !IO).

    % A slot's value from the scenario, by name. An omitted slot is what pyds
    % makes of it, as the libds half asserts through pyds: `hydrated_corr` is
    % `""` and a nullable slot `null` ([LNUL.4.1]); `run_step` has refused a
    % non-nullable one. `compiler/mercury/test/test_behave.m`'s `slot_value`
    % makes the same cases.
    %
:- pred slot_value_for(program::in, assoc_list(string, raw_value)::in,
                       slot_common::in, ds_value::out,
                       engine::in, engine::out) is det.

slot_value_for(_P, Assigns, Common, Value, !E) :-
    % The engine's table, as `run_step` reads the schema from it.
    IT0 = engine_interns(!.E),
    ( if
        expand(IT0, Common ^ sc_name, Name),
        assoc_list.search(Assigns, Name, Raw)
    then
        (
            Raw = rv_int(I),
            Value = int(I)
        ;
            Raw = rv_float(F),
            Value = float(F)
        ;
            Raw = rv_bool(B),
            Value = bool(B)
        ;
            Raw = rv_string(S),
            engine_intern(S, Ref, !E),
            Value = str(Ref)
        ;
            % Parsed as libds's `ds_json_parse` parses it (`ds.json_text`).
            % A text that does not parse is the scenario's mistake, so it
            % stops the run rather than asserting a `null` neither side wrote.
            Raw = rv_json(J),
            ds.json_text.parse(J, Parsed),
            (
                Parsed = parsed(Term),
                Value = json(Term)
            ;
                Parsed = refused(_),
                unexpected($pred, "scenario `json:` value does not parse: " ++ J)
            )
        ;
            Raw = rv_null,
            Value = null
        ;
            Raw = rv_live(SchemaName),
            ( if
                find_schema(engine_schemas(!.E), IT0, SchemaName, Target),
                Live = facts_of_schema(engine_wm(!.E), Target ^ s_id),
                Live = [_ | _]
            then
                Ids = list.map((func(F) = fact_id_value(F ^ f_id)), Live),
                Value = fact_ref(make_fact_id(list.foldl(uint64.min, Ids,
                    list.det_head(Ids))))
            else
                Value = null
            )
        )
    else if expand(IT0, Common ^ sc_name, "hydrated_corr") then
        engine_intern("", Ref, !E),
        Value = str(Ref)
    else
        Value = null
    ).

%-----------------------------------------------------------------------------%

:- pred print_effects(list(schema)::in, intern_table::in, list(effect)::in,
                      io::di, io::uo) is det.

print_effects(Schemas, IT, Effects, !IO) :-
    list.foldl(print_effect(Schemas, IT), Effects, !IO).

:- pred print_effect(list(schema)::in, intern_table::in, effect::in,
                     io::di, io::uo) is det.

print_effect(Schemas, IT, eff_event(E), !IO) :-
    print_event(Schemas, IT, E, !IO).
print_effect(_, _, eff_action(A), !IO) :-
    io.format("cb_%s\n", [s(callback_name(A))], !IO).
    % Not traced: a recorder's bracket, on neither runtime's stream.
print_effect(_, _, eff_input(_), !IO).
    % With its key, as `trace_libds.py` prints libds's cache-removal handler
    % for a `ttl` removal.
print_effect(_, _, eff_cache_expired(K), !IO) :-
    io.format("cb_cache_expired %s\n", [s(K)], !IO).
print_effect(_, _, eff_metric(M), !IO) :-
    print_metric(M, !IO).
    % A bare `cb_log`, as `trace_libds.py` prints every call of libds's.
print_effect(_, _, eff_host_log(_, _, _), !IO) :-
    io.write_string("cb_log\n", !IO).
    % `run_step`'s `st_pump` prints the status after the pump's events, where
    % `trace_libds.py` prints libds's.
print_effect(_, _, eff_pump_status(_), !IO).

    % One metric emission, as `trace_libds.py`'s `on_metric` prints libds's:
    % `metric <name> <kind> <labels>`, the labels sorted by key, a counter's
    % value last, a gauge's not on the line ([NMET.4.7]).
    %
:- pred print_metric(metric::in, io::di, io::uo) is det.

print_metric(M, !IO) :-
    Sorted = list.sort(M ^ m_labels),
    Labels = ( if Sorted = [] then "-"
        else string.join_list(",",
            list.map((func({K, V}) = K ++ "=" ++ V), Sorted)) ),
    (
        M ^ m_kind = mk_counter,
        io.format("metric %s counter %s %s\n",
            [s(M ^ m_name), s(Labels), s(float_to_string(M ^ m_value))], !IO)
    ;
        M ^ m_kind = mk_gauge,
        io.format("metric %s gauge %s\n", [s(M ^ m_name), s(Labels)], !IO)
    ).

    % The integrator callback an action fires, which `verb_name_of` names
    % except for a hydration call: that reaches the integrator through
    % `cb_call`. No artefact that loads carries one while hydration is
    % deferred ([RDSC.4a.9.5]).
    %
:- func callback_name(action) = string.

callback_name(A) = Name :-
    ( if A = a_hydration_call(_, _, _, _, _) then
        Name = "call"
    else
        Name = verb_name_of(A)
    ).

:- pred print_event(list(schema)::in, intern_table::in, stream_event::in,
                    io::di, io::uo) is det.

print_event(Schemas, IT, Event, !IO) :-
    ( if Event = se_rule_lhs_facts(fire_id(_, Rule), Facts) then
        io.format("lhs %s %d\n",
            [s(name_of(IT, Rule)), i(list.length(Facts))], !IO)
    else if Event = se_fire_begin(fire_id(_, Rule2)) then
        io.format("fire_begin %s\n", [s(name_of(IT, Rule2))], !IO)
    else if Event = se_fire_end(fire_id(_, Rule3)) then
        io.format("fire_end %s\n", [s(name_of(IT, Rule3))], !IO)
    else if Event = se_timer_armed(fire_id(_, Rule3a), _, _) then
        % The rule name only, as the libds half reports it: the two runtimes'
        % clocks share no origin.
        io.format("timer_armed %s\n", [s(name_of(IT, Rule3a))], !IO)
    else if Event = se_fact_assert(_, SchemaId, _, _) then
        io.format("assert %s\n", [s(schema_of(Schemas, IT, SchemaId))], !IO)
    else if
        ( Event = se_fact_retract(_) ; Event = se_fact_withdraw(_, _)
        ; Event = se_fact_withdraw_unnamed(_, _) )
    then
        % One line for both: libds's callback calls either `fact_retract`.
        io.write_string("retract\n", !IO)
    else if Event = se_emit(_, SchemaId2) then
        io.format("emit %s\n", [s(schema_of(Schemas, IT, SchemaId2))], !IO)
    else if Event = se_publish(SchemaId3, _, External) then
        % The FactExternal is on the line ([NCBK.10.1]), as a fact call
        % argument's is: `fact:` and its bytes in hex, `-` for none.
        io.format("publish %s %s\n",
            [s(schema_of(Schemas, IT, SchemaId3)),
             s(published_external(External))],
            !IO)
    else if Event = se_log_emitted(Level, Msg) then
        % The message is the last field, because it may contain spaces.
        io.format("log %s %s\n", [s(log_level_name(Level)), s(Msg)], !IO)
    else if Event = se_call_issued(_, Service, Corr, Args, _) then
        % The correlation is on the line: it is the causal join key
        % ([RFCS.11.2], [RFCS.15.2]). The arguments are last, because they
        % contain spaces and commas, as `{"name":value,...}` in their order,
        % the shape `trace_libds.py` renders pyds's `args` in.
        io.format("call %s %s %s\n",
            [s(name_of(IT, Service)), s(correlation_text(IT, Corr)),
             s(trace_args(Args))],
            !IO)
    else if Event = se_cache_set(_, _, _) then
        io.write_string("cache_set\n", !IO)
    else if Event = se_cache_delete(_) then
        io.write_string("cache_delete\n", !IO)
    else if Event = se_clock_advance(_) then
        io.write_string("clock\n", !IO)
    else if Event = se_clock_tick(_, _) then
        io.write_string("tick\n", !IO)
    else if Event = se_engine_error(ee_expr_fault(Fault), _) then
        % One token per fault class, as `trace_libds.py` maps libds's three
        % stream kinds. `engine_error` is the refused-call marker below.
        io.format("fault %s\n", [s(fault_token(Fault))], !IO)
    else if Event = se_engine_error(_, _) then
        io.write_string("engine_error\n", !IO)
    else
        true
    ).

:- func name_of(intern_table, intern_ref) = string.

name_of(IT, Ref) = ( if expand(IT, Ref, S) then S else "?" ).

    % By the schemas it is given: the engine's at a run step and the
    % program's elsewhere, which are one set ([NFCT.1.1]).
    %
:- func schema_of(list(schema), intern_table, schema_id) = string.

schema_of(Schemas, IT, Id) = Name :-
    ( if
        list.find_first_match(has_schema_id(Id), Schemas, S),
        expand(IT, schema_name_ref(S ^ s_name), N)
    then
        Name = N
    else
        Name = "?"
    ).

:- pred has_schema_id(schema_id::in, schema::in) is semidet.

has_schema_id(Id, S) :- S ^ s_id = Id.

    % A fault's class, as the trace spells it -- `trace_libds.py` maps libds's
    % `computation_error`, `type_error` and `engine_error` onto the same three.
    %
:- func fault_token(runtime_fault) = string.

fault_token(rf_type_error) = "type".
fault_token(rf_artefact_lied) = "engine".
fault_token(rf_type_mismatch) = "engine".
fault_token(rf_pattern_index) = "engine".
fault_token(rf_binding_order) = "engine".
fault_token(rf_unimplemented) = "engine".
fault_token(rf_div_zero) = "computation".
fault_token(rf_mod_zero) = "computation".
fault_token(rf_domain) = "computation".
fault_token(rf_not_representable) = "computation".
fault_token(rf_time_range) = "computation".
fault_token(rf_cast_non_finite(_)) = "computation".

%-----------------------------------------------------------------------------%
% The interpolation renderer, against the clauses
%-----------------------------------------------------------------------------%
%
% Expectations written from [LGRA.2.9.6.10] and [LGRA.2.9.6.4], not measured.
% The runtime differential's `31_format_vectors` compares this renderer with
% libds; these hold it to the clauses, so a misreading both share still fails.

:- pred test_format(tally::in, tally::out, io::di, io::uo) is det.

test_format(!T, !IO) :-
    io.format("\n-- format (the renderer, against the clauses) --\n", [], !IO),
    list.foldl2(check_render, render_cases, !T, !IO),
    list.foldl2(check_refusal, refusal_cases, !T, !IO),
    list.foldl2(check_part_refusal, part_refusal_cases, !T, !IO),
    list.foldl2(check_time, time_cases, !T, !IO).

    % A `ValuePrim` with every field given; the value expression is unused by
    % `render_value`, which is handed the value.
    %
:- func vp(format_type, format_align, bool, bool, int, maybe(int)) = value_prim.

vp(Type, Align, Plus, Zero, Width, Prec) =
    value_prim(e_lit(null), Align, Plus, Zero, uint32.det_from_int(Width),
        maybe.map_maybe(uint32.det_from_int, Prec), Type).

:- func canon = value_prim.

canon = vp(ft_canonical, align_default, no, no, 0, no).
    % The `-0.0` cases use `neg_zero`, not the literal `-0.0`: Mercury's
    % unary minus is `0.0 - X`, so `-0.0` in source is positive zero.

:- type render_case ---> rc(string, value_prim, renderable, string).

:- func render_cases = list(render_case).

render_cases = [
    % The canonical texts.
    rc("Int canonical", canon, r_int(42i64), "42"),
    rc("negative Int canonical", canon, r_int(-7i64), "-7"),
    rc("min_int64 keeps its magnitude", canon, r_int(int64.min_int64),
        "-9223372036854775808"),
    rc("whole Float keeps .0", canon, r_float(42.0), "42.0"),
    rc("-0.0 keeps its sign", canon, r_float(neg_zero), "-0.0"),
    rc("inf", canon, r_float(float.infinity), "inf"),
    rc("-inf", canon, r_float(-float.infinity), "-inf"),
    rc("small Float is scientific", canon, r_float(0.00001), "1e-05"),
    rc("Bool canonical", canon, r_bool(yes), "true"),
    rc("String canonical", canon, r_string("kitchen"), "kitchen"),

    % Width and alignment: a number right, a String or Bool left.
    rc("d width 5 aligns right", vp(ft_d, align_default, no, no, 5, no),
        r_int(42i64), "   42"),
    rc("d `<5`", vp(ft_d, align_left, no, no, 5, no), r_int(42i64), "42   "),
    rc("String width 8 aligns left", vp(ft_canonical, align_default, no, no,
        8, no), r_string("kitchen"), "kitchen "),
    rc("String `>8`", vp(ft_s, align_right, no, no, 8, no),
        r_string("kitchen"), " kitchen"),
    rc("Bool width 6 aligns left", vp(ft_canonical, align_default, no, no, 6,
        no), r_bool(no), "false "),
    rc("text past the width is whole", vp(ft_d, align_default, no, no, 2, no),
        r_int(12345i64), "12345"),

    % The sign and zero padding.
    rc("`+d`", vp(ft_d, align_default, yes, no, 0, no), r_int(42i64), "+42"),
    rc("`05d`", vp(ft_d, align_default, no, yes, 5, no), r_int(42i64),
        "00042"),
    rc("`05d` negative: zeros after the sign",
        vp(ft_d, align_default, no, yes, 5, no), r_int(-42i64), "-0042"),
    rc("`+05d`", vp(ft_d, align_default, yes, yes, 5, no), r_int(42i64),
        "+0042"),

    % Bases: the magnitude, with a `-`, never two's complement.
    rc("`x`", vp(ft_x_lower, align_default, no, no, 0, no), r_int(255i64),
        "ff"),
    rc("`X`", vp(ft_x_upper, align_default, no, no, 0, no), r_int(255i64),
        "FF"),
    rc("negative `x` is sign-magnitude", vp(ft_x_lower, align_default, no, no,
        0, no), r_int(-7i64), "-7"),
    rc("`06x`", vp(ft_x_lower, align_default, no, yes, 6, no), r_int(42i64),
        "00002a"),
    rc("`b`", vp(ft_b, align_default, no, no, 0, no), r_int(5i64), "101"),
    rc("negative `b`", vp(ft_b, align_default, no, no, 0, no), r_int(-5i64),
        "-101"),

    % `f`: the binary value correctly rounded, ties to even, six by default.
    rc("`f` defaults to six", vp(ft_f, align_default, no, no, 0, no),
        r_float(3.14159), "3.141590"),
    rc("`.2f` rounds, not truncates", vp(ft_f, align_default, no, no, 0,
        yes(2)), r_float(0.129), "0.13"),
    rc("`.0f` writes no point, and rounds", vp(ft_f, align_default, no, no, 0,
        yes(0)), r_float(7.9), "8"),
    % 0.125 and 0.375 are exact in binary, so they are true ties: half-up
    % would give 0.13 for the first.
    rc("`.2f` tie goes to even, down", vp(ft_f, align_default, no, no, 0,
        yes(2)), r_float(0.125), "0.12"),
    rc("`.2f` tie goes to even, up", vp(ft_f, align_default, no, no, 0,
        yes(2)), r_float(0.375), "0.38"),
    rc("`f` on an Int", vp(ft_f, align_default, no, no, 0, no), r_int(3i64),
        "3.000000"),
    rc("`.1f` keeps -0.0's sign", vp(ft_f, align_default, no, no, 0, yes(1)),
        r_float(neg_zero), "-0.0"),
    rc("`+.2f`", vp(ft_f, align_default, yes, no, 0, yes(2)), r_float(1.5),
        "+1.50"),
    rc("`010.2f` negative", vp(ft_f, align_default, no, yes, 10, yes(2)),
        r_float(-1.5), "-000001.50"),
    rc("`f` on inf", vp(ft_f, align_default, no, no, 0, no),
        r_float(float.infinity), "inf"),

    % Precision and width count code points.
    rc("`.3s`", vp(ft_s, align_default, no, no, 0, yes(3)),
        r_string("kitchen"), "kit"),
    rc("`.2s` cuts on a code point", vp(ft_s, align_default, no, no, 0,
        yes(2)), r_string("héllo"), "hé"),
    rc("width counts code points", vp(ft_s, align_default, no, no, 4, no),
        r_string("hé"), "hé  "),
    rc("a canonical String takes a precision", vp(ft_canonical,
        align_default, no, no, 0, yes(1)), r_string("abc"), "a")
].

:- pred check_render(render_case::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_render(rc(Name, VP, R, Want), !T, !IO) :-
    ( if render_value(VP, R, Got) then
        check_quiet(Name, ( if Got = Want then yes else no ), Got, Want,
            !T, !IO)
    else
        check_quiet(Name, no, "<refused>", Want, !T, !IO)
    ).

    % [LGRA.2.9.6.5]'s kinds: what a type does not take is refused, and the
    % evaluator raises it as the node's type error.
    %
:- type refusal_case ---> fc(string, format_type, renderable).

:- func refusal_cases = list(refusal_case).

refusal_cases = [
    fc("`d` refuses a Float", ft_d, r_float(1.0)),
    fc("`x` refuses a String", ft_x_lower, r_string("a")),
    fc("`b` refuses a Bool", ft_b, r_bool(yes)),
    fc("`f` refuses a String", ft_f, r_string("1.0")),
    fc("`s` refuses an Int", ft_s, r_int(1i64)),
    fc("`s` refuses a Bool", ft_s, r_bool(no))
].

:- pred check_refusal(refusal_case::in, tally::in, tally::out,
                      io::di, io::uo) is det.

check_refusal(fc(Name, Type, R), !T, !IO) :-
    check(Name, ( if render_value(vp(Type, align_default, no, no, 0, no), R, _)
                  then no else yes ), !T, !IO).

    % [LGRA.2.9.6.5]'s refusals of a part rather than a type, which the
    % renderer applies at run time to a `Json` leaf ([LGRA.2.9.6.11]): never
    % rendered with the part dropped. A sign or `0` on a String or a Bool; a
    % precision with no type on anything but a String; a precision on an
    % integer type.
    %
:- type part_refusal_case ---> pc(string, value_prim, renderable).

:- func part_refusal_cases = list(part_refusal_case).

part_refusal_cases = [
    pc("`+` refuses a Bool", vp(ft_canonical, align_default, yes, no, 0, no),
        r_bool(yes)),
    pc("`+` refuses a String", vp(ft_canonical, align_default, yes, no, 0, no),
        r_string("ab")),
    pc("`05` refuses a String", vp(ft_canonical, align_default, no, yes, 5,
        no), r_string("ab")),
    pc("`+s` refuses a String", vp(ft_s, align_default, yes, no, 0, no),
        r_string("ab")),
    pc("`.3` refuses an Int", vp(ft_canonical, align_default, no, no, 0,
        yes(3)), r_int(7i64)),
    pc("`.3` refuses a Float", vp(ft_canonical, align_default, no, no, 0,
        yes(3)), r_float(1.5)),
    pc("`.3` refuses a Bool", vp(ft_canonical, align_default, no, no, 0,
        yes(3)), r_bool(no)),
    pc("`.3d` refuses an Int", vp(ft_d, align_default, no, no, 0, yes(3)),
        r_int(7i64)),
    pc("`.3x` refuses an Int", vp(ft_x_lower, align_default, no, no, 0,
        yes(3)), r_int(7i64))
].

:- pred check_part_refusal(part_refusal_case::in, tally::in, tally::out,
                           io::di, io::uo) is det.

check_part_refusal(pc(Name, VP, R), !T, !IO) :-
    check(Name, ( if render_value(VP, R, _) then no else yes ), !T, !IO).

    % [LGRA.2.9.6.4]: every field in the value's own offset, floor before the
    % epoch, `%f` truncated, `%z` with seconds only when it has them.
    %
:- type time_case ---> tc(string, list(time_item), int64, int64, string).

:- func time_cases = list(time_case).

time_cases = [
    tc("the epoch, ISO-shaped", iso_items, 0i64, 0i64, "1970-01-01T00:00:00"),
    tc("one nanosecond before the epoch floors", iso_items, -1i64, 0i64,
        "1969-12-31T23:59:59"),
    tc("`%f` truncates the nanoseconds", [ti_field(tf_microsecond)],
        1234567890i64, 0i64, "234567"),
    tc("`%f` before the epoch", [ti_field(tf_microsecond)], -1i64, 0i64,
        "999999"),
    tc("fields in the value's own offset", [ti_field(tf_hour),
        ti_text(":"), ti_field(tf_minute)], 0i64, 19800000000000i64, "05:30"),
    tc("`%z` east", [ti_field(tf_utc_offset)], 0i64, 19800000000000i64,
        "+0530"),
    tc("`%z` west", [ti_field(tf_utc_offset)], 0i64, -3600000000000i64,
        "-0100"),
    tc("`%z` at UTC", [ti_field(tf_utc_offset)], 0i64, 0i64, "+0000"),
    tc("`%z` with seconds", [ti_field(tf_utc_offset)], 0i64, 3661000000000i64,
        "+010101"),
    tc("`%%` is a text item", [ti_text("%")], 0i64, 0i64, "%"),
    % `UtcNs + OffsetNs` near either end of int64 does not wrap. libds's
    % `test_interp_time` holds the same two values.
    tc("1677-09-21T03:00Z at -08:00 is the local 1677-09-20", iso_items,
        -9223362000000000000i64, -28800000000000i64, "1677-09-20T19:00:00"),
    tc("2262-04-11T20:00Z at +09:00 is the local 2262-04-12", iso_items,
        9223358400000000000i64, 32400000000000i64, "2262-04-12T05:00:00")
].

:- func iso_items = list(time_item).

iso_items = [ti_field(tf_year), ti_text("-"), ti_field(tf_month),
    ti_text("-"), ti_field(tf_day), ti_text("T"), ti_field(tf_hour),
    ti_text(":"), ti_field(tf_minute), ti_text(":"), ti_field(tf_second)].

:- pred check_time(time_case::in, tally::in, tally::out, io::di, io::uo)
    is det.

check_time(tc(Name, Items, UtcNs, OffsetNs, Want), !T, !IO) :-
    Got = render_time(Items, UtcNs, OffsetNs),
    check_quiet(Name, ( if Got = Want then yes else no ), Got, Want, !T, !IO).

    % Reports a failure with both strings.
    %
:- pred check_quiet(string::in, bool::in, string::in, string::in,
                    tally::in, tally::out, io::di, io::uo) is det.

check_quiet(Name, Ok, Got, Expected, !T, !IO) :-
    (
        Ok = yes,
        !.T = tally(P, F),
        !:T = tally(P + 1, F)
    ;
        Ok = no,
        !.T = tally(P, F),
        !:T = tally(P, F + 1),
        io.format("  FAIL  %s\n        got %s, want %s\n",
            [s(Name), s(Got), s(Expected)], !IO)
    ).

